function previewAtrasoMs() { return prevAtrasoMs; }

function recalcularAtrasoPreview() {
  let alvo = 0;
  const e = mirrorEstado;
  const telas = (e && e.ligado && Array.isArray(e.telas)) ? e.telas : [];
  if (telas.length && !telaoConectado()) {
    // TELAS DE COMANDO renderizam localmente com ~10 ms de latência: elas
    // NÃO entram na conta, e uma sala só com elas fica em atraso ZERO — o
    // motivo da fila da preview (v5.162) morreu junto com o pipeline de
    // pixels. Sem esta guarda, telas sem `vivo.vfim` cairiam no PADRÃO de
    // 1,2 s — a preview atrasando por um atraso que não existe.
    const dePixels = telas.filter((t) => t && !t.comando);
    const folgas = dePixels
      .map((t) => (t && t.vivo && typeof t.vivo.vfim === 'number') ? t.vivo.vfim : null)
      .filter((v) => v !== null && v > 0)
      .sort((a, b) => a - b);
    if (!dePixels.length) {
      alvo = 0;
    } else {
      alvo = folgas.length ? folgas[Math.floor(folgas.length / 2)] : PREV_ATRASO_PADRAO;
      alvo = Math.min(PREV_ATRASO_MAX, Math.max(PREV_ATRASO_MIN, alvo));
    }
  }
  // Ligar e desligar o atraso é sempre uma mudança de regime, por menor que
  // seja o número: é a diferença entre a preview espelhar a rede e espelhar o
  // telão. Dentro do mesmo regime, só um degrau de verdade conta.
  const mesmoRegime = (alvo === 0) === (prevAtrasoMs === 0);
  if (mesmoRegime && Math.abs(alvo - prevAtrasoMs) < PREV_ATRASO_PASSO) return;
  prevAtrasoMs = alvo;
  // Caindo a zero, o que estiver na fila vale AGORA: segurar a preview por um
  // atraso que não existe mais é o defeito ao contrário.
  if (!alvo) drenarPreview(true);
}

// ===== A REFERÊNCIA: quem é a PROJEÇÃO, e por que nunca é a preview =====
//
// A preview é uma ILUSTRAÇÃO, nunca a fonte de verdade: ela roda no WebView do
// Controle, o único que o Android estrangula quando o app sai da frente.
// Enquanto ela for a referência nada corrige isso — o erro está na régua.
//
// A projeção é uma destas três, NESTA ordem:
//   1. o TELÃO (`display-status`), quando há TV conectada;
//   2. a TELA ELEITA (`tela-status` → `espelho-status`), quando não há TV: as
//      telas da rede são o que a congregação vê, cada uma com um `<video>` de
//      verdade num navegador que o Android do celular não estrangula;
//   3. ninguém — sem TV e sem telas a projeção É a preview em tela cheia, que
//      exige o app na frente. Aí ela é a própria referência.
//
// `displayStatusAt`/`lastDisplayTime` guardam o último status de QUEM estiver
// valendo; `telaoStatusAt` é só do telão, porque a precedência dele precisa de
// relógio próprio (com os dois no ar, a tela da rede é ruído).
let displayStatusAt = 0;
let lastDisplayTime = 0;
let telaoStatusAt = 0;
let refFonte = '';            // 'telao' | 'espelho' | '' — só diagnóstico
const DISPLAY_TIMEOUT = 2500; // sem status da projeção por mais que isso → preview assume

// A TOLERÂNCIA DO RE-ALINHAMENTO, e ela era grande demais.
//
// 1,6 s foi escolhido quando o resync existia para não estalar o áudio da
// preview. Só que **a preview que se realinha não tem som**, e isso continua
// verdadeiro depois da v5.215: o realinhamento só roda com `displayActive()`,
// isto é, com uma projeção reportando status — e é exatamente essa a condição
// que cala este aparelho (ver `acertarSaidaDeAudio`). As duas são mutuamente
// exclusivas por construção; a única janela em que elas se tocam são os
// `DISPLAY_TIMEOUT` (2,5 s) seguintes à queda de uma tela, e ali um seek custa
// um quadro num som que acabou de nascer. Sem som, um seek é invisível: o que
// se paga é um quadro, e o que se ganha é a ilustração parar de mentir. Meio
// segundo é folga de sobra para o jitter do status (que chega a ~4 Hz) e
// apertado o bastante para um desvio de verdade nunca chegar a ser percebido.
const SYNC_DRIFT = 0.5;

// E AO VOLTAR DO SEGUNDO PLANO O ALINHAMENTO É EXATO, não tolerante.
//
// A tolerância existe para não corrigir ruído; ao retomar não há ruído a
// poupar, há um desvio conhecido e possivelmente enorme. `RESYNC_EXATO` é só a
// margem que evita um seek inútil quando por sorte já estava alinhado.
const RESYNC_EXATO = 0.15;
// Por quanto tempo depois de retomar o próximo status vale como reposicionamento
// forçado. Ele precisa sobreviver ao intervalo entre a retomada e o status
// seguinte — que, num telão parado, é o compasso do `display-status`.
const RESYNC_JANELA_MS = 4000;
let forcarResyncAte = 0;

/**
 * COM A PÁGINA ESCONDIDA NÃO SE TOCA NO TRANSPORTE DA PREVIEW.
 *
 * Esta guarda é a metade que faltava da v5.173. Ao passar a escutar o
 * `espelho-status`, o Controle ganhou uma referência de tempo justamente no
 * caso em que ele não tinha nenhuma (sem TV, app minimizado) — e junto ganhou
 * uma consequência que não estava prevista: `resyncPreviewToDisplay` passou a
 * chamar `preview.play()` a ~4 Hz numa página oculta.
 *
 * O Chromium PAUSA um `<video>` de página escondida. O `play()` sai, o
 * navegador pausa de volta, o status seguinte chega 250 ms depois e recomeça —
 * um laço de `play`/`PAUSA ESPONTÂNEA` que a própria linha do tempo do Registro
 * mostrou, par a par, com a marca `[oculto]`. O estrago não fica na preview: os
 * três WebViews dividem UM processo, e essa rotatividade de decodificador rouba
 * justamente o fio que alimenta o `AudioWorklet` do espelho. Do lado da tela da
 * rede isso aparece como `AUDIO_MUDO_MS` vencido — "o som parou de chegar" com
 * a imagem seguindo — que é a queixa que abriu esta rodada.
 *
 * Não há nada a preservar: um `play()` que o navegador desfaz no quadro
 * seguinte não é sincronização, é ruído. Escondida, a preview fica onde está; o
 * realinhamento EXATO da retomada (`forcarResyncAte` + `ressincronizarPreview`)
 * é o que a traz de volta ao lugar, e ele já existe desde a v5.173.
 */
function preverPodeMexer() {
  return typeof document === 'undefined' || document.visibilityState === 'visible';
}

function displayActive() {
  return (Date.now() - displayStatusAt) < DISPLAY_TIMEOUT;
}
/** Só o TELÃO de verdade — é ele que tira o espelho da jogada. */
function telaoAtivo() {
  return (Date.now() - telaoStatusAt) < DISPLAY_TIMEOUT;
}
// Posição "oficial" do item atual: a do Display enquanto ele for a fonte de
// verdade (ver acima), senão a da própria preview. Usado por ações
// disparadas fora do ciclo de tick normal (stepSlide, renderSlideNav) — sem
// isso, "estrofe anterior/próxima" calcularia a partir de um tempo local já
// desatualizado em relação ao que está de fato no telão.
function authoritativeTime() {
  if (currentItem && currentItem.kind !== 'youtube' && displayActive()) return lastDisplayTime;
  // E O ATRASO DA PREVIEW VOLTA AQUI. Com a preview deslocada no tempo (ver
  // `cmd`), `preview.getTime()` está exatamente `previewAtrasoMs` atrás da
  // projeção — porque o `load` dela aconteceu esse tanto depois. Quem pergunta
  // esta função quer a posição REAL: é ela que decide qual estrofe vem a
  // seguir, e usar o tempo deslocado faria "próxima estrofe", tocado logo
  // depois de a estrofe virar na tela, devolver a estrofe que já está no ar —
  // isto é, o botão pareceria não funcionar, que é o defeito que o atraso da
  // preview existe para curar.
  return (preview.getTime() || 0) + previewAtrasoMs() / 1000;
}

/**
 * O tempo que a PREVIEW deve estar mostrando — a projeção menos o atraso.
 *
 * É o par de [authoritativeTime], e a distinção entre os dois é o modelo
 * inteiro: um responde "o que está NO AR agora?" (decisões — qual estrofe vem a
 * seguir, o que a barra marca, o que a `MediaSession` publica) e o outro
 * responde "o que a ILUSTRAÇÃO deve estar desenhando?" (o `<video>` da preview,
 * a letra desenhada dentro dela).
 *
 * Sem os dois, o atraso deliberado da preview (ver `cmd`) vira defeito: quem
 * desenha a letra pelo tempo da projeção a troca `previewAtrasoMs` ANTES da
 * imagem correspondente, e quem re-alinha o `<video>` pelo tempo da projeção
 * DESFAZ o atraso a cada status — os dois em silêncio.
 */
function tempoDaPreview() {
  return Math.max(0, authoritativeTime() - previewAtrasoMs() / 1000);
}
// Re-alinha a preview à projeção real do Display (fonte de verdade): casa o
// play/pause e corrige o tempo da preview quando o drift passa de SYNC_DRIFT
// — sem isso, dois decodificadores de áudio independentes (Display e preview)
// divergem aos poucos e a letra sincronizada acaba trocando de slide em
// momentos diferentes nos dois lados. O que segura o seek indevido são as
// duas guardas do corpo: `preverPodeMexer()` (página oculta) e o próprio
// SYNC_DRIFT.
function resyncPreviewToDisplay(isPlaying, currentTime, tolerancia) {
  if (!preview.isTimed()) return;
  if (!preverPodeMexer()) return;   // ver `preverPodeMexer`
  const tol = typeof tolerancia === 'number' ? tolerancia : SYNC_DRIFT;
  try {
    if (typeof currentTime === 'number' && isFinite(currentTime)) {
      const alvo = alvoDaPreview(currentTime);
      const pt = preview.getTime() || 0;
      if (Math.abs(pt - alvo) > tol) preview.seek(alvo);
    }
    if (isPlaying && !preview.isPlaying()) preview.play();
    else if (!isPlaying && preview.isPlaying()) preview.pause();
  } catch (_) {}
}

/**
 * Onde a preview deveria estar, dado um instante da PROJEÇÃO.
 *
 * O atraso entra aqui com o sinal certo, e ele é a razão de esta linha existir:
 * mirar o instante da projeção faria cada `display-status` (a ~4 Hz) puxar a
 * preview para a frente, desfazendo o deslocamento que ela tem de propósito
 * para casar com as telas da rede (ver `cmd`). Com o telão conectado o atraso é
 * zero e isto é a identidade.
 */
function alvoDaPreview(tempoDaProjecao) {
  return Math.max(0, tempoDaProjecao - previewAtrasoMs() / 1000);
}

/**
 * Realinha a preview AGORA, pela última posição conhecida da projeção.
 *
 * Chamado ao retomar do segundo plano, antes de qualquer status novo chegar: se
 * a referência ainda estiver fresca, a correção acontece no ato; se não, o
 * `forcarResyncAte` faz o próximo status valer como reposicionamento forçado.
 * Sem os dois caminhos, a correção dependeria de o telão estar emitindo naquele
 * exato instante — e uma cena PARADA (imagem, versículo) não emite nada.
 */
function ressincronizarPreview() {
  if (!displayActive()) return;
  resyncPreviewToDisplay(playing, lastDisplayTime, RESYNC_EXATO);
}
// HÁ UMA TELA RECEBENDO A PROJEÇÃO?
//
// Não é a mesma pergunta de `displayActive()`, que mede se o telão MANDOU
// notícia há pouco (ele só emite `display-status` com mídia em cena): um telão
// conectado e mostrando o wallpaper não responde nada, e continua sendo um
// telão conectado. Aqui a pergunta é sobre a CONEXÃO — a `Presentation` no app,
// a janela do Display no navegador —, que é o que decide se ligar o som deste
// aparelho atrapalha alguém.
function telaoConectado() {
  if (!window.__NATIVE__) return !!(webDisplayWin && !webDisplayWin.closed);
  return !!telaoNoAr();
}

// A TELA EM QUE O TELÃO ESTÁ DE FATO NO AR — e ela NÃO é `lastDisplays[0]`.
//
// A lista responde pelo DisplayManager; a projeção é a `Presentation`, e as
// duas divergem exatamente quando mais custa. `show()` lança num dongle
// instável e o sistema derruba a janela sozinho numa oscilação de Miracast: a
// tela continua listada e não há telão nenhum. Enquanto esta função foi
// `lastDisplays.length > 0`, esse estado calava a preview (havia "para onde
// mandar o som") sem ninguém tocando do outro lado — SILÊNCIO NOS DOIS LADOS,
// sem erro em lugar nenhum. O `telao` do shell (59) é quem responde.
//
// Ela é a pergunta das TRÊS decisões que dependem de haver projeção: quem toca
// o som (`acertarSaidaDeAudio`), se o microfone é oferecido
// (`haOndeReproduzirMic`) e se o Modo Fácil destrava (`simpleDisplay`). O que
// segue lendo a lista CRUA é o que descreve a CONEXÃO — o rótulo da folha, o
// `applyPreviewAspect`, o Registro —, e é lá que a distância entre as duas vira
// frase.
function telaoNoAr() {
  for (const d of lastDisplays) if (d && d.telao) return d;
  return null;
}

// A TELA ESTÁ CONECTADA E O TELÃO NÃO SUBIU. É o estado que o shell retenta por
// ~15 s (a escada do `syncPresentation`) e o único em que o app tem uma TV na
// lista sem ter para onde projetar.
function telaoNoChao() {
  return window.__NATIVE__ && lastDisplays.length > 0 && !telaoNoAr();
}

// ===== A SAÍDA DE ÁUDIO: os displays, ou ESTE APARELHO =====
//
// Sem tela nenhuma conectada quem toca o som é a preview — ali a projeção É ela
// em tela cheia, e uma projeção muda não é projeção. Com QUALQUER tela
// conectada este aparelho está mudo, sempre.
//
// NÃO É UM MODO, É UMA CONSEQUÊNCIA: sem botão, sem preferência e sem nada a
// lembrar entre sessões — o estado é DERIVADO da conexão. Era esse desencontro
// que matava a "mesa de som" manual (o operador a esquecia ligada e o `<video>`
// deste WebView roubava o foco de áudio do Android do player do telão). A troca
// é automática nos dois sentidos, pelo reenvio de cena da reconexão.
//
// TELA é a pergunta larga do Modo Fácil (`simpleDisplay`): a TV **ou** uma tela
// da rede recebendo — cada uma toca o próprio arquivo, e contá-las é o que
// impede o celular de duplicar o áudio da sala.
//
// Só no modo avançado: no Modo Fácil sem tela a cortina cobre tudo, e som
// atrás de uma tela que diz "conecte uma tela" seria o único sinal de vida.
let somLocal = false;          // a preview está tocando o som DESTE aparelho?
let somLocalBloqueado = false; // o navegador recusou o som (ver `onBlocked`)

// HÁ ALGUMA TELA RECEBENDO — a TV ou uma tela da rede.
//
// `telaoConectado()` responde só pela TV, e é a pergunta certa para o atraso da
// preview e para o botão de espelhar. Para o SOM a pergunta é mais larga, e ela
// já tem uma resposta única no app: `simpleDisplay()`. O nome é do Modo Fácil
// porque foi lá que ela nasceu; delegar em vez de reescrever é o que impede as
// duas de divergirem no primeiro caso de borda.
function algumaTelaConectada() { return !!simpleDisplay(); }

/**
 * ===== "TOCAR NESTE CELULAR": A ESCOLHA DE NÃO CONECTAR NADA =====
 *
 * Sem tela, o Modo Fácil bloqueia. O argumento era bom — ali a projeção não
 * existe e a preview nem som tem —, mas ele supunha que quem abre aquele modo
 * sempre quer projetar. Ensaiar o louvor, conferir a letra ou ouvir o playback
 * antes do culto são usos legítimos, e para todos eles a resposta certa é o som
 * saindo daqui: exatamente o que o modo avançado já faz sozinho sem tela.
 *
 * ## CAMINHO SÓ DE IDA, e valendo só o USO ATUAL
 *
 * Não há botão de volta, e a escolha **não é guardada em lugar nenhum** — este
 * `let` é a memória inteira dela. O bloqueio se rearma sozinho por três
 * caminhos, e são eles que substituem o botão de desfazer:
 *
 * - **o app fecha** — nada foi gravado, então a abertura seguinte nasce
 *   bloqueada;
 * - **ida e volta pelo modo avançado** (`setAppMode`, que a zera em toda troca);
 * - **uma tela entra** (`renderSimpleGate`) — aí há para onde mandar o som, e é
 *   para lá que ele vai.
 *
 * A versão anterior (v1.0.5) persistia a escolha e oferecia "Voltar a exigir uma
 * tela". Persistir era o defeito que o botão vinha remendar: guardada, a decisão
 * de um ensaio de quarta-feira chegava ao culto de sábado, e alguém tinha de
 * lembrar de desfazê-la. Sem gravar, não há o que desfazer.
 */
let tocarNoCelular = false;
function setTocarNoCelular(on) {
  const alvo = !!on;
  if (alvo === tocarNoCelular) return;
  tocarNoCelular = alvo;
  renderSimpleGate();
  acertarSaidaDeAudio();
  renderCast();
  diagC(tocarNoCelular ? 'modo fácil: tocando neste celular' : 'modo fácil: exigindo uma tela');
}

function somLocalDeveEstar() {
  if (somLocalBloqueado) return false;
  // O MODO FÁCIL entra por ESCOLHA, o avançado por DERIVAÇÃO — e os dois pela
  // mesma porta, porque a pergunta de baixo é uma só: há para onde mandar o som?
  return !algumaTelaConectada() && (appMode === 'full' || tocarNoCelular);
}

// O ÚNICO ponto que mexe no mudo da preview. Chamado de onde o estado muda —
// telas (`renderDisplayStatus`), transmissão (`lerEspelho`), modo do app
// (`setAppMode`) e a janela do Display no navegador (`openWebDisplay`).
function acertarSaidaDeAudio() {
  const alvo = somLocalDeveEstar();
  // A PROTEÇÃO É REAVALIADA SEMPRE, mesmo quando o mudo não muda: ela depende
  // também da CENA, e a cena muda sem passar por aqui.
  acertarProjecaoLocal();
  if (alvo === somLocal) return;
  somLocal = alvo;
  // A rampa curta mora no `stage` (ver `setForceMuted`): sem ela a troca seria
  // um corte no talo, e um corte estala na caixa de som.
  preview.setForceMuted(!somLocal);
  diagC(somLocal ? 'som: neste aparelho' : 'som: nos displays');
}

// ===== A PREVIEW QUE É A PROJEÇÃO NÃO PODE SER SUSPENSA (v1.3.12) =====
//
// Sem tela conectada quem projeta é o `<video>` da preview, no WebView do
// CONTROLE — e o Chromium pausa o `<video>` de uma página oculta. Com o app
// minimizado, o louvor calava. Relato do operador: *"mídias baixadas sendo
// executadas estão sendo pausadas quando minimizo o aplicativo… ocorre quando
// não há telas conectadas, no caso no modo onde o áudio deve sair no próprio
// smartphone"*.
//
// A pergunta é de DUAS metades, e nenhuma delas sozinha basta:
//  - **não há tela** (`somLocalDeveEstar`, o MESMO veredito que decide de onde
//    sai o som — duas contas para a mesma pergunta divergiriam no primeiro
//    ajuste); e
//  - **há cena no ar** (`cenaNoAr`). Sem esta metade a proteção ficaria ligada
//    o tempo todo num aparelho sem TV, e o que ela custa é um renderer que
//    nunca desacelera em segundo plano — trocar um defeito por um consumo.
//
// COM tela conectada isto fica DESLIGADO de propósito: ali o Controle é a mesa
// de comando, o som está lá fora, e ser estrangulado em segundo plano é o
// comportamento certo (é o que o `snoopDisplayStatus` da ponte existe para
// contornar).
let projecaoLocalAtual = null;   // null = ainda não dito ao shell
function acertarProjecaoLocal() {
  if (!window.__NATIVE__) return;
  const alvo = somLocalDeveEstar() && cenaNoAr();
  if (alvo === projecaoLocalAtual) return;
  projecaoLocalAtual = alvo;
  AVNative.projecaoLocal(alvo);
  diagC(alvo ? 'projeção: nesta preview' : 'projeção: fora deste WebView');
}

// Fundo da letra sincronizada (Hinário 2022): 'image' (PADRÃO) usa as imagens
// dos slides atrás do texto; 'black' as ignora e mantém o fundo preto.
// Persistido em state.lyricsBg, aplicado ao vivo (igual fade/fit) via comando —
// tanto no Display quanto na própria preview, que segue o mesmo conceito
// universal de espelhar o telão.
//
// Mora no popup de EXIBIÇÃO (segmento "Imagens dos slides"), junto do
// preenchimento e do wallpaper: é uma preferência de como o telão se parece,
// escolhida uma vez, não um controle que se opera durante o culto. O botão que
// tinha no mixer virou a leitura da letra completa (ver openLyricsPopup).
//
// AS IMAGENS SÃO O PADRÃO, e daí a leitura do banco perguntar `=== 'black'` em
// vez de `=== 'image'`: valor AUSENTE é quem nunca escolheu, e tem de cair no
// padrão — quem escolheu "Remover" gravou 'black' e continua nele. Elas já vêm
// baixadas com a música (`resolveImage` não consulta preferência nenhuma), então
// o padrão anterior escondia material que o aparelho já tinha, e escondia
// CALADO: nada erra, o hino sai em texto sobre preto, e quem acabou de instalar
// não tem como saber que a opção existe.
let lyricsBg = 'image';
async function setLyricsBg(mode) {
  mode = mode === 'image' ? 'image' : 'black';
  if (lyricsBg === mode) return;
  lyricsBg = mode;
  // PINTAR ANTES DE GRAVAR, como o `applyFit` e o `applyRotate` já faziam
  // (v1.4.40). Depois do `await` o tile só respondia ao toque quando a
  // transação do IndexedDB voltasse — no aparelho isso é o botão parecendo não
  // ter recebido o dedo, e no oráculo era uma leitura que media o banco em vez
  // da tela. O valor já está em `lyricsBg`; a gravação é o que ele significa
  // na abertura seguinte, não o que a tela mostra agora.
  renderLyricsBgTile();
  await AVDB.setState('lyricsBg', lyricsBg);
  cmd({ type: 'lyricsbg', mode: lyricsBg });
}
// ESTE LIGA E DESLIGA, e a v1.4.40 INVERTEU o aceso dele: as imagens MOSTRADAS
// são a função ligada, e antes o aceso marcava "Remover" (o que não é o padrão).
// Com a inversão o desenho e a luz passam a concordar — imagem inteira e aceso,
// imagem riscada e apagado —, em vez de dizerem coisas opostas no mesmo botão.
function renderLyricsBgTile() {
  const mostra = lyricsBg === 'image';
  pintarTile(lyricsBgTileEl, lyricsBg, mostra ? 'Mostrar' : 'Remover', mostra, !mostra);
}

// Envia o comando ao display E aplica na preview. YouTube usa o player pequeno
// (acima); mídia comum continua no stage.js. O mudo da preview NÃO se decide
// aqui (ver `acertarSaidaDeAudio`).
//
// A PREVIEW ATRASA JUNTO COM AS TELAS DA REDE, e o ponto de corte é aqui. Sem
// telão elas SÃO o que a congregação vê, e chegam ~1 s depois do comando; a
// preview muda no ato. O operador lê essa distância como "o botão não
// funcionou" e toca de novo.
//
// Atrasa-se A CÓPIA, nunca o original: `AVDB.sendCommand` sai na hora e a
// metade da preview entra numa fila que escoa `previewAtrasoMs` depois — ela
// vira um espelho FIEL e deslocado, com letra, fades e cortina deslizando
// junto. Deslocar o `currentTime` em vez disso teria de ser desfeito em cada
// consumidor (barra, navegação de estrofe, `MediaSession`), cada um uma chance
// de errar o sinal.
//
// FILA, e não um `setTimeout` por comando: o atraso muda de valor conforme as
// telas entram e saem, e dois `setTimeout` com atrasos diferentes podem
// INVERTER a ordem — um `play` chegando antes do `load` a que ele pertence.
const filaPreview = [];
let filaPreviewTimer = null;

function drenarPreview(tudo) {
  const agora = Date.now();
  while (filaPreview.length && (tudo || filaPreview[0].em <= agora)) {
    const passo = filaPreview.shift();
    aplicarNaPreview(passo.obj, passo.item);
  }
  clearTimeout(filaPreviewTimer);
  filaPreviewTimer = null;
  if (filaPreview.length) {
    filaPreviewTimer = setTimeout(() => drenarPreview(false),
      Math.max(15, filaPreview[0].em - Date.now()));
  }
}

// A FILA NUNCA PODE VIRAR UM BURACO NEGRO. O telão recebe pelo `sendCommand`
// acima, aconteça o que acontecer; a preview é a cópia — e uma cópia que
// congelasse deixaria o operador voando cego, com a projeção funcionando. Se a
// fila passar deste tamanho (a aba estrangulada em segundo plano é o caso real:
// os timers atrasam e os comandos empilham), ela escoa inteira na hora. Perder
// o deslocamento é um arranhão; perder a preview, não.
const FILA_PREVIEW_MAX = 24;

function cmd(obj) {
  AVDB.sendCommand(obj);
  // COM A PÁGINA ESCONDIDA A ILUSTRAÇÃO NÃO TEM PLATEIA — e atrasá-la ali é o
  // pior dos dois mundos. O atraso existe para o operador não ver a preview
  // responder antes das telas da rede; com o app fora da frente ninguém está
  // comparando nada, e os `setTimeout` que fariam a fila escoar são justamente
  // os que o Android estrangula. O resultado era a preview voltando do segundo
  // plano com uma cena velha na mão, esperando um relógio que não corria.
  //
  // Escondida, a preview aplica na hora: é a posição mais próxima da verdade
  // que ela pode ocupar, e é dela que o realinhamento da retomada parte.
  const atraso = document.visibilityState === 'visible' ? previewAtrasoMs() : 0;
  if (atraso <= 0) { drenarPreview(true); aplicarNaPreview(obj, currentItem); return; }
  // O ITEM VIAJA COM O COMANDO (v5.180). `aplicarNaPreview` lia `currentItem`
  // no instante do DRENO, e o dreno acontece até 2,5 s depois: dois toques
  // dentro da janela do atraso (trocar de música, ou errar a linha e corrigir)
  // faziam o `load` de A ser aplicado com o item B na mão — a preview montava a
  // mídia certa pelo `mediaId` e decidia LETRA, YouTube e "mantém o texto?" pelo
  // item errado. O comando é do passado por construção; o estado que ele carrega
  // tem de ser o daquele passado também.
  filaPreview.push({ obj: obj, item: currentItem, em: Date.now() + atraso });
  if (filaPreview.length > FILA_PREVIEW_MAX) { drenarPreview(true); return; }
  if (!filaPreviewTimer) drenarPreview(false);
}

// `item` é o `currentItem` DE QUANDO O COMANDO SAIU, não o de agora — ver a
// fila em `cmd`. Só ele: `pvTextActive` é estado da PRÓPRIA preview e já vive na
// linha do tempo atrasada dela, então lê-se no dreno mesmo.
function aplicarNaPreview(obj, item) {
  // O tempo volta a correr: destrava a letra congelada pelo fim natural.
  if (obj.type === 'load' || obj.type === 'play' || obj.type === 'seek') pvLyricsEnded = false;
  // MÍDIA NOVA, TENTATIVA NOVA de som local: a recusa de autoplay de um
  // navegador vale para o `play()` que a levou, não para a sessão inteira — e
  // quem carregou esta veio de um toque, que é a ativação que faltava. No app
  // isto nunca chega a valer (não há política de gesto ali). Ver `onBlocked`.
  if (obj.type === 'load' && somLocalBloqueado) {
    somLocalBloqueado = false;
    acertarSaidaDeAudio();
  }
  // Texto manual (Bíblia/Mensagem): overlay independente — espelha na preview.
  if (obj.type === 'text') { showPvText(obj); return; }
  if (obj.type === 'text-hide') { hidePvText(); return; }
  if (obj.type === 'load') {
    // O nome que o cartão de espera vai escrever, gravado ANTES do `handle`:
    // é dentro dele que o palco pode anunciar a espera, e o `onEspera` não
    // recebe o item.
    pvEsperaNome = (item && item.name) || '';
    // Esconde a letra incondicionalmente (como o Display). O texto manual é um
    // overlay independente: só some ao carregar VISUAL; ÁUDIO toca por baixo e
    // mantém o texto (independência áudio × texto).
    hidePvLyrics(true);
    const keepText = pvTextActive && item && item.kind === 'audio';
    if (!keepText) hidePvText(false); // o load abaixo já monta a cena nova
    // preview.handle() sempre roda primeiro: mantém preview.getCurrent()/
    // fallback de thumbnail em dia (stage.js já sabe lidar com kind=youtube,
    // só não toca o vídeo) — mesmo quando o player real assume por cima.
    aoCarregarPv(preview.handle(obj));
    // Só mostra a letra do áudio se NÃO houver texto manual em cena (precedência).
    if (!keepText && item && item.kind === 'audio' && Array.isArray(item.lyrics) && item.lyrics.length) showPvLyrics(item);
    return;
  }
  if (obj.type === 'clear') {
    hidePvLyrics(true);
    hidePvText(false); // a cena inteira está sendo encerrada; nada a restaurar
    aoSairDeCenaPv(preview.handle(obj));
    return;
  }
  // PARAR SÓ A MÍDIA: a ilustração segue o telão camada por camada (v5.178). O
  // `hidePvText` NÃO é chamado — é justamente o texto que continua no ar —, e a
  // escolha entre as duas saídas do stage repete a do Display, lida aqui pelo
  // `pvTextActive`, que é o espelho local do `textActive` de lá.
  if (obj.type === 'media-clear') {
    hidePvLyrics(true);
    aoSairDeCenaPv(preview.handle({ type: pvTextActive ? 'clear-media' : 'clear' }));
    return;
  }
  if (obj.type === 'lyricsbg') {
    // Não é um comando do stage.js (letra é camada paralela) — aplica direto
    // na preview, se ela estiver mostrando letra sincronizada agora.
    applyPvLyricsBg();
    return;
  }
  if (obj.type === 'view' || obj.type === 'fit') {
    preview.handle(obj); // cortina/config compartilhada — sempre, independe do youtube
    return;
  }
  preview.handle(obj);
}

function previewTick() {
  // Texto manual em cena sem áudio de fundo: nada de mídia/tempo a sincronizar.
  // (Com áudio de fundo, o texto é overlay e a preview segue o áudio normalmente.)
  // O conjunto é o MESMO de `clearManualText` — as SEIS sessões, incluindo
  // cronômetro, sorteio e a imagem sobre o áudio; listar só três deixava o tick rodando sobre uma
  // preview sem mídia durante uma contagem regressiva.
  if (cenaDeRoteiroNoAr() && !preview.getCurrent()) return;
  // Itens YouTube tocam só no Display (player real): a UI de transporte é
  // dirigida pelo display-status remoto, não pela preview local.
  if (currentItem && currentItem.kind === 'youtube') return;
  // Display presente é a fonte de verdade (ver displayActive()) — a preview
  // só dirige a UI/letra na ausência dele; enquanto ele estiver ativo, quem
  // atualiza tudo isso é o handler de 'display-status' (AVDB.onCommand).
  if (displayActive()) return;
  // MÍDIA FORA DE CENA NÃO PINTA TRANSPORTE (v5.179) — a outra metade da guarda
  // do handler de `display-status`, e ela precisa estar nos DOIS lugares porque
  // são duas fontes independentes: sem telão nem espelho, quem alimenta a barra
  // é este tick. `preview.getCurrent()` continua devolvendo o registro durante
  // todo o esmaecimento do `clearFaded` (é o mesmo fato que o comentário de
  // `midiaNoAr` descreve para o ▶), então o Parar zerava a barra e o tick
  // seguinte a repunha no ponto antigo, com o ícone de pausa de volta.
  if (!midiaNoAr) return;
  setPlaying(preview.isPlaying());
  const dur = preview.getDuration();
  durTimeEl.textContent = fmtTime(dur);
  seekEl.disabled = !preview.isTimed();
  // A BARRA MOSTRA A PROJEÇÃO, a letra da preview mostra a PREVIEW. Com a
  // preview deslocada (ver `cmd`), os dois números diferem pelo atraso: a barra
  // existe para ser ARRASTADA, e um seek precisa ser absoluto e verdadeiro; a
  // letra é desenhada dentro da preview e tem de casar com a imagem que está
  // ali. Um deslocamento contínuo na barra é invisível; uma estrofe fora de
  // hora, não.
  const real = authoritativeTime();
  if (!seeking) {
    seekEl.max = isFinite(dur) && dur > 0 ? dur : 0;
    seekEl.value = real;
    curTimeEl.textContent = fmtTime(real);
  }
  updatePvLyricSlide(preview.getTime() || 0);
  renderSlideNav();
}

// ===== Fades de camada paralela da preview (letra, texto) =====
// A preview mostra exatamente o que vai ao telão, transições incluídas — por
// isso são LITERALMENTE as mesmas funções do Display, vindas de stage.js. Não
// há calibração própria aqui (o que difere entre preview e telão é só o CSS,
// em cq* relativos a cada container).
const PV_LAYER_FADE_MS = createStage.LAYER_FADE_MS;
const findSlideIndex = createStage.findSlideIndex;
const pvFadeIn = createStage.fadeContentIn;
const pvLayerIn = createStage.fadeLayerIn;
const pvLayerOut = createStage.fadeLayerOut;
const chronoReading = createStage.chronoReading;
const CHRONO_TICK_MS = createStage.CHRONO_TICK_MS;
const drawReading = createStage.drawReading;
const DRAW_FRAME_MS = createStage.DRAW_FRAME_MS;

// ===== Letra sincronizada na preview — mesma visualização do Display =====
// A preview já espelha o Display para imagem e vídeo (stage.js) — letra
// sincronizada segue o mesmo princípio universal do sistema: o operador vê no
// celular exatamente o que está sendo exibido no telão.
let pvLyrics = null;
let pvLyricsMeta = null; // { hymnName, hymnTrack, hymnAlbum } do item atual, pro slide de capa
let pvLyricSlideIdx = -1;
let pvLyricLoadSeq = 0;
let pvLyricImgKey = null;
let pvLyricTeardownTimer = null;  // ver showPvLyrics: a letra que volta cancela o teardown
let pvLyricImgUrl = null;
// Fim natural da faixa (local ou reportado pelo Display): trava a troca de
// slide até o próximo load/play/seek. Sem isso, o `currentTime = 0` que o fim
// natural produz (preparando o replay) faz o slide de CAPA reaparecer por um
// instante antes de o wallpaper cobrir — o "piscar da thumbnail" no fim da música.
let pvLyricsEnded = false;

// `fade` = a letra está saindo de cena para o operador ver (fim da música,
// texto manual assumindo). Espelha hideLyrics() do Display, inclusive o
// adiamento do teardown da imagem de fundo (ela é FILHA da camada: desmontá-la
// de imediato faria o fundo sumir por trás de um texto ainda esmaecendo).
function hidePvLyrics(fade) {
  pvLyrics = null;
  pvLyricsMeta = null;
  pvLyricSlideIdx = -1;
  ++pvLyricLoadSeq; // descarta uma imagem ainda resolvendo (não deve reaparecer)
  const seq = pvLyricLoadSeq;
  const teardown = () => {
    if (seq !== pvLyricLoadSeq) return; // a letra voltou nesse meio tempo
    if (pvLyricImgUrl) { URL.revokeObjectURL(pvLyricImgUrl); pvLyricImgUrl = null; }
    pvLyricImgKey = null;
    pvLyricsImgEl.hidden = true;
    pvLyricsImgEl.removeAttribute('src');
  };
  clearTimeout(pvLyricTeardownTimer);
  if (fade && !pvLyricsEl.hidden && pvLyricsEl.animate && fadeCfg.out) {
    pvLayerOut(pvLyricsEl);
    pvLyricTeardownTimer = setTimeout(teardown, PV_LAYER_FADE_MS);
  } else {
    pvLyricsEl.hidden = true;
    teardown();
  }
}

function showPvLyrics(rec) {
  // A letra VOLTOU antes do teardown agendado por hidePvLyrics: cancela-o de
  // forma explícita. A guarda de sequência sozinha NÃO basta — se a estrofe que
  // volta usa a MESMA imagem (`key === pvLyricImgKey`), applyPvLyricsImage
  // devolve cedo e não incrementa `pvLyricLoadSeq`: o teardown dispara com o seq
  // ainda válido, revoga a object URL EM USO e apaga o fundo da letra que
  // acabara de reaparecer — e como ele zera a chave, a estrofe seguinte
  // reaparece e a de depois some de novo. É o caso NORMAL de trocar de música:
  // o fallback "grudento" do sync faz estrofes seguidas (e hinos vizinhos)
  // compartilharem o mesmo `imageOpfsPath`.
  //
  // O telão tem esta guarda desde que o defeito foi visto lá; a preview ficou
  // sem ela, e sem TV a preview É a projeção.
  clearTimeout(pvLyricTeardownTimer);
  pvLyrics = rec.lyrics;
  pvLyricsMeta = { hymnName: rec.hymnName, hymnTrack: rec.hymnTrack, hymnAlbum: rec.hymnAlbum };
  pvLyricSlideIdx = -1;
  pvLayerIn(pvLyricsEl);
  applyPvLyricsBgClass();
  renderPvLyricSlide(0);
}

// ===== A PREVIEW NÃO CORTA A LETRA (v1.1.8) =====
// O espelho de `ajustarLetra()` do `display.js`, e ele existe pela razão de
// sempre: a preview mostra o que o telão vai mostrar, e uma que corta o que o
// telão não corta MENTE ao operador — ele confere ali antes de projetar.
//
// As DUAS metades são separadas (documentos diferentes, folhas diferentes, uma
// delas com tema), e a regra é a mesma: escala do CONJUNTO por busca binária,
// piso, e `ResizeObserver` para a caixa que muda de tamanho sem o slide mudar
// (a preview entra e sai de tela cheia, e ali ela muda de proporção inteira).
const PV_ESCALA_MAX = 1;
const PV_ESCALA_MIN = 0.34;
function pvCabeNaCaixa() {
  const cs = getComputedStyle(pvLyricsBoxEl);
  const util = pvLyricsBoxEl.clientHeight
    - (parseFloat(cs.paddingTop) || 0) - (parseFloat(cs.paddingBottom) || 0);
  if (util <= 0) return true;
  const gap = parseFloat(cs.rowGap) || 0;
  const pecas = [...pvLyricsBoxEl.children].filter((el) => !el.hidden);
  const alto = pecas.reduce((soma, el) => soma + el.getBoundingClientRect().height, 0)
    + gap * Math.max(0, pecas.length - 1);
  return alto <= util + 0.5;
}
function pvAjustarLetra() {
  if (!pvLyricsBoxEl) return;
  const escrever = (v) => pvLyricsBoxEl.style.setProperty('--lyrics-escala', String(v));
  escrever(PV_ESCALA_MAX);
  if (pvCabeNaCaixa()) return;
  let cabe = PV_ESCALA_MIN;
  let naoCabe = PV_ESCALA_MAX;
  for (let i = 0; i < 7; i++) {
    const meio = (cabe + naoCabe) / 2;
    escrever(meio);
    if (pvCabeNaCaixa()) cabe = meio; else naoCabe = meio;
  }
  escrever(cabe);
}
if (window.ResizeObserver && pvLyricsBoxEl) {
  new ResizeObserver(() => pvAjustarLetra()).observe(pvLyricsBoxEl);
}


// A moldura (borda + fundo semitransparente) só faz sentido cobrindo uma
// imagem de fundo de verdade — mesmo motivo do Display (ver
// applyLyricsBgClass em display.js). `.imgbg` liga a moldura só quando
// lyricsBg==='image' (ver .pv-lyrics-box/.pv-lyrics-content.imgbg em
// controle.css).
function applyPvLyricsBgClass() {
  pvLyricsContentEl.classList.toggle('imgbg', lyricsBg === 'image');
}

function renderPvLyricSlide(idx) {
  if (idx === pvLyricSlideIdx) return;
  const slide = pvLyrics[idx];
  // O índice só é REGISTRADO depois de validado (a mesma ordem do telão):
  // gravá-lo antes fazia um índice inexistente ficar marcado como "já
  // renderizado", e se o mesmo índice voltasse a ser pedido a guarda de cima
  // devolvia cedo — o slide certo nunca era pintado.
  if (!slide) return;
  pvLyricSlideIdx = idx;

  pvLyricsContentEl.classList.toggle('cover', !!slide.cover);
  if (slide.cover) {
    // Espelha o cartão de capa do telão peça a peça (ver `renderLyricSlide` em
    // display.js, que é onde o desenho está explicado). A preview existe para
    // mostrar o que a congregação vê — uma capa diferente aqui seria uma
    // ilustração errada, e é justamente na capa que o operador confere se
    // pegou o hino certo.
    const meta = pvLyricsMeta || {};
    pvLyricsNumEl.textContent = meta.hymnTrack ? String(meta.hymnTrack) : '';
    pvLyricsNumEl.hidden = !pvLyricsNumEl.textContent;
    pvLyricsLineEl.textContent = meta.hymnName || '';
    pvLyricsAuxEl.textContent = meta.hymnAlbum || '';
    pvLyricsAuxEl.hidden = !pvLyricsAuxEl.textContent;
  } else {
    pvLyricsNumEl.hidden = true;
    pvLyricsLineEl.textContent = slide.text || '';
    pvLyricsAuxEl.textContent = slide.auxText || '';
    pvLyricsAuxEl.hidden = !slide.auxText;
  }
  // Trecho sem letra (solo, introdução, instrumental): a moldura esmaece e
  // some, deixando só a imagem de fundo — mesmo comportamento do telão.
  pvLyricsContentEl.classList.toggle('nolyric',
    !pvLyricsLineEl.textContent.trim() && pvLyricsAuxEl.hidden && pvLyricsNumEl.hidden);
  // ANTES do fade, como no telão: a escala é medida com o texto novo no lugar.
  pvAjustarLetra();
  pvFadeIn(pvLyricsLineEl);
  if (!pvLyricsNumEl.hidden) pvFadeIn(pvLyricsNumEl);
  if (!pvLyricsAuxEl.hidden) pvFadeIn(pvLyricsAuxEl);

  applyPvLyricsImage(slide);
}

// Resolve (ou limpa) a imagem de fundo do slide atual, respeitando o modo
// preto/imagens (`lyricsBg`, ver setLyricsBg) — só troca de fato se a chave
// efetiva mudou (linhas seguidas costumam compartilhar a mesma imagem), com
// guarda de sequência pra descartar resoluções obsoletas.
function applyPvLyricsImage(slide) {
  if (!slide) return;
  const key = (lyricsBg === 'image' && slide.imageOpfsPath) ? slide.imageOpfsPath : null;
  if (key === pvLyricImgKey) return;
  const seq = ++pvLyricLoadSeq;
  if (!key) {
    pvLyricImgKey = null;
    // Oculta a <img> (não só limpa o src) — mesmo motivo do Display: sem
    // isso, alguns navegadores mostram o ícone/borda padrão de "imagem
    // quebrada" mesmo sem `src`, aparecendo como uma linha branca de
    // margem sobre o preto de .pv-lyrics-bg. Sai esmaecendo, e `src`/object
    // URL só caem DEPOIS do fade (limpá-las agora exporia justamente esse
    // ícone durante toda a transição).
    const url = pvLyricImgUrl;
    pvLyricImgUrl = null;
    pvLayerOut(pvLyricsImgEl);
    setTimeout(() => {
      // A revogação vem ANTES da guarda, e de propósito: `pvLyricImgUrl` já foi
      // zerada acima, então esta URL não é mais de ninguém — nenhum outro
      // caminho vai revogá-la. Atrás da guarda, uma imagem nova entrando em
      // menos de PV_LAYER_FADE_MS retinha o blob da foto até o WebView do
      // Controle morrer, uma vez a cada ocorrência, o culto inteiro.
      if (url) URL.revokeObjectURL(url);
      if (seq !== pvLyricLoadSeq) return; // outra imagem já assumiu: o src é DELA
      pvLyricsImgEl.removeAttribute('src');
    }, PV_LAYER_FADE_MS);
    return;
  }
  AVDB.opfsGetFile(key).then((file) => {
    if (seq !== pvLyricLoadSeq) return;
    const url = URL.createObjectURL(file);
    const prevUrl = pvLyricImgUrl;
    pvLyricImgUrl = url;
    pvLyricImgKey = key;
    pvLyricsImgEl.src = url;
    // Cada imagem de estrofe entra com fade — igual ao telão.
    pvLayerIn(pvLyricsImgEl);
    if (prevUrl) URL.revokeObjectURL(prevUrl);
  }).catch(() => {});
}

function updatePvLyricSlide(t) {
  if (!pvLyrics || pvLyricsEnded) return;
  // Replay depois do fim: a letra foi esmaecida junto com a música, mas os
  // slides continuam carregados — o tempo voltar a correr a traz de volta.
  if (pvLyricsEl.hidden) pvLayerIn(pvLyricsEl);
  renderPvLyricSlide(findSlideIndex(pvLyrics, t));
}

// Reaplica o fundo (preto/imagens) no slide atual sem precisar de uma troca
// de estrofe — chamado quando o operador alterna o botão de fundo da letra.
function applyPvLyricsBg() {
  if (!pvLyrics || pvLyricSlideIdx < 0) return;
  applyPvLyricsBgClass();
  applyPvLyricsImage(pvLyrics[pvLyricSlideIdx]);
}

// ===== Camada de TEXTO manual na preview (Bíblia/Mensagem) — espelha o Display =====
// Overlay independente do áudio: um som pode seguir tocando por baixo (preview
// muda), como no Display. `mode`: 'verse' (sublinha = referência) | 'message'.
let pvTextActive = false;

// UM `load` EM VOO ADIA A RESTAURAÇÃO — a metade PREVIEW da regra que o
// `display.js` aplica ao telão (`aoCarregar`/`aoSairDeCena`), e ler cada lado
// isolado aprova os dois: é a armadilha que o `fundo-da-letra.test.mjs` já
// pagou. `preview.handle({type:'load'})` só troca o `current` depois do fade de
// saída (os ~600 ms de FADE.time, em TODA troca de cena) e do `getMedia`: dentro
// dessa janela `preview.getCurrent()` ainda é a mídia ANTERIOR, e um `text-hide`
// que chegue aí remonta a letra do hino VELHO sobre a música nova. E PARA
// SEMPRE: quem montaria a letra da nova é o ramo `showPvLyrics(item)` do `load`,
// que já passou, e nada reavalia depois — as estrofes erradas passam a rolar
// pelo relógio da música certa. Sem TV a preview em tela cheia É a projeção.
//
// CONTADOR e não booleano (dois loads sobrepostos), com o decremento no `then`:
// um load descartado pelo `loadSeq` do stage resolve do mesmo jeito.
let pvCarregando = 0;
let pvRestaurarAoAssentar = false;

function aoCarregarPv(p) {
  pvCarregando++;
  Promise.resolve(p).catch(() => {}).then(() => {
    if (--pvCarregando) return;
    if (!pvRestaurarAoAssentar) return;
    pvRestaurarAoAssentar = false;
    // O cartão pode ter VOLTADO durante o load: aí quem manda é ele.
    if (!pvTextActive) restorePvSceneAfterText();
  });
}

// A CENA SAINDO CANCELA a restauração adiada — sem isto o adiamento INTRODUZ
// uma regressão. `clearFaded` faz `++loadSeq` e o load em voo resolve na hora,
// mas o `current` só vira null depois do fade: o callback acima dispararia com
// o registro ANTIGO na mão e remontaria a letra sobre uma preview já esvaziada
// (invisível — a cortina cobre —, mas o estado fica). Conferir
// `preview.getCurrent()` lá NÃO serviria, pelo mesmo motivo.
//
// A promise passa INTACTA: o wrap existe pela forma — é por esta função que
// toda saída de cena da preview passa, então um caminho novo nasce coberto.
function aoSairDeCenaPv(p) {
  pvRestaurarAoAssentar = false;
  return p;
}

// `restore` = a cena anterior deve voltar (ver hideText no display.js: mesma
// regra dos dois lados — 'text-hide' restaura; load visual/stop/clear não,
// porque algo novo já vai assumir a cena).
function hidePvText(restore = true) {
  if (!pvTextActive && pvTextEl.hidden) return;
  pvTextActive = false;
  soltarPvTextImg();
  pvTextEl.classList.remove('mode-img');
  stopPvLiveTimer();   // espelha hideText no Display
  // Sai esmaecendo — e o texto NÃO é limpo aqui: apagá-lo agora deixaria o
  // cartão vazio visível durante todo o fade. O próximo showPvText sobrescreve.
  pvLayerOut(pvTextEl);
  if (restore) restorePvSceneAfterText();
}

// Espelha restoreSceneAfterText() do Display: só a letra sincronizada precisa
// ser remontada (vídeo/imagem/YouTube nunca pararam e reaparecem sozinhos), e
// no slide correspondente ao instante atual — por authoritativeTime(), que é
// a posição do Display quando ele é a fonte de verdade.
function restorePvSceneAfterText() {
  if (pvCarregando) { pvRestaurarAoAssentar = true; return; } // ver `aoCarregarPv`
  const cur = preview.getCurrent();
  // NADA de fato em cena — nenhuma mídia carregada, ou a que havia já terminou
  // (só na playlist, ou tocada antes). O ponto de repouso é o WALLPAPER, não o
  // preto: showPvText abriu a cortina para o cartão aparecer, e sem isto ela
  // ficava aberta sobre o vazio quando o texto saía. Note que a fonte aqui é o
  // STAGE (`preview.getCurrent()`), não `currentItem`: este último é o item
  // SELECIONADO, que continua apontando para uma música só da playlist ou já
  // terminada — era justamente ele que fazia a preview achar que havia algo em
  // cena quando não havia.
  if (!cur || preview.hasEnded()) { preview.coverIn(false); return; }
  if (cur.kind !== 'audio' || !Array.isArray(cur.lyrics) || !cur.lyrics.length) return;
  showPvLyrics(cur);
  // O tempo da ILUSTRAÇÃO, não o da projeção — ver `tempoDaPreview`.
  updatePvLyricSlide(tempoDaPreview());
}

// Texto VIVO na preview (cronômetro e sorteio): mesmo desenho do Display (ver
// showText lá) — o valor é derivado localmente do descritor, não recebido
// pronto. Os dois laços são independentes de propósito: cada um lê o MESMO
// `startAt`/`rollUntil` do MESMO relógio do aparelho, e o ruído do sorteio sai
// do MESMO PRNG semeado, então convergem quadro a quadro sem sincronizar nada.
// Um laço só para os dois modos, como no Display: o cartão é um só.
let pvLiveKind = '';
let pvLiveDesc = null;
let pvLiveTimer = null;

function pvLiveTick() {
  const r = pvLiveKind === 'draw' ? drawReading(pvLiveDesc, Date.now())
    : pvLiveKind === 'chrono' ? chronoReading(pvLiveDesc, Date.now()) : null;
  if (!r) return;
  pvTextMainEl.textContent = r.text;
  pvTextMainEl.style.setProperty('--ch', r.text.length);  // ver .mode-chrono no CSS
  pvTextContentEl.classList.toggle('chrono-over', !!r.over);
  pvTextContentEl.classList.toggle('draw-rolling', !!r.rolling);
  if (pvLiveKind === 'draw' && !r.rolling) stopPvLiveTimer();
}

function startPvLive(kind, desc) {
  pvLiveKind = kind; pvLiveDesc = desc || {};
  stopPvLiveTimer();
  pvLiveTick();
  if (kind === 'draw') {
    if (pvLiveDesc.rollUntil && Date.now() < pvLiveDesc.rollUntil) {
      pvLiveTimer = setInterval(pvLiveTick, DRAW_FRAME_MS);
    }
    return;
  }
  if (pvLiveDesc.mode === 'clock' || pvLiveDesc.running) {
    pvLiveTimer = setInterval(pvLiveTick, CHRONO_TICK_MS);
  }
}

function stopPvLiveTimer() {
  if (pvLiveTimer) { clearInterval(pvLiveTimer); pvLiveTimer = null; }
}

function clearPvLive() {
  stopPvLiveTimer(); pvLiveKind = ''; pvLiveDesc = null;
  pvTextContentEl.classList.remove('chrono-over', 'draw-rolling');
}

// A metade da preview do modo IMAGEM. Mesma anatomia do lado do telão, e mesma
// razão para a URL ser revogada num lugar só: os dois WebViews dividem o
// processo, e um objectURL por imagem projetada num app que fica aberto o culto
// inteiro é vazamento no lugar mais caro.
let pvTextImgUrl = null;
let pvTextImgSeq = 0;
function soltarPvTextImg() {
  if (pvTextImgUrl) { URL.revokeObjectURL(pvTextImgUrl); pvTextImgUrl = null; }
  pvTextImgEl.hidden = true;
  pvTextImgEl.removeAttribute('src');
}
async function pintarPvTextImg(obj) {
  const seq = ++pvTextImgSeq;
  soltarPvTextImg();
  let rec = null;
  if (obj.mediaId) { try { rec = await AVDB.getMedia(obj.mediaId); } catch (_) { rec = null; } }
  if (seq !== pvTextImgSeq || !rec) return;
  // A PÁGINA DA APRESENTAÇÃO, aqui também (v1.4.28) — e o "também" é o ponto.
  // Esta é a metade PREVIEW do `pintarTextImg` do telão, e as duas escolhem o
  // blob por conta própria: sem esta linha a preview mostraria a página 1 para
  // sempre enquanto o telão passa slides, e SEM TV ela É a projeção. É a
  // armadilha que o `fundo-da-letra` já pagou uma vez — *ler cada lado isolado
  // aprova os dois*.
  if (Array.isArray(rec.pages) && rec.pages.length) {
    const pg = rec.pages[Math.min(Math.max(obj.page | 0, 0), rec.pages.length - 1)];
    if (!pg) return;
    rec = (typeof pg === 'string') ? { url: pg } : { blob: pg };
  }
  let src = '';
  if (rec.blob) { pvTextImgUrl = URL.createObjectURL(rec.blob); src = pvTextImgUrl; }
  else if (rec.opfsPath) {
    let f = null;
    try { f = await AVDB.opfsGetFile(rec.opfsPath); } catch (_) {}
    if (seq !== pvTextImgSeq) return;
    if (f) { pvTextImgUrl = URL.createObjectURL(f); src = pvTextImgUrl; }
  } else if (rec.url) src = rec.url;
  if (!src) return;
  pvTextImgEl.src = src;
  pvTextImgEl.hidden = false;
  // Repõe o giro no instante em que a camada ganha caixa medível — ver
  // `reporGiro` no `stage.js`.
  preview.reporGiro();
}

function showPvText(obj) {
  const wallpaper = obj.view === 'wallpaper';
  const isMsg = obj.mode === 'message';
  const isChrono = obj.mode === 'chrono';
  const isDraw = obj.mode === 'draw';
  const isImg = obj.mode === 'image';
  pvTextContentEl.classList.toggle('mode-message', isMsg);
  pvTextContentEl.classList.toggle('mode-chrono', isChrono);
  pvTextContentEl.classList.toggle('mode-draw', isDraw);
  pvTextEl.classList.toggle('mode-img', isImg);
  if (!isImg) soltarPvTextImg();
  if (isImg) {
    // A PREVIEW É A ILUSTRAÇÃO DO TELÃO, e um cartão preto onde o telão mostra
    // uma imagem é a ilustração errada — o operador confere pela preview o que
    // a congregação vê.
    clearPvLive();
    pvTextMainEl.textContent = '';
    pintarPvTextImg(obj);
  } else if (isChrono) {
    startPvLive('chrono', obj.chrono || {});
  } else if (isDraw) {
    startPvLive('draw', obj.draw || {});
  } else {
    clearPvLive();
    pvTextMainEl.textContent = obj.main || '';
  }
  pvTextSubEl.textContent = obj.sub || '';
  if (pvTextActive) {
    // Já em cena (troca de versículo/mensagem): fade-in do texto.
    pvFadeIn(pvTextMainEl); if (obj.sub) pvFadeIn(pvTextSubEl);
    preview.instantCover(wallpaper);
    return;
  }
  // O cartão é OPACO e fica acima de toda a mídia (.pv-text, z-index 2): nada
  // precisa ser interrompido para ele aparecer — nem o player do YouTube, que
  // antes era derrubado aqui e não tinha como voltar. A letra sincronizada é a
  // única exceção (ela É texto; volta em hidePvText, no slide certo).
  hidePvLyrics(true);
  pvTextActive = true;
  pvLayerIn(pvTextEl);
  if (wallpaper) preview.instantCover(true); else preview.coverOut();
}

// ===== util =====
function fmtTime(s) {
  if (!s || !isFinite(s)) return '0:00';
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return m + ':' + String(sec).padStart(2, '0');
}
function msym(code) {
  const s = document.createElement('span');
  s.className = 'msym';
  s.textContent = code;
  return s;
}
function persistCurrent() {
  // `noAr` É O QUE SOLTA O DETENTOR. `state.current.mediaId` sobrevive ao fim da
  // mídia de propósito (é o que o ▶ repete), então ele sozinho não serve de
  // detentor para o coletor: prenderia para sempre o último item tocado, e
  // excluí-lo deixaria os bytes no aparelho sem lugar visível onde removê-los —
  // o fantasma da v5.87. Com a bandeira, o `lerDetentores` só conta a cena
  // enquanto ela está NO TELÃO, e `pararMidia`/`resetAfterEnd` a soltam sozinhos.
  return AVDB.setState('current', {
    mediaId: currentId, noAr: midiaNoAr, view, muted, volume, at: Date.now(),
  });
}

// Sessão nova, player LIMPO. A mídia que ficou selecionada na sessão anterior
// não volta ao abrir o app: `current` é estado de uma sessão (o que estava no
// ar naquele culto), não biblioteca. O Cronograma, a playlist, os favoritos, as
// coleções e a Bíblia baixada continuam intactos — some só a seleção, e o item
// segue a um toque de distância na lista.
//
// O volume, o mudo e a cortina (`view`) FICAM: são o ajuste da mesa, não uma
// seleção — quem deixou o volume em 40 na semana passada não quer reabrir em
// 100.
//
// E NÃO manda `clear` para o telão. No app os dois WebViews sobem juntos (o
// Display já nasce no wallpaper, e nada é retomado sem comando explícito); no
// navegador o Display é outra janela, que pode estar projetando — e uma recarga
// do Controle (a do service worker, inclusive) apagaria a projeção no meio do
// culto.
async function clearCurrentSelection() {
  const cur = (await AVDB.getState('current')) || {};
  if (!cur.mediaId) return;
  await AVDB.setState('current', { ...cur, mediaId: null, at: Date.now() });
}

// ===== miniaturas =====
function drawThumb(srcEl, w, h) {
  return new Promise((resolve) => {
    const size = 160;
    const canvas = document.createElement('canvas');
    canvas.width = size; canvas.height = size;
    const ctx = canvas.getContext('2d');
    const scale = Math.max(size / w, size / h);
    const dw = w * scale, dh = h * scale;
    ctx.drawImage(srcEl, (size - dw) / 2, (size - dh) / 2, dw, dh);
    canvas.toBlob((b) => resolve(b), 'image/jpeg', 0.72);
  });
}
function thumbFromImage(file) {
  return new Promise((resolve) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = async () => {
      try { resolve(await drawThumb(img, img.naturalWidth, img.naturalHeight)); }
      catch (e) { resolve(null); }
      finally { URL.revokeObjectURL(url); }
    };
    img.onerror = () => { URL.revokeObjectURL(url); resolve(null); };
    img.src = url;
  });
}
function thumbFromVideo(file, medidas) {
  return new Promise((resolve) => {
    const url = URL.createObjectURL(file);
    const v = document.createElement('video');
    let settled = false;
    function finish(blob) {
      if (settled) return;
      settled = true;
      URL.revokeObjectURL(url);
      resolve(blob);
    }
    v.muted = true; v.preload = 'auto'; v.playsInline = true;
    // A altura e a duração saem de CARONA no elemento que já vai ser carregado
    // para a miniatura — medi-las depois custaria um segundo decode do mesmo
    // arquivo. Em `loadedmetadata` porque é o evento mais cedo em que elas
    // existem: se o prazo de segurança lá embaixo vencer antes do seek, os
    // números já foram guardados.
    v.onloadedmetadata = () => {
      if (!medidas) return;
      medidas.height = v.videoHeight || 0;
      medidas.seconds = Math.round(v.duration) || 0;
    };
    v.onloadeddata = () => {
      try { v.currentTime = Math.min(0.5, (v.duration || 1) / 3); }
      catch (e) { finish(null); }
    };
    v.onseeked = async () => {
      try { finish(await drawThumb(v, v.videoWidth || 160, v.videoHeight || 160)); }
      catch (e) { finish(null); }
    };
    v.onerror = () => finish(null);
    v.src = url;
    // Garante limpeza caso onseeked nunca dispare (ex: vídeo com duração=0).
    setTimeout(() => finish(null), 3500);
  });
}
async function makeThumb(file, kind, medidas) {
  if (kind !== 'image' && kind !== 'video') return null;
  return kind === 'image' ? thumbFromImage(file) : thumbFromVideo(file, medidas);
}

// A MINIATURA de um item de YouTube SEM bytes (link guardado, não baixado).
//
// Baixa o `hqdefault.jpg` como Blob, para o registro guardar mídia de verdade
// em vez de uma URL externa — a mesma miniatura que hoje some assim que a
// conexão cai. `null` cobre TODO desfecho ruim (sem rede, CORS recusado,
// prazo vencido, HTTP != 2xx, blob vazio ou grande demais): quem chama cai de
// volta na URL string, o comportamento de sempre.
/** Teto de tamanho do Blob: `hqdefault.jpg` mede 15-30 kB de costume — bem
 *  abaixo disto —, e o teto é só uma cerca contra o CDN um dia redirecionar
 *  para outro asset. */
const THUMB_YOUTUBE_MAX_BYTES = 300000;
const THUMB_YOUTUBE_PRAZO_MS = 5000;
function thumbYoutube(id) {
  if (!id) return Promise.resolve(null);
  const url = 'https://img.youtube.com/vi/' + id + '/hqdefault.jpg';
  const busca = fetch(url).then((res) => {
    if (!res.ok) throw new Error('HTTP ' + res.status);
    return res.blob();
  }).then((b) => (b && b.size && b.size < THUMB_YOUTUBE_MAX_BYTES ? b : null))
    .catch(() => null);
  const prazo = new Promise((resolve) => setTimeout(() => resolve(null), THUMB_YOUTUBE_PRAZO_MS));
  return Promise.race([busca, prazo]);
}

// A DURAÇÃO de um áudio, para o subtítulo da lista (v5.118).
//
// Vídeo não precisa disto: o `<video>` que monta a miniatura já sabe a altura e
// a duração, então elas saem de carona. Áudio não tem miniatura, e um decode
// só para medir seria caro se ele lesse o arquivo — daí `preload='metadata'`,
// que traz o cabeçalho e para.
//
// Prazo curto e falha em ZERO: um formato que o WebView não sabe abrir não pode
// travar uma importação. Sem o número, o subtítulo diz só "Áudio", que é o
// comportamento de antes deste campo existir.
function medirAudio(file) {
  return new Promise((resolve) => {
    const url = URL.createObjectURL(file);
    const a = document.createElement('audio');
    let pronto = false;
    const fim = (seg) => {
      if (pronto) return;
      pronto = true;
      URL.revokeObjectURL(url);
      resolve(seg);
    };
    a.preload = 'metadata';
    // `Infinity` É O CASO NORMAL de um blob de `MediaRecorder`: o WebM sai sem
    // duração no cabeçalho, e `Math.round(Infinity) || 0` é `Infinity` — que
    // atravessava o `m.seconds || null` e virava `seconds: Infinity` no
    // registro. O estrago é contido (`fmtTime` e `seekEl.max` guardam
    // `isFinite`), mas o desfecho é uma faixa sem duração, sem barra e sem
    // seek, sem nada que explique.
    a.onloadedmetadata = () => {
      const d = a.duration;
      fim(Number.isFinite(d) && d > 0 ? Math.round(d) : 0);
    };
    a.onerror = () => fim(0);
    a.src = url;
    setTimeout(() => fim(0), 4000);
  });
}

// Miniatura + os metadados do subtítulo, numa passada só.
//
// Usado nos dois caminhos de IMPORTAÇÃO (o seletor de arquivos e o
// compartilhamento), que trazem alguns arquivos por vez. A sincronização de
// PASTA fica de fora de propósito: ela percorre centenas de arquivos, e uma
// leitura de metadados por áudio ali é um custo que o operador sente no tempo
// da sincronização inteira, para ganhar um detalhe numa linha. Lá o subtítulo
// diz só o tipo, que já é a informação que faltava.
async function prepararMidia(file, kind) {
  const m = {};
  const thumb = await makeThumb(file, kind, m);
  if (kind === 'audio') m.seconds = await medirAudio(file);
  return { thumb, height: m.height || null, seconds: m.seconds || null };
}

// ===== carregar + render =====
// Guarda de sequência: load() é async e disparada fire-and-forget por dezenas
// de handlers. Sem isto, duas chamadas concorrentes poderiam terminar fora de
// ordem e a mais antiga sobrescreveria o estado/render da mais nova. Só o
// último load() aplica seu resultado (mesmo padrão do loadSeq do stage.js).
let loadSeqCtl = 0;
/**
 * Redesenha a lista da aba atual.
 *
 * `opts.restaurarScroll` — só a NAVEGAÇÃO o passa. A última linha desta função
 * escrevia `scrollPos[scrollKey()]` incondicionalmente, e o único produtor
 * daquele mapa é `rememberScroll()`, chamado em DOIS lugares: a troca de aba e
 * o voltar. Isto é: em todo redesenho que não fosse navegação — acrescentar um
 * item, favoritar, o progresso de um download, a chegada de um share — a lista
 * saltava de volta para onde o operador estava da última vez que TROCOU DE ABA,
 * quase sempre o topo. Ele rolava até o meio do Cronograma, mandava um louvor
 * para lá, e a lista voltava para o começo.
 *
 * Sem a flag, o padrão passa a ser o certo: um redesenho no lugar mantém o
 * lugar. A navegação continua restaurando a posição guardada daquela aba.
 */
async function load(opts) {
  // Medido ANTES da reconstrução — depois de `host.innerHTML = ''` a rolagem
  // já é zero.
  const restaurar = !!(opts && opts.restaurarScroll);
  const topoAntes = restaurar ? 0 : libraryEl.scrollTop;
  const myseq = ++loadSeqCtl;

  // ---- FASE 1: só leituras do IDB, em locais (nada de estado/DOM ainda) ----
  const cur = await AVDB.getState('current');
  const repeatV = (await AVDB.getState('repeat')) || 'off';
  const plItemsV = await AVDB.listItems('playlist');
  const opfsFoldersV = (await AVDB.getState('opfs-folders')) || [];
  // Os favoritos entram na FASE 1 como todo o resto: a estrela de cada linha é
  // desenhada por `renderLibrary`, e ela precisa do conjunto pronto — ler
  // depois faria a primeira pintura sair com todas as estrelas apagadas.
  const favIdsV = await AVDB.listIds('favs');
  const favItemsV = await AVDB.listItems('favs');
  // O CRONOGRAMA em ids (v1.4.25), e SEMPRE — não só quando ele é a aba ativa.
  // `libItemsV` logo abaixo é a lista da aba, e a fila da playlist é desenhada
  // com a Biblioteca aberta: sem esta leitura o botão "ao Cronograma" da fila
  // nasceria apagado sobre um item que já está lá.
  const cronoIdsV = await AVDB.listIds('imports');
  const messagesV = (await AVDB.getState('messages')) || [];
  const chronoPrefsV = (await AVDB.getState('chronoPrefs')) || null;
  const drawPrefsV = (await AVDB.getState('drawPrefs')) || null;
  const storedFit = await AVDB.getState('fit');
  const storedRot = await AVDB.getState('rotate');
  const lvFonteV = await AVDB.getState('lyricsFont');
  const cifraVelV = await AVDB.getState('cifraVelocidade');
  const cifraFonteCheiaV = await AVDB.getState('cifraFonteCheia');
  const lyricsBgV = (await AVDB.getState('lyricsBg')) === 'black' ? 'black' : 'image';
  const downloadOkV = !!(await AVDB.getState('downloadOk'));
  // A LISTA DA TELA É SEMPRE O CRONOGRAMA (v1.5.0). Ela era `listItems(activeTab)`
  // dentro de uma guarda, porque a aba podia ser a Bíblia — e ali a leitura
  // tinha de ser pulada: `'bible'` não é lista de mídia, e passá-la por
  // `listItems` (um `getMedia` por id) lançaria `DataError` e derrubaria o
  // `load()` inteiro. Com a Bíblia virando FOLHA, a lista de baixo não muda
  // nunca, e a guarda deixou de ter o que guardar.
  const libItemsV = await AVDB.listItems('imports');
  const curMediaId = cur && cur.mediaId ? cur.mediaId : null;
  const currentItemV = curMediaId ? (await AVDB.getMedia(curMediaId)) || null : null;

  // Um load() mais novo assumiu enquanto este lia o IDB — descarta este.
  if (myseq !== loadSeqCtl) return;

  // ---- FASE 2: aplica ao estado do módulo + render (síncrono, atômico) ----
  currentId = curMediaId;
  view = (cur && cur.view) || 'visual';
  muted = !!(cur && cur.muted);
  volume = (cur && typeof cur.volume === 'number') ? cur.volume : 1;
  repeat = repeatV;
  plItems = plItemsV;
  opfsFolders = opfsFoldersV;
  favSet = new Set(favIdsV);
  favItems = favItemsV;
  cronoSet = new Set(cronoIdsV);
  messages = messagesV;
  applyChronoPrefs(chronoPrefsV);
  applyDrawPrefs(drawPrefsV);
  // "Esticar" SAIU da UI na v5.142 e o valor guardado é MIGRADO aqui, uma vez.
  // Sem a migração, quem já o tinha escolhido continuaria com a mídia distorcida
  // no telão e sem nenhum botão na tela que explicasse por quê — o pior estado
  // possível: o defeito permanece e o controle dele some.
  if (storedFit === 'fill') { mediaFit = 'contain'; AVDB.setState('fit', mediaFit); }
  else if (storedFit) mediaFit = storedFit;
  mediaRot = ROTACOES.includes(storedRot | 0) ? (storedRot | 0) : 0;
  // O TAMANHO DA LETRA guardado. Como o `mediaRot` logo acima: valor fora da
  // escada cai no padrão, e não numa medida que ninguém escolheu — a escada pode
  // encolher numa versão futura, e o que estava salvo continua sendo lido.
  lvTamanho = LV_TAMANHOS.includes(lvFonteV) ? lvFonteV : LV_PADRAO;
  cifraAdotarVelocidade(cifraVelV);
  // A SEGUNDA ESCADA (v1.6.0): o corpo da cifra em tela cheia é uma escolha
  // INDEPENDENTE da do retrato, e ausente ela é semeada na primeira entrada.
  cifraAdotarFonteCheia(cifraFonteCheiaV);
  aplicarTamanhoDaLetra();
  lyricsBg = lyricsBgV;
  downloadConsent = downloadOkV;
  libItems = libItemsV;
  currentItem = currentItemV;

  renderLyricsBgTile();
  renderControls();
  renderNowPlaying();
  renderRepeat();
  renderLibToggle();
  renderListTitle();
  renderPlaylist();
  renderLibrary();
  // A seção de Favoritos da Biblioteca é a OUTRA lista que este `load()` acabou
  // de reaplicar (`favItems`/`favSet`/`opfsFolders`), e ninguém a redesenhava —
  // ver `sincronizarFavoritosNaBiblioteca`.
  sincronizarFavoritosNaBiblioteca();
  renderSelbar();
  renderSlideNav();

  // mantém a preview alinhada (sem recarregar a mídia). NÃO mexe na cortina
  // (setView) enquanto um texto bíblico está em cena: a Bíblia é uma camada
  // paralela e o stage da preview está sem `current` (=null), então setView
  // recobriria a cortina e o texto sumiria da preview ao trocar de aba — a
  // projeção deve ser independente da navegação, como qualquer outra mídia.
  if (!pvTextActive) preview.setView(view);
  preview.setMute(muted); preview.setVolume(volume);
  preview.setFade({ fadeIn: fadeCfg.in, fadeOut: fadeCfg.out, time: fadeCfg.time });
  preview.setFit(mediaFit);
  preview.setRotate(mediaRot);
  // OS TILES DO PAINEL SÃO PINTADOS AQUI, e não só ao abrir a folha (v1.4.38).
  // Um segmentado carregava o valor de cada opção no HTML (`data-fit`), então
  // ele já dizia a verdade antes de alguém olhar; um tile só diz o que a
  // pintura escreveu — sem esta linha o `data-estado` fica `null` até a
  // primeira abertura de Configurações, e um estado ausente lido como "não
  // está preenchendo" é o tipo de mentira que não erra alto.
  // A CONTAGEM DE USO não está aqui: ela saiu da grade na v1.4.41 (é uma linha
  // do rodapé do Registro agora) e, mesmo antes, ficava de fora — é uma ida à
  // ponte, e `load()` roda dezenas de vezes por culto. Quem a pinta é o
  // `openFadePopup`, o único instante em que alguém olha para ela.
  renderRotBtn();
  renderFitTile();
  renderTemaTile();

  // A posição: a GUARDADA quando isto é navegação, a de ANTES quando é um
  // redesenho no lugar.
  libraryEl.scrollTop = restaurar ? (scrollPos[scrollKey()] || 0) : topoAntes;
}

// Chave de posição de scroll. Ela era a ABA; com o Cronograma virando a tela
// única sobrou uma chave só — o mapa fica porque `rememberScroll`/`load` o
// consultam em pontos espalhados, e um nome constante custa menos que
// desmontá-los.
function scrollKey() {
  return 'imports';
}
function rememberScroll() {
  scrollPos[scrollKey()] = libraryEl.scrollTop;
}

// CONVENÇÃO (v5.50): o ÍCONE RISCADO mostra o CORTE — o estado em que a coisa
// está desligada —, e a cor/borda confirma. Vale para os dois cortes do app: o
// som (alto-falante riscado = mudo) e a imagem (imagem riscada = telão coberto).
//
// A v5.47 tinha adotado o oposto ("o ícone mostra a AÇÃO que o toque executa"),
// e a razão declarada era que estado e ação conviviam misturados na tela. O
// problema era real, mas a solução escolhida gastava o riscado — o símbolo
// universal de "cortado" — para dizer justamente que NÃO está cortado. Nada se
// perde invertendo: a COR já carrega o estado sozinha (`.alternado`, `.muted` e
// `.blocked` pintam o traço sobre a preview e o botão inteiro no Modo Fácil), o
// `title` continua nomeando a ação, e o ícone volta a ser lido como todo mundo
// lê um alto-falante riscado.
//
// O ▶/⏸ segue sendo AÇÃO — ali a convenção é de plataforma (todo player do
// mundo mostra ▶ quando está pausado) e o botão não tem cor de estado.
// `renderRepeat` também segue mostrando o modo atual (ver lá).
function renderControls() {
  // Coberto → imagem RISCADA; mídia no ar → imagem inteira. Desde a v1.3.5 os
  // dois botões moram SOBRE a preview e o desenho é SVG do sprite: quem troca é
  // a classe `.alternado` (o `<use>` do estado ativo aparece, o outro some — ver
  // `.pv-fab .ico-alt`), a MESMA chave do `#fsView` da tela cheia. Era um glifo
  // da fonte, e sobre a miniatura ele não teria traço para as três
  // `drop-shadow` do `.pv-fab` sombrearem — perdia o contraste que o mantém
  // legível sobre um slide branco.
  viewToggleEl.classList.toggle('alternado', view === 'wallpaper');
  viewToggleEl.title = view === 'visual' ? 'Cobrir o telão' : 'Mostrar a mídia no telão';
  viewToggleEl.setAttribute('aria-label', viewToggleEl.title);
  // 3 estados do botão de mudo: normal | mudo (operador) | sem áudio no
  // Display (navegador bloqueou — tocando mudo; clique tenta liberar). Nos dois
  // últimos NÃO SAI SOM, e é isso que o riscado diz; o que os distingue é a
  // cor (vermelho de mudo × âmbar pulsante de bloqueado).
  const blocked = displayAudioBlocked && !muted;
  muteToggleEl.classList.toggle('alternado', muted || blocked);
  muteToggleEl.classList.toggle('muted', muted);
  muteToggleEl.classList.toggle('blocked', blocked);
  muteToggleEl.title = blocked
    ? 'Sem áudio no Display — toque para tentar liberar'
    : muted ? 'Tirar o mudo' : 'Mutar';
  muteToggleEl.setAttribute('aria-label', muteToggleEl.title);
  // Os DOIS mostradores de volume (o fader do deck e a leitura do Modo Fácil)
  // saem daqui: um só ponto os escreve, então nunca divergem.
  syncFader(Math.round(volume * 100));
  renderSimple();
  // A coluna da tela cheia espelha a cortina daqui: este é o único ponto que a
  // escreve, então é o único que precisa avisar.
  renderFsCtl();
  // A cortina (view) muda por aqui, não por renderNowPlaying — e o rótulo do
  // botão da notificação depende dela. A deduplicação segura o excesso.
  pushNowPlaying();
}

// O dedo está no fader? (ver os ouvintes dele, no fim do arquivo). Declarada
// AQUI, ao lado da única função que a lê: `renderControls` chama `syncFader` na
// abertura, muito antes de a parte de baixo do arquivo ser avaliada.
let volArrastando = false;

// Põe o fader no volume atual. O trilho e o preenchimento são desenhados pelo
// nosso CSS (ver `.fader`), porque a espessura do trilho nativo é fixa e não
// acompanha a largura da coluna — e `appearance: none` desliga junto o
// preenchimento que vinha do `accent-color`. `--vol` é esse preenchimento, e
// mora no WRAPPER porque o número dentro do cap é irmão do input.
//
// O input NÃO é reescrito enquanto o dedo o arrasta: o valor voltaria
// arredondado no meio do movimento. O preenchimento e o número, sim — eles
// devem seguir o dedo.
function syncFader(pct) {
  if (!volArrastando) volSliderEl.value = pct;
  faderWrapEl.style.setProperty('--vol', String(pct / 100));
  volValueEl.textContent = String(pct);
}

// EXCEÇÃO à convenção "ícone = ação": este botão CICLA por quatro modos
// (off → all → one → shuffle), não alterna dois. Num par binário mostrar a ação
// não custa nada, porque o estado é o inverso dela; num ciclo de quatro, o
// glifo só cabe um — mostrar o PRÓXIMO modo apagaria da tela qual está valendo,
// e a cor (`.active`) só distingue ligado de desligado, não qual dos três.
// Então aqui o ícone segue sendo o modo ATUAL, que é a informação que se perde.
function renderRepeat() {
  const icon = repeat === 'one' ? ICON.repeatOne : repeat === 'shuffle' ? ICON.shuffle : ICON.repeatAll;
  const label = repeat === 'off' ? 'Repetição desativada'
    : repeat === 'one' ? 'Repetir 1' : repeat === 'shuffle' ? 'Aleatório' : 'Repetir tudo';
  repeatEl.querySelector('.msym').textContent = icon;
  repeatEl.title = label;
  repeatEl.classList.toggle('active', repeat !== 'off');
}

/**
 * ===== A BADGE DO AUXILIAR DE LEITURA (v1.4.31) =====
 *
 * Pedido do operador: *"crie uma badge nesse botão de auxiliar de leitura para
 * indicar que ele está com alguma função disponível quando houver alguma mídia
 * que disponibiliza uma das funções dele"*.
 *
 * Ela nasce com a mudança de casa do botão. Sobre a preview, "não há o que ler"
 * se lia no próprio palco, a dois centímetros dali — o wallpaper no ar responde
 * a pergunta sozinho. Na sétima célula do deck não há esse contexto: sem a
 * badge, a única forma de descobrir que não há letra é abrir a folha e ler
 * "Nada em exibição".
 *
 * **A FONTE É `lyricsViewSources`, a MESMA que a folha usa.** Uma segunda conta
 * de "o que está disponível" divergiria no primeiro recurso novo, e esta é a
 * que ninguém confere: a folha denuncia o erro dela ao abrir, a badge não
 * denuncia nada — ela só acende errado.
 *
 * **E OS RÓTULOS SAEM DAS PRÓPRIAS ABAS** (`data-lvsrc`), pelo mesmo motivo:
 * uma tabela de nomes aqui seria a terceira lista da mesma pergunta.
 *
 * O `title` diz O QUE há, e a badge diz SE há — o ícone continua sendo a ação.
 * Com a folha ABERTA ela pode descrever o alvo de um ensaio (`lvAlvo`) em vez
 * da cena, e isso é inofensivo: o botão está coberto pela folha, e
 * `closeLyricsPopup` a reescreve ao sair.
 */
function renderLeitorBadge() {
  if (!lvBadgeEl) return;
  const fontes = lyricsViewSources();
  lvBadgeEl.hidden = !fontes.length;
  const nomes = fontes.map((f) => {
    const btn = lyricsViewSegEl.querySelector('.fit-opt[data-lvsrc="' + f + '"]');
    return btn ? (btn.textContent || '').trim().toLowerCase() : f;
  }).join(', ');
  lyricsViewBtnEl.title = nomes
    ? 'Auxiliar de leitura: ' + nomes
    : 'Auxiliar de leitura — nada em exibição';
  lyricsViewBtnEl.setAttribute('aria-label', lyricsViewBtnEl.title);
}

function renderNowPlaying() {
  // O SELO DE CAMADAS PRIMEIRO, e é por isso que ele está no TOPO: esta função
  // tem um `return` por ramo de cena, e qualquer linha no fim dela só rodaria
  // para o último caso.
  renderCamadaBtn();
  // A BADGE do auxiliar de leitura, pelo MESMO motivo e no mesmo lugar: ela
  // depende da pilha de camadas, que muda em todo ramo abaixo.
  renderLeitorBadge();
  // Sorteio EM EXIBIÇÃO.
  if (drawProjecting()) {
    npNameInnerEl.textContent = 'Sorteio';
    applyTitleMarquee();
    playPauseEl.querySelector('.msym').textContent = playing ? ICON.pause : ICON.play;
    renderSimple();
    pushNowPlaying();
    return;
  }
  // Cronômetro/relógio/timer EM EXIBIÇÃO: o nome da ferramenta. Não há barra de
  // progresso (o tempo dele não é o de uma mídia), e o ▶ segue valendo para o
  // áudio de fundo, que continua tocando por baixo do cartão.
  if (chronoProjecting()) {
    const m = CHRONO_MODES.find((x) => x.id === chrono.mode);
    npNameInnerEl.textContent = m ? m.name : 'Cronômetro';
    applyTitleMarquee();
    playPauseEl.querySelector('.msym').textContent = playing ? ICON.pause : ICON.play;
    renderSimple();
    pushNowPlaying();
    return;
  }
  // Letra avulsa EM EXIBIÇÃO: o nome da música + a estrofe. Sem o número, duas
  // estrofes seguidas dão exatamente o mesmo cabeçalho e o operador perde a
  // única referência de onde está na música.
  if (lyricProjecting()) {
    npNameInnerEl.textContent = lyricSession.title
      + ' · ' + (lyricSession.idx + 1) + '/' + lyricSession.stanzas.length;
    applyTitleMarquee();
    // A MESMA regra do cronômetro logo acima: o ▶/⏸ segue o áudio de fundo
    // (que continua por baixo do texto) e o seek fica com quem já o governa
    // (previewTick/display-status). Forçar ▶ fixo e seek desabilitado fazia o
    // transporte piscar até o próximo tick quando havia áudio tocando.
    playPauseEl.querySelector('.msym').textContent = playing ? ICON.pause : ICON.play;
    renderSimple();
    pushNowPlaying();
    return;
  }
  // Mensagem EM EXIBIÇÃO: mostra "Mensagem" no now-playing.
  if (msgSession && msgSession.projecting) {
    npNameInnerEl.textContent = 'Mensagem ' + (msgSession.idx + 1);
    applyTitleMarquee();
    playPauseEl.querySelector('.msym').textContent = playing ? ICON.pause : ICON.play;
    renderSimple();
    pushNowPlaying();
    return;
  }
  // Texto bíblico EM EXIBIÇÃO: mostra a referência (livro cap:versículo). Antes
  // de ativar a exibição (só selecionado), o telão ainda não mostra a Bíblia,
  // então o now-playing segue a mídia/estado normal.
  if (bibleSession && bibleSession.projecting) {
    const v = bibleSession.verses[bibleSession.idx];
    npNameInnerEl.textContent = bibleSession.bookName + ' ' + bibleSession.chapter + ':' + v.n;
    applyTitleMarquee();
    // Mesma regra do cronômetro: ▶/⏸ acompanha o áudio de fundo e o seek não
    // é tocado aqui (ver o comentário no ramo da letra avulsa).
    playPauseEl.querySelector('.msym').textContent = playing ? ICON.pause : ICON.play;
    renderSimple();
    pushNowPlaying();
    return;
  }
  // Prioriza plItems/libItems (já carregados); usa currentItem como fallback
  // para o caso de o item estar somente em outra aba (ex: dentro de uma pasta).
  const cur = [...plItems, ...libItems].find((m) => m.id === currentId) || currentItem;
  // A apresentação leva a PÁGINA no título, pela mesma razão da letra avulsa
  // logo acima: sem o número, duas páginas seguidas dão o mesmo cabeçalho e o
  // operador perde a única referência de onde está no material.
  npNameInnerEl.textContent = cur
    ? (isDeck(cur) ? cur.name + ' · ' + (deckPagina + 1) + '/' + cur.pages.length : cur.name)
    : 'Nada em exibição';
  applyTitleMarquee();
  playPauseEl.querySelector('.msym').textContent = playing ? ICON.pause : ICON.play;
  const isTimed = cur && (cur.kind === 'video' || cur.kind === 'audio');
  seekEl.disabled = !isTimed;
  renderSimple();
  pushNowPlaying();
}

// Título rolante: se o nome da mídia não couber na largura disponível, liga a
// animação de rolagem (ping-pong) para que o operador possa lê-lo inteiro.
// Mede no estado estático (a leitura de scrollWidth força o reflow, que também
// reinicia a animação ao religar a classe). A distância e a duração (velocidade
// ~constante) vão para o CSS via variáveis.
function applyTitleMarquee() {
  npNameEl.classList.remove('scrolling');
  npNameInnerEl.style.removeProperty('--np-shift');
  npNameInnerEl.style.removeProperty('--np-dur');
  const overflow = npNameInnerEl.scrollWidth - npNameEl.clientWidth;
  if (overflow > 4) {
    const shift = overflow + 12; // +margem para o fim do texto sair da borda
    const dur = Math.max(5, shift / 32 + 2);
    npNameInnerEl.style.setProperty('--np-shift', (-shift) + 'px');
    npNameInnerEl.style.setProperty('--np-dur', dur.toFixed(1) + 's');
    npNameEl.classList.add('scrolling');
  }
}

// ===== Notificação de controles / tela de bloqueio (só no app) =====
// O título sai do PRÓPRIO elemento já renderizado (`#npName`), nunca de uma
// segunda árvore de decisão: as três origens (mídia, versículo, mensagem) já
// são resolvidas em `renderNowPlaying`.
//
// `slideMode` decide se ⏮/⏭ passam MÍDIA ou ESTROFE — no modo compacto só cabem
// três botões, e com letra/versículo/mensagem em cena é a estrofe que se passa.
//
// A POSIÇÃO fica FORA da chave de deduplicação: a sessão extrapola o tempo
// sozinha (posição + decorrido × velocidade). Mas um SEEK é descontinuidade que
// a extrapolação não adivinha, e a barra ficaria contando do ponto antigo. Em
// vez de avisar em cada ponto que faz seek (slide, barra, gesto, re-sincronia
// com o Display), compara-se aqui o tempo real com o extrapolado e republica-se
// na divergência: um só lugar cobre todas as causas, inclusive as futuras. A
// tolerância absorve o jitter do `display-status`.
const POS_TOL_MS = 1500;
let lastScene = '';
let lastPosMs = 0, lastPosAt = 0, lastPosPlaying = false;
/**
 * QUAIS BOTÕES A NOTIFICAÇÃO MOSTRA NESTA CENA — e a decisão é daqui por
 * invariante 5: quem sabe se "próxima estrofe" faz sentido agora é esta função,
 * que tem a cena inteira na mão. Cinco botões fixos serviam a UMA cena (mídia
 * tocando); nas outras eles não somem, eles MENTEM — e ocupam o modo compacto,
 * que só mostra três.
 *
 *  - play/pause só com mídia que tenha TEMPO (`temTempo`, a régua da barra de
 *    progresso). Imagem, versículo, mensagem e cronômetro não têm o que pausar.
 *  - ⏮/⏭ só com EIXO: cena com slides (`who`, de `slideTarget`) ou mídia atual.
 *  - cortina e parar existem sempre.
 *
 * A ORDEM IMPORTA: o shell mostra os três primeiros no modo compacto (ele
 * calcula os índices a partir desta lista). Sem transporte, sobem a cortina e o
 * parar, que viram os dois botões grandes do cartão.
 */
function acoesDaNotificacao(who, temTempo) {
  const eixo = !!who || !!currentId;
  const a = [];
  if (eixo) a.push('prev');
  if (temTempo) a.push('playpause');
  if (eixo) a.push('next');
  a.push('view', 'stop');
  return a;
}

// HÁ CENA NO AR? Um VEREDITO, com dois leitores: a sessão de mídia
// (`pushNowPlaying`, que o publica como `active`) e a proteção da preview
// (`acertarProjecaoLocal`). Ele saiu de dentro do primeiro na v1.3.12 — uma
// segunda escrita da mesma pergunta envelheceria à parte, e as duas respostas
// governam coisas que precisam concordar: o serviço em primeiro plano e o
// WebView que não pode ser suspenso.
function cenaNoAr() {
  return !!currentId
    || !!(msgSession && msgSession.projecting)
    || !!(bibleSession && bibleSession.projecting)
    || lyricProjecting()
    || chronoProjecting()
    || drawProjecting();
}

function pushNowPlaying() {
  if (!window.__NATIVE__) return;
  const who = slideTarget();
  // CENA é tudo que está no telão, não só mídia. Cronômetro e sorteio ficavam
  // de fora: `renderNowPlaying` já os trata como cena (escreve "Cronômetro" no
  // título e chama esta função), mas aqui `active` dava false e o Kotlin
  // derrubava a sessão de mídia. O efeito não é a projeção cair no meio — uma
  // vez que qualquer mídia foi tocada, `currentId` nunca mais volta a null e a
  // cena segue ativa —, é o caso da sessão RECÉM-ABERTA: projetar a contagem
  // regressiva de abertura sem ter selecionado mídia nenhuma não LEVANTA o
  // serviço em primeiro plano, e o processo (com a `Presentation` junto)
  // continua descartável sob pressão de memória exatamente durante os dez
  // minutos em que o operador minimiza o app para esperar.
  const active = cenaNoAr();
  // A CENA acabou de ser apurada, e a proteção da preview depende dela — este é
  // o ponto por onde TODA mudança de cena passa. O outro chamador
  // (`acertarSaidaDeAudio`) cobre a outra metade: a conexão mudando.
  acertarProjecaoLocal();
  // A IMAGEM não vira `who` (ela não tem eixo de ⏮/⏭ — ver `slideTarget`),
  // mas o cartão que ela põe na tela é a informação que falta no título: ali
  // continua o nome do ÁUDIO, que é o que o ▶ e a barra de fato controlam.
  // A APRESENTAÇÃO SOBREPOSTA diz a PÁGINA aqui, e não no título: o título
  // continua sendo o do ÁUDIO (é ele que o ▶ e a barra controlam), e sem o
  // número duas páginas seguidas dariam o mesmo cabeçalho — a mesma razão pela
  // qual o deck-como-mídia leva a página no nome.
  const subtitle = deckSobreProjetando()
      ? 'Apresentação · ' + (deckPagina + 1) + '/' + visualSession.rec.pages.length
    : visualSobreProjetando() ? 'Imagem em cena'
    : who === 'bible' ? 'Bíblia'
    : who === 'songlyrics' ? 'Letra (sem música)'
    : who === 'message' ? 'Mensagem'
    : who === 'lyrics' ? 'Letra sincronizada'
    : (plItems.length > 1 && currentId)
      ? 'Playlist · ' + (plItems.findIndex((m) => m.id === currentId) + 1) + ' de ' + plItems.length
      : '';
  // Posição e duração saem da PRÓPRIA barra de progresso, não de um cálculo
  // paralelo: ela já é mantida em dia pelos três caminhos (tick da preview,
  // display-status e tick do YouTube) e é a única fonte que cobre todos os
  // tipos de mídia — `preview.getDuration()` é do `<video>` do stage e não
  // sabe nada de um vídeo do YouTube. Desabilitada = sem linha do tempo
  // (imagem, versículo, mensagem): zera, para o sistema não desenhar uma barra
  // que não significa nada.
  const temTempo = !seekEl.disabled;
  const cena = {
    // OS BOTÕES DA NOTIFICAÇÃO (v5.231). Ver `acoesDaNotificacao`.
    actions: acoesDaNotificacao(who, temTempo),
    active,
    title: npNameInnerEl.textContent || '',
    subtitle,
    playing,
    slideMode: !!who,
    // Como o operador CHAMA o que ⏮/⏭ passam agora. A notificação escrevia
    // "(estrofe)" sempre, e com uma APRESENTAÇÃO em cena isso é simplesmente
    // outra palavra — o que passa ali é página. Num shell antigo o campo é
    // ignorado e o rótulo volta a ser o de sempre.
    //
    // A palavra sai da MESMA tabela que nomeia os botões da tela
    // (`SLIDE_AXIS_NAME`): são a mesma pergunta feita em dois lugares, e a
    // cópia local respondia "estrofe" para um versículo e para uma mensagem.
    slideLabel: SLIDE_AXIS_NAME[who] || 'estrofe',
    wallpaper: view === 'wallpaper',
    positionMs: temTempo ? Math.round((parseFloat(seekEl.value) || 0) * 1000) : 0,
    durationMs: temTempo ? Math.round((parseFloat(seekEl.max) || 0) * 1000) : 0,
  };
  // A posição fica FORA da chave de deduplicação de propósito: a sessão de
  // mídia extrapola o tempo sozinha a partir do último estado e da velocidade
  // (1x tocando), então reenviar a cada segundo só para mexer o cursor seria
  // desperdício. O que precisa chegar é toda MUDANÇA de estado.
  const chave = JSON.stringify([cena.active, cena.title, cena.subtitle,
    cena.playing, cena.slideMode, cena.wallpaper, cena.durationMs,
    // O CONJUNTO DE BOTÕES entra na chave (v5.231): sem ele, uma cena que muda
    // só de eixo — o cronômetro entrando por cima de uma imagem, por exemplo —
    // seria deduplicada e o cartão ficaria com os botões da cena anterior. Um
    // botão que sobrou é pior que um que faltou: ele responde.
    cena.actions.join(',')]);
  const agora = Date.now();
  const extrapolado = lastPosAt
    ? lastPosMs + (lastPosPlaying ? agora - lastPosAt : 0)
    : null;
  // Arrastando a barra, `seekEl.value` é a posição do DEDO e não a da mídia —
  // republicar aí encheria a sessão de instantes que ainda não aconteceram.
  const saltou = !seeking
    && (extrapolado === null || Math.abs(cena.positionMs - extrapolado) > POS_TOL_MS);
  if (chave === lastScene && !saltou) return;
  lastScene = chave;
  lastPosMs = cena.positionMs;
  lastPosAt = agora;
  lastPosPlaying = cena.playing;
  AVNative.nowPlaying(cena);
}

// `playing` e o ícone do ▶/⏸ andam SEMPRE juntos — e a notificação de
// controles precisa saber da troca. Eram sete pontos repetindo as mesmas duas
// linhas, e nenhum deles avisava o nativo: a sessão de mídia nascia "pausada" e
// ficava assim para sempre. Isso produzia dois sintomas de uma vez — o ícone na
// notificação nunca mudava, e o estado que o SISTEMA acreditava divergia do
// real, fazendo `onPlay`/`onPause` caírem nas guardas de `__avRemote` e virarem
// no-op. ⏮/⏭ seguiam funcionando por não dependerem desse estado, que foi
// exatamente o padrão observado em aparelho.
function setPlaying(v) {
  playing = !!v;
  playPauseEl.querySelector('.msym').textContent = playing ? ICON.pause : ICON.play;
  renderFsCtl();   // e a coluna da tela cheia, pelo mesmo motivo
  renderSimple();   // o botão do modo simplificado espelha este
  pushNowPlaying();
}

// Reenvia a cena mesmo sem mudança de estado — usado quando há indício de que
// o que o sistema mostra ficou para trás (ver `__avRemote`).
function resyncScene() {
  lastScene = '';
  pushNowPlaying();
}

// (`renderTabs` era o realce da aba ativa mais o vazado deslizante. Com a faixa
//  fora, o que ocupa o lugar dela é o desenho do botão da Biblioteca — SETA
//  quando ela está fechada, ✕ quando aberta.)
function renderLibToggle() {
  if (!hymnSearchToggleEl) return;
  const aberta = !!hymnSearchPopupEl && hymnSearchPopupEl.classList.contains('open');
  // `ico-alt` é a mesma gramática dos tiles do painel rápido: os dois desenhos
  // vivem na árvore CLARA e a classe escolhe qual aparece. Um `<symbol>` com os
  // dois dentro carregaria os dois para sempre — a folha do documento não
  // atravessa a árvore-sombra de um `<use>`.
  hymnSearchToggleEl.classList.toggle('alt', aberta);
  hymnSearchToggleEl.title = aberta ? 'Fechar a Biblioteca' : 'Abrir a Biblioteca';
  hymnSearchToggleEl.setAttribute('aria-label', hymnSearchToggleEl.title);
}

// O cabeçalho da LISTA (a faixa de cima da tela avançada). Desde a v5.247 ele
// tem DOIS elementos — voltar e título —, e o que saiu foi a troca de modo: ela
// é a mesma decisão do "Modo do app" em Configurações, a dois toques dali, e
// aquela é a que GUARDA a escolha entre aberturas. Com ela foi embora também a
// regra de "só no Cronograma" (v5.111) e o lugar reservado que a sustentava —
// o botão que podia sumir e mover o título simplesmente não existe mais.
// (O cabeçalho DA GAVETA — `renderFavHeader` — saiu com ela na v5.294.)
function renderListTitle() {
  // (O ramo de 'mic' saiu na v1.3.10: as Ferramentas deixaram de ser uma ABA e
  //  viraram uma FOLHA do Cronograma, com título próprio. O cabeçalho da tela
  //  continua dizendo "Cronograma", que é onde o operador de fato está.
  //  As funções seguem `renderDiversos`/`refreshDiversos` e o `miscTool` segue
  //  com os ids de sempre — renomeá-las não mudaria nada visível.)
  // (O ramo da BÍBLIA saiu na v1.5.0, com a aba. O cabeçalho do app diz sempre
  //  "Cronograma" porque é a tela única; o nome da Bíblia e o voltar DELA moram
  //  na barra da folha, que é o lugar de quem está dentro de uma janela.)
  backBtnEl.hidden = true;
  listTitleEl.hidden = false;
  listTitleEl.textContent = 'Cronograma';
}

// ---- thumb element ----
function thumbEl(item) {
  const t = document.createElement('div');
  t.className = 'thumb';
  if (item.thumb && typeof item.thumb === 'string') {
    // URL string thumb (e.g. YouTube hqdefault)
    const im = document.createElement('img'); im.src = item.thumb; im.alt = '';
    t.appendChild(im);
  } else if (item.thumb) {
    const url = URL.createObjectURL(item.thumb);
    thumbUrlsAtual.push(url);
    const im = document.createElement('img'); im.src = url; im.alt = '';
    t.appendChild(im);
  } else {
    t.appendChild(msym(item.kind === 'audio' ? ICON.music : ICON.broken));
    t.classList.add('thumb--icon');
  }
  return t;
}

// ---- Playlist (sequência) ----
function renderPlaylist() {
  // O ESTADO DOS BOTÕES DE PLAYLIST DAS OUTRAS LISTAS anda com esta função
  // (v5.302) — ver `marcarNaPlaylist`. Ela é o ponto por onde TODA mudança da
  // fila passa, e é isso que dispensa cada porta de lembrar do repintor.
  marcarNaPlaylist();
  const count = plItems.length;
  // O badge (e a cor do ícone) não devem chamar atenção quando a playlist é só
  // a mídia atual (1 item); conta apenas os itens além do primeiro (2 itens →
  // "1", 3 → "2"...) — mesmo critério pros dois, o ícone só fica destacado
  // quando existe de fato uma fila além do item em exibição.
  plCountEl.textContent = count > 1 ? String(count - 1) : '';
  plPopupCountEl.textContent = String(count);
  plBtnEl.classList.toggle('has-items', count > 1);
  // COM A FILA VAZIA NÃO HÁ O QUE LIMPAR, e um botão que não faz nada é pior
  // que botão nenhum — ainda mais um destrutivo, que assim ensinaria que
  // tocá-lo é inofensivo. A caixa inteira sai (ela carrega a margem do rodapé),
  // e leva junto qualquer pergunta que estivesse aberta nela.
  if (count === 0 && plClearFaixaEl.classList.contains('confirmando')) fecharConfirmacaoNaLinha();
  plClearFaixaEl.hidden = count === 0;

  playlistEl.innerHTML = '';
  if (count === 0) {
    // O texto mandava DESLIZAR o item para a esquerda — o gesto saiu na v5.50
    // (ver `attachRowGestures`) e a frase ficou para trás, ensinando ao
    // operador um caminho que não existe mais. Hoje se acrescenta pela seleção
    // múltipla ou pela folha de destinos do acervo.
    playlistEl.innerHTML = '<li class="empty">Playlist vazia.<br>Segure um item da lista para selecioná-lo'
      + '<br>e toque em "Acrescentar à playlist".</li>';
    return;
  }
  plItems.forEach((item, i) => {
    const li = document.createElement('li');
    li.className = 'row-item' + (linhaAtiva(item.id) ? ' active' : '')
      + (linhaNoAr(item.id) ? ' no-ar' : '');
    li.dataset.id = item.id;

    const row = document.createElement('div');
    row.className = 'row';
    const name = document.createElement('span'); name.className = 'row-name'; name.textContent = item.name;
    // ===== A LIXEIRA DO APP, E NÃO UMA SÓ DESTA LISTA (v5.301) =====
    //
    // Pedido do operador: *"na playlist, ajuste o botão de excluir para que
    // represente o mesmo ícone de excluir que já usamos no resto do sistema"*.
    // Era `playlist_remove` — a pilha de linhas com um "−" —, o único
    // destrutivo do app desenhado por um símbolo próprio: o mesmo gesto tinha
    // dois desenhos conforme a lista em que a linha por acaso morava.
    //
    // E COM O ÍCONE VEM A CONFIRMAÇÃO, pela régua que o excluir da linha já
    // segue: um mesmo desenho com dois alcances conforme a tela (aqui apaga no
    // toque, ali pergunta) é a pior forma de oferecer um destrutivo. A classe
    // `row-excluir` é o que o inscreve em `ACOES_QUE_NAO_FECHAM`.
    //
    // O QUE NÃO MUDA É A SEMÂNTICA, e por isso ele não é um
    // `botaoExcluirDaLinha`: sair da FILA não é sair de uma lista de acervo.
    // Sem `retirarDoAr` (o item pode estar no Cronograma e seguir projetando) e
    // sem `soltarAvulso` — a prateleira `avulsos` é
    // detentora à parte, e soltá-la aqui apagaria a mídia que o "Tocar agora"
    // segurava.
    //
    // A FILA, ESSA, É DETENTORA como qualquer outra lista (ver LISTS em
    // `db.js`, e o KDoc de `togglePlaylist`): o `listRemove` roda o coletor na
    // MESMA transação, e sair da ÚLTIMA lista apaga os bytes. É a cláusula que
    // a dica diz por extenso — um gesto que parece reversível e não é custa,
    // num episódio de série, ~300 MB baixados em rede de celular.
    const rm = document.createElement('button');
    rm.className = 'row-btn row-excluir';
    rm.title = 'Tirar da playlist';
    rm.setAttribute('aria-label', 'Tirar da playlist');
    rm.appendChild(msym(ICON.del));
    rm.addEventListener('click', (e) => {
      e.stopPropagation();
      pedirConfirmacaoNaLinha(rm, {
        ok: 'Tirar',
        dica: 'Tirar da fila. O arquivo só é apagado se ele não estiver '
          + 'guardado em mais nenhuma lista.',
        aoConfirmar: async () => { await AVDB.listRemove('playlist', item.id); await load(); },
      });
    });
    // A GAVETA DO `⋮` CHEGOU AQUI NA v5.285, e ela é o que torna o par ↑↓
    // possível nesta lista: até então a fila era a única com alça de arrastar e
    // sem botão de opções. Tirar o gesto sem dar a gaveta deixaria a fila como a
    // única lista do app sem como reordenar.
    //
    // ===== E A FILA GANHOU OS DOIS DESTINOS (v1.4.25) =====
    //
    // Pedido do operador: *"na lista da playlist, pode adicionar opções como:
    // adicionar aos favoritos e adicionar ao cronograma"*.
    //
    // Ela era a única das três listas sem caminho para as outras duas: da linha
    // daqui só se saía tirando da fila. E é o pior lugar para esse buraco — a
    // fila é onde o bloco de louvores é montado, e "esta faixa merece ficar
    // guardada" é a decisão que se toma justamente aí.
    //
    // A ORDEM É A DO CRONOGRAMA (v5.302), com a ressalva de não contar com o
    // que não existe nesta lista: o que mexe no ITEM (tirar da fila), o que
    // mexe em ONDE ele está (favoritar, Cronograma) e o que mexe na POSIÇÃO
    // (↑↓). Falta o botão da PLAYLIST — esta LINHA é a playlist —, e o
    // renomear, que nunca esteve aqui.
    //
    // OS DOIS SÃO ALTERNADORES COM ESTADO À VISTA, como no Cronograma: a
    // pergunta que se faz montando o culto é "está lá?", não "eu mandei?".
    // UMA CENA DE ROTEIRO NÃO GANHA O DA FILA no Cronograma (*"um versículo não
    // é uma fila de reprodução"*), e aqui a guarda não é necessária pelo motivo
    // oposto — um cue não entra na playlist, então esta linha nunca é um.
    row.append(name, ...montarAcoesDaLinha(li, [
      rm,
      favBtn(item.id, item.name),
      cronoBtnDaLinha(item),
      ...botoesDeOrdem('playlist', item.id, i, plItems.length),
    ], 'playlist:' + item.id));
    li.appendChild(row);
    // O SEGUNDO TOQUE RETIRA DO AR (ver `retirarDoAr`) — mas o item da
    // playlist NÃO passa por `onTap`: aqui o toque é `send` direto, porque
    // tocar numa linha da fila não pode REDEFINIR a fila para aquele item, que
    // é o que `onTap` faz para a biblioteca. Só a metade do desligamento é
    // compartilhada.
    row.addEventListener('click', (e) => {
      // `.row-slot` entrou na guarda na v1.4.27: a coluna do `⋮` emprestada ao
      // processo fica FORA da faixa, e sem ela um toque na lixeira da pergunta
      // cairia aqui — isto é, poria no ar a mídia que se está perguntando se
      // apaga.
      if (e.target.closest('.row-btn,.row-acoes,.row-slot')) return;
      if (noArAgora(item)) { retirarDoAr(item); return; }
      send(item.id);
    });
    playlistEl.appendChild(li);
  });
}

// ---- Biblioteca (Cronograma / Favoritos) ----
// ===== Bíblia: metadados, seleção (tabela periódica) e download =====

// Garante a lista de versões (pt_bible_version) e de livros (pt_bible_book) —
// baixadas na 1ª vez e cacheadas em state; offline reusa o cache. Silenciosa
// (uma falha de rede só mantém o que já houver). A seleção de livros/capítulos
// funciona mesmo sem isso (Bible.BOOKS é offline); versões/ids reais só são de
// fato necessários no download do capítulo.
async function ensureBibleMeta(force) {
  // versões
  if (!bibleVersions.length) bibleVersions = (await AVDB.getState('bibleVersions')) || [];
  if (!bibleVersions.length || force) {
    try {
      const fetched = await Bible.fetchVersions();
      if (fetched.length) { bibleVersions = fetched; await AVDB.setState('bibleVersions', fetched); }
    } catch (_) {}
  }
  // versão selecionada (padrão: Almeida Revista e Atualizada — ver
  // pickDefaultBibleVersion; senão a 1ª disponível)
  if (bibleVersionId == null) {
    const saved = await AVDB.getState('bibleVersion');
    bibleVersionId = (saved != null && bibleVersions.some((v) => v.id === saved))
      ? saved : pickDefaultBibleVersion(bibleVersions);
  }
  // livros (ids reais)
  if (!bibleBooksOnline) bibleBooksOnline = (await AVDB.getState('bibleBooks')) || null;
  if (!bibleBooksOnline || force) {
    try {
      const fetched = await Bible.fetchBooks();
      if (fetched.length) { bibleBooksOnline = fetched; await AVDB.setState('bibleBooks', fetched); }
    } catch (_) {}
  }
  // Completude offline de TODAS as versões (pra resumir na lista de seleção).
  // O próprio Set é o cache: versão que já está nele não volta ao IDB (uma
  // versão completa não "des-completa", e os downloads que completam uma já a
  // adicionam na hora — ver ensureBibleVersionDownloaded). As leituras que
  // restam saem em paralelo: são independentes, e em série este laço pagava
  // uma ida ao IDB por versão a cada entrada na aba.
  await Promise.all(bibleVersions
    .filter((v) => !bibleCompleteVersions.has(v.id))
    .map(async (v) => {
      if (await AVDB.getState('bibleComplete:' + v.id)) bibleCompleteVersions.add(v.id);
    }));
  if (bibliaAberta()) renderBible();
}

// Versão padrão: Almeida Revista e Atualizada (RA/ARA) quando existir no banco,
// senão a primeira disponível.
function pickDefaultBibleVersion(versions) {
  if (!versions.length) return null;
  const ra = versions.find((v) => /revista\s+e\s+atualizada|\bara\b|(^|\s)ra(\s|$)/i.test(v.name || ''));
  return (ra || versions[0]).id;
}

// Popup de seleção de versão (bottom-sheet) — a lista não fica mais toda
// exposta em chips; um botão com a versão atual abre esta lista.
function openBibleVerPopup() {
  renderBibleVerList();
  bibleVerPopupEl.classList.add('open');
}
function closeBibleVerPopup() { bibleVerPopupEl.classList.remove('open'); }
function renderBibleVerList() {
  bibleVerListEl.innerHTML = '';
  bibleVersions.forEach((v) => {
    const li = document.createElement('li');
    const row = document.createElement('div');
    row.className = 'row bible-ver-row' + (v.id === bibleVersionId ? ' selected' : '');
    // nome + status offline resumido (completa / baixando / —)
    const main = document.createElement('span'); main.className = 'bible-ver-main';
    const name = document.createElement('span'); name.className = 'row-name'; name.textContent = v.name;
    const st = document.createElement('span'); st.className = 'bible-ver-status';
    if (bibleCompleteVersions.has(v.id)) { st.textContent = '✓ Completa offline'; st.classList.add('done'); }
    else if (bibleDl && bibleDl.running && bibleDl.versionId === v.id) { st.textContent = 'Baixando ' + bibleDl.done + '/' + bibleDl.total + '…'; }
    else { st.textContent = 'Baixa ao usar'; }
    main.append(name, st);
    row.appendChild(main);
    if (v.id === bibleVersionId) { const chk = document.createElement('span'); chk.textContent = '✓'; chk.className = 'bible-ver-check'; row.appendChild(chk); }
    row.addEventListener('click', () => {
      closeBibleVerPopup();
      changeBibleVersion(v.id); // troca + recarrega o capítulo atual na nova versão
    });
    li.appendChild(row);
    bibleVerListEl.appendChild(li);
  });
}

// Entrada na aba Bíblia: garante os metadados e dispara o download da versão
// INTEIRA na 1ª vez (em segundo plano) — ver ensureBibleVersionDownloaded.
async function enterBibleTab() {
  // Armazenamento persistente (mesma proteção do sync de músicas/pastas): pede
  // ao browser para NÃO descartar a origin sob pressão de espaço — garante que
  // a Bíblia baixada (cache IDB em 'bible:<v>_<b>_<c>') sobreviva entre sessões.
  // persist() é da origin inteira (não por store) e idempotente.
  if (navigator.storage && navigator.storage.persist) navigator.storage.persist().catch(() => {});
  await ensureBibleMeta(false);
  if (bibleVersionId != null) ensureBibleVersionDownloaded(bibleVersionId);
}

// A BÍBLIA BASE DO APP, baixada sozinha na abertura.
//
// O download da versão INTEIRA só era disparado por alguém ENTRAR na aba
// Bíblia; quem nunca entrou ficava com o caminho sob demanda do
// `loadBibleChapter` — um capítulo por vez, com a rede da igreja no meio do
// culto como única rede. Agora o app garante UMA versão offline por conta
// própria, como já faz com os índices (`autoRefreshCollections`): o texto de
// 1189 capítulos é leve o bastante para vir inteiro, e vir inteiro é o que
// torna a Bíblia utilizável sem rede nenhuma.
//
// A versão é a que o app JÁ ESCOLHERIA (`pickDefaultBibleVersion`), nunca
// `bibleVersionId`, que é a escolha do OPERADOR: esta é a base que o app
// garante, não a preferência de quem opera. As duas convivem porque
// `ensureBibleVersionDownloaded` é resumível e idempotente.
//
// Fire-and-forget na init, e por isso os erros morrem aqui: uma falha de rede
// na abertura não pode borbulhar para o `init()`.
async function garantirBibliaBase() {
  try {
    // Mesma proteção do `enterBibleTab`, e agora ela é ainda mais devida: sem
    // ninguém abrir a aba, este é o único ponto que pede à origin para não ser
    // descartada sob pressão de espaço.
    if (navigator.storage && navigator.storage.persist) navigator.storage.persist().catch(() => {});
    await ensureBibleMeta(false);
    const base = pickDefaultBibleVersion(bibleVersions);
    if (base != null) await ensureBibleVersionDownloaded(base);
  } catch (_) {}
}

// Baixa a versão INTEIRA da Bíblia (todos os capítulos de todos os livros) na
// 1ª vez que ela é usada — em segundo plano, resumível (pula o que já está em
// cache), concorrência limitada (runLimited, 5). O texto de cada capítulo é
// leve (só versículos, sem mídia), então o volume total é modesto. O progresso
// (bibleDl) aparece na tela de livros; ao terminar sem falhas, marca
// state['bibleComplete:<v>'] pra não refazer. A leitura por capítulo
// (loadBibleChapter) continua funcionando sob demanda se o operador abrir um
// capítulo antes de o download em massa chegar nele.
async function ensureBibleVersionDownloaded(versionId) {
  if (versionId == null) return;
  // Já baixando esta versão, ou já completa: nada a fazer.
  if (bibleDl && bibleDl.running && bibleDl.versionId === versionId) return;
  if (bibleCompleteVersions.has(versionId)) return;
  if (await AVDB.getState('bibleComplete:' + versionId)) { bibleCompleteVersions.add(versionId); return; }
  await ensureBibleMeta(false); // garante os ids reais dos livros

  // Lista de todos os capítulos (livro × capítulo).
  const items = [];
  Bible.BOOKS.forEach((b, i) => {
    const bId = bibleBookId(i);
    // `bookName` só serve para a notificação mostrar "Gênesis 3" em vez de um id.
    for (let c = 1; c <= b.chapters; c++) items.push({ bId, chapter: c, bookName: b.name });
  });
  const total = items.length;

  // O que JÁ está em cache, numa transação só e sem ler valor nenhum. Antes
  // eram 1189 `getState` — 1189 transações desserializando o capítulo inteiro
  // só para testar existência —, refeitos a CADA entrada na aba sempre que a
  // flag `bibleComplete` não estivesse marcada.
  const prefix = 'bible:' + versionId + '_';
  let cached = null;
  try {
    cached = new Set((await AVDB.stateKeys(prefix)).map((k) => String(k).slice(prefix.length)));
  } catch (_) { /* sem getAllKeys (improvável): o teste volta a ser por capítulo */ }
  const missing = cached
    ? items.filter((it) => !cached.has(it.bId + '_' + it.chapter))
    : items;

  // Tudo em cache: marca a flag e encerra. Isso conserta o caso em que uma
  // única falha de rede num download anterior condenava a versão a revarrer
  // para sempre — a flag só era gravada com `failed === 0`, e nunca era
  // reavaliada depois.
  if (!missing.length) {
    await AVDB.setState('bibleComplete:' + versionId, true);
    bibleCompleteVersions.add(versionId);
    return;
  }

  let done = total - missing.length, failed = 0;
  // Falhas CONSECUTIVAS — o freio de quem varre 1189 capítulos sem rede.
  //
  // Enquanto a varredura só começava por alguém ENTRAR na aba Bíblia, insistir
  // até o fim era barato: havia um operador olhando. Com a varredura automática
  // na abertura (`garantirBibliaBase`, v5.242) o cenário mudou — um lançamento
  // offline, ou com o Wi-Fi da igreja sem uplink (que este projeto descreve
  // como o ambiente NORMAL), pagaria 1189 requisições fadadas ao erro, com
  // serviço em primeiro plano, wake lock e uma notificação contando até o fim,
  // a cada abertura. Vinte e cinco erros seguidos não são uma oscilação: são a
  // rede fora, e a resposta certa é parar e tentar no lançamento seguinte.
  //
  // Ele NÃO grava `bibleComplete` (o `failed` cresce), então a versão continua
  // pendente e a varredura é retomada de onde parou — que é exatamente o que
  // ela já fazia depois de qualquer interrupção.
  let seguidas = 0;
  // Sequência monotônica: cada invocação ganha a sua, e uma varredura superada
  // nunca mais volta a valer (ver o guard do worker abaixo). Trocar `bibleDl`
  // por si só não bastava — a igualdade de versão é reversível.
  const runSeq = ++bibleDlSeq;
  bibleDl = { versionId, total, done, running: true, seq: runSeq };
  refreshBibleDl();

  // 1189 capítulos: é o download mais longo do app e o que mais sofria com o
  // congelamento do processo ao minimizar.
  const notifId = bgTaskStart('Bíblia · ' + (bibleVersionName(versionId) || 'versão'), missing.length);
  // `bgTaskEnd` dentro do `withBgWork` — mesma ordem de syncGroup/syncCollection:
  // o `finally` de withBgWork roda primeiro e já limpa o registro de tarefas.
  await withBgWork(async () => {
   try {
    await runLimited(missing, NET_CONCURRENCY, async (it) => {
    // Guard por SEQUÊNCIA, não por igualdade de versão: o teste antigo
    // (`bibleDl.versionId !== versionId`) era reversível — trocar de versão e
    // VOLTAR fazia os workers da varredura antiga, ainda em voo, passarem no
    // teste de novo e retomarem em paralelo com a nova. Pior, a antiga
    // terminava primeiro e, como os capítulos que ela pulou saíam pelo
    // `return` sem contar falha, gravava `bibleComplete` sobre uma varredura
    // incompleta — flag persistida, versão nunca mais completada.
    if (!bibleDl || !bibleDl.running || bibleDl.seq !== runSeq) { failed++; return; }
    // A rede caiu (ver `seguidas`): o que resta conta como falha e sai sem
    // abrir requisição nenhuma.
    if (seguidas >= BIBLE_DL_DESISTE) { failed++; return; }
    const key = prefix + it.bId + '_' + it.chapter;
    const nome = (it.bookName || '') + ' ' + it.chapter;
    bgItemStart(notifId, nome);
    try {
      // Só quando não houve varredura de chaves (fallback): confere um a um.
      if (!cached && (await AVDB.getState(key))) { done++; return; }
      const vs = await Bible.fetchChapter(versionId, it.bId, it.chapter);
      if (vs.length) { await AVDB.setState(key, { verses: vs, syncedAt: Date.now() }); seguidas = 0; }
      else { failed++; seguidas++; }
    } catch (_) { failed++; seguidas++; }
    finally { bgItemEnd(notifId, nome); }
    done++;
    bgTaskStep(notifId, done - (total - missing.length));
    if (bibleDl && bibleDl.seq === runSeq) { bibleDl.done = done; refreshBibleDl(); }
    });
   } finally { bgTaskEnd(notifId); }
  });

  if (bibleDl && bibleDl.seq === runSeq) {
    bibleDl.running = false;
    if (failed === 0) { await AVDB.setState('bibleComplete:' + versionId, true); bibleCompleteVersions.add(versionId); }
    refreshBibleDl();
  }
}

// O status offline/progresso do download aparece SÓ dentro do popup de seleção
// de versão (`.bible-ver-status` por versão) — não disputa espaço com a leitura.
// Enquanto o download roda, re-renderiza a lista se o popup estiver aberto.
function refreshBibleDl() {
  if (bibleVerPopupEl.classList.contains('open')) renderBibleVerList();
}

// Ordem das telas da Bíblia (pra direção do slide de transição).
// Capítulo e versículo convivem numa tela só (`chapters`, dividida ao meio na
// vertical): escolher o capítulo e o versículo é um gesto só, e voltar da
// leitura mostra os dois de uma vez, marcados na grade.
const BIBLE_SCREENS = ['books', 'chapters', 'reading'];

// Navega entre as telas da Bíblia sem recarregar o IDB inteiro (só re-render):
// guarda o scroll, volta ao topo e faz um leve slide direcional (fundo → frente
// desliza da direita; voltar, da esquerda).
function gotoBibleScreen(screen) {
  const dir = BIBLE_SCREENS.indexOf(screen) >= BIBLE_SCREENS.indexOf(bibleScreen) ? 1 : -1;
  bibleScreen = screen;
  renderBible();
  bibleBodyEl.scrollTop = 0;
  // O DESLIZE FICOU, e agora ele é da FOLHA (v1.5.0). Ele nasceu como a
  // animação genérica da troca de ABA e a Bíblia pegou carona nela; com a faixa
  // de abas fora, o único movimento lateral que sobrou no app é este — a
  // navegação DENTRO da Bíblia, que é para onde ele sempre apontou.
  deslizarNaFolha(bibleBodyEl, dir);
}

function renderBible() {
  const wrap = document.createElement('div');
  // A tela de livros preenche a altura disponível (grade compacta, sem scroll);
  // as demais rolam normalmente se precisarem (ex.: Salmos, 150 capítulos).
  // Todas as telas preenchem a altura disponível e cabem sem scroll (ver
  // .bible-wrap em controle.css).
  wrap.className = 'bible-wrap';
  if (bibleScreen === 'chapters') renderBibleChapters(wrap);
  else if (bibleScreen === 'reading') renderBibleReading(wrap);
  else renderBibleBooks(wrap);
  // O HOST É O DA FOLHA desde a v1.5.0 — era o `#library`, o mesmo `<ul>` do
  // Cronograma, e por isso `renderLibrary` tinha um desvio por aba no topo. Com
  // host próprio, as duas listas deixam de disputar um nó.
  bibleBodyEl.innerHTML = '';
  bibleBodyEl.appendChild(wrap);
  // O voltar é da NAVEGAÇÃO INTERNA (livros → capítulos → leitura), e por isso
  // ele mora na barra da folha e não no cabeçalho do app: na raiz não há para
  // onde voltar que não seja fechar, e fechar é o ✕ ao lado.
  if (bibleBackEl) bibleBackEl.hidden = bibleScreen === 'books';
}

function bibleCell(sym, opts) {
  const cell = document.createElement('button');
  cell.type = 'button';
  cell.className = 'bible-cell' + (opts && opts.cls ? ' ' + opts.cls : '') + (opts && opts.active ? ' active' : '');
  const s = document.createElement('span'); s.className = 'bible-cell-sym'; s.textContent = sym;
  cell.appendChild(s);
  if (opts && opts.name) {
    const nm = document.createElement('span'); nm.className = 'bible-cell-name'; nm.textContent = opts.name;
    cell.appendChild(nm);
  }
  return cell;
}

function renderBibleBooks(wrap) {
  // (O seletor de versão e o status de download saíram daqui — moram na tela de
  // leitura, dando mais espaço para a grade de livros. Ver renderBibleReading.)
  const grid = document.createElement('div'); grid.className = 'bible-grid bible-grid--books';
  Bible.BOOKS.forEach((b, i) => {
    // Só a abreviação (sem o nome completo) — fonte maior, ver .bible-grid--books.
    const cell = bibleCell(b.abbr, { cls: 'bg-' + b.g });
    cell.title = b.name;
    cell.addEventListener('click', () => { bibleSel = { bookIdx: i, chapter: 0 }; gotoBibleScreen('chapters'); });
    grid.appendChild(cell);
  });
  wrap.appendChild(grid);
}

// Capítulo e versículo na MESMA tela, dividida ao meio na vertical: em cima a
// grade de capítulos, embaixo a de versículos do capítulo escolhido. O nome do
// livro fica em destaque no topo — sem ele, uma tela só de números não diz em
// que livro o operador está.
//
// As duas grades marcam a seleção atual (`.active`), então **voltar da leitura
// mostra de imediato o capítulo E o versículo que estão no ar**, sem o
// operador ter que se localizar.
function renderBibleChapters(wrap) {
  const book = Bible.BOOKS[bibleSel.bookIdx];
  if (!book) { gotoBibleScreen('books'); return; }

  const head = document.createElement('div'); head.className = 'bible-book-head';
  const nm = document.createElement('span'); nm.className = 'bible-book-name'; nm.textContent = book.name;
  head.appendChild(nm);
  if (bibleSel.chapter) {
    const ref = document.createElement('span'); ref.className = 'bible-book-ref';
    ref.textContent = 'Capítulo ' + bibleSel.chapter;
    head.appendChild(ref);
  }
  wrap.appendChild(head);

  const split = document.createElement('div'); split.className = 'bible-split';

  // ---- metade de cima: capítulos ----
  const top = document.createElement('div'); top.className = 'bible-half';
  const cGrid = document.createElement('div'); cGrid.className = 'bible-grid bible-grid--num bible-grid--chapters';
  for (let c = 1; c <= book.chapters; c++) {
    const cell = bibleCell(String(c), { cls: 'bible-cell--num', active: bibleSel.chapter === c });
    cell.addEventListener('click', () => {
      if (bibleSel.chapter === c) return;
      bibleSel.chapter = c;
      renderLibrary();          // marca o capítulo já; a metade de baixo mostra "Baixando…"
      loadBibleChapter();
    });
    cGrid.appendChild(cell);
  }
  top.appendChild(cGrid);

  // ---- metade de baixo: versículos ----
  const bottom = document.createElement('div'); bottom.className = 'bible-half';
  bottom.appendChild(bibleVersesPane());

  split.append(top, bottom);
  wrap.appendChild(split);
  requestAnimationFrame(() => {
    scrollActiveIntoView(cGrid);
    scrollActiveIntoView(bottom.querySelector('.bible-grid--verses'));
  });
}

// Rola cada grade até a célula marcada. As duas podem ser longas (Salmos tem
// 150 capítulos, o 119 tem 176 versículos), e voltar da leitura tem que
// mostrar onde se está sem o operador procurar.
function scrollActiveIntoView(grid) {
  const active = grid && grid.querySelector('.bible-cell.active');
  if (active && active.scrollIntoView) active.scrollIntoView({ block: 'center' });
}

// A metade de baixo: grade de versículos do capítulo selecionado, ou o estado
// em que ela está (nada escolhido / baixando / erro / capítulo vazio).
function bibleVersesPane() {
  const note = (text, err) => {
    const n = document.createElement('div');
    n.className = 'bible-note' + (err ? ' err' : '');
    n.textContent = text;
    return n;
  };
  if (!bibleSel.chapter) return note('Nenhum capítulo selecionado.');
  if (bibleChapterLoading) return note('Baixando versículos…');
  if (bibleChapterError) return note(bibleChapterError, true);
  const verses = bibleChapterData && bibleChapterData.verses ? bibleChapterData.verses : [];
  if (!verses.length) return note('Nenhum versículo neste capítulo.');

  const onThisChapter = bibleSession
    && bibleSession.bookIdx === bibleSel.bookIdx && bibleSession.chapter === bibleSel.chapter;
  const grid = document.createElement('div'); grid.className = 'bible-grid bible-grid--num bible-grid--verses';
  verses.forEach((v, i) => {
    const cell = bibleCell(String(v.n), {
      cls: 'bible-cell--num',
      active: onThisChapter && bibleSession.idx === i,
    });
    cell.addEventListener('click', () => startBibleReading(i));
    grid.appendChild(cell);
  });
  return grid;
}

// Baixa (ou lê do cache) o texto do capítulo selecionado. Cacheado em
// state 'bible:<versao>_<livro>_<capitulo>' (baixado na 1ª vez que for usado).
async function loadBibleChapter() {
  const seq = ++bibleLoadSeq;
  bibleChapterData = null; bibleChapterError = ''; bibleChapterLoading = true;
  if (bibliaAberta()) renderBible();
  await ensureBibleMeta(false);
  if (seq !== bibleLoadSeq) return;
  const vId = bibleVersionId;
  if (vId == null) {
    bibleChapterLoading = false;
    bibleChapterError = 'Nenhuma versão da Bíblia disponível. Conecte-se à internet uma vez para baixá-la.';
    if (bibliaAberta()) renderBible();
    return;
  }
  const bId = bibleBookId(bibleSel.bookIdx);
  const key = 'bible:' + vId + '_' + bId + '_' + bibleSel.chapter;
  let cached = await AVDB.getState(key);
  if (!cached || !cached.verses || !cached.verses.length) {
    try {
      const vs = await Bible.fetchChapter(vId, bId, bibleSel.chapter);
      if (!vs.length) throw new Error('vazio');
      cached = { verses: vs, syncedAt: Date.now() };
      await AVDB.setState(key, cached);
    } catch (_) {
      if (seq !== bibleLoadSeq) return;
      bibleChapterLoading = false;
      bibleChapterError = (navigator.onLine === false)
        ? 'Sem internet — não foi possível baixar este capítulo.'
        : 'Não foi possível baixar este capítulo. Tente novamente.';
      if (bibliaAberta()) renderBible();
      return;
    }
  }
  if (seq !== bibleLoadSeq) return;
  bibleChapterData = cached;
  bibleChapterLoading = false;
  if (bibliaAberta() && bibleScreen === 'chapters') renderBible();
}

// Inicia a leitura a partir do versículo `i` (índice na lista do capítulo):
// define a sessão e abre a tela de leitura — SEM exibir ainda (o texto só é
// projetado depois que o operador toca no versículo central; ver
// renderBibleReading / activateBibleVerse).
function startBibleReading(i) {
  if (!bibleChapterData || !bibleChapterData.verses.length) return;
  clearMsgSession(); // só um texto manual por vez (Bíblia × Mensagem)
  const book = Bible.BOOKS[bibleSel.bookIdx];
  bibleSession = {
    versionId: bibleVersionId,
    bookIdx: bibleSel.bookIdx,
    bookId: bibleBookId(bibleSel.bookIdx),
    bookName: book.name,
    chapter: bibleSel.chapter,
    verses: bibleChapterData.verses,
    idx: i,
    projecting: false,   // ainda não exibido; ativa ao tocar o central
  };
  bibleScreen = 'reading';
  renderListTitle();
  bibleRenderReading();
  deslizarNaFolha(bibleBodyEl, 1); // desliza pra frente (verses → reading)
}

// Define o versículo central da leitura. Se a visualização já estiver ativa,
// EXIBE o novo versículo automaticamente; senão, só move o central na tela
// (sem projetar) — é o gate pedido: navegar entre anterior/próximo antes de
// ativar não mostra nada no telão.
function bibleSetIdx(idx) {
  const s = bibleSession;
  if (!s || idx < 0 || idx >= s.verses.length) return;
  s.idx = idx;
  if (s.projecting) projectBibleVerse(idx);
  else { renderNowPlaying(); renderSlideNav(); bibleRenderReading(); }
}

// O toque no versículo CENTRAL alterna a exibição pública: exibe se está
// fora do ar, tira do ar se está exibindo. É o mesmo gesto nos dois sentidos
// — quem acabou de projetar um versículo tem o dedo exatamente onde precisa
// para tirá-lo do telão, sem procurar outro controle.
//
// Tirar do ar NÃO encerra a sessão de leitura (diferente do stop ⏹): a
// seleção, o capítulo e o versículo central continuam onde estavam, e um
// novo toque volta a exibir. É a diferença entre "esconder" e "sair".
function toggleBibleVerse() {
  const s = bibleSession;
  if (!s) return;
  if (s.projecting) hideBibleVerse();
  else projectBibleVerse(s.idx);
}

// Tira a Escritura do telão mantendo a sessão viva.
function hideBibleVerse() {
  const s = bibleSession;
  if (!s || !s.projecting) return;
  s.projecting = false;
  // `text-hide` encerra só a Camada de Texto — um áudio de fundo, se houver,
  // segue tocando (ver "Independência do áudio" na arquitetura da camada).
  cmd({ type: 'text-hide' });
  renderControls();
  renderNowPlaying();
  renderSlideNav();
  // A LINHA DA CENA SÓ SE REPINTA POR `marcarNoAr` — e nenhum dos irmãos acima
  // toca em lista: `renderControls`/`renderNowPlaying`/`renderSlideNav` cuidam do
  // transporte, `refreshDiversos` da folha de Ferramentas. Sem esta chamada o
  // `<li>` do Cronograma fica com a classe `no-ar` e o selo "● No ar" sobre um
  // telão em wallpaper, e NÃO se conserta sozinho: o outro caminho que chama
  // `marcarNoAr` é o `display-status`, que o telão só emite com MÍDIA — e a
  // cena de roteiro que mais usa estes `hide*` (cronômetro, sorteio) é
  // justamente a que não tem mídia nenhuma por baixo. Todo `hide*` precisa
  // dela; `hideVisualSobre` já a tinha.
  marcarNoAr();
  bibleRenderReading();
}

// Projeta o versículo de índice `idx` da sessão atual (Display + preview).
// Sempre marca a sessão como "exibindo" (projecting) — é o ato de mostrar.
function projectBibleVerse(idx) {
  const s = bibleSession;
  if (!s || idx < 0 || idx >= s.verses.length) return;
  soUmProvedorDeTexto('bible');   // cartão único: um provedor por vez
  s.idx = idx;
  s.projecting = true;
  const v = s.verses[idx];
  const ref = s.bookName + ' ' + s.chapter + ':' + v.n;
  view = 'visual';   // projetar a Escritura sempre revela (desliga o wallpaper)
  persistCurrent();
  // Camada de texto unificada: modo 'verse' (sublinha = referência dourada).
  cmd({ type: 'text', mode: 'verse', main: v.text, sub: ref, view: 'visual' });
  renderControls();
  renderNowPlaying();
  renderSlideNav();
  bibleRenderReading();
}

// Re-render só da tela de leitura (destaque do versículo central), preservando
// o scroll — usado tanto ao projetar quanto ao só mover o central.
function bibleRenderReading() {
  if (bibliaAberta() && (bibleScreen === 'reading' || bibleScreen === 'chapters')) {
    const sp = bibleBodyEl.scrollTop;
    renderBible();
    bibleBodyEl.scrollTop = sp;
  }
}

function bibleVersionName(id) {
  const v = bibleVersions.find((x) => x.id === id);
  return v ? v.name : '';
}

// Sigla da versão, para caber no seletor ao lado de livro/capítulo/versículo.
// Nomes como "Almeida Revista e Atualizada" ocupam a linha inteira; a sigla
// que todo mundo já usa (ARA) diz a mesma coisa em três letras. As regras, em
// ordem: um acrônimo entre parênteses no próprio nome é a melhor resposta
// possível; um nome de uma palavra já é a sigla; senão, as iniciais das
// palavras significativas (ignorando "e", "de", "na"…).
const BIBLE_ABBR_STOP = new Set(['e', 'de', 'da', 'do', 'das', 'dos', 'na', 'no', 'em', 'a', 'o', 'as', 'os', 'para', 'com']);
function bibleVersionAbbr(id) {
  const name = bibleVersionName(id);
  if (!name) return 'Versão';
  const paren = name.match(/\(([A-Za-zÀ-ÿ0-9]{2,6})\)/);
  if (paren) return paren[1].toUpperCase();
  const words = name.split(/[\s\-–]+/).filter(Boolean).filter((w) => !BIBLE_ABBR_STOP.has(w.toLowerCase()));
  if (!words.length) return name.slice(0, 5).toUpperCase();
  if (words.length === 1) return words[0].slice(0, 5).toUpperCase();
  return words.map((w) => w[0]).join('').toUpperCase().slice(0, 5);
}

// Troca a versão da Bíblia (do seletor na tela de leitura). Recarrega o
// capítulo atual na nova versão, mantendo o versículo; reexibe se estava
// exibindo.
async function changeBibleVersion(id) {
  if (id == null || bibleVersionId === id) return;
  bibleVersionId = id;
  bibleAdjCache = {}; // vizinhos em cache eram da versão antiga
  await AVDB.setState('bibleVersion', id);
  ensureBibleVersionDownloaded(id);
  if (!bibleSession) { renderLibrary(); return; }
  const s = bibleSession;
  let verses;
  try { verses = await fetchBibleChapterCached(id, s.bookIdx, s.chapter); }
  catch (_) { renderLibrary(); return; }
  if (bibleSession !== s) return;
  s.versionId = id;
  s.verses = verses;
  s.idx = Math.min(s.idx, verses.length - 1);
  // INVALIDA qualquer `loadBibleChapter` em voo: sem isto, um capítulo lento
  // pedido antes desta troca voltava DEPOIS, passava na guarda de sequência
  // (que não havia mudado) e sobrescrevia `bibleChapterData` com os versículos
  // do capítulo/versão antigos sob o rótulo dos novos — e `startBibleReading`
  // monta a sessão a partir daí, projetando o versículo errado com a
  // referência certa. É o mesmo papel do `loadSeq` do stage.
  ++bibleLoadSeq;
  bibleChapterData = { verses };
  // …e zera o estado da grade: uma falha antiga ("Não foi possível baixar
  // este capítulo") continuava na metade de baixo da tela mesmo com o
  // capítulo novo já carregado e no ar.
  bibleChapterError = ''; bibleChapterLoading = false;
  if (s.projecting) projectBibleVerse(s.idx);
  else bibleRenderReading();
}

// Referência do capítulo vizinho (cruza para o próximo/anterior LIVRO nos
// extremos). null = fim/início da Bíblia.
function nextChapterRef(bookIdx, chapter) {
  const b = Bible.BOOKS[bookIdx];
  if (chapter < b.chapters) return { bookIdx, chapter: chapter + 1 };
  if (bookIdx < Bible.BOOKS.length - 1) return { bookIdx: bookIdx + 1, chapter: 1 };
  return null;
}
function prevChapterRef(bookIdx, chapter) {
  if (chapter > 1) return { bookIdx, chapter: chapter - 1 };
  if (bookIdx > 0) return { bookIdx: bookIdx - 1, chapter: Bible.BOOKS[bookIdx - 1].chapters };
  return null;
}

// Lê (do cache) ou baixa o texto de um capítulo — [{ n, text }]. Lança se não
// houver cache nem rede.
async function fetchBibleChapterCached(versionId, bookIdx, chapter) {
  const bId = bibleBookId(bookIdx);
  const key = 'bible:' + versionId + '_' + bId + '_' + chapter;
  let cached = await AVDB.getState(key);
  if (!cached || !cached.verses || !cached.verses.length) {
    const vs = await Bible.fetchChapter(versionId, bId, chapter);
    if (!vs.length) throw new Error('vazio');
    cached = { verses: vs, syncedAt: Date.now() };
    await AVDB.setState(key, cached);
  }
  return cached.verses;
}

// Move a sessão de leitura para outro capítulo (cruza livro nos extremos),
// baixando o texto se necessário.
// `want`: 'first' | 'last' | um índice (podendo ser NEGATIVO, contado a partir
// do fim — é como um salto de -2 que estourou o começo do capítulo chega aqui).
async function bibleGotoChapter(bookIdx, chapter, want) {
  const s = bibleSession;
  if (!s) return;
  let verses;
  try { verses = await fetchBibleChapterCached(s.versionId, bookIdx, chapter); }
  catch (_) { return; } // sem cache e sem rede: fica onde está
  if (!bibleSession || bibleSession !== s) return; // a sessão trocou durante o await
  const book = Bible.BOOKS[bookIdx];
  const wasProjecting = s.projecting;
  let idx;
  if (want === 'last') idx = verses.length - 1;
  else if (typeof want === 'number') idx = want < 0 ? verses.length + want : want;
  else idx = 0;
  idx = Math.max(0, Math.min(verses.length - 1, idx));
  bibleSession = {
    versionId: s.versionId, bookIdx, bookId: bibleBookId(bookIdx),
    bookName: book.name, chapter, verses, idx,
    projecting: wasProjecting,
  };
  // A seleção acompanha a leitura (grid de versículos e título seguem o capítulo).
  bibleSel = { bookIdx, chapter };
  // A MESMA INVALIDAÇÃO do `changeBibleVersion`, e pelo mesmo motivo escrito
  // lá: este é o OUTRO ponto que escreve `bibleChapterData` fora do
  // `loadBibleChapter`. Sem o bump, um capítulo lento pedido antes desta
  // navegação volta DEPOIS, passa na guarda de sequência (que não mudou) e
  // sobrescreve a grade com os versículos do capítulo antigo sob o rótulo do
  // novo. E sem zerar o par erro/carregando, um "Não foi possível baixar este
  // capítulo" de antes seguia na metade de baixo da tela com o capítulo novo
  // já no ar.
  ++bibleLoadSeq;
  bibleChapterError = ''; bibleChapterLoading = false;
  bibleChapterData = { verses };
  renderListTitle();
  // Exibe o novo versículo só se já estava exibindo; senão apenas move o central.
  if (wasProjecting) projectBibleVerse(bibleSession.idx);
  else { renderNowPlaying(); renderSlideNav(); bibleRenderReading(); }
}

// Passa/volta um versículo (reusa os botões de slide). No fim do último
// versículo do capítulo, pula para o 1º do capítulo seguinte (indo para o
// próximo LIVRO, se preciso); no início, volta para o último do anterior.
// Respeita o gate: se ainda não ativou a visualização, só move o central.
async function bibleStep(delta) {
  const s = bibleSession;
  if (!s) return;
  const t = s.idx + delta;
  if (t >= 0 && t < s.verses.length) { bibleSetIdx(t); return; }
  // Cruzando o limite: `want` leva o quanto sobrou do salto, para um pulo de
  // +2 no último versículo cair no segundo do capítulo seguinte.
  if (delta > 0) {
    const nx = nextChapterRef(s.bookIdx, s.chapter);
    if (nx) await bibleGotoChapter(nx.bookIdx, nx.chapter, t - s.verses.length);
  } else {
    const pv = prevChapterRef(s.bookIdx, s.chapter);
    if (pv) await bibleGotoChapter(pv.bookIdx, pv.chapter, t);
  }
}

// Cache dos capítulos VIZINHOS (só pra preview do anterior/próximo que cruza o
// limite do capítulo/livro), por `<versao>_<livroIdx>_<capitulo>`. Limpo ao
// trocar de versão / encerrar a leitura.
let bibleAdjCache = {};
let bibleAdjSeq = 0;
// Capítulos vizinhos EM VOO, por chave. A dedupe é pela REQUISIÇÃO PENDENTE, e
// não pelo cache já preenchido: `renderBibleReading` chama `ensureAdjLoaded` uma
// vez por seção e, no ÚLTIMO versículo do capítulo, os deltas +1 e +2 cruzam
// para o MESMO capítulo seguinte. As duas chamadas são SÍNCRONAS dentro do
// mesmo render, então as duas passam pela guarda de cache antes de qualquer uma
// preenchê-lo — saíam duas requisições idênticas e duas gravações do mesmo
// `state`, a cada `bibleRenderReading()` (isto é, a cada passo de versículo).
// De brinde, resolve o efeito colateral do `bibleAdjSeq`: com uma chamada só,
// `seq === bibleAdjSeq` e o redesenho sempre acontece — antes, quem redesenhava
// era a SEGUNDA, e uma falha dela deixava "…" na tela sobre um capítulo que a
// primeira já tinha posto em cache.
const bibleAdjEmVoo = new Map();

// Info do versículo vizinho (delta = -1 anterior, +1 próximo). Dentro do
// capítulo: o versículo direto. No limite: cruza pro capítulo/livro vizinho
// (verso já em cache do vizinho, se houver). null = início/fim da Bíblia.
function bibleAdjacentVerse(delta) {
  const s = bibleSession;
  const t = s.idx + delta;
  if (t >= 0 && t < s.verses.length) {
    return { bookIdx: s.bookIdx, chapter: s.chapter, bookName: s.bookName, v: s.verses[t], cross: false };
  }
  const ref = delta > 0 ? nextChapterRef(s.bookIdx, s.chapter) : prevChapterRef(s.bookIdx, s.chapter);
  if (!ref) return null; // início/fim da Bíblia
  const book = Bible.BOOKS[ref.bookIdx];
  const cachedKey = s.versionId + '_' + ref.bookIdx + '_' + ref.chapter;
  const cached = bibleAdjCache[cachedKey];
  // Índice DENTRO do capítulo vizinho: com mais de um versículo de preview à
  // frente, um `delta` de +2 no último versículo cai no SEGUNDO do capítulo
  // seguinte, não no primeiro. `t` já é o índice absoluto que estourou.
  let v = null;
  if (cached && cached.length) {
    const j = delta > 0 ? (t - s.verses.length) : (cached.length + t);
    v = cached[Math.max(0, Math.min(cached.length - 1, j))];
  }
  return {
    bookIdx: ref.bookIdx, chapter: ref.chapter, bookName: book.name, v,
    cross: true, crossBook: ref.bookIdx !== s.bookIdx, chapterRef: ref,
  };
}

// Baixa/lê o capítulo vizinho pra preencher a preview do anterior/próximo que
// cruza limite, e re-renderiza a leitura quando chega.
async function ensureAdjLoaded(ref) {
  const s = bibleSession;
  if (!s) return;
  const key = s.versionId + '_' + ref.bookIdx + '_' + ref.chapter;
  if (bibleAdjCache[key]) return;
  if (bibleAdjEmVoo.has(key)) return bibleAdjEmVoo.get(key);
  const seq = ++bibleAdjSeq;
  const p = (async () => {
    try {
      bibleAdjCache[key] = await fetchBibleChapterCached(s.versionId, ref.bookIdx, ref.chapter);
    } catch (_) {
      return;
    } finally {
      // Depois da gravação no cache, nunca antes: solto cedo, um chamador do
      // mesmo tick não veria nem o voo nem o cache e pediria de novo.
      bibleAdjEmVoo.delete(key);
    }
    if (seq === bibleAdjSeq && bibleSession && bibliaAberta() && bibleScreen === 'reading') {
      bibleRenderReading();
    }
  })();
  bibleAdjEmVoo.set(key, p);
  return p;
}

// Tela de LEITURA: seletor de versão + status offline no topo, versículo
// anterior / atual / próximo empilhados (o anterior/próximo mostram também o
// salto pro capítulo/livro vizinho nos limites, com indicador da mudança), e a
// referência atual num botão que volta para a seleção de livros. Toque no
// CENTRAL ativa a exibição; toque no anterior/próximo move pro central (só
// exibe automaticamente depois de ativado — ver bibleSetIdx).
function renderBibleReading(wrap) {
  const s = bibleSession;
  if (!s) { gotoBibleScreen('books'); return; }
  const read = document.createElement('div'); read.className = 'bible-read';

  // delta: -1 (anterior) | 0 (atual) | +1 (próximo)
  const mkSection = (delta, role) => {
    const sec = document.createElement('div');
    const info = delta === 0
      ? { bookName: s.bookName, chapter: s.chapter, v: s.verses[s.idx], cross: false }
      : bibleAdjacentVerse(delta);
    if (!info) { // início/fim da Bíblia
      sec.className = 'bible-vsec ' + role + ' empty';
      const t = document.createElement('div'); t.className = 'bible-vsec-text';
      t.textContent = delta > 0 ? 'Fim da Bíblia' : 'Início da Bíblia';
      sec.appendChild(t);
      return sec;
    }
    const live = role === 'cur' && s.projecting;
    sec.className = 'bible-vsec ' + role + (live ? ' live' : '') + (info.cross ? ' cross' : '');
    // Indicador de mudança de capítulo/livro (antes de selecionar).
    if (info.cross) {
      const badge = document.createElement('div'); badge.className = 'bible-vsec-cross';
      const arrow = delta > 0 ? '▸ ' : '◂ ';
      const label = info.crossBook
        ? (delta > 0 ? 'Livro seguinte: ' : 'Livro anterior: ') + info.bookName + ' ' + info.chapter
        : 'Capítulo ' + info.chapter;
      badge.textContent = arrow + label;
      sec.appendChild(badge);
    }
    const ref = document.createElement('div'); ref.className = 'bible-vsec-ref';
    ref.textContent = (live ? '● No ar · ' : '') + info.bookName + ' ' + info.chapter + (info.v ? ':' + info.v.n : '');
    const txt = document.createElement('div'); txt.className = 'bible-vsec-text';
    txt.textContent = info.v ? info.v.text : (info.cross ? '…' : '');
    sec.append(ref, txt);
    sec.addEventListener('click', () => {
      if (role === 'cur') toggleBibleVerse(); // exibe / tira do ar
      else bibleStep(delta); // navega (cruza capítulo/livro nos limites)
    });
    if (info.cross && !info.v && info.chapterRef) ensureAdjLoaded(info.chapterRef);
    return sec;
  };
  // Um versículo atrás e DOIS à frente: sobrava espaço na tela, e ler adiante
  // é o que o operador faz — ele precisa saber o que vem para acompanhar a
  // leitura, não o que já passou.
  read.appendChild(mkSection(-1, 'adj'));
  read.appendChild(mkSection(0, 'cur'));
  read.appendChild(mkSection(1, 'adj'));
  read.appendChild(mkSection(2, 'adj'));

  // Rodapé: um controle segmentado só, com as QUATRO coordenadas do que está
  // sendo lido — livro · capítulo · versículo · versão —, cada uma levando ao
  // seu próprio seletor. A versão entra pela SIGLA (ver bibleVersionAbbr):
  // "Almeida Revista e Atualizada" ocupava a linha inteira e empurrava a
  // referência para baixo. Antes a referência era um botão só, que sempre
  // voltava à grade de livros: trocar só o capítulo custava passar pela
  // seleção de livro de novo. Capítulo e versículo levam à mesma tela porque
  // as duas grades convivem nela (ver "Seleção em tabela periódica").
  //
  // A VERSÃO É A ÚLTIMA (v5.309), a pedido do operador. As três primeiras são
  // a referência que se lê em voz alta, na ordem em que ela é dita e na ordem
  // em que o operador acabou de escolhê-las (livro → capítulo → versículo); a
  // versão não é coordenada do texto, é em que edição ele está sendo lido, e
  // trocá-la é a decisão mais rara das quatro. À frente ela abria a barra por
  // uma sigla de três letras e empurrava o nome do livro — o único campo de
  // largura imprevisível, e o que diz onde a leitura está — para as
  // reticências antes de qualquer outro.
  const foot = document.createElement('div'); foot.className = 'bible-read-foot';
  const v = s.verses[s.idx];
  const nav = document.createElement('div'); nav.className = 'bible-ref-nav';
  const part = (label, value, onClick, cls) => {
    const b = document.createElement('button'); b.type = 'button';
    b.className = 'bible-ref-part' + (cls ? ' ' + cls : '');
    const l = document.createElement('span'); l.className = 'bible-ref-label'; l.textContent = label;
    const t = document.createElement('span'); t.className = 'bible-ref-value'; t.textContent = value;
    b.append(l, t);
    b.addEventListener('click', onClick);
    nav.appendChild(b);
  };
  // A seleção acompanha a leitura antes de abrir a grade, senão ela abriria no
  // que o operador escolheu por último, não no que está no ar.
  const goto = (screen) => () => {
    bibleSel = { bookIdx: s.bookIdx, chapter: s.chapter };
    gotoBibleScreen(screen);
  };
  // CADA PÍLULA VESTE A GRADE QUE ELA ABRE (v1.3.14) — ver `.bible-ref-part` no
  // CSS. A do LIVRO leva a classe do GRUPO CANÔNICO dele, a mesma que a célula
  // daquele livro tem no mosaico (`'bg-' + b.g`, em `renderBibleBooks`): a
  // pílula é a amostra da tela seguinte, não mais um botão genérico. Grupo
  // desconhecido não quebra nada — sem a classe, ela fica sem tinta e a faixa
  // continua transparente.
  const grupo = Bible.BOOKS[s.bookIdx] && Bible.BOOKS[s.bookIdx].g;
  part('Livro', s.bookName, goto('books'),
    'bible-ref-part--book' + (grupo ? ' bg-' + grupo : ''));
  part('Capítulo', String(s.chapter), goto('chapters'), 'bible-ref-part--cap');
  part('Versículo', String(v.n), goto('chapters'), 'bible-ref-part--vers');
  if (bibleVersions.length) part('Versão', bibleVersionAbbr(bibleVersionId), openBibleVerPopup, 'bible-ref-part--edic');
  foot.appendChild(nav);
  // GUARDAR A REFERÊNCIA (v5.103). Até aqui a leitura bíblica era uma coisa do
  // MOMENTO: o versículo da pregação de domingo tinha de ser reencontrado ao
  // vivo, navegando livro → capítulo → versículo enquanto o pregador falava. As
  // duas ações abaixo o transformam num item — no roteiro do culto (na ordem
  // certa, entre o hino e o aviso) ou nos favoritos (o Salmo 23 que volta toda
  // semana). O que é guardado é a REFERÊNCIA, não o texto: trocar de versão
  // depois continua valendo, e nada do texto da Escritura é duplicado no banco.
  // SÓ ÍCONE, e NA MESMA LINHA da referência (v5.109): com os rótulos, as duas
  // ações não cabiam ao lado dos quatro campos e ocupavam uma segunda faixa —
  // altura tirada da leitura, que é o conteúdo desta tela. São os mesmos dois
  // símbolos que a linha da lista e a barra de seleção já usam para estas
  // mesmas duas ações; onde eles se repetem, o rótulo não acrescenta nada.
  const acoes = document.createElement('div'); acoes.className = 'bible-read-acoes';
  acoes.append(
    cueSaveBtn(ICON.cronoAdd, 'Adicionar ao Cronograma', (b) => salvarVersiculo('imports', b)),
    cueSaveBtn(ICON.star, 'Favoritar', (b) => salvarVersiculo('favs', b)),
  );
  foot.appendChild(acoes);
  read.appendChild(foot);
  wrap.appendChild(read);
}

// O versículo em leitura vira uma cena de roteiro. O nome é a própria
// referência — numa lista de culto, "Salmo 23:1" diz tudo o que precisa dizer.
async function salvarVersiculo(destino, btn) {
  const s = bibleSession;
  if (!s) return;
  const v = s.verses[s.idx];
  if (!v) return;
  const nome = s.bookName + ' ' + s.chapter + ':' + v.n;
  const rec = await criarCue('verse', {
    versionId: s.versionId, bookIdx: s.bookIdx, chapter: s.chapter, verse: v.n,
  }, nome, destino, btn);
  // O aviso vem do `criarCue` — inclusive o "já está nos favoritos", que é o
  // que impede o operador de marcar o mesmo versículo duas vezes.
  if (!rec) return;
}

// Encerra o modo de leitura bíblica (quando uma mídia comum assume, ou stop).
function clearBibleSession() {
  if (!bibleSession) return;
  bibleSession = null;
  bibleAdjCache = {};
  // A tela de leitura depende da sessão: sem ela, volta pra seleção.
  if (bibleScreen === 'reading') bibleScreen = 'chapters';
  renderSlideNav();
  renderNowPlaying();
  if (bibliaAberta()) renderBible();
}

// ===== Mensagens: lista, projeção e navegação =====
function clearMsgSession() {
  if (!msgSession) return;
  msgSession = null;
  renderSlideNav();
  renderNowPlaying();
  refreshDiversos();
}
// ===== CENAS DE ROTEIRO (`kind: 'cue'`) =====
//
// Um cue é um item de lista que aponta para uma CENA em vez de para bytes —
// contagem regressiva, leitura bíblica, aviso, letra sem música. Três
// propriedades desenham o resto:
//
//  1. O Display NÃO muda uma linha. Um cue nunca vira `load`: projetá-lo chama
//     a MESMA função que o botão da aba já chamava (`projectBibleVerse`,
//     `projectMessage`, `projectChrono`, `projectDraw`,
//     `projectLyricStanza`), que manda o `text`/`chrono`/`draw` de sempre.
//     Invariante 5: ponteiro novo, nunca lógica de projeção nova.
//  2. A reconexão do telão vem de graça: projetar deixa a SESSÃO montada, e
//     `resendSceneToDisplay` já reenvia sessões.
//  3. O descritor é uma REFERÊNCIA, nunca cópia do conteúdo — o versículo
//     guarda `{versão, livro, capítulo, número}` e o texto vem do cache na hora
//     de projetar: o cue não envelhece quando a mensagem é editada nem duplica
//     a Escritura no banco.
// Os seis subtipos. O ícone é SVG inline porque a fonte é um SUBSET de ~30
// glifos e um código fora dela desenha um quadrado vazio; só o "pacote" reusa
// um glifo do subset (`queue_music` é exatamente o que ele é).
const CUE_SVG = {
  // O MESMO desenho da aba da Bíblia (livro aberto com uma cruz), copiado dela:
  // o item de roteiro que abre a Escritura tem de usar o símbolo pelo qual a
  // Escritura é conhecida NESTE app. Um segundo desenho de livro só faria o
  // operador se perguntar se são coisas diferentes.
  verse: '<path d="M4 4.5A1.5 1.5 0 0 1 5.5 3H19v15H5.5A1.5 1.5 0 0 0 4 19.5z"/>'
    + '<path d="M4 19.5A1.5 1.5 0 0 0 5.5 21H19"/>'
    + '<line x1="11.5" y1="6.4" x2="11.5" y2="11.6"/><line x1="9.2" y1="8.4" x2="13.8" y2="8.4"/>',
  message: '<path d="M20 14a2 2 0 0 1-2 2H8l-4 4V5a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2z"/>',
  songlyrics: '<line x1="4" y1="6" x2="20" y2="6"/><line x1="4" y1="11" x2="16" y2="11"/><line x1="4" y1="16" x2="20" y2="16"/><line x1="4" y1="21" x2="12" y2="21"/>',
  chrono: '<circle cx="12" cy="13" r="8"/><path d="M12 9v4l2.5 2"/><line x1="9" y1="2" x2="15" y2="2"/>',
  draw: '<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8.5" cy="8.5" r="1.3"/><circle cx="15.5" cy="15.5" r="1.3"/><circle cx="15.5" cy="8.5" r="1.3"/><circle cx="8.5" cy="15.5" r="1.3"/>',
};

function cueIconSvg(cue) {
  const d = CUE_SVG[cue];
  if (!d) return '';
  return '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor"'
    + ' stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + d + '</svg>';
}

const CUES = {
  verse: { nome: 'Versículo' },
  message: { nome: 'Mensagem' },
  songlyrics: { nome: 'Letra' },
  chrono: { nome: 'Tempo' },
  draw: { nome: 'Sorteio' },
  group: { nome: 'Pacote', glifo: () => ICON.queue },
};

function isCue(rec) { return !!(rec && rec.kind === 'cue' && rec.cue); }

// O QUE ESTE ITEM É — a segunda linha de toda linha da lista.
//
// Subtítulo, nunca selo ao lado do nome: o selo dividia a largura num `flex` em
// que o nome tem `flex: 1`, então sumia justamente nos itens de nome comprido,
// que são os que menos se distinguem entre si. Não custa altura (a linha já tem
// 40px por causa da miniatura).
//
// O detalhe é o que o registro JÁ tem à mão — nada aqui decodifica arquivo nem
// mede nada. Um detalhe com trabalho por linha, a cada render, não se paga.
//
// DE ONDE O ITEM VEIO: `hymnAlbum`, gravado no registro quando a mídia vem de
// uma coleção (ver `preencherAlbunsDosHinos`, que o preenche também para o
// acervo já baixado). É ele que distingue duas gravações do mesmo hino. Vale
// para QUALQUER item com o campo, não só áudio. Entra logo depois do tipo,
// ANTES da duração: numa linha que corta com reticências, o que sobrevive tem
// de ser o que identifica.
function subtituloItem(item) {
  if (!item) return '';
  if (isCue(item)) return cueTipo(item);
  const album = (item.hymnAlbum || '').trim();
  const com = (base) => base + (album ? ' · ' + album : '');
  if (item.kind === 'deck') {
    const n = Array.isArray(item.pages) ? item.pages.length : 0;
    return 'Apresentação' + (n ? ' · ' + n + (n === 1 ? ' página' : ' páginas') : '');
  }
  // O item de PLAYER: o link, sem bytes no aparelho. Dizer "YouTube" é dizer
  // que ele depende da rede durante o culto, que é a diferença que importa
  // entre ele e o arquivo baixado do mesmo vídeo.
  // A DURAÇÃO VALE PARA OS TRÊS, não só para o áudio (v1.5.21). Ela era do
  // `audio` porque só ele a tinha gravada — hoje o link e o vídeo do YouTube a
  // gravam também, e a régua nunca foi o kind: é *"o registro sabe?"*. Sem
  // dado, a linha continua exatamente como era.
  const dur = fmtDur(item.seconds);
  const comDur = (base) => base + (dur ? ' · ' + dur : '');
  if (item.kind === 'youtube') return comDur(com('YouTube'));
  if (item.kind === 'video') {
    return comDur(com('Vídeo') + (item.height ? ' · ' + item.height + 'p' : ''));
  }
  if (item.kind === 'audio') return comDur(com('Áudio'));
  if (item.kind === 'image') return com('Imagem');
  if (!item.blob && item.url) return 'Link externo';
  return com('Arquivo');
}

// ===== UM SÓ CAMINHO PARA "ADICIONAR" (v5.104) =====
//
// Todo destino do app passa por aqui, e por dois motivos que andam juntos:
//
// 1. **O aviso.** Metade dos destinos não está na tela quando se manda algo
//    para eles (mandar ao Cronograma estando na Bíblia, favoritar de dentro do
//    acervo), e sem resposta o operador toca de novo — que é como se duplica.
// 2. **A duplicação.** A resposta precisa distinguir "entrou" de "já estava
//    lá", porque é a segunda que evita o toque repetido.
//
// As listas são conjuntos de ids, então `listAdd` já é idempotente para MÍDIA:
// o mesmo vídeo não entra duas vezes na mesma lista, por construção. O que não
// era idempotente é a CENA DE ROTEIRO — cada uma cria um registro novo, com id
// novo — e é por isso que ela tem uma chave de conteúdo (ver `cueChave`).
// Duas formas por destino, porque as duas frases pedem preposições
// diferentes: "já está NO Cronograma" e "adicionado AO Cronograma". Com uma só
// forma, metade dos avisos sai torta — e um aviso torto num app em português é
// a primeira coisa que se lê como descuido.
const LISTA_ROTULO = {
  imports: { em: 'no Cronograma', para: 'ao Cronograma' },
  playlist: { em: 'na playlist', para: 'à playlist' },
  favs: { em: 'nos favoritos', para: 'aos favoritos' },
};
const ROTULO_PADRAO = { em: 'na lista', para: 'à lista' };

// ===== DESTINOS: um item pode ir para MAIS DE UM lugar de uma vez (v5.141) =====
//
// Toda porta de entrada do app — o acervo, a busca do YouTube, o link
// compartilhado, a importação de arquivos — perguntava "para onde?" e aceitava
// UMA resposta: a folha fechava no primeiro toque, e quem quisesse o mesmo
// louvor na playlist E nos Favoritos tinha de refazer a busca, reabrir a folha
// e — no caso do YouTube — pagar o download de novo. O item é o mesmo; o que
// muda é em quantas listas ele entra, e isso nunca foi uma escolha exclusiva.
//
// A tabela é a fonte única: uma porta nova ganha os três destinos escrevendo
// uma linha, e um destino novo aparece em todas as portas de uma vez. `chave` é
// o nome do destino como o app fala dele por fora (é o que viaja nas ações e no
// `ytAcao`); `lista` é o nome no banco, que não se confunde com ele — o
// Cronograma é a lista `imports` desde antes de se chamar Cronograma.
// SEM SUBTÍTULO (v5.195). Os três destinos se chamam Playlist, Cronograma e
// Favoritos — que são NOMES DE ABA deste app, na barra que o operador usa todo
// domingo. Escrever embaixo de cada um o que ele é ("A lista do culto") é
// explicar a própria navegação para quem já está navegando nela, e era metade
// da altura desta folha.
const DESTINOS = [
  { chave: 'playlist', lista: 'playlist', rotulo: 'Playlist' },
  { chave: 'cronograma', lista: 'imports', rotulo: 'Cronograma' },
  { chave: 'favoritos', lista: 'favs', rotulo: 'Favoritos' },
];
function destinoPorChave(chave) { return DESTINOS.find((d) => d.chave === chave) || null; }
function listaDoDestino(chave) {
  const d = destinoPorChave(chave);
  return d ? d.lista : 'imports';
}
function listasDosDestinos(chaves) {
  // `Set` porque duas chaves podem cair na mesma lista num futuro em que um
  // destino novo compartilhe a `imports` — e um `listAdd` repetido gastaria uma
  // transação para não fazer nada.
  return [...new Set((chaves || []).map(listaDoDestino))];
}

// "à playlist e aos favoritos" — a lista de destinos escrita como se fala.
// Sem isto o aviso do multi-destino sairia como "adicionado à playlist,
// adicionado ao Cronograma", que é a mesma frase duas vezes.
function juntarFrases(partes) {
  if (partes.length <= 1) return partes[0] || '';
  return partes.slice(0, -1).join(', ') + ' e ' + partes[partes.length - 1];
}
function ondeDe(listas, campo) {
  return juntarFrases(listas.map((l) => (LISTA_ROTULO[l] || ROTULO_PADRAO)[campo]));
}

// O nome do item, encurtado — o aviso é uma linha e o nome de um louvor com o
// álbum junto passa fácil da largura da tela.
function rotuloItem(nome) {
  if (!nome) return '';
  return '"' + (nome.length > 28 ? nome.slice(0, 28) + '…' : nome) + '" ';
}

// Acrescenta O MESMO id a VÁRIAS listas, com um aviso só.
//
// Um aviso por lista seria três faixas piscando uma por cima da outra para um
// toque único — o mesmo argumento de `textoLote`, que já resolvia isto para
// vários itens num destino só. Aqui é o espelho: um item em vários destinos.
//
// A frase separa o que ENTROU do que JÁ ESTAVA, porque é essa distinção que
// impede o toque repetido (ver o cabeçalho acima). Com os dois casos presentes
// ela diz os dois — "adicionado à playlist — já estava no Cronograma" —, e não
// um resumo que esconderia metade.
async function adicionarNasListas(listas, id, nome, btn) {
  const alvos = [...new Set(listas)];
  const novas = [], antigas = [];
  for (const l of alvos) {
    if (await AVDB.listHas(l, id)) { antigas.push(l); continue; }
    await AVDB.listAdd(l, id);
    novas.push(l);
  }
  const que = rotuloItem(nome);
  let texto;
  if (!novas.length) texto = que + 'já está ' + ondeDe(antigas, 'em');
  else if (!antigas.length) texto = que + 'adicionado ' + ondeDe(novas, 'para');
  else texto = que + 'adicionado ' + ondeDe(novas, 'para') + ' — já estava ' + ondeDe(antigas, 'em');
  responder(btn, novas.length ? (antigas.length ? 'dup' : 'ok') : 'dup', texto);
  if (alvos.includes('favs')) await recarregarFavoritos();
  if (alvos.includes('playlist')) { plItems = await AVDB.listItems('playlist'); renderPlaylist(); }
  // E O CRONOGRAMA TAMBÉM — ele ficava por conta do chamador, e dos dois que
  // existem só um lembrava. Pelo outro (a gaveta de um item da Biblioteca), o
  // item entrava no banco e a lista de trás continuava sem ele até o próximo
  // redesenho por outro motivo: do lado de quem opera, "adicionei e não
  // apareceu". Um funil que cuida de dois dos três destinos é um convite a
  // isto no terceiro chamador que aparecer.
  if (alvos.includes('imports')) {
    // O ESPELHO DO CRONOGRAMA (v1.4.25) anda ANTES do `load()` condicional: ele
    // é o que responde ao botão da fila, e ele existe justamente para o caso em
    // que a aba de trás NÃO é o Cronograma — que é o caso em que aquele `load()`
    // não roda.
    cronoSet.add(id);
    marcarNoCronograma();
    await load();
  }
  return novas.length;
}

// (`adicionarNaLista` — a forma de UM destino — SAIU: o comentário dela dizia
// que era "o que a maior parte do app ainda usa" e ela não tinha um único
// chamador. Os dois pontos que acrescentam item a lista (a gaveta de uma linha
// e a folha de destinos de uma música) passam por `listasDosDestinos` e chamam
// `adicionarNasListas` direto desde a v5.141, que é o lote que a tornou
// supérflua. Quem a mantinha viva era o `tools/destinos.test.mjs` — um oráculo
// exercitando um caminho que o app não percorre não é rede de segurança, é uma
// segunda API mantida por engano, e ele passou a montar o fixture pela mesma
// porta que o app usa.)

// A identidade de uma CENA: tipo + descritor. Duas cenas com a mesma chave são
// a mesma coisa para o operador ("Salmo 23:1" é "Salmo 23:1"), ainda que sejam
// dois registros diferentes no banco.
//
// `JSON.stringify` basta porque os descritores são montados sempre pelo MESMO
// código, campo a campo e na mesma ordem — não são objetos que chegam de fora.
function cueChave(cue, data) {
  const d = data || {};
  // A MENSAGEM é identificada pelo `msgId`. O texto viaja junto no descritor
  // como reserva (para o roteiro não ficar mudo se ela for apagada), mas duas
  // cenas da MESMA mensagem são a mesma cena — comparar o texto deixaria a
  // reserva decidir a identidade.
  if (cue === 'message') return 'message:' + (d.msgId || d.text || '');
  return cue + ':' + JSON.stringify(d);
}

async function acharCueIgual(lista, cue, data) {
  const chave = cueChave(cue, data);
  const itens = await AVDB.listItems(lista);
  return itens.find((r) => isCue(r) && cueChave(r.cue, r.data) === chave) || null;
}

// A mesma pergunta, mas SÍNCRONA e só sobre os favoritos — `favItems` já está
// em memória, e quem precisa disto (a estrela de cada linha) é desenhado num
// laço de render, onde um `await` por linha seria uma leitura de IDB por item.
function favCue(cue, data) {
  const chave = cueChave(cue, data);
  return favItems.find((r) => isCue(r) && cueChave(r.cue, r.data) === chave) || null;
}

// A miniatura de uma cena: o símbolo do tipo no lugar da imagem que ela não
// tem. Mesma caixa das outras (`.thumb--icon`), então a lista não muda de
// ritmo por causa dela.
function cueThumb(rec) {
  const t = document.createElement('div');
  t.className = 'thumb thumb--icon thumb--cue';
  const meta = CUES[rec.cue];
  if (meta && meta.glifo) t.appendChild(msym(meta.glifo()));
  else t.innerHTML = cueIconSvg(rec.cue);
  return t;
}

// O que a linha do Cronograma mostra à esquerda do nome: qual TIPO de cena é.
// Sem isso, "Salmo 23:1" e "Bem-vindos ao culto" seriam duas linhas de texto
// indistinguíveis numa lista que também tem vídeo e hino.
function cueTipo(rec) { return (isCue(rec) && CUES[rec.cue]) ? CUES[rec.cue].nome : ''; }

// Cria a cena e devolve o registro. `destino` é a lista — o Cronograma por
// padrão, mas a mesma função serve aos Favoritos (é o mesmo id em outra lista).
async function criarCue(cue, data, nome, destino, btn) {
  if (!CUES[cue]) return null;
  const lista = destino || 'imports';
  // ANTI-DUPLICAÇÃO, com regras DIFERENTES por destino — e a diferença é do
  // operador, não técnica:
  //
  //  - **Favoritos não repetem.** Favoritar é marcar; dois "Salmo 23:1" na
  //    mesma gaveta são ruído puro, e ninguém consegue distingui-los. O item
  //    que já existe é reaproveitado e o aviso diz isso.
  //  - **O Cronograma PODE repetir.** O mesmo versículo pode ser lido na
  //    abertura e no apelo, e a mesma contagem regressiva pode aparecer duas
  //    vezes no culto. Aqui a duplicata é criada — mas o aviso avisa, que é o
  //    que separa a repetição intencional do toque dado duas vezes.
  const igual = await acharCueIgual(lista, cue, data);
  const onde = LISTA_ROTULO[lista] || ROTULO_PADRAO;
  if (igual && lista !== 'imports') {
    responder(btn, 'dup', rotuloItem(igual.name) + 'já está ' + onde.em);
    return igual;
  }
  const rec = await AVDB.addCue(cue, data, { name: nome, list: lista });
  responder(btn, igual ? 'dup' : 'ok', igual
    ? rotuloItem(nome) + 'adicionado — já havia um igual no Cronograma'
    : rotuloItem(nome) + 'adicionado ' + onde.para);
  if (lista === 'favs') await recarregarFavoritos();
  // Redesenha só quando a tela em cena é justamente a que acabou de receber o
  // item — guardar um versículo estando na aba da Bíblia não precisa remontar
  // o Cronograma, que ainda vai ser carregado ao voltar para ele.
  if (lista === 'imports') await load();
  return rec;
}

// PROJETA uma cena. Cada ramo termina na função que a aba correspondente já
// usava, então o comportamento (incluindo ⏮/⏭, o rótulo do now-playing e a
// notificação nativa) é idêntico ao de projetar pela aba — porque É a mesma
// projeção.
// O `rec.id` DESCE JUNTO porque é ele que diz em qual LINHA escrever quando a
// projeção não dá (ver `falharNoItem`): estas quatro falhas são sobre um item
// específico de uma lista que está na tela, e a resposta pertence a ele.
async function playCue(rec) {
  if (!isCue(rec)) return;
  const d = rec.data || {};
  switch (rec.cue) {
    case 'verse': return projetarVersiculoRef(d, rec.id);
    case 'message': return projetarMensagemCue(d, rec.id);
    case 'songlyrics': return projetarLetraCue(d, rec.id);
    case 'chrono': return projetarTempoCue(d);
    case 'draw': return projetarSorteioCue(d);
    case 'group': return abrirPacote(d, rec.id);
    default: return undefined;
  }
}

// ---- versículo ----
// Monta a sessão de leitura DO ZERO a partir da referência e projeta. Não
// reaproveita `bibleGotoChapter` de propósito: aquela exige uma sessão já
// aberta (lê `s.versionId` dela), e aqui a sessão é justamente o que não
// existe — o operador pode estar em qualquer aba quando toca no roteiro.
async function projetarVersiculoRef(ref, cueId) {
  // A VERSÃO EM USO HOJE tem precedência sobre a que estava em uso quando o
  // item foi guardado: a referência é do TEXTO ("Salmo 23:1"), não da tradução,
  // e um roteiro montado há um mês não pode arrastar de volta uma versão que o
  // operador trocou desde então — nem disparar o download dela no domingo.
  // A guardada fica como RESERVA, e é ela que salva o caso offline: a versão de
  // hoje pode não ter este capítulo em cache, e a de então provavelmente tem.
  const versoes = [bibleVersionId, ref.versionId].filter((v, i, a) => v && a.indexOf(v) === i);
  if (!versoes.length) { falharNoItem(cueId, 'nenhuma versão da Bíblia baixada'); return; }
  // A SENHA VEM ANTES DO `await` (ver `projecaoSeq`). O capítulo pode não estar
  // em cache, e aí o laço abaixo vai à REDE: nesse tempo o operador — que não vê
  // nada acontecendo — projeta outra coisa, e sem esta guarda o versículo entra
  // no telão por cima dela quando o texto chegar.
  const seq = ++projecaoSeq;
  let verses = null;
  let versao = versoes[0];
  for (const v of versoes) {
    try { verses = await fetchBibleChapterCached(v, ref.bookIdx, ref.chapter); versao = v; break; }
    catch (_) { /* tenta a próxima */ }
  }
  if (seq !== projecaoSeq) return;   // o operador projetou outra coisa enquanto esperava
  if (!verses || !verses.length) { falharNoItem(cueId, 'capítulo não está no aparelho'); return; }
  const book = Bible.BOOKS[ref.bookIdx];
  if (!book) return;
  // Pelo NÚMERO do versículo, não pelo índice: capítulos com numeração
  // irregular (ou uma versão que traga um versículo a menos) deslocariam o
  // índice e projetariam outra coisa. Sem o número, cai no primeiro.
  let idx = verses.findIndex((v) => v.n === ref.verse);
  if (idx < 0) idx = 0;
  clearMsgSession(); clearChronoSession(); clearDrawSession(); clearLyricSession();
  bibleSession = {
    versionId: versao, bookIdx: ref.bookIdx, bookId: bibleBookId(ref.bookIdx),
    bookName: book.name, chapter: ref.chapter, verses, idx, projecting: false,
  };
  // A aba da Bíblia (se o operador for até ela) abre no que está no ar, e não
  // no que ele escolheu por último — a leitura continua de onde o roteiro
  // parou, e daí em diante ⏮/⏭ passam versículo como em qualquer leitura.
  bibleSel = { bookIdx: ref.bookIdx, chapter: ref.chapter };
  bibleChapterData = { verses };
  bibleScreen = 'reading';
  projectBibleVerse(idx);
}

// ---- mensagem ----
// Guarda o `msgId` E o texto. Com a mensagem ainda na lista, projeta pelo
// ÍNDICE — e aí ⏮/⏭ passam para a mensagem seguinte, como sempre. Apagada a
// mensagem, o roteiro não pode ficar mudo no meio do culto: projeta o texto
// guardado, sem sessão de navegação (o `slideTarget` devolve null e os botões
// voltam a ser de mídia, que é a leitura honesta — não há lista para percorrer).
function projetarMensagemCue(d, cueId) {
  const i = d.msgId ? messages.findIndex((m) => m.id === d.msgId) : -1;
  if (i >= 0) { projectMessage(i); return; }
  const texto = String(d.text || '').trim();
  if (!texto) { falharNoItem(cueId, 'a mensagem foi excluída'); return; }
  clearManualText();
  // SEM SESSÃO DE NAVEGAÇÃO, MAS NÃO SEM ESTADO: sem esta linha o texto ficava
  // projetado e invisível para o resto do app — o segundo toque não o
  // reconhecia como no ar, e só o Parar o tirava. Ver `cenaDeRoteiroNoAr`.
  textoAvulsoNoAr = true;
  view = 'visual';
  persistCurrent();
  cmd({ type: 'text', mode: 'message', main: texto, sub: '', view: 'visual' });
  renderControls();
  renderNowPlaying();
  renderSlideNav();
}

// ---- letra avulsa ----
async function projetarLetraCue(d, cueId) {
  const coll = allCollections().find((c) => c.id === d.collId);
  const s = coll ? collSongs(d.collId).find((x) => String(x.id_music) === String(d.songId)) : null;
  if (!coll || !s) { falharNoItem(cueId, 'a música saiu do acervo'); return; }
  await projectSongLyricsOnly(coll, s);
}

// ---- cronômetro / relógio / timer ----
// O cue é um PRESET: ele reescreve o estado da ferramenta (modo, duração,
// legenda) e projeta. Um timer de abertura no roteiro tem de começar do
// princípio — daí o reset da contagem e o start automático, que é o que o
// operador faria em seguida de qualquer forma.
function projetarTempoCue(d) {
  if (CHRONO_MODES.some((m) => m.id === d.mode)) chrono.mode = d.mode;
  if (typeof d.durationMs === 'number' && d.durationMs > 0) chrono.durationMs = d.durationMs;
  if (typeof d.label === 'string') chrono.label = d.label;
  if (typeof d.secs === 'boolean') chrono.secs = d.secs;
  if (typeof d.h12 === 'boolean') chrono.h12 = d.h12;
  chrono.baseMs = 0;
  chrono.running = chrono.mode !== 'clock';
  chrono.startAt = chrono.running ? Date.now() : 0;
  saveChronoPrefs();
  projectChrono();
}

// ---- sorteio ----
// Também um preset (faixa ou lista de opções). NÃO sorteia sozinho: o resultado
// é o momento público do sorteio, e ele pertence ao toque do operador em
// "Sortear" — um número que já aparece pronto ao entrar em cena tira justamente
// o que faz a coisa ter graça.
function projetarSorteioCue(d) {
  if (d.kind === 'text' || d.kind === 'number') draw.kind = d.kind;
  if (typeof d.min === 'number') draw.min = d.min;
  if (typeof d.max === 'number') draw.max = d.max;
  if (Array.isArray(d.pool)) draw.pool = d.pool.map(String);
  if (typeof d.label === 'string') draw.label = d.label;
  // O HISTÓRICO SAI JUNTO. Este preset reescreve `kind`, `min`, `max` e `pool`
  // — exatamente os campos que invalidam o que já foi sorteado —, e o caminho
  // MANUAL já zera `used` ao trocar a natureza do sorteio pelo mesmo motivo.
  // Sem isto, um cue de "1 a 60" herdava os já sorteados de um sorteio anterior
  // e o `noRepeat` podia filtrar o conjunto inteiro: o roteiro abria um sorteio
  // sem números para sortear, na frente da congregação.
  draw.used = [];
  draw.value = null; draw.rollUntil = 0;
  saveDrawPrefs();
  projectDraw();
}

// ---- pacote ----
// O "pacote de playlist": um cue que carrega uma FILA inteira. Tocar substitui
// a playlist pelos itens dele e começa pelo primeiro — é o bloco de louvores da
// abertura entrando com um toque, em vez de quatro itens montados à mão a cada
// semana. Os ids que não existirem mais são simplesmente pulados (uma mídia
// excluída não pode impedir o resto do bloco de tocar).
async function abrirPacote(d, cueId) {
  const ids = Array.isArray(d.ids) ? d.ids : [];
  const recs = (await Promise.all(ids.map((id) => AVDB.getMedia(id)))).filter(Boolean);
  if (!recs.length) { falharNoItem(cueId, 'as mídias saíram do aparelho'); return; }
  // A CORTINA VIAJA NO DESCRITOR, e só o pacote da playlist automática a
  // grava: um "Fundo musical" abre com o telão coberto, uma "Playlist" o
  // revela. AUSENTE NÃO MEXE EM NADA — é o caso do pacote montado à mão pelo
  // botão da fila, que nunca prometeu nada sobre o telão e não pode começar a
  // prometer por causa deste campo.
  if (d.view && view !== d.view) await setView(d.view);
  await AVDB.listSet('playlist', recs.map((r) => r.id));
  plItems = recs;
  renderPlaylist();
  await send(recs[0].id);
}

// ===== Letra avulsa: projeção e navegação =====
function clearLyricSession() {
  if (!lyricSession) return;
  lyricSession = null;
  renderSlideNav();
  renderNowPlaying();
}
function lyricProjecting() { return !!(lyricSession && lyricSession.projecting); }

// Abre a sessão a partir de uma música do acervo. `songLyricStanzas` lê só o
// que já está no aparelho; quando não há nada, o caminho é o MESMO das outras
// duas opções da folha — baixar a música (que traz a letra junto) e tentar de
// novo. Até a v5.63 isto era um beco sem saída: "Letra ainda não baixada." e
// nada acontecia, num item que o operador acabara de escolher.
async function projectSongLyricsOnly(coll, s) {
  // A RESPOSTA VEM PRIMEIRO — mesma regra de `playSongVariant`.
  closeSongMenu();
  closeHymnSearch();
  const seq = ++lyricLoadSeq;
  const bg = previewBusy('Baixando a letra', songLabel(coll, s));
  try {
    let stanzas = await lyricStanzaTexts(coll, s);
    if (seq !== lyricLoadSeq) return;
    if (!stanzas.length) {
      await ensureSongDownloaded(coll, s);
      if (seq !== lyricLoadSeq) return;
      stanzas = await lyricStanzaTexts(coll, s);
      if (seq !== lyricLoadSeq) return;
    }
    // O MESMO CARTÃO que estava dizendo "Baixando…" diz por que não deu — ele
    // é sobre a preview, que é onde a letra apareceria.
    if (!stanzas.length) { bg.falhar('esta música não tem letra'); return; }
    soUmProvedorDeTexto('songlyrics');
    lyricSession = { title: songLabel(coll, s), stanzas, idx: 0, projecting: true };
    projectLyricStanza(0);
  } finally {
    bg.soltar();
  }
}

// As estrofes já achatadas em texto de slide (uma string por estrofe, linhas
// separadas por `\n`), sem as vazias.
async function lyricStanzaTexts(coll, s) {
  const estrofes = await songLyricStanzas(coll, s);
  return (estrofes || []).map((e) => (e.l || []).join('\n').trim()).filter((t) => t);
}

function projectLyricStanza(idx) {
  if (!lyricSession) return;
  lyricSession.idx = Math.min(Math.max(idx, 0), lyricSession.stanzas.length - 1);
  lyricSession.projecting = true;
  view = 'visual';
  persistCurrent();
  // `mode: 'message'` — o telão já sabe desenhar um bloco de texto centrado, que
  // é exatamente o que uma estrofe é. Um modo novo no protocolo só para isto
  // exigiria shell/bundle novos dos dois lados sem mudar um pixel do resultado.
  cmd({ type: 'text', mode: 'message', main: lyricSession.stanzas[lyricSession.idx], sub: '', view: 'visual' });
  renderControls();
  renderNowPlaying();
  renderSlideNav();
}

function lyricStep(delta) {
  if (!lyricSession) return;
  const t = Math.min(Math.max(lyricSession.idx + delta, 0), lyricSession.stanzas.length - 1);
  if (t === lyricSession.idx) return;
  if (!lyricProjecting()) { lyricSession.idx = t; renderSlideNav(); return; }
  projectLyricStanza(t);
}

// ===== A MÍDIA VISUAL SOBRE O ÁUDIO (v5.312 · a apresentação na v1.4.28) =====
//
// Pedido do operador: *"preciso que imagens, ou arquivos unicamente visuais,
// possam ser apresentados sobre uma mídia de áudio, sem interromper o áudio,
// semelhante ao que já temos com elementos de texto sobre áudio"* — e, na
// v1.4.28, *"adicione a possibilidade de música atrás dos slides. Atualmente
// são concorrentes, mas os slides devem ser tratados como camada, assim como
// as imagens ou os textos e mensagens"*.
//
// A APRESENTAÇÃO ENTROU NESTA CAMADA, e não numa segunda. Uma página de deck é
// UMA imagem opaca ocupando a tela — exatamente o que este cartão já pinta —, e
// o que muda entre as duas é só QUAL blob do registro sai: `rec.blob` na imagem,
// `rec.pages[page]` na apresentação. Por isso o comando continua sendo
// `mode: 'image'` com um campo `page` a mais: o `display.js` ganha uma escolha
// de blob e nenhum ramo novo, nenhuma classe nova, nenhum caminho novo de
// reenvio nem de `text-hide`. O motor de projeção continua sem mudar uma linha,
// que é o mesmo argumento que tornou a v5.312 segura.
//
// **Não era um defeito: era uma capacidade que nunca existiu.** Medido num
// navegador de verdade — com um áudio tocando, projetar uma imagem deixava o
// `<video>` em `paused: true` e `currentTime: 0`. A causa é o slot ÚNICO do
// `stage.js`: `loadInner` faz `video.pause()` + `removeAttribute('src')` em TODO
// load, qualquer que seja o *kind*. O texto escapa porque não passa por ali.
//
// Por isso a imagem passou a ser um MODO da Camada de Texto, e não um segundo
// slot no motor: a camada já é um cartão opaco acima da mídia, já declara
// `stage.setOverlay`, já é reenviada na reconexão e já sai pelo `text-hide`. O
// motor de projeção — o código que roda na frente da congregação — não muda uma
// linha, que é o que torna esta mudança segura.
//
// A sessão tem a mesma forma das outras cinco (`{ id, projecting }`), e por isso
// entra de graça em `cenaDeRoteiroNoAr`, no rodízio do `soUmProvedorDeTexto` e
// na escada do botão voltar. **O NOME É `visual` e não `imagem`** desde que a
// apresentação entrou: um `imgSession` guardando um deck é a armadilha que este
// projeto nomeia — quem o lesse procuraria uma imagem que não está lá.
// O `rec` viaja DENTRO da sessão porque ele é o único lugar que sobrevive à
// troca de aba: a imagem sobreposta costuma vir de `libItems`, e essa lista é
// zerada a cada troca. Sem ele, um reenvio de cena (uma tela da rede que deu F5)
// mandava `{type:'text',mode:'image'}` sem `__rec` e a tela pintava um cartão
// PRETO sobre a projeção. Ver `await0Rec`.
let visualSession = null;   // { id, nome, rec, projecting } | null
function visualSobreProjetando() { return !!(visualSession && visualSession.projecting); }

// A CAMADA DE CIMA É UMA APRESENTAÇÃO? É a única pergunta que separa os dois
// conteúdos deste cartão, e ela existe porque um deck tem o que uma imagem não
// tem: PÁGINAS. É ela que devolve o eixo de ⏮/⏭ ao `slideTarget` (onde a imagem
// devolve `null`, por não ter para onde ir) e que põe a aba "Páginas" no
// auxiliar de leitura enquanto a música de fundo mantém as dela.
function deckSobreProjetando() {
  return visualSobreProjetando() && isDeck(visualSession.rec);
}

/**
 * A APRESENTAÇÃO QUE ESTÁ NO AR — pela camada, ou como a própria mídia.
 *
 * São os dois jeitos de um deck estar projetando, e todo o resto do app precisa
 * de UMA resposta: os limites do ⏮/⏭, o número da página no transporte, a
 * coluna do auxiliar de leitura e o reenvio de cena. Duas leituras espalhadas
 * pelo arquivo divergiriam no primeiro caminho novo — é a mesma razão pela qual
 * `slideTarget` é um lugar só.
 *
 * A CAMADA VENCE, e não é empate: com as duas coisas de pé, o que a congregação
 * vê é o cartão de cima.
 */
function deckNoAr() {
  if (deckSobreProjetando()) return visualSession.rec;
  return isDeck(currentItem) ? currentItem : null;
}

// ESTA LINHA DA LISTA É A IMAGEM QUE ESTÁ POR CIMA? A pergunta existe porque a
// sobreposição rompe a premissa das quatro funções de realce: elas dividem o
// mundo em CUE (texto de roteiro, marcado por `cueNoArId`) e MÍDIA (marcada por
// `midiaNoArId`), e a imagem sobreposta não é nenhuma das duas — é um item de
// mídia projetando pela porta da Camada de Texto. Sem ela a linha não ganhava
// selo, não ficava ativa, e o segundo toque caía no `pararMidia` do ramo de
// mídia: o operador tocava na IMAGEM para tirá-la e o que saía era o ÁUDIO,
// com a imagem seguindo na tela.
function visualSobreNaLinha(id) {
  return !!(id && visualSobreProjetando() && visualSession.id === id);
}
function clearVisualSession() {
  if (!visualSession) return;
  visualSession = null;
  renderSlideNav();
  renderNowPlaying();
}

// HÁ UM ÁUDIO NO AR? A pergunta é "no ar", e não "tocando": um louvor PAUSADO
// para a oração continua sendo a cena, e cobrir a imagem por cima dele é o
// mesmo gesto. É a mesma régua que o reenvio de cena usa (`midiaNoAr`).
function audioNoAr() {
  return !!(midiaNoAr && currentItem && currentItem.kind === 'audio');
}

// Encerra QUALQUER texto manual em cena (Bíblia, Mensagem, letra avulsa,
// cronômetro ou sorteio) — só um por vez.
/**
 * UM PROVEDOR DE TEXTO POR VEZ — e a lista mora aqui, não em cada projetor.
 *
 * O cartão de texto é UM, e cada `project*` limpava as outras camadas à mão.
 * A conta não fechava, e nenhum caminho errava alto: `projectBibleVerse`
 * limpava só cronômetro e sorteio, `projectMessage`/`projectChrono`/
 * `projectDraw` esqueciam a LETRA AVULSA nos três, e ninguém zerava o
 * `textoAvulsoNoAr`. Como `lyricProjecting()` tem PRECEDÊNCIA sobre mensagem e
 * Bíblia no `slideTarget` e no `renderNowPlaying`, uma `lyricSession` órfã com
 * `projecting: true` sequestrava ⏮/⏭ e o título publicado na notificação de
 * mídia: o telão mostrava o aviso e o transporte continuava dizendo "147. Ó
 * Adorai o Senhor · 1/5", passando estrofes de um hino que não estava em cena.
 *
 * SEIS listas mantidas à mão seriam seis lugares para a próxima camada ser
 * esquecida. Aqui é um: quem entra diz QUEM É, e o resto sai.
 */
function soUmProvedorDeTexto(quem) {
  ++projecaoSeq;   // ver `projecaoSeq`: invalida um versículo de roteiro em voo
  // UM PROVEDOR DIFERENTE ASSUMINDO O CARTÃO TIRA A CENA DE ROTEIRO DO AR — e o
  // selo "● No ar" da linha do roteiro tem de sair junto. Sem esta linha o selo
  // ficava na linha ANTIGA e o toque seguinte lia `noArAgora = true`: o operador
  // tocava no versículo esperando reprojetá-lo e o que saía do telão era a cena
  // NOVA (o cronômetro), com o versículo sem entrar. Só a TROCA zera: navegar
  // entre versículos ou mensagens reprojeta pelo MESMO provedor, e a cena de
  // roteiro continua sendo a mesma.
  //
  // A pergunta é `provedorDoCartao()` — quem é DONO da sessão —, e nunca
  // `provedorDeTextoNoAr()`, que pergunta quem está PROJETANDO. Os `hide*`
  // deixam a sessão de pé com `projecting:false` (é o que permite reexibir pela
  // lista), então com o cartão escondido o segundo devolveria `''`, a troca
  // seria falsa, e reexibir O PRÓPRIO cue apagaria o selo dele.
  if (cueNoArId && provedorDoCartao() !== quem) cueNoArId = '';
  if (quem !== 'visual') clearVisualSession();
  if (quem !== 'bible') clearBibleSession();
  if (quem !== 'message') clearMsgSession();
  if (quem !== 'songlyrics') clearLyricSession();
  if (quem !== 'chrono') clearChronoSession();
  if (quem !== 'draw') clearDrawSession();
  // O AVULSO não tem sessão (é a mensagem de roteiro cuja original foi
  // apagada), e por isso ele não estava em lista nenhuma — mas ele responde
  // `cenaDeRoteiroNoAr()`, então deixá-lo de pé fazia a lista continuar
  // dizendo "● No ar" sobre um texto que outro provedor já tinha substituído.
  if (quem !== 'avulso') textoAvulsoNoAr = false;
}

function clearManualText() {
  clearBibleSession(); clearMsgSession(); clearLyricSession();
  clearChronoSession(); clearDrawSession(); clearVisualSession();
  textoAvulsoNoAr = false;
  // A Camada de Texto saiu: nenhuma cena de roteiro está mais no ar, venha ela
  // de onde vier. Ver `cueNoArId`.
  cueNoArId = '';
}

// QUEM É DONO DO CARTÃO ('' se ninguém) — pela EXISTÊNCIA da sessão, não pela
// projeção. É o par de `provedorDeTextoNoAr` logo abaixo, e a diferença entre os
// dois é o que separa "escondi e vou reexibir" de "outro provedor assumiu": os
// `hide*` zeram `projecting` e deixam a sessão viva, de propósito, para o
// operador reexibir pela lista.
//
// A ordem não importa: `soUmProvedorDeTexto` garante uma sessão por vez.
function provedorDoCartao() {
  if (bibleSession) return 'bible';
  if (msgSession) return 'message';
  if (lyricSession) return 'songlyrics';
  if (chronoSession) return 'chrono';
  if (drawSession) return 'draw';
  if (visualSession) return 'visual';
  if (textoAvulsoNoAr) return 'avulso';
  return '';
}

// QUAL provedor ocupa o cartão de texto AGORA ('' se nenhum). A ordem é a de
// `cenaDeRoteiroNoAr` e não importa: `soUmProvedorDeTexto` garante um por vez.
function provedorDeTextoNoAr() {
  if (bibleSession && bibleSession.projecting) return 'bible';
  if (msgProjecting()) return 'message';
  if (lyricProjecting()) return 'songlyrics';
  if (chronoProjecting()) return 'chrono';
  if (drawProjecting()) return 'draw';
  if (visualSobreProjetando()) return 'visual';
  if (textoAvulsoNoAr) return 'avulso';
  return '';
}

/**
 * ===== O SELO DE CAMADAS É PADRÃO DE TODA CAMADA DE TEXTO (v1.1.11) =====
 *
 * UMA condição: há Camada de Texto projetando. Ele **não** pergunta mais se há
 * mídia por baixo.
 *
 * A regra anterior exigia as duas coisas, com o argumento de que sobre um
 * versículo sozinho não há camada a encerrar e o Parar já resolveria. O
 * argumento estava errado por duas razões, e as duas são do operador:
 *
 *  - **O botão sumia justamente onde ele é mais procurado.** Bíblia, mensagem e
 *    cronômetro são projetados o tempo todo SEM música por baixo, e ali o selo
 *    simplesmente não existia — o mesmo gesto funcionava ou não conforme algo
 *    que não tem relação nenhuma com o texto na tela.
 *  - **Um controle que aparece e some conforme o contexto é um controle que
 *    ninguém aprende.** Se ele é a saída da Camada de Texto, ele é a saída
 *    SEMPRE; que a camada de baixo seja um louvor ou o wallpaper não muda o que
 *    o toque faz nem o que o operador quis.
 *
 * `encerrarCamadaDeCima` já estava certo para os dois casos: cada provedor sai
 * pela própria porta e o que houver por baixo — áudio ou wallpaper — fica.
 */
function renderCamadaBtn() {
  if (!pvCamadaBtnEl) return;
  pvCamadaBtnEl.hidden = !cenaDeRoteiroNoAr();
}

/**
 * ENCERRA SÓ A CAMADA DE CIMA — a de baixo (o áudio) segue tocando.
 *
 * Cada provedor sai pela PRÓPRIA porta, e é isso que preserva a sessão dele: os
 * `hide*` escrevem `projecting = false` e deixam a navegação de pé, então o
 * operador reexibe pela lista sem remontar nada. A ordem é a de
 * `provedorDeTextoNoAr`, que já é a precedência do resto do app.
 *
 * `songlyrics` e `avulso` caem no caminho GENÉRICO porque não têm `hide*`
 * próprio: a letra avulsa só sai por `clearLyricSession`, e o avulso não tem
 * sessão nenhuma (é a mensagem de roteiro cuja original foi apagada). É o mesmo
 * par `text-hide` + `clearManualText` que o ramo de cue do `retirarDoAr` usa —
 * o `text-hide` é o que TIRA DA TELA, e o `clear` é só a escrituração.
 */
function encerrarCamadaDeCima() {
  const quem = provedorDeTextoNoAr();
  if (!quem) return;
  if (quem === 'visual') return hideVisualSobre();
  if (quem === 'bible') return hideBibleVerse();
  if (quem === 'message') return hideMessage();
  if (quem === 'chrono') return hideChrono();
  if (quem === 'draw') return hideDraw();
  cmd({ type: 'text-hide' });
  clearManualText();
  marcarNoAr();
  renderNowPlaying();
}

/**
 * Há uma Camada de Texto NO AR? A pergunta é sobre PROJEÇÃO, nunca sobre a
 * existência da sessão.
 *
 * Os quatro `hide*` existem para tirar da tela SEM matar a sessão (o operador
 * reexibe, e o cronômetro segue correndo por baixo): eles escrevem
 * `projecting = false` e deixam a sessão de pé. Testando a existência, esta
 * função respondia "está no ar" com o telão limpo — a linha da cena ficava com
 * o selo "● No ar" e o toque caía em `retirarDoAr`, de modo que reprojetar
 * custava DOIS toques e o primeiro não fazia nada visível.
 *
 * O AVULSO entra por um booleano: é a mensagem de roteiro cuja original foi
 * apagada — `projetarMensagemCue` projeta o texto guardado sem sessão de
 * navegação (não há lista a percorrer), e sem a bandeira ele ficaria projetado
 * e invisível para o resto do app.
 */
function cenaDeRoteiroNoAr() {
  return !!((bibleSession && bibleSession.projecting) || msgProjecting()
    || lyricProjecting() || chronoProjecting() || drawProjecting()
    || visualSobreProjetando() || textoAvulsoNoAr);
}

// Projeta a mensagem de índice `idx` (Display + preview). Encerra a Bíblia (só
// um texto manual por vez).
function projectMessage(idx) {
  if (idx < 0 || idx >= messages.length) return;
  soUmProvedorDeTexto('message');
  msgSession = { idx, projecting: true };
  view = 'visual';
  persistCurrent();
  cmd({ type: 'text', mode: 'message', main: messages[idx].text, sub: '', view: 'visual' });
  renderControls();
  renderNowPlaying();
  renderSlideNav();
  refreshDiversos();
}

// PROJETAR UMA IMAGEM POR CIMA. Nenhum `load` sai daqui — é essa a diferença
// inteira, e é o que preserva o áudio por baixo.
function projetarVisualSobre(rec) {
  if (!rec) return;
  soUmProvedorDeTexto('visual');
  visualSession = { id: rec.id, nome: rec.name || '', rec, projecting: true };
  // A APRESENTAÇÃO ENTRA SEMPRE PELA PRIMEIRA PÁGINA, e a linha mora AQUI
  // porque o caminho da camada volta antes do `deckPagina = 0` do `send`. Sem
  // ela, sobrepor um deck ao louvor abriria na página em que o deck ANTERIOR
  // parou — um slide aleatório no telão.
  deckPagina = 0;
  // `view` volta a 'visual' porque a cortina esconderia o cartão que acabou de
  // ser pedido — a mesma linha que `projectMessage` tem, pela mesma razão.
  view = 'visual';
  persistCurrent();
  cmd({ type: 'text', mode: 'image', mediaId: rec.id, page: 0, sub: '', view: 'visual' });
  renderControls();
  renderNowPlaying();
  renderSlideNav();
  marcarNoAr();
}
function hideVisualSobre() {
  if (!visualSobreProjetando()) return;
  visualSession.projecting = false;
  cmd({ type: 'text-hide' });
  renderControls();
  renderNowPlaying();
  renderSlideNav();
  marcarNoAr();
}

// Tira a mensagem do telão mantendo a sessão viva (o operador pode reexibir
// pela lista). Espelha hideBibleVerse: `text-hide` encerra só a Camada de
// Texto — um áudio de fundo, se houver, segue tocando.
function hideMessage() {
  if (!msgProjecting()) return;
  msgSession.projecting = false;
  cmd({ type: 'text-hide' });
  renderControls();
  renderNowPlaying();
  renderSlideNav();
  marcarNoAr();   // o selo "● No ar" da linha só sai por aqui — ver `hideBibleVerse`
  // Uma chamada só: a segunda (lapso — nenhum outro hide* do arquivo repete)
  // remontava a aba inteira, microfone incluído, duas vezes no mesmo pulso.
  refreshDiversos();
}

// Passa/volta entre mensagens salvas (reusa os botões de slide). Com a
// mensagem fora do ar (o operador tocou no X), passar só MOVE a seleção — não
// traz de volta o que ele acabou de tirar. Mesma regra da Bíblia (bibleSetIdx).
function msgStep(delta) {
  if (!msgSession) return;
  const t = Math.min(Math.max(msgSession.idx + delta, 0), messages.length - 1);
  if (t === msgSession.idx) return;
  if (!msgProjecting()) {
    msgSession.idx = t;
    renderSlideNav();
    refreshDiversos();
    return;
  }
  projectMessage(t);
}

async function saveMessages() { await AVDB.setState('messages', messages); }

async function addMessage() {
  const text = await appPrompt({ title: 'Nova mensagem', message: 'Texto da mensagem:', okText: 'Salvar', placeholder: 'Ex.: Bem-vindos ao culto!' });
  if (!text || !text.trim()) return;
  messages.push({ id: uid(), text: text.trim() });
  await saveMessages();
  refreshDiversos();
}

async function deleteMessage(id) {
  const i = messages.findIndex((m) => m.id === id);
  if (i < 0) return;
  if (msgSession) {
    if (msgSession.idx === i) {
      // TIRAR DO AR antes de anular a sessão. `clearManualText()` sozinho
      // zerava `msgSession` sem mandar `text-hide`: o aviso apagado continuava
      // projetado no telão e na preview, e — como a sessão morria junto — o
      // botão "Tirar do telão" ficava DESABILITADO e a linha sumia da lista.
      // O operador não tinha mais nenhum caminho na aba para tirar o texto do
      // ar; só ⏹ Parar ou projetar outra coisa por cima.
      hideMessage();
      clearMsgSession();
    } else if (msgSession.idx > i) {
      // REINDEXAR: apagar uma mensagem ACIMA da projetada deixava `idx`
      // apontando para a vizinha errada (ou para fora do array). Sintomas:
      // "Mensagem 3" numa lista de duas, nenhuma linha marcada como ativa, e
      // "Projetar no telão" caindo no guard `idx >= messages.length` de
      // `projectMessage` — um botão que não faz nada e não explica por quê.
      msgSession.idx--;
    }
  }
  messages.splice(i, 1);
  await saveMessages();
  refreshDiversos();
}

// ===== Microfone ao vivo (push-to-talk) =====
// Segurar o botão abre o microfone e a voz sai NA PROJEÇÃO, ao vivo. A captura
// acontece no Display, não aqui: um MediaStream não atravessa o
// BroadcastChannel, então quem reproduz é quem abre o microfone (ver startMic
// em display.js). Daqui só sai o comando.
//
// O comando vai por `AVDB.sendCommand`, **não** por `cmd()`: `cmd()` também
// aplica na preview, e a preview é este mesmo aparelho, a centímetros do
// microfone — reproduzir aqui seria realimentação garantida.
let micOn = false;          // o Display confirmou que está captando
let micPressed = false;     // o dedo está no botão agora
let micError = '';

function sendMic(on) {
  micPressed = on;
  AVDB.sendCommand({ type: 'mic', on });
  renderMicUI();
}

// HÁ ONDE A VOZ SAIR?
//
// Quem abre o microfone é o `/display/`, e ele só existe DENTRO da
// `Presentation` — sem TV conectada o `syncPresentation` não cria nenhuma, e
// ninguém consome o comando `mic`. Como ninguém o consome, ninguém responde
// `mic-status`: `micError` ficava vazio, a nota não aparecia, e o único sinal na
// tela era o botão vermelho escrito "No ar" — que é o `micPressed`, nunca uma
// confirmação. O operador segurava o botão achando que falava para a igreja.
//
// AS TELAS DA REDE NÃO CONTAM, e é o erro que uma pergunta por `simpleDisplay()`
// cometeria: elas rodam em `http://`, onde `getUserMedia` não existe, e o
// `setMic` delas sai na guarda de papel. A pergunta é pela TV, e só por ela.
//
// No NAVEGADOR o Display é outra janela, aberta à mão, e o app não tem como
// saber se ela está lá — ali a resposta otimista continua sendo a certa.
function haOndeReproduzirMic() {
  // E A PERGUNTA É PELA `Presentation`, NÃO PELA TELA (shell 59). Quem abre o
  // microfone é o `/display/`, que só existe dentro dela: com a tela listada e a
  // janela no chão o botão era desenhado sobre nada, e o toque gastava a única
  // permissão sensível do app numa ação que não podia funcionar.
  return !window.__NATIVE__ || !!telaoNoAr();
}

function renderMicUI() {
  const btn = document.getElementById('micBtn');
  if (!btn) return;
  const live = micOn || micPressed;
  btn.classList.toggle('live', live);
  const label = btn.querySelector('.mic-btn-label');
  if (label) label.textContent = live ? 'No ar' : 'Microfone';
  // A nota só existe para ERRO (permissão negada, sem microfone…) — é
  // diagnóstico, não instrução de uso.
  const note = document.getElementById('micNote');
  if (note) {
    note.textContent = micError ? micErrorText(micError) : '';
    note.hidden = !micError;
  }
}

function micErrorText(err) {
  // NÃO É UM ERRO DO MICROFONE, e é por isso que a frase não fala dele: o
  // aparelho está bem, o que falta é para ONDE mandar a voz.
  if (err === 'sem-telao') {
    // DESDE A v1.2.20 ELE É UMA CORRIDA, não o caminho normal: sem TV o botão
    // nem é desenhado. Só se alcança aqui se a tela cair ENTRE o desenho e o
    // toque — a guarda fica porque essa janela existe, e um `sendMic` sem
    // destino acenderia "No ar" sobre um telão que já não está lá.
    return 'A TV saiu: a voz não tem mais onde sair.';
  }
  if (err === 'NotAllowedError' || err === 'SecurityError') {
    return 'Permissão de microfone negada. Autorize o app nas configurações do Android.';
  }
  if (err === 'NotFoundError') return 'Nenhum microfone encontrado neste aparelho.';
  if (err === 'unsupported') return 'Este aparelho não expõe captura de áudio ao app.';
  // "EM USO POR OUTRO APP" SAIU (v5.142) — a frase nomeava uma causa e quase
  // sempre a errada. `NotReadableError` é o "não consegui abrir o dispositivo"
  // genérico do WebRTC, e no Android a causa comum aqui não é outro app: é o
  // sistema recusando a sessão de VOZ que o cancelamento de eco pede enquanto o
  // áudio está indo para outro lugar (o telão). O app agora tenta de novo sem o
  // processamento antes de desistir (ver `startMic`), então chegar até esta
  // mensagem já significa que as três tentativas falharam — e aí a única coisa
  // honesta a dizer é o que de fato costuma destravar.
  if (err === 'NotReadableError') {
    return 'O Android não liberou o microfone. Costuma ser uma chamada, um gravador '
      + 'aberto em outro app ou o assistente de voz — feche-os e tente de novo.';
  }
  return 'Não foi possível abrir o microfone (' + err + ').';
}

// A ÚLTIMA TENTATIVA DE CAPTURA, guardada para o Registro.
//
// Ela existe porque o caminho de FALHA não escrevia nada em lugar nenhum: o
// operador via "O Android não liberou o microfone" na tela e o Registro — que é
// o que ele copia e manda — não tinha uma linha sobre o assunto. A frase acusava
// uma chamada ou um gravador aberto, que é a causa MENOS provável, e não havia
// como saber se falhou UM degrau ou os TRÊS.
//
// As perguntas que só esta estrutura separa, e cada uma pede uma ação oposta:
//
//   nenhum dispositivo de entrada  → não é permissão, é o aparelho/privacidade;
//   um degrau falhou, outro abriu  → é o PROCESSAMENTO (a escada fez o trabalho);
//   os TRÊS falharam               → o sistema recusa o microfone a este app;
//   NotAllowedError                → permissão, e a frase de sempre serve.
let micUltima = null;   // { origem, quando, degraus:[{qual,erro}], entradas, ok }

function micRegistrar(origem, degraus, disp, ok) {
  micUltima = { origem, quando: Date.now(), degraus, disp: disp || null, ok, shell: null };
  // A SONDA DO SHELL, só na FALHA e só quando há ponte. Ela responde o que o
  // navegador não enxerga — `AppOps` pode negar `RECORD_AUDIO` com a permissão
  // concedida —, e é assíncrona: o bloco do Registro a mostra quando chegar, e
  // o resto da linha não espera por ela.
  if (!ok && window.__NATIVE__) {
    const alvo = micUltima;
    AVNative.micDiag().then((d) => { if (d) alvo.shell = d; }).catch(() => {});
  }
  // E A LISTA DE ENTRADAS, quando quem registrou não a trouxe. O AO VIVO capta
  // no TELÃO, então a falha chega aqui por `mic-status` e sem lista nenhuma — e
  // é justamente a contagem que separa "não abre" de "não existe", os dois
  // vereditos que pedem ações opostas. Enumerar é LEITURA PURA: não abre o
  // microfone, não pede permissão, e os dois WebViews são o MESMO aparelho, logo
  // a lista do Controle vale pela do telão. Assíncrona pelo mesmo motivo da
  // sonda: o resto da linha não espera por ela.
  if (!disp) {
    const alvo = micUltima;
    micDispositivos().then((d) => { if (d && alvo === micUltima) alvo.disp = d; }).catch(() => {});
  }
  const falhas = degraus.filter((d) => d.erro);
  if (ok) {
    if (falhas.length) {
      diagC('microfone (' + origem + ') abriu no degrau ' + (falhas.length + 1)
        + ' — o(s) anterior(es) deu(deram) ' + falhas.map((d) => d.erro).join(', '));
    }
    return;
  }
  // TODOS OS DEGRAUS NA MESMA LINHA: é a diferença entre "o processamento
  // incomodou" e "o sistema não entrega o microfone", e ela decide o que fazer.
  diagC('microfone (' + origem + ') RECUSADO em ' + degraus.length + ' tentativa(s): '
    + degraus.map((d) => d.qual + '=' + d.erro).join(' · ')
    + ' · entradas de áudio: ' + (disp === null || disp === undefined ? '?' : disp.length));
}

// QUANTOS MICROFONES O NAVEGADOR ENXERGA. Zero separa "o aparelho não entrega
// microfone nenhum a este app" (privacidade do sistema, hardware ocupado) de
// "existe e não abre" — e as duas leem igual na tela.
async function micDispositivos() {
  try {
    if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return null;
    const ds = await navigator.mediaDevices.enumerateDevices();
    return ds.filter((d) => d.kind === 'audioinput')
      .map((d) => ({ deviceId: d.deviceId, label: d.label || '' }));
  } catch (_) { return null; }
}

// O microfone virou uma BARRA, e não mais um disco: ele fica fixo na base da
// aba, fora do acordeão, porque push-to-talk é o único controle daqui que pode
// ser preciso no meio de uma frase — ter que abrir uma seção antes de falar o
// tornaria inútil. Como barra ele custa ~56px de altura em vez de 132 e ainda
// oferece uma área de toque MAIOR (largura inteira), que é o que importa para
// achá-lo sem olhar.
function renderMic() {
  const btn = document.createElement('button');
  btn.type = 'button'; btn.id = 'micBtn'; btn.className = 'mic-btn';
  btn.innerHTML = '<svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor"'
    + ' stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    + '<rect x="9" y="2" width="6" height="11" rx="3"/><path d="M5 10a7 7 0 0 0 14 0"/>'
    + '<line x1="12" y1="17" x2="12" y2="21"/><line x1="8" y1="21" x2="16" y2="21"/></svg>';
  const label = document.createElement('span'); label.className = 'mic-btn-label';
  label.textContent = 'Microfone';
  btn.appendChild(label);

  // Push-to-talk: abre no pointerdown e fecha em QUALQUER forma de soltar.
  // `setPointerCapture` mantém o evento de soltura vindo para cá mesmo se o
  // dedo escorregar para fora do botão — sem isso o microfone ficaria aberto.
  btn.addEventListener('pointerdown', async (e) => {
    e.preventDefault();
    try { btn.setPointerCapture(e.pointerId); } catch (_) {}
    micError = '';
    // ANTES DA PERMISSÃO, e essa ordem é o ponto: sem telão a voz não tem onde
    // sair, e pedir o microfone do Android para uma ação que não pode funcionar
    // é gastar — talvez queimar — a única permissão sensível deste app. É a
    // mesma razão pela qual o pedido não mora na abertura, dois comentários
    // abaixo: um pedido sem contexto é negado por reflexo.
    if (!haOndeReproduzirMic()) { micError = 'sem-telao'; renderMicUI(); return; }
    // A permissão do Android é pedida AQUI, no primeiro uso — não na abertura
    // do app, onde um pedido de gravar áudio sem contexto seria negado por
    // reflexo. No navegador não existe ponte: o getUserMedia do Display pede.
    if (window.__NATIVE__) {
      const ok = await AVNative.requestMic();
      if (!ok) {
        // NO REGISTRO TAMBÉM. A recusa acontece ANTES de qualquer captura, então
        // o telão não emite `mic-status` nenhum e o bloco do microfone ficaria
        // sem uma linha sequer sobre a tentativa — que é exatamente o estado
        // mudo que ele existe para acabar. (Este caminho era do RECADO até a
        // v1.2.17; ele saiu, e o registro veio com ele para cá.)
        micRegistrar('ao vivo', [{ qual: 'permissão do Android', erro: 'NotAllowedError' }],
          null, false);
        micError = 'NotAllowedError'; renderMicUI(); return;
      }
      if (!micPressed && !btn.hasPointerCapture(e.pointerId)) return; // já soltou
    }
    sendMic(true);
  });
  const release = () => { if (micPressed || micOn) sendMic(false); };
  btn.addEventListener('pointerup', release);
  btn.addEventListener('pointercancel', release);

  return btn;
}

// ===== Rodapé da aba Ferramentas: microfone + projetar =====
// "Projetar no telão" saiu do fim de cada painel e veio para cá, ao lado do
// microfone. São as duas ações que MANDAM ALGO PARA A TELA — as únicas com
// efeito fora do celular —, e tê-las sempre no mesmo lugar vale mais do que a
// proximidade com os controles que as configuram: o operador aprende UM ponto
// da tela em vez de um por ferramenta. De quebra, o botão para de descer
// conforme o painel cresce (no sorteio de texto ele ficava abaixo da lista).
function miscProjectState() {
  if (miscTool === 'draw') {
    const live = drawProjecting();
    return { live, disabled: false, hint: '', act: () => (live ? hideDraw() : projectDraw()) };
  }
  if (miscTool === 'chrono') {
    const live = chronoProjecting();
    return { live, disabled: false, hint: '', act: () => (live ? hideChrono() : projectChrono()) };
  }
  // Mensagens: projetar exige saber QUAL, e isso se escolhe tocando na lista.
  // O botão cobre o resto — tirar do ar, e reexibir a que ficou selecionada
  // depois de um "Tirar do telão" (é a ação natural seguinte, e sem ela o
  // operador teria que caçar a linha certa de novo).
  const live = msgProjecting();
  const podeVoltar = !!msgSession;
  return {
    live,
    disabled: !live && !podeVoltar,
    hint: !live && !podeVoltar ? 'Toque numa mensagem da lista para projetar' : '',
    act: () => { if (live) hideMessage(); else if (msgSession) projectMessage(msgSession.idx); },
  };
}

function renderFoot() {
  const wrap = document.createElement('div'); wrap.className = 'mic-wrap';

  const row = document.createElement('div'); row.className = 'misc-foot';
  // UM BOTÃO SÓ. O RECADO (o walkie-talkie da v1.1.26) saiu na v1.2.17: ele
  // existia para cobrir os modelos SEM TV, onde o microfone ao vivo não podia
  // funcionar — e a razão pela qual o ao vivo não funcionava era um defeito
  // nosso (`MODIFY_AUDIO_SETTINGS` ausente do manifest, v1.2.13), não uma
  // limitação. Consertado o ao vivo, o que sobrava do recado era um segundo
  // caminho que INTERROMPE a cena para dizer o que o primeiro diz sem
  // interromper nada.
  // O MICROFONE SÓ EXISTE QUANDO HÁ PARA ONDE MANDAR A VOZ (v1.2.21).
  //
  // Quem capta é o `/display/`, e ele só roda dentro da `Presentation` — sem TV
  // o `syncPresentation` não cria nenhuma e ninguém consome o comando `mic`. As
  // telas da rede também não servem: elas rodam o mesmo `display.js`, e lá o
  // `setMic` sai por `if (TELA) return`.
  //
  // ANTES ELE FICAVA VISÍVEL E RECUSAVA O TOQUE, explicando por quê. Explicar é
  // melhor que mentir (era o conserto da v1.1.20, quando ele acendia "No ar"
  // sem capturar nada), mas não é melhor que NÃO OFERECER: um controle que só
  // sabe dizer que não funciona é um controle a mais para o operador aprender,
  // e a frase aparece no pior momento — com o dedo no botão, no meio do culto.
  //
  // A LARGURA VEM DE GRAÇA: `.misc-foot` é flex e os dois filhos são `flex: 1`,
  // então sozinho o "Projetar no telão" ocupa a linha inteira. Não há regra de
  // CSS para o caso — há a ausência de um irmão.
  if (haOndeReproduzirMic()) row.appendChild(renderMic());

  const st = miscProjectState();
  const proj = document.createElement('button');
  proj.type = 'button';
  proj.id = 'miscProjectBtn';
  proj.className = 'misc-project' + (st.live ? ' live' : '');
  proj.textContent = st.live ? 'Tirar do telão' : 'Projetar no telão';
  proj.disabled = st.disabled;
  if (st.hint) proj.title = st.hint;
  proj.addEventListener('click', st.act);
  row.appendChild(proj);
  wrap.appendChild(row);

  const note = document.createElement('div'); note.id = 'micNote'; note.className = 'mic-note'; note.hidden = true;
  wrap.appendChild(note);

  toolsBodyEl.appendChild(wrap);
  renderMicUI();
}

// ===== Cronômetro / Relógio / Timer (aba Ferramentas) =====
// Terceiro provedor da Camada de Texto, ao lado da Bíblia e das Mensagens, e
// pelo mesmo motivo: o que vai ao telão é um cartão de texto. A diferença é que
// aqui o texto é DERIVADO do tempo, não digitado — ver chronoReading em
// stage.js, e o laço em showText (display.js).
//
// `chrono` é a fonte única do estado; `chronoSession` diz apenas se ele está no
// ar, exatamente como `msgSession.projecting`. Separar os dois é o que permite
// deixar o cronômetro correndo aqui e projetá-lo depois — ou tirá-lo do telão
// sem zerar a contagem.
let chronoSession = null;   // { projecting } | null
let chrono = {
  mode: 'clock',            // 'clock' | 'stopwatch' | 'timer'
  running: false,
  startAt: 0,               // epoch ms da última partida
  baseMs: 0,                // acumulado das voltas anteriores (pausas)
  durationMs: 5 * 60000,    // alvo do timer
  // Relógio SEM segundos por padrão: no telão o que o operador e a igreja
  // querem é a hora, e o dígito dos segundos mudando o tempo todo puxa o olho
  // para um número que não informa nada. Quem precisar liga no chip.
  secs: false,
  h12: false,               // relógio em 12 h
  label: '',                // sublinha dourada no telão (opcional)
};
let chronoPanelTimer = null;

const CHRONO_MODES = [
  { id: 'clock', name: 'Relógio' },
  { id: 'stopwatch', name: 'Cronômetro' },
  { id: 'timer', name: 'Timer' },
];
const CHRONO_PRESETS = [1, 3, 5, 10, 15, 30];

const CHRONO_PREFS_V = 2;   // 2 = relógio passou a nascer sem segundos

function applyChronoPrefs(p) {
  if (!p) return;
  // Preferências gravadas ANTES da v2 carregam `secs: true` só porque era o
  // padrão de então, não porque alguém escolheu — respeitá-las faria a mudança
  // de padrão não chegar a ninguém que já tivesse aberto a aba uma vez.
  const legado = p.v !== CHRONO_PREFS_V;
  // Só as PREFERÊNCIAS voltam do banco. Uma contagem em curso não sobrevive ao
  // fechamento do app de propósito: restaurar um cronômetro que "correu" com o
  // app fechado mostraria um número sem significado nenhum.
  if (CHRONO_MODES.some((m) => m.id === p.mode)) chrono.mode = p.mode;
  if (typeof p.durationMs === 'number' && p.durationMs > 0) chrono.durationMs = p.durationMs;
  if (typeof p.secs === 'boolean' && !legado) chrono.secs = p.secs;
  if (typeof p.h12 === 'boolean') chrono.h12 = p.h12;
  if (typeof p.label === 'string') chrono.label = p.label;
}

function saveChronoPrefs() {
  return AVDB.setState('chronoPrefs', {
    v: CHRONO_PREFS_V,
    mode: chrono.mode, durationMs: chrono.durationMs,
    secs: chrono.secs, h12: chrono.h12, label: chrono.label,
  });
}

function chronoProjecting() { return !!(chronoSession && chronoSession.projecting); }

// O descritor enviado ao telão. É uma CÓPIA: o comando atravessa o barramento
// (e o relay nativo o serializa), então mandar o objeto vivo convidaria a uma
// mutação posterior a "vazar" para um comando já enviado.
function chronoDescriptor() {
  return {
    mode: chrono.mode, running: chrono.running, startAt: chrono.startAt,
    baseMs: chrono.baseMs, durationMs: chrono.durationMs,
    secs: chrono.secs, h12: chrono.h12,
  };
}

// Reenvia o descritor SE estiver no ar. Todo comando de start/pause/zerar/troca
// de modo passa por aqui — é o único ponto que fala com o telão, então nenhum
// caminho novo pode esquecer de atualizar a projeção.
function pushChrono() {
  if (!chronoProjecting()) return;
  cmd({ type: 'text', mode: 'chrono', chrono: chronoDescriptor(), sub: chrono.label || '', view: 'visual' });
}

// Projeta (Display + preview). Encerra Bíblia e Mensagem: a Camada de Texto é
// um cartão só, e só um provedor por vez (mesma regra de projectMessage).
function projectChrono() {
  soUmProvedorDeTexto('chrono');
  chronoSession = { projecting: true };
  view = 'visual';
  persistCurrent();
  cmd({ type: 'text', mode: 'chrono', chrono: chronoDescriptor(), sub: chrono.label || '', view: 'visual' });
  renderControls();
  renderNowPlaying();
  renderSlideNav();
  refreshDiversos();
}

// Tira do telão SEM parar a contagem — espelha hideMessage/hideBibleVerse: um
// áudio de fundo segue tocando, e o cronômetro segue correndo aqui para poder
// voltar ao ar no ponto certo.
function hideChrono() {
  if (!chronoProjecting()) return;
  chronoSession.projecting = false;
  cmd({ type: 'text-hide' });
  renderControls();
  renderNowPlaying();
  renderSlideNav();
  marcarNoAr();   // o selo "● No ar" da linha só sai por aqui — ver `hideBibleVerse`
  refreshDiversos();
}

function clearChronoSession() {
  if (!chronoSession) return;
  chronoSession = null;
  renderNowPlaying();
  renderSlideNav();
  refreshDiversos();
}

function chronoStart() {
  if (chrono.running) return;
  chrono.running = true;
  chrono.startAt = Date.now();
  pushChrono();
  renderChrono();
}

// Pausar CONGELA o acumulado: sem isso, `startAt` sozinho perderia todo o
// trecho anterior na retomada.
function chronoPause() {
  if (!chrono.running) return;
  chrono.baseMs = createStage.chronoElapsed(chrono, Date.now());
  chrono.running = false;
  chrono.startAt = 0;
  pushChrono();
  renderChrono();
}

function chronoReset() {
  chrono.baseMs = 0;
  chrono.startAt = chrono.running ? Date.now() : 0;
  pushChrono();
  renderChrono();
}

function chronoSetMode(mode) {
  if (chrono.mode === mode) return;
  chrono.mode = mode;
  // Trocar de ferramenta zera a contagem: levar o decorrido do cronômetro para
  // dentro de um timer daria um valor que o operador não pediu nem espera.
  chrono.running = false; chrono.baseMs = 0; chrono.startAt = 0;
  saveChronoPrefs();
  pushChrono();
  renderChrono();
}

function chronoSetDuration(ms) {
  chrono.durationMs = Math.max(1000, Math.round(ms));
  saveChronoPrefs();
  pushChrono();
  renderChrono();
}

// Atualiza só o NÚMERO do painel (o resto do painel não muda a cada tick).
// No-op quando a aba não está montada — o laço pode sobreviver a um render.
function renderChronoReadout(r) {
  const el = document.getElementById('chronoRead');
  if (!el) return;
  const rr = r || chronoReading(chrono, Date.now());
  el.textContent = rr.text;
  el.classList.toggle('over', rr.over);
}

function chronoPanelTick() { renderChronoReadout(); }

function startChronoPanelTimer() {
  stopChronoPanelTimer();
  if (chrono.mode === 'clock' || chrono.running) {
    chronoPanelTimer = setInterval(chronoPanelTick, CHRONO_TICK_MS);
  }
}

function stopChronoPanelTimer() {
  if (chronoPanelTimer) { clearInterval(chronoPanelTimer); chronoPanelTimer = null; }
}

function chronoSegBtn(m) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'misc-seg' + (chrono.mode === m.id ? ' active' : '');
  b.textContent = m.name;
  b.addEventListener('click', () => chronoSetMode(m.id));
  return b;
}

function renderChrono() {
  const host = document.getElementById('chronoWrap');
  if (!host) return;
  host.innerHTML = '';

  const modes = document.createElement('div');
  modes.className = 'misc-modes';
  CHRONO_MODES.forEach((m) => modes.appendChild(chronoSegBtn(m)));
  host.appendChild(modes);

  const read = document.createElement('div');
  read.className = 'chrono-read'; read.id = 'chronoRead';
  host.appendChild(read);

  // ---- Timer: alvo da contagem ----
  if (chrono.mode === 'timer') {
    const presets = document.createElement('div');
    presets.className = 'chrono-presets';
    CHRONO_PRESETS.forEach((min) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'misc-chip' + (chrono.durationMs === min * 60000 ? ' active' : '');
      b.textContent = min + ' min';
      b.addEventListener('click', () => chronoSetDuration(min * 60000));
      presets.appendChild(b);
    });
    host.appendChild(presets);

    const row = document.createElement('div');
    row.className = 'misc-row';
    const lab = document.createElement('span');
    lab.className = 'misc-row-label'; lab.textContent = 'Minutos';
    const inp = document.createElement('input');
    inp.type = 'number'; inp.min = '1'; inp.max = '600'; inp.inputMode = 'numeric';
    inp.className = 'misc-num';
    inp.value = String(Math.max(1, Math.round(chrono.durationMs / 60000)));
    // `change` (e não `input`): reprojetar a cada dígito faria o telão piscar
    // valores intermediários enquanto o operador ainda digita.
    inp.addEventListener('change', () => {
      const v = parseInt(inp.value, 10);
      if (isFinite(v) && v > 0) chronoSetDuration(v * 60000);
      else renderChrono();
    });
    row.appendChild(lab); row.appendChild(inp);
    host.appendChild(row);
  }

  // ---- Relógio: formato ----
  if (chrono.mode === 'clock') {
    const opts = document.createElement('div');
    opts.className = 'misc-opts';
    const mk = (name, on, fn) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'misc-chip' + (on ? ' active' : '');
      b.textContent = name;
      b.addEventListener('click', fn);
      return b;
    };
    opts.appendChild(mk('Segundos', chrono.secs, () => {
      chrono.secs = !chrono.secs; saveChronoPrefs(); pushChrono(); renderChrono();
    }));
    opts.appendChild(mk('12 h', chrono.h12, () => {
      chrono.h12 = !chrono.h12; saveChronoPrefs(); pushChrono(); renderChrono();
    }));
    host.appendChild(opts);
  }

  // ---- Transporte (não existe para o relógio: a hora não se pausa) ----
  if (chrono.mode !== 'clock') {
    const acts = document.createElement('div');
    acts.className = 'chrono-actions';
    const run = document.createElement('button');
    run.type = 'button';
    run.className = 'chrono-btn primary';
    // Ícone/rótulo = a AÇÃO, nunca o estado (ver "O ícone mostra a AÇÃO" na
    // arquitetura): correndo, o botão oferece PAUSAR.
    run.textContent = chrono.running ? 'Pausar' : 'Iniciar';
    run.addEventListener('click', () => (chrono.running ? chronoPause() : chronoStart()));
    const zero = document.createElement('button');
    zero.type = 'button'; zero.className = 'chrono-btn';
    zero.textContent = 'Zerar';
    zero.addEventListener('click', chronoReset);
    acts.appendChild(run); acts.appendChild(zero);
    host.appendChild(acts);
  }

  // ---- Sublinha do telão ----
  const labRow = document.createElement('div');
  labRow.className = 'misc-row';
  const labLab = document.createElement('span');
  labLab.className = 'misc-row-label'; labLab.textContent = 'Legenda';
  const labInp = document.createElement('input');
  labInp.type = 'text'; labInp.className = 'misc-text';
  labInp.placeholder = 'opcional — ex: Início do culto';
  labInp.maxLength = 60;
  labInp.value = chrono.label;
  labInp.addEventListener('change', () => {
    chrono.label = labInp.value.trim();
    saveChronoPrefs();
    pushChrono();
  });
  labRow.appendChild(labLab); labRow.appendChild(labInp);
  host.appendChild(labRow);

  // O PRESET vira item do roteiro. A contagem regressiva de abertura é a cena
  // mais previsível de um culto — e era justamente a que não cabia na lista do
  // culto: o operador tinha de lembrar de vir a esta aba, escolher o modo,
  // ajustar os minutos e projetar, com o salão já enchendo. Guardado aqui, um
  // toque no Cronograma faz as quatro coisas.
  host.appendChild(cueSaveRow('Guardar esta contagem', async (destino, btn) => {
    const nome = chrono.label
      || (chrono.mode === 'timer' ? 'Timer ' + Math.round(chrono.durationMs / 60000) + ' min'
        : chrono.mode === 'clock' ? 'Relógio' : 'Cronômetro');
    return criarCue('chrono', {
      mode: chrono.mode, durationMs: chrono.durationMs, label: chrono.label,
      secs: chrono.secs, h12: chrono.h12,
    }, nome, destino, btn);
  }));

  renderChronoReadout();
  startChronoPanelTimer();
}

// UM BOTÃO DE ÍCONE para "guardar isto aqui" (v5.109). Os dois destinos de uma
// cena de roteiro apareciam com rótulo em dois lugares ("Ao Cronograma" /
// "Favoritar" na Bíblia, "Cronograma" / "Favoritos" nas Ferramentas) e com
// ícone só em todos os outros (linha da lista, barra de seleção, folha das
// músicas) — o mesmo par de ações desenhado de duas formas, e a forma com texto
// era justamente a que não cabia na linha em que estava.
//
// O rótulo vira `title` + `aria-label`: sem texto na tela, é ele que nomeia o
// botão para o leitor de tela e para o toque longo.
function cueSaveBtn(icone, titulo, fn) {
  const b = document.createElement('button');
  b.type = 'button'; b.className = 'cue-save-btn';
  b.title = titulo; b.setAttribute('aria-label', titulo);
  b.appendChild(msym(icone));
  b.addEventListener('click', () => fn(b));
  return b;
}

// A linha "guardar isto" das ferramentas: os DOIS destinos possíveis para uma
// cena de roteiro, lado a lado. Uma função só porque cronômetro e sorteio fazem
// exatamente a mesma pergunta — e um terceiro provedor de Camada de Texto que
// apareça amanhã ganha os dois botões sem reescrever nada.
function cueSaveRow(rotulo, montar) {
  const row = document.createElement('div');
  row.className = 'misc-row misc-row--save';
  const lab = document.createElement('span');
  lab.className = 'misc-row-label'; lab.textContent = rotulo;
  const botoes = document.createElement('div'); botoes.className = 'misc-save-btns';
  const mk = (icone, titulo, destino) => {
    botoes.appendChild(cueSaveBtn(icone, titulo, async (b) => {
      const rec = await montar(destino, b);
      if (!rec) responder(b, 'erro', 'Não foi possível guardar');
    }));
  };
  mk(ICON.cronoAdd, 'Adicionar ao Cronograma', 'imports');
  mk(ICON.star, 'Favoritar', 'favs');
  row.append(lab, botoes);
  return row;
}

// ===== Sorteio (aba Ferramentas) =====
// Quarto provedor da Camada de Texto. Sorteia NÚMERO (faixa de/até) ou TEXTO
// (uma lista de opções — nomes, prêmios, perguntas).
//
// **Quem sorteia é só o Controle.** Se cada tela rodasse o próprio
// `Math.random`, o telão e a preview anunciariam ganhadores DIFERENTES — o
// pior defeito possível aqui, e público. O resultado viaja pronto no descritor;
// o que cada lado faz sozinho é apenas a animação até ele (ver drawReading em
// stage.js).
let drawSession = null;   // { projecting } | null
let draw = {
  kind: 'number',   // 'number' | 'text'
  min: 1,
  max: 100,
  pool: [],         // opções de texto
  noRepeat: true,
  label: '',
  value: null,      // último resultado
  used: [],         // já sorteados (só conta com noRepeat)
  seed: 0,
  rollUntil: 0,
};
let drawPanelTimer = null;

const DRAW_ROLL_MS = 1800;   // suspense sem cansar
const DRAW_POOL_CAP = 40;    // amostra do ruído que viaja no comando
const DRAW_SPAN_CAP = 100000;

function drawProjecting() { return !!(drawSession && drawSession.projecting); }

function applyDrawPrefs(p) {
  if (!p) return;
  if (p.kind === 'text' || p.kind === 'number') draw.kind = p.kind;
  if (typeof p.min === 'number') draw.min = p.min;
  if (typeof p.max === 'number') draw.max = p.max;
  if (Array.isArray(p.pool)) draw.pool = p.pool.filter((x) => typeof x === 'string');
  if (typeof p.noRepeat === 'boolean') draw.noRepeat = p.noRepeat;
  if (typeof p.label === 'string') draw.label = p.label;
  // Ao contrário do cronômetro, aqui o RESULTADO e os já sorteados VOLTAM. Um
  // cronômetro restaurado mostraria um tempo que não correu; um sorteio não
  // depende do relógio — e perder "quem já foi sorteado" porque o app fechou no
  // meio faria a próxima rodada repetir alguém, que é o erro que `noRepeat`
  // existe para impedir.
  if (Array.isArray(p.used)) draw.used = p.used.map(String);
  if (typeof p.value === 'string' || typeof p.value === 'number') draw.value = String(p.value);
}

function saveDrawPrefs() {
  return AVDB.setState('drawPrefs', {
    kind: draw.kind, min: draw.min, max: draw.max, pool: draw.pool,
    noRepeat: draw.noRepeat, label: draw.label, used: draw.used, value: draw.value,
  });
}

// OS JÁ SORTEADOS QUE AINDA PERTENCEM À FAIXA.
//
// `draw.used` é o histórico da ferramenta e sobrevive à troca de min/max no
// painel — só a troca número↔texto o zera. Contá-lo INTEIRO era dizer que uma
// rifa nova de 1 a 10, rodada depois de outra de 91 a 100, já tinha saído toda:
// `drawRemaining` devolvia 0, o chip anunciava "0 de 10 restantes" e o botão
// Sortear nascia desabilitado, com o "Reiniciar" como única saída. É o mesmo
// buraco que `projetarSorteioCue` já fecha no caminho do ROTEIRO (zerando
// `draw.used`); aqui filtrar em vez de zerar preserva o histórico de quem só
// ESTREITOU a faixa da mesma rifa.
//
// Só a FONTE do número está aqui; quem responde "acabou?" continua sendo o par
// `drawRemaining`/`pickNumber`, e os dois têm de usar a mesma conta — divergir
// daria um botão habilitado que sorteia `null`.
function drawUsadosNaFaixa() {
  const out = new Set();
  for (const x of draw.used) {
    const n = Number(x);
    if (Number.isFinite(n) && n >= draw.min && n <= draw.max) out.add(n);
  }
  return out;
}

// Quantas opções ainda podem sair. Para número não materializa a faixa: um
// "de 1 até 100000" viraria um array de 100 mil strings a cada render.
function drawRemaining() {
  if (draw.kind === 'text') {
    if (!draw.noRepeat) return draw.pool.length;
    const used = new Set(draw.used);
    return draw.pool.filter((x) => !used.has(x)).length;
  }
  const span = Math.max(0, draw.max - draw.min + 1);
  return draw.noRepeat ? Math.max(0, span - drawUsadosNaFaixa().size) : span;
}

function pickText() {
  const used = new Set(draw.used);
  const cand = draw.noRepeat ? draw.pool.filter((x) => !used.has(x)) : draw.pool;
  if (!cand.length) return null;
  return cand[Math.floor(Math.random() * cand.length)];
}

// Amostragem por REJEIÇÃO enquanto sobra folga, varredura quando aperta: numa
// faixa grande, montar a lista do que falta a cada sorteio é caro à toa; no
// fim, quando quase tudo já saiu, a rejeição é que ficaria cara.
function pickNumber() {
  const span = draw.max - draw.min + 1;
  if (span <= 0) return null;
  if (!draw.noRepeat) return draw.min + Math.floor(Math.random() * span);
  // A MESMA conta do `drawRemaining`: um sorteado fora da faixa atual não pode
  // esgotá-la. Contando `draw.used` inteiro, `used.size >= span` devolvia
  // `null` para uma faixa em que nenhum número tinha saído.
  const used = drawUsadosNaFaixa();
  if (used.size >= span) return null;
  for (let i = 0; i < 200; i++) {
    const n = draw.min + Math.floor(Math.random() * span);
    if (!used.has(n)) return n;
  }
  const left = [];
  for (let n = draw.min; n <= draw.max; n++) if (!used.has(n)) left.push(n);
  return left.length ? left[Math.floor(Math.random() * left.length)] : null;
}

// A amostra do ruído do rolo. Não é o sorteio — é só o que pisca antes de
// assentar —, então uma amostra basta e evita mandar uma lista de 500 nomes
// pelo barramento a cada rodada.
function drawNoisePool() {
  if (draw.kind !== 'text') return null;
  if (draw.pool.length <= DRAW_POOL_CAP) return draw.pool.slice();
  const out = [];
  for (let i = 0; i < DRAW_POOL_CAP; i++) out.push(draw.pool[Math.floor(Math.random() * draw.pool.length)]);
  return out;
}

function drawDescriptor() {
  return {
    kind: draw.kind, value: draw.value, seed: draw.seed, rollUntil: draw.rollUntil,
    min: draw.min, max: draw.max, pool: drawNoisePool(),
  };
}

function pushDraw() {
  if (!drawProjecting()) return;
  cmd({ type: 'text', mode: 'draw', draw: drawDescriptor(), sub: draw.label || '', view: 'visual' });
}

// O SORTEIO FALA NO PRÓPRIO PAINEL (v5.207).
//
// "Escreva as opções antes de sortear" e "todas já saíram" são respostas ao
// botão de sortear, e ele mora num painel da aba Ferramentas que está inteiro
// na tela. A frase ia para uma faixa flutuante no topo; agora ela ocupa o
// lugar do VALOR sorteado — que é exatamente o que o operador está olhando
// quando toca em sortear, e o que ele teria recebido se houvesse o que sortear.
function naoResta(texto) {
  // `#drawRead` é o mostrador do sorteio — o mesmo que exibe o número/nome
  // sorteado e a animação do rolo (ver `renderDrawReadout`). Ele é redesenhado
  // a cada sorteio, então a frase não precisa ser limpa: o próximo sorteio
  // válido a substitui pelo resultado.
  const el = document.getElementById('drawRead');
  if (!el) return;
  el.classList.remove('rolling');
  el.textContent = texto;
}

function doDraw() {
  const v = draw.kind === 'text' ? pickText() : pickNumber();
  if (v == null) {
    naoResta(draw.kind === 'text' && !draw.pool.length
      ? 'Escreva as opções antes de sortear.'
      : 'Todas as opções já saíram. Toque em "Reiniciar" para sortear de novo.');
    return;
  }
  draw.value = String(v);
  if (draw.noRepeat) draw.used.push(String(v));
  // Semente nova a cada rodada: sem ela o ruído do rolo seria idêntico toda
  // vez, e um sorteio que "roda igual" parece decidido de antemão.
  draw.seed = (Math.random() * 0x7fffffff) | 0;
  draw.rollUntil = Date.now() + DRAW_ROLL_MS;
  saveDrawPrefs();
  pushDraw();
  renderDraw();
}

function drawReset() {
  draw.used = [];
  draw.value = null;
  draw.rollUntil = 0;
  saveDrawPrefs();
  pushDraw();
  renderDraw();
}

function projectDraw() {
  soUmProvedorDeTexto('draw');
  drawSession = { projecting: true };
  view = 'visual';
  persistCurrent();
  cmd({ type: 'text', mode: 'draw', draw: drawDescriptor(), sub: draw.label || '', view: 'visual' });
  renderControls();
  renderNowPlaying();
  renderSlideNav();
  refreshDiversos();
}

function hideDraw() {
  if (!drawProjecting()) return;
  drawSession.projecting = false;
  cmd({ type: 'text-hide' });
  renderControls();
  renderNowPlaying();
  renderSlideNav();
  marcarNoAr();   // o selo "● No ar" da linha só sai por aqui — ver `hideBibleVerse`
  refreshDiversos();
}

function clearDrawSession() {
  if (!drawSession) return;
  drawSession = null;
  renderNowPlaying();
  renderSlideNav();
  refreshDiversos();
}

function renderDrawReadout() {
  const el = document.getElementById('drawRead');
  if (!el) return;
  const r = createStage.drawReading(
    { kind: draw.kind, value: draw.value, seed: draw.seed, rollUntil: draw.rollUntil,
      min: draw.min, max: draw.max, pool: draw.pool },
    Date.now(),
  );
  el.textContent = r.text;
  el.classList.toggle('rolling', r.rolling);
  if (!r.rolling) stopDrawPanelTimer();
}

function startDrawPanelTimer() {
  stopDrawPanelTimer();
  if (draw.rollUntil && Date.now() < draw.rollUntil) {
    drawPanelTimer = setInterval(renderDrawReadout, DRAW_FRAME_MS);
  }
}

function stopDrawPanelTimer() {
  if (drawPanelTimer) { clearInterval(drawPanelTimer); drawPanelTimer = null; }
}

function drawChip(name, on, fn) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'misc-chip' + (on ? ' active' : '');
  b.textContent = name;
  b.addEventListener('click', fn);
  return b;
}

function renderDraw() {
  const host = document.getElementById('drawWrap');
  if (!host) return;
  host.innerHTML = '';

  const modes = document.createElement('div');
  modes.className = 'misc-modes';
  // `id` interno × `name` exibido, como em CHRONO_MODES — o id era 'texto'
  // com um ternário remapeando para 'text' logo abaixo, dois nomes para o
  // mesmo valor dentro do mesmo laço.
  [{ id: 'number', name: 'Número' }, { id: 'text', name: 'Texto' }].forEach((m) => {
    const id = m.id;
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'misc-seg' + (draw.kind === id ? ' active' : '');
    b.textContent = m.name;
    b.addEventListener('click', () => {
      if (draw.kind === id) return;
      draw.kind = id;
      // Trocar a natureza do sorteio invalida o histórico: "12" e "Maria" não
      // pertencem ao mesmo conjunto, e manter os dois faria `noRepeat` filtrar
      // por valores que nem podem sair.
      draw.used = []; draw.value = null; draw.rollUntil = 0;
      saveDrawPrefs(); pushDraw(); renderDraw();
    });
    modes.appendChild(b);
  });
  host.appendChild(modes);

  const read = document.createElement('div');
  read.className = 'draw-read'; read.id = 'drawRead';
  host.appendChild(read);

  // ---- Fonte das opções ----
  if (draw.kind === 'number') {
    const row = document.createElement('div');
    row.className = 'draw-range';
    const mk = (lab, val, fn) => {
      const wrap = document.createElement('label');
      wrap.className = 'draw-range-field';
      const s = document.createElement('span'); s.className = 'misc-row-label'; s.textContent = lab;
      const i = document.createElement('input');
      i.type = 'number'; i.inputMode = 'numeric'; i.className = 'misc-num';
      i.value = String(val);
      i.addEventListener('change', () => fn(parseInt(i.value, 10)));
      wrap.appendChild(s); wrap.appendChild(i);
      return wrap;
    };
    row.appendChild(mk('De', draw.min, (v) => {
      if (!isFinite(v)) return renderDraw();
      draw.min = v; if (draw.max < draw.min) draw.max = draw.min;
      if (draw.max - draw.min + 1 > DRAW_SPAN_CAP) draw.max = draw.min + DRAW_SPAN_CAP - 1;
      saveDrawPrefs(); renderDraw();
    }));
    row.appendChild(mk('Até', draw.max, (v) => {
      if (!isFinite(v)) return renderDraw();
      draw.max = v; if (draw.max < draw.min) draw.max = draw.min;
      if (draw.max - draw.min + 1 > DRAW_SPAN_CAP) draw.max = draw.min + DRAW_SPAN_CAP - 1;
      saveDrawPrefs(); renderDraw();
    }));
    host.appendChild(row);
  } else {
    const ta = document.createElement('textarea');
    ta.className = 'draw-pool'; ta.rows = 5;
    ta.placeholder = 'Uma opção por linha\nEx.:\nMaria\nJoão\nAna';
    ta.value = draw.pool.join('\n');
    // `change` (e não `input`): reprojetar/repersistir a cada tecla escreveria
    // no IDB dezenas de vezes enquanto o operador ainda digita a lista.
    ta.addEventListener('change', () => {
      draw.pool = ta.value.split('\n').map((s) => s.trim()).filter(Boolean);
      saveDrawPrefs(); renderDraw();
    });
    host.appendChild(ta);
  }

  // ---- Regras e histórico ----
  const opts = document.createElement('div');
  opts.className = 'misc-opts';
  opts.appendChild(drawChip('Não repetir', draw.noRepeat, () => {
    draw.noRepeat = !draw.noRepeat; saveDrawPrefs(); renderDraw();
  }));
  const left = drawRemaining();
  const info = document.createElement('span');
  info.className = 'draw-info';
  info.textContent = draw.noRepeat
    ? left + ' de ' + (draw.kind === 'text' ? draw.pool.length : Math.max(0, draw.max - draw.min + 1)) + ' restantes'
    : (draw.kind === 'text' ? draw.pool.length + ' opções' : Math.max(0, draw.max - draw.min + 1) + ' números');
  opts.appendChild(info);
  if (draw.used.length) {
    const rst = document.createElement('button');
    rst.type = 'button'; rst.className = 'misc-chip'; rst.textContent = 'Reiniciar';
    rst.addEventListener('click', drawReset);
    opts.appendChild(rst);
  }
  host.appendChild(opts);

  // Os já sorteados, à vista: numa rifa a pergunta seguinte é sempre "quem já
  // saiu?" — e o contador sozinho não responde.
  if (draw.used.length) {
    const hist = document.createElement('div');
    hist.className = 'draw-hist';
    draw.used.slice().reverse().forEach((u, i) => {
      const c = document.createElement('span');
      c.className = 'draw-hist-chip' + (i === 0 ? ' last' : '');
      c.textContent = u;
      hist.appendChild(c);
    });
    host.appendChild(hist);
  }

  // ---- Legenda ----
  const labRow = document.createElement('div');
  labRow.className = 'misc-row';
  const labLab = document.createElement('span');
  labLab.className = 'misc-row-label'; labLab.textContent = 'Legenda';
  const labInp = document.createElement('input');
  labInp.type = 'text'; labInp.className = 'misc-text';
  labInp.placeholder = 'opcional — ex: Sorteio dos visitantes';
  labInp.maxLength = 60;
  labInp.value = draw.label;
  labInp.addEventListener('change', () => {
    draw.label = labInp.value.trim(); saveDrawPrefs(); pushDraw();
  });
  labRow.appendChild(labLab); labRow.appendChild(labInp);
  host.appendChild(labRow);

  // ---- Ações ----
  const go = document.createElement('button');
  go.type = 'button'; go.className = 'draw-go';
  go.textContent = draw.used.length || draw.value ? 'Sortear de novo' : 'Sortear';
  go.disabled = left <= 0;
  go.addEventListener('click', doDraw);
  host.appendChild(go);

  // O sorteio guardado é a CONFIGURAÇÃO (faixa ou lista de opções), nunca um
  // resultado: projetar a cena arma o sorteio e espera o toque em "Sortear" —
  // um ganhador que já aparece pronto ao entrar em cena tira do momento
  // justamente o que ele tem de público.
  host.appendChild(cueSaveRow('Guardar este sorteio', async (destino, btn) => {
    const nome = draw.label || (draw.kind === 'text'
      ? 'Sorteio (' + draw.pool.length + ' opções)'
      : 'Sorteio ' + draw.min + '–' + draw.max);
    return criarCue('draw', {
      kind: draw.kind, min: draw.min, max: draw.max,
      pool: draw.kind === 'text' ? draw.pool.slice() : [], label: draw.label,
    }, nome, destino, btn);
  }));

  renderDrawReadout();
  startDrawPanelTimer();
}

// ===== Mensagens na aba Ferramentas =====
// Deixou de ser um botão flutuante sobre a preview e passou a ser uma seção
// como as outras. O FAB fazia sentido quando Mensagens era a única ferramenta
// avulsa; com três delas, ter uma em cima da preview e duas numa aba era a
// mesma pergunta ("que aviso eu ponho na tela?") respondida em dois lugares
// diferentes. E o espaço sobre a preview é justamente o que menos sobra.
function renderMsg() {
  const host = document.getElementById('msgWrap');
  if (!host) return;
  host.innerHTML = '';

  const list = document.createElement('div');
  list.className = 'msg-list';
  if (!messages.length) {
    const empty = document.createElement('div');
    empty.className = 'empty'; empty.textContent = 'Nenhuma mensagem.';
    list.appendChild(empty);
  } else {
    messages.forEach((m, i) => {
      const active = msgSession && msgSession.projecting && msgSession.idx === i;
      const row = document.createElement('div');
      row.className = 'msg-item' + (active ? ' active' : '');
      const txt = document.createElement('div');
      txt.className = 'msg-text'; txt.textContent = m.text;
      // Tocar PROJETA — e tocar de novo TIRA DO AR (v5.104), exatamente como o
      // versículo central da Bíblia. É o mesmo gesto nos dois sentidos: quem
      // acabou de projetar um aviso tem o dedo onde precisa para tirá-lo, sem
      // procurar outro controle. Tirar do ar não encerra a sessão — a linha
      // segue selecionada e um novo toque a devolve ao telão.
      txt.addEventListener('click', () => {
        if (active) hideMessage(); else projectMessage(i);
      });
      // A mensagem entra no ROTEIRO (v5.103): o aviso de sempre — o convite do
      // sábado, o recado da secretaria — deixa de viver só nesta aba e passa a
      // ocupar o lugar dele na ordem do culto. O que o item guarda é o `id` da
      // mensagem (mais o texto como reserva), então editá-la aqui atualiza o
      // que o roteiro projeta.
      const add = document.createElement('button');
      add.type = 'button'; add.className = 'row-btn';
      add.title = 'Adicionar ao Cronograma';
      add.appendChild(msym(ICON.cronoAdd));
      add.addEventListener('click', async (e) => {
        e.stopPropagation();
        const rec = await criarCue('message', { msgId: m.id, text: m.text },
          m.text.length > 40 ? m.text.slice(0, 40) + '…' : m.text, 'imports', add);
        if (!rec) responder(add, 'erro', 'Não foi possível adicionar');
      });
      // FAVORITAR uma mensagem (v5.104). Ela não tem id de mídia — o que se
      // favorita é a CENA dela —, então a estrela alterna a existência de um
      // cue `message` nos favoritos, em vez de mexer numa lista de ids. Para
      // quem opera é a mesma estrela de todas as outras linhas do app.
      const cueFav = favCue('message', { msgId: m.id, text: m.text });
      const fav = document.createElement('button');
      fav.type = 'button';
      fav.className = 'row-btn fav-btn' + (cueFav ? ' on' : '');
      fav.title = cueFav ? 'Remover dos favoritos' : 'Favoritar';
      fav.innerHTML = starSvg(!!cueFav);
      fav.addEventListener('click', async (e) => {
        e.stopPropagation();
        if (cueFav) {
          await AVDB.listRemove('favs', cueFav.id);
          await recarregarFavoritos();
          responder(fav, 'ok', 'Removido dos favoritos');
        } else {
          await criarCue('message', { msgId: m.id, text: m.text },
            m.text.length > 40 ? m.text.slice(0, 40) + '…' : m.text, 'favs', fav);
        }
        // O redesenho da aba (que troca a estrela vazada pela cheia) espera o
        // pulso terminar: remontar a linha agora arrancaria o botão que está
        // justamente mostrando a confirmação.
        setTimeout(refreshDiversos, PULSO_MS);
      });
      const del = document.createElement('button');
      del.type = 'button'; del.className = 'row-btn';
      del.appendChild(msym(ICON.del));
      del.addEventListener('click', (e) => { e.stopPropagation(); deleteMessage(m.id); });
      row.append(txt, fav, add, del);
      list.appendChild(row);
    });
  }
  host.appendChild(list);

  const add = document.createElement('button');
  add.type = 'button'; add.className = 'msg-add-btn';
  add.textContent = '+ Nova mensagem';
  add.addEventListener('click', addMessage);
  host.appendChild(add);

}

// ===== A aba Ferramentas =====
// Três ferramentas empilhadas não cabiam numa tela de celular. A primeira
// tentativa (v5.31) foi um acordeão, e ele custava caro pelo que entregava:
// três cabeçalhos permanentes comendo altura, e a ferramenta em uso empurrada
// para baixo conforme a posição dela na pilha. Um SELETOR no topo faz o mesmo
// trabalho em UMA linha — as outras ferramentas continuam a um toque, e o
// painel ativo começa sempre no mesmo lugar, o que importa para a memória
// muscular de quem opera sem olhar.
//
// O microfone fica FORA do seletor, fixo na base: é o único controle daqui com
// urgência real (ver renderMic).
let miscTool = 'msg';

const MISC_TOOLS = [
  { id: 'msg', name: 'Mensagens', wrap: 'msgWrap', render: () => renderMsg(), live: () => msgProjecting() },
  { id: 'chrono', name: 'Tempo', wrap: 'chronoWrap', render: () => renderChrono(), live: () => chronoProjecting() },
  { id: 'draw', name: 'Sorteio', wrap: 'drawWrap', render: () => renderDraw(), live: () => drawProjecting() },
];

function renderDiversos() {
  // Só a ferramenta ATIVA é montada, e é o render dela que religa o seu timer.
  // As outras não existem no DOM — nenhum laço batendo em nó invisível.
  stopChronoPanelTimer();
  stopDrawPanelTimer();

  const sw = document.createElement('div');
  sw.className = 'misc-switch';
  MISC_TOOLS.forEach((t) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'misc-tab' + (miscTool === t.id ? ' active' : '');
    b.dataset.tool = t.id;
    const label = document.createElement('span');
    label.textContent = t.name;
    b.appendChild(label);
    // Ponto vermelho = esta ferramenta está PROJETANDO. Fora dela, nada na aba
    // diria isso: trocar de ferramenta não tira do telão a que estava no ar, e
    // sem o ponto o operador teria que voltar em cada uma para descobrir qual é.
    if (t.live()) {
      const dot = document.createElement('span');
      dot.className = 'misc-tab-live';
      b.appendChild(dot);
    }
    b.addEventListener('click', () => {
      if (miscTool === t.id) return;
      miscTool = t.id;
      toolsBodyEl.innerHTML = '';
      renderDiversos();
    });
    sw.appendChild(b);
  });
  toolsBodyEl.appendChild(sw);

  const tool = MISC_TOOLS.find((t) => t.id === miscTool) || MISC_TOOLS[0];
  const panel = document.createElement('div');
  panel.className = 'misc-panel misc-panel--' + tool.id;
  panel.id = tool.wrap;
  toolsBodyEl.appendChild(panel);
  tool.render();

  renderFoot();
}

// Redesenha só a aba Ferramentas (usado quando o estado de uma ferramenta muda
// por fora do painel — ex.: uma mensagem projetada por outro caminho).
function refreshDiversos() {
  if (!ferramentasAbertas()) return;
  toolsBodyEl.innerHTML = '';
  renderDiversos();
}

// ===== A FOLHA DE FERRAMENTAS (v1.3.10) =====
// As Ferramentas eram uma ABA, ao lado do Cronograma e da Bíblia. Elas viraram
// uma FOLHA do Cronograma a pedido do operador — e a mudança não é de navegação,
// é de PARENTESCO: toda ferramenta daqui produz uma CENA que entra no roteiro (a
// mensagem vira cue, o cronômetro e o sorteio são projetados no meio da ordem do
// culto). Ser uma extensão do Cronograma é o que essa relação já era; a aba só a
// escondia atrás de um passo lateral.
//
// (A faixa de abas que hospedava a porta delas saiu na v1.5.0, e com ela a
//  última razão de haver "aba" alguma. O argumento que valia aqui — *a folha
//  cobre a lista, não a substitui, então o Cronograma continua sendo a tela em
//  que se está* — virou a regra do app inteiro: ele tem uma tela e duas folhas.)
function ferramentasAbertas() { return !!toolsSheetEl && !toolsSheetEl.hidden; }

// A DURAÇÃO DA ENTRADA E DA SAÍDA, e ela é UMA — lida do `--tools-anim` do CSS,
// que é o dono. Um número repetido aqui divergiria do outro no primeiro ajuste,
// e o que se veria é a folha sumindo no meio do caminho (ou uma faixa parada
// depois de ela já ter descido).
const TOOLS_ANIM_MS = 220;
let toolsSaindoTimer = null;

function abrirFerramentas() {
  if (!toolsSheetEl || ferramentasAbertas()) return;
  // Uma saída em curso é CANCELADA: reabrir no meio dela deixaria a folha
  // entrando com a classe da descida ainda pendurada, e o `setTimeout` daquela
  // saída a esconderia logo depois — aberta e sumindo sozinha.
  clearTimeout(toolsSaindoTimer);
  toolsSaindoTimer = null;
  toolsSheetEl.classList.remove('saindo');
  toolsSheetEl.hidden = false;
  toolsBodyEl.innerHTML = '';
  renderDiversos();
}

function fecharFerramentas() {
  if (!ferramentasAbertas()) return;
  // Sair com o microfone aberto o deixaria captando sem nada na tela que o
  // mostrasse. O botão é push-to-talk: sem o botão, sem microfone. (Era a mesma
  // guarda do `switchTab`, quando sair daqui era trocar de aba.)
  if (micPressed || micOn) sendMic(false);
  // Os laços dos painéis morrem com a folha — o cronômetro NÃO: ele segue
  // correndo no estado, e a projeção tem laço próprio. Sem isto sobraria um
  // timer de 5 Hz reescrevendo nós que o `innerHTML = ''` já descartou.
  stopChronoPanelTimer();
  stopDrawPanelTimer();
  // A FOLHA DESCE POR ONDE SUBIU (v1.3.13, a pedido do operador). Ela aparecia
  // deslizando e sumia no talo — duas coisas diferentes para o olho, e a
  // segunda lendo como um erro justamente porque a primeira já ensinou a
  // esperar o contrário.
  //
  // O ESTADO CONTINUA SENDO O `hidden`, e ele só cai no FIM: uma folha "fora"
  // por estar transladada continuaria na árvore e capturando toque. A animação
  // é o caminho até o estado, não o estado.
  //
  // O CORPO É ESVAZIADO JUNTO COM O `hidden`, e não agora: limpá-lo aqui
  // deixaria a folha descendo VAZIA, que é o mesmo defeito que o
  // `hideText`/`hidePvText` já evita ("apagá-lo na hora deixaria o cartão vazio
  // visível durante todo o fade").
  //
  // Sem `animationend`: um `prefers-reduced-motion` desliga a animação e o
  // evento nunca chega — a folha ficaria de pé para sempre. O relógio dispara do
  // mesmo jeito, e com a animação desligada os 220 ms passam despercebidos.
  clearTimeout(toolsSaindoTimer);
  toolsSheetEl.classList.add('saindo');
  toolsSaindoTimer = setTimeout(() => {
    toolsSaindoTimer = null;
    toolsSheetEl.classList.remove('saindo');
    toolsSheetEl.hidden = true;
    toolsBodyEl.innerHTML = '';
  }, TOOLS_ANIM_MS);
}

// ===== A FOLHA DA BÍBLIA (v1.5.0) =====
//
// Irmã da de Ferramentas, no mesmo molde e com a mesma mecânica de entrada e
// saída — o que ela tem a mais é o ESTADO. As ~9 guardas espalhadas pelo
// arquivo (o download da versão, o realce do versículo no ar, o redesenho
// quando a leitura chega) continuam valendo: o que era `activeTab === 'bible'`
// é hoje `bibliaAberta()`, e o que era `activeTab === 'imports'` deixou de ser
// uma pergunta — a folha COBRE a lista, não a substitui, então o Cronograma
// está sempre à vista por baixo.
let bibleSaindoTimer = null;

function bibliaAberta() { return !!bibleSheetEl && !bibleSheetEl.hidden; }

function abrirBiblia() {
  if (!bibleSheetEl || bibliaAberta()) return;
  clearTimeout(bibleSaindoTimer);
  bibleSaindoTimer = null;
  bibleSheetEl.classList.remove('saindo');
  // AS DUAS FOLHAS NÃO SE EMPILHAM. Elas são as duas portas do mesmo rodapé, e
  // uma sobre a outra teria duas barras de título na mesma caixa — e dois ✕
  // dizendo coisas diferentes.
  fecharFerramentas();
  bibleSheetEl.hidden = false;
  bibliaNoAr = true;
  // A tela de LIVROS é a raiz: entrar pela porta é começar do começo. Sem isto
  // a Bíblia reabriria no capítulo de uma consulta de meia hora atrás — a mesma
  // razão do `resetarBiblioteca` do acervo.
  bibleScreen = 'books';
  renderBible();
  // Versões/livros e o download da versão INTEIRA na 1ª vez (em segundo plano).
  enterBibleTab();
}

function fecharBiblia() {
  if (!bibliaAberta()) return;
  bibliaNoAr = false;
  clearTimeout(bibleSaindoTimer);
  bibleSheetEl.classList.add('saindo');
  bibleSaindoTimer = setTimeout(() => {
    bibleSaindoTimer = null;
    bibleSheetEl.classList.remove('saindo');
    bibleSheetEl.hidden = true;
    bibleBodyEl.innerHTML = '';
  }, TOOLS_ANIM_MS);
}

// A mensagem está NO AR? Pela PROJEÇÃO, nunca pela existência da sessão — a
// mesma pergunta dos outros cinco provedores de Camada de Texto.
function msgProjecting() { return !!(msgSession && msgSession.projecting); }

function renderLibrary() {
  // O menu de uma linha (v5.258) não sobrevive ao redesenho — ver
  // `renderFolderList`, mesmo motivo.
  fecharAcoesDaLinha();
  const host = libraryEl;
  // Revoga SÓ as URLs que este host criou no render anterior — as do outro
  // host continuam em cena e continuam válidas (ver `thumbUrlsPorHost`).
  (thumbUrlsPorHost.get(host) || []).forEach((u) => URL.revokeObjectURL(u));
  thumbUrlsAtual = [];
  thumbUrlsPorHost.set(host, thumbUrlsAtual);
  host.innerHTML = '';
  // ANTES do desvio por aba, e não no fim: a Bíblia e a raiz dos Favoritos saem
  // por `return` daqui, e o rodapé é da CAIXA da lista, não da lista — deixado
  // para o fim, o "Importar arquivos" do Cronograma continuava desenhado
  // embaixo da grade de livros da Bíblia.
  renderListFoot();

  // (O DESVIO POR ABA saiu na v1.5.0: a Bíblia deixou de disputar este `<ul>` e
  //  passou a desenhar no `#bibleBody` da folha dela. `renderLibrary` voltou a
  //  ser o que o nome diz — o Cronograma, e só ele.)
  const items = libItems;

  // Lista vazia MAS com download em curso: a linha provisória é a única coisa
  // que existe, e ela precisa aparecer — é justamente o primeiro item chegando.
  // Sem isto o operador via "Cronograma vazio" durante todo o download do
  // primeiro vídeo, que é o pior momento possível para essa frase.
  const provisorias = [...libBaixando.entries()]
    .filter(([chave]) => !libItems.some((m) => m.id === chave));

  if (items.length === 0 && !provisorias.length) {
    host.innerHTML = '<li class="empty">Cronograma vazio.</li>';
    return;
  }

  items.forEach((item, i) => {
    const li = document.createElement('li');
    // Bug fix: active highlight only when not in selection mode
    const isActive = !selectionMode && linhaAtiva(item.id);
    // NO AR é outra coisa que "atual" — ver `linhaNoAr`. Na seleção múltipla ele
    // some junto com o realce: ali a tela fala de escolha, não de projeção.
    const noAr = !selectionMode && linhaNoAr(item.id);
    li.className = 'lib-item' + (isActive ? ' active' : '') + (noAr ? ' no-ar' : '')
      + (selected.has(item.id) ? ' selected' : '');
    li.dataset.id = item.id;

    const row = document.createElement('div'); row.className = 'row';

    // A miniatura é o primeiro elemento (flush à esquerda). A seleção múltipla
    // é indicada só pelo highlight azul (.lib-item.selected) — sem ícone de check.
    const thumb = isCue(item) ? cueThumb(item) : thumbEl(item);

    // NOME + SUBTÍTULO numa coluna só (v5.118). O tipo do item era um selo ao
    // lado do nome e disputava largura com ele — some no primeiro título
    // comprido, que é justamente onde ele faz falta. Ver `subtituloItem`.
    const textWrap = document.createElement('div'); textWrap.className = 'row-text';
    const name = document.createElement('span'); name.className = 'row-name'; name.textContent = item.name;
    const sub = document.createElement('span'); sub.className = 'row-sub';
    sub.textContent = subtituloItem(item);
    pintarSubNoAr(sub, noAr);
    // A linha pode estar sendo remontada COM uma falha recente em cena (a lista
    // se redesenha por vários motivos); sem isto, o motivo sumiria no primeiro
    // render e o operador ficaria sem resposta.
    pintarFalha(sub, item.id);
    textWrap.append(name, sub);
    // Item de player do YouTube num shell que sabe baixar: o botão converte o
    // link num arquivo local. Quem diz que ele DEPENDE DO YOUTUBE agora é o
    // subtítulo; aqui ficou só a ação de tirar essa dependência.
    let ytDl = null;
    if (item.kind === 'youtube') {
      const podeBaixar = !!window.__NATIVE__;
      if (podeBaixar && item.url) {
        ytDl = document.createElement('button');
        ytDl.className = 'row-btn';
        ytDl.title = 'Baixar o vídeo e usar o arquivo no lugar do player';
        ytDl.innerHTML = downloadAllIconSvg();
        ytDl.addEventListener('click', async (e) => {
          e.stopPropagation();
          if (ytDl.disabled) return;
          ytDl.disabled = true;
          // A linha JÁ existe: o aviso vai nela, com a chave do próprio item.
          // Se o arquivo desse vídeo já existir (baixado por outro caminho), o
          // `ytArquivo` o devolve e não há download nenhum.
          const rec = await ytArquivo(
            { id: item.youtubeId || extractYouTubeId(item.url), url: item.url, name: item.name },
            { chave: item.id, lista: 'imports' },
          );
          if (!rec) { ytDl.disabled = false; return; }
          // O arquivo TOMA O LUGAR do link, NA MESMA POSIÇÃO: duas linhas com o
          // mesmo nome deixariam o operador adivinhando qual das duas é a que
          // toca em segundo plano. `addMedia` já pendurou o novo no fim do
          // Cronograma, então a troca é "tira a cópia do fim, substitui no
          // lugar do antigo".
          await AVDB.listSet('imports', (ids) => {
            const sem = ids.filter((x) => x !== rec.id);
            const i = sem.indexOf(item.id);
            if (i >= 0) sem[i] = rec.id; else sem.push(rec.id);
            return sem;
          });
          // Agora o Cronograma o segura: sai do slot avulso (no-op se ele nunca
          // esteve lá).
          await AVDB.listRemove('avulsos', rec.id);
          // `gc` decide sozinho se o link some: ele só apaga o que não estiver
          // referenciado em nenhuma outra lista nem num Favorito — se o item
          // antigo também estiver na playlist, ele fica lá, inteiro.
          await AVDB.gc(item.id);
          if (currentId === item.id) await send(rec.id);
          await load();
        });
      }
    }
    // ===== "ADICIONAR À PLAYLIST", NA GAVETA DA LINHA (v5.301) =====
    //
    // Pedido do operador: *"nas opções dos itens do cronograma, especificamente
    // na gaveta de opções, adicione o botão de 'Adicionar a playlist'"*.
    //
    // O Cronograma é a ORDEM do culto; a playlist é a FILA do momento — o bloco
    // de louvores que toca em sequência. Mandar um item de uma para a outra era
    // o único trajeto entre as três listas sem caminho curto: o Favorito já
    // oferece o destino na gaveta dele (`renderItemMenu`), e daqui só se chegava
    // lá por toque longo → seleção múltipla → botão do rodapé.
    //
    // ACRESCENTA, nunca substitui — quem TROCA a fila por este item é o toque no
    // corpo da linha (`onTap` → `replacePlaylistWith`), e são ações opostas.
    //
    // E ELE É UM ALTERNADOR QUE MOSTRA O ESTADO (v5.302) — ver `plBtnDaLinha`.
    //
    // NÃO ENTRA NUMA CENA DE ROTEIRO (`isCue`), e a regra já estava escrita no
    // `onTap`: *"um versículo não é uma fila de reprodução"* — ali um cue projeta
    // sem tocar na playlist. Oferecer o destino aqui contradiria aquele desvio na
    // mesma linha, e o Cronograma é justamente a lista cheia de cues.
    //
    // (O `+` de "Adicionar ao Cronograma" não tem par nesta fileira: aqui o item
    // JÁ está no Cronograma. Ele continua na gaveta de um Favorito e na de um
    // arquivo da pasta do aparelho, que é onde a pergunta faz sentido.)
    const addBtn = (!selectionMode && !isCue(item)) ? plBtnDaLinha(item) : null;

    // A ESTRELA, em toda linha: é ela que torna favoritar um toque só. Fica
    // fora da seleção múltipla porque ali o alvo é o conjunto, não a linha.
    const star = selectionMode ? null : favBtn(item.id, item.name);

    // O PARAR MORA NA MINIATURA (v5.259) — ver `porParar`.
    if (!selectionMode) porParar(thumb, item);

    // Item que JÁ existe e está sendo baixado (converter um link em arquivo):
    // o aviso vai nele mesmo, não na preview.
    // A ESPERA DE UMA RESOLUÇÃO DE LINK (v1.4.21), antes do download: as duas
    // usam a mesma miniatura, e só uma pode estar em curso para o mesmo item.
    porCarregando(li, thumb, item.id);
    const dl = libBaixando.get(item.id);
    if (dl) {
      li.classList.add('baixando');
      li.dataset.dl = item.id;
      const anel = document.createElement('span'); anel.className = 'dl-ring';
      anel.innerHTML = downloadArrowIconSvg();
      thumb.appendChild(anel);
    }

    const parts = [thumb, textWrap];
    if (dl) {
      const pct = document.createElement('span'); pct.className = 'dl-pct';
      pct.textContent = dl.pct >= 0 ? dl.pct + '%' : '';
      parts.push(pct);
    }
    // TUDO ATRÁS DO `⋮` (v5.258) — ver `montarAcoesDaLinha`. A ordem dentro da
    // caixa é a de sempre, da esquerda para a direita: o que se usa mais fica
    // mais perto do dedo que acabou de tocar no `⋮`, que é a direita.
    //
    // Baixando: o botão de converter sai de cena. Ele já está desabilitado, mas
    // continuar desenhando "baixar" ao lado de um anel girando é oferecer a
    // ação que está justamente em curso.
    //
    // Na SELEÇÃO MÚLTIPLA não há `⋮`: ali o alvo é o conjunto, e quem age é a
    // barra do rodapé. (Antes a alça de arrastar continuava na linha; arrastar
    // com meia lista marcada nunca foi uma operação que alguém quisesse.)
    if (!selectionMode) {
      parts.push(...montarAcoesDaLinha(li, [
        // ===== O EXCLUIR É O PRIMEIRO, isto é, o MAIS LONGE do `⋮` (v5.288) =====
        //
        // Pedido do operador: *"coloque o botão de excluir mais à esquerda na
        // lista de opções, já que excluir deve ficar o mais longe de um
        // acidente de clique de fechar opções"*.
        //
        // O `⋮` fica colado na ponta direita da faixa e é o alvo que se toca
        // repetidamente (abre e fecha) — errá-lo por alguns pixels caía
        // justamente no destrutivo. Do outro lado o vizinho é o VAZIO da caixa,
        // que também fecha; a diferença é que ele é uma área larga em que
        // ninguém mira a borda, e não um botão de 40px que se procura.
        //
        // (Isto inverte a ordem que valia desde a v5.258 — "o que se usa mais
        // fica mais perto do dedo que acabou de tocar no `⋮`". Ela continua
        // valendo para o resto da fileira: o que muda é que o destrutivo deixa
        // de disputar essa vizinhança.)
        //
        // ===== E A ORDEM DO RESTO É A QUE O OPERADOR DITOU (v5.302) =====
        //
        // *"Ajuste a ordem dos botões de opções do cronograma para, da esquerda
        // para a direita: excluir, renomear, favoritar, adicionar à playlist,
        // subir e descer."*
        //
        // Ela agrupa por NATUREZA, que é o que a ordem anterior não fazia: o que
        // mexe no ITEM (excluir, renomear), o que mexe em ONDE ele está
        // (favoritar, playlist) e o que mexe na POSIÇÃO dele (↑↓). Antes o
        // renomear caía entre a playlist e o par de ordem, separando os dois
        // pares que se parecem.
        botaoExcluirDaLinha(item, 'imports', () => load()),
        // RENOMEAR (v5.288), com a mesma guarda do excluir: na pasta do aparelho
        // o nome vem do arquivo, e um nome só no registro seria desfeito na
        // varredura seguinte.
        botaoRenomearDaLinha(item, () => load()),
        star,
        addBtn,
        // O "baixar o vídeo" de uma linha de LINK não está na ordem pedida — ele
        // só existe nessa linha. Entra DEPOIS dela, para não partir ao meio a
        // sequência que o operador ditou.
        (ytDl && !dl) ? ytDl : null,
        // O PAR ↑↓ (v5.285), no lugar da alça de arrastar. Só onde há ordem a
        // mexer: a pasta do aparelho não é uma lista reordenável.
        ...botoesDeOrdem('imports', item.id, i, items.length),
        // (O EXCLUIR subiu para o começo desta lista na v5.288 — ver a nota lá.
        // NA PASTA DO APARELHO ELE NÃO ENTRA, desde a v5.271: ali "excluir"
        // apaga o ARQUIVO físico, e essa limpeza tem donos próprios
        // (`deleteSelected`, com o `opfsDeleteFile` e o `purgeCatalogRecords`).
        // Um mesmo ícone com dois alcances conforme a tela é a pior forma de
        // oferecer um destrutivo.)
      ], 'imports:' + item.id));
    }
    row.append(...parts);
    li.appendChild(row);
    attachRowGestures(row, item);
    host.appendChild(li);
  });

  // As linhas PROVISÓRIAS vão no fim, que é para onde o item vai quando
  // existir: `addMedia` sempre pendura no fim do Cronograma.
  provisorias.forEach(([chave, reg]) => host.appendChild(libBusyRow(chave, reg)));
}

// Importar arquivos é uma ação sobre ESTA lista, não uma aba — mas até a v5.106
// ele era o último `<li>` do `<ul>` rolável, e com trinta itens no Cronograma
// (que é o culto normal) alcançá-lo exigia rolar a lista inteira. Agora mora no
// RODAPÉ FIXO da caixa da lista (`#listFoot`), fora da rolagem: continua junto
// do lugar onde os arquivos vão cair e está sempre a um toque.
// O `<input type="file">` continua dentro de um <label>, que é o que dispensa
// JS pra abrir o seletor.
//
// A função reconstrói só o que é DELA: o rodapé é dividido com a barra de
// seleção (ver `hostSelbar`), e um `innerHTML = ''` aqui tiraria a `#selbar` do
// documento — o nó é um só, movido, e perdê-lo significa perder os listeners.
// O MOLDE DAS DUAS PORTAS LATERAIS do rodapé (v1.5.0): ícone em cima da caixa,
// rótulo ao lado, `title` igual ao `aria-label`. Uma função e não duas cópias —
// elas nasceram iguais e a terceira porta que aparecer nasce igual também.
function botaoDoRodape(id, cls, titulo, rotulo, desenho) {
  const b = document.createElement('button');
  b.type = 'button';
  b.id = id;
  b.className = cls;
  b.title = titulo;
  b.setAttribute('aria-label', titulo);
  b.innerHTML = '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor"'
    + ' stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    + desenho + '</svg>';
  const t = document.createElement('span');
  t.textContent = rotulo;
  b.appendChild(t);
  return b;
}

function renderListFoot() {
  const antiga = listFootEl.querySelector('.import-row');
  // O seletor de arquivos mora DENTRO da linha antiga; tirá-lo antes de
  // descartá-la é o que preserva o listener de `change` (mesmo cuidado do
  // fantasma da troca de aba).
  if (fileEl.parentElement && fileEl.parentElement.closest('.import-row')) mainEl.appendChild(fileEl);
  if (antiga) antiga.remove();
  // O rodapé some quando não tem inquilino nenhum. Não dá para deixar isso com
  // um `:empty` no CSS: a `#selbar` MORA aqui mesmo fora da seleção (escondida
  // pelo `hidden`), então o rodapé nunca fica de fato vazio — e um filho de
  // altura zero ainda consome o `gap` do `<main>`, que viraria uma faixa de ar
  // acima da caixa de controles em toda aba sem rodapé.
  const temImport = !selectionMode;
  const temSelbar = selectionMode && selbarEl.parentElement === listFootEl;
  listFootEl.hidden = !temImport && !temSelbar;
  if (!temImport) return;
  const li = document.createElement('div');
  li.className = 'import-row';

  // UM botão só, para TODO arquivo — inclusive apresentação (v5.99). O que
  // muda é só QUEM abre o seletor:
  //
  //  - no app (shell ≥ 21), o seletor do SISTEMA (`AVNative.pickDoc`). É o
  //    único caminho que serve para o PDF: o `<input type="file">` devolve um
  //    `File` — bytes já lidos —, e quem desenha o PDF é o shell, que precisa
  //    do ARQUIVO; mandar os bytes de volta pela ponte inverteria o princípio
  //    dela ("URLs servíveis, nunca bytes"). O `content://` que o seletor
  //    entrega é a mesma porta por onde as pastas do dispositivo já entram.
  //  - no navegador (e num shell antigo), o `<input type="file">` de sempre,
  //    dentro de um <label>, que é o que dispensa JS para abrir o seletor.
  //
  // O rótulo é o mesmo nos dois casos: o operador escolhe o ARQUIVO, não a
  // porta por onde ele entra.
  const usaSeletorNativo = !!window.__NATIVE__;
  const label = document.createElement(usaSeletorNativo ? 'button' : 'label');
  if (usaSeletorNativo) label.type = 'button';
  label.className = 'import-btn';
  label.title = 'Importar arquivos (mídia, PDF ou PowerPoint)';
  label.innerHTML = '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor"'
    + ' stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    + '<path d="M7 3h7l5 5v11a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2z"/>'
    + '<path d="M14 3v5h5"/>'
    + '<line x1="12" y1="12" x2="12" y2="17.6"/>'
    + '<line x1="9.2" y1="14.8" x2="14.8" y2="14.8"/></svg>';
  const txt = document.createElement('span');
  // "Importar", e não "Importar arquivos" (v1.5.0): a faixa passou a ter TRÊS
  // portas em partes iguais, e MEDIDO em 430px o nome inteiro saía com
  // reticências — que é pior que a palavra curta, porque as reticências não
  // dizem qual palavra foi cortada. O `title` guarda a frase completa (e o que
  // ela inclui: mídia, PDF ou PowerPoint).
  txt.textContent = 'Importar';
  label.appendChild(txt);
  if (usaSeletorNativo) label.addEventListener('click', importarPeloSistema);
  else label.appendChild(fileEl); // o MESMO input de sempre, só reposicionado

  // O BOTÃO DE FAVORITOS SAIU DAQUI (v5.104). Ele fazia par com "Importar" — as
  // duas respondendo "de onde vem a mídia?" —, mas era também a ÚNICA porta da
  // gaveta, e uma porta no fim de uma lista rolável não é acesso rápido: com
  // trinta itens no Cronograma era preciso rolar tudo para chegar num favorito.
  // Agora ela mora no cabeçalho FIXO, com rótulo, alcançável de qualquer aba.
  li.appendChild(label);

  // ===== AS TRÊS PORTAS DO CRONOGRAMA (v1.5.0) =====
  //
  // Pedido do operador: *"na base dela se mantém o botão de importar arquivos
  // no centro, a esquerda o botão de bíblia e a direita o botão de
  // ferramentas"*.
  //
  // Com o Cronograma virando a tela ÚNICA, este rodapé passou a ser a
  // navegação inteira do app: é o único ponto que fica sempre à vista (fora do
  // `<ul>` rolável), e é dele que saem os dois lugares que não são a lista. A
  // Biblioteca não entra aqui — ela tem a barra própria na caixa de controles.
  //
  // OS TRÊS TÊM RÓTULO desde a v1.5.0, a pedido (*"coloque um texto no botão de
  // ferramentas"*). O argumento anterior contra o texto — *"dois nomes lado a
  // lado numa faixa de celular empurrariam o primeiro para reticências"* —
  // valia para uma linha em que "Importar arquivos" era `flex: 1` e os irmãos
  // eram quadrados; com TRÊS portas de mesmo peso, deixar duas mudas faria a
  // faixa dizer que a do meio é a única que importa, e ela não é. Quem paga a
  // conta da largura é o `.import-row`, que reparte as três em partes iguais e
  // deixa cada rótulo encolher com reticências por conta própria.
  //
  // A ORDEM É A DO PEDIDO, e ela é a da leitura: o que se CONSULTA à esquerda,
  // o que ENTRA no roteiro no centro, o que se PRODUZ à direita.
  const bib = botaoDoRodape('bibleBtn', 'lib-foot-btn',
    'Bíblia: livros, capítulos e versículos', 'Bíblia',
    '<path d="M4 4.5A1.5 1.5 0 0 1 5.5 3H19v15H5.5A1.5 1.5 0 0 0 4 19.5z"/>'
    + '<path d="M4 19.5A1.5 1.5 0 0 0 5.5 21H19"/>'
    + '<line x1="11.5" y1="6.4" x2="11.5" y2="11.6"/>'
    + '<line x1="9.2" y1="8.4" x2="13.8" y2="8.4"/>');
  bib.addEventListener('click', abrirBiblia);
  li.insertBefore(bib, label);

  const ferr = botaoDoRodape('toolsBtn', 'tools-btn',
    'Ferramentas: mensagens, tempo, sorteio e microfone', 'Ferramentas',
    '<rect x="3.5" y="3.5" width="7" height="7" rx="1.6"/>'
    + '<rect x="13.5" y="3.5" width="7" height="7" rx="1.6"/>'
    + '<rect x="3.5" y="13.5" width="7" height="7" rx="1.6"/>'
    + '<rect x="13.5" y="13.5" width="7" height="7" rx="1.6"/>');
  ferr.addEventListener('click', abrirFerramentas);
  li.appendChild(ferr);

  listFootEl.appendChild(li);
}

// Os tipos que o seletor do sistema oferece. PDF e PPTX entram na MESMA lista
// dos de mídia: uma apresentação é um arquivo como qualquer outro, e separá-la
// num botão próprio faria o operador escolher a PORTA antes de escolher o
// arquivo. `.ppt` (o binário anterior a 2007) e `.odp` ficam de fora porque o
// app não sabe desenhá-los — oferecer e depois falhar é pior que não oferecer.
const IMPORT_MIMES = [
  'image/*', 'video/*', 'audio/*',
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
].join(',');

async function importarPeloSistema() {
  const escolhidos = await AVNative.pickDoc(IMPORT_MIMES);
  if (!escolhidos || !escolhidos.length) return;   // o operador desistiu
  // Pelo MESMO caminho do compartilhamento: os itens já vêm no formato
  // `{ name, type, url }` que ele espera, e é lá que mora o roteamento por
  // tipo. Duas rotas de importação divergiriam na primeira correção.
  await importShare({ files: escolhidos });
}

// "N de M músicas" — e o M NÃO é o tamanho da lista (v5.134). Uma música cuja
// origem não tem áudio (`semAudio`, ver `ensureSongVariant`) nunca vira arquivo
// no aparelho: mantê-la no denominador travava o contador em 53/54 para sempre,
// ao lado de um chip dizendo "Completo offline" — as duas frases certas pela
// sua própria régua, contando coisas diferentes na mesma linha. Ela sai dos
// DOIS lados da fração, que é o mesmo que `colecaoCompleta` já faz.
function songsBaixaveis(id) {
  return collSongs(id).filter((s) => !s.semAudio);
}
function countDownloaded(id) {
  return collSongs(id).filter((s) => s.fileIdFull).length;
}

// (O ícone de antena `wifiIconEl()` saiu na v5.73 com o chip "Rede" das opções
// do álbum, seu único consumidor. A regra de rede não mudou: quem decide se a
// sincronização em massa pergunta antes de usar dados móveis continua sendo
// `isConfirmedWifi()`, e ela o diz na hora, no diálogo — que é onde a
// informação tem consequência. Um chip permanente repetindo o estado da rede
// em cada álbum aberto era ruído entre dados sobre o ÁLBUM.)

// ===== OS BOTÕES DA LINHA VIRAM UM SÓ =====
//
// Cada botão na linha era um pedaço a menos do nome — a única coisa dela que
// não se adivinha. Medido numa lista de 368px: Cronograma com estrela +
// arrastar deixava 194px; Favoritos com estrela + Cronograma + arrastar, 152px.
// Nenhum deles é usado com a frequência com que se LÊ a lista.
//
// Agora a linha tem UM botão à direita (`⋮`) e as ações aparecem por cima dela,
// da direita para a esquerda. Paga-se um toque a mais para agir; ganha-se a
// lista legível nos 95% do culto em que ela só é lida.
//
// O "Tirar do ar" não perdeu o caminho curto: o segundo toque no CORPO da linha
// já faz isso. O botão dentro do menu é o mesmo desfecho, nomeado.
//
// SVG inline porque `more_vert` (U+E5D4) NÃO está no subset de
// `material-symbols.woff2` (31 codepoints). Glifo ausente desenha um retângulo
// vazio, sem erro em lugar nenhum.
function dotsIconSvg() {
  return '<svg viewBox="0 0 24 24" width="19" height="19" fill="currentColor" aria-hidden="true">'
    + '<circle cx="12" cy="5" r="1.9"/><circle cx="12" cy="12" r="1.9"/><circle cx="12" cy="19" r="1.9"/>'
    + '</svg>';
}

// O LÁPIS de renomear. SVG inline, e nunca um glifo: a fonte é um SUBSET
// ESTÁTICO de pouco mais de trinta codepoints, e `edit` não está nele — um
// codepoint ausente desenha um RETÂNGULO VAZIO, sem erro em lugar nenhum (a
// armadilha da v5.184 e da v5.200).
function pencilIconSvg() {
  return '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" '
    + 'stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    + '<path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z"/>'
    + '</svg>';
}

/**
 * RENOMEAR UM ITEM, na gaveta da própria linha (v5.288).
 *
 * Pedido do operador: *"adicione renomear nas opções individuais dos itens do
 * cronograma"*. Renomear já existia, e só para UM item de cada vez — atrás do
 * toque longo, do modo de seleção múltipla e de um botão no rodapé
 * (`renameSelected`), isto é, quatro gestos para trocar uma palavra. É a mesma
 * correção que o excluir recebeu na v5.272, pela mesma razão.
 *
 * NA PASTA DO APARELHO ELE NÃO ENTRA, como o excluir: ali a lista é derivada do
 * sistema de arquivos a cada sincronização, e um nome escrito só no registro
 * seria desfeito na próxima varredura — sem erro, e sem nada que o explicasse.
 *
 * E O CAMPO MORA NA PRÓPRIA FAIXA desde a v1.4.25 (`pedirRenomearNaLinha`), e
 * não num diálogo de tela cheia: renomear é a única ação do app em que o nome
 * VELHO precisa continuar à vista enquanto o novo é escrito.
 */
function botaoRenomearDaLinha(item, depois) {
  const b = document.createElement('button');
  b.className = 'row-btn row-renomear';
  b.title = 'Renomear';
  b.setAttribute('aria-label', 'Renomear');
  b.innerHTML = pencilIconSvg();
  b.addEventListener('click', (e) => {
    e.stopPropagation();
    pedirRenomearNaLinha(b, item, depois);
  });
  return b;
}

/**
 * O "Tirar do ar" DENTRO da miniatura da linha (v5.259, pedido do operador:
 * *"o parar deve ficar na própria thumbnail do item"*).
 *
 * Ele nasceu na fileira da direita (v5.177) e passou uma versão dentro do menu
 * `⋮` (v5.258) — os dois lugares erram a mesma coisa: enquanto a linha está no
 * ar, tirá-la de lá é a ÚNICA decisão que ela oferece, e ela ficava atrás de um
 * toque (abrir o menu) ou disputando espaço com ações que ninguém quer ali.
 *
 * Na miniatura ele resolve três coisas de uma vez: o alvo passa a ser o
 * quadrado inteiro (40px, contra os 34px de um botão de fileira), ele não
 * disputa um pixel com o nome, e fica sobre a única parte da linha que já
 * estava dizendo "é este item aqui" — a capa, que com a mídia no ar é
 * exatamente o que está projetado.
 *
 * Ele é construído SEMPRE e escondido por CSS (`.lib-item.no-ar .row-stop`),
 * porque quem liga e desliga o estado é `marcarNoAr`, que roda a cada
 * `display-status` (~4 Hz) e só troca classes: remontar botão nesse ritmo
 * perderia listeners e trabalho à toa.
 */
function porParar(thumb, item) {
  const b = document.createElement('button');
  b.className = 'row-stop';
  b.title = 'Tirar do ar';
  b.setAttribute('aria-label', 'Tirar do ar');
  // O MESMO glifo do Parar do transporte (`&#xe047;` no `index.html`), escrito
  // por escape: ele não é um símbolo NOVO, é o de lá, na linha.
  b.appendChild(msym(''));
  b.addEventListener('click', (e) => {
    e.stopPropagation();
    retirarDoAr(item);
  });
  thumb.appendChild(b);
  return b;
}

// A linha com o menu aberto — UMA por vez. Duas abertas seriam duas faixas
// cobrindo dois nomes, e o operador teria de fechar a errada para ler.
let linhaAcoesAberta = null;
// A confirmação de exclusão aberta — UMA por vez, pelo mesmo motivo, e guardada
// como a função que a DESFAZ (ver `pedirConfirmacaoNaLinha`). Declarada aqui, ao
// lado da irmã, e não junto da função: `fecharAcoesDaLinha` a lê e é escrita
// antes dela — um `let` só existe depois da linha que o declara.
let desfazerConfirmacao = null;
// Qual linha deve REABRIR a gaveta no próximo desenho (v5.285). `moverNaLista`
// a escreve porque `load()` reconstrói a lista inteira: o `li` que tinha a
// gaveta aberta deixa de existir, e sem isto cada casa de reordenação custaria
// reabrir a gaveta à mão. É consumida UMA vez, por quem a encontra.
//
// A chave é `lista:id`, e não o id sozinho: o MESMO item aparece em mais de uma
// lista ao mesmo tempo (um favorito que também está no Cronograma é o caso
// normal), e com o id nu o redesenho do Cronograma consumiria a marca e abriria
// a gaveta na linha errada, noutra tela.
let reabrirAcoesEm = null;
function fecharAcoesDaLinha() {
  // A confirmação vive DENTRO da faixa: fechá-la sem desfazer a pergunta
  // deixaria a linha com a miniatura de lixeira e nenhum botão que a explique.
  fecharConfirmacaoNaLinha();
  if (linhaAcoesAberta) linhaAcoesAberta.classList.remove('acoes-abertas');
  linhaAcoesAberta = null;
}
/**
 * "A gaveta que está aberta AGORA continua aberta depois do próximo redesenho."
 *
 * (v5.288) Uma ação da faixa pode redesenhar a lista inteira — favoritar o faz
 * (`toggleFav` → `renderLibrary`, depois do pulso) —, e um redesenho apaga o
 * `li` que tinha a gaveta. Sem isto, marcar uma estrela fechava as opções: o
 * operador precisava reabri-las para fazer a segunda coisa que ele tinha ido
 * fazer ali.
 *
 * Ela reusa o `reabrirAcoesEm` do par ↑↓ e a CHAVE que `montarAcoesDaLinha`
 * carimbou no `li` — sem a chave não haveria como reencontrar a linha, porque o
 * mesmo item vive em duas listas ao mesmo tempo (um favorito que também está no
 * Cronograma é o caso normal).
 */
function manterAcoesAbertas() {
  if (linhaAcoesAberta && linhaAcoesAberta.dataset.acoesChave) {
    reabrirAcoesEm = linhaAcoesAberta.dataset.acoesChave;
  }
}
function alternarAcoesDaLinha(li) {
  const abrir = linhaAcoesAberta !== li;
  fecharAcoesDaLinha();
  if (!abrir) return;
  li.classList.add('acoes-abertas');
  linhaAcoesAberta = li;
}
// Tocar em QUALQUER outro lugar fecha. Na fase de CAPTURA e por `pointerdown`,
// e não por `click`, e a razão MUDOU de dono sem mudar de forma: até a v5.284
// era a alça de arrastar (que morava dentro do menu, capturava o ponteiro e
// nunca produzia um `click`); a alça saiu na v5.285, e o que sustenta o
// `pointerdown` hoje é a PROPRIEDADE que ele sempre teve e que a alça apenas
// exemplificava: um gesto que não termina em `click` — rolar a lista de baixo é
// o caso comum — fecha o menu do mesmo jeito. A CAPTURA continua sendo o único
// caminho pelo mesmo motivo de sempre: todo botão de linha deste app chama
// `stopPropagation` no próprio `click`.
document.addEventListener('pointerdown', (e) => {
  if (!linhaAcoesAberta) return;
  if (e.target.closest && e.target.closest('.acoes-abertas')) return;
  fecharAcoesDaLinha();
}, true);

/**
 * ===== A CONFIRMAÇÃO DE EXCLUIR MORA NA PRÓPRIA LINHA (v5.301) =====
 *
 * Pedido do operador: *"remova os popups de confirmar exclusão, para que todas
 * essas confirmações sejam inseridas direto na UI… no cronograma, coloque a
 * confirmação na própria gaveta de opções, com um botão de cancelar e
 * confirmar; durante o processo de exclusão pode trocar o ícone da thumbnail
 * pela lixeira, para ilustrar que está confirmando uma exclusão"*.
 *
 * O modal fazia o que todo modal faz: TIRAVA O ALVO DE CENA. A pergunta era
 * "excluir este item?" e a tela que a fazia não mostrava mais item nenhum — o
 * operador confirmava de memória, num app cuja lista tem trinta linhas com
 * nomes parecidos. É a mesma correção que a faixa flutuante recebeu na v5.207
 * (*"o feedback mora na interface de origem"*), aplicada agora à PERGUNTA.
 *
 * O par nasce NA FAIXA que hospeda o botão que o pediu — a caixa do `⋮` no
 * Cronograma e na fila, a `.fav-acoes` na gaveta dos Favoritos. Ele não conhece
 * nenhuma das duas por nome: pergunta ao próprio botão quem é o pai dele, e por
 * isso a próxima lista que ganhar um excluir já nasce com a confirmação certa.
 *
 * DECISÕES QUE PRECISAM ESTAR DITAS:
 *
 *  · **Ele entra no COMEÇO da faixa**, não no fim. A `.row-acoes` escalona a
 *    entrada dos botões por `nth-last-child` (v5.269), que conta a partir do
 *    FIM: um irmão acrescentado depois deles deslocaria o índice de todos, e a
 *    animação que o operador pediu sairia trocada.
 *  · **A miniatura vira uma LIXEIRA**, pelo mesmo mecanismo do "Tirar do ar"
 *    (`.row-stop`): o conteúdo dela é escondido por CSS e o desenho novo entra
 *    por cima. É a única parte da linha que a faixa não cobre, e por isso a
 *    única que ainda pode dizer de QUAL item é a pergunta. A fila da playlist
 *    não tem miniatura — ali a linha é só o nome, e o `if` cobre isso.
 *  · **UMA por vez**, como a gaveta: duas linhas perguntando ao mesmo tempo
 *    seriam duas lixeiras e quatro botões numa lista de trinta nomes.
 *  · **Tudo que fecha a gaveta CANCELA**: o `⋮` outra vez, o toque fora, o
 *    redesenho da lista (todos passam por `fecharAcoesDaLinha`) e o fechamento
 *    da gaveta de um favorito. O erro possível aqui é o seguro — perder a
 *    pergunta custa um toque; herdar um "sim" pendente não tem volta.
 *  · **A frase que o diálogo dizia** ("os arquivos só são apagados se ele não
 *    estiver em mais nenhuma lista") não cabe nos ~250px da faixa e não sumiu:
 *    ela é o `title`/`aria-label` do botão que a executa, que é onde o toque
 *    longo e o leitor de tela a procuram.
 */
// FECHA O QUE ESTIVER ABERTO NA FAIXA, e desde a v1.4.25 isso é mais que a
// pergunta da exclusão: o campo de renomear entra pela mesma porta e sai por
// esta. O nome ficou — os treze chamadores dizem "desfaz o que a faixa está
// mostrando", que continua sendo exatamente o que ele faz.
function fecharConfirmacaoNaLinha() {
  const desfazer = desfazerConfirmacao;
  desfazerConfirmacao = null;
  if (desfazer) desfazer();
}

/**
 * ===== A FAIXA TROCA DE CONTEÚDO, E ISSO É UM MECANISMO (v1.4.25) =====
 *
 * A pergunta da exclusão (v5.301) e o campo de renomear (v1.4.25) fazem a MESMA
 * coisa com a mesma caixa: escondem os botões de opção, põem outro bloco no
 * lugar deles e devolvem tudo ao fim. Escrever a segunda por cópia da primeira
 * era garantir que uma delas esquecesse uma das cinco coisas que as duas têm de
 * fazer — fechar a anterior, marcar a faixa, marcar o `li`, publicar o desfazer
 * e devolvê-lo.
 *
 * Ele devolve a CAIXA VAZIA, para quem chamou preencher — ou `null` quando o
 * botão não tem faixa (uma linha remontada sob o dedo).
 *
 * ===== E A COLUNA DO `⋮` É DO PROCESSO ENQUANTO ELE DURA (v1.4.27) =====
 *
 * Pedido do operador: o `⋮` *"contradiz o fluxo dos botões, pois o processo de
 * exclusão e o de renomear já devem ter métodos de retorno/cancelamento"*, e a
 * capa deve sair junto *"para ter mais espaço tanto para a gaveta de opções
 * como para a barra de renomeação"* — com a coluna dele virando o *"botão
 * indicativo"* do processo.
 *
 * Quem esconde as duas colunas é o CSS, por `:has(> .row-acoes.confirmando)`;
 * daqui sai só o ELEMENTO que ocupa a que sobrou. E ele não é enfeite: sem um
 * ocupante, esconder o `⋮` encolheria a linha e a faixa dançaria de largura no
 * meio de uma pergunta destrutiva.
 *
 * `opts`:
 *  · `classe`  — a classe extra da caixa, para o CSS distinguir os dois usos.
 *  · `marca`   — a classe que vai no `li` enquanto ela está aberta. OPCIONAL, e
 *    hoje só a exclusão a usa: é ela que troca a miniatura pela lixeira no
 *    CAMINHO B (ver abaixo).
 *  · `simbolo` — o elemento que ocupa a coluna do `⋮`.
 *  · `semSlot(simbolo, cx)` — o CAMINHO B, para a linha que não tem `⋮`: a
 *    gaveta dos FAVORITOS, cuja faixa fica abaixo da linha em vez de cobri-la.
 *    Cada processo escolhe o dele, e são destinos diferentes de propósito — o
 *    ✓ do renomear é um BOTÃO e precisa continuar alcançável (volta para dentro
 *    da faixa), a lixeira é um INDICADOR (volta para a capa, que ali continua
 *    visível o tempo todo).
 */
function abrirNaFaixaDaLinha(botao, opts) {
  const faixa = botao.parentElement;
  if (!faixa) return null;
  // Uma segunda abertura desfaz a primeira — inclusive a DESTA mesma linha, que
  // é o caso do toque repetido na lixeira ou no lápis.
  fecharConfirmacaoNaLinha();
  const li = botao.closest('.lib-item,.row-item');

  const cx = document.createElement('div');
  cx.className = 'linha-confirma' + (opts.classe ? ' ' + opts.classe : '');
  // NO COMEÇO da faixa, não no fim: a `.row-acoes` escalona a entrada dos botões
  // por `nth-last-child` (v5.269), que conta a partir do FIM — um irmão
  // acrescentado depois deles deslocaria o índice de todos.
  faixa.insertBefore(cx, faixa.firstChild);
  faixa.classList.add('confirmando');
  const marca = opts.marca || '';
  if (li && marca) li.classList.add(marca);

  // O SÍMBOLO ENTRA DEPOIS DA CAIXA porque o caminho B de um dos dois é ela
  // mesma — e ela precisa existir para receber o hóspede.
  const simbolo = opts.simbolo || null;
  const mais = li ? li.querySelector(':scope > .row > .row-mais') : null;
  if (simbolo && mais) {
    simbolo.classList.add('row-slot');
    mais.insertAdjacentElement('afterend', simbolo);
  } else if (simbolo && opts.semSlot) {
    opts.semSlot(simbolo, cx);
  }

  desfazerConfirmacao = () => {
    cx.remove();
    // `remove()` de um nó que nunca entrou no documento é no-op — é o caso do
    // símbolo cujo caminho B não achou onde pousar.
    if (simbolo) simbolo.remove();
    faixa.classList.remove('confirmando');
    if (li && marca) li.classList.remove(marca);
  };

  return cx;
}

/**
 * Abre a pergunta na faixa do `botao`. `opts`:
 *
 *  · `ok` — o rótulo do botão que executa ("Excluir", "Tirar").
 *  · `dica` — a frase inteira, no `title` desse botão.
 *  · `aoConfirmar` — o que fazer. Só é chamado depois de a pergunta sair da
 *    tela: ele costuma redesenhar a lista, e um redesenho com a faixa ainda
 *    montada deixaria o par pendurado num nó fora do documento.
 */
function pedirConfirmacaoNaLinha(botao, opts) {
  // A LIXEIRA É O SÍMBOLO DA PERGUNTA, e não um botão: `<span>` sem ponteiro,
  // fora da árvore de acessibilidade. Quem decide são os dois rótulos.
  const lixo = document.createElement('span');
  lixo.className = 'row-slot--del';
  lixo.setAttribute('aria-hidden', 'true');
  lixo.appendChild(msym(ICON.del));
  const cx = abrirNaFaixaDaLinha(botao, {
    marca: 'excluindo',
    simbolo: lixo,
    // CAMINHO B (a gaveta dos Favoritos): de volta à capa, o lugar de onde ela
    // saiu na v1.4.27 — ali a faixa não cobre a linha e não há `⋮` a ceder.
    semSlot: (sim) => {
      const li = botao.closest('.lib-item,.row-item');
      const thumb = li && li.querySelector(':scope > .row > .thumb');
      if (!thumb) return;
      sim.className = 'row-lixo';
      thumb.appendChild(sim);
    },
  });
  if (!cx) return;
  const nao = document.createElement('button');
  nao.type = 'button';
  nao.className = 'linha-confirma-btn linha-nao';
  nao.textContent = 'Cancelar';
  const sim = document.createElement('button');
  sim.type = 'button';
  sim.className = 'linha-confirma-btn linha-sim';
  sim.textContent = opts.ok;
  if (opts.dica) { sim.title = opts.dica; sim.setAttribute('aria-label', opts.dica); }
  cx.append(nao, sim);

  nao.addEventListener('click', (e) => { e.stopPropagation(); fecharConfirmacaoNaLinha(); });
  sim.addEventListener('click', async (e) => {
    e.stopPropagation();
    // Um segundo toque enquanto o `await` corre executaria duas vezes — e o
    // segundo cairia sobre uma lista já redesenhada.
    if (sim.disabled) return;
    sim.disabled = true;
    fecharConfirmacaoNaLinha();
    await opts.aoConfirmar();
  });
}

/**
 * ===== RENOMEAR TAMBÉM MORA NA PRÓPRIA LINHA (v1.4.25) =====
 *
 * Pedido do operador: *"coloque o processo de renomear também dentro do item na
 * lista do cronograma, não como um popup de tela inteira, assim como já é feito
 * no processo de excluir"*.
 *
 * É o mesmo argumento da v5.301, e ele vale AQUI COM MAIS FORÇA que na
 * exclusão: um modal TIRA O ALVO DE CENA, e renomear é a única ação do app em
 * que o operador precisa ver o nome VELHO enquanto escreve o novo — a linha
 * logo acima do campo é a única coisa que diz qual dos trinta nomes parecidos
 * está sendo trocado. O `appPrompt` mostrava o nome antigo dentro do campo, e
 * era só isso: o instante em que ele o apaga para digitar é o instante em que a
 * referência some da tela inteira.
 *
 * DECISÕES QUE PRECISAM ESTAR DITAS:
 *
 *  · **O campo nasce com o nome atual e SELECIONADO** (`select()`), não com o
 *    cursor no fim: trocar a frase inteira é o caso comum de um arquivo
 *    importado, e ajustar uma palavra continua a um toque de distância.
 *  · **`Enter` confirma e `Esc` cancela.** O teclado do Android mostra "OK" na
 *    tecla de ação (`enterkeyhint`), e sem o atalho o dedo teria de sair do
 *    teclado para achar um botão de 40px atrás dele.
 *  · **O ✓ é um BOTÃO À VISTA de qualquer jeito**: nem todo teclado honra o
 *    `enterkeyhint`, e um campo cuja única saída é uma tecla que pode não estar
 *    lá é um campo sem saída. Desde a v1.4.27 ele mora na COLUNA DO `⋮`, que o
 *    processo toma emprestada — o campo fica com a faixa inteira, e a coluna
 *    deixa de oferecer uma terceira saída para algo que já tem duas.
 *  · **Nome vazio ou igual ao atual não é renomear**: os dois desfecham em
 *    fechar sem gravar, que é o que o modal já fazia.
 *  · **Tudo que fecha a gaveta CANCELA**, como a pergunta da exclusão — o `⋮`
 *    outra vez, o toque fora, o redesenho da lista. O erro possível aqui é o
 *    seguro: perder o texto digitado custa redigitar; gravar um nome que
 *    ninguém confirmou não tem volta.
 */
function pedirRenomearNaLinha(botao, item, aoGravar) {
  const ok = document.createElement('button');
  ok.type = 'button';
  ok.className = 'row-slot--ok';
  ok.title = 'Salvar o nome';
  ok.setAttribute('aria-label', 'Salvar o nome');
  ok.innerHTML = checkIconSvg();
  const cx = abrirNaFaixaDaLinha(botao, {
    classe: 'linha-renome',
    simbolo: ok,
    // CAMINHO B (a gaveta dos Favoritos, sem `⋮`): ele volta para DENTRO da
    // faixa, ao lado do campo, que é onde morou até a v1.4.27. A lixeira tem
    // outro caminho B de propósito — ela ilustra e ele decide, e um botão que
    // desaparece por não achar coluna deixa o campo sem confirmação.
    semSlot: (sim, caixa) => { sim.classList.add('row-slot'); caixa.appendChild(sim); },
  });
  if (!cx) return;

  const campo = document.createElement('input');
  campo.type = 'text';
  campo.className = 'linha-renome-campo';
  campo.value = item.name || '';
  campo.setAttribute('aria-label', 'Novo nome');
  campo.enterKeyHint = 'done';
  // O teclado do Android sugere a primeira maiúscula e a correção automática num
  // campo de texto comum — os dois atrapalham um nome de arquivo, que é o que
  // está aqui na maior parte das vezes.
  campo.autocapitalize = 'off';
  campo.autocomplete = 'off';
  campo.spellcheck = false;
  // O TECLADO SOBREPÕE (v1.4.29) — ver `keyboardShift`. Este campo vive DENTRO
  // da lista, que rola sozinha; encolher o app para revelá-lo comprime a
  // preview e o transporte, que é o que o operador está olhando.
  campo.dataset.teclado = 'sobrepoe';

  // O CAMPO É O ÚNICO FILHO DA FAIXA — o ✓ já foi para a coluna do `⋮`.
  // `prepend` e não `append`: no CAMINHO B o ✓ já está aqui dentro (o `semSlot`
  // roda DENTRO do `abrirNaFaixaDaLinha`, antes desta linha), e com `append` o
  // campo entraria à DIREITA dele — a faixa sairia com o botão na frente do
  // texto que se está digitando. Com a faixa vazia os dois são a mesma coisa.
  cx.prepend(campo);

  const gravar = async () => {
    if (ok.disabled) return;
    const nome = (campo.value || '').trim();
    fecharConfirmacaoNaLinha();
    // Cancelou, apagou tudo, ou não mudou nada: o nome VAZIO não é um nome, e
    // gravar o mesmo nome gastaria uma transação e um redesenho para nada.
    if (!nome || nome === item.name) return;
    ok.disabled = true;
    await AVDB.renameMedia(item.id, nome);
    await aoGravar();
  };

  ok.addEventListener('click', (e) => { e.stopPropagation(); gravar(); });
  campo.addEventListener('click', (e) => e.stopPropagation());
  campo.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') { e.preventDefault(); gravar(); }
    else if (e.key === 'Escape') { e.preventDefault(); fecharConfirmacaoNaLinha(); }
  });
  // O FOCO É ADIADO UM QUADRO: a caixa acabou de entrar no documento e a faixa
  // ainda está com a transição de `visibility` da gaveta em curso — focar um
  // elemento que o navegador ainda não pintou não abre o teclado em todos os
  // aparelhos.
  requestAnimationFrame(() => {
    if (!campo.isConnected) return;
    campo.focus();
    campo.select();
  });
}

/**
 * EXCLUIR ESTE ITEM DA LISTA — a ação que faltava no `⋮` (v5.271).
 *
 * Pedido do operador: *"adicione a opção de excluir nas opções nos itens
 * individuais das listas de cronograma e favoritos"*.
 *
 * Até aqui excluir era um caminho só, e era o de LOTE: toque longo → seleção
 * múltipla → a lixeira do rodapé. Para tirar UM item isso é três gestos e um
 * modo, e nos Favoritos aquele modo nem chegava a se desenhar (ver
 * `favItemRow`). O `⋮` já é a gaveta de decisões daquela linha; a exclusão é
 * uma delas.
 *
 * A SEMÂNTICA É A MESMA DO LOTE, e de propósito: sai da LISTA (`listRemove`) e
 * o coletor decide o resto — se o item também estiver nos Favoritos, ou na
 * playlist, ele continua lá e os bytes ficam. Duas definições de "excluir" no
 * mesmo app seriam a divergência que `deleteSelected` já evitou uma vez.
 *
 * A CONFIRMAÇÃO não é zelo: é a condição para um destrutivo caber num ícone —
 * sem ela, a lixeira sozinha seria uma aposta. Desde a v5.301 ela mora NA
 * PRÓPRIA LINHA (`pedirConfirmacaoNaLinha`), e não num modal: a pergunta
 * "excluir este item?" feita por cima de uma tela sem o item era respondida de
 * memória, numa lista de trinta nomes parecidos.
 *
 * E ele TIRA DO AR antes de remover: um item que sai da lista enquanto está
 * projetado deixaria o telão com uma cena que nenhuma linha da tela explica.
 */
function botaoExcluirDaLinha(item, lista, depois) {
  const b = document.createElement('button');
  b.className = 'row-btn row-excluir';
  b.title = 'Excluir da lista';
  b.setAttribute('aria-label', 'Excluir da lista');
  b.appendChild(msym(ICON.del));   // o MESMO glifo da lixeira do rodapé
  b.addEventListener('click', (e) => {
    e.stopPropagation();
    const nome = item.name ? '"' + item.name + '"' : 'este item';
    pedirConfirmacaoNaLinha(b, {
      ok: 'Excluir',
      dica: 'Tirar ' + nome + ' desta lista. Os arquivos só são apagados se '
        + 'ele não estiver em mais nenhuma.',
      aoConfirmar: async () => {
        // EXCLUIR DE UMA LISTA NÃO TIRA DO AR (v1.3.13). Havia aqui um
        // `retirarDoAr`, e era ele — não o coletor — que interrompia o louvor
        // quando o operador apagava do Cronograma o item que estava tocando.
        //
        // A dica logo acima é o contrato, e ela fala de LISTA: *"tirar isto
        // desta lista"*. Parar a projeção é outra ação, tem botão próprio (o
        // segundo toque na linha) e não podia vir de carona.
        //
        // A FILA JÁ FAZIA ASSIM, com o motivo escrito na linha dela desde a
        // v5.309: *"o item pode estar no Cronograma e seguir projetando"*. Era
        // este caminho que destoava.
        //
        // E o que sustenta a mudança é o `fixarAvulso` do `send`: sem ele o
        // `listRemove` abaixo apagaria os bytes de baixo da cena.
        if (lista === 'favs') favSet.delete(item.id);
        await AVDB.listRemove(lista, item.id);
        await soltarAvulso(item.id);
        await depois();
      },
    });
  });
  return b;
}

// ===== REORDENAR É UM PAR DE BOTÕES, NÃO UM ARRASTO =====
//
// Vale nas TRÊS listas (Cronograma, Favoritos, fila da playlist) — dois idiomas
// de reordenar seriam pior que qualquer um dos dois. Um arrasto é gesto
// CONTÍNUO com captura de ponteiro, disputando o eixo vertical com a lista que
// rola por baixo, dentro de uma gaveta que já é alvo pequeno; dois toques
// discretos não têm corrida com nada.
//
// PREÇO dito: mover dez posições passou de um gesto a dez toques. A lista
// redesenha entre um toque e o outro, e o botão continua sob o dedo porque a
// gaveta reabre no item que se moveu (ver `moverNaLista`).
//
// `pos`/`total` vêm de quem itera a lista e desabilitam as pontas. Sem eles os
// dois nascem ativos e `moverNaLista` recusa a borda em silêncio — degradação
// segura.
function botoesDeOrdem(listName, id, pos, total) {
  if (!listName || typeof pos !== 'number' || total <= 1) return [];
  const faz = (delta, titulo, inerte) => {
    const b = document.createElement('button');
    b.className = 'row-btn row-ordem';
    b.title = titulo;
    b.setAttribute('aria-label', titulo);
    b.innerHTML = chevronDirSvg(delta < 0);
    if (inerte) b.disabled = true;
    else b.addEventListener('click', (e) => { e.stopPropagation(); moverNaLista(listName, id, delta); });
    return b;
  };
  return [
    faz(-1, 'Mover para cima', pos === 0),
    faz(1, 'Mover para baixo', pos === total - 1),
  ];
}

// Move UMA casa. A troca é no array de ids e o desfecho é o mesmo `load()` que
// o arrasto usava — o resto do app não sabe que o gesto mudou.
//
// `reabrirAcoesEm` é o que faz o segundo toque cair no mesmo lugar: `load()`
// reconstrói a lista inteira, o `li` que tinha a gaveta aberta deixa de existir,
// e sem isso cada casa custaria reabrir a gaveta à mão.
async function moverNaLista(listName, id, delta) {
  const ids = await AVDB.listIds(listName);
  const de = ids.indexOf(id);
  if (de === -1) return;
  const para = de + delta;
  if (para < 0 || para >= ids.length) return;
  ids.splice(de, 1);
  ids.splice(para, 0, id);
  await AVDB.listSet(listName, ids);
  reabrirAcoesEm = listName + ':' + id;
  await load();
  // (O REDESENHO EXPLÍCITO DA SEÇÃO saiu na v5.292: `load()` passou a fazê-lo
  // sozinho, para toda porta que mexe nos favoritos — ver
  // `sincronizarFavoritosNaBiblioteca`. Mantê-lo aqui seria um SEGUNDO
  // redesenho, e ele custava o recurso desta função: `reabrirAcoesEm` é
  // CONSUMIDO pelo primeiro, então o segundo reconstruía a linha sem a gaveta
  // aberta — o botão saía de baixo do dedo, que é exatamente o que ele existe
  // para evitar.)
}

// OS BOTÕES DA FAIXA QUE NÃO A FECHAM. A régua é a mesma desde a v5.289 — *a
// ação que NÃO TERMINA a conversa com aquele item* —, e cada linha diz por quê:
//
//  · `row-ordem` — o par ↑↓ REPETE (mover três casas são três toques), e fechar
//    no primeiro obrigaria a reabrir a cada casa;
//  · `fav-btn`  — a estrela é ALTERNADOR: o desfecho dela é o próprio botão
//    mudando de desenho sob o dedo;
//  · `row-excluir` — desde a v5.301 ele não exclui, PERGUNTA: a resposta nasce
//    dentro desta caixa, e fechá-la a levaria junto;
//  · `row-playlist` — como a estrela, é ALTERNADOR desde a v5.302: o desfecho
//    dele é o próprio botão trocando `+` por `✓` sob o dedo, e a caixa fechada
//    (`visibility: hidden`) tiraria da tela a única resposta que o toque tem.
//
// O `linha-nao` (o Cancelar da confirmação) entra pelo primeiro motivo, ao
// contrário: cancelar devolve a fileira de opções, e fechar a caixa junto
// cobraria dois toques de quem só desistiu.
//
// E DESDE A v1.4.25 três nomes a mais, pela mesma régua:
//
//  · `row-renomear` — como o excluir, ele não renomeia: ABRE O CAMPO, e o campo
//    nasce dentro desta caixa. Fechá-la levaria junto o que o toque acabou de
//    pedir;
//  · `row-crono` — como a estrela e a playlist, é ALTERNADOR (v1.4.25): o
//    desfecho dele é o próprio botão trocando `+` por `✓` sob o dedo.
//
// (O ✓ do renomear saiu desta lista na v1.4.27, e não porque a razão dele
// mudou: ele deixou de morar DENTRO da caixa — foi para a coluna do `⋮` —, e
// este ouvinte só enxerga o que está dentro dela. A razão em si continua de pé
// no código: ele fecha a pergunta SOZINHO, depois de ler o campo, e o inverso
// perderia o nome digitado.)
const ACOES_QUE_NAO_FECHAM = ['row-ordem', 'fav-btn', 'row-excluir', 'row-playlist',
  'row-crono', 'row-renomear', 'linha-nao'];

/**
 * Os botões de uma linha, guardados atrás do `⋮`.
 *
 * Devolve `[caixa, botão]` na ordem em que entram na linha — a caixa é
 * absoluta e cobre da miniatura até o `⋮`, então a posição dela no DOM não
 * importa para o layout, mas importa para a ORDEM DE LEITURA de quem usa
 * leitor de tela: as ações vêm antes do botão que as abre.
 *
 * Uma linha sem ação nenhuma (não há, hoje) não ganha `⋮`: um botão que abre
 * uma caixa vazia é pior que botão nenhum.
 */
function montarAcoesDaLinha(li, botoes, chave) {
  const uteis = botoes.filter(Boolean);
  if (!uteis.length) return [];
  // A REABERTURA depois de uma casa de reordenação (v5.285). Ela mora aqui, e
  // não em cada chamador, para a próxima lista que ganhar a gaveta não poder
  // esquecê-la — e o `li` ainda não está no documento, o que não importa: o que
  // reabre é a classe.
  // A CHAVE FICA NO `li` (v5.288): é por ela que `manterAcoesAbertas` reencontra
  // esta linha depois de um redesenho disparado por uma ação de dentro da
  // gaveta. Guardá-la só na closure não bastaria — quem precisa dela é código
  // de fora, que só tem o nó na mão.
  if (chave) li.dataset.acoesChave = chave;
  if (chave && chave === reabrirAcoesEm) {
    reabrirAcoesEm = null;
    fecharAcoesDaLinha();
    li.classList.add('acoes-abertas');
    linhaAcoesAberta = li;
  }
  const caixa = document.createElement('div');
  caixa.className = 'row-acoes';
  caixa.append(...uteis);
  // ESCOLHIDA a opção, a caixa fecha — ela cobre o nome, e um menu aberto por
  // cima do item depois de já ter feito o que se pediu é o defeito que ele
  // existe para corrigir.
  //
  // AS EXCEÇÕES estão em `ACOES_QUE_NAO_FECHAM`, logo abaixo — uma lista
  // nomeada, e não uma cadeia de `||` no meio do `if`: elas passaram de duas a
  // quatro na v5.301, e a régua que as separa é longa demais para caber ali.
  //
  // O VAZIO da caixa fecha pelo mesmo motivo, e é a saída barata de quem só
  // queria ler a linha — sem ele o único caminho de volta seria acertar o `⋮`
  // outra vez, um alvo de 34px ao lado de uma faixa inteira inerte.
  //
  // Na fase de CAPTURA, e isto não é preferência: todo botão de linha chama
  // `stopPropagation` no próprio `click` (senão o toque acionaria o corpo da
  // linha atrás), então um ouvinte de bolha aqui nunca veria nenhum deles.
  // Fechar antes de a ação rodar não a atrapalha — `fecharAcoesDaLinha` só tira
  // uma classe.
  caixa.addEventListener('click', (e) => {
    const alvo = e.target === caixa ? caixa : (e.target.closest && e.target.closest('button'));
    if (!alvo) return;
    if (alvo !== caixa && ACOES_QUE_NAO_FECHAM.some((c) => alvo.classList.contains(c))) return;
    if (alvo === caixa) e.stopPropagation();
    fecharAcoesDaLinha();
  }, true);
  const mais = document.createElement('button');
  mais.className = 'row-btn row-mais';
  mais.title = 'Opções deste item';
  mais.setAttribute('aria-label', 'Opções deste item');
  mais.innerHTML = dotsIconSvg();
  mais.addEventListener('click', (e) => {
    e.stopPropagation();
    alternarAcoesDaLinha(li);
  });
  return [caixa, mais];
}

// SVG inline (fora do subset da fonte): setas circulares de "sincronizar".
function syncIconSvg() {
  return '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    + '<polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/>'
    + '<path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/>'
    + '</svg>';
}
// SVG inline de "baixar tudo" — seta para baixo sobre uma bandeja, distinta
// das setas circulares de "sincronizar" (que é por álbum): aqui é a coleção
// inteira, uma ação de outra escala.
function downloadAllIconSvg() {
  return '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    + '<path d="M12 3v10"/><polyline points="8 9 12 13 16 9"/>'
    + '<path d="M4 15v3a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-3"/>'
    + '</svg>';
}
// SVG inline de "cancelar" — o mesmo botão do grupo enquanto o lote roda.
function closeIconSvg() {
  return '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    + '<line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>'
    + '</svg>';
}
// SVG inline de "check" (verde), usado no status "Completo offline".
function checkIconSvg() {
  return '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="20 6 9 17 4 12"/></svg>';
}
// (`listIconSvg` saiu: sem chamador desde que "Ver músicas" deixou as opções
// do álbum — a lista é o toque no card.)
// SVG inline de "seta para cima" — o MESMO botão da engrenagem enquanto as
// opções estão à mostra (v5.73). A engrenagem acesa dizia "as opções estão
// abertas" só pela cor; a seta diz o que o toque FAZ, que é recolher o painel
// que está logo abaixo dela. É a convenção de qualquer gaveta, e aqui o alvo é
// literalmente o teto do painel que ela fecha.
// As setas do par de reordenar (v5.285). SVG inline, e NÃO um glifo da fonte:
// `material-symbols.woff2` é um subset ESTÁTICO de ~32 codepoints, e um
// codepoint que não está nele desenha um retângulo vazio sem erro nenhum — a
// armadilha da v5.184, em que três ícones "existiam" no cmap com o contorno
// vazio. O desenho é o mesmo chevron da seta das seções, virado.
function chevronDirSvg(paraCima) {
  return '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="'
    + (paraCima ? '18 15 12 9 6 15' : '6 9 12 15 18 9') + '"/></svg>';
}
function chevronUpIconSvg() {
  return '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="18 15 12 9 6 15"/></svg>';
}
// (`gearIconSvg` saiu na v5.95, com o botão de opções do card: as opções agora
// aparecem sozinhas com o álbum aberto, e o único símbolo daquele canto é a
// seta que fecha. O mesmo desenho continua no botão de Configurações que
// flutua sobre a preview, que tem o seu.)
// (Os desenhos de "voz" e "nota musical" — `voiceIconSvg`/`noteIconSvg` —
// saíram com o último chamador: eles marcavam os botões de tocar CANTADA e
// PLAYBACK na linha, e desde a v5.286 a variante é um SEGMENTO da gaveta, com
// rótulo escrito. Um ícone sem chamador é um desenho que ninguém revisa.)

// Lista de cards da aba Álbuns: hinários (fixos) + um card por álbum do
// catálogo. Cada card é um "check do sistema" (não abre como pasta): símbolo,
// status, estatísticas e ações.
// Um álbum que na verdade é hinário não ganha card próprio (os dois hinários
// já são coleções fixas). O fato vem de `album_{id}.categories` e só se sabe
// depois de baixar o índice do álbum; até lá, o nome é o palpite disponível.
function isHymnalAlbum(coll) {
  if (coll.kind !== 'album') return false;
  const st = collState[coll.id];
  if (st && st.isHymnal != null) return !!st.isHymnal;
  return /hin[aá]rio/i.test(coll.name || '');
}

// O NÚMERO só existe em hinário. Ali ele é o nome da música — se pede "o 471",
// e a numeração é a mesma no hinário impresso de todo mundo. Num álbum,
// `track` é só a posição no disco: um dado de catálogo que ninguém usa para
// pedir nem para achar. "12. Ele Vem" não ajuda a reconhecer nada, e numa
// busca global punha uma coluna de números sem significado na frente de todo
// título de álbum.
function collNumbersSongs(coll) {
  return !!coll && (coll.kind === 'hymnal' || isHymnalAlbum(coll));
}

// Rótulo da música. É o ÚNICO lugar que decide se o número entra — a lista da
// coleção, a busca, o nome do arquivo baixado e o slide de capa passam todos
// por aqui (ou pelo `hymnTrack` que ele governa).
function songLabel(coll, s, pad) {
  const n = collNumbersSongs(coll) && s.track
    ? (pad ? String(s.track).padStart(3, '0') : String(s.track)) + '. ' : '';
  return n + s.name;
}

// Faixa de álbum já baixada carrega o número GRAVADO no registro ("012. Nome
// (Cantado)" e `hymnTrack`), de quando tudo era numerado. Só parar de escrever
// deixaria a biblioteca existente numerada para sempre — e é justamente ela que
// o operador já tem. Passagem única, marcada em estado: varre os arquivos das
// coleções que não numeram e tira o prefixo. Não recalcula o nome a partir de
// `hymnName` porque o registro também cobre importados e variantes; remover o
// "N. " da frente é a operação exata, e nada mais.
const MIG_SEM_NUMERO = 'migSemNumeroAlbuns';

async function desnumerarAlbunsBaixados() {
  if (await AVDB.getState(MIG_SEM_NUMERO)) return;
  try {
    const semNumero = new Set(
      allCollections().filter((c) => !collNumbersSongs(c)).map((c) => c.id));
    if (semNumero.size) {
      const arquivos = await AVDB.filesAll();
      for (const rec of arquivos) {
        if (!semNumero.has(rec.folder)) continue;
        const limpo = String(rec.name || '').replace(/^\d+\.\s*/, '');
        if (limpo === rec.name && rec.hymnTrack == null) continue;
        rec.name = limpo;
        rec.hymnTrack = null;
        await AVDB.fileAdd(rec);
      }
    }
    await AVDB.setState(MIG_SEM_NUMERO, 1);
  } catch (_) {
    // Sem a marca, a próxima abertura tenta de novo — é uma limpeza cosmética
    // e nada depende dela para o app funcionar.
  }
}

// O ÁLBUM DA CAPA, PARA A BIBLIOTECA QUE JÁ EXISTE (v5.220).
//
// A v5.219 pôs o nome da coleção no registro em dois pontos — no download e na
// varredura da sincronização — e os dois estão certos e os dois erram o alvo: a
// música do operador **já está baixada**, e uma coleção completa não é
// re-sincronizada. O relato foi exatamente esse: tocar um hino do hinário e a
// capa não mostrar "Hinário Adventista 2022". O dado nunca chegaria sozinho.
//
// Este é o preenchimento que faltava, no mesmo molde do `desnumerarAlbunsBaixados`
// logo acima: uma passagem, marcada em estado, depois de `loadCollections()` (é
// dele que sai o nome). O `folder` do registro é o id da coleção — a ligação já
// existia, só não estava sendo lida.
//
// Ele CORRIGE além de preencher (compara com o nome atual em vez de só olhar se
// está vazio): uma coleção renomeada na origem deixaria capas dizendo o nome
// velho, e o custo de conferir é o mesmo.
const MIG_ALBUM_CAPA = 'migAlbumDaCapa';
async function preencherAlbunsDosHinos() {
  if (await AVDB.getState(MIG_ALBUM_CAPA)) return;
  try {
    const nomes = new Map(allCollections().map((c) => [c.id, c.name]));
    const arquivos = await AVDB.filesAll();
    for (const rec of arquivos) {
      const nome = nomes.get(rec.folder);
      if (!nome || rec.hymnAlbum === nome) continue;
      rec.hymnAlbum = nome;
      await AVDB.fileAdd(rec);
    }
    await AVDB.setState(MIG_ALBUM_CAPA, 1);
  } catch (_) {
    // Mesma regra da passagem acima: sem a marca, a próxima abertura tenta de
    // novo. A capa sem a linha do álbum é a capa da v5.218 — não quebra nada.
  }
}

// A aba Álbuns espelha a classificação do banco: **categoria → álbum**, na
// ordem que o próprio banco define (`order`), com os hinários num grupo fixo
// no topo. Antes era uma lista plana de todos os álbuns em ordem de descoberta
// — sem categoria, sem subtítulo e sem ordem —, o que tornava impossível achar
// um álbum específico entre dezenas.
//
// A relação categoria↔álbum é N:N, então **o mesmo álbum pode aparecer em mais
// de uma categoria** — de propósito: é assim no banco e no app original, e o
// `subtitle` que acompanha o card muda conforme a categoria (é campo de pivô).
// Álbuns de uma categoria que de fato viram card (existem no catálogo e não
// são hinário disfarçado).
function categoryCards(cat) {
  const byId = new Map(allCollections().map((c) => [c.id, c]));
  const out = [];
  for (const a of cat.albums) {
    const coll = byId.get('album-' + a.id_album);
    if (coll && !isHymnalAlbum(coll)) out.push({ coll, ctx: a });
  }
  return out;
}

// O MIOLO do cabeçalho de grupo — contador (busy/done/fração) + botão de
// lote/cancelar — hoje usado só pelo `header()` da lista, por CATEGORIA. Ele
// era compartilhado com o "Baixar toda a biblioteca" fixo do cabeçalho do
// popup, que saiu na v5.258; `aposClique` era a diferença legítima daquele
// (ele precisava se redesenhar) e ficou sem chamador que o passe.
function montarResumoGrupo(host, key, text, colls, gOpts, aposClique) {
  const g = gui(key);
  const complete = grupoCompleto(colls);

  const info = document.createElement('span');
  // `busy` fica (ele diz que ALGO está acontecendo, que o número não diz);
  // `done` saiu na v5.263 — ver "O verde sai dos indicadores" em controle.css.
  info.className = 'coll-group-count' + (g.busy ? ' busy' : '');
  info.textContent = g.status || fracaoPeso(colls.map((c) => c.id)) || '—';
  host.appendChild(info);

  // COM O GRUPO INTEIRO BAIXADO O BOTÃO SAI DA LINHA (v5.135) — a MESMA regra
  // da barra do card. Enquanto o download ROLA ele continua, porque ali ele é
  // o cancelar.
  if (!complete || g.busy) {
    const btn = document.createElement('button');
    btn.className = 'coll-group-btn' + (g.busy ? ' busy' : '');
    btn.title = g.busy
      ? 'Cancelar o download'
      : 'Baixar a coleção completa (' + colls.length + ' álbum(ns))';
    btn.innerHTML = g.busy ? closeIconSvg() : downloadAllIconSvg();
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      syncGroup(key, text, colls, gOpts);
      if (aposClique) aposClique();
    });
    host.appendChild(btn);
  }
}

// O MESMO navegador de acervo, em dois lugares: a aba Álbuns e o estado padrão
// da busca (ver renderSearchResults). É uma função só de propósito — duas
// cópias divergiriam no primeiro ajuste de categoria, e o operador veria dois
// acervos diferentes conforme por onde entrou.
// (A PALETA DAS COLEÇÕES saiu na v1.5.9, com o `tomDaVez`/`colTom` que a
// carimbava. Ela dava a cada linha de topo uma matiz própria, e o operador
// reprovou: *"está errado, reformule o sistema de coloração e organização de
// grupos e subgrupos"*. O que a substitui é MOLDURA, e é tudo CSS — ver "A
// HIERARQUIA DA BIBLIOTECA É DESENHADA COM MOLDURA" em controle.css.)
function renderCollectionsList(alvo, redesenhar, opts) {
  // ===== A LISTA DO ACERVO SE NOMEIA (v1.5.9) =====
  // A hierarquia por MOLDURA é escopada a esta lista e a mais nada — foi a
  // condição do operador ao autorizá-la (*"mas apenas para a biblioteca"*), e é
  // um ESCOPO que o `tokens.test.mjs` cobra. A marca vai no contêiner e não num
  // id porque ela diz O QUE é, não ONDE calha de estar: a lista do acervo é a
  // Biblioteca em qualquer lugar em que alguém a desenhe — inclusive num
  // oráculo, que monta a própria `<ul>` para poder medir com largura de celular.
  if (alvo) alvo.classList.add('acervo');
  // A passada é síncrona: liga a memoização de `levantarColecao`/taxa global
  // (ver "Memoização por PASSADA de render"), zerada aqui a cada redesenho.
  // O `finally` desliga mesmo se um card lançar — cache ligado fora de uma
  // passada é dado velho em diálogo de confirmação.
  cacheLevantar.clear(); cacheBpsGlobal = 0;
  cacheColecoesAtivo = true;
  try {
    renderCollectionsListMiolo(alvo, redesenhar, opts);
  } finally {
    // O véu das bordas: este redesenho roda a cada 400 ms durante um download e
    // muda a altura da lista sem rolagem nenhuma.
    acertarVeuDaLista();
    // A TAMPA (v1.5.19), e é aqui porque é aqui que a lista está COMPLETA: a
    // conta divide a altura útil pelo número de blocos, e medi-la no meio da
    // montagem leria uma tela com metade deles.
    acertarTampa(alvo);
    cacheColecoesAtivo = false;
  }
}
function renderCollectionsListMiolo(alvo, redesenhar, opts) {
  alvo = alvo || libraryEl;
  redesenhar = redesenhar || renderLibrary;
  redesenharAcervo = redesenhar;
  const byId = new Map(allCollections().map((c) => [c.id, c]));
  let any = false;
  // ===== AS COLETÂNEAS DISSOLVIDAS (v1.5.16) =====
  //
  // A leitura EDITORIAL do catálogo, aplicada AQUI e não no `fetchAlbumCatalog`:
  // o `state['albumCatalog']` continua cru, e a regra é reaplicada a cada
  // desenho. É isso que faz um ajuste da tabela chegar por OTA e valer na
  // abertura seguinte mesmo offline — gravada, a decisão viraria dado no
  // aparelho e só sairia de lá com rede.
  //
  // UMA chamada, e os DOIS consumidores leem dela: o laço que desenha as seções
  // e o `claimed` que decide o que é órfão. Chamar só num deles é o defeito
  // MEDIDO desta mudança — a coletânea sai da tela e os álbuns dela voltam
  // como "Outros álbuns", com a mesma contagem de blocos e o pedido não
  // atendido.
  const coletaneas = AVColetanea.aplicar(albumCatalog.categories);

  // ===== UM GRUPO COLAPSÁVEL =====
  //
  // Devolve o `<ul>` em que os cards entram, ou **null** quando o grupo está
  // fechado — e o `null` não é um detalhe de implementação: é ele que faz o
  // fechado não CONSTRUIR os cards. Numa Biblioteca com dezenas de álbuns, e
  // com o acervo redesenhado a cada 400 ms durante um download, montar o que
  // não está à vista é o grosso do trabalho de DOM da tela.
  //
  // O cabeçalho continua sendo o `<li class="coll-group">` de sempre, com o
  // mesmo nome e o mesmo resumo — o que ele ganha é uma barra clicável e uma
  // seta. Não é um `<button>` por dentro porque o resumo já traz um botão (o
  // de baixar o grupo), e botão dentro de botão é HTML inválido: é a mesma
  // solução da `.coll-bar` do card, que também é uma `div` com ouvinte.
  const grupo = (text, colls, gOpts) => {
    any = true;
    // TODA seção colapsa, inclusive a dos Favoritos (v5.262). A exceção `fixo`
    // da v5.238 saiu: o que ela protegia — os favoritos ABERTOS por padrão — é
    // hoje o `favAberto` no topo do arquivo.
    //
    // DOIS ESTADOS, e não um (v5.276): as coleções fazem rodízio entre si
    // (`grupoAberto`) e os Favoritos respondem só a si mesmos (`favAberto`).
    // Esta linha é o lugar inteiro em que essa diferença existe.
    const ehFav = text === GRUPO_FAVORITOS;
    const aberto = ehFav ? favAberto : grupoAberto === text;
    const li = document.createElement('li');
    li.className = 'coll-group coll-group--drop' + (aberto ? ' aberto' : '');
    // A SEÇÃO ABERTA OCUPA O VÃO (v5.273) — a regra em si é do CSS
    // (`.coll-group--drop.aberto { flex: 1 1 auto }`), e o que a torna possível
    // é a decisão de cima: com UMA aberta por vez, "quem se estica" não precisa
    // ser escolhido — é sempre a única que tem conteúdo. As fechadas são barras
    // de altura fixa e sobram empilhadas na base, que é o pedido do operador.
    //
    // A MARCA DOS FAVORITOS é do NOME e não do estado. Ela responde a UMA
    // pergunta desde a v5.282: quem ocupa o vão que sobra da tela (o
    // `min-height` do CSS). O TOM PRÓPRIO que ela carregou da v5.273 à v5.281
    // saiu — *"ajuste as cores dela para que ela fique igual as outras
    // coleções"* —, e a classe fica porque o vão continua sendo só dela.
    if (ehFav) li.classList.add('coll-group--fav');
    // O nome no nó: o redesenho APAGA este `li`, e quem quiser reencontrar a
    // seção depois (o alinhamento da abertura, logo abaixo) não tem outro
    // caminho — a referência viraria um nó órfão.
    li.dataset.grupo = text;

    const bar = document.createElement('div');
    bar.className = 'coll-group-bar';
    bar.setAttribute('role', 'button');
    bar.setAttribute('tabindex', '0');
    bar.setAttribute('aria-expanded', aberto ? 'true' : 'false');
    // ===== A SETA É A THUMBNAIL DAS RAÍZES (v5.244) =====
    //
    // Pedido do operador: *"pode manter uma seta como 'thumbnail' padrão, pois
    // nas subdivisões, uma thumbnail é meio inútil, deixe apenas nos arquivos os
    // ícones, nas raízes mais altas o ideal é a seta, pois ela representa que
    // pode abrir mais listagens."*
    //
    // A seção ganha o MESMO quadrado do card do álbum (`.coll-bar-icon`), e nos
    // dois ele carrega a mesma coisa: a seta que abre e fecha. O que sobrava
    // ali era identidade — e identidade de uma SEÇÃO ("Diversos", "CDs do ano")
    // não é um desenho, é o nome ao lado. Ícone fica onde ele distingue um item
    // do outro, que é a folha da árvore.
    //
    // E ela desceu da coluna da DIREITA (onde estava desde a v5.237): é a mesma
    // razão da v5.243 — a direita é a coluna do peso e do botão de baixar, e uma
    // seta que aparece ali empurra os números.
    const seta = document.createElement('button');
    seta.className = 'coll-group-icon';
    seta.type = 'button';
    seta.title = aberto ? 'Fechar' : 'Abrir';
    seta.setAttribute('aria-label', aberto ? 'Fechar' : 'Abrir');
    seta.innerHTML = chevronUpIconSvg();
    bar.appendChild(seta);
    const name = document.createElement('span');
    name.className = 'coll-group-name';
    name.textContent = text;
    bar.appendChild(name);
    // O RESUMO do grupo é o mesmo de antes, e ele importa mais agora: fechado,
    // ele é a única coisa que o cabeçalho diz sobre o que há lá dentro.
    if (gOpts && gOpts.acoes) {
      // AS AÇÕES DA SEÇÃO MORAM NA BARRA DELA (v5.239, pedido do operador). Só
      // ícone: o rótulo do que a ação faz mora na folha que ela abre, e uma
      // barra de seção com texto de botão dentro deixa de se ler como um
      // cabeçalho. `stopPropagation` porque num grupo colapsável a barra
      // inteira é o alvo de abrir/fechar.
      const espaco = document.createElement('span');
      espaco.className = 'coll-group-espaco';
      bar.appendChild(espaco);
      gOpts.acoes.forEach((a) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'coll-group-acao';
        b.title = a.titulo;
        b.setAttribute('aria-label', a.titulo);
        if (typeof a.icone === 'string') b.innerHTML = a.icone;
        else b.appendChild(a.icone);
        b.addEventListener('click', (e) => { e.stopPropagation(); a.aoTocar(b); });
        bar.appendChild(b);
      });
    } else if (colls && colls.length) {
      montarResumoGrupo(bar, 'grp:' + text, text, colls, gOpts);
    }
    li.appendChild(bar);

    const corpo = document.createElement('ul');
    corpo.className = 'coll-group-corpo';
    li.appendChild(corpo);

    // ===== UMA COLEÇÃO POR VEZ, E OS FAVORITOS À PARTE (v5.273 → v5.276) =====
    //
    // A v5.273 REVOGOU a decisão da v5.237 (*"abrir um grupo não fecha os
    // outros, ao contrário do acordeão de um álbum: aqui os grupos são curtos,
    // e comparar dois deles é o que se faz numa tela de índice"*), porque
    // aquele argumento supunha que a tela cabe. O rodízio FICA; o que sai dele
    // são os FAVORITOS.
    //
    // Pedido do operador: *"agora não mais são concorrentes com os favoritos…
    // as coleções são concorrentes entre si, mas não com os favoritos"*. Ele
    // está corrigindo uma consequência que a v5.273 não pesou: com os Favoritos
    // no mesmo rodízio, abrir um hinário custava o atalho que o operador tinha
    // deixado aberto — e reabri-lo custava fechar o hinário. Duas decisões
    // diferentes disputando o mesmo interruptor.
    //
    // FECHAR UMA COLEÇÃO deixa `grupoAberto` VAZIO, e isso deixou de ser um
    // estado a evitar: é o estado em que a Biblioteca ABRE (v1.1.4), e os
    // Favoritos respondem por conta própria — abrir ou fechar uma coleção não
    // toca neles.
    const alternar = () => {
      const abrindo = !aberto;
      const aplicar = () => {
        if (ehFav) favAberto = abrindo;
        else grupoAberto = abrindo ? text : '';
        if (abrindo) gruposAnimar.add(text);
        redesenhar();
      };
      // Fechando: anima ANTES de redesenhar. O redesenho apaga o nó, e um nó
      // apagado não tem como sair deslizando (a mesma nota do card).
      if (!abrindo) { collapseAccordion(corpo, aplicar); return; }
      aplicar();
      // ===== A COLEÇÃO ABRE PARA BAIXO, ALINHADA PELO TOPO (v5.277) =====
      //
      // Pedido do operador: *"as coleções estão abrindo estendendo para cima,
      // mas elas devem sempre abrir para baixo e rolar/alinhar a tela sempre
      // com o início da lista da coleção, alinhando com o topo dela"*.
      //
      // O "para cima" era a seção dos Favoritos ENCOLHENDO para dar espaço (ver
      // `--fav-vao`, que este mesmo lote tornou fixo) — o conteúdo acima subia,
      // e o que se via era a coleção crescendo na direção errada. Com o vão
      // fixo, o que falta é a segunda metade: uma coleção que abre lá embaixo
      // cresce para fora da tela, e quem a abriu fica olhando a barra dela sem
      // ver um item. Rolar até o topo dela é o que faz "abrir" e "ver o que
      // abriu" serem a mesma coisa.
      //
      // Nos Favoritos não: eles têm posição fixa no alto da lista, e rolar até
      // eles seria rolar até onde a tela já está.
      //
      // DEPOIS DA ANIMAÇÃO, e não no quadro seguinte: `expandAccordion` anima a
      // altura do corpo de 0 até o valor natural, então durante esses 220 ms o
      // conteúdo abaixo ainda não existe e a lista não tem para onde rolar. Uma
      // versão em `requestAnimationFrame` mediu o layout COLAPSADO e rolou
      // 7px de 59 possíveis (verificado) — o número certo para uma tela que
      // ainda não tinha crescido.
      if (!ehFav) setTimeout(() => alinharGrupoNoTopo(alvo, text), ACC_MS + 30);
    };
    // ===== O ALVO É O BLOCO, E NÃO A BARRA (v1.5.17) =====
    //
    // O card já fazia isto ("O ALVO É O CARD, E NÃO A BARRA", mais abaixo); a
    // seção não, e desde que o bloco de raiz passou a CRESCER para preencher a
    // tela isso virou margem morta: MEDIDO, 4,75px acima e 4,77px abaixo da
    // barra, 9,5px por seção, em que o toque não fazia nada. É exatamente o que
    // o recuo da barra existe para impedir (v5.288: *"a faixa em volta dela ser
    // ALVO em vez de margem morta"*).
    //
    // A GUARDA é o CORPO aberto, pelo mesmo motivo do card: sem ela um toque
    // num álbum lá dentro borbulharia até aqui e fecharia a seção debaixo do
    // dedo. Os três controles da barra já param a propagação por conta própria
    // (a seta, o `.coll-group-acao` e o botão do `montarResumoGrupo`), então
    // nenhum deles alterna duas vezes.
    //
    // O `keydown` FICA NA BARRA: ela é quem recebe foco (é ela que tem
    // `role`/`tabindex`), e um `<li>` não entra na ordem de tabulação.
    li.addEventListener('click', (e) => {
      // A GUARDA É POSITIVA: alterna o toque na PRÓPRIA caixa do bloco (a faixa
      // que sobra em volta da barra) ou dentro da BARRA. Escrita ao contrário —
      // "tudo menos o corpo aberto" —, ela depende de o corpo ter sempre a
      // mesma classe, e a seção dos FAVORITOS monta o dela por outro caminho:
      // um toque numa linha de favorito borbulhava até aqui e FECHAVA a seção
      // debaixo do dedo (o `boot-nativo` pegou, com o nó removido no meio do
      // percurso).
      const t = e.target;
      if (t !== li && !(t && t.closest && t.closest('.coll-group-bar'))) return;
      alternar();
    });
    bar.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); alternar(); }
    });
    // A seta tem ouvinte PRÓPRIO, com `stopPropagation`: sem ele o clique nela
    // borbulharia até a barra e alternaria duas vezes, isto é, não faria nada.
    seta.addEventListener('click', (e) => { e.stopPropagation(); alternar(); });

    alvo.appendChild(li);
    if (!aberto) return null;
    if (gruposAnimar.has(text)) {
      gruposAnimar.delete(text);
      // O `li` ainda não está no documento quando esta função devolve: medir
      // agora daria zero, então a animação espera o quadro seguinte — e a essa
      // altura os cards já foram anexados pelo chamador.
      requestAnimationFrame(() => expandAccordion(corpo));
    }
    return corpo;
  };

  // (A barra "Toda a biblioteca" saiu na v5.258 — ver o bloco acima. Ela já
  // vinha desligada por `semTotal` no único chamador real desde que subiu para
  // o cabeçalho, e o cabeçalho saiu com ela.)

  // ===== FAVORITOS, O PRIMEIRO GRUPO =====
  //
  // A Biblioteca é onde se procura o que projetar, e o favorito é o atalho de
  // quem já procurou antes — a primeira coisa a olhar dentro dela.
  //
  // Quem monta é `renderFolderList`, hoje com UMA casa: este corpo (ver
  // `favHost`/`favAlvo`). O nome vem da gaveta de tela cheia, que não existe
  // mais — a pasta do aparelho abre INLINE desde a v5.290 e o `#favPopup` saiu
  // na v5.294, levando a busca DENTRO de uma pasta e a seleção múltipla lá
  // dentro (declarado no cabeçalho deste arquivo).
  //
  // SEM CONTADOR: a seção nasce aberta e a lista inteira está logo abaixo — um
  // número a dois centímetros dela é a mesma medida dita duas vezes. Fechada
  // ela não diz quantos são, e isso é aceito: fechar é o gesto de quem não está
  // procurando ali agora.
  // ===== A SEÇÃO DE FAVORITOS NÃO EXISTE NO MODO FÁCIL =====
  //
  // Pedido do operador. E a razão é a mesma do "Ao Cronograma" do sorteio (ver
  // `renderSorteioAcoes`): o Modo Fácil não tem abas nem listas — o que se
  // GUARDA ali não tem onde ser visto depois. Uma seção que mostra o acervo
  // marcado, com um botão de trazer pastas do aparelho, é a gaveta inteira do
  // modo avançado aparecendo dentro do modo que existe para não ter gaveta.
  //
  // Só a SEÇÃO sai. Os favoritos continuam existindo, continuam sincronizando e
  // voltam inteiros ao trocar de modo — o que muda é a Biblioteca aberta DAQUI
  // mostrar as coleções e mais nada.
  const favCorpo = appMode === 'simple' ? null : grupo(GRUPO_FAVORITOS, null, {
    // UMA AÇÃO, E ELA FAZ A COISA (v5.254): trazer uma pasta do aparelho.
    //
    // PASTA + (v5.258, pedido do operador). A v5.254 pôs aqui as setas
    // circulares, e elas são o desenho de RE-SINCRONIZAR — o que a linha de
    // cada pasta já trazida faz. Este botão não re-sincroniza nada: ele
    // ACRESCENTA uma pasta que ainda não está aqui, e é isso que o `+` diz.
    // As setas continuam sendo as certas onde a ação é repetir; aqui a ação é
    // a primeira vez.
    acoes: [{
      icone: msym(ICON.folderNew),
      titulo: 'Trazer uma pasta do aparelho',
      aoTocar: (b) => syncDeviceFolder(undefined, b),
    }],
  });
  if (favCorpo) {
    // A MARCA que o redesenho no lugar procura (v5.258, ver
    // `redesenharFavoritosNaBiblioteca`). Ela mora AQUI, no dono, e não no
    // `grupo()`: quem sabe que este corpo é o dos Favoritos é este trecho, e
    // como `grupo()` só devolve o corpo quando a seção está ABERTA, a marca
    // deixa de existir com ela fechada — que é exatamente quando não há o que
    // redesenhar.
    favCorpo.dataset.favCorpo = '1';
    favHost = favCorpo;
    // `finally` obrigatório: um erro ao montar uma linha deixaria o host preso
    // no corpo de um grupo que já saiu do documento, e a gaveta de verdade
    // passaria a desenhar dentro de um nó órfão — sem erro nenhum na tela.
    try { comBaldeDeMiniaturas('fav-biblioteca', renderFolderList); } finally { favHost = null; }
    // A medição do vão é agendada aqui e roda no quadro seguinte — quando as
    // outras seções já foram anexadas e a altura que sobra é a de verdade.
    acertarVaoDosFavoritos(favCorpo);
  }

  // AS COLEÇÕES FIXAS FICAM NA RAIZ, uma a uma (v1.0.1).
  //
  // Elas moravam em dois grupos — "Arquivos oficiais" (as séries) e "Hinários"
  // —, e o agrupamento cobrava um toque que não pagava por si: quem abre o
  // Hinário 2022 quase nunca quer o de 1996 na mesma sessão, e quem vai ao
  // Provai e Vede não vai ao Informativo. O grupo existia para separar dois
  // MODELOS de item (áudio com letra × vídeo do sábado), e essa distinção
  // continua inteira — ela é do CARD (`tipoDaColecao`), não do cabeçalho que
  // ficava por cima dele.
  //
  // Na raiz, o toque que antes abria o grupo agora abre a LISTA: o card já é um
  // acordeão que expande nas próprias faixas (ver `alternarAcordeao`). Um toque
  // a menos para o destino mais frequente da Biblioteca.
  //
  // A ORDEM é a do uso: as séries são o material DATADO do sábado que vem, e é
  // a elas que se volta toda semana; o hinário é o acervo PERMANENTE, a que se
  // chega pela busca, pelo número ou pelo nome.
  //
  // ARMADILHA: `allCollections()` alimenta as CONTAS (peso, "toda a
  // biblioteca", busca), NÃO o desenho. Uma coleção fixa nova tem de ser
  // acrescentada AQUI também, ou ela é construída, conta no peso e não aparece
  // em lugar nenhum — sem erro.
  const fixasNaRaiz = [...serieCollections(), ...FIXED_COLLECTIONS]
    .filter((c) => byId.has(c.id));
  if (fixasNaRaiz.length) {
    any = true;
    fixasNaRaiz.forEach((coll) => alvo.appendChild(renderCollectionCard(coll)));
  }

  for (const cat of coletaneas.categorias) {
    const cards = categoryCards(cat);
    if (!cards.length) continue;
    const corpo = grupo(cat.name, cards.map((x) => x.coll));
    if (corpo) cards.forEach(({ coll, ctx }) => corpo.appendChild(renderCollectionCard(coll, ctx)));
  }

  // Álbuns conhecidos que nenhuma categoria reivindicou (catálogo antigo,
  // migrado de uma versão sem categorias, ou álbum removido de todas elas).
  const claimed = new Set();
  for (const cat of coletaneas.categorias) for (const a of cat.albums) claimed.add('album-' + a.id_album);
  const orphans = albumCatalog.albums
    .map((a) => byId.get('album-' + a.id_album))
    .filter((c) => c && !claimed.has(c.id) && !isHymnalAlbum(c));
  if (orphans.length) {
    const corpo = grupo(coletaneas.categorias.length ? 'Outros álbuns' : 'Álbuns', orphans);
    if (corpo) orphans.forEach((coll) => corpo.appendChild(renderCollectionCard(coll)));
  }

  if (!any) {
    const empty = document.createElement('li'); empty.className = 'empty';
    empty.textContent = 'Nenhuma coleção disponível.';
    alvo.appendChild(empty);
  }
}

// Cartão informativo de UMA coleção (hinário ou álbum) — NÃO é uma pasta: é um
// "check do sistema" (símbolo, status, estatísticas sincronizados/peso/rede +
// ações sincronizar/excluir). Não abre como pasta ao tocar (o operador
// acessa/toca as músicas pela busca do acervo, botão de lupa). Sempre visível,
// mesmo antes da 1ª sincronização. Retorna o <li> (não anexa).
//
// COLAPSADO POR PADRÃO (deixa a lista compacta): mostra só uma barra com nome +
// resumo de sincronização (baixados/total). Tocar na barra EXPANDE o card com o
// detalhe completo (status, ações, estatísticas). O estado (expandido) é
// transitório em `ui(coll.id).expanded` (não persistido) — cada abertura do app
// começa colapsada.
// `ctx` = a entrada do álbum DENTRO da categoria sendo renderizada (o pivô:
// subtitle/order). Nulo para hinários e órfãos.
function renderCollectionCard(coll, ctx) {
  const total = songsBaixaveis(coll.id).length;
  // (Havia aqui um `countDownloaded(coll.id)` calculado e nunca lido — resto de
  // quando a fração vinha dele. Quem responde "quanto já está no aparelho?" é
  // `fracaoPeso`, e "está inteiro?" é `colecaoCompleta`. A varredura custava
  // um `filter` sobre TODAS as faixas do álbum, por card, e o acervo é
  // redesenhado a cada 400 ms enquanto um download corre.)
  // UMA definição só, e ela conta VARIANTES (ver `levantarColecao`): a antiga
  // comparava músicas com `fileIdFull`, ignorando os Playbacks que o download
  // busca — e nunca ficava completa numa coleção com música sem áudio na
  // origem, deixando o botão de baixar para sempre na tela.
  const complete = colecaoCompleta(coll.id);
  const u = ui(coll.id);

  const li = document.createElement('li');
  li.className = 'hymnal-card';
  // (A `coll.color` do banco desenhava uma faixa lateral de 3px no cartão. Ela
  // saiu na v5.71 com as molduras: era mais uma linha vertical repetida em toda
  // a lista. Ela NÃO volta com a tinta da v1.5.7: na Bíblia a faixa carrega a
  // informação porque o ladrilho é pequeno e a tinta é sutil; aqui o card é uma
  // barra larga e a tinta cobre tudo.)

  // Uma linha só: ícone + nome/subtítulo + resumo + a coluna de ações. O card
  // deixou de ser um acordeão de manutenção — TOCAR NELE ABRE A LISTA, que é o
  // que o operador quer quase sempre; sincronizar e excluir são botões PRÓPRIOS
  // na direita da barra, cada um com a sua regra de aparecer (ver abaixo).
  const bar = document.createElement('div'); bar.className = 'coll-bar';
  // A THUMB É A SETA, ABERTO OU FECHADO (v5.244 — ver "A seta é a thumbnail das
  // raízes", em `grupo()`). Ela era o ícone da coleção com o card fechado e a
  // seta com ele aberto; agora é a seta nos dois, girada por CSS, e é o MESMO
  // quadrado que a barra de seção acima usa. Um álbum é uma subdivisão: o que
  // distingue um do outro é o nome, não um glifo repetido em todos eles (era a
  // mesma nota musical em cada hinário e a mesma fila em cada álbum).
  //
  // A SETA FECHA O ÁLBUM (v5.95). Ela era uma engrenagem que abria um painel de
  // opções dentro do card — mas com as opções encolhidas numa linha só, elas
  // cabem SEMPRE que o álbum está aberto, e um botão para revelar duas ações que
  // já caberiam na tela é cerimônia.
  const barIcon = document.createElement('button');
  barIcon.type = 'button';
  barIcon.className = 'coll-bar-icon coll-bar-fechar';
  barIcon.title = u.expanded ? 'Fechar o álbum' : 'Abrir o álbum';
  barIcon.setAttribute('aria-label', barIcon.title);
  barIcon.innerHTML = chevronUpIconSvg();
  barIcon.addEventListener('click', (e) => {
    e.stopPropagation();   // divide a barra com o toque que também alterna
    alternarAcordeao();
  });

  const info = document.createElement('div'); info.className = 'coll-bar-info';
  const barName = document.createElement('span'); barName.className = 'coll-bar-name'; barName.textContent = coll.name;
  info.appendChild(barName);
  // ===== O PESO É SUBTÍTULO, NÃO UMA COLUNA (v5.247) =====
  //
  // Pedido do operador: *"ajuste o elemento que descreve o peso dos arquivos e
  // álbuns e coleções, para que ele seja um subtítulo abaixo do título, pois
  // atualmente ele está apertando o espaço disponível para o título dos
  // álbuns. Mas garanta que os cards não fiquem mais altos por causa disso."*
  //
  // Ele dividia a LINHA com o nome, e numa tela de celular isso é caro: "~1,2 GB"
  // come um terço da largura útil, e o nome de um álbum é a única coisa daquela
  // barra que não se adivinha. Abaixo, o nome fica com a linha inteira e o peso
  // não perde nada — ele é um número curto que ninguém lê de relance.
  //
  // A SEGUNDA LINHA JÁ EXISTIA (o subtítulo do pivô categoria↔álbum), e o peso
  // entra NELA, não numa terceira: são duas peças do mesmo tipo — metadado curto
  // sobre a coleção —, e uma linha por peça faria o card crescer conforme o
  // catálogo, que é justamente o que a segunda metade do pedido proíbe.
  const meta = document.createElement('div'); meta.className = 'coll-bar-meta';
  const subtitle = ctx && ctx.subtitle;
  if (subtitle) {
    const sub = document.createElement('span'); sub.className = 'coll-bar-sub';
    sub.textContent = subtitle;
    meta.appendChild(sub);
  }
  bar.append(barIcon, info);

  // Resumo de sincronização: progresso ao vivo enquanto sincroniza, senão
  // baixados/total.
  //
  // **A SÉRIE NÃO TEM PESO A ANUNCIAR** (v1.1.21). `fracaoPeso` devolve, para
  // um acervo vazio, "o que vai custar baixar" — e num álbum de série isso era
  // um número de gigabytes prometendo um download em lote que nunca existiu e
  // que agora nem botão tem. O que ela tem de verdade para dizer na barra é
  // quantos episódios a lista traz, que é o número que o painel carregava antes
  // de sair. Sem índice, silêncio: o botão de atualizar ao lado já é a mensagem.
  //
  // COM O ÁLBUM INTEIRO BAIXADO ELE SOME (v5.70), junto com o botão de baixar
  // que já saíra na v5.63. "24/24" não pede nada nem informa nada de novo — é
  // ruído repetido em cada linha de uma lista de dezenas de álbuns, e o estado
  // que o operador procura ali é justamente o oposto: o que ainda FALTA. Numa
  // lista toda baixada, o silêncio é a resposta certa, e ela continua legível
  // por eliminação: "não sincron." quando não há índice, uma fração quando
  // falta algo, nada quando está completo. O detalhe (peso, "✓ Completo
  // offline") segue na engrenagem dentro do card aberto.
  const summary = document.createElement('span'); summary.className = 'coll-bar-sync';
  const peso = ehLink(coll) ? null : fracaoPeso([coll.id]);
  if (u.syncBusy && u.status) {
    summary.classList.add('busy'); summary.textContent = u.status;
  } else if (peso) {
    summary.textContent = peso;
  } else if (ehLink(coll)) {
    summary.textContent = total ? total + (total === 1 ? ' episódio' : ' episódios') : '';
  } else if (coll.kind === 'album') {
    summary.textContent = 'não sincron.';
  }
  // O TRAVESSÃO SAIU (v5.247). Ele era o marcador de "nada a dizer" numa COLUNA
  // que precisava existir para os cards se alinharem; como subtítulo ele vira um
  // traço solto embaixo do nome, dizendo menos que o silêncio. Sem ele o card
  // fica com uma linha só — e não encolhe, porque quem manda na altura é a
  // thumb.
  if (summary.textContent) meta.appendChild(summary);
  // A linha do metadado só existe se houver o que pôr nela: um card sem
  // subtítulo e sem peso não paga uma linha vazia de altura.
  if (meta.childElementCount) info.appendChild(meta);
  // Reconferência do peso: uma vez por sessão e por álbum (ver a função — desde
  // a v5.134 ela vale para qualquer peso, não só o zerado).
  conferirPesoSeFaltar(coll.id);

  // A BARRA INTEIRA é o alvo do acordeão; a seta de abrir mora na THUMB (o
  // único elemento sem função com o álbum aberto).
  //
  // A COLUNA DA DIREITA tem até dois botões, e cada um responde a uma pergunta
  // diferente (v1.1.16): BAIXAR a "há o que baixar?", independente de
  // aberto/fechado; REMOVER a "o álbum está aberto?". Álbum completo e fechado:
  // canto vazio. Download EM CURSO: o cancelar fica ali mesmo com o card aberto
  // — centenas de faixas precisam poder parar num toque, de qualquer ponto da
  // rolagem.
  // A SÉRIE NÃO BAIXA EM LOTE, NEM COM A LISTA VAZIA (v1.1.21). Até aqui o
  // botão ficava enquanto não houvesse índice — ali ele buscava a LISTA, não
  // baixava —, e isso era um botão com dois significados conforme o estado. A
  // busca da lista passou a ter botão PRÓPRIO na mesma coluna (logo abaixo), e
  // este some da série em todos os estados.
  if ((u.syncBusy || !complete) && !ehLink(coll)) {
    // **O QUE É LINK NÃO BAIXA EM LOTE** (v5.230). São ~52 vídeos de ~300 MB — o
    // "download direto" que o operador pediu para não existir, na maior escala
    // que este app tem. Quem quiser um episódio offline o manda ao Cronograma
    // ou aos Favoritos pela folha, que é o caminho do YouTube. O botão continua
    // aparecendo enquanto NÃO há índice (`total === 0`): ali ele não baixa
    // nada, ele busca a lista — que é justamente o que falta na tela.
    const dl = document.createElement('button');
    dl.className = 'coll-bar-dl' + (u.syncBusy ? ' busy' : '');
    dl.title = u.syncBusy ? 'Cancelar o download'
      : (total > 0 ? 'Baixar esta coleção' : 'Sincronizar a lista');
    dl.innerHTML = u.syncBusy ? closeIconSvg() : downloadAllIconSvg();
    dl.addEventListener('click', (e) => { e.stopPropagation(); syncCollection(coll); });
    // ELE NÃO SE ESCONDE MAIS COM O CARD ABERTO (v1.1.16). O `vago` existia
    // porque o painel de dentro tinha um "Baixar" que fazia a mesma coisa dois
    // centímetros abaixo — e o painel saiu. Agora a barra é o ÚNICO lugar onde
    // se baixa, e ela é o que gruda no topo enquanto se percorre a lista: um
    // álbum de centenas de faixas precisa poder começar (e parar) num toque, de
    // qualquer ponto da rolagem.
    bar.appendChild(dl);
  }

  // ===== A SÉRIE TEM UM BOTÃO SÓ, E ELE É O DE ATUALIZAR A LISTA (v1.1.21) =====
  //
  // Pedido do operador: *"para o Provai e Vede e para o Informativo, os arquivos
  // precisam estar ou no cronograma ou nos favoritos ou no player para o arquivo
  // baixado existir… então não vamos precisar de um botão geral de baixar no
  // topo desses álbuns e nem um para excluir… vamos jogar o botão de atualizar
  // lista para o local onde está o botão excluir, no mesmo estilo, botão puro,
  // sem texto"*.
  //
  // **O ÁLBUM DE SÉRIE NÃO GUARDA NADA, e é isso que tira dele os outros dois
  // botões.** Um episódio só existe no aparelho enquanto está no Cronograma, nos
  // Favoritos ou na playlist; saindo de lá, o coletor o recolhe. Não há acervo
  // do álbum para baixar em lote (~15 GB/ano) nem para remover — "Remover do
  // dispositivo" num álbum que não retém nada apagaria o que está em OUTRA
  // lista, ou nada, e as duas leituras são erradas.
  //
  // Sobra UMA ação, e ela é a que a série tem de ter: refazer a lista. O índice
  // dela custa uma extração do canal do YouTube, então o TTL de 12 h a segura —
  // e sem este botão o operador esperaria meio dia pelo episódio do sábado sem
  // ter o que fazer (ver `forcarIndice`, que de propósito não a força).
  //
  // ===== E ELE SÓ EXISTE COM O ÁLBUM ABERTO (v1.2.0) =====
  //
  // Pedido do operador: *"os botões de atualizar lista do provai e vede e do
  // informativo mundial das missões só deve aparecer com o album/grupo
  // aberto"*.
  //
  // É a régua da LIXEIRA (v1.1.16) aplicada ao terceiro botão desta coluna: o
  // gesto que revela a ação é o mesmo que revela a LISTA sobre a qual ela age.
  // Fechado, o card de uma série não oferece nada — e o acervo inteiro é uma
  // lista de cards fechados, onde este ícone aparecia em cada série como uma
  // ação sem contexto a dois centímetros do nome.
  //
  // **`u.syncBusy` é a exceção, e ela não é uma segunda regra:** enquanto a
  // varredura corre este botão não é "atualizar", é o CANCELAR dela — o mesmo
  // desfecho que faz o irmão de download ficar visível com o card fechado. Um
  // cancelar que some é um cancelar que não existe no único momento em que ele
  // importa.
  if (ehLink(coll) && (u.expanded || u.syncBusy)) {
    const at = document.createElement('button');
    // `coll-bar-at` além da base: os TRÊS botões desta coluna dividem a
    // geometria (`.coll-bar-dl`) e precisam ser distinguíveis um do outro — por
    // quem lê a folha e por quem escreve um oráculo sobre ela.
    at.className = 'coll-bar-dl coll-bar-at' + (u.syncBusy ? ' busy' : '');
    at.title = u.syncBusy ? 'Cancelar' : 'Atualizar a lista';
    at.setAttribute('aria-label', at.title);
    at.innerHTML = u.syncBusy ? closeIconSvg() : syncIconSvg();
    // `soIndice`: numa série o toque NUNCA baixa episódio — ele refaz a lista.
    at.addEventListener('click', (e) => { e.stopPropagation(); syncCollection(coll, { soIndice: true }); });
    bar.appendChild(at);
  }

  // ===== A LIXEIRA MORA NA BARRA, E SÓ COM O ÁLBUM ABERTO (v1.1.16) =====
  //
  // Pedido do operador: *"coloque o botão de excluir na direita no card do
  // título do álbum, ali onde fica o botão de download… deixe o botão de
  // excluir apenas visível quando abrir o álbum"*.
  //
  // As duas metades do pedido são uma coisa só: a lixeira ganha o lugar mais
  // alcançável da linha E o gesto que a revela é o mesmo que revela o conteúdo
  // que ela apaga. Fechado, o card não oferece destruição nenhuma — e o acervo
  // inteiro é uma lista de cards fechados.
  //
  // `countDownloaded` só é chamado com o card ABERTO, e isso é deliberado: ele
  // varre todas as faixas do álbum, e o acervo é redesenhado a cada 400 ms
  // enquanto um download corre. Há no máximo um card aberto (o acordeão), então
  // a varredura acontece uma vez por redesenho, não quarenta.
  // A SÉRIE fica de fora (v1.1.21): ela não retém arquivo nenhum, e remover o
  // que ela não tem apagaria o que está em outra lista — ou nada.
  if (!ehLink(coll) && u.expanded && (total > 0 || countDownloaded(coll.id) > 0)) {
    const rm = document.createElement('button');
    // "Remover do dispositivo", e não "Excluir": o que sai é o que ocupa espaço
    // NESTE aparelho, e o álbum continua no acervo para ser baixado de novo.
    // "Excluir" prometeria um dano maior do que o que a ação faz.
    rm.className = 'coll-bar-dl coll-bar-rm';
    rm.title = 'Remover do dispositivo';
    rm.setAttribute('aria-label', 'Remover do dispositivo');
    rm.appendChild(msym(ICON.del));
    // `stopPropagation` como no irmão ao lado: sem ele o toque borbulha até o
    // card e FECHA o álbum — debaixo do diálogo de confirmação que acabou de
    // abrir.
    rm.addEventListener('click', (e) => { e.stopPropagation(); deleteCollection(coll); });
    bar.appendChild(rm);
  }

  // Sem índice ainda não há lista para abrir — o toque abre o card assim mesmo.
  // O que resolve a ausência é um botão da BARRA, presente com o card fechado ou
  // aberto: "Sincronizar a lista" num álbum, "Atualizar a lista" numa série.
  //
  // Nomeada porque tem DOIS gatilhos: o toque na barra e a seta (v5.95).
  const alternarAcordeao = () => {
    if (!total && !u.expanded) { openCollectionOptions(coll); return; }
    // Acordeão: uma coleção aberta por vez. Duas listas de centenas de músicas
    // abertas ao mesmo tempo empurrariam o acervo para fora da tela e tirariam
    // do lugar exatamente o card que o operador mira.
    const abrindo = !u.expanded;
    const aplicar = () => {
      // Fechar zera a paginação junto: reabrir um hinário de 613 hinos que
      // ficou rolado até o fim traria os 613 de volta de uma vez, que é
      // exatamente o custo que `COLL_PAGE` existe para evitar.
      allCollections().forEach((c) => { const x = ui(c.id); x.expanded = false; x.shown = 0; });
      u.expanded = abrindo;
      if (abrindo) u.shown = COLL_PAGE;
      // O card só existe DEPOIS do redesenho (a lista inteira é reconstruída),
      // então quem anima a abertura é o próprio render — este é o recado.
      if (abrindo) u.animarAbertura = true;
      redesenharAcervo();
    };
    // Fechando: anima ANTES de redesenhar. O redesenho apaga o nó, e um nó
    // apagado não tem como sair deslizando.
    const aberto = li.querySelector('.coll-open');
    if (!abrindo && aberto) { collapseAccordion(aberto, aplicar); return; }
    aplicar();
  };
  // ===== O ALVO É O CARD, E NÃO A BARRA =====
  //
  // ARMADILHA: o feedback de toque tira o alvo de baixo do dedo. O ouvinte mora
  // no CARD, que não se mexe — fecha a classe inteira em vez de caçar pixels.
  //
  // A barra ESCALAVA (`--press`), e escalar um contêiner arrasta o que vive
  // dentro dele: o botão de baixar está colado na borda direita, e um dedo na
  // metade direita DELE caía sobre a barra no `pointerup` — o toque abria o
  // acordeão em vez de baixar (MEDIDO: 6 de 11 acertavam). Hoje a barra responde
  // por PREENCHIMENTO (`.coll-bar:active`, em `controle.css`, onde a regra geral
  // está escrita), e este ouvinte no card continua valendo pelo mesmo motivo de
  // sempre.
  //
  // A GUARDA é o corpo aberto (`.coll-open`, o invólucro de tudo que não é a
  // barra — nunca uma lista de filhos, para o próximo bloco lá dentro já nascer
  // protegido): sem ela, um toque numa faixa borbulharia até aqui e fecharia o
  // álbum debaixo do dedo.
  //
  // E A PERGUNTA É SOBRE O CAMINHO (`e.composedPath()`), NUNCA SOBRE A ÁRVORE
  // DE AGORA. Marcar uma opção chama `renderSongMenu`, que faz
  // `alvo.innerHTML = ''`: quando o evento chega aqui o `e.target` está
  // DESANEXADO, e `closest` devolve `null` — o álbum fecharia. O caminho é
  // fixado no DISPARO e sobrevive ao apagamento.
  li.addEventListener('click', (e) => {
    const caminho = typeof e.composedPath === 'function' ? e.composedPath() : null;
    const deDentro = caminho && caminho.length
      ? caminho.some((n) => n !== li && n.classList && n.classList.contains('coll-open'))
      : !!(e.target.closest && e.target.closest('.coll-open'));
    if (deDentro) return;
    alternarAcordeao();
  });
  li.appendChild(bar);

  // ----- Aberto: as opções (se pedidas) + as músicas da coleção -----
  // `total === 0` também abre: é o caso do álbum sem índice, em que o card só
  // tem as opções a mostrar — e é para elas que o toque na barra leva.
  if (u.expanded) {
    li.classList.add('expanded');

    // Um invólucro só para os dois blocos abertos: é ele que a animação de
    // altura recorta. As margens negativas dele repetem as da lista de músicas
    // (que sangra até a borda do card para o filete do topo atravessar a
    // largura toda) — sem isso o `overflow:hidden` cortaria justamente esse
    // filete durante a animação.
    const aberto = document.createElement('div'); aberto.className = 'coll-open';

    // As opções ALI MESMO, logo abaixo da barra, dentro do card (v5.72). Eram
    // um bottom-sheet (`#collPopup`), e um popup para ver o peso e o estado de
    // sincronização de um álbum que já está aberto na tela era uma camada a
    // mais sobre outra camada — o acervo já é um popup de tela cheia. Aqui elas
    // ficam onde o assunto está, e fechar é o mesmo toque que abriu.
    // O DESTAQUE DO SÁBADO, acima da lista e só na série (ver `blocoDestaque`).
    const dest = blocoDestaque(coll);
    if (dest) aberto.appendChild(dest);

    // A lista sai INTEIRA, quantos itens tenha: aqui o operador está folheando
    // um álbum, não filtrando o acervo — cortar num teto esconderia o fim de
    // qualquer hinário. É o mesmo `hymnResultRow` da busca, sem o subtítulo da
    // coleção (que é o próprio card em volta). Ela só chega em PÁGINAS de
    // `COLL_PAGE`, à medida que o scroll alcança o fim — ver `fillSongList`.
    if (total > 0) {
      const lista = document.createElement('ul'); lista.className = 'coll-songs';
      // O ÍNDICE ANTES da lista, e FECHADO (ver `indiceDeSecoes`).
      const indice = indiceDeSecoes(coll, u, lista);
      if (indice) aberto.appendChild(indice);
      fillSongList(lista, coll, u);
      aberto.appendChild(lista);
    }
    li.appendChild(aberto);

    // Só o toque que ABRIU anima. Um redesenho por outro motivo (o progresso do
    // download, a volta de uma sincronização) reencontra o card já aberto — e
    // vê-lo "abrir" de novo sozinho leria como se algo tivesse acontecido.
    if (u.animarAbertura) {
      u.animarAbertura = false;
      // O `li` ainda não está no documento: medir agora daria zero.
      requestAnimationFrame(() => expandAccordion(aberto));
    }
  }
  return li;
}

// ===== A lista do álbum chega em páginas =====
// Um hinário tem 613 hinos, e cada linha é um `<li>` com miniatura, dois botões
// e SVG inline dentro deles. Montar as 613 de uma vez no toque que abre o card
// é meio segundo de JAVASCRIPT SÍNCRONO num celular: a animação de abertura
// nasce já engasgada e o toque parece não ter funcionado. Pior, isso acontece
// TODA vez que o card é redesenhado — e o progresso de um download redesenha o
// acervo a cada `COLL_REFRESH_MS`.
//
// Então a lista chega de `COLL_PAGE` em `COLL_PAGE`, e o gatilho da próxima
// página é o SCROLL CHEGAR NO FIM da anterior — não um botão. Quem folheia um
// hinário está procurando um hino, não administrando uma lista: parar para
// pedir mais é atrito num gesto que já é contínuo.
const COLL_PAGE = 100;

// Preenche (ou completa) `lista` até `u.shown` e reinstala a sentinela do fim.
// É INCREMENTAL de propósito: a próxima página é anexada às linhas que já estão
// no DOM, sem reconstruir as anteriores — reconstruir mexeria no scroll debaixo
// do dedo do operador, que é o gesto que acabou de pedir a página.
function fillSongList(lista, coll, u) {
  const songs = faixasDaLista(coll);
  if (!u.shown) u.shown = COLL_PAGE;
  const ate = Math.min(u.shown, songs.length);
  // A retomada conta só as FAIXAS (`.hymn-result`), nunca os filhos da lista:
  // os cabeçalhos de seção moram na mesma `<ul>` e contá-los faria a página
  // seguinte começar adiantada, pulando tantos hinos quantos cabeçalhos já
  // tivessem sido desenhados.
  for (let i = lista.querySelectorAll('.hymn-result').length; i < ate; i++) {
    const cab = cabecalhoDeSecao(coll, songs[i]);
    if (cab) lista.appendChild(cab);
    lista.appendChild(hymnResultRow(coll, songs[i], null, true));
  }

  const velha = lista.querySelector('.coll-more');
  if (velha) {
    if (velha.__obs) velha.__obs.disconnect();
    velha.remove();
  }
  if (ate >= songs.length) return;

  // A sentinela é também o BOTÃO da próxima página. O observador cobre o caso
  // normal (o dedo rolando), o toque cobre quem chegou aqui de outro jeito —
  // uma lista curta demais para rolar dentro do popup, por exemplo.
  const sent = document.createElement('li');
  sent.className = 'coll-more';
  const btn = document.createElement('button');
  btn.className = 'coll-more-btn';
  btn.innerHTML = '<span class="dl-ring"></span>';
  btn.appendChild(document.createTextNode('Carregando mais ' + Math.min(COLL_PAGE, songs.length - ate)
    + ' de ' + (songs.length - ate) + ' restantes'));
  sent.appendChild(btn);

  const mais = () => {
    if (sent.__obs) sent.__obs.disconnect();
    if (!lista.isConnected) return;
    u.shown = ate + COLL_PAGE;
    fillSongList(lista, coll, u);
  };
  btn.addEventListener('click', mais);

  // `root: null` (a viewport) resolve sozinho o problema de descobrir QUAL é o
  // contêiner que rola — a interseção com a viewport já vem recortada pelos
  // `overflow` dos ancestrais, então a sentinela só "aparece" quando de fato
  // aparece na tela. A margem adianta a página em ~300px: o objetivo é que o
  // operador nunca CHEGUE a ver esta linha.
  const obs = new IntersectionObserver((entradas) => {
    if (entradas.some((e) => e.isIntersecting)) mais();
  }, { rootMargin: '300px 0px' });
  sent.__obs = obs;
  lista.appendChild(sent);
  obs.observe(sent);
}

// ===== O ÍNDICE DE TEMAS, NO TOPO DO CARD DO HINÁRIO (v1.1.12) =====
//
// Pedido do operador: *"um pequeno índice no início da lista do álbum do
// hinário"*.
//
// **ELE NASCE FECHADO**, como uma barra de uma linha, e essa é a decisão que o
// mantém "pequeno": são 35 seções, e desenhá-las abertas empurraria os 600
// hinos para baixo de um paredão que o operador teria de rolar TODA vez que
// abrisse o hinário — inclusive nas nove vezes em dez em que ele já sabe o
// número que quer. É a mesma regra da v1.1.4 ("a Biblioteca abre com tudo
// fechado e compacto"), aplicada um nível abaixo.
//
// O estado mora na `ui()` do álbum (`u.indiceAberto`), como todo estado de
// navegação deste acervo: o card é REMONTADO a cada redesenho (o progresso de
// um download, uma sincronização), e um estado guardado no nó morreria junto
// com ele.
//
// **O TOQUE NUMA SEÇÃO ROLA ATÉ ELA — e antes disso GARANTE que ela exista.** A
// lista chega de `COLL_PAGE` em `COLL_PAGE` por scroll: pedir "Despedida" (592)
// com 100 linhas desenhadas rolaria até o fim de uma lista que ainda não tem o
// destino. Por isso o `u.shown` é esticado até cobrir o número ANTES do
// `scrollIntoView` — e o desfecho é o cabeçalho no topo da tela, não um pulo
// para o vazio.
function indiceDeSecoes(coll, u, lista) {
  if (!window.AVHinario || !ehHinarioNovo(coll)) return null;
  const cx = document.createElement('div');
  cx.className = 'hino-indice' + (u.indiceAberto ? ' aberto' : '');

  const barra = document.createElement('button');
  barra.type = 'button';
  barra.className = 'hino-indice-bar';
  const rot = document.createElement('span'); rot.className = 'hino-indice-rot';
  rot.textContent = 'Índice de temas';
  const cnt = document.createElement('span'); cnt.className = 'hino-indice-cnt';
  cnt.textContent = AVHinario.SECOES.length + ' seções';
  barra.appendChild(rot); barra.appendChild(cnt);
  barra.setAttribute('aria-expanded', u.indiceAberto ? 'true' : 'false');
  cx.appendChild(barra);

  const corpo = document.createElement('div');
  corpo.className = 'hino-indice-corpo';
  corpo.hidden = !u.indiceAberto;
  for (const g of AVHinario.indice()) {
    const t = document.createElement('div'); t.className = 'hino-indice-bloco';
    t.textContent = g.bloco;
    corpo.appendChild(t);
    const grade = document.createElement('div'); grade.className = 'hino-indice-grade';
    for (const sec of g.secoes) {
      const b = document.createElement('button');
      b.type = 'button'; b.className = 'hino-indice-chip';
      const n = document.createElement('span'); n.className = 'hino-indice-chip-nome';
      n.textContent = sec.nome;
      const f = document.createElement('span'); f.className = 'hino-indice-chip-faixa';
      f.textContent = sec.de === sec.ate ? String(sec.de) : sec.de + '–' + sec.ate;
      b.appendChild(n); b.appendChild(f);
      b.addEventListener('click', () => irParaSecao(coll, u, lista, sec.de));
      grade.appendChild(b);
    }
    corpo.appendChild(grade);
  }
  cx.appendChild(corpo);

  barra.addEventListener('click', () => {
    u.indiceAberto = !u.indiceAberto;
    cx.classList.toggle('aberto', u.indiceAberto);
    corpo.hidden = !u.indiceAberto;
    barra.setAttribute('aria-expanded', u.indiceAberto ? 'true' : 'false');
    if (u.indiceAberto && !semMovimento()) requestAnimationFrame(() => expandAccordion(corpo));
  });
  return cx;
}

// Estica a lista até o hino pedido existir no DOM e rola até o cabeçalho dele.
//
// O `u.shown` é arredondado para cima em páginas inteiras: `fillSongList` é
// incremental e a próxima página parte de `u.shown`, então um valor quebrado
// deixaria a paginação seguinte fora do passo. E o `scrollIntoView` espera um
// quadro — o `<li>` acabou de ser inserido e medir agora daria a posição
// anterior.
function irParaSecao(coll, u, lista, numero) {
  const songs = faixasDaLista(coll);
  const alvo = songs.findIndex((x) => (x.track | 0) === numero);
  if (alvo < 0) return;
  const preciso = Math.ceil((alvo + 1) / COLL_PAGE) * COLL_PAGE;
  if ((u.shown || 0) < preciso) {
    u.shown = preciso;
    fillSongList(lista, coll, u);
  }
  requestAnimationFrame(() => {
    const cab = lista.querySelector('.hino-secao[data-secao="' + numero + '"]');
    if (cab) cab.scrollIntoView({ block: 'start', behavior: semMovimento() ? 'auto' : 'smooth' });
  });
}

// ===== OS TÍTULOS DE SEÇÃO NO MEIO DA LISTAGEM (v1.1.12) =====
//
// Pedido do operador: *"adicionar pequenos títulos no meio da listagem dos
// hinos, para demarcar as divisões de temas"*.
//
// Quem sabe a seção de um número é `AVHinario` (a tabela pura, com oráculo). O
// que mora AQUI é só a decisão de desenhar, e ela tem três guardas:
//
//  - **Só o hinário NOVO** (`ehHinarioNovo`): os números da tabela são os do
//    2022. O de 1996 tem 613 hinos e outra organização — desenhar "Infantis"
//    sobre o 508 dele seria um rótulo mentindo, que é o defeito que este
//    recurso inteiro existe para não ter.
//  - **Só quem COMEÇA uma seção** (`comecaSecao`), nunca "mudou em relação à
//    linha anterior": a lista chega de 100 em 100 e a linha anterior nem sempre
//    está no DOM — a comparação erraria exatamente na primeira linha de cada
//    página, e erraria desenhando um cabeçalho a mais no meio de uma seção.
//  - **Só na LISTA DO ÁLBUM**, não nos resultados de busca: ali as linhas vêm
//    de coleções diferentes e fora de ordem, e um "A Trindade" sobre um
//    resultado solto não demarca nada — afirma.
//
// `aria-hidden` não: o cabeçalho é conteúdo, e um leitor de tela que o pule
// perde justamente a informação que ele acrescenta. É um `<li>` de propósito
// (a lista é uma `<ul>`), com `role="presentation"` fora de questão pelo mesmo
// motivo.
function ehHinarioNovo(coll) { return !!coll && coll.id === HYMNAL_2022_ID; }

function cabecalhoDeSecao(coll, s) {
  if (!window.AVHinario || !ehHinarioNovo(coll)) return null;
  const sec = AVHinario.comecaSecao(s && s.track);
  if (!sec) return null;
  const li = document.createElement('li');
  li.className = 'hino-secao';
  li.dataset.secao = String(sec.de);
  // O NOME é o título; o BLOCO é a linha de cima, esmaecida — e ela só aparece
  // quando muda, senão "A Doutrina da Vida Cristã" se repetiria cinco vezes
  // seguidas dizendo a mesma coisa.
  if (sec.de === (AVHinario.SECOES.find((x) => x.bloco === sec.bloco) || {}).de) {
    const b = document.createElement('span'); b.className = 'hino-secao-bloco';
    b.textContent = sec.bloco;
    li.appendChild(b);
  }
  const n = document.createElement('span'); n.className = 'hino-secao-nome';
  n.textContent = sec.nome;
  li.appendChild(n);
  // A FAIXA, à direita: é ela que responde "estou perto?" quando o operador
  // rola procurando um número, que é como um hinário de verdade é folheado.
  const f = document.createElement('span'); f.className = 'hino-secao-faixa';
  f.textContent = sec.de === sec.ate ? String(sec.de) : sec.de + '–' + sec.ate;
  li.appendChild(f);
  return li;
}

// ===== Acordeões: a animação de altura =====
// Um acordeão que troca `display` aparece PRONTO, e num toque a lista inteira
// abaixo dá um salto — o operador perde de vista onde estava. Animar a altura
// mostra de onde o conteúdo saiu, que é a única informação que o salto destrói.
//
// A altura é MEDIDA (`scrollHeight`) e animada até um `auto` final: um teto
// fixo em CSS cortaria a letra de um hino de 40 linhas ou deixaria um vão
// enorme depois de um refrão de duas.
const ACC_MS = 220;
const ACC_EASE = 'cubic-bezier(.22,.61,.36,1)';

// `prefers-reduced-motion` é a única razão para NÃO animar: quem pediu menos
// movimento no sistema pediu isso para o app inteiro.
function semMovimento() {
  return window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

function expandAccordion(el) {
  if (!el || !el.isConnected) return;
  if (semMovimento()) return;
  // `offsetHeight`, e não `scrollHeight`: a caixa da letra tem teto de altura e
  // rola por dentro — o conteúdo de um hino de 40 linhas passa MUITO do que ela
  // de fato ocupa, e animar até lá abriria um vão e depois recuaria.
  const alvo = el.offsetHeight;
  if (!alvo) return;
  el.style.overflow = 'hidden';
  const anim = el.animate(
    [{ height: '0px', opacity: 0 }, { height: alvo + 'px', opacity: 1 }],
    { duration: ACC_MS, easing: ACC_EASE },
  );
  // O `finally` do acordeão: sem devolver o `overflow`, a lista de músicas
  // ficaria presa à altura do instante em que a animação foi montada — e a
  // letra que uma linha abre depois seria cortada.
  const soltar = () => { el.style.overflow = ''; };
  anim.addEventListener('finish', soltar);
  anim.addEventListener('cancel', soltar);
}

// Fecha animando e SÓ ENTÃO executa `depois` (que costuma apagar o nó).
function collapseAccordion(el, depois) {
  if (!el || !el.isConnected || semMovimento()) { depois(); return; }
  const de = el.offsetHeight;
  if (!de) { depois(); return; }
  el.style.overflow = 'hidden';
  const anim = el.animate(
    [{ height: de + 'px', opacity: 1 }, { height: '0px', opacity: 0 }],
    { duration: ACC_MS, easing: ACC_EASE },
  );
  let feito = false;
  const fim = () => { if (feito) return; feito = true; el.style.overflow = ''; depois(); };
  anim.addEventListener('finish', fim);
  anim.addEventListener('cancel', fim);
}

// Quem redesenha o acervo depende de onde ele está na tela. `renderCollectionsList`
// recebe esse callback e o guarda aqui para os cards — eles são criados um a um
// e não têm como saber o alvo sozinhos.
let redesenharAcervo = () => {};

// ===== "BAIXAR TODA A BIBLIOTECA" SAIU (v5.258) =====
//
// Pedido do operador: *"remova a opção de download total de toda a biblioteca,
// pois ele ficou muito grande e muito inconveniente. Pode inclusive remover o
// botão e o indicador de peso total que ficam na barra do topo."*
//
// Ele está certo pela própria escala que o botão anunciava: com as séries e os
// álbuns de hoje, "tudo" é dezenas de gigabytes — um toque cujo desfecho
// razoável é sempre "não", e que ocupava o lugar de maior alcance da tela para
// oferecer isso. O CONTADOR foi junto: ele era o peso do acervo INTEIRO, um
// número que não responde nenhuma pergunta que o operador faça de fato (a que
// ele faz é sobre UMA coleção, e essa continua na barra de cada card).
//
// O que FICA: o download por coleção (a barra de cada card) e o por CATEGORIA
// (`montarResumoGrupo`, no cabeçalho de "Diversos", "CDs do ano"…). São os dois
// que têm tamanho de decisão.

// ===== Abrir o card de uma coleção =====
// Abre o card sem passar pelo alternador da barra: é o caminho do toque numa
// coleção SEM ÍNDICE. Ali não há lista para folhear, e o que resolve isso — o
// botão de sincronizar — mora na barra, aberto ou fechado; o que abrir
// acrescenta é a lixeira (num álbum) e o destaque do sábado (numa série).
function openCollectionOptions(coll) {
  const u = ui(coll.id);
  // Reconta o peso PELO DISCO (`opfsFolderSize`, v5.134 — não mais pelo
  // catálogo): uma coleção, ao abrir. Durante o uso ele é mantido
  // incrementalmente; os outros pontos de reconferência estão listados no
  // comentário de `updateCollBytes`.
  updateCollBytes(coll.id);
  allCollections().forEach((c) => { ui(c.id).expanded = false; });
  u.expanded = true;
  u.animarAbertura = true;
  redesenharAcervo();
}

// (`buildCollectionOptions` e o painel `.coll-opts` saíram na v1.1.21, e as
// três ações que ele teve terminaram na COLUNA DA DIREITA DA BARRA — ver
// `renderCollectionCard`. A última a sair foi o "Atualizar a lista" da série,
// que virou botão puro ao lado dos irmãos; antes dele saíram o "Verificar"
// (v1.1.16, a verificação virou automática na abertura) e o "Baixar", que já
// existia na barra e era só repetido ali.
//
// O QUE ELE ENSINOU, e vale para o que vier ocupar aquele lugar: **nada dentro
// do card repete o que a barra dele já diz.** Ele teve três chips, uma linha de
// status, um chip de peso e um chip de rede — e o peso está na barra ANTES de
// abrir (é ele que faz o operador decidir abrir), e o "Baixando 2 de 4…" está na
// barra `sticky` dois centímetros acima.)

/**
 * ===== O DESTAQUE DO SÁBADO, NO TOPO DA LISTA DA SÉRIE (v1.1.21) =====
 *
 * Pedido do operador: *"gostaria que fizesse um sistema de destaque que
 * colocasse separado destacado no topo da lista o item referente ao sábado
 * atual. Caso não tenha, deixe uma mensagem de Aguardando lançamento"*.
 *
 * A pergunta "qual é o episódio deste sábado?" é do `AVSerie`
 * (`ehDoSabadoAtual`, puro e com oráculo). O que mora AQUI é a decisão de
 * DESENHAR, e ela tem três regras:
 *
 *  - **O item destacado SAI da lista** (`faixasDaLista`). Deixá-lo nos dois
 *    lugares daria duas linhas que fazem exatamente a mesma coisa, a dois
 *    centímetros uma da outra — e a de baixo, no meio de cinquenta irmãs, é a
 *    que o operador tocaria por engano procurando outra data. "Separado" é
 *    literal.
 *  - **A AUSÊNCIA também é um estado, e ela é o caso comum na segunda-feira.**
 *    Sem o bloco, um card sem o episódio da semana fica indistinguível de um
 *    card que ainda não carregou. "Aguardando lançamento" responde a pergunta
 *    que o operador veio fazer, e o cabeçalho ao lado diz de QUE sábado se
 *    trata — sem a data, a frase valeria para qualquer semana.
 *  - **A LINHA É A MESMA da lista** (`hymnResultRow`), dentro de uma `<ul>` que
 *    também é `.coll-songs`: o toque, a gaveta de opções, o indicador de
 *    download e o "Tocar agora" vêm todos de graça. Um cartão próprio seria uma
 *    segunda implementação do item mais complexo desta tela.
 *
 * Devolve `null` fora de uma série — o destaque não é um recurso do acervo, é um
 * recurso do CALENDÁRIO de uma série semanal.
 */
function destaqueDaSerie(coll) {
  if (!ehLink(coll) || !window.AVSerie || !AVSerie.ehDoSabadoAtual) return null;
  const sab = AVSerie.sabadoDaSemana();
  const alvo = collSongs(coll.id).find(
    (s) => AVSerie.ehDoSabadoAtual(s.serieData, coll.serie));
  return { sabado: sab, rotulo: AVSerie.rotuloData(sab), song: alvo || null };
}

// As faixas que a LISTA desenha — o destaque sai dela (ver `destaqueDaSerie`).
// Uma função só, usada pela montagem e pela paginação: duas leituras diferentes
// do mesmo array fariam o contador de "restantes" discordar do que há na tela.
function faixasDaLista(coll) {
  const todas = collSongs(coll.id);
  const d = destaqueDaSerie(coll);
  if (!d || !d.song) return todas;
  return todas.filter((s) => s !== d.song);
}

function blocoDestaque(coll) {
  const d = destaqueDaSerie(coll);
  if (!d) return null;
  const cx = document.createElement('div');
  cx.className = 'serie-destaque' + (d.song ? '' : ' vazio');

  const cab = document.createElement('div'); cab.className = 'serie-destaque-cab';
  const rot = document.createElement('span'); rot.className = 'serie-destaque-rot';
  rot.textContent = 'Este sábado';
  const dia = document.createElement('span'); dia.className = 'serie-destaque-data';
  dia.textContent = d.rotulo;
  cab.appendChild(rot); cab.appendChild(dia);
  cx.appendChild(cab);

  if (d.song) {
    // `.coll-songs` junto do modificador: a linha herda o corpo, o raio e o
    // alvo que a lista já define, sem uma segunda folha para manter em dia.
    const ul = document.createElement('ul');
    ul.className = 'coll-songs serie-destaque-lista';
    ul.appendChild(hymnResultRow(coll, d.song, null, true));
    cx.appendChild(ul);
  } else {
    const vazio = document.createElement('div');
    vazio.className = 'serie-destaque-vazio';
    vazio.textContent = 'Aguardando lançamento';
    cx.appendChild(vazio);
  }
  return cx;
}

// (`hymnalStat` — o construtor dos chips do painel — saiu na v5.232 com o
// último chip que restava, o do peso: ele já estava na barra do card, antes
// mesmo de abrir.)

// Só re-renderiza os cards de coleção se a aba Álbuns estiver de fato visível —
// evita custo de DOM à toa enquanto o operador está em outra aba durante o download.
//
// COALESCIDO: o progresso da sincronização chama isto uma vez por música
// baixada (e uma vez por álbum indexado no auto-refresh). Sincronizar um
// hinário de 613 hinos com a aba aberta reconstruía a lista inteira 613 vezes
// — centenas de <li> com SVG inline cada. Como a informação é meramente
// informativa, um re-render a cada COLL_REFRESH_MS basta; a chamada final
// (fim do download, status limpo) chega pelo mesmo caminho e fecha o estado.
const COLL_REFRESH_MS = 400;
let collRefreshTimer = null;
// O acervo não tem mais aba própria (v5.44): quem o mostra é o estado padrão da
// busca. UMA definição de "ele está de fato à vista", usada pelo redesenho e
// pela espera abaixo — duas escritas da mesma pergunta divergiriam no primeiro
// ajuste, e a de baixo passaria a segurar (ou a soltar) o redesenho errado.
function acervoAVista() {
  return hymnSearchPopupEl.classList.contains('open')
    && searchIsBrowsing(normalizeForSearch(hymnSearchInputEl.value).trim());
}
/**
 * ===== O PROGRESSO ESPERA A GAVETA FECHAR (v1.1.2) =====
 *
 * Relato do operador: *"enquanto está baixando as coletâneas, eu não consigo
 * abrir os itens nos álbuns para ver e interagir com o que já está baixado,
 * como se a atualização da tela por causa dos downloads estivesse fechando a
 * seção de opções de play"*.
 *
 * Era isso mesmo. `renderSearchResults` em modo folhear faz
 * `hymnResultsEl.innerHTML = ''` e remonta os cards inteiros — e o que ABRE uma
 * linha vive no `li` que ele acabou de jogar fora: a classe `expanded`, a
 * closure `gavetaMontada`, os destinos marcados (`destMarcados`, zerados por
 * `destLimpar()` na remontagem) e a letra já lida. A cada 400 ms de download a
 * gaveta voltava fechada e vazia.
 *
 * **A espera é a resposta certa, e não restaurar o estado depois.** Remontar a
 * gaveta a cada 400 ms apagaria os destinos marcados, recarregaria a letra e
 * mexeria no scroll debaixo do dedo — três coisas que o operador está usando
 * justamente enquanto ela está aberta. O que se perde esperando é o número do
 * progresso ficar parado no card por alguns segundos, e ele volta em dia no
 * primeiro tique depois que a gaveta fecha.
 *
 * O tique se REARMA em vez de marcar um pendente: a espera dura exatamente o
 * tempo em que há gaveta aberta, e o desfecho (um redesenho com o estado final)
 * acontece sozinho, sem depender de alguém lembrar de chamar isto de dentro de
 * cada caminho que fecha uma gaveta.
 */
function interacaoAbertaNoAcervo() {
  // `abrindo` conta como aberta, e é ela que fecha o caso do RELATO: entre o
  // toque e o `expanded` há um `await` (a letra sai do IndexedDB, o estado de um
  // vídeo sai de `mediaByYoutube`), e era ali que o redesenho alcançava a linha
  // — o `li` do toque virava órfão e a classe caía num nó fora do documento. O
  // toque não fazia nada, e nada explicava por quê.
  //
  // `.acoes-abertas` é a MESMA armadilha na outra lista deste host: a seção de
  // Favoritos da Biblioteca é montada aqui dentro, e o `⋮` de uma linha dela
  // morre no mesmo `innerHTML = ''`.
  //
  // `.lib-item.expanded` é a TERCEIRA marca de abertura deste host, e ela não é
  // opcional: desde a v5.290 a linha de um favorito e a de um arquivo de pasta
  // do aparelho são montadas por `linhaDeItem`, cuja gaveta se marca assim — e
  // as três classes acima não a alcançam. Sem ela, abrir a gaveta de um
  // favorito enquanto um álbum baixa (ou uma pasta sincroniza, que chama
  // `statusPasta` uma vez POR ARQUIVO) a perdia em até 400 ms, com os destinos
  // marcados junto. Marca de abertura nova entra AQUI: este seletor é a única
  // definição de "há interação aberta neste host".
  //
  // O `:not(.folder-opfs)` é o contrário de um esquecimento. A PASTA aberta é
  // estado que o redesenho PRESERVA de propósito (`pastaAberta` a reabre em
  // `renderFolderList`), e ela fica aberta o tempo todo — contá-la faria a
  // espera se rearmar para sempre e o progresso do download nunca chegar à
  // tela. O que precisa de proteção é a gaveta de dentro dela, que é
  // `.lib-item.expanded` sem `.folder-opfs`.
  return !!hymnResultsEl.querySelector(
    '.hymn-result.expanded, .hymn-result.abrindo, .acoes-abertas,'
    + ' .lib-item.expanded:not(.folder-opfs)',
  );
}
function refreshCollectionsIfVisible() {
  if (collRefreshTimer) return;
  collRefreshTimer = setTimeout(() => {
    collRefreshTimer = null;
    if (acervoAVista() && interacaoAbertaNoAcervo()) {
      refreshCollectionsIfVisible();   // rearma: o redesenho sai quando fechar
      return;
    }
    renderCollectionsNow();
  }, COLL_REFRESH_MS);
}
function renderCollectionsNow() {
  // Só redesenha com o acervo à vista — redesenhar por baixo de uma lista de
  // músicas tiraria do lugar o que o operador mira.
  if (acervoAVista()) renderSearchResults(hymnSearchInputEl.value);
  // (O painel de opções vive DENTRO do card desde a v5.72, então ele é
  // redesenhado junto com o acervo — não há mais um popup a sincronizar à
  // parte.)
}

// A tela de FAVORITOS: os caminhos curtos para o que o operador usa toda
// semana, e não "o lugar onde os arquivos moram".
//
// UMA LISTA, e duas naturezas nela (v5.254): os itens marcados, na ordem que o
// operador der a eles, e — no fim — as pastas do APARELHO, que ele sincronizou
// uma vez e que trazem os arquivos inteiras. As pastas VIRTUAIS (`folders` /
// `folder_<id>`), que ele criava aqui para agrupar o que já havia favoritado,
// saíram a pedido dele; o conteúdo delas subiu para a lista por
// `migrarPastasParaFavoritos`.
// O ESTADO DE UMA PASTA MORA NA LINHA DELA (v5.207).
//
// A sincronização de uma pasta do dispositivo falava por uma faixa flutuante no
// topo da tela: "Sincronizando 12/340…", "Pasta já em dia", "Erro na
// sincronização". Três mensagens sobre UMA linha que estava na tela, logo
// abaixo, com o dedo ainda em cima do botão de sincronizar — e a resposta
// aparecendo a meia tela de distância, por cima de outra coisa.
//
// Aqui ela ocupa o lugar do CONTADOR daquela pasta, que é exatamente o número
// que a sincronização está mudando: enquanto ela corre, o contador vira o
// progresso; terminada, ele volta a ser a contagem. Nenhum elemento novo.
const pastaStatus = new Map();
function statusPasta(id, texto, ms) {
  if (!id) return;
  const antes = pastaStatus.get(id);
  if (antes && antes.timer) clearTimeout(antes.timer);
  if (!texto) pastaStatus.delete(id);
  else {
    pastaStatus.set(id, {
      texto,
      timer: ms ? setTimeout(() => { pastaStatus.delete(id); renderFoldersSeVisivel(); }, ms) : 0,
    });
  }
  renderFoldersSeVisivel();
}
// Só redesenha quando a lista de pastas está de fato à vista — o mesmo cuidado
// do `refreshCollectionsIfVisible`: uma sincronização de 600 arquivos rodando
// com a gaveta fechada não pode remontar a lista a cada arquivo.
function renderFoldersSeVisivel() {
  // A OUTRA CASA (v5.237): com o grupo Favoritos aberto dentro da Biblioteca, a
  // mesma lista está na tela por outro caminho — e sem isto ela ficaria com a
  // contagem de uma pasta que acabou de sincronizar, ou com um favorito que já
  // saiu.
  //
  // COALESCIDO, e não imediato. O único chamador de verdade é o `statusPasta`
  // do laço de cópia de uma pasta do aparelho — UMA VEZ POR ARQUIVO —, e a
  // versão imediata redesenhava a Biblioteca inteira (todas as seções abertas,
  // todos os cards, todas as linhas) a cada arquivo copiado: numa pasta de
  // centenas de vídeos, centenas de reconstruções de DOM enquanto o operador
  // rola a mesma tela. O coalescimento de 400 ms já existia e tem nome; o que
  // faltava era este caminho passar por ele. O número que ele mostra é
  // informativo — é o mesmo argumento que criou o coalescimento.
  refreshCollectionsIfVisible();
}

// ===== OS FAVORITOS TÊM DUAS CASAS, E UMA IMPLEMENTAÇÃO SÓ (v5.237) =====
//
// Pedido do operador: *"coloque os favoritos dentro da biblioteca… Pode deixar
// a seção de favoritos no topo da listagem."*
//
// A lista continua sendo montada por `renderFolderList`, e desde a v5.294 há
// UM host só: o corpo `data-fav-corpo` da seção de Favoritos da Biblioteca (a
// gaveta de tela cheia saiu). É o mesmo padrão do `favHost` logo acima, e a razão
// é a de sempre: duas marcações para a mesma
// lista divergem no primeiro ajuste, e aqui divergiriam em gestos (o toque
// longo que entra na seleção múltipla), na alça de arrastar e na estrela.
//
// Por VARIÁVEL DE MÓDULO e não por parâmetro em cada função: quem escreve na
// lista são o item e a pasta do aparelho, e enfiar um `alvo` nas duas — e em
// todas as futuras — é a mesma sincronização manual que este projeto recusa.
// Ela é ligada e desligada num ponto só, num `try/finally`.
let favHost = null;
// Sem `favHost` não há onde desenhar: a seção de Favoritos é a ÚNICA casa desta
// lista desde que a gaveta saiu (v5.294), e ela é montada dentro do corpo do
// grupo pelo `comBaldeDeMiniaturas`. Devolver `null` aqui é o certo — quem
// chama `renderFolderList` fora daquele `try/finally` está enganado, e um host
// de emergência esconderia o engano desenhando num nó que ninguém vê.
function favAlvo() { return favHost; }

/**
 * O BALDE DE `object-URL` DA TERCEIRA CASA.
 *
 * `thumbEl` cria as URLs das miniaturas e as empurra em `thumbUrlsAtual` — o
 * balde do render EM CURSO. Quem troca esse balde e revoga o anterior é só o
 * `renderLibrary`, e ele o faz por CHAVE — o host único `libraryEl` e a string
 * `'fav-biblioteca'`. A seção de Favoritos DENTRO da Biblioteca é o segundo
 * balde, desenhada pelo mesmo
 * `renderFolderList` por outro caminho: as URLs que ela criava caíam no balde
 * de OUTRO host, e o `renderLibrary` seguinte — que roda a cada 400 ms enquanto
 * um download corre — as revogava COM ELAS EM CENA. As miniaturas da Biblioteca
 * simplesmente sumiam, e nada explicava por quê.
 *
 * A chave é uma STRING e não o elemento: o corpo da seção é recriado a cada
 * render completo da Biblioteca, e um `Map` keyado pelo nó nunca reencontraria
 * o balde do render anterior — trocaria a revogação prematura por um vazamento.
 */
function comBaldeDeMiniaturas(chave, fn) {
  const anterior = thumbUrlsAtual;
  (thumbUrlsPorHost.get(chave) || []).forEach((u) => URL.revokeObjectURL(u));
  thumbUrlsAtual = [];
  thumbUrlsPorHost.set(chave, thumbUrlsAtual);
  try { fn(); } finally { thumbUrlsAtual = anterior; }
}

function renderFolderList() {
  // O menu de uma linha não sobrevive ao redesenho: o `li` que a classe marcava
  // deixou de existir, e a referência viraria um nó órfão preso para sempre.
  fecharAcoesDaLinha();
  if (opfsFolders.length === 0 && favItems.length === 0) {
    // UMA LINHA, E SÓ (v5.239, pedido do operador: *"remova todo o texto e
    // explicações no corpo da lista dos favoritos, mantenha apenas um 'Nenhum
    // favorito ainda'"*). O que estava aqui explicava COMO favoritar e COMO
    // criar pasta — duas instruções num corpo de lista, quando a ação de trazer
    // uma pasta está a um dedo dali, na barra da seção, e a estrela está em
    // cada linha do app inteiro. Instrução que descreve um botão visível é
    // ruído; o botão é a instrução.
    const empty = document.createElement('li');
    empty.className = 'empty';
    empty.textContent = 'Nenhum favorito ainda.';
    favAlvo().appendChild(empty);
    return;
  }
  // UMA LISTA SÓ, na ordem da lista `favs` (ordem de chegada), editável pelo
  // par ↑↓. Sem subdivisão por tipo: o operador procura pelo LUGAR onde ele
  // mesmo pôs o item, e uma lista que se reorganiza sozinha impede isso.
  //
  // AS PASTAS DO APARELHO VÊM PRIMEIRO — a lista de favoritos cresce por baixo
  // delas, e no fim cada favorito novo as empurraria para longe.
  //
  // OS ITENS MORAM NUMA PLACA (`.fav-itens`), AS PASTAS NÃO. Os dois níveis
  // querem bases diferentes: o item precisa de placa de card atrás dele (sobre
  // o tom da seção mede 1,03:1 no escuro — some), a pasta precisa do tom da
  // seção (sobre a placa mediria 1,00:1). A placa é o par que o álbum já usa
  // (`.hymnal-card` PINTA, `.coll-songs` zera o degrau seguinte) e só nasce
  // quando há item. As pastas ficam filhas diretas do corpo, vestindo a cor de
  // álbum pela regra do `--camada` que ele declara — sem CSS próprio.
  opfsFolders.forEach((f) => {
    const li = document.createElement('li');
    li.className = 'lib-item folder-opfs';
    const row = document.createElement('div'); row.className = 'row';
    const icon = document.createElement('div'); icon.className = 'thumb thumb--icon';
    icon.appendChild(msym(ICON.import));
    const nameEl = document.createElement('span'); nameEl.className = 'row-name'; nameEl.textContent = f.name;
    // O CONTADOR É TAMBÉM O CANAL DE ESTADO desta pasta (ver `statusPasta`):
    // durante a sincronização ele mostra o progresso, e depois volta a ser a
    // contagem. É o número que a ação está mudando — nada mais perto do alvo.
    const st = pastaStatus.get(f.id);
    const countEl = document.createElement('span');
    countEl.className = 'folder-count' + (st ? ' folder-count--st' : '');
    countEl.textContent = st ? st.texto : String(f.count || 0);
    const syncBtn = document.createElement('button'); syncBtn.className = 'row-btn'; syncBtn.title = 'Re-sincronizar com a pasta do dispositivo';
    // Setas circulares, o MESMO desenho de "sincronizar" dos cards de coleção.
    // Antes era `ICON.import` (folder_open) — o mesmo glifo do ícone à esquerda,
    // que identifica a pasta: na mesma linha, o operador via o mesmo desenho
    // duas vezes, um como identidade e outro como ação (com a lixeira ao lado).
    syncBtn.innerHTML = syncIconSvg();
    syncBtn.addEventListener('click', (e) => { e.stopPropagation(); syncDeviceFolder(f, syncBtn); });
    const rmBtn = document.createElement('button'); rmBtn.className = 'row-btn'; rmBtn.title = 'Excluir pasta e arquivos sincronizados';
    rmBtn.appendChild(msym(ICON.del));
    rmBtn.addEventListener('click', (e) => { e.stopPropagation(); deleteOpfsFolder(f); });
    row.append(icon, nameEl, countEl, syncBtn, rmBtn);
    li.appendChild(row);
    // ===== A PASTA ABRE INLINE, COMO UM ÁLBUM (v5.290) =====
    //
    // Pedido do operador: *"ajuste o sistema de pastas dos favoritos, para que
    // ele abra a lista de arquivos das pastas de forma visual sem ser um popup,
    // para que abra a lista assim como abrem os álbuns com seus itens"*.
    //
    // Ela abria uma GAVETA de tela cheia (`#favPopup`), que desde a v5.238 só
    // existia para isto — o botão de porta dela já tinha saído. Uma pasta é um
    // CONTÊINER de arquivos, exatamente como um álbum é um contêiner de faixas,
    // e o app já sabe desenhar isso: o mesmo acordeão, no mesmo lugar, com as
    // mesmas linhas de item.
    //
    // O corpo é montado UMA vez, e só quando a pasta abre: o catálogo de uma
    // pasta sincronizada tem centenas de arquivos, e montá-los para todas as
    // pastas a cada redesenho da seção seria o trabalho de DOM da tela inteira
    // por algo que ninguém está vendo. (É a mesma decisão do corpo de um grupo
    // da Biblioteca, v5.237.)
    const corpo = document.createElement('ul');
    corpo.className = 'folder-itens';
    li.appendChild(corpo);
    let montado = false;

    async function montarCorpo() {
      corpo.innerHTML = '';
      let arquivos = [];
      try { arquivos = (await AVDB.filesByFolder(f.id)) || []; } catch (_) { arquivos = []; }
      // Por NOME, que é a ordem em que o operador procura — a do disco é a de
      // gravação, e não diz nada a quem está montando um culto.
      arquivos.sort((a, b) => (a.name || '').localeCompare(b.name || '', 'pt-BR'));
      if (!arquivos.length) {
        const vazio = document.createElement('li');
        vazio.className = 'empty';
        vazio.textContent = 'Pasta vazia.';
        corpo.appendChild(vazio);
        return;
      }
      // SEM `lista`: aqui não há ordem a mexer (ela vem do disco) nem excluir a
      // oferecer — apagar um arquivo desta pasta é apagar o ARQUIVO, e isso tem
      // dono próprio na linha da pasta ("Excluir pasta e arquivos
      // sincronizados"). Um excluir por linha ainda seria desfeito pela
      // sincronização seguinte, que é o mesmo argumento que mantém o renomear
      // fora daqui (v5.288).
      arquivos.forEach((a) => corpo.appendChild(linhaDeItem(a, {
        destinos: ['playlist', 'cronograma', 'favoritos'],
      })));
    }

    row.addEventListener('click', async (e) => {
      if (e.target.closest('.row-btn')) return;
      if (li.classList.contains('expanded')) {
        pastaAberta = null;
        collapseAccordion(corpo, () => li.classList.remove('expanded'));
        return;
      }
      // Uma pasta aberta por vez, como um álbum: duas listas de centenas de
      // arquivos empurrariam para fora da tela justamente a que o operador mira.
      const irmas = li.parentElement;
      if (irmas) {
        irmas.querySelectorAll(':scope > .folder-opfs.expanded').forEach((el) => {
          if (el !== li) el.classList.remove('expanded');
        });
      }
      if (!montado) { montado = true; await montarCorpo(); }
      pastaAberta = f.id;
      li.classList.add('expanded');
      expandAccordion(corpo);
    });

    // A pasta ABERTA continua aberta depois de um redesenho da seção (favoritar
    // um arquivo de dentro dela redesenha os Favoritos). Sem isto, cada ação
    // dentro da pasta a fecharia — que é o defeito que a v5.289 corrigiu na
    // gaveta da linha, um nível acima.
    // (Sem animação: quem anima é o TOQUE. Um redesenho por outro motivo — o
    // progresso de uma sincronização, uma estrela marcada — reencontra a pasta
    // já aberta, e vê-la "abrir" de novo sozinha leria como se algo tivesse
    // acontecido. É a mesma regra do `animarAbertura` do card de álbum.)
    if (pastaAberta === f.id) {
      montado = true;
      li.classList.add('expanded');
      montarCorpo();
    }
    favAlvo().appendChild(li);
  });

  if (favItems.length) {
    const placa = document.createElement('ul');
    placa.className = 'fav-itens';
    favItems.forEach((item, i) => placa.appendChild(favItemRow(item, i, favItems.length)));
    favAlvo().appendChild(placa);
  }
}

// Uma linha da seção "Favoritos" — o item em si, não um grupo. Tocar faz o
// MESMO que tocar nele no Cronograma (`onTap`: mídia toca, cena projeta), a
// estrela desmarca e o `+` manda para a lista do culto. São as três coisas que
// se quer de um favorito, sem entrar em pasta nenhuma.
function favItemRow(item, pos, total) {
  return linhaDeItem(item, {
    lista: 'favs', pos, total, destinos: ['playlist', 'cronograma'],
    depoisDeExcluir: () => recarregarFavoritos(),
  });
}

/**
 * A LINHA DE UM ITEM QUE JÁ EXISTE, com a gaveta de opções no corpo dela.
 *
 * Ela nasceu como `favItemRow` (v5.287) e virou geral na v5.290, quando a pasta
 * do aparelho passou a abrir INLINE: as duas listas mostram registros prontos e
 * respondem ao toque do mesmo jeito, e uma segunda anatomia divergiria da
 * primeira no primeiro ajuste — foi por essa razão que a linha de favorito
 * copiou a da Biblioteca, e ela continua valendo um nível acima.
 *
 * O que MUDA entre as duas mora em `opts`, e nada mais:
 *
 *  · `lista` — a lista a que a linha pertence, e de onde o excluir a tira. A
 *    pasta do aparelho NÃO tem uma (`null`): ali "excluir" apagaria o arquivo
 *    físico, que tem dono próprio (o "Excluir pasta e arquivos sincronizados"
 *    da própria pasta), e reordenar não faz sentido — a ordem vem do disco.
 *  · `destinos` — quais linhas marcáveis a gaveta oferece. Num favorito
 *    "Favoritar" não muda nada; num arquivo da pasta ela é justamente o caminho
 *    de promovê-lo.
 */
function linhaDeItem(item, opts) {
  const cfg = opts || {};
  const lista = cfg.lista || null;
  const pos = cfg.pos; const total = cfg.total;
  const li = document.createElement('li');
  li.className = 'lib-item' + (linhaAtiva(item.id) ? ' active' : '')
    + (linhaNoAr(item.id) ? ' no-ar' : '');
  li.dataset.id = item.id;
  const row = document.createElement('div'); row.className = 'row';
  // A MESMA coluna nome+subtítulo da biblioteca, e de propósito: uma segunda
  // anatomia de linha divergiria da primeira no próximo ajuste. O subtítulo
  // VOLTOU A APARECER na v5.254: ele era escondido por CSS porque a lista se
  // dividia em seções por tipo e o cabeçalho já dizia o que ele diria — sem as
  // seções, ele é a única coisa na linha que distingue um vídeo de um versículo.
  const textWrap = document.createElement('div'); textWrap.className = 'row-text';
  const nome = document.createElement('span'); nome.className = 'row-name'; nome.textContent = item.name;
  const sub = document.createElement('span'); sub.className = 'row-sub';
  sub.textContent = subtituloItem(item);
  textWrap.append(nome, sub);
  // (A ALÇA DE ARRASTAR viveu aqui da v5.254 à v5.284. Ela saiu na v5.285 com o
  // arrasto do app inteiro — quem reordena agora é o par ↑↓, pela mesma
  // `botoesDeOrdem` das outras duas listas.)
  // O PARAR NA MINIATURA (v5.259), como no Cronograma. Aqui ele simplesmente
  // NÃO EXISTIA: uma linha de favorito no ar mostrava o selo "● No ar" e não
  // oferecia nada que a tirasse de lá. Ele CONTINUA sendo um toque direto,
  // e é a única coisa desta linha que continua: tirar do ar é a decisão que não
  // pode custar uma gaveta.
  const miniatura = isCue(item) ? cueThumb(item) : thumbEl(item);
  porParar(miniatura, item);
  // A ESPERA DE UMA RESOLUÇÃO DE LINK (v1.4.21) — a mesma da linha do
  // Cronograma. Um link também mora nos Favoritos, e um estado que aparecesse
  // só numa das listas seria pior que nenhum: o operador aprenderia a não
  // confiar nele.
  porCarregando(li, miniatura, item.id);
  row.append(miniatura, textWrap);
  li.appendChild(row);

  // ===== A LINHA DOS FAVORITOS GANHA A GAVETA DA BIBLIOTECA =====
  //
  // O `⋮` e a faixa que ele abre existem para caber numa linha que responde ao
  // toque com OUTRA coisa (no Cronograma, projetar): sem lugar embaixo, a
  // gaveta só tinha para onde ir por CIMA do título. Aqui o toque deixa de
  // projetar, o corpo da linha fica livre, e a sobreposição some por construção.
  //
  // Esta lista mora DENTRO da Biblioteca, e é isso que decide o lado da regra:
  // a Biblioteca é a tela em que se PREPARA (o toque abre opções), o Cronograma
  // é a lista com que se OPERA (o toque projeta). O `⋮` continua inteiro lá.
  //
  // PREÇO: projetar um favorito passou de um toque a três. Em troca as três
  // listas ficam a um toque do mesmo lugar (antes, mandar um favorito à
  // playlist não tinha caminho nenhum nesta tela).
  const gaveta = document.createElement('div');
  gaveta.className = 'hymn-gaveta';
  const opcoes = document.createElement('ul');
  opcoes.className = 'song-menu-list hymn-opcoes';
  // A FAIXA DE AÇÕES é o conteúdo do `⋮` de antes, verbatim. Desde a v5.302 ela
  // mora DENTRO da `<ul>`, na linha do confirmar — e o que a protege do
  // `alvo.innerHTML = ''` que `renderItemMenu` faz a cada marca é ser o MESMO
  // nó a cada remontagem: o `appendChild` a move de volta em vez de recriá-la.
  //
  // A ESTRELA NÃO ENTRA AQUI, e quem fica é a LIXEIRA. Nesta lista as duas
  // terminam num `listRemove('favs', id)`, e:
  //  1. aqui a estrela é alternador de UMA direção (todo item já é favorito,
  //     então ela nasce acesa e o único toque possível é o que apaga) — nas
  //     outras listas ela alterna de verdade e continua inteira lá;
  //  2. a lixeira PERGUNTA — e desde a v5.301 a pergunta nasce nesta mesma
  //     faixa, com o par Cancelar/Excluir no lugar dos botões e a miniatura
  //     virando lixeira (ver `pedirConfirmacaoNaLinha`);
  //  3. ela solta a prateleira invisível (`soltarAvulso`) — a diferença entre
  //     "a linha sumiu" e "os bytes saíram". Desfavoritar não é declaração de
  //     intenção de apagar.
  //
  // O RENOMEAR ENTROU AQUI NA v5.301 (pedido do operador: *"adicione o botão de
  // renomear nas opções dos itens individuais dos favoritos"*). Ele existia só
  // na linha do Cronograma desde a v5.288, e o favorito é justamente onde o nome
  // importa mais: a lista é a que o operador MONTA para reencontrar coisas, e um
  // arquivo importado chega com o nome que o aparelho deu a ele.
  //
  // ELE ENTRA PELA MESMA PORTA DO EXCLUIR — dentro do `lista ?`, e não ao lado
  // dele —, e essa guarda é o que o mantém FORA da pasta do aparelho: ali o nome
  // vem do arquivo, e um nome só no registro seria desfeito na varredura
  // seguinte, sem erro em lugar nenhum.
  // A ORDEM É A MESMA DA FILEIRA DO CRONOGRAMA (v5.302), *"com a ressalva de não
  // contar com os itens que não existem naquela lista"*: excluir · renomear ·
  // ↑ · ↓. Faltam a ESTRELA (nesta lista ela e a lixeira terminam no mesmo
  // `listRemove('favs')` — ver acima) e o botão da PLAYLIST, que aqui é uma
  // LINHA da folha de destinos logo acima, com caixa de marcação.
  const depoisDeMexer = cfg.depoisDeExcluir || (() => load());
  const acoes = document.createElement('div');
  acoes.className = 'fav-acoes';
  // ELA FICA À ESQUERDA DO CONFIRMAR, que é onde TODO irmão fica desde a v1.4.7
  // — ver `destConfirmRow`. Até lá o lado era escolha do dono da faixa
  // (`data-antes`), e um irmão que não a fizesse caía do outro lado: era essa a
  // divergência entre os Favoritos e o resto da Biblioteca.
  acoes.append(...(lista ? [
    botaoExcluirDaLinha(item, lista, depoisDeMexer),
    botaoRenomearDaLinha(item, depoisDeMexer),
    ...botoesDeOrdem(lista, item.id, pos, total),
  ] : []).filter(Boolean));
  gaveta.append(opcoes);
  // ===== A FAIXA DIVIDE A LINHA COM O CONFIRMAR (v5.302) =====
  //
  // Pedido do operador: *"ponha o botão de confirmar as escolhas do play dos
  // favoritos para que ele fique lado a lado … ajustado com a altura dos
  // botões"*. (O LADO se inverteu na v5.307 e virou regra única na v1.4.7 —
  // ver `destConfirmRow`.)
  //
  // Ela era um bloco PRÓPRIO no pé da gaveta, logo abaixo da linha do confirmar
  // — duas faixas empilhadas para o que cabe numa, e a gaveta inteira mais alta
  // por isso, num acordeão cuja regra é manter a decisão sob o dedo.
  //
  // Quem a leva para lá é o hook `aoLado` que a v5.286 abriu para o "Ver a
  // letra": a `.song-menu-go-row` já é um flex de dois filhos em que o confirmar
  // CRESCE e o irmão fica com o que precisa. Nenhum mecanismo novo.
  //
  // O NÓ É O MESMO A CADA REMONTAGEM, e isto não é economia: `renderItemMenu`
  // refaz a lista a cada marca (`alvo.innerHTML = ''`), e devolver uma faixa
  // NOVA perderia os ouvintes e, pior, apagaria uma confirmação de exclusão
  // aberta — deixando a lixeira na miniatura sem nenhum botão que a explique.
  // Devolvendo o mesmo nó, o `appendChild` apenas o MOVE.
  //
  // Sem lista não há faixa: `null` faz o confirmar ocupar a linha sozinho, que é
  // o desenho de sempre (a pasta do aparelho não tem o que oferecer aqui).
  const aoLado = () => (acoes.childElementCount ? acoes : null);

  function abrir() {
    // A gaveta que se fecha aqui pode estar PERGUNTANDO (v5.301) — e um "sim"
    // pendurado numa linha que saiu de cena é o que nenhum destrutivo pode ter.
    fecharConfirmacaoNaLinha();
    const lista = li.parentElement;
    if (lista) {
      lista.querySelectorAll(':scope > .lib-item.expanded').forEach((el) => {
        if (el !== li) el.classList.remove('expanded');
      });
    }
    // ===== REABRIR REMONTA A GAVETA =====
    //
    // A folha inteira vive em globais de MÓDULO — `songMenuFor`, `destExecutor`,
    // `destRemontar` e o Set `destMarcados` —, e há no máximo uma gaveta aberta
    // por vez. Abrir a linha B reescreve os QUATRO. A v5.302 reapontava só o
    // `songMenuFor` ao reabrir a linha A já montada, e os outros três seguiam
    // sendo os de B: o DOM de A na tela, "Confirmar" na linha de A, e o
    // `destExecutor` de B executando. Como "Tocar agora" nasce marcado
    // (`destPadraoTocar`), bastava abrir A, espiar B e voltar a A — o item B ia
    // ao Cronograma e ao TELÃO. Remontar repõe os quatro de uma vez.
    //
    // E é isto que torna verdadeira a regra escrita no `destMarcados`: *"o
    // conjunto é da FOLHA ABERTA, não do item: ele nasce vazio a cada abertura"*.
    // As marcas nunca foram por linha — o `destLimpar()` de `renderItemMenu` já
    // as zerava ao abrir a vizinha; o que faltava era o DESENHO de A concordar
    // com isso em vez de exibir caixas marcadas que não existiam mais.
    //
    // Remontar é seguro porque a faixa de ações é o MESMO nó a cada montagem (o
    // `aoLado` devolve `acoes`): o `alvo.innerHTML = ''` de `renderItemMenu` não
    // a alcança, e o `appendChild` apenas a MOVE de volta — ouvintes e uma
    // confirmação de exclusão aberta sobrevivem. A montagem continua vindo ANTES
    // do `expandAccordion`, que mede a altura do que vai ficar em cena.
    renderItemMenu(item, opcoes, cfg.destinos, aoLado);
    li.classList.add('expanded');
    expandAccordion(gaveta);
  }

  row.addEventListener('click', (e) => {
    if (e.target.closest('.row-btn')) return;
    // O SEGUNDO TOQUE RETIRA DO AR continua valendo (v5.165): com o item
    // projetado, a pergunta que a linha responde não é "o que fazer com ele?" —
    // é "tira isto do telão". A gaveta só abre quando não há nada a desfazer.
    //
    // MAS ELE TAMBÉM COLAPSA A GAVETA JÁ ABERTA, e sem isto ela não tinha como
    // fechar: o "Tocar agora" nasce marcado (`destPadraoTocar`), então confirmar
    // na própria gaveta põe o item no ar SEM colapsá-la (`closeSongMenu` é da
    // FOLHA, não da linha), e daí todo toque cai neste `return`. A marca
    // `.lib-item.expanded` presa para sempre é o que `interacaoAbertaNoAcervo`
    // lê como "há interação aberta" — e o progresso do download deixava de
    // chegar à tela pelo resto da sessão.
    if (noArAgora(item)) {
      retirarDoAr(item);
      if (li.classList.contains('expanded')) {
        fecharConfirmacaoNaLinha();
        collapseAccordion(gaveta, () => li.classList.remove('expanded'));
      }
      return;
    }
    if (li.classList.contains('expanded')) {
      fecharConfirmacaoNaLinha();
      collapseAccordion(gaveta, () => li.classList.remove('expanded'));
      return;
    }
    abrir();
  });

  // A REABERTURA depois de uma casa de reordenação (v5.285), agora na gaveta:
  // `moverNaLista` redesenha a lista inteira e o `li` que estava aberto deixa de
  // existir. Sem isto, mover três casas custaria três aberturas.
  if (lista && reabrirAcoesEm === lista + ':' + item.id) {
    reabrirAcoesEm = null;
    // Depois de o `li` entrar no documento: `expandAccordion` mede altura, e
    // fora da árvore toda medida é zero.
    setTimeout(() => { if (li.isConnected) abrir(); }, 0);
  }

  li.appendChild(gaveta);
  return li;
}

// ===== AS OPÇÕES DE UM ITEM QUE JÁ EXISTE (v5.287) =====
//
// A gaveta da Biblioteca (`renderSongMenu`) fala de uma MÚSICA DO ACERVO: ela
// tem variantes (cantada · playback · letra) e o item ainda não existe no banco
// — cada destino o cria. Aqui o registro já está pronto, e é o mesmo em todas as
// listas: o que sobra é ONDE ele deve estar.
//
// Daí não haver seletor de variante e não haver "Favoritar": o item É um
// favorito, e quem o tira de lá é a LIXEIRA da faixa de ações (a estrela saiu
// dela na v5.288 — nesta lista as duas terminavam no mesmo `listRemove`).
//
// O resto é a MESMA maquinaria — `songMenuItem` com `destino`, `destExecutor`,
// `destRemontar` e `destConfirmRow` —, pelo motivo de sempre: uma segunda lista
// de destinos com a mesma anatomia divergiria da primeira no próximo ajuste.
/**
 * ===== "TOCAR AGORA" NASCE MARCADO (v1.1.8) =====
 *
 * Pedido do operador: *"nas opções de play, deixe que venha por padrão o check
 * de tocar agora, pois é a opção que normalmente já se tem mais urgência"*.
 *
 * O que isso muda de fato é o caso de DOIS destinos: com o telão já marcado,
 * tocar em "Adicionar ao Cronograma" projeta E guarda no mesmo toque, sem
 * precisar marcar a caixa do "Tocar agora" antes. E a linha de CONFIRMAR nasce
 * na tela (ela aparece com pelo menos um marcado), então a gaveta abre já
 * respondível.
 *
 * **Só onde a mídia É LOCAL.** A folha do YouTube (`openYtMenu`) fica de fora de
 * propósito: ali "Tocar agora" TRANSMITE — abre rede, monta MSE e põe algo no
 * telão —, e as três linhas de lista significam "espere o download". Marcado por
 * padrão, um toque em "Favoritar" começaria uma transmissão na frente da
 * congregação por um destino que não pedia projeção nenhuma. Aqui os bytes já
 * estão no aparelho e o pior caso é uma faixa entrando em cena, que é o que o
 * operador está fazendo de qualquer jeito.
 *
 * Desmarcar continua sendo um toque na linha, como em qualquer destino — o que
 * muda é de qual lado a gaveta começa.
 */
function destPadraoTocar() { destMarcados.add('tocar'); }

function renderItemMenu(item, alvo, destinos, aoLado) {
  destLimpar();
  destPadraoTocar();
  // `aoLado` é o irmão do confirmar (v5.286, hoje a faixa de ações da linha —
  // ver `linhaDeItem`). Ele viaja no ESTADO, e não como argumento de
  // `destConfirmRow`, porque quem monta a linha de fecho é a folha e ela não
  // conhece o dono da gaveta.
  songMenuFor = { item, alvo, aoLado };
  // QUAIS destinos, e por que isto é parâmetro (v5.290): numa linha de FAVORITO
  // "Favoritar" seria uma opção que não muda nada — o item já está lá —, e numa
  // linha de arquivo da PASTA DO APARELHO ela é justamente o caminho de promover
  // o arquivo para os favoritos. Uma escolha que não faz nada é pior que escolha
  // nenhuma, e por isso quem sabe a resposta é quem monta a linha.
  const quais = destinos || ['playlist', 'cronograma'];
  const desenhar = () => {
    alvo.innerHTML = '';
    destRemontar = desenhar;
    destExecutor = async (alvos, btn) => {
      const marcados = alvos || [];
      const listas = marcados.filter((a) => a !== 'tocar');
      // O TELÃO VEM PRIMEIRO quando marcado, como em `renderSongMenu`: é a
      // única metade que o operador está esperando ver acontecer.
      if (marcados.includes('tocar')) await projetarItem(item);
      if (listas.length) {
        await adicionarNasListas(listasDosDestinos(listas), item.id, item.name, btn);
      }
    };
    alvo.appendChild(songMenuItem(msym(ICON.play), 'Tocar agora',
      'Sem entrar em lista nenhuma',
      (vr, btn, alvos) => destExecutor(alvos, btn), 'tocar', desenhar));
    const LINHA = {
      playlist: [ICON.queue, 'Adicionar à playlist'],
      cronograma: [ICON.cronoAdd, 'Adicionar ao Cronograma'],
      favoritos: [ICON.star, 'Favoritar'],
    };
    quais.forEach((d) => {
      const [ico, rot] = LINHA[d] || [];
      if (!rot) return;
      alvo.appendChild(songMenuItem(msym(ico), rot, '',
        (vr, btn, alvos) => destExecutor(alvos, btn), d, desenhar));
    });
    // O IRMÃO VEM DO FECHO, nunca do global — ver a nota em `destConfirmRow`.
    const go = destConfirmRow(aoLado);
    if (go) alvo.appendChild(go);
  };
  desenhar();
}

// Projetar um item que já existe — o que o toque na linha fazia até a v5.287.
// A distinção entre cena e mídia é a mesma do `onTap`, e mora numa função só
// para as duas portas (a lista principal e a gaveta) nunca divergirem.
async function projetarItem(item) {
  if (isCue(item)) { await send(item.id); return; }
  await replacePlaylistWith(item);
  send(item.id);
}

// ===== "TRAZER UMA PASTA DO APARELHO" — UM BOTÃO, UMA ORIGEM (v5.254) =====
//
// A v5.239 unificou dois botões numa folha de duas escolhas ("criar uma pasta"
// × "trazer uma pasta do aparelho"), e o argumento era o certo: os dois
// respondiam à MESMA pergunta por caminhos diferentes. Agora a pergunta tem uma
// resposta só — o operador pediu para o app não ter mais atalhos de pasta,
// apenas as pastas sincronizadas do armazenamento do aparelho —, e uma folha
// com uma opção é um toque cobrado para não escolher nada.
//
// (A folha `#songMenuPopup` continua sendo a de escolha do app; o que sai é
// esta abertura dela.)

// (`renderStorageUsage` saiu na v5.239 com os dois chamadores. `fmtBytes`
// FICA: ele é o formatador de tamanho do app inteiro — o peso de cada coleção,
// o total do acervo, o diálogo de confirmação antes de um download grande.)

// Vírgula decimal (v5.93): o app é em português e o número aparece ao lado de
// texto em português — "1.5 GB" lia como mil e quinhentos em pt-BR.
//
// Uma casa só até 10, nenhuma acima: "1,4 GB" é informação, "148,3 MB" é uma
// precisão que a medida não tem (a estimativa varia mais que essa casa) e que
// ainda faz o número balançar de largura a cada música baixada.
function fmtBytes(n) {
  const num = (v) => (v < 10 ? v.toFixed(1) : String(Math.round(v))).replace('.', ',');
  if (n >= 1073741824) return num(n / 1073741824) + ' GB';
  if (n >= 1048576) return num(n / 1048576) + ' MB';
  if (n >= 1024) return Math.round(n / 1024) + ' KB';
  return n + ' B';
}

// (`fmtParBytes` — a forma por extenso, "3,7 de 18 MB" — saiu na v5.232 com o
// chip de peso, seu único chamador. A forma curta, `fmtFracBytes`, é a das
// barras e continua.)

function renderSelbar() {
  hostSelbar();
  selbarEl.hidden = !selectionMode;
  // As ABAS NÃO SOMEM MAIS durante a seleção (v5.107): a barra passou a ocupar
  // o rodapé da lista, não a faixa de navegação. Quem cede o lugar é o
  // "Importar arquivos", e é `renderListFoot` (pela guarda de `selectionMode`)
  // que cuida disso.
  renderListFoot();
  if (!selectionMode) return;
  selCountEl.textContent = String(selected.size);
  selRenameEl.disabled = selected.size !== 1;
}

// ===== FAVORITOS: a marcação de UM TOQUE =====
//
// Até a v5.102 favoritar era "escolher (ou criar) um atalho e pôr o item nele":
// seis passos para o primeiro favorito, porque o modelo por baixo eram as
// antigas PASTAS VIRTUAIS com um nome novo. A v5.102 criou o ato simples — a
// estrela da linha marca e desmarca na hora — e deixou os atalhos como
// organização opcional; a v5.254 os removeu, a pedido do operador. O que
// organiza a lista hoje é a ORDEM, e quem a decide é ele, arrastando.
//
// A lista mora no banco (`favs`) e é um detentor de referência como qualquer
// outra (ver LISTS em db.js): favoritar segura o blob, desfavoritar deixa o gc
// decidir. Nenhuma regra de coleta nova.
function isFav(id) { return favSet.has(id); }

async function toggleFav(id, nome, btn) {
  if (!id) return;
  // A estrela já muda de estado na hora — este aviso acrescenta O QUE foi
  // marcado. Numa lista de trinta linhas, a estrela que acendeu está no meio
  // da tela e o dedo a cobre no exato instante em que ela muda.
  const rotulo = nome ? '"' + (nome.length > 24 ? nome.slice(0, 24) + '…' : nome) + '"' : 'Item';
  if (favSet.has(id)) {
    favSet.delete(id);
    // `listRemove` (e não um setState cru) porque é ele que roda o gc na MESMA
    // transação: desfavoritar algo que não está em mais lista nenhuma tem de
    // liberar o espaço, não deixar um registro invisível para trás.
    await AVDB.listRemove('favs', id);
  } else {
    favSet.add(id);
    await AVDB.listAdd('favs', id);
  }
  const marcado = favSet.has(id);
  responder(btn, 'ok', rotulo + (marcado ? ' adicionado aos favoritos' : ' removido dos favoritos'));
  await recarregarFavoritos(PULSO_MS);
  // O BOTÃO SE ATUALIZA NO LUGAR (estrela cheia ↔ vazada) e a lista só é
  // remontada DEPOIS do pulso: `renderLibrary` recria as linhas, e recriar
  // agora arrancaria da tela justamente o botão que está confirmando.
  // O redesenho continua sendo necessário — a estrela do mesmo item aparece no
  // Cronograma, dentro de um atalho e na gaveta, e na gaveta a linha até some
  // ao ser desmarcada. A DA FILA DA PLAYLIST (v1.4.25) não vem por aqui: ela
  // mora numa folha por cima desta lista, e quem a repinta é o `marcarFavoritos`
  // do `recarregarFavoritos`, chamado logo acima.
  if (btn) {
    btn.classList.toggle('on', marcado);
    btn.title = marcado ? 'Remover dos favoritos' : 'Favoritar';
    btn.innerHTML = starSvg(marcado);
  }
  // A GAVETA SOBREVIVE AO REDESENHO (v5.288): este `renderLibrary` reconstrói a
  // linha inteira, e sem esta marca a estrela fecharia as opções pela porta de
  // trás — mesmo com o ouvinte da caixa já a poupando.
  manterAcoesAbertas();
  setTimeout(renderLibrary, PULSO_MS);
}

// Relê a lista e os registros. Chamado depois de qualquer mudança — é o único
// ponto que reconstrói `favSet`/`favItems`, para os dois nunca divergirem.
//
// E DESDE A v5.258 ELE TAMBÉM REDESENHA (relato do operador: *"se estou na
// biblioteca e adiciono algo aos favoritos, ele só aparece na lista após fechar
// e abrir novamente"*). Ele estava certo, e a causa é que os favoritos têm DUAS
// casas desde a v5.237: quem redesenhava depois de favoritar era o
// `renderLibrary` — a lista de baixo —, e a seção dentro da Biblioteca é
// desenhada por `renderSearchResults`, que ninguém chamava. O estado estava em
// dia; a tela é que não.
//
// Por SEÇÃO e não pela Biblioteca inteira: `renderSearchResults` refaz o
// `innerHTML` da lista, e com ele a POSIÇÃO DE ROLAGEM — favoritar um item no
// meio do acervo jogaria o operador de volta ao topo, que é pior que o defeito.
//
// `atrasoMs` existe para o pulso: quem acabou de tocar na estrela DENTRO da
// seção veria a própria linha sumir por baixo do dedo antes de o pulso
// confirmar o que aconteceu. É o mesmo raciocínio (e o mesmo prazo) do
// `renderLibrary` adiado em `toggleFav`.
async function recarregarFavoritos(atrasoMs) {
  const ids = await AVDB.listIds('favs');
  favSet = new Set(ids);
  favItems = await AVDB.listItems('favs');
  // AS ESTRELAS QUE ESTÃO À VISTA (v1.4.25) — ver `marcarFavoritos`. Aqui, e não
  // em cada porta que favorita: este é o único ponto que reconstrói `favSet`, e
  // o `renderLibrary` adiado do `toggleFav` só alcança a lista de baixo.
  marcarFavoritos();
  if (atrasoMs) setTimeout(redesenharFavoritosNaBiblioteca, atrasoMs);
  else redesenharFavoritosNaBiblioteca();
}

// A seção de Favoritos DENTRO da Biblioteca, redesenhada no lugar. O corpo é
// marcado no `grupo()` (`data-fav-corpo`) porque ele é criado lá e não tem id:
// procurá-lo por posição ou pelo texto do cabeçalho quebraria no primeiro
// grupo novo.
function redesenharFavoritosNaBiblioteca() {
  if (!hymnSearchPopupEl.classList.contains('open')) return;
  const corpo = hymnResultsEl.querySelector('[data-fav-corpo]');
  if (!corpo) return;
  corpo.innerHTML = '';
  favHost = corpo;
  try { comBaldeDeMiniaturas('fav-biblioteca', renderFolderList); } finally { favHost = null; }
  acertarVaoDosFavoritos();
  favAssinatura = assinaturaDosFavoritos();
}

// ===== A SEÇÃO NÃO PODE FICAR PARA TRÁS DO BANCO (v5.292) =====
//
// Relato do operador: excluir uma PASTA (e os itens que ela leva junto) não
// tirava nada da tela — a linha só sumia fechando e reabrindo a Biblioteca.
//
// A causa é estrutural e não daquele botão: `deleteOpfsFolder`, `syncDeviceFolder`
// e a limpeza de catálogo terminam em `load()`, que é o funil onde `favItems`,
// `favSet` e `opfsFolders` são reaplicados ao estado do módulo — e `load()`
// redesenhava o Cronograma (`renderLibrary`) e mais nada. A seção de Favoritos
// tem DUAS casas desde a v5.237, e desde a v5.290 a de dentro da Biblioteca é a
// única alcançável: quem a desenha é `renderFolderList` com `favHost`, que
// `load()` nunca chamava. É o mesmo defeito que a v5.258 corrigiu para o
// favoritar, numa porta que aquele lote não tinha.
//
// A guarda é uma ASSINATURA e não um redesenho incondicional, e a razão é
// concreta: `load()` roda também ao mandar um item para o Cronograma, e ali a
// gaveta de opções da linha está ABERTA — refazer a seção a fecharia debaixo do
// dedo. Assim ela só é reconstruída quando o que ela DESENHA mudou.
let favAssinatura = '';
function assinaturaDosFavoritos() {
  return favItems.map((m) => m.id).join(',')
    + '|' + opfsFolders.map((f) => f.id + ':' + (f.count || 0)).join(',');
}
function sincronizarFavoritosNaBiblioteca() {
  if (!hymnSearchPopupEl.classList.contains('open')) return;
  if (assinaturaDosFavoritos() === favAssinatura) return;
  redesenharFavoritosNaBiblioteca();
}

// (O BOTÃO "VER TODOS" viveu aqui da v5.273 à v5.281 e SAIU na v5.282, com o
// `favExpandido` que ele governava — *"não tenha mais o sistema de ver mais.
// Agora quando aberta ela mostra toda a listagem"*. Ele existia porque o vão
// era uma altura EXATA e o corpo era um RECORTE; com o vão virando um PISO
// (`min-height`), a seção cresce com a lista e não há mais nada cortado para
// um botão revelar. Com ele foram embora a régua de "quantos itens ficaram de
// fora" e a leitura adiada um quadro que ela exigia — o que restou desta
// família é a MEDIDA do vão, logo abaixo, que continua sendo medida e nunca
// deduzida de uma contagem fixa: quantos favoritos cabem depende de quantas
// seções existem, de haver ou não pasta do aparelho, da altura da tela e do
// teclado.)
// Rola `lista` até o topo da seção `nome` ficar no topo da área visível dela.
// O `li` é reencontrado pelo `data-grupo` porque o redesenho que acabou de
// rodar apagou o nó que o chamador tinha na mão.
function alinharGrupoNoTopo(lista, nome) {
  if (!lista || !lista.isConnected) return;
  const el = [...lista.children].find((n) => n.dataset && n.dataset.grupo === nome);
  if (!el) return;
  const topoLista = lista.getBoundingClientRect().top
    + parseFloat(getComputedStyle(lista).paddingTop || 0);
  const dy = el.getBoundingClientRect().top - topoLista;
  // Um pixel de folga: o arredondamento do layout produz sobras minúsculas, e
  // uma rolagem de meio pixel é um tranco sem destino.
  if (Math.abs(dy) <= 1) return;
  lista.scrollTo({ top: lista.scrollTop + dy, behavior: semMovimento() ? 'auto' : 'smooth' });
}

// ===== O VÃO DOS FAVORITOS É UMA MEDIDA DE TELA =====
//
// Ele é o que sobra da TELA depois de tudo o mais COLAPSADO: uma altura em
// pixels, escrita numa custom property da lista. A conta usa a altura da BARRA
// de cada vizinho (que é a altura dele fechado, já que o resto é `display:
// none` ou nem é montado nesse estado), então ela NÃO depende de qual coleção
// está aberta — que é a propriedade inteira. Por `flex-grow` o vão era
// REPARTIDO com a coleção aberta, e os favoritos encolhiam conforme o operador
// abrisse outra coisa.
//
// OS VIZINHOS NÃO SÃO SÓ SEÇÕES (v1.0.1). Com as coleções fixas na RAIZ, a
// lista passou a ter `.hymnal-card` como filho direto, lado a lado com as
// seções — e a conta que só somava `.coll-group--drop` devolvia um vão maior
// que a tela pela altura dos quatro cards mais os vãos entre eles. O efeito é o
// oposto do que o vão existe para produzir: os favoritos ficavam grandes demais
// e empurravam as seções fechadas para FORA da primeira tela, isto é, elas
// deixavam de estar "empilhadas na base".
//
// Daí a conta ser sobre TODO filho da lista, e a barra ser procurada pelos dois
// nomes: um vizinho novo aqui entra sozinho, e o que não tiver barra responde
// com a própria altura.
//
// No CSS ele é `min-height`, não `height`: o vão é o piso, e a seção cresce
// quando a lista pede mais. Esta função não muda por causa disso — a MEDIDA é a
// mesma pergunta ("o que sobra da tela?").
function medirVaoDosFavoritos(lista) {
  if (!lista || !lista.isConnected) return;
  const vizinhos = [...lista.children].filter((n) => n.nodeType === 1);
  const fav = vizinhos.find((n) => n.classList
    && n.classList.contains('coll-group--fav'));
  if (!fav) return;
  const cs = getComputedStyle(lista);
  const gap = parseFloat(cs.rowGap) || 0;
  // O RESPIRO DO PRIMEIRO FILHO (v1.5.20, `.coll-group--drop:first-child`) é
  // MARGEM, e margem não entra em `clientHeight`/padding/gap — mas consome
  // espaço de verdade na coluna, do mesmo jeito que os outros três termos.
  // Lido do COMPUTADO (não um `--sp-5` copiado): o dia em que a regra mudar de
  // valor, ou deixar de existir, esta conta acompanha sozinha.
  const margemTopo = parseFloat(getComputedStyle(vizinhos[0]).marginTop) || 0;
  const util = lista.clientHeight - (parseFloat(cs.paddingTop) || 0)
    - (parseFloat(cs.paddingBottom) || 0) - gap * Math.max(0, vizinhos.length - 1)
    - margemTopo;
  let fechadas = 0;
  for (const s of vizinhos) {
    if (s === fav) continue;
    // FECHADA, A CAIXA É A BARRA. (Medir o `<li>` direto não serve: a seção
    // ABERTA tem corpo, e é a altura FECHADA que esta soma quer.)
    // A v1.5.9 somava aqui as duas linhas de 1px da moldura da Biblioteca; ela
    // saiu na v1.5.14 e a parcela ia junto — um termo que hoje é sempre zero,
    // com cinco linhas de comentário explicando um desenho que não existe.
    // `.row` NA LISTA desde a v1.5.17: com o `flex-grow` dos blocos de raiz, um
    // bloco que caísse no ramo de baixo (o `<li>` inteiro) entraria nesta soma
    // já CRESCIDO, e o vão dos Favoritos encolheria em silêncio. Hoje nenhum
    // bloco da raiz é uma pasta — mas a fórmula não pode depender disso.
    // `querySelector` devolve o primeiro em ordem de DOCUMENTO, não de seletor:
    // numa seção a barra vem antes de qualquer `.row`.
    const barra = s.querySelector('.coll-group-bar, .coll-bar, .row');
    fechadas += (barra ? barra.getBoundingClientRect().height
      : s.getBoundingClientRect().height);
  }
  const vao = Math.max(0, Math.round(util - fechadas));
  // Escrito na LISTA e não no `li`: o `li` é refeito a cada redesenho, e a
  // propriedade herda daqui sem que ninguém precise reaplicá-la.
  lista.style.setProperty('--fav-vao', vao + 'px');
}

// ===== A TAMPA DE UM BLOCO DE RAIZ NÃO MUDA DE ALTURA AO ABRIR (v1.5.19) =====
//
// Relato do operador: *"Ajuste o cartão das coleções, o card do titulo, pois ele
// está encolhendo ou modificando seu tamanho ao abrir sua listagem."*
//
// A CAUSA é o crescimento da v1.5.17 visto pelo outro lado. Colapsado, o bloco
// ganha `flex-grow` e cresce até a altura de encaixe (MEDIDO na captura dele,
// 411×856 com 9 blocos: 51,00px) com a barra CENTRADA dentro; ao abrir, ele
// deixa de casar `:not(.expanded)`, perde o crescimento, e a tampa cai para a
// barra nua (45,01). SALTO MEDIDO NA PRÓPRIA CAPTURA: 20,0 device px = 5,71 CSS
// = −11,2%. E ele é um SALTO, não um deslize: quadro a quadro, a tampa muda e o
// bloco sobe 5,64px em DOIS quadros, enquanto o corpo desliza por 220 ms.
//
// O TEOREMA QUE FECHA AS SAÍDAS EM CSS PURO: a tampa só pode ser CONSTANTE no
// valor MÍNIMO dela. Qualquer altura maior tem de caber em toda tela e em todo
// número de blocos — e MEDIDO, a lista já transborda com 45,19 a 360×740/9 e com
// 20 blocos em qualquer tela. A "altura de encaixe" é função da TELA e do NÚMERO
// de blocos: ela não existe como valor em CSS. Logo, ou a pílula emagrece para
// 45,19 sempre (e a sobra vai para os vãos, que sobem de 10 para 16–21px), ou o
// número é MEDIDO uma vez. **O operador escolheu manter a pílula gorda**, e é
// isso que esta função faz.
//
// ELA É A IRMÃ EXATA DO `--fav-vao`: mesma caixa, mesma régua (a BARRA de cada
// vizinha é a altura fechada dela), mesmo lugar de chamada. Não é uma COORDENADA
// guardada — é uma ALTURA recomposta a cada render —, e por isso a classe de
// defeito da v1.5.3 (o valor que envelhece por um caminho que ninguém observa)
// não se aplica.
//
// A CLÁUSULA DOS FAVORITOS É OBRIGATÓRIA, e sem ela o lote não sai: a seção dos
// Favoritos ABERTA nunca veste `--tampa-h` — ela tem `min-height: var(--fav-vao)`
// e come a folga por conta própria (v5.273). Contá-la na divisão dá a cada irmã
// uma fatia da folga que ela JÁ gastou, e a lista COLAPSADA passa a ROLAR:
// MEDIDO, 81,5px de transbordo a 430×900 com 9 blocos, e o `smoke.mjs` reprova
// em *"as fechadas ficam EMPILHADAS NA BASE"*. Como o `verificar` é `needs` do
// `web-ota`, isso seria o bundle não chegando à frota.
//
// E É SÓ A DOS FAVORITOS. Descontar TODO bloco aberto é a variante óbvia e está
// ERRADA (MEDIDO): ela leva `--tampa-h` ao piso assim que alguém abre um hinário,
// devolvendo o defeito original. Um bloco que o operador abriu continua contando
// como FECHADO — é justamente a hipótese "tudo fechado" que dá a altura que a
// tampa dele tem de manter.
function medirTampa(lista) {
  if (!lista || !lista.isConnected) return;
  // Fora do acervo (a lista de BUSCA) não há bloco de raiz que cresça, e um
  // valor de ontem herdado ali pintaria altura em linha de resultado.
  if (!lista.classList.contains('acervo')) {
    lista.style.removeProperty('--tampa-h');
    return;
  }
  const blocos = [...lista.children].filter((n) => n.nodeType === 1);
  if (!blocos.length) { lista.style.removeProperty('--tampa-h'); return; }
  const cs = getComputedStyle(lista);
  const gap = parseFloat(cs.rowGap) || 0;
  // A MESMA CORREÇÃO do `--fav-vao` (v1.5.20): o respiro do primeiro filho
  // (`.coll-group--drop:first-child`) é margem, e ela consome espaço da coluna
  // sem entrar em `clientHeight`/padding/gap.
  const margemTopo = parseFloat(getComputedStyle(blocos[0]).marginTop) || 0;
  const util = lista.clientHeight - (parseFloat(cs.paddingTop) || 0)
    - (parseFloat(cs.paddingBottom) || 0) - gap * Math.max(0, blocos.length - 1)
    - margemTopo;
  let base = 0;
  let n = 0;
  let sobra = util;
  for (const b of blocos) {
    if (b.classList.contains('coll-group--fav')
        && (b.classList.contains('aberto') || b.classList.contains('expanded'))) {
      sobra -= b.getBoundingClientRect().height;
      continue;
    }
    n++;
    // A MESMA RÉGUA do `--fav-vao`, e pelo mesmo motivo: fechada, a caixa é a
    // BARRA. Medir o `<li>` leria um bloco ABERTO com o corpo dele dentro.
    const barra = b.querySelector('.coll-group-bar, .coll-bar, .row');
    base += (barra ? barra.getBoundingClientRect().height
      : b.getBoundingClientRect().height);
  }
  if (!n) { lista.style.removeProperty('--tampa-h'); return; }
  // SÓ CRESCE, e nunca acima do teto de hoje: o `--bar-raiz-max` existe porque
  // a lista pode ter POUCOS blocos (três coleções dariam 183px cada).
  const teto = parseFloat(getComputedStyle(document.documentElement)
    .getPropertyValue('--bar-raiz-max')) || 66;
  const h = Math.max(base / n, Math.min(sobra / n, teto));
  lista.style.setProperty('--tampa-h', h.toFixed(2) + 'px');
}

// A MEDIÇÃO É ADIADA UM QUADRO, e não é cerimônia: quem chama isto durante a
// montagem da lista (o `renderCollectionsList`) ainda vai anexar as outras
// seções na mesma passada síncrona, e a conta soma a barra de CADA uma delas —
// medir na hora leria uma tela com metade das seções e devolveria um vão grande
// demais.
function acertarVaoDosFavoritos(corpoDado) {
  const corpo = corpoDado || hymnResultsEl.querySelector('[data-fav-corpo]');
  const li = corpo && corpo.parentElement;
  if (!li) return;
  requestAnimationFrame(() => {
    // O redesenho é a cada 400 ms durante um download: reconferir que o `li`
    // ainda é o do documento evita medir um nó que já foi substituído.
    if (!li.isConnected) return;
    medirVaoDosFavoritos(li.parentElement);
  });
}

// A tampa é agendada NO FIM DA PASSADA (ver o `finally` de
// `renderCollectionsList`), e não aqui dentro: esta função só é chamada com a
// seção dos Favoritos ABERTA — o `grupo()` só devolve o corpo nesse caso, e é o
// que o comentário do `favCorpo` diz por extenso. Pendurar a tampa aqui a
// deixava sem medida nenhuma no estado padrão (Favoritos FECHADOS), que é
// exatamente o cenário do oráculo: MEDIDO, os blocos caíam para a barra nua
// (45,19) e o D5/D5b reprovavam.
//
// A ORDEM ENTRE AS DUAS É OBRIGATÓRIA, e é o preço declarado da cláusula dos
// Favoritos: `--tampa-h` lê a ALTURA RENDERIZADA daquela seção, que é governada
// por `--fav-vao`. Não há realimentação — o `--fav-vao` soma BARRAS, que
// `--tampa-h` nunca muda (MEDIDO, 1769px antes e depois) —, mas há ORDEM. Ela
// sai de graça do agendamento: `acertarVaoDosFavoritos` registra o `rAF` DENTRO
// da passada síncrona e este registra no `finally` dela, e os callbacks de
// `requestAnimationFrame` rodam na ordem em que foram registrados.
function acertarTampa(lista) {
  if (!lista) return;
  requestAnimationFrame(() => { if (lista.isConnected) medirTampa(lista); });
}

// O botão de estrela de uma linha. `.on` = favoritado (a cor faz o estado, como
// no resto do app); o rótulo diz o que o toque FAZ.
// A estrela SÓLIDA quando marcada, contornada quando não — e por isso ela é
// SVG, não o glifo da fonte: `material-symbols.woff2` é um subset ESTÁTICO da
// família *Outlined*, sem o eixo `FILL` da fonte variável, então o glifo
// `star` desenha sempre a mesma estrela vazada. Cor sozinha carregava o estado,
// mas preenchido × vazado é a convenção universal de "favorito" — é o que se
// reconhece sem aprender, e some a dúvida de "esta estrela dourada quer dizer
// que está marcado ou que dá para marcar?".
const STAR_PATH = 'M12 3.4l2.7 5.47 6.03.88-4.36 4.25 1.03 6.01L12 17.17l-5.4 2.84 1.03-6.01L3.27 9.75l6.03-.88z';

function starSvg(cheia) {
  return '<svg viewBox="0 0 24 24" width="19" height="19" aria-hidden="true"'
    + (cheia
      ? ' fill="currentColor" stroke="none">'
      : ' fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round">')
    + '<path d="' + STAR_PATH + '"/></svg>';
}

/**
 * ===== O BOTÃO DA PLAYLIST DIZ SE O ITEM ESTÁ NELA (v5.302) =====
 *
 * Pedido do operador: *"faça com que o estado de adicionado à playlist seja um
 * botão que visualmente responda se aquele item está ou não na playlist, não
 * apenas a confirmação de 'enviado para playlist'"*.
 *
 * Ele nasceu na v5.301 como uma AÇÃO: tocava, respondia com o ✓ do `pulsar` e
 * voltava ao mesmo desenho. Um segundo depois a linha não dizia mais nada — e a
 * pergunta que o operador faz montando o culto não é "eu mandei?", é "**está
 * lá?**". Sem resposta na linha, conferir custava abrir a fila.
 *
 * Agora ele é o que a ESTRELA já era: um ALTERNADOR com estado à vista. Mesma
 * anatomia (`favBtn`/`toggleFav`), mesma dupla de cores (`--line` apagado,
 * `--accent` aceso) e a mesma exceção no fecho da caixa — o desfecho dele é o
 * próprio botão mudando de desenho sob o dedo.
 *
 * E o SEGUNDO toque TIRA da fila, que é a metade que faz dele um estado em vez
 * de um contador: um botão que só acende nunca se apaga, e a única forma de
 * desfazer seria abrir a playlist e procurar a linha lá dentro.
 */
function plBtnDaLinha(item) {
  const b = document.createElement('button');
  b.className = 'row-btn row-playlist';
  vestirPlBtn(b, naPlaylist(item.id));
  b.addEventListener('click', (e) => { e.stopPropagation(); togglePlaylist(item, b); });
  return b;
}

// "Este id está na fila AGORA?" — lido de `plItems`, que é o espelho em memória
// da lista `playlist` e é refeito em todo caminho que a muda.
function naPlaylist(id) { return !!id && plItems.some((m) => m.id === id); }

// Ícone e rótulo NUM LUGAR SÓ: ele é escrito na construção da linha e outra vez
// no toque, e duas cópias divergiriam no primeiro ajuste de texto.
function vestirPlBtn(b, dentro) {
  b.classList.toggle('on', dentro);
  const t = dentro ? 'Tirar da playlist' : 'Adicionar à playlist';
  b.title = t;
  b.setAttribute('aria-label', t);
  b.setAttribute('aria-pressed', dentro ? 'true' : 'false');
  b.innerHTML = playlistIconSvg(dentro);
}

/**
 * A FILA, em dois estados. SVG inline e NUNCA um glifo: a fonte é um subset
 * estático de pouco mais de trinta codepoints, `playlist_add_check` não está
 * nele, e um codepoint ausente desenha um RETÂNGULO VAZIO sem erro em lugar
 * nenhum (a armadilha da v5.184 e da v5.200).
 *
 * A diferença entre os estados é o SÍMBOLO, não só a cor: `+` = "cabe aqui",
 * `✓` = "já está". Cor sozinha não sobrevive a um salão escuro nem a quem não
 * distingue os dois tons, e é a única coisa que a estrela tem de sobra (ela
 * também troca vazada por cheia).
 */
function playlistIconSvg(dentro) {
  return '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor"'
    + ' stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    + '<line x1="3" y1="6" x2="15" y2="6"/><line x1="3" y1="11.5" x2="15" y2="11.5"/>'
    + '<line x1="3" y1="17" x2="10" y2="17"/>'
    + (dentro
      ? '<polyline points="13.2 17.4 15.8 20 20.8 14.6"/>'
      : '<line x1="17.5" y1="13.5" x2="17.5" y2="21"/><line x1="13.75" y1="17.25" x2="21.25" y2="17.25"/>')
    + '</svg>';
}

/**
 * ===== O CRONOGRAMA GANHOU O IRMÃO DO BOTÃO DA PLAYLIST (v1.4.25) =====
 *
 * Pedido do operador: *"na lista da playlist, pode adicionar opções como:
 * adicionar aos favoritos e adicionar ao cronograma"*.
 *
 * A fila era a única das três listas sem caminho curto para as outras duas: da
 * linha dela só se saía tirando da fila. As outras duas já se alcançam
 * mutuamente (a estrela e o botão da playlist estão na gaveta do Cronograma; a
 * folha de destinos está na gaveta de um Favorito), e o buraco era exatamente
 * o lugar em que o operador monta o bloco de louvores — descobrir ali que uma
 * faixa merece ficar guardada é o caso normal.
 *
 * ALTERNADOR, como a estrela e o botão da fila, e pelo mesmo argumento da
 * v5.302: a pergunta que se faz montando o culto não é "eu mandei?", é "**está
 * lá?**". Um botão que só acende nunca se apaga, e desfazer custaria trocar de
 * tela.
 *
 * TIRAR DAQUI NÃO APAGA BYTES, e isso não é sorte: esta linha existe porque o
 * item está NA FILA, e a fila é detentora de referência como qualquer outra
 * lista (ver LISTS em `db.js`) — o `listRemove('imports')` roda o coletor na
 * mesma transação e encontra a `playlist` segurando o registro.
 */
function cronoBtnDaLinha(item) {
  const b = document.createElement('button');
  b.className = 'row-btn row-crono';
  vestirCronoBtn(b, noCronograma(item.id));
  b.addEventListener('click', (e) => { e.stopPropagation(); toggleCronograma(item, b); });
  return b;
}

// "Este id está no Cronograma AGORA?" — lido de `cronoSet`, o espelho em memória
// da lista `imports`. Ele existe porque `libItems` só tem a ABA ATIVA: com a
// Biblioteca aberta ou a Bíblia na tela, a lista do culto não está em memória
// nenhuma, e a fila da playlist é justamente uma folha que se abre por cima de
// qualquer uma delas.
function noCronograma(id) { return !!id && cronoSet.has(id); }

// Ícone e rótulo NUM LUGAR SÓ, como em `vestirPlBtn`: ele é escrito na
// construção da linha e outra vez no toque, e duas cópias divergiriam no
// primeiro ajuste de texto.
function vestirCronoBtn(b, dentro) {
  b.classList.toggle('on', dentro);
  const t = dentro ? 'Tirar do Cronograma' : 'Adicionar ao Cronograma';
  b.title = t;
  b.setAttribute('aria-label', t);
  b.setAttribute('aria-pressed', dentro ? 'true' : 'false');
  b.innerHTML = cronogramaIconSvg(dentro);
}

/**
 * O CRONOGRAMA, em dois estados. SVG inline e NUNCA um glifo — a razão é a de
 * sempre (subset estático, codepoint ausente desenha retângulo vazio), e aqui
 * ela é dupla: `more_time` está no subset, mas a variante com `✓` não existe, e
 * um par de estados em que um lado é glifo e o outro é desenho sairia com dois
 * pesos de traço no mesmo botão.
 *
 * O RELÓGIO é a família que este app já escolheu para o Cronograma (ver
 * `ICON.cronoAdd`): ele diz o que a lista é — a ORDEM do culto —, e é o que o
 * separa à primeira vista da pilha de linhas da playlist, que é o vizinho dele
 * na fileira. A diferença entre os estados é o SÍMBOLO, não só a cor: `+` =
 * "cabe aqui", `✓` = "já está".
 */
function cronogramaIconSvg(dentro) {
  return '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor"'
    + ' stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    + '<path d="M20.4 13.2A8.6 8.6 0 1 0 12.4 20.4"/>'
    + '<polyline points="11.4 6.4 11.4 12 15 13.8"/>'
    + (dentro
      ? '<polyline points="14.6 18.4 17 20.8 21.4 16.2"/>'
      : '<line x1="18.2" y1="15" x2="18.2" y2="21.4"/><line x1="15" y1="18.2" x2="21.4" y2="18.2"/>')
    + '</svg>';
}

/**
 * Entra ou sai do Cronograma, com o desfecho no próprio botão — o espelho do
 * `togglePlaylist`.
 *
 * `renderLibrary()` só é chamado quando a lista de trás É o Cronograma: fora
 * disso ela não está na tela, e refazê-la seria trabalho de DOM para ninguém.
 * `marcarNoCronograma()` repinta os botões que ESTÃO à vista, e é ele que faz o
 * estado continuar honesto na fila enquanto a lista de baixo mostra outra aba.
 */
async function toggleCronograma(item, btn) {
  if (!item || !item.id) return;
  const dentro = noCronograma(item.id);
  if (dentro) { await AVDB.listRemove('imports', item.id); cronoSet.delete(item.id); }
  else { await AVDB.listAdd('imports', item.id); cronoSet.add(item.id); }
  const agora = noCronograma(item.id);
  // `'ok'` NAS DUAS DIREÇÕES, como em `toggleFav` e `togglePlaylist`: o pulso diz
  // que o toque valeu, e QUAL das duas coisas aconteceu quem diz é o ícone que
  // fica.
  responder(btn, 'ok');
  vestirCronoBtn(btn, agora);
  marcarNoCronograma();
  libItems = await AVDB.listItems('imports'); renderLibrary();
}

/**
 * O ESTADO DOS BOTÕES DO CRONOGRAMA, repintado no lugar — o irmão do
 * `marcarNaPlaylist`, e ele existe pelo mesmo motivo: a lista `imports` muda por
 * portas que não redesenham a fila (a folha de destinos, a gaveta de um
 * favorito, o excluir de uma linha), e um botão que promete um estado antigo é
 * pior que um que não promete nada.
 *
 * Só mexe no que MUDOU, como o irmão: reescrever o `innerHTML` de botões que já
 * estão certos é trabalho de DOM à toa.
 */
function marcarNoCronograma() {
  document.querySelectorAll('.row-crono').forEach((b) => {
    const li = b.closest('.lib-item,.row-item');
    const dentro = noCronograma(li && li.dataset.id);
    if (dentro !== b.classList.contains('on')) vestirCronoBtn(b, dentro);
  });
}

/**
 * O ESTADO DAS ESTRELAS, repintado no lugar — o terceiro irmão (v1.4.25).
 *
 * Ele mora em `recarregarFavoritos`, que é o ÚNICO ponto que reconstrói
 * `favSet`: toda porta que favorita passa por lá, então a próxima que aparecer
 * já nasce coberta. O `renderLibrary` adiado do `toggleFav` cobria só a lista de
 * baixo; a estrela da fila da playlist (v1.4.25) mora numa folha por cima dela,
 * que aquele redesenho não alcança.
 */
function marcarFavoritos() {
  document.querySelectorAll('.fav-btn').forEach((b) => {
    const li = b.closest('.lib-item,.row-item');
    if (!li) return;   // a estrela de uma MENSAGEM não mora numa linha de mídia
    const marcado = isFav(li.dataset.id);
    if (marcado === b.classList.contains('on')) return;
    b.classList.toggle('on', marcado);
    b.title = marcado ? 'Remover dos favoritos' : 'Favoritar';
    b.innerHTML = starSvg(marcado);
  });
}

/**
 * Entra ou sai da fila, com o desfecho no próprio botão.
 *
 * `listAdd`/`listRemove` e não um `listSet`: é o `listRemove` que roda o coletor
 * na MESMA transação, e a fila é detentora de referência como qualquer outra
 * lista (ver LISTS em `db.js`). Tirar da fila algo que não está em mais lugar
 * nenhum tem de liberar o espaço, não deixar um registro invisível para trás.
 *
 * `renderPlaylist()` é quem repinta os outros botões (`marcarNaPlaylist`), então
 * este não precisa saber que existem — e continua certo quando a fila muda por
 * outra porta.
 */
async function togglePlaylist(item, btn) {
  if (!item || !item.id) return;
  const dentro = naPlaylist(item.id);
  if (dentro) await AVDB.listRemove('playlist', item.id);
  else await AVDB.listAdd('playlist', item.id);
  plItems = await AVDB.listItems('playlist');
  const agora = naPlaylist(item.id);
  // `'ok'` NAS DUAS DIREÇÕES, como em `toggleFav`: o pulso diz que o toque
  // valeu, e QUAL das duas coisas aconteceu quem diz é o ícone que fica. O
  // âmbar (`'dup'`) é reservado para "já estava lá", que aqui não existe — este
  // botão nunca repete a ação que acabou de fazer.
  responder(btn, 'ok');
  vestirPlBtn(btn, agora);
  renderPlaylist();
}

/**
 * O ESTADO DOS BOTÕES DE PLAYLIST, repintado no lugar — o irmão do `marcarNoAr`.
 *
 * A fila muda por MUITAS portas e quase nenhuma redesenha a lista: o toque no
 * corpo de uma linha a SUBSTITUI por aquele item (`replacePlaylistWith`), a
 * folha de destinos acrescenta, o avanço automático não muda nada mas o "Guardar
 * pacote" e o `plPopup` mudam. Sem este repintor, o botão de toda OUTRA linha
 * ficaria dizendo o que era verdade antes do último toque — que é pior que não
 * dizer nada, porque agora ele promete um estado.
 *
 * Ele mora em `renderPlaylist()`, e não em cada porta: todo caminho que REFAZ
 * `plItems` chama `renderPlaylist()` logo depois (é o redesenho da fila), então
 * a próxima porta que aparecer já nasce coberta. A régua é essa, e não "toda
 * escrita na lista `playlist`" — `criarCue` grava direto no banco sem refazer o
 * espelho, mas o que ele grava é uma CENA DE ROTEIRO, e um cue nunca ganha este
 * botão (a guarda `!isCue` de `renderLibrary`).
 *
 * E na PRIMEIRA linha dela, nunca no fim: `renderPlaylist` volta cedo quando a
 * fila fica vazia (o ramo do `count === 0`), e no fim ele não rodaria justamente
 * no caso em que TODOS os botões precisam apagar.
 *
 * Só mexe no que MUDOU — reescrever o `innerHTML` de botões que já estão certos
 * é trabalho de DOM à toa a cada redesenho da fila.
 */
function marcarNaPlaylist() {
  document.querySelectorAll('.row-playlist').forEach((b) => {
    const li = b.closest('.lib-item,.row-item');
    const dentro = naPlaylist(li && li.dataset.id);
    if (dentro !== b.classList.contains('on')) vestirPlBtn(b, dentro);
  });
}

function favBtn(id, nome) {
  const b = document.createElement('button');
  const on = isFav(id);
  b.className = 'row-btn fav-btn' + (on ? ' on' : '');
  b.title = on ? 'Remover dos favoritos' : 'Favoritar';
  b.innerHTML = starSvg(on);
  b.addEventListener('click', (e) => { e.stopPropagation(); toggleFav(id, nome, b); });
  return b;
}

// ===== ações de reprodução / sequência =====
// `daFila` = o avanço automático da playlist chamou. Ver a guarda de imagem
// sobre áudio, lá dentro: é a única coisa que a distingue de um toque.
async function send(id, daFila, retomarEm) {
  ++projecaoSeq;   // ver `projecaoSeq`: invalida um versículo de roteiro em voo
  derrubarPalcoEmVoo();   // ver `palcoEmVoo`: e o cartão de uma resolução de link
  // UMA CENA DE ROTEIRO NÃO É MÍDIA: ela não pode virar um comando `load` (o
  // telão apagaria, porque um registro sem blob/url/pages cai no `clear` do
  // stage). A guarda fica AQUI, e não só no toque da lista, porque `send` é o
  // ponto por onde TODOS os caminhos passam — o avanço automático da playlist,
  // o ⏮/⏭ do transporte, a notificação nativa e o pacote logo acima.
  const alvo = [...plItems, ...libItems, ...favItems].find((m) => m.id === id)
    || (await AVDB.getMedia(id));
  if (isCue(alvo)) {
    currentItem = alvo;
    currentId = id;
    await persistCurrent();
    await playCue(alvo);
    // DEPOIS do `playCue`, e não antes: um pacote (`group`) não põe nada no ar,
    // e um versículo pode falhar (capítulo ausente e sem internet). Quem
    // responde "esta cena está no ar?" são as sessões, não a intenção — e
    // marcar antes deixaria o realce e o segundo toque apontando para uma cena
    // que nunca chegou ao telão.
    cueNoArId = cenaDeRoteiroNoAr() ? id : '';
    marcarNoAr();
    return;
  }
  // O ITEM DE LINK NÃO VAI AO TELÃO COMO LINK (v5.212). Ele é resolvido agora —
  // transmissão direta ou download — e quem projeta é o registro que sair daí.
  // A guarda fica AQUI pelo mesmo motivo da guarda de cena de roteiro logo
  // acima: `send` é o ponto por onde TODOS os caminhos passam (o avanço
  // automático da playlist, o ⏮/⏭ do transporte, a notificação nativa).
  if (alvo && alvo.kind === 'youtube') {
    await resolverLinkYoutube(alvo);
    return;
  }
  // ===== IMAGEM SOBRE ÁUDIO (v5.312) =====
  //
  // Com um áudio no ar, tocar numa IMAGEM sobrepõe em vez de substituir: o
  // louvor de fundo continua e o aviso entra por cima. É a regra que o
  // versículo já segue, aplicada ao outro tipo de conteúdo que só ocupa a
  // tela — e foi a escolha do operador entre as três (*"automático: o toque já
  // sobrepõe"*).
  //
  // A guarda mora AQUI pelo mesmo motivo das duas acima: `send` é o ponto por
  // onde TODOS os caminhos passam. E ela é a ÚLTIMA das três porque as outras
  // recusam o que nem é mídia; esta escolhe entre dois jeitos de projetar.
  //
  // **Não vale para o avanço automático da fila** (`autoAdvance`): ali a
  // imagem é o PRÓXIMO item da sequência, não um cartão que alguém pediu por
  // cima do atual — sobrepor faria a fila parar de andar sozinha, com o áudio
  // anterior tocando para sempre sob a imagem nova.
  //
  // A APRESENTAÇÃO ENTROU NA MESMA GUARDA (v1.4.28), a pedido do operador:
  // *"adicione a possibilidade de música atrás dos slides… os slides devem ser
  // tratados como camada, assim como as imagens ou os textos e mensagens"*. Um
  // deck e uma imagem respondem à mesma pergunta — conteúdo que só ocupa a
  // TELA —, e responder a ela em dois lugares diferentes seria a divergência
  // de sempre.
  //
  // O GESTO É O MESMO DA IMAGEM, e por isso é assimétrico: a música vem
  // PRIMEIRO, e o toque na apresentação a cobre. O contrário (deck no ar, e o
  // toque numa música) SUBSTITUI, como sempre substituiu — inventar uma segunda
  // regra para a mesma pergunta é o que este arquivo recusa em toda parte, e o
  // operador já conhece esta.
  //
  // ===== E O MODO FÁCIL NÃO SOBREPÕE (v1.4.32) =====
  //
  // Pedido do operador: *"no modo simples, coloque a limitação de apenas um
  // elemento ativo na mídia, assim no modo simples não há sobreposição e nem
  // necessidade de multicontroles"*.
  //
  // A sobreposição é uma CENA COMPOSTA — duas coisas no ar ao mesmo tempo —, e
  // operá-la exige saber qual das duas cada controle governa: o ▶ é do áudio de
  // baixo, o ⏭ é da apresentação de cima, o Parar tira uma só. Esse é o
  // vocabulário do modo avançado, e é exatamente o que o Modo Fácil existe para
  // não pedir de quem opera. Ali o toque tem UM significado: *isto vai para o
  // telão* — e o que estava vai embora.
  //
  // A GUARDA MORA AQUI, e não em cada porta: `send` é o ponto por onde TODOS os
  // caminhos passam, inclusive o compartilhamento (que no Modo Fácil projeta na
  // hora, sem perguntar nada). Uma limitação escrita nas portas seria a lista
  // que envelhece no primeiro caminho novo.
  //
  // **É `appMode`, e não "há tela?" nem o Modo Fácil bloqueado.** A pergunta é
  // sobre o VOCABULÁRIO daquele modo, não sobre o estado da conexão.
  if (!daFila && appMode !== 'simple' && alvo
      && (alvo.kind === 'image' || isDeck(alvo)) && audioNoAr()) {
    projetarVisualSobre(alvo);
    return;
  }
  currentId = id;
  // O registro já foi resolvido acima (listas carregadas, com o IDB como
  // reserva) — a mídia AVULSA (v5.87 — "Tocar agora" num vídeo do YouTube) não
  // está em lista nenhuma, e sem essa leitura o `|| currentItem` deixava no ar
  // o nome do item ANTERIOR, que é pior que nome nenhum.
  currentItem = alvo || currentItem;
  // ===== O PLAYER É UM DETENTOR (v1.3.13) =====
  //
  // Pedido do operador, nas palavras dele: *"onplayer também deveria ser um
  // elemento que mantém a existência de um item no sistema"*. Ele apagou do
  // Cronograma um item que estava tocando, e a cena caiu.
  //
  // O coletor só conhece LISTAS: `listRemove` pergunta se algum outro detentor
  // aponta o id e, não achando nenhum, apaga os bytes na MESMA transação. Estar
  // NO AR não era detenção nenhuma — então sair da última lista matava o
  // registro de baixo de uma projeção. A cena até seguia (o `<video>` já tem os
  // bytes), mas era irrecuperável: uma queda de dongle chama
  // `resendSceneToDisplay`, e o `getMedia` não acharia mais nada.
  //
  // A PRATELEIRA `avulsos` JÁ ERA A RESPOSTA, e já era usada assim no Modo
  // Fácil e no "Tocar agora" — ela existe exatamente para segurar "a mídia em
  // cena sem pertencer a lista nenhuma". O que faltava era pô-la a valer no
  // modo avançado, onde o item quase sempre TEM lista e por isso nunca era
  // fixado. `fixarAvulso` é idempotente e faz rodízio de três, então tocar o
  // culto inteiro não empilha nada.
  //
  // AQUI e não no toque da lista: `send` é o ponto por onde TODOS os caminhos
  // passam — o avanço automático da playlist, o ⏮/⏭ do transporte, a
  // notificação nativa, o roteiro. É o mesmo argumento das três guardas acima,
  // e é o que faz a proteção valer para o excluir da LINHA, o da seleção
  // múltipla e qualquer caminho de remoção que venha depois.
  //
  // SEM `await`: a cena não pode esperar por cinco transações de IndexedDB, e o
  // que a proteção defende acontece segundos depois (o dedo indo até a lixeira).
  // O `soltarAvulso` do caminho de excluir compara com `currentId`, que já foi
  // escrito acima de forma síncrona — a guarda não depende desta gravação.
  fixarAvulso(id).catch(() => { /* a prateleira é cache; falhar nela não derruba a cena */ });
  // ===== A CIFRA COMEÇA A SER BUSCADA AGORA, NÃO AO ABRIR A ABA (v1.1.16) =====
  //
  // Pedido do operador: *"que a busca da cifra seja automaticamente ao tocar a
  // música e não ao abrir a aba de cifras"*.
  //
  // A rede deixa de estar no caminho crítico. Quem abre a aba está com o
  // instrumento na mão e a música já tocando — esperar ali um GET a um site de
  // terceiro é esperar no pior momento possível. Disparada aqui, a folha
  // costuma estar pronta antes de alguém pedir por ela.
  //
  // AQUI e não no toque da lista: `send` é o ponto por onde TODOS os caminhos
  // passam (o avanço automático da playlist, o ⏮/⏭ do transporte, a notificação
  // nativa, o roteiro). É o mesmo argumento das três guardas acima.
  //
  // `cifraGarantir` é IDEMPOTENTE — a entrada no cache nasce no estado
  // `buscando` e é ela que impede uma segunda requisição —, então repetir a
  // mesma música não repete a rede. E não há `await`: a cena não pode esperar
  // pela cifra, que é auxiliar; a aba se redesenha sozinha quando a resposta
  // chega. Falha nenhuma daqui atravessa para o `send` (o `catch` mora lá).
  if (cifraCabe(currentItem)) cifraGarantir(currentItem);
  // Independência áudio × texto: um ÁUDIO (música de fundo) NÃO encerra o texto
  // manual em cena (Bíblia/Mensagem/cronômetro); qualquer VISUAL (vídeo/imagem/
  // YouTube) encerra. Um louvor de fundo sob a contagem regressiva de abertura
  // é justamente o uso normal.
  if (!(cenaDeRoteiroNoAr() && currentItem && currentItem.kind === 'audio')) clearManualText();
  await persistCurrent();
  ytEnded = false;
  displayStatusAt = 0; // até o Display confirmar o novo item, a preview dirige
  lastDisplayTime = 0;
  // A apresentação entra sempre pela PRIMEIRA página: quem manda o operador
  // para outra é o par de botões do transporte, e uma cena nova que começasse
  // no meio do deck anterior seria um slide aleatório no telão.
  deckPagina = 0;
  // O ESQUELETO DA LINHA DO TEMPO. Todo caminho que projeta passa por aqui — o
  // toque na lista, o avanço da playlist, o ⏮/⏭ do transporte, a notificação
  // nativa —, e é a linha à qual todas as outras se penduram: "o telão parou"
  // só é investigável ao lado de "o que estava no ar quando parou".
  //
  // O NOME É O QUE O OPERADOR RECONHECE, não o id. E `← fila` sai só quando o
  // app SABE que veio do avanço automático (`daFila`); um toque não é afirmado,
  // porque este ponto não distingue toque de reenvio programático.
  diagC('entrou em cena: ' + ((currentItem && currentItem.name) || id)
    + (daFila ? ' ← fila' : ''));
  // E O HISTÓRICO DO CULTO, pelo mesmo argumento da linha acima: `send` é o
  // ponto por onde TODOS os caminhos passam. Ver `historicoRegistrar`.
  historicoRegistrar(id, currentItem);
  // A POSIÇÃO VIAJA DENTRO DO `load`, nunca como um `seek` logo depois — o
  // `onCommand` do Display NÃO serializa, o `load` é assíncrono (getMedia →
  // opfsGetFile → mediaReady, mais o fade de saída), e um comando que chegasse
  // em seguida agiria sobre o `<video>` ANTERIOR. É o mesmo contrato que a
  // reconexão do telão usa; quem o alimenta aqui é a volta do RECADO.
  const carga = { type: 'load', mediaId: id, view, muted, volume, page: 0 };
  if (retomarEm && retomarEm.t > 0) carga.time = retomarEm.t;
  if (retomarEm && retomarEm.playing === false) carga.playing = false;
  cmd(carga);
  // A partir daqui há mídia no telão — é o que a reconexão precisa reenviar e o
  // que o ▶ pode retomar em vez de recarregar (ver `midiaNoAr`).
  midiaNoAr = true;
  midiaNoArId = id;
  // E a ORIGEM cai aqui, sempre: `send` é o ponto por onde todo play passa, e
  // uma origem que sobrevivesse a um play normal deixaria a linha do link
  // marcada como "no ar" enquanto outra mídia toca. Quem a repõe é o único
  // caminho que precisa dela (`resolverLinkYoutube`), DEPOIS de projetar.
  midiaNoArOrigem = '';
  // re-render leve de estados ativos
  marcarNoAr();
  renderNowPlaying();
  // E o EIXO DOS BOTÕES, que muda com o item (v5.101). Sem esta linha, trocar
  // de mídia deixava ⏮/⏭ com o estado da mídia ANTERIOR — e para uma
  // APRESENTAÇÃO isso é permanente: quem repunha os limites era o pulso de
  // `timeupdate` da preview, que só existe em áudio/vídeo. Um deck é imagem
  // parada, então nada mais rodava: o nome já dizia "1/9" (ele sai de
  // `renderNowPlaying`, que É chamado) e os botões continuavam apagados,
  // sem passar página. Parecia intermitente porque dependia do que estava em
  // cena ANTES — vindo de uma música com letra os botões já estavam acesos e
  // funcionavam; vindo de uma imagem, não. Só uma importação consertava, e por
  // acidente: ela termina em `load()`, que chama isto.
  renderSlideNav();
  if (currentItem && currentItem.kind === 'youtube') {
    // Zera a UI de transporte; o display-status remoto assume em seguida.
    seekEl.value = 0; seekEl.max = 0; seekEl.disabled = true;
    curTimeEl.textContent = '0:00'; durTimeEl.textContent = '0:00';
  }
}

// ⏮/⏭ TROCAM DE MÍDIA — é a mesma intenção do avanço automático, e por isso
// passam `daFila`. Sem ele a imagem seguinte era SOBREPOSTA ao áudio no ar:
// `currentId` continuava no áudio, o `idx` daqui não andava, e o botão "Próxima
// mídia" (aqui, na notificação e na tela de bloqueio) parava de andar na fila.
// A sobreposição continua valendo para o toque na LINHA, que é onde o operador
// escolhe o cartão — ver a guarda de imagem sobre áudio em `send`.
function step(delta) {
  if (plItems.length === 0) return;
  const idx = plItems.findIndex((m) => m.id === currentId);
  const target = idx === -1 ? 0 : (idx + delta + plItems.length) % plItems.length;
  send(plItems[target].id, true);
}

// Navegação manual de estrofe (independente da posição do áudio): pula pro
// tempo do slide vizinho reaproveitando o comando `seek` já existente — o
// Display (e a preview) sincronizam a letra sozinhos ao reagir ao novo tempo.
// Quem os botões de estrofe controlam: sempre o elemento NO AR, nunca o que
// apenas existe em memória — uma sessão de leitura pode continuar aberta com a
// Escritura FORA do ar, e aí o hino que reaparece ficaria sem controle. A ordem
// abaixo é a da precedência visual: texto manual cobre a letra, e a letra volta
// a mandar assim que o texto sai.
// REGRA: tudo o que muda a resposta desta função precisa chamar
// `renderSlideNav()`, e não só `renderNowPlaying()`. As duas descrevem a MESMA
// cena (nome e eixo dos botões); o nome tem muito mais caminhos de atualização,
// então a divergência aparece sempre igual — cabeçalho certo, botões errados,
// e numa APRESENTAÇÃO isso é PERMANENTE (quem repõe os limites de tempos em
// tempos é o `timeupdate` da preview, e um deck é imagem parada).
function slideTarget() {
  // O cronômetro não tem slides. Sem esta guarda, os botões de estrofe cairiam
  // na letra do áudio de fundo — que está ESCONDIDO atrás do cartão: o operador
  // apertaria "próxima estrofe" e a música saltaria, sem nada mudar na tela.
  // A IMAGEM SOBREPOSTA entra nesta guarda pela razão que o parágrafo acima
  // descreve, ao pé da letra: ela é um cartão opaco, e a letra do áudio de
  // fundo está atrás dele.
  // A APRESENTAÇÃO SOBRE O ÁUDIO É A EXCEÇÃO DA GUARDA ABAIXO, e vem antes
  // dela: o argumento daquela é "este cartão não tem para onde ir", e um deck
  // TEM — cada toque passa uma página. Com o eixo devolvido, o ⏮/⏭ passa slide
  // enquanto o louvor de fundo continua andando por baixo, que é o pedido.
  if (deckSobreProjetando()) return 'deck';
  if (chronoProjecting() || drawProjecting() || visualSobreProjetando()) return null;
  if (lyricProjecting()) return 'songlyrics';
  if (msgSession && msgSession.projecting) return 'message';
  if (bibleSession && bibleSession.projecting) return 'bible';
  // A APRESENTAÇÃO é o alvo mais literal que este par de botões já teve: cada
  // toque passa uma página. Vem antes da letra porque um deck não tem letra —
  // são caminhos que nunca coexistem.
  if (isDeck(currentItem)) return 'deck';
  const lyrics = currentItem && Array.isArray(currentItem.lyrics) ? currentItem.lyrics : null;
  if (lyrics && lyrics.length) return 'lyrics';
  return null;
}

function stepSlide(delta) {
  const who = slideTarget();
  if (who === 'deck') { deckStep(delta); return; }
  if (who === 'songlyrics') { lyricStep(delta); return; }
  if (who === 'message') { msgStep(delta); return; }
  if (who === 'bible') { bibleStep(delta); return; }
  if (who !== 'lyrics') return;
  const lyrics = currentItem.lyrics;
  const idx = findSlideIndex(lyrics, authoritativeTime());
  const target = Math.min(Math.max(idx + delta, 0), lyrics.length - 1);
  if (target === idx) return;
  cmd({ type: 'seek', time: lyrics[target].time });
}

// Habilita/desabilita os botões de estrofe conforme o item atual tem letra
// sincronizada e a posição dentro dela (desabilita no primeiro/último slide).
function renderSlideNav() {
  // Mesmo pulso da navegação de estrofe: a leitura auxiliar (popup da letra /
  // do capítulo) e a zona de letra do modo simplificado acompanham o que está
  // no ar sem um timer próprio.
  refreshLyricsView();
  refreshSimpleLyrics();
  renderSimpleTime();
  const who = slideTarget(); // o que está NO AR — ver slideTarget()
  applySlideLimits(who);
  // O eixo do transporte é escrito DEPOIS dos limites: ele lê o `disabled` das
  // âncoras para dizer quando o toque curto não tem para onde ir.
  renderTransportAxis(who);
  renderSimpleSlides(who);
}

/**
 * AS TECLAS DE PÁGINA DO MODO FÁCIL (v1.4.30).
 *
 * Ela **espelha**, não recalcula: o `disabled` sai das âncoras que
 * `applySlideLimits` acabou de escrever, e o `who` é o mesmo `slideTarget()` da
 * linha acima. É a técnica do `renderTransportAxis`, e pelo motivo dele — uma
 * segunda conta de "posso avançar?" divergiria no primeiro caminho novo, e
 * divergiria CALADA: a tecla ficaria acesa num fim de apresentação, ou apagada
 * no meio dela.
 *
 * **SÓ COM UM DECK NO AR.** Com uma letra em cena a linha nem existe: neste modo
 * a estrofe anda sozinha pelo relógio da música, e um par de teclas oferecendo
 * um controle que ninguém precisa exercer é o que este app não faz.
 */
function renderSimpleSlides(who) {
  const d = who === 'deck' ? deckNoAr() : null;
  simpleSlidesRowEl.hidden = !d;
  // A ÁREA DE CONTROLE INTEIRA SEGUE A CENA (v1.5.14). A marca vai no
  // `.simple-remote` e não em cada peça: quem decide o que existe é a CENA, e
  // uma classe no contêiner deixa isso escrito num lugar só — as três regras
  // que dependem dela (o play e o mudo somem, a linha de volume some, o parar
  // fica sozinho e ganha rótulo) moram juntas na folha, onde se leem como um
  // desenho e não como três exceções.
  simpleRemoteEl.classList.toggle('deck', !!d);
  if (!d) return;
  simpleSlidePrevEl.disabled = slidePrevBtnEl.disabled;
  simpleSlideNextEl.disabled = slideNextBtnEl.disabled;
  simpleSlideNumEl.textContent = (deckPagina + 1) + '/' + d.pages.length;
  // O mesmo traço de curso do volume, no mesmo nó — ver `--curso`.
  simpleSlidesRowEl.style.setProperty('--curso',
    String(d.pages.length > 1 ? deckPagina / (d.pages.length - 1) : 1));
}

// Onde as âncoras de estrofe podem ir a partir daqui (é isso que `disabled`
// significa nelas). Saiu de dentro de `renderSlideNav` para o eixo do
// transporte poder ser desenhado depois — os `return` intermediários não
// deixavam.
function applySlideLimits(who) {
  // Letra avulsa: passa/volta entre as estrofes da música escolhida.
  if (who === 'songlyrics') {
    slidePrevBtnEl.disabled = lyricSession.idx <= 0;
    slideNextBtnEl.disabled = lyricSession.idx >= lyricSession.stanzas.length - 1;
    return;
  }
  // Mensagens: passa/volta entre as mensagens salvas (nos extremos desabilita).
  if (who === 'message') {
    slidePrevBtnEl.disabled = msgSession.idx <= 0;
    slideNextBtnEl.disabled = msgSession.idx >= messages.length - 1;
    return;
  }
  // Leitura bíblica: só desabilita no começo (Gn 1:1) e no fim (Ap, último
  // versículo) da Bíblia — nos limites de capítulo cruza para o vizinho.
  if (who === 'bible') {
    const s = bibleSession;
    const lastBook = Bible.BOOKS.length - 1;
    slidePrevBtnEl.disabled = (s.bookIdx === 0 && s.chapter === 1 && s.idx === 0);
    slideNextBtnEl.disabled = (s.bookIdx === lastBook
      && s.chapter === Bible.BOOKS[lastBook].chapters && s.idx === s.verses.length - 1);
    return;
  }
  if (who === 'deck') {
    const d = deckNoAr();
    slidePrevBtnEl.disabled = !d || deckPagina <= 0;
    slideNextBtnEl.disabled = !d || deckPagina >= d.pages.length - 1;
    return;
  }
  if (who !== 'lyrics') {
    slidePrevBtnEl.disabled = true;
    slideNextBtnEl.disabled = true;
    return;
  }
  const lyrics = currentItem.lyrics;
  const idx = findSlideIndex(lyrics, authoritativeTime());
  slidePrevBtnEl.disabled = idx <= 0;
  slideNextBtnEl.disabled = idx >= lyrics.length - 1;
}

// O QUE OS DOIS BOTÕES DE SLIDE ESTÃO PASSANDO AGORA — estrofe, versículo,
// mensagem ou página. Eles têm um significado só desde a v1.3.5 (o eixo de
// mídia voltou a ser dos ⏮/⏭ do transporte, e de mais ninguém), então o que
// muda com a cena não é mais o EIXO: é o SUBSTANTIVO do rótulo. Quem diz "não
// há para onde ir" é o `disabled` que `applySlideLimits` escreve — o esmaecido
// de um botão desabilitado, que é a leitura de sempre.
//
// AS TRÊS TABELAS COBREM TODOS OS ALVOS DE `slideTarget()`, e isso não é
// zelo: elas são indexadas pelo alvo, e um alvo que falte não dá erro nenhum —
// vira `undefined` e o `title` do botão passa a dizer literalmente
// "undefined". Faltavam justamente os dois mais novos, `deck` (v5.97) e
// `songlyrics` — e o da apresentação é o que mais aparece, porque ali eles são
// o único jeito de passar página.
const SLIDE_AXIS_NAME = {
  lyrics: 'estrofe', songlyrics: 'estrofe', bible: 'versículo',
  message: 'mensagem', deck: 'página',
};
const SLIDE_AXIS_PREV = {
  lyrics: 'Estrofe anterior', songlyrics: 'Estrofe anterior', bible: 'Versículo anterior',
  message: 'Mensagem anterior', deck: 'Página anterior',
};
const SLIDE_AXIS_NEXT = {
  lyrics: 'Próxima estrofe', songlyrics: 'Próxima estrofe', bible: 'Próximo versículo',
  message: 'Próxima mensagem', deck: 'Próxima página',
};
// O rótulo dos dois botões de slide. Sem alvo eles ficam com o nome genérico —
// e desabilitados, porque `applySlideLimits` já respondeu que não há para onde
// ir; um nome específico ali prometeria uma cena que não está no ar.
function renderTransportAxis(who) {
  const par = [[slidePrevBtnEl, SLIDE_AXIS_PREV[who], 'Slide anterior'],
    [slideNextBtnEl, SLIDE_AXIS_NEXT[who], 'Próximo slide']];
  for (const [btn, rotulo, generico] of par) {
    btn.title = rotulo || generico;
    btn.setAttribute('aria-label', btn.title);
  }
}

// ===== Leitura auxiliar: letra completa / capítulo inteiro =====
// O telão mostra UMA estrofe (ou UM versículo) por vez — é o formato certo
// para quem assiste, e o errado para quem opera: o operador precisa saber o
// que vem depois. Este popup é a íntegra do que está em cena, só para ler
// (com scroll); projetar continua sendo dos controles de estrofe/versículo.
//
// As duas fontes convivem: um louvor de fundo durante a leitura bíblica deixa
// letra E capítulo disponíveis ao mesmo tempo, e aí o seletor do topo escolhe.
// Sem essa disputa, a única fonte disponível abre direto, sem seletor.
let lvSource = null;      // escolha manual do operador ('lyrics' | 'bible' | null = automática)
// A CAMADA DA FRENTE vista na ÚLTIMA abertura da folha — ver `openLyricsPopup`.
let lvFrenteVista = null;
let lvCurIdx = -1;        // índice destacado (estrofe/versículo no ar)
let lvFollow = true;      // acompanhar sozinho? Desliga ao primeiro scroll manual
let lvSig = '';           // assinatura do conteúdo já renderizado (ver lvSignature)

// Fontes disponíveis AGORA, na mesma ordem de precedência da tela.
function lyricsViewSources() {
  // É PROJEÇÃO que põe uma camada na lista, nunca a existência da sessão: um
  // capítulo aberto e fora do ar não está em exibição — ele volta lá embaixo, na
  // RESERVA, que é o caso da última linha desta função.
  //
  // COM UM ALVO DA BIBLIOTECA nada de cena entra: quem abriu a folha de uma
  // música pediu AQUELA música, e o que está no telão não tem por que roubar a
  // folha de um ensaio.
  //
  // ===== TUDO O QUE ESTÁ EM EXIBIÇÃO, DA FRENTE PARA TRÁS (v1.4.26) =====
  //
  // Pedido do operador, que REVOGA a exclusividade da Bíblia (v1.1.11) e a da
  // apresentação (v1.4.24): *"o auxiliar de leitura deve deixar disponível os
  // auxiliares de tudo que estiver em exibição, seja uma música de fundo e uma
  // bíblia sobrepondo… devo ter a opção da letra, da cifra e da bíblia, pois
  // todos estes estão em exibição. É claro, o elemento na camada mais a frente
  // de tudo é o que aparece na abertura"*.
  //
  // O que as duas regras revogadas acertavam era a PRECEDÊNCIA; o que elas
  // erravam era tirar as outras da mesa. Uma camada por baixo continua no ar —
  // o louvor de fundo continua tocando sob o versículo —, e quem opera pode
  // precisar da letra dele no minuto seguinte. Hoje a lista é a PILHA, e quem
  // decide a aba que abre é a ORDEM: `lvActiveSource` devolve a primeira.
  //
  // A ORDEM É A DO `slideTarget()`, e é ela que já descreve o empilhamento do
  // telão — a Camada de Texto por cima da mídia. Duas listas com a mesma
  // pergunta divergiriam no primeiro recurso novo, e é por isso que esta ordem
  // não é escrita duas vezes: o que muda entre as duas é só o que cada uma sabe
  // fazer com a resposta.
  //
  // A CIFRA continua por ÚLTIMA, e agora ela é a única precedência que não vem
  // de camada nenhuma: ela não é projetada, é o auxiliar de quem TOCA a mídia
  // que está no ar. Por isso ela nunca abre sozinha enquanto houver o que está
  // sendo visto.
  const list = [];
  const alvo = lvItem();
  // 1. A CAMADA DE TEXTO, se estiver projetando: é o que está na frente.
  if (lvNaCena() && bibleSession && bibleSession.projecting
      && bibleSession.verses && bibleSession.verses.length) list.push('bible');
  // 2. A MÍDIA embaixo dela, e ela pode ser DUAS CAMADAS desde a v1.4.28: uma
  //    apresentação sobreposta a um louvor de fundo devolve `deck` E `lyrics`,
  //    nessa ordem, porque é essa a ordem no telão — o cartão do slide por cima,
  //    a música tocando por baixo. Antes eram exclusivos por `currentItem` ser
  //    uma coisa só; hoje o deck pode estar na CAMADA, e aí `currentItem` é a
  //    música.
  if (lvDeckRec()) list.push('deck');
  const lyrics = alvo && Array.isArray(alvo.lyrics) ? alvo.lyrics : null;
  if (lyrics && lyrics.length) list.push('lyrics');
  // 3. O auxiliar de quem toca a mídia de cima.
  //
  // SÓ NO APP. No navegador não há ponte, e sem ela não há como buscar a página
  // (CORS — ver `AVNative.cifraHtml`). Oferecer uma aba que só sabe explicar por
  // que não funciona é pior que não oferecê-la.
  if (cifraCabe(alvo)) list.push('cifra');
  // A RESERVA: sem NADA em exibição, um capítulo aberto (mesmo fora do ar) ainda
  // é o que o operador tem para ler — e é o que ele foi buscar ao abrir esta
  // folha. Ela sobrevive à revogação acima porque responde a outra pergunta: as
  // regras de cima listam o que ESTÁ no ar, e esta cobre o caso em que não há
  // nada no ar.
  if (!list.length && lvNaCena() && bibleSession && bibleSession.verses
      && bibleSession.verses.length) list.push('bible');
  return list;
}

/**
 * ===== O ALVO DO LEITOR (v1.2.14) =====
 *
 * A folha nasceu presa ao `currentItem`: ela era o "auxiliar de leitura" de
 * QUEM ESTÁ NO AR, e por isso ler uma música exigia projetá-la. Quem TOCA não
 * quer isso — ele quer abrir a cifra de um louvor no ensaio sem que a
 * congregação veja nada.
 *
 * `lvAlvo` é a música que a folha mostra quando ela NÃO é a que está em cena.
 * Nulo é o caso de sempre (o leitor segue a cena), e por isso o desvio é a
 * exceção que se declara — a mesma forma do `if (!window.__NATIVE__)`.
 *
 * **Nada aqui projeta.** O alvo não toca em `currentItem`, não emite comando e
 * não passa pelo `send`: o telão não sabe que esta folha existe.
 */
let lvAlvo = null;

/** A música que a FOLHA mostra: o alvo escolhido, ou o que está em cena. */
function lvItem() { return lvAlvo || currentItem; }

/**
 * A APRESENTAÇÃO que a FOLHA mostra — e ela não sai do `lvItem()`.
 *
 * São dois casos que o `lvItem` não distingue: um deck da BIBLIOTECA (o alvo, e
 * aí só ele conta — nada da cena entra numa folha de ensaio) e o deck que está
 * NO AR, que desde a v1.4.28 pode ser a CAMADA por cima de um louvor. Neste
 * segundo caso `lvItem()` é a MÚSICA, e perguntar a ela por páginas devolveria
 * nada: a aba "Páginas" sumiria justamente na cena que o pedido criou.
 */
function lvDeckRec() {
  if (lvAlvo) return isDeck(lvAlvo) ? lvAlvo : null;
  return deckNoAr();
}

/**
 * A folha está mostrando o que está NO AR?
 *
 * Governa as duas coisas que só fazem sentido para a cena: o DESTAQUE da
 * estrofe corrente e o RELÓGIO da rolagem automática. Com o alvo apontando para
 * outra música, seguir o `authoritativeTime()` faria a folha andar no compasso
 * de um louvor diferente — o defeito mais confuso que este recurso poderia
 * produzir, porque parece funcionar.
 */
function lvNaCena() { return !lvAlvo; }

// Qual fonte mostrar: a escolhida pelo operador enquanto continuar disponível;
// senão a primeira da lista (a letra, quando há as duas).
function lvActiveSource() {
  const avail = lyricsViewSources();
  if (lvSource && avail.includes(lvSource)) return lvSource;
  return avail[0] || null;
}

// Índice do que está no ar dentro da fonte ativa.
function lvCurrentIndex(src) {
  // SÓ A CENA TEM POSIÇÃO. Uma música aberta da Biblioteca não está tocando —
  // destacar uma estrofe dela pelo relógio de OUTRA música é pior que não
  // destacar nenhuma, porque parece certo.
  if (src === 'lyrics') {
    return lvNaCena() ? findSlideIndex(lvItem().lyrics, authoritativeTime()) : -1;
  }
  if (src === 'bible') return bibleSession.idx;
  // A APRESENTAÇÃO tem posição, e ela é a MESMA do telão: `deckPagina` é a
  // página que o ⏮/⏭ está passando. Fora da cena não há posição nenhuma, pela
  // razão da letra logo acima — uma apresentação aberta da Biblioteca não está
  // projetando, e destacar uma página dela seria inventar uma referência.
  if (src === 'deck') return lvNaCena() ? deckPagina : -1;
  // A CIFRA NÃO TEM POSIÇÃO. Ela é uma folha para ler, não uma sequência de
  // slides — não há "estrofe no ar" a destacar, e o `-1` faz o `lvScroll` sair
  // sem achar `.lv-row.current`, que é o comportamento certo: rolar sozinho
  // uma folha que o operador está lendo com a mão seria disputar o scroll com
  // ele a cada `timeupdate`.
  return -1;
}

// Muda de conteúdo? Então re-renderiza; senão só move o destaque. Cobre trocar
// de música, de capítulo e a chegada/saída de uma das fontes.
//
// A lista de fontes DISPONÍVEIS entra na assinatura, não só a ativa: com um
// louvor tocando, começar a leitura bíblica não muda o conteúdo em cena (a
// letra continua na frente) mas passa a haver o que alternar — e sem isso o
// seletor do topo só apareceria na próxima troca de estrofe.
function lvSignature(src) {
  const avail = lyricsViewSources().join('+');
  // A CHAVE É DO ALVO, não do que está em cena: com a folha aberta para uma
  // música da Biblioteca, o `send` de outra não pode trocar o conteúdo por
  // baixo de quem está lendo.
  if (src === 'lyrics') {
    const a = lvItem();
    return avail + '|lyrics|' + (lvAlvo ? 'alvo:' + (a.id || a.name) : currentId)
      + '|' + a.lyrics.length;
  }
  if (src === 'bible') {
    const s = bibleSession;
    return avail + '|bible|' + s.versionId + '|' + s.bookIdx + '|' + s.chapter + '|' + s.verses.length;
  }
  // A APRESENTAÇÃO muda de conteúdo por ITEM e por número de páginas — a
  // PÁGINA corrente fica de fora de propósito: ela é o DESTAQUE, e entrar aqui
  // faria cada toque no ⏭ remontar as dezenas de miniaturas (e revogar e
  // recriar as URLs delas) em vez de mover uma classe.
  if (src === 'deck') {
    const a = lvDeckRec();
    if (!a) return avail + '|deck|';
    // A CHAVE É DO DECK, não de `currentId`: sobreposto a um louvor, quem está
    // no ar é a MÚSICA, e chavear por ela deixaria a coluna de páginas de pé
    // depois de o operador trocar a apresentação sem trocar o áudio.
    return avail + '|deck|' + (a.id || a.name) + '|' + a.pages.length;
  }
  // A CIFRA muda de conteúdo por CHEGADA e por TRANSPOSIÇÃO, e as duas precisam
  // entrar aqui: a primeira porque a resposta da rede vem depois do desenho, a
  // segunda porque transpor não muda música nenhuma — sem o passo na assinatura,
  // o `refreshLyricsView` do pulso seguinte reverteria a folha ao tom original.
  if (src === 'cifra') {
    const e = cifraEstado(lvItem());
    return avail + '|cifra|' + cifraChave(lvItem())
      + '|' + (e ? e.estado + '|' + e.motivo + '|' + e.semitons : 'novo');
  }
  return avail + '|none';
}

/**
 * Abre a folha. Sem argumento, para o que está em cena (o caso de sempre); com
 * um item, para AQUELA música — é assim que a Biblioteca abre a mesma folha sem
 * projetar nada.
 */
function openLyricsPopup(item, fonte) {
  // O ALVO É A EXCEÇÃO, e ela se declara: um item igual ao que já está em cena
  // não é desvio nenhum, e guardá-lo faria a folha parar de acompanhar o culto
  // por uma coincidência.
  const novo = (item && item !== currentItem) ? item : null;
  const trocouAlvo = novo !== lvAlvo;
  // O ALVO É FIXADO ANTES DE PERGUNTAR QUAL É A FRENTE: `lyricsViewSources` lê
  // `lvItem()`, e com o alvo antigo ainda de pé ela responderia sobre a folha
  // anterior.
  lvAlvo = novo;
  const frente = lyricsViewSources()[0] || null;
  // A ABA ESCOLHIDA SOBREVIVE À REABERTURA, e só não sobrevive à TROCA DE
  // ALVO. São duas coisas diferentes: quem escolheu "cifra" no transporte quer
  // continuar na cifra na próxima abertura (é a preferência de quem toca o
  // culto inteiro); mas carregá-la para OUTRA música seria abrir a folha de um
  // louvor na aba que o operador escolheu para outro.
  //
  // `fonte` é o PEDIDO de quem abriu, e vence os dois — a Biblioteca abre na
  // cifra, porque quem toca ali foi buscar os acordes. Não é imposição:
  // `lvActiveSource` só a honra enquanto a fonte existir, e sem ponte
  // (navegador) a cifra nem entra na lista, então a folha abre na letra sem
  // nenhum caso especial.
  // E A CAMADA DA FRENTE VENCE A ESCOLHA GUARDADA QUANDO ELA MUDA (v1.4.26).
  //
  // "O elemento na camada mais a frente de tudo é o que aparece na abertura" —
  // e uma escolha feita numa cena não pode responder pela seguinte: quem tocou
  // "Cifra" com o louvor sozinho no ar não pediu cifra para o momento em que o
  // versículo subir por cima dele. Mudou a frente, mudou a pergunta.
  //
  // DENTRO da mesma frente a escolha SOBREVIVE, e é o que o músico pediu na
  // v1.2.x: reabrir a folha no meio do mesmo louvor devolve a cifra. E ela
  // também não é derrubada com a folha ABERTA — trocar a aba embaixo do dedo de
  // quem está lendo é pior que uma aba desatualizada, e o seletor está a um
  // toque dali.
  //
  // `lvFrenteVista` nasce `null` e isso significa *"nenhuma frente vista ainda"*,
  // nunca *"a frente mudou"*: na PRIMEIRA abertura não houve cena anterior, logo
  // não há escolha de antes a invalidar. Ler o sentinela como troca derruba uma
  // fonte pedida antes da primeira abertura — que é o que um chamador
  // programático faz, e o que o `cifra-rolagem.test.mjs` faz.
  if (fonte) lvSource = fonte;
  else if (trocouAlvo || (lvFrenteVista !== null && frente !== lvFrenteVista)) lvSource = null;
  lvFrenteVista = frente;
  lvFollow = true; // toda abertura começa acompanhando o que está no ar
  renderLyricsView();
  lyricsPopupEl.classList.add('open');
  // Depois de aberto (a folha ainda está subindo): o scroll só é possível com
  // o elemento já medido — e a MEDIDA da cifra também. No `renderLyricsView`
  // acima o popup ainda não tinha largura, então a folha saiu sem quebrar.
  requestAnimationFrame(() => { cifraRemedir(); lvScrollToCurrent(false); });
}

function closeLyricsPopup() {
  // UMA FOLHA FECHADA NUNCA DEIXA UMA TELA CHEIA DE PÉ (v1.6.0), e a invariante
  // mora AQUI porque este é o ponto único por onde passam todas as portas: o ✕,
  // o toque no fundo, o degrau 2 do voltar e o `sairDasCamadas()` de um
  // compartilhamento — que só sai da tela cheia quando há telão, e por si só
  // deixaria a folha invisível com a Activity ainda deitada.
  cifraCheiaSair();
  lyricsPopupEl.classList.remove('open');
  // O ALVO MORRE COM A FOLHA. Ele é um desvio de UMA leitura: sobrevivendo ao
  // fechamento, a próxima abertura pelo transporte mostraria a música do ensaio
  // em vez da que está no ar — e nada na tela explicaria por quê.
  lvAlvo = null;
  // E AS MINIATURAS DA APRESENTAÇÃO SAEM COM ELA: o `renderLyricsView` só as
  // solta quando desenha outra coisa, e uma folha fechada nunca chega lá.
  lvDeckSoltarUrls();
  // Sem folha na tela não há o que rolar, e um rAF vivo atrás de um popup
  // fechado é trabalho por quadro para ninguém ver.
  cifraRolarParar();
  // E A BADGE VOLTA A FALAR DA CENA: com a folha aberta ela podia estar
  // descrevendo o alvo de um ensaio (`lvAlvo`), que acabou de morrer.
  renderLeitorBadge();
}

function renderLyricsView() {
  const avail = lyricsViewSources();
  const src = lvActiveSource();
  lvSig = lvSignature(src);
  lvCurIdx = src ? lvCurrentIndex(src) : -1;

  // ===== O SELETOR MOSTRA SÓ AS FONTES QUE EXISTEM AGORA (v1.1.18) =====
  //
  // Os três botões são HTML ESTÁTICO — eles existem no documento desde a carga.
  // A v1.1.11 acertou a LISTA (`lyricsViewSources` já devolvia só o que cabe) e
  // esqueceu de usá-la aqui: o laço marcava o ativo e mais nada. Com uma música
  // em cena há duas fontes (Letra + Cifra), o seletor aparece — e a Bíblia
  // aparecia junto, sem estar em `avail`, oferecendo uma aba que a regra tinha
  // acabado de recusar.
  //
  // **Calcular a coisa certa e não aplicá-la é um defeito mudo:** a função que
  // decide continua passando em qualquer leitura, e só a tela denuncia. Por isso
  // a visibilidade de cada botão passa a sair da MESMA lista que governa a
  // precedência — uma fonte nova nasce visível pelo mesmo caminho, e uma que
  // saia some pelo mesmo caminho.
  //
  // O container ainda some inteiro com menos de duas: um seletor de uma opção
  // não é um seletor.
  // O A+/A− É DO TEXTO, e a apresentação não tem nenhum: a miniatura ocupa a
  // largura da coluna e não responde ao token. Um par de botões que continua ali
  // e não muda nada na tela é a coisa que este app não deixa acontecer — a mesma
  // regra do microfone sem TV: explicar é melhor que mentir, e não oferecer é
  // melhor que explicar. Só ESTA instância; a do Modo Fácil é outro nó.
  lyricsFonteCtlEl.hidden = src === 'deck';
  // O ⛶ SÓ EXISTE NA CIFRA (v1.6.0), pela mesma regra do microfone sem TV: não
  // oferecer é melhor que explicar. E a tela cheia SAI SOZINHA quando a cifra
  // deixa de ser a fonte — trocar de aba, ou a cena virar para uma música sem
  // cifra. Sem esta guarda o layout desenhado para a cifra passaria a mostrar a
  // letra com o seletor de abas escondido e sem o botão que devolve o retrato.
  cifraCheiaBtnEl.hidden = src !== 'cifra';
  if (cifraCheia && src !== 'cifra') cifraCheiaSair();
  lyricsViewSegEl.hidden = avail.length < 2;
  lyricsViewSegEl.querySelectorAll('.fit-opt').forEach((btn) => {
    btn.hidden = !avail.includes(btn.dataset.lvsrc);
    btn.classList.toggle('active', btn.dataset.lvsrc === src);
  });
  // ===== A ORDEM DAS ABAS É A DA PILHA (v1.4.28) =====
  //
  // Pedido do operador: *"a aba da bíblia está entre a letra e a cifra, coloque
  // ela à esquerda, pois letra e cifra são irmãs, sempre juntas quando ambas
  // existem. E é claro, a bíblia acaba sempre ficando por cima quando os três
  // são exibidos."*
  //
  // A ordem que ele descreve JÁ EXISTIA — é a de `lyricsViewSources`, a pilha
  // do que está em exibição. O que estava errado era haver uma SEGUNDA ordem: a
  // do HTML estático, escrita meses antes, que ninguém tinha razão para manter
  // em dia. Duas listas com a mesma pergunta divergem no primeiro esquecimento,
  // e esta divergiu em silêncio — a folha continuava funcionando, com a Bíblia
  // separando duas abas que são irmãs.
  //
  // Por isso a correção não é reordenar o HTML: é a tela passar a LER a única
  // ordem que existe. Reordenar só o que está à vista basta e é o que mantém a
  // regra viva — uma fonte nova entra no lugar certo por ter entrado na pilha,
  // e não por alguém lembrar de mover um `<button>`.
  //
  // `appendChild` MOVE um nó que já está no pai (não copia), então isto é uma
  // reordenação no lugar; e ela é idempotente — reanexar na ordem em que já
  // estão não muda nada na tela.
  //
  // ===== E O PAI É A `.fit-seg`, NÃO O BLOCO DE FORA (v1.4.39) =====
  //
  // Relato do operador: as abas *"estão com pouca largura, considerando que
  // deveria ter a largura adaptável para preencher a largura total
  // disponível"*. A v1.4.28 anexava em `lyricsViewSegEl` — que é o
  // `.lyricsview-seg`, o bloco com o respiro —, e os botões moram um nível
  // abaixo, dentro da `.fit-seg`. Isso não era reordenar: era REPARENTAR.
  //
  // Fora do contêiner flex o `flex: 1` do `.fit-opt` fica INERTE: cada botão
  // volta a ser `inline-block` do tamanho do próprio rótulo, encostado à
  // esquerda. MEDIDO a 430px — a faixa tem 401px e as duas abas saíam com 44,8
  // e 42,7, cada uma do tamanho da palavra.
  //
  // Falha CALADA por construção: a ordem que o pedido da v1.4.28 queria
  // continuou certa (o `appendChild` reordena do mesmo jeito), e o que se
  // perdeu foi só a largura — nada lança, nada some da tela.
  const faixaDasAbas = lyricsViewSegEl.querySelector('.fit-seg');
  for (const nome of avail) {
    const btn = lyricsViewSegEl.querySelector('.fit-opt[data-lvsrc="' + nome + '"]');
    if (btn) faixaDasAbas.appendChild(btn);
  }

  lyricsViewBodyEl.innerHTML = '';
  // AS URLS DAS MINIATURAS MORREM AQUI, no MESMO ponto em que o corpo é
  // esvaziado — é o único lugar por onde toda troca de conteúdo passa. Uma
  // `createObjectURL` que ninguém revoga segura o Blob da página VIVO enquanto
  // o documento existir, e uma apresentação são dezenas deles: a folha aberta e
  // fechada meia dúzia de vezes num culto seguraria a memória de meia dúzia de
  // apresentações num processo que já hospeda os dois WebViews e a Presentation.
  lvDeckSoltarUrls();
  // A BARRA é da cifra e de mais ninguém: limpar aqui, num ponto só, evita que
  // trocar de fonte deixe os controles da folha anterior de pé sobre a Bíblia.
  lyricsViewBarEl.innerHTML = '';
  lyricsViewBarEl.hidden = true;
  if (!src) {
    lyricsPopupTitleEl.textContent = 'Letra';
    const empty = document.createElement('div');
    empty.className = 'empty';
    empty.textContent = 'Nada em exibição com letra ou texto bíblico.';
    lyricsViewBodyEl.appendChild(empty);
    return;
  }
  if (src === 'lyrics') {
    const a = lvItem();
    const track = a.hymnTrack ? a.hymnTrack + '. ' : '';
    lyricsPopupTitleEl.textContent = track + (a.hymnName || a.name || 'Letra');
    lvBuildSong(lyricsViewBodyEl, lvCurIdx);
  } else if (src === 'deck') {
    const a = lvItem();
    // O TÍTULO É O NOME, e a posição NÃO entra nele: quem diz qual página está
    // no ar é o destaque da linha, e o cabeçalho do transporte logo acima já
    // escreve "· 3/27". Repetir o número num terceiro lugar é criar mais uma
    // fonte para divergir — a mesma razão pela qual o título da Bíblia é o
    // CAPÍTULO e não o versículo corrente.
    lyricsPopupTitleEl.textContent = a.name || 'Apresentação';
    lvBuildDeck(lyricsViewBodyEl, lvCurIdx, lvDeckUrls);
  } else if (src === 'cifra') {
    lyricsPopupTitleEl.textContent = cifraNomeDoItem(lvItem()) || 'Cifra';
    lvBuildCifra(lyricsViewBodyEl, lyricsViewBarEl);
  } else {
    const b = bibleSession;
    // A sigla da versão só entra quando a lista de versões já foi baixada — sem
    // ela `bibleVersionAbbr` devolve o rótulo genérico "Versão", que no título
    // seria só ruído.
    const abbr = bibleVersionName(b.versionId) ? ' · ' + bibleVersionAbbr(b.versionId) : '';
    lyricsPopupTitleEl.textContent = b.bookName + ' ' + b.chapter + abbr;
    lvBuildBible(lyricsViewBodyEl, lvCurIdx);
  }
}

// ===== A ABA DE CIFRA (v1.1.7) =====
//
// A terceira fonte do visualizador. Ela responde a uma pergunta que as outras
// duas não respondem: *"em que acorde eu entro?"* — e responde para quem TOCA,
// não para quem assiste. Por isso ela vive aqui, ao lado da letra, e **nunca
// vai ao telão**: o que a congregação vê continua sendo a letra, pelo caminho
// de sempre.
//
// ## QUEM BAIXA É O APARELHO, e isso é o contrato
//
// **Nada entra no bundle do OTA nem no repositório** — o app LÊ conteúdo de
// terceiro, nunca o DISTRIBUI. Cada aparelho busca o que vai usar.
//
// São DOIS caches, com prazos diferentes: o `Map` abaixo é o da SESSÃO (a
// folha em cena, com o passo de transposição), morto ao fechar o app; o
// arquivo do acervo mora no IndexedDB, em `cifras:<coleção>` — ver
// "A CIFRA DO HINÁRIO, GUARDADA NO APARELHO", com `cifraDiscoDe`/
// `cifraDiscoMesclar` e a ausência com prazo de `CIFRA_REVISITA_MS`. É ele que
// faz a folha abrir SEM REDE, que é o problema real: o Wi-Fi da igreja no
// sábado de manhã.
//
// ## As DUAS metades, e por que a segunda existe
//
//  1. **O ATALHO DO HINÁRIO.** Para uma coleção do catálogo (`AVCifra.CATALOGO`)
//     a URL é DEDUZÍVEL do nome do hino: uma requisição, direta, sem ranking de
//     ninguém escolhendo por nós. É o caminho de quase todo culto.
//  2. **A BUSCA GENÉRICA**, para qualquer outra música — e para o hino cujo
//     nome no acervo não bate com o nome no site (acontece: "Ó Vem" × "Oh, Vem").
//     Custa uma requisição a mais e por isso é a SEGUNDA tentativa, nunca a
//     primeira.
//
// ## Estados, e por que são quatro e não dois
//
// `buscando` · `ok` · `falha` · (ausente = nem pediram). E a `falha` carrega um
// MOTIVO, porque "não achei" e "não entendi a página" pedem ações opostas do
// operador — a primeira se resolve procurando outro nome, a segunda é o site
// ter mudado a marcação e só se resolve com um lote novo. Achatar as duas numa
// frase só é o defeito que o `cifra.js` chama de falhar vazio.
let lvCifraSeq = 0;
const cifraCache = new Map();   // chave → { estado, url, pagina, motivo, semitons }
let cifraUltimoDiag = '';       // a linha "Cifra:" do Registro (lado web)
/**
 * Quantas páginas da busca vale tentar. Três, e não uma: o ranking do site não é
 * o nosso — o primeiro colocado pode ser uma versão simplificada, uma playback
 * ou um homônimo. E não é ilimitado: cada tentativa é um GET a um site de
 * terceiro no meio do culto, e uma lista inteira de páginas ilegíveis não diz
 * mais que três.
 */
const CIFRA_CANDIDATOS = 3;

// A coleção a que o item em cena pertence, ou null. O registro de mídia guarda
// o NOME do álbum (`hymnAlbum`), não o id — e quem sabe traduzir um no outro é
// o catálogo de coleções, não este código.
function cifraColecaoDoItem(item) {
  const nome = item && item.hymnAlbum;
  if (!nome) return null;
  return allCollections().find((c) => c.name === nome) || null;
}

// O nome pelo qual esta música é procurada. `hymnName` primeiro (é o nome
// LIMPO do hino, sem "(Cantado)" nem variante), `name` como reserva.
function cifraNomeDoItem(item) {
  return (item && (item.hymnName || item.name)) || '';
}

/**
 * CABE CIFRA PARA ESTE ITEM? — e a resposta é UMA, para os dois consumidores.
 *
 * A mesma pergunta é feita em dois lugares (a aba, que decide se se oferece, e
 * o pré-carregamento do `send`, que decide se busca). Duas escritas dela
 * divergiriam no primeiro ajuste — e a divergência entre "o que conta como
 * acorde" e "o que é transposto" foi exatamente o que produziu o defeito da
 * v1.1.15. Uma função, dois chamadores.
 *
 * O corte é por CONTEÚDO MUSICAL, não por nome: um episódio de série é um
 * testemunho em vídeo, e procurar cifra dele é uma requisição garantidamente
 * perdida — e, pior, uma aba oferecida que só sabe dizer que não achou. Vale
 * para `audio` (todo o hinário e os álbuns) e para o que tiver LETRA, que é o
 * louvor gravado em vídeo.
 *
 * Sem ponte não cabe: no navegador não há como buscar a página (CORS).
 */
function cifraCabe(item) {
  if (!window.__NATIVE__ || !item || !cifraNomeDoItem(item)) return false;
  return item.kind === 'audio' || (Array.isArray(item.lyrics) && item.lyrics.length > 0);
}

// A chave do cache. Coleção + nome, e não o `mediaId`: a MESMA música baixada
// como Cantada e como Playback são dois registros com a mesma cifra, e chavear
// por id faria a segunda variante buscar de novo o que já está na memória.
function cifraChave(item) {
  const coll = cifraColecaoDoItem(item);
  return (coll ? coll.id : '') + '|' + AVCifra.normalizar(cifraNomeDoItem(item)).toLowerCase();
}

// UMA requisição, já interpretada — `{ ok, pagina, motivo }`.
//
// Os quatro desfechos do shell viram os quatro motivos do `cifra.js`, e a
// tradução acontece AQUI, num ponto só: `status 0` é "não houve resposta",
// `404` é "o site respondeu que não tem", outro status é "respondeu outra
// coisa", e 200 com HTML que o parser não entende é `ilegivel`. Espalhar esta
// tradução pelos chamadores é como duas listas divergem.
/**
 * `mudo: true` para o trabalho de MASSA. A radiografia é um slot só, e o
 * download das cifras do hinário roda em segundo plano com 6 trabalhadores: sem
 * esta guarda ele sobrescreve, a cada hino, a estrutura da página que o operador
 * está tentando diagnosticar. MEDIDO num Registro real — o bloco mostrava um
 * hino qualquer no lugar da página de busca que a linha acima nomeava.
 */
async function cifraPedir(url, mudo) {
  const r = await AVNative.cifraHtml(url);
  if (!r.status) return { ok: false, motivo: AVCifra.MOTIVO_SEM_REDE };
  if (r.status === 404) return { ok: false, motivo: AVCifra.MOTIVO_NAO_TEM };
  if (r.status < 200 || r.status > 299) return { ok: false, motivo: AVCifra.MOTIVO_RECUSOU };
  const pagina = AVCifra.lerPagina(r.html);
  // A RADIOGRAFIA SÓ DO CASO QUE PRECISA DELA. `ilegivel` é o único desfecho em
  // que o Registro fica devendo uma resposta: a página está lá, a rede está boa,
  // e "não entendi" não diz O QUE era. Guardá-la também no caminho feliz
  // sobrescreveria justamente a página que interessa — a última música do culto
  // apagaria a que quebrou dez minutos antes.
  if (!pagina) {
    // DOIS DESFECHOS, e eles pedem ações opostas: `sem-cifra` é o site
    // respondendo que aquela música não TEM cifra ali (a página existe e é a
    // letra ou a partitura), `ilegivel` é o parser não entendendo o que veio.
    // Achatá-los num só manda investigar um parser certo e faz a varredura
    // rebater a mesma música toda sessão. Quem decide é o `cifra.js` (regra
    // pura); aqui só se traduz o veredito.
    const variante = AVCifra.varianteSemCifra(r.html);
    // A RADIOGRAFIA VALE PARA OS DOIS. Ela era só do `ilegivel`, porque "já se
    // sabia o que a página de letra era" — e foi a radiografia que resolveu a
    // dúvida seguinte: `/ministerio-jovem/meu-senhor-minha-vida/` respondeu
    // 449 kB de "partituras para teclado", com o `<h1>` da música certa e zero
    // `<pre>`. Sem ver a FORMA da página não havia como separar "o endereço
    // está errado" de "o site não tem cifra desta música".
    if (!mudo) cifraGuardarEstrutura('página ' + url, r.html);
    // O COLETOR é o segundo destino da radiografia: a BATERIA precisa da forma
    // das páginas que ELA não entendeu, e não pode escrevê-la no slot
    // compartilhado (é justamente o diagnóstico do operador que ela enterraria).
    // A VARIANTE viaja junto do motivo: ela é o que o Registro mostra e o que
    // permite descobrir, um dia, que o site passou a servir uma terceira.
    return variante
      ? { ok: false, motivo: AVCifra.MOTIVO_SEM_CIFRA, variante }
      : { ok: false, motivo: AVCifra.MOTIVO_ILEGIVEL };
  }
  return { ok: true, pagina, motivo: AVCifra.OK };
}

/**
 * A CADEIA DE TENTATIVAS — uma escrita, dois consumidores.
 *
 * A mesma razão do `cifraCabe`: quem projeta uma música (`cifraGarantir`) e a
 * VARREDURA do acervo (`syncCifrasColecao`) precisam da MESMA cadeia, e duas
 * escritas dela divergiriam no primeiro ajuste — com a varredura guardando no
 * aparelho um resultado que a aba nunca produziria.
 *
 * Devolve `{ ok, pagina, motivo, url, via, tentativas, crus, consulta }`.
 *
 * **`via` é o degrau QUE VENCEU** (`''`, `fixada`, `aparelho`, `catalogo`,
 * `album`, `padrao`, `busca`). Ele não muda o que o app faz — quem o lê é o
 * oráculo, e é por ele que a ORDEM da cadeia fica travada: "achou" e "achou
 * pelo catálogo" respondem perguntas diferentes, e uma poda que pulasse um
 * degrau passaria despercebida sem este campo.
 *
 * `opts.mudo` cala a radiografia (trabalho de massa não pode sobrescrever a
 * página que o operador está diagnosticando); `opts.semDisco` pula o que já
 * está guardado no aparelho, porque a varredura pergunta *"o endereço ainda
 * leva à página?"* e ler o disco responde outra coisa; `opts.semBusca` pula o
 * último degrau, que em massa custa o dobro de requisições para devolver zero.
 */
async function cifraProcurar(nome, coll, opts) {
  const o = opts || {};
  const tentativas = [];
  let desfecho = { ok: false, motivo: AVCifra.MOTIVO_NAO_TEM };
  let url = '';
  let via = '';
  let crus = [];
  let consulta = nome;
  // Um degrau só falha PARA A FRENTE se a página não existir. `ilegivel` é
  // "respondeu e o parser não entendeu", e insistir noutro endereço troca o
  // motivo certo (o site mudou de formato) por um errado (a música não existe).
  const segue = () => !desfecho.ok && desfecho.motivo !== AVCifra.MOTIVO_ILEGIVEL
    && !respondidoPeloDisco && !fechadoPeloCatalogo;
  // `sem-cifra` NÃO interrompe a cadeia, e isso é escolha: ele diz que AQUELE
  // endereço não tem cifra, não que a música não exista no site — outro artista
  // pode ter a folha. Só o `ilegivel` para, porque ali a página é a certa e o
  // problema é a leitura.
  //
  // MAS ELE SOBREVIVE ATÉ O FIM. O motivo devolvido é o do ÚLTIMO endereço
  // tentado, e sem esta memória um `sem-cifra` seguido de dois 404 sairia como
  // "nenhum endereço tinha a página" — a resposta menos informativa das três,
  // e a única que manda o operador continuar procurando o que já foi achado.
  let viuSemCifra = false;
  // A AUSÊNCIA GUARDADA ENCERRA a procura — refazer a cadeia que a produziu é
  // gastar as mesmas requisições para chegar à mesma resposta. Ela vence pelo
  // PRAZO, não por um toque; o que a contorna é a escolha à mão (tentativa 0).
  //
  // Declarado AQUI, com o resto do estado, e não junto do passo que o escreve:
  // o `segue()` logo abaixo o lê, e um `const` alcançado de cima é uma zona
  // morta esperando a ordem de chamada mudar.
  let respondidoPeloDisco = false;
  // O CATÁLOGO É AUTORIDADE SOBRE O HINÁRIO (v1.2.15). Quando o endereço do
  // catálogo responde "o site só tem a letra", a procura ACABA: aquela É a
  // página daquele hino no site, e continuar é pedir os outros endereços
  // deduzíveis para uma pergunta que já foi respondida. MEDIDO num Registro
  // real: `Teu Divinal Amor` deu `sem-cifra` no catálogo e gastou mais três
  // requisições (o álbum-como-artista e os dois artistas padrão), todas 404,
  // para chegar ao mesmo veredito — vezes as ~300 do Hinário 2022 que ainda
  // faltavam varrer.
  //
  // Só vale para a coleção do CATÁLOGO. Num álbum o `sem-cifra` de um endereço
  // não fecha a pergunta: a mesma música pode estar cifrada sob outro artista.
  let fechadoPeloCatalogo = false;

  // 0,5ª TENTATIVA: O QUE JÁ ESTÁ NO APARELHO. É a única que não toca na rede,
  // e por isso é a que faz a folha abrir no sábado com o Wi-Fi da igreja
  // oscilando. Vem DEPOIS da escolha do operador (uma correção à mão vale
  // mais que o automático guardado) e ANTES de todo o resto.
  if (!desfecho.ok && !o.semDisco && coll && cifraGuardavel(coll)) {
    const disco = await cifraDiscoDe(coll.id);
    const g = disco[cifraChaveNoDisco(nome)];
    if (g && g.pagina) {
      url = g.url || '';
      desfecho = { ok: true, pagina: g.pagina, motivo: AVCifra.OK };
      via = 'aparelho';
      tentativas.push('guardada no aparelho ' + url + ' → ok');
    } else if (cifraNoDiscoVale(g, Date.now())) {
      // A AUSÊNCIA GUARDADA TAMBÉM RESPONDE, e responde na hora. Sem isto, a
      // aba gasta a cadeia inteira para chegar à MESMA frase que a varredura já
      // tinha escrito — quatro requisições e alguns segundos de "Procurando…"
      // com o instrumento na mão. O prazo é o mesmo do `cifraNoDiscoVale`: uma
      // ausência de 30 dias volta a ser perguntada.
      //
      // A ausência guardada VENCE em 30 dias e volta para a fila: é esse prazo,
      // e não uma saída manual, que impede um "não achei" de virar permanente.
      via = 'aparelho';
      // `soLetra` é a forma ANTIGA da mesma entrada (v1.2.12 a v1.2.20). Ela
      // continua sendo lida porque está gravada em aparelhos: rebaixá-la seria
      // refazer a varredura inteira por uma troca de nome de campo.
      const semCifraGuardado = g.semCifra || (g.soLetra ? 'letra' : '');
      desfecho = semCifraGuardado
        ? { ok: false, motivo: AVCifra.MOTIVO_SEM_CIFRA, variante: semCifraGuardado }
        : { ok: false, motivo: AVCifra.MOTIVO_NAO_TEM };
      respondidoPeloDisco = true;
      tentativas.push('guardada no aparelho → ' + desfecho.motivo
        + ' (de ' + new Date(g.em || 0).toLocaleDateString('pt-BR') + ')');
    }
  }

  // 1ª TENTATIVA: o atalho do catálogo.
  const direta = !desfecho.ok && !respondidoPeloDisco && coll ? AVCifra.urlDoHino(coll.id, nome) : '';
  if (direta) {
    url = direta;
    desfecho = await cifraPedir(direta, o.mudo);
    if (desfecho.motivo === AVCifra.MOTIVO_SEM_CIFRA) {
      viuSemCifra = true;
      fechadoPeloCatalogo = true;   // ver a declaração: o catálogo é autoridade
    }
    tentativas.push('direta ' + direta + ' → ' + desfecho.motivo);
    if (desfecho.ok) via = 'catalogo';
  }

  // 1,5ª TENTATIVA: O ÁLBUM DO ACERVO COMO ARTISTA DO SITE. MEDIDO:
  // "Usa-me", do álbum **Adoradores 5**, mora em `/adoradores-5/usa-me/` — o
  // nome do álbum em slug É o artista lá. É a tentativa deduzível de melhor
  // custo-benefício que este recurso tem, porque sai do dado que já está no
  // item: nem catálogo para manter, nem rodízio fixo. Vem ANTES dos artistas
  // padrão porque é mais específica que eles.
  // **NUNCA PARA UMA COLEÇÃO DO CATÁLOGO**, e isto é MEDIDO: o nome do Hinário
  // 2022 vira `/hinario-adventista-2022/`, que não existe no site — 404 certo,
  // uma vez por hino, num acervo de 601. Onde o endereço já é deduzível de uma
  // tabela, adivinhá-lo de novo pelo nome do álbum só pode errar.
  if (segue() && coll && coll.name && !cifraDeduzivel(coll)) {
    const ua = AVCifra.urlDoAlbum(coll.name, nome);
    if (ua && ua !== url) {
      url = ua;
      desfecho = await cifraPedir(ua, o.mudo);
      if (desfecho.motivo === AVCifra.MOTIVO_SEM_CIFRA) viuSemCifra = true;
      tentativas.push('álbum ' + ua + ' → ' + desfecho.motivo);
      if (desfecho.ok) via = 'album';
    }
  }

  // 2ª TENTATIVA: os ARTISTAS PADRÃO. Os CDs oficiais e os do ano estão sob a
  // coleção "Ministério Jovem" do site, e ali a URL é DEDUZÍVEL do nome — uma
  // requisição, sem ranking de ninguém escolhendo por nós, que é a mesma razão
  // pela qual o catálogo vem antes da busca. Errar custa um 404 e a busca roda
  // em seguida como sempre.
  if (segue()) {
    for (const u of AVCifra.urlsPadrao(nome)) {
      url = u;
      desfecho = await cifraPedir(u, o.mudo);
      if (desfecho.motivo === AVCifra.MOTIVO_SEM_CIFRA) viuSemCifra = true;
      tentativas.push('padrão ' + u + ' → ' + desfecho.motivo);
      if (desfecho.ok) via = 'padrao';
      if (desfecho.ok || desfecho.motivo === AVCifra.MOTIVO_ILEGIVEL) break;
    }
  }

  // 3ª TENTATIVA: a busca do site. Ela cobre o "qualquer música" E o hino cujo
  // nome no acervo não bate com o do site — mas NÃO cobre o `ilegivel` (ver o
  // `segue()`).
  //
  // DOIS TENTOS DE CONSULTA, e o álbum entra só no segundo: ele não é o
  // artista do site, e uma palavra a mais numa busca de texto pode ENCOLHER o
  // resultado em vez de afiná-lo. Quando o primeiro tento não devolve nada com
  // parentesco, não há o que encolher — e aí o álbum é a única carta que sobra.
  //
  // ATÉ `CIFRA_CANDIDATOS` PÁGINAS, na ordem do parentesco. O ranking do site
  // não é o nosso: o primeiro colocado pode ser uma versão simplificada, uma
  // playback ou um homônimo. Cada tentativa entra no Registro, então três
  // `ilegivel` seguidos continuam dizendo "o site mudou de formato" — mais
  // alto, não mais baixo.
  // A BUSCA DO SITE é pulada no trabalho de MASSA (`semBusca`). MEDIDO na
  // acervo inteiro: toda linha `busca …` devolveu `0 resultado(s)` — os resultados são
  // desenhados por JavaScript, que o `cifraHtml` não executa. São duas
  // requisições por música que, varrendo o acervo, dobrariam o custo para não
  // achar nada. Na aba ela fica: lá é a última carta da música que o operador
  // tem na frente, e custa duas requisições UMA vez.
  if (segue() && !o.semBusca) {
    // As consultas, na ordem, SEM repetir: o álbum entra na segunda, e quando
    // não há álbum a segunda simplesmente não existe (a primeira versão
    // repetia a mesma consulta e gastava uma requisição a troco de nada).
    const album = (coll && coll.name) || '';
    const consultas = [nome];
    if (album) consultas.push(nome + ' ' + album);
    let candidatos = [];
    for (const q of consultas) {
      if (candidatos.length) continue;
      // O PARENTESCO É SEMPRE CONTRA O NOME DA MÚSICA, nunca contra a consulta:
      // com o álbum colado, nenhum resultado seria parente dela.
      const r = await cifraBuscarNoSite(q, nome, album, o.mudo);
      if (!r.url) continue;
      candidatos = r.ordenados;
      for (const l of (r.linhas || [])) tentativas.push(l);
    }
    for (const c of candidatos.slice(0, CIFRA_CANDIDATOS)) {
      url = c.url;
      desfecho = await cifraPedir(url, o.mudo);
      if (desfecho.motivo === AVCifra.MOTIVO_SEM_CIFRA) viuSemCifra = true;
      tentativas.push('tentada ' + url + ' → ' + desfecho.motivo);
      if (desfecho.ok) { via = 'busca'; break; }
    }
  }

  // O `sem-cifra` visto em qualquer degrau vence o `nao-tem` do último — e SÓ
  // ele: um `sem-rede` no fim é outra história, e anunciá-lo como "o site só
  // tem a letra" seria inventar um fato a partir de uma queda de conexão.
  const motivo = (!desfecho.ok && viuSemCifra && desfecho.motivo === AVCifra.MOTIVO_NAO_TEM)
    ? AVCifra.MOTIVO_SEM_CIFRA : desfecho.motivo;
  return {
    ok: !!desfecho.ok, pagina: desfecho.pagina || null, motivo,
    url, via, tentativas,
  };
}

// Garante que a cifra do item em cena está a caminho (ou já chegou). Idempotente
// de propósito: `renderLyricsView` pode chamá-la a cada pulso, e o estado
// `buscando` é o que impede uma segunda requisição para a mesma chave.
function cifraGarantir(item) {
  const chave = cifraChave(item);
  if (!chave || cifraCache.has(chave)) return cifraCache.get(chave) || null;

  const nome = cifraNomeDoItem(item);
  const coll = cifraColecaoDoItem(item);
  const entrada = {
    estado: 'buscando', url: '', pagina: null, motivo: '', semitons: 0,
    buscando: false,
  };
  cifraCache.set(chave, entrada);

  const seq = ++lvCifraSeq;
  // As radiografias são DESTA procura: sem limpar, a música seguinte herdaria
  // as páginas da anterior e o Registro descreveria um culto misturado.
  //
  // O QUE ISTO NÃO COBRE, dito: `cifraGuardarEstrutura` é chamado lá de dentro
  // da cadeia, sem a `seq` na mão. Com duas procuras SOBREPOSTAS (dois `send`
  // seguidos), as páginas que a primeira ainda tem em voo caem nesta lista já
  // zerada pela segunda. Fechá-lo é levar a `seq` até o `cifraPedir`.
  cifraEstruturas = [];
  cifraProcurar(nome, coll).then((r) => {
    // O QUE É DA `entrada` ENTRA SEMPRE; O QUE É SLOT COMPARTILHADO, SÓ DO MAIS
    // NOVO. Cada chave tem a entrada dela e ninguém a substitui no `cifraCache`
    // — descartar a resposta inteira de uma procura vencida deixaria AQUELA
    // música em `buscando` para sempre, porque `cifraGarantir` volta cedo pelo
    // `has` e nunca mais pergunta. Já `cifraUltimoDiag` é UM só para o app
    // todo: sem a guarda de sequência, a procura do louvor que SAIU de cena
    // chega depois e o Registro passa a listar os endereços de outra música —
    // o log que discorda do aparelho, lido a distância por quem não confere.
    //
    // A guarda anterior era `seq !== lvCifraSeq && cifraCache.get(chave) !==
    // entrada`: o segundo termo é constante (nada troca nem apaga entrada do
    // cache), então o `return` nunca rodava.
    entrada.estado = r.ok ? 'ok' : 'falha';
    entrada.pagina = r.pagina;
    entrada.motivo = r.motivo;
    entrada.url = r.url;
    if (seq === lvCifraSeq) cifraUltimoDiag = r.tentativas.join('\n');
    // O desfecho REDESENHA — sem isto a aba fica em "Procurando…" até o próximo
    // pulso do `refreshLyricsView`, que num áudio pausado nunca vem.
    if (lyricsPopupEl.classList.contains('open')) renderLyricsView();
  }).catch(() => {
    entrada.estado = 'falha';
    entrada.motivo = AVCifra.MOTIVO_SEM_REDE;
    if (lyricsPopupEl.classList.contains('open')) renderLyricsView();
  });

  return entrada;
}

// ===== A CIFRA DO HINÁRIO, GUARDADA NO APARELHO (v1.1.28) =====
//
// O Hinário 2022 é o único acervo em que o endereço da cifra é **deduzível e
// estável**: a coleção existe no site, o slug sai do nome do hino, e MEDIDO em
// uso não falhou uma vez. Isso o torna o único caso em que vale guardar — e o
// caso em que guardar resolve o problema de verdade: no sábado, com a rede da
// igreja oscilando, a folha abre sem rede nenhuma.
//
// ## QUEM BAIXA É O APARELHO, e isso é a decisão inteira
//
// Nada disto entra no bundle do OTA nem no repositório. O `.zip` do canal é
// público e servido em nome de quem publica; um acervo inteiro ali dentro é o
// app DISTRIBUINDO uma obra de terceiro, e não é isso que ele faz. Aqui cada
// aparelho busca o que vai usar, do mesmo jeito que já busca uma cifra por vez
// — o que muda é só QUANDO (uma vez, no download do hinário) e ONDE fica
// (IndexedDB do aparelho, não a memória da sessão).
//
// O ganho prático é o mesmo, e há três de quebra: a cifra fica sempre ATUAL
// (rebaixar é apagar e sincronizar), o repositório não incha, e não existe um
// segundo lugar de onde a verdade possa divergir.
//
// ## A forma é a do `syncLyrics`, e de propósito
//
// Mesma fila (`runLimited`), mesma proteção de segundo plano (`withBgWork`),
// mesma notificação de progresso, mesma gravação em LOTES, e a mesma regra que
// mais importa: **falha de rede não grava nada**. Marcar "não tem" por causa de
// um Wi-Fi que oscilou tiraria o hino da lista para sempre — e num acervo em
// que tudo existe, um buraco é sempre erro nosso.
const CIFRA_LOTE = 20;          // hinos por gravação
/**
 * ===== POR QUE NÃO HÁ MAIS UM TETO POR PASSADA (v1.2.21) =====
 *
 * Houve um: uma passada dominada por "sem cifra" não gravava nada, na suspeita
 * de que o site tivesse mudado de marcação. **Ele custou caro e não protegia
 * nada.** MEDIDO: o Hinário 2022 fechou uma passada com `309 tentadas · 0
 * achadas · 309 recusadas`, e como nada era gravado a varredura recomeçava do
 * zero a cada abertura, para sempre.
 *
 * E a suspeita era falsa. O operador conferiu à mão as páginas que a
 * radiografia nomeou: aquele hino tem só a letra no site mesmo, e a outra não
 * tem cifra nenhuma. **O veredito estava certo; o teto é que não sabia disso.**
 *
 * Ele também é estruturalmente errado: a passada só cobre o que FALTA, então a
 * proporção de ausências tende a 100% conforme o acervo completa — um teto por
 * proporção acaba disparando num acervo saudável, que é exatamente o que
 * aconteceu.
 *
 * O que protege contra a mudança de marcação são as duas defesas que ficam, e
 * elas não têm esse defeito:
 *
 *  1. o MARCADOR POSITIVO (`AVCifra.varianteSemCifra`): sem o `<title>`
 *     anunciando a variante, o desfecho volta a ser `ilegivel` e nada é gravado;
 *  2. o PRAZO de 30 dias (`CIFRA_REVISITA_MS`): nenhum veredito nosso vira
 *     buraco permanente, nem em massa.
 */

/**
 * O PRAZO DE UMA AUSÊNCIA — o que torna possível varrer o acervo INTEIRO.
 *
 * No hinário toda música existe no site, e "não achei" era sempre defeito
 * nosso: por isso a varredura nunca gravava um `nao-tem`, e a passada seguinte
 * tentava de novo. **No acervo de álbuns a conta se inverte.** MEDIDO na
 * acervo: cerca de dois terços das músicas não estão sob nenhum dos endereços
 * deduzíveis — e sem memória isso são milhares de requisições a um site de
 * terceiro EM TODA ABERTURA, para redescobrir o que já se sabia.
 *
 * A resposta não é gravar para sempre (um Wi-Fi ruim não pode custar um buraco
 * permanente) nem não gravar (o custo acima): é gravar **com data**. Trinta
 * dias depois a música volta para a fila e é reperguntada — tempo de sobra para
 * o site publicar uma cifra nova, e curto o bastante para um erro se corrigir
 * sozinho.
 *
 * O que NUNCA entra aqui continua sendo a falha de REDE (`sem-rede`, `recusou`)
 * e o `ilegivel`: a primeira não é resposta do site, e o segundo é defeito do
 * nosso parser — gravar qualquer um dos dois seria carimbar como "não tem" uma
 * pergunta que nem chegou a ser feita.
 */
const CIFRA_REVISITA_MS = 30 * 24 * 60 * 60 * 1000;

/**
 * Quantos nomes de hino "não achei" o Registro imprime por hinário.
 *
 * Vinte: são poucos por construção (MEDIDO, 41 nos dois hinários juntos) e cada
 * um é um conserto de uma linha na regra de slug. O teto existe para o dia em
 * que a regra quebrar de vez — aí o número da linha acima é que responde, e
 * duzentos nomes só enterrariam a linha do tempo.
 */
const CIFRA_FALTANDO_MAX = 20;



/**
 * A VERSÃO DO DIÁRIO, e ela existe por causa do PRAZO.
 *
 * Um diário recusado põe a coleção em prazo de uma semana. Um lote novo que
 * mude o que a passada faz — ou o que ela GUARDA — não pode ficar esperando o
 * prazo escrito pelo código antigo: a correção chegaria por OTA e não rodaria.
 * Diário de versão diferente é IGNORADO, e a passada recomeça com o código
 * novo, que é o que se quis publicar.
 */
const CIFRA_PASSADA_VERSAO = 2;

/** Quantas falhas o diário guarda como EXEMPLO. */
const CIFRA_EXEMPLOS_MAX = 12;

/** A chave do diário de uma passada de varredura. */
function cifraPassadaChave(collId) { return 'cifras-passada:' + collId; }

/** A entrada guardada ainda vale? Uma FOLHA vale sempre; uma ausência, 30 dias. */
function cifraNoDiscoVale(v, agora) {
  if (!v) return false;
  if (v.pagina) return true;
  return (agora - (v.em || 0)) < CIFRA_REVISITA_MS;
}
let cifraDiscoColl = '';        // de qual coleção é o `cifraDisco` carregado
let cifraDisco = null;          // { nome normalizado → { pagina, url, em } }
let cifraSyncRodando = false;

/** A chave de um hino dentro da coleção — a mesma normalização do cache. */
function cifraChaveNoDisco(nome) {
  return AVCifra.normalizar(AVCifra.semNumero(nome)).toLowerCase();
}

/**
 * Carrega (uma vez por coleção) o que está guardado.
 *
 * Por COLEÇÃO e sob demanda, não tudo na abertura: só os hinários têm cifra
 * guardada, e trazer os dois para a memória no `load()` custaria alguns MB num
 * processo que já divide espaço com dois WebViews e um vídeo.
 */
async function cifraDiscoDe(collId) {
  if (cifraDiscoColl === collId && cifraDisco) return cifraDisco;
  let v = null;
  try { v = await AVDB.getState('cifras:' + collId); } catch (_) { v = null; }
  cifraDiscoColl = collId;
  cifraDisco = (v && typeof v === 'object') ? v : {};
  return cifraDisco;
}

/**
 * MESCLA as cifras novas no que já está guardado — nunca SUBSTITUI.
 *
 * **A versão anterior gravava o mapa INTEIRO a partir de um slot de módulo**
 * (`AVDB.setState('cifras:'+id, cifraDisco)`), e isso é a receita exata do
 * ler-calcular-gravar que o `CLAUDE.md` proíbe para o `state`: duas transações
 * com um vão entre elas, e quem lê primeiro grava por último. Pior: o que ia
 * para o disco era um GLOBAL, cuja identidade mora noutra variável
 * (`cifraDiscoColl`) — bastava outra coleção ser carregada no meio para o
 * mapa do 1996 (ou um `{}`) ser escrito por cima do 2022.
 *
 * MEDIDO num aparelho: `275 de 601` virou `0 de 601`, e a cada abertura o app
 * recomeçava o download do zero. Uma substituição pode produzir zero a partir
 * de 275; **uma mescla não pode**, e é essa a diferença que faz a correção ser
 * estrutural em vez de um remendo no interleaving que mordeu deste vez.
 *
 * `fn` é SÍNCRONA (um `await` lá dentro deixaria a transação fechar sozinha e a
 * atomicidade sumiria em silêncio), e `novas` é ESVAZIADA depois do commit: o
 * que já está no disco não pode ser reenviado no lote seguinte.
 */
async function cifraDiscoMesclar(collId, novas) {
  const chaves = Object.keys(novas);
  if (!chaves.length) return;
  const junto = await AVDB.updateState('cifras:' + collId, (atual) =>
    Object.assign((atual && typeof atual === 'object') ? atual : {}, novas));
  for (const k of chaves) delete novas[k];
  // O slot de leitura acompanha, senão a aba continuaria vendo o mapa de antes
  // desta passada e iria à rede por uma cifra que acabou de ser guardada.
  if (cifraDiscoColl === collId) cifraDisco = junto;
}

/**
 * UMA FAIXA DA BIBLIOTECA COMO ALVO DO LEITOR (v1.2.14).
 *
 * O leitor sempre falou a língua do `currentItem` — o registro de uma mídia
 * baixada. Uma faixa da Biblioteca é outra coisa (a entrada do catálogo), e o
 * que falta entre as duas é pouco: o nome, a procedência e a letra.
 *
 * **A letra vem do que JÁ EXISTE no aparelho** (`songLyricStanzas`: o acervo de
 * texto ou os slides do arquivo baixado), nunca de uma requisição nova — abrir
 * uma folha no ensaio não pode depender da rede da igreja. E os TEMPOS não são
 * reconstruídos de propósito: sem cena não há posição a destacar
 * (`lvCurrentIndex` devolve -1), então um `time` aqui seria um número que
 * ninguém lê e que sugeriria uma sincronia que não existe.
 *
 * `kind: 'audio'` é o que faz o `cifraCabe` aceitar a faixa mesmo sem letra
 * guardada: é conteúdo musical, e a cifra é justamente o que se foi buscar.
 */
async function lvItemDaBiblioteca(coll, s) {
  const estrofes = await songLyricStanzas(coll, s).catch(() => null);
  const lyrics = (estrofes || []).map((e) => ({
    time: 0, cover: false, text: (e.l || []).join('\n'), auxText: e.a || null,
    imageOpfsPath: null, imagePosition: null,
  }));
  return {
    id: 'lib:' + coll.id + ':' + s.id_music,
    kind: 'audio',
    name: s.name,
    hymnName: s.name,
    hymnTrack: collNumbersSongs(coll) ? s.track : null,
    // É por ELE que o `cifraColecaoDoItem` reencontra a coleção — e com ela o
    // catálogo, o álbum-como-artista e o arquivo de cifras no aparelho.
    hymnAlbum: coll.name || '',
    lyrics,
  };
}

/**
 * O ENDEREÇO É DEDUZÍVEL DO CATÁLOGO? Só os dois hinários são.
 *
 * Continua existindo depois de o arquivo abrir para o acervo inteiro, porque
 * responde outra pergunta: **quantas requisições custa uma música**. No hinário
 * é UMA (o catálogo acerta), num álbum é a cadeia inteira. Quem decide se
 * GUARDA é o `cifraGuardavel`; este decide o que esperar da varredura.
 */
function cifraDeduzivel(coll) {
  return !!(coll && AVCifra.CATALOGO[coll.id]);
}

/**
 * GUARDA CIFRA PARA ESTA COLEÇÃO? — hoje, todo acervo de MÚSICA (v1.2.14).
 *
 * Nasceu valendo só para os dois hinários, porque ali o endereço é deduzível e
 * "baixar tudo" era uma operação previsível em vez de 600 apostas. O acervo de
 * álbuns provou, numa varredura medida, que a cadeia deduzível (álbum como
 * artista + artistas padrão) acerta uma boa parte dele — e o que ela não acerta
 * agora é RESPOSTA GUARDADA, não uma pergunta refeita a cada abertura.
 *
 * O corte é o mesmo do `cifraCabe`: conteúdo musical. Uma SÉRIE é testemunho em
 * vídeo, e procurar cifra dela é requisição garantidamente perdida.
 */
function cifraGuardavel(coll) {
  return !!coll && temLetra(coll);
}

/**
 * As cifras de TODO acervo de música que o operador tem no aparelho.
 *
 * O irmão do `syncLyrics`, e chamado do mesmo lugar: sem isto, o recurso só
 * existia para quem baixasse o acervo DEPOIS da versão que o trouxe — quem já o
 * tinha ficava em `0 de N` para sempre, e o Registro dizia isso sem que nada na
 * tela explicasse o quê fazer.
 *
 * **A coleção precisa ter algo BAIXADO** (`countDownloaded`): um álbum que o
 * operador nunca trouxe para o aparelho não é acervo dele, e varrer o catálogo
 * inteiro seria pagar rede por música que ninguém vai tocar.
 */
// ===== A ROTINA DE ACERVO CEDE A VEZ AO QUE ESTÁ NO AR (v1.4.19) =====
//
// `syncLyrics` e `syncCifrasAcervo` saem da abertura SEM `await`, portanto
// correm juntas: `NET_CONCURRENCY` é 6, então são até **12 requisições
// concorrentes** a dois hosts de terceiros, sobre o acervo inteiro (MEDIDO:
// 309 + 145 hinos numa passada). O único freio era `networkType() ===
// 'cellular'` — nada consultava a cena.
//
// **Por que isto é estabilidade e não desempenho.** O uso normal é abrir o app
// minutos antes do culto e tocar o primeiro item. Nesse instante os fragmentos
// do MSE disputam a Wi-Fi da igreja com as 12 requisições — e a MEDIDA DE BANDA
// que escolhe o degrau do louvor inteiro é feita justamente durante a disputa
// (`talvezTrocarDegrau` roda antes do primeiro quadro, uma vez, para sempre).
// A varredura do acervo podia rebaixar a resolução do louvor, e numa rede
// apertada empurrar o fragmento seguinte para a fome.
//
// **CEDE A VEZ E SAI, não cede a vez e espera.** Esperar seguraria o
// `withBgRotina` — e com ele o serviço em primeiro plano, cuja cota de
// `dataSync` é de 6 h em 24 h — parado por um culto inteiro, sem baixar nada.
// Sair é seguro porque as duas rotinas são RETOMÁVEIS POR CONSTRUÇÃO (o que já
// foi gravado não é pedido de novo) e porque quem as rearma já existe:
// `autoRefreshCollections` roda na abertura **e em todo `visibilitychange`**, e
// o operador troca de app dezenas de vezes durante um culto.
//
// A pergunta é `midiaNoAr` e não `currentId`: aquele sobrevive ao Parar de
// propósito (é o que o ▶ repete), e uma varredura adiada para sempre por uma
// cena que já saiu seria o mesmo defeito com o sinal trocado.
function rotinaDeAcervoPodeCorrer() { return !midiaNoAr; }

async function syncCifrasAcervo() {
  for (const c of allCollections().filter((c) => cifraGuardavel(c) && countDownloaded(c.id) > 0)) {
    if (!rotinaDeAcervoPodeCorrer()) return;
    await syncCifrasColecao(c).catch(() => {});
  }
}

async function syncCifrasColecao(coll) {
  if (!window.__NATIVE__ || !cifraGuardavel(coll) || cifraSyncRodando) return;
  // Ver `rotinaDeAcervoPodeCorrer`: a varredura é adiável, o louvor não.
  if (!rotinaDeAcervoPodeCorrer()) return;
  // A MESMA REGRA DO `syncLyrics`: são centenas de requisições a um site que
  // não é nosso, e o plano de dados do operador não é o lugar delas.
  if (networkType() === 'cellular') return;

  const agora = Date.now();
  // NÃO HÁ MAIS PRAZO DE PASSADA (v1.2.21): ele existia para o caso em que o
  // teto recusava tudo, e o teto saiu — quem impede a revarredura agora é o
  // que sempre deveria: cada música tem uma resposta GRAVADA, com data.
  const disco = await cifraDiscoDe(coll.id);
  const faltam = collSongs(coll.id)
    .map((s) => ({ nome: s.name, chave: cifraChaveNoDisco(s.name) }))
    .filter((h) => h.chave && !cifraNoDiscoVale(disco[h.chave], agora));
  if (!faltam.length) return;

  cifraSyncRodando = true;
  const notifId = bgTaskStart('Cifras do ' + coll.name, faltam.length);
  let done = 0;
  let desdeGravacao = 0;
  // O QUE AINDA NÃO FOI PARA O DISCO, e só isso. A gravação mescla este punhado
  // no que já está guardado — nunca manda o acervo inteiro de volta.
  const pendentes = {};
  // OS `sem-cifra` FICAM À PARTE do resto só para o diário poder contá-los
  // separadamente: eles são resposta do site ("a página está aqui, a cifra
  // não"), não uma falha nossa, e é essa distinção que o Registro mostra.
  const semCifra = {};
  // CONTADOS À PARTE porque `cifraDiscoMesclar` ESVAZIA `pendentes` depois do
  // commit: recontar o objeto no fim daria zero sempre, e o diário sairia
  // dizendo que a passada não achou nada.
  let okDaPassada = 0;
  let naoTemDaPassada = 0;
  // OS EXEMPLOS DO QUE NÃO SAIU COM FOLHA — número, nome, veredito e o ENDEREÇO
  // tentado. É o que responde a pergunta que nenhum contador responde: *"quais
  // hinos, e o que a página deles tem?"*. Sem o endereço a lista não serve para
  // nada — é abrindo a página no navegador que se descobre se o erro é o nosso
  // endereço ou a nossa leitura.
  //
  // Guardados no DIÁRIO e não no disco de cifras, porque o diário é escrito
  // MESMO QUANDO O TETO RECUSA a passada: é justamente o caso em que nada mais
  // sobrevive, e era o caso em que não havia como investigar.
  const exemplos = [];
  try {
    await withBgRotina(async () => {
      try {
        await runLimited(faltam, NET_CONCURRENCY, async (h) => {
          // O gêmeo do `syncLyrics`, e pelo mesmo motivo — ver
          // `rotinaDeAcervoPodeCorrer`.
          if (!rotinaDeAcervoPodeCorrer()) return;
          bgItemStart(notifId, h.nome);
          try {
            // A CADEIA INTEIRA, e não só o catálogo (v1.2.14). É ela que faz o
            // arquivo valer para um álbum, onde o endereço não é deduzível de
            // uma tabela: quem acerta ali é o álbum-como-artista e os artistas
            // padrão. Num hinário nada muda — o catálogo é o primeiro degrau e
            // encerra na primeira requisição.
            //
            // `semBusca` porque a busca do site é MEDIDA em zero: toda linha
            // `busca …` medida devolveu `0 resultado(s)`. Ela custa duas
            // requisições por música e, em massa, dobraria a varredura do acervo
            // para não achar nada. Na aba ela FICA — lá é a última carta para a
            // música que está na frente do operador.
            // AS OPÇÕES VÃO NA TERCEIRA POSIÇÃO — `cifraProcurar(nome, coll,
            // opts)`. Um argumento a mais aqui não erra alto: `opts` recebia a
            // string do parâmetro que a v1.3.3 removeu, e `mudo`/`semDisco`/
            // `semBusca` saíam `undefined`. A varredura voltava a bater na
            // busca do site (MEDIDA em zero resultado, dois terços do acervo, a
            // cada abertura) e a empurrar as radiografias do operador para fora
            // do `CIFRA_ESTRUTURAS_MAX` — tudo sem uma linha no console.
            const d = await cifraProcurar(h.nome, coll, {
              mudo: true, semDisco: true, semBusca: true,
            });
            if (d.ok && d.pagina) {
              pendentes[h.chave] = { pagina: d.pagina, url: d.url, em: Date.now() };
              okDaPassada++;
            } else if (d.motivo === AVCifra.MOTIVO_SEM_CIFRA) {
              // O SITE TEM A PÁGINA E NÃO A CIFRA — é resposta, não falha.
              // A VARIANTE é guardada, não um booleano: é ela que o Registro
              // mostra, e é por ela que se descobre, um dia, que o site passou
              // a servir uma terceira.
              semCifra[h.chave] = { semCifra: d.variante || 'letra', url: d.url, em: Date.now() };
            } else if (d.motivo === AVCifra.MOTIVO_NAO_TEM) {
              // NENHUM ENDEREÇO DEDUZÍVEL TINHA A PÁGINA. Também é resposta do
              // site — e, ao contrário do `sem-cifra`, ela pode mudar quando
              // alguém publicar a cifra: daí o prazo, e não o silêncio eterno.
              pendentes[h.chave] = { naoTem: true, em: Date.now() };
              naoTemDaPassada++;
            }
            // `sem-rede`, `recusou` e `ilegivel` NÃO gravam nada: os dois
            // primeiros não são resposta do site, e o terceiro é defeito do
            // nosso parser. A passada seguinte tenta de novo.
            // O EXEMPLO, para o que NÃO saiu com folha. `sem-rede` fica de fora:
            // ali não houve resposta do site, e um endereço sem resposta não é
            // pista de nada — mandaria o operador abrir uma página que o app
            // nem chegou a ver.
            if (!d.ok && d.motivo !== AVCifra.MOTIVO_SEM_REDE
                && exemplos.length < CIFRA_EXEMPLOS_MAX) {
              exemplos.push({ nome: h.nome, motivo: d.motivo, url: d.url || '' });
            }
          } catch (_) { /* rede: a próxima passada tenta de novo */ }
          finally { bgItemEnd(notifId, h.nome); }
          done++;
          bgTaskStep(notifId, done);
          if (++desdeGravacao >= CIFRA_LOTE) {
            desdeGravacao = 0;
            await cifraDiscoMesclar(coll.id, pendentes).catch(() => {});
          }
        });
      } finally { bgTaskEnd(notifId); }
    });
  } finally {
    await cifraDiscoMesclar(coll.id, pendentes).catch(() => {});
    // OS `sem-cifra` VÃO PARA O DISCO como qualquer outra resposta — ver o
    // bloco que explica por que não há mais teto por passada.
    const quantos = Object.keys(semCifra).length;
    if (quantos) await cifraDiscoMesclar(coll.id, semCifra).catch(() => {});
    // O DIÁRIO DA PASSADA — e ele é o que transforma um laço mudo num achado.
    // Sem ele, "309 por varrer" reaparecia a cada abertura sem que nada na tela
    // dissesse que aquelas 309 tinham sido julgadas E RECUSADAS. Guardado com
    // `setState` (objeto inteiro, uma escritora só) e lido pelo Registro.
    await AVDB.setState(cifraPassadaChave(coll.id), {
      v: CIFRA_PASSADA_VERSAO,
      em: Date.now(), tentadas: faltam.length,
      ok: okDaPassada, naoTem: naoTemDaPassada,
      semCifra: quantos,
      exemplos,
    }).catch(() => {});
    cifraSyncRodando = false;
  }
}

// ===== A CIFRA É SÓ AUTOMÁTICA (v1.3.3) =====
//
// Houve uma busca à mão aqui (v1.1.24 a v1.3.2): a aba desenhava a lista de
// resultados do site, abria qualquer um em prévia e FIXAVA o endereço escolhido
// para aquela música, que passava a ser a tentativa 0 nas aberturas seguintes.
// Ela saiu inteira a pedido do operador — lista, prévia, campo de consulta,
// atalhos e a escolha guardada (`cifraEscolhas`).
//
// O QUE ISSO CUSTA, para quem for reintroduzi-la saber o que está reintroduzindo:
// a regra ADIVINHA a partir de um nome, e quando ela erra (uma versão
// simplificada, um homônimo) não há mais correção dentro do app — resta o link
// "Ver no Cifra Club". A cadeia automática é o recurso inteiro agora:
// disco → catálogo → álbum-como-artista → artistas padrão → busca do site.
//
// UM RESTO FICA NO APARELHO, e é de propósito não mexer nele: a chave
// `cifraEscolhas` do `state` continua gravada em quem já usou o recurso. Não é
// lida por ninguém e não custa nada; apagá-la exigiria uma migração para
// devolver bytes que não fazem falta, e ela é o que uma volta atrás reaproveita.

/**
 * As RADIOGRAFIAS desta procura, uma por endereço — para o Registro.
 *
 * **UMA SÓ NÃO BASTA, e este é o terceiro lugar do recurso onde isso mordeu**
 * (v1.2.6). Uma procura tenta vários endereços; a última escrita apagava as
 * anteriores, e o que sobrava era sempre a página menos interessante: o
 * `buscador` respondeu `HTTP 202` — a resposta anti-robô — e a estrutura dela
 * foi sobrescrita pela busca interna que rodou em seguida. O Registro dizia
 * "202" numa linha e mostrava OUTRA página embaixo.
 *
 * Um Registro não tem pressão de tamanho (ele existe para ser COPIADO, não
 * para caber numa tela), então o certo é guardar todas e imprimir todas. Uma
 * por RÓTULO: repetir o mesmo endereço não empilha.
 */
const CIFRA_ESTRUTURAS_MAX = 6;
let cifraEstruturas = [];      // [{ rotulo, texto }]



/**
 * Uma busca no site, já lida: `{ crus, ordenados, url }`.
 *
 * `crus` é TUDO que estruturalmente parece música — é o que o seletor mostra,
 * porque o ponto dele é justamente deixar ver o que a regra RECUSOU.
 * `ordenados` é o que a regra aceitaria, na ordem dela.
 *
 * **TRÊS PARÂMETROS PORQUE SÃO TRÊS PAPÉIS**, e juntá-los foi um defeito real:
 * a primeira versão passava um `extra` que ia ao mesmo tempo para a consulta e
 * para o parentesco, e o seletor — que manda a consulta DIGITADA — acabava sem
 * álbum em lugar nenhum, nem na busca nem no desempate.
 *
 *  - `consulta` é o que vai no `?q=`, já montado por quem chama;
 *  - `alvo` é contra o que o PARENTESCO compara (o nome da música, ou o que o
 *    operador digitou — nunca a consulta com o álbum colado, senão nenhum
 *    resultado seria parente dela);
 *  - `artista` é o DESEMPATE, e só isso.
 *
 * `mudo` cala a radiografia, pela mesma razão do `cifraPedir`: a varredura do
 * acervo roda centenas de procuras seguidas, e sem a guarda a última delas
 * apagaria a estrutura da página que o operador está diagnosticando.
 */
async function cifraBuscarNoSite(consulta, alvo, artista, mudo) {
  // UM MOTOR SÓ — o buscador externo saiu na v1.2.8.
  //
  // Ele entrou na v1.2.2 porque a busca interna nunca teve como funcionar
  // (MEDIDO: `cifraclub.com.br/?q=` responde 425 kB cujos únicos links de duas
  // partes são o índice A–Z — os resultados são desenhados por JavaScript, que
  // o `cifraHtml` não executa), e saiu porque também não funcionou: o endpoint
  // HTML do DuckDuckGo responde `HTTP 202` — a recusa anti-robô —, e uma recusa
  // parseada como página vazia é uma requisição por procura para não devolver
  // nada. Quem passou a achar as músicas foram os endereços DEDUZÍVEIS
  // (catálogo, álbum-como-artista, artistas padrão), e é neles que o esforço
  // vale: uma requisição, sem ranking de ninguém escolhendo por nós.
  //
  // A busca interna FICA, e é a última carta: ela não custa mais do que a
  // requisição que já custava, e no dia em que o site voltar a desenhar no
  // servidor volta a funcionar sozinha — com o Registro acumulando a resposta
  // dela enquanto isso não acontece.
  const motores = [
    { rotulo: 'busca', url: AVCifra.urlDeBusca(consulta), ler: AVCifra.lerBusca },
  ];
  // CADA MOTOR VIRA UMA LINHA (v1.2.5). A primeira versão devolvia só o ÚLTIMO,
  // e o Registro de um aparelho saiu com duas linhas `busca` e NENHUMA do
  // `buscador` — que tinha sido tentado. Não dá para diagnosticar um motor que
  // o diário não menciona, e este é o segundo lugar deste recurso em que um
  // diagnóstico se calou justamente sobre o que se queria medir.
  let ultima = { crus: [], ordenados: [], url: '', linhas: [] };
  const linhas = [];
  for (const m of motores) {
    if (!m.url) continue;
    const rb = await AVNative.cifraHtml(m.url);
    const ok = rb.status >= 200 && rb.status <= 299;
    if (!mudo) cifraGuardarEstrutura(m.rotulo + ' ' + m.url, ok ? rb.html : '');
    const crus = ok ? m.ler(rb.html) : [];
    const ordenados = AVCifra.ordenarBusca(crus, alvo, artista);
    // O STATUS entra na linha: `0` é "não houve resposta" e `403` é "o motor
    // recusou o agente" — dois consertos diferentes, e a linha do shell só
    // guarda a ÚLTIMA requisição de todas, que quase nunca é esta.
    linhas.push(m.rotulo + ' ' + m.url + ' → HTTP ' + (rb.status | 0) + ', '
      + crus.length + ' resultado(s), ' + ordenados.length + ' com parentesco');
    ultima = { crus, ordenados, url: m.url, rotulo: m.rotulo, linhas };
    if (crus.length) return ultima;
  }
  ultima.linhas = linhas;
  return ultima;
}

/**
 * A RADIOGRAFIA da última página, em texto, para o Registro.
 *
 * Guardada aqui e não no `cifra.js` porque o módulo é puro e devolve OBJETO —
 * quem monta a frase é o `controle.js`, que é a mesma regra do Kotlin devolver
 * JSON. Uma linha por fato, e nenhuma delas leva conteúdo da página.
 */
function cifraGuardarEstrutura(rotulo, html) {
  const guardar = (texto) => {
    const i = cifraEstruturas.findIndex((e) => e.rotulo === rotulo);
    if (i >= 0) cifraEstruturas[i] = { rotulo, texto };
    else cifraEstruturas.push({ rotulo, texto });
    if (cifraEstruturas.length > CIFRA_ESTRUTURAS_MAX) cifraEstruturas.shift();
  };
  if (!html) { guardar(rotulo + ' → sem corpo'); return; }
  const r = AVCifra.radiografia(html);
  const l = [rotulo + ' → ' + r.bytes + ' caractere(s)'];
  if (r.titulo) l.push('  <title> ' + JSON.stringify(r.titulo));
  if (r.h1 || r.h2) l.push('  <h1> ' + JSON.stringify(r.h1) + ' · <h2> ' + JSON.stringify(r.h2));
  l.push('  ' + r.pres + ' <pre>, o maior com ' + r.maiorPre + ' caractere(s) e '
    + r.bNoMaiorPre + ' <b>' + (r.tom ? ' · tom "' + r.tom + '"' : ' · tom não achado'));
  l.push('  ' + r.links + ' link(s) de 2 segmentos, ' + r.linksDeMusica + ' com forma de música'
    + (r.amostraEhCrua ? ' — a amostra abaixo é do que HAVIA, já que nada passou' : ''));
  for (const a of r.amostra) l.push('    ' + a.caminho + '  ' + JSON.stringify(a.texto));
  guardar(l.join('\n'));
}




// O estado atual da cifra do item em cena, SEM disparar busca — para a
// assinatura (`lvSignature`), que roda a cada pulso e não pode ter efeito.
function cifraEstado(item) {
  const chave = cifraChave(item);
  return (chave && cifraCache.get(chave)) || null;
}

// Transpõe a folha em cena. O passo é guardado NA ENTRADA do cache, e não numa
// variável solta: voltar a um hino já transposto nesta sessão devolve o tom em
// que o operador o deixou, e trocar de hino não arrasta o passo do anterior.
function cifraTranspor(passo) {
  const e = cifraEstado(lvItem());
  if (!e || e.estado !== 'ok') return;
  // Doze semitons é a volta inteira: passar disso é o mesmo tom com outro nome.
  e.semitons = ((e.semitons + passo) % 12 + 12) % 12;
  renderLyricsView();
}

/**
 * QUANTOS CARACTERES CABEM numa linha da folha, ou 0 se não dá para medir.
 *
 * O `AVCifra.quebrarPares` é PURO e não olha o DOM — a medida é injetada, e
 * quem a tira é aqui. Ela não pode ser calculada: a folha é monoespaçada, mas a
 * fonte que o Android escolhe para `ui-monospace` varia de aparelho, e o corpo
 * segue o A+/A− do operador. O único jeito honesto é **renderizar e medir**.
 *
 * Mede uma amostra longa e divide, em vez de medir UM caractere: com um só, o
 * arredondamento subpixel vira erro de várias colunas na linha inteira.
 *
 * Devolve 0 quando o elemento ainda não tem largura (a folha abrindo, o popup
 * fechado). Zero faz `quebrarPares` devolver a folha intacta — sem medida
 * confiável, não quebrar é melhor que quebrar no lugar errado.
 */
const CIFRA_AMOSTRA = 40;
function cifraColunas(folha) {
  const largura = folha.clientWidth;
  if (!largura) return 0;
  const regua = document.createElement('span');
  regua.className = 'lv-cifra-linha';
  regua.style.position = 'absolute';
  regua.style.visibility = 'hidden';
  regua.style.whiteSpace = 'pre';
  regua.textContent = '0'.repeat(CIFRA_AMOSTRA);
  folha.appendChild(regua);
  const porCaractere = regua.getBoundingClientRect().width / CIFRA_AMOSTRA;
  folha.removeChild(regua);
  if (!(porCaractere > 0)) return 0;
  return Math.max(8, Math.floor(largura / porCaractere));
}

// ===== A CIFRA EM TELA CHEIA, DEITADA (v1.6.0) =====
//
// Pedido do operador: *"gostaria que criasse um sistema para visualização das
// cifras em tela cheia, no modo paisagem. deixe visível em uma coluna vertical
// na direita, os botões de controle de tom, automático, tamanho da fonte e
// etc... e é claro, ao abrir esse modo em tela cheia, pode já deixar
// automaticamente a fonte já um pouco maior, já que uma visualização com a
// fonte maior é o objetivo desse método em tela cheia"*.
//
// O ELEMENTO É O `#lyricsPopup` INTEIRO, e a razão é o que NÃO acontece: nada
// é reparentado. Mover o corpo para um contêiner novo zeraria o `scrollTop`,
// invalidaria a posição fracionária da rolagem (`cifraPos`/`cifraEscrito`) e
// mataria as referências de `cifraRolarBtnEl`/`cifraVelBtnEl`. Só o layout
// muda — quem o vira é o CSS, sob `#lyricsPopup:fullscreen`.
//
// A TRAVA DE PAISAGEM NÃO CUSTA UMA LINHA DE KOTLIN: quem deita o aparelho e
// esconde as barras é o `onShowCustomView` do `MainActivity`, que não testa
// tipo de elemento nenhum — a preview, que já usa este caminho todo culto, é um
// `<div>` comum.
//
// ## A FONTE MAIOR é uma SEGUNDA ESCADA, não um deslocamento
//
// `--lv-fonte` é global (mora no `<html>`) e as DUAS casas do A+/A− o leem —
// engordá-lo ali levaria junto a zona de letra do Modo Fácil, e obrigaria a
// desfazer na saída. Aqui ele é ESCOPADO no `#lyricsPopup` (custom property
// herda, e `.lv-cifra-folha` resolve `calc(var(--lv-fonte) * .74)` por ele):
// sair é `removeProperty`, e **o tamanho normal volta porque nunca foi
// embora**. Um offset somado ao índice global teria de ser subtraído na saída,
// e não sobreviveria a um ajuste feito DENTRO da tela cheia nem ao teto da
// escada.
//
// O PREÇO, DITO: mudar o corpo no retrato não arrasta o da tela cheia. Está
// certo — são duas perguntas ("ler o celular na mão" × "ler de longe com o
// instrumento na mão") —, e está escrito para ninguém "consertar".
//
// (`--lv-estrofe-gap` é `calc(var(--lv-fonte) * .86)` declarado no `:root`, e a
// substituição acontece em quem DECLARA: os descendentes herdam o valor já
// resolvido. É inócuo para a cifra, que espaça em `em`; no dia em que a tela
// cheia valer para a aba de LETRA, ele tem de ser redeclarado junto.)
let cifraCheia = false;
// -1 é "ainda não semeado", e não um degrau: é ele que faz a PRIMEIRA entrada
// de sempre saltar dois degraus a partir do corpo do retrato. Daí em diante o
// valor é do operador, e é persistido em `cifraFonteCheia`.
let cifraCheiaIdx = -1;
// DOIS DEGRAUS, e o número é MEDIDO em colunas, não em gosto. No retrato de
// 430px a folha tem ~375px úteis a `1.4rem × .74` ≈ 16,6px monoespaçados, o que
// dá ~37 colunas; na paisagem de 800px sobram ~734 depois da coluna, e a
// `2rem × .74` ≈ 23,7px dá ~52. Isto é: +43% de corpo E +40% de linha. Um salto
// maior inverteria o negócio — uma fonte maior que faz a folha quebrar MAIS é
// uma regressão, e é isso que o oráculo cobra.
const CIFRA_CHEIA_SALTO = 2;

/**
 * Adota o corpo guardado da tela cheia. Por FUNÇÃO (hoisted) e não por
 * atribuição direta, pelo mesmo motivo do `cifraAdotarVelocidade`: o estado
 * mora aqui e o `load()` que hidrata roda muito antes na leitura.
 *
 * Valor fora da escada (ou ausente) volta ao sentinela: a semente do primeiro
 * uso é o que responde, e a escada pode encolher numa versão futura.
 */
function cifraAdotarFonteCheia(v) {
  // COM A TELA CHEIA NO AR, QUEM MANDA É O CORPO QUE ESTÁ NA TELA. A semente da
  // primeira entrada é DERIVADA (do corpo do retrato) e não é gravada — só o
  // A+/A− grava —, então um `load()` que chegasse aqui com a folha deitada
  // leria `undefined` e devolveria o índice ao sentinela **enquanto o corpo
  // grande continua escrito no `#lyricsPopup`**. E `load()` chega: todo
  // download que começa ou termina passa por ele (`libBusy`/`soltar`), tanto
  // quanto o fim de uma sincronização de pasta. O toque seguinte no A+
  // resolveria `-1 + 1` e SALTARIA PARA O MENOR corpo da escada — 1rem, o
  // oposto do modo cujo objetivo declarado é ler de longe —, gravando-o; e o
  // A− já nasceria desabilitado pela regra de `aplicarTamanhoDaLetra`.
  if (cifraCheia) return;
  const i = LV_TAMANHOS.indexOf(v);
  cifraCheiaIdx = i >= 0 ? i : -1;
}

// Escreve o corpo ESCOPADO. Semeia na primeira vez a partir do corpo do
// retrato: `Math.min` clampa, então entrar já no topo da escada é no-op — e
// tem de ser no-op silencioso, com o A+ nascendo desabilitado pela regra de
// `aplicarTamanhoDaLetra`.
function cifraAplicarFonteCheia() {
  if (cifraCheiaIdx < 0) {
    const base = LV_TAMANHOS.indexOf(lvTamanho);
    cifraCheiaIdx = Math.min(
      LV_TAMANHOS.length - 1,
      (base < 0 ? LV_TAMANHOS.indexOf(LV_PADRAO) : base) + CIFRA_CHEIA_SALTO,
    );
  }
  lyricsPopupEl.style.setProperty('--lv-fonte', LV_TAMANHOS[cifraCheiaIdx] + 'rem');
}

// O A+/A− DENTRO da tela cheia mexe na escada DELA, e persiste nela. Não chama
// `lvScroll`: a cifra não tem `.lv-row.current` (`lvCurrentIndex` devolve -1
// para ela), então aquelas duas linhas seriam no-op.
async function passoTamanhoDaCheia(passo) {
  const alvo = Math.min(LV_TAMANHOS.length - 1, Math.max(0, cifraCheiaIdx + passo));
  if (alvo === cifraCheiaIdx) return;
  // A LEITURA É CAPTURADA ANTES DO CORPO MUDAR — a regra escrita em
  // `cifraRemedir`, no lugar em que ela mais é exercitada. De 1,4 para 1,7rem
  // são ~21% de folha a mais, e quem estava na metade reapareceria perto dos
  // 41% se a fração fosse lida depois.
  const fracao = cifraFracaoDeLeitura();
  cifraCheiaIdx = alvo;
  cifraAplicarFonteCheia();
  aplicarTamanhoDaLetra();   // repinta o desabilitado, agora pela escada certa
  cifraRemedir(fracao);      // o corpo mudou: a folha quebra por CARACTERE
  try { await AVDB.setState('cifraFonteCheia', LV_TAMANHOS[cifraCheiaIdx]); }
  catch (_) { /* sem banco: vale a sessão */ }
}

/** Os dois desenhos do ⛶, trocados por `innerHTML` — nunca por `<use>`. */
const CIFRA_CHEIA_SVG = {
  entrar: '<path d="M4 9V5.5A1.5 1.5 0 0 1 5.5 4H9"/><path d="M15 4h3.5A1.5 1.5 0 0 1 20 5.5V9"/>'
    + '<path d="M20 15v3.5a1.5 1.5 0 0 1-1.5 1.5H15"/><path d="M9 20H5.5A1.5 1.5 0 0 1 4 18.5V15"/>',
  sair: '<path d="M9 4v3.5A1.5 1.5 0 0 1 7.5 9H4"/><path d="M20 9h-3.5A1.5 1.5 0 0 1 15 7.5V4"/>'
    + '<path d="M15 20v-3.5a1.5 1.5 0 0 1 1.5-1.5H20"/><path d="M4 15h3.5A1.5 1.5 0 0 1 9 16.5V20"/>',
};

// O botão é ESTÁTICO, mas o desenho dele é estado — e o estado mora fora do
// DOM, como o do `cifraPintarRolar`.
function cifraPintarCheia() {
  if (!cifraCheiaBtnEl) return;
  const rotulo = cifraCheia ? 'Sair da tela cheia' : 'Ler em tela cheia (deitado)';
  cifraCheiaBtnEl.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" '
    + 'stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    + (cifraCheia ? CIFRA_CHEIA_SVG.sair : CIFRA_CHEIA_SVG.entrar) + '</svg>';
  cifraCheiaBtnEl.title = rotulo;
  cifraCheiaBtnEl.setAttribute('aria-label', rotulo);
}

/**
 * Sai da tela cheia da cifra — e SÓ dela.
 *
 * A guarda pelo elemento é o que separa esta saída da da PREVIEW, que sem TV É
 * a projeção: um `document.exitFullscreen()` cru com dois donos possíveis
 * derrubaria o telão para fechar uma folha de acordes.
 */
function cifraCheiaSair() {
  if (document.fullscreenElement !== lyricsPopupEl) return;
  try { document.exitFullscreen(); } catch (_) { /* já saiu */ }
}

// UMA TELA CHEIA POR VEZ: o `onShowCustomView` do shell recusa a segunda
// (`if (customView != null)`), e o Chromium não sabe disso — o estado do
// navegador divergiria do da Activity, com a janela deitada e sem o elemento
// que a pediu. A guarda mora aqui, onde ela é barata.
async function cifraCheiaAlternar() {
  if (cifraCheia || document.fullscreenElement === lyricsPopupEl) { cifraCheiaSair(); return; }
  if (document.fullscreenElement) return;
  if (lvActiveSource() !== 'cifra') return;
  try {
    if (lyricsPopupEl.requestFullscreen) await lyricsPopupEl.requestFullscreen();
    else if (lyricsPopupEl.webkitRequestFullscreen) lyricsPopupEl.webkitRequestFullscreen();
  } catch (_) { /* o navegador recusou: a folha continua no retrato */ }
}

if (cifraCheiaBtnEl) cifraCheiaBtnEl.addEventListener('click', cifraCheiaAlternar);
cifraPintarCheia();   // ele nasce com desenho; quem o revela é `renderLyricsView`

// QUEM MANDA É O EVENTO, nunca o toque. F11, Esc e o `exitFullscreen` do voltar
// do Android chegam todos por aqui, e é aqui que a escada de fonte entra e sai
// — pendurar isso no clique deixaria as três saídas com a fonte grande de pé.
document.addEventListener('fullscreenchange', () => {
  const agora = document.fullscreenElement === lyricsPopupEl;
  if (agora === cifraCheia) return;
  // A POSIÇÃO DE LEITURA É CAPTURADA AQUI, antes de o corpo mudar: trocar a
  // fonte muda o comprimento da folha na hora, e a remedição só roda no quadro
  // seguinte — lida lá, a fração já descreveria o estado novo.
  const fracao = cifraFracaoDeLeitura();
  cifraCheia = agora;
  if (agora) cifraAplicarFonteCheia();
  else lyricsPopupEl.style.removeProperty('--lv-fonte');
  aplicarTamanhoDaLetra();
  cifraPintarCheia();
  // A LARGURA E O CORPO MUDAM EM INSTANTES DIFERENTES, e este cobre o primeiro:
  // o elemento já está na top layer (a caixa já é a tela inteira), o corpo
  // acabou de ser escrito — e o aparelho ainda NÃO girou. Quem cobre a rotação
  // é o `resize` de sempre, que chega depois: não há promise para esperá-la (o
  // `screen.orientation.lock` é decorativo num WebView), quem gira é a
  // Activity.
  requestAnimationFrame(() => cifraRemedir(fracao));
});

/**
 * A fração do CONTEÚDO que está no topo do corpo — a régua com que a posição de
 * leitura atravessa uma remedição. Por que do CONTEÚDO e não do percurso está
 * dito em `cifraRemedir`, que é quem a consome.
 *
 * Ela existe porque TRÊS chamadores precisam capturá-la **antes de mexer na
 * fonte** (a entrada e a saída da tela cheia, e as duas escadas do A+/A−): o
 * corpo novo muda o comprimento da folha na hora, e a remedição só roda depois
 * — lida lá, a fração já descreveria o estado novo, e o que sai é uma leitura
 * que recua na proporção do crescimento do corpo.
 */
function cifraFracaoDeLeitura() {
  const el = lyricsViewBodyEl;
  return el.scrollHeight > 0 ? el.scrollTop / el.scrollHeight : 0;
}

// Redesenha a folha quando a MEDIDA pode ter mudado — e só então.
//
// A assinatura de `lvSignature` fala do CONTEÚDO (música, estado, transposição)
// e não da largura, porque medir a 4 Hz para comparar seria caro e inútil. Os
// três casos em que a largura muda de verdade são eventos, e cada um chama
// aqui: a folha ABRINDO (antes de `.open` ela não tem largura), o A+/A− e o
// gerar do aparelho.
function cifraRemedir(fracaoDada) {
  if (!lyricsPopupEl.classList.contains('open')) return;
  if (lvActiveSource() !== 'cifra') return;
  // (A guarda de TECLADO saiu na v1.3.3, com o campo que ela protegia: esta aba
  // não tem mais `<input>` nenhum. Ela existia porque o teclado do sistema é um
  // `resize`: o redesenho refazia a aba, o campo com foco deixava de existir, e
  // a perda do foco fechava o teclado — um teclado que piscava e sumia. Se um
  // campo voltar a esta aba, a guarda tem de voltar com ele.)
  const el = lyricsViewBodyEl;
  const folha = el.querySelector('.lv-cifra-folha');
  // ===== A GUARDA É POR COLUNAS, NUNCA POR LARGURA (v1.6.0) =====
  //
  // A pergunta que ela faz é *"a folha que está aí foi quebrada para a largura
  // que ela tem AGORA?"* — `cifraColunasAtual` guarda o que a folha em cena de
  // fato usou (escrito em `cifraDesenharFolha`), e aqui se mede de novo.
  //
  // Ela paga por três coisas de uma vez. A rotação dispara `resize` em RAJADA,
  // e cada um custava a folha inteira reconstruída. O `ResizeObserver` do corpo
  // (abaixo) REALIMENTA — reconstruir muda o `scrollHeight`, a barra de rolagem
  // aparece ou some, o `clientWidth` muda, o observador dispara de novo —, e o
  // ciclo morre no segundo passo. E ela continua deixando passar o A+/A−, onde
  // a largura é a MESMA e o avanço por caractere não é: por LARGURA, aquele
  // caminho seria apagado em silêncio.
  //
  // Sem folha (estados `buscando`/`erro`) não há o que medir, e cai no
  // comportamento de sempre: redesenhar.
  if (folha && cifraColunas(folha) === cifraColunasAtual) return;
  // ===== E A POSIÇÃO DE LEITURA SOBREVIVE À REMEDIÇÃO =====
  //
  // `renderLyricsView` esvazia e reconstrói o corpo: o `scrollTop` volta a zero
  // e, no quadro seguinte, `cifraRolarQuadro` lê `scrollTop !== cifraEscrito`,
  // conclui — com toda a razão, é a linha que atende o "vale tanto para volta
  // como para avanços" — que outro mexeu na folha, e adota o topo. A folha
  // voltava ao começo no meio da música.
  //
  // Em FRAÇÃO do percurso, e não em pixel: a remedição muda a QUEBRA, logo o
  // número de linhas, logo o comprimento da folha — um `scrollTop` guardado não
  // significa nada do outro lado. E a volta é por `cifraAplicarPos`, que é quem
  // atualiza `cifraEscrito`: escrever cru faria o quadro seguinte concluir
  // "outro mexeu" outra vez.
  // A FRAÇÃO É DO CONTEÚDO (`scrollTop / scrollHeight`), não do PERCURSO
  // (`/ (scrollHeight - clientHeight)`). MEDIDO: a segunda muda sozinha quando
  // só a ALTURA da caixa muda — e é o que a rotação faz, sem tocar no texto —,
  // e o que saía era a folha andando 19% do arquivo ao deitar. A do conteúdo
  // responde "que pedaço do texto está no topo?", que é a pergunta.
  //
  // E ELA PODE VIR DE FORA: quem troca a fonte (a entrada e a saída da tela
  // cheia) muda o comprimento da folha ANTES de a remedição rodar, então a
  // leitura feita aqui já descreveria o estado novo. O chamador captura antes
  // de mexer e passa adiante. `typeof` e não `||`: zero é fração legítima, e
  // um `Event` de `resize` chegando por engano no lugar dela seria pior.
  const fracao = typeof fracaoDada === 'number'
    ? fracaoDada
    : (el.scrollHeight > 0 ? el.scrollTop / el.scrollHeight : 0);
  renderLyricsView();
  const rolavelDepois = el.scrollHeight - el.clientHeight;
  if (fracao > 0 && rolavelDepois > 0) {
    cifraPos = Math.min(rolavelDepois, fracao * el.scrollHeight);
    cifraAplicarPos(el);
  }
}

// A LARGURA DO CORPO É O QUE `cifraColunas` MEDE — perguntar à JANELA é inferir.
// O `resize`/`orientationchange` continuam (eles cobrem a rotação, que chega
// depois da tela cheia); este cobre tudo o mais que mexe na caixa sem mexer na
// janela. A realimentação que ele poderia criar morre na guarda por colunas.
if (typeof ResizeObserver === 'function') {
  new ResizeObserver(() => cifraRemedir()).observe(lyricsViewBodyEl);
}


// ===== A ROLAGEM AUTOMÁTICA DA FOLHA (v1.1.20 → v1.5.6) =====
//
// Quem lê uma cifra está com as duas mãos no instrumento — e é justamente aí
// que a folha precisa andar sozinha.
//
// ## O modo AUTO é um RITMO tirado da música, não a POSIÇÃO dela
//
// Uma velocidade fixa em px/s não tem como estar certa: a mesma folha serve a um
// hino de 2 min e a um de 6, e o que decide o ritmo da leitura é a MÚSICA. Daí o
// `auto` — mas o que ele toma da música é só a DURAÇÃO TOTAL, e o que ele
// integra é o relógio de parede a partir de onde a folha está agora.
//
//   ritmo = percurso rolável ÷ (t1 − t0)          `AVCifra.ritmoDaRolagem`
//
// **Isto REVOGA o desenho da v1.1.20**, em que a posição da folha era uma FUNÇÃO
// da posição da música. Pedido do operador: *"ajuste o sistema de rolagem
// automática de cifra para que ele não siga o tempo da música atual em exibição,
// pois se a música não está tocando, ele não anda. Ou se eu quiser tocar de um
// ponto específico em diante, ele fica voltando para onde a mídia estaria… Eu
// quero que siga o progresso levando em conta: o tempo total da música e a
// posição atual do scroll"*.
//
// **As três vantagens daquele desenho eram os três defeitos do relato**, vistas
// do outro lado — e é por isso que a correção é uma troca de premissa e não um
// remendo:
//
// | a v1.1.20 dizia | o operador viu |
// |---|---|
// | pausar a música PARA a folha | *"se a música não está tocando, ele não anda"* |
// | um seek LEVA a folha ao ponto | *"ele fica voltando para onde a mídia estaria"* |
// | um quadro perdido não acumula erro | (só isto sobrevive — e o teto de delta cobre) |
//
// O `cifraDesvio` da v1.1.20 era o remendo sobre a premissa errada: um
// deslocamento somado ao alvo para dar ao dedo um lugar na briga com a música.
// Ele SAIU, e com ele o alvo teórico e a perseguição suave — não há mais briga.
// **A folha era da MÚSICA; ela passou a ser de quem lê.**
//
//   ┌ topo                                                    fim da folha ┐
//   │╲                                                                     │
//   │  ╲___ ritmo constante, integrado do ponto em que a folha ESTÁ ___    │
//   │                                                              ╲______ │
//   └ o dedo pode mover a origem a qualquer momento, para frente ou para trás ┘
//
// **O que sobrevive da janela é o FECHO**, e sobrevive por construção: percorrer
// o rolável em `t1 − t0` segundos põe a última linha na tela no instante `t1`,
// que é o que o fecho sempre quis dizer — o fim da cifra lido bem antes do fim
// da música, que é a parte que mais se erra. **A ABERTURA saiu**, e saiu porque
// perdeu o referente: ela era *"a música acabou de começar"*, e não há mais
// começo nenhum — a origem é onde o scroll está.
//
// **A FOLHA NUNCA MEXE NO TEMPO DA MÍDIA**, e o operador pediu isso por extenso:
// *"esse scroll das cifras não altera o tempo, seja parado ou tocando, da mídia
// em exibição"*. Sempre foi verdade e nunca teve oráculo; hoje tem
// (`cifra-rolagem.test.mjs`), porque uma ausência não tem sintoma — o dia em que
// alguém ligar os dois eixos "para sincronizar", a folha passa a comandar a
// projeção no meio do culto.
//
// ## O modo LIVRE: px/s constante, para quando não há duração
//
// Ensaio sem tocar a gravação, um item sem linha do tempo (imagem, mensagem),
// um vídeo cuja duração ainda não chegou. Ali `auto` não tem de onde tirar o
// ritmo e cai no fixo — o botão continua dizendo `Auto`, que é a ESCOLHA, e o
// `title` diz o que está de fato acontecendo. Os degraus numéricos são a escolha
// explícita do mesmo ritmo fixo. **Os dois modos passaram a ser UM LAÇO**: a
// única diferença é de onde sai o px/s.
//
// ## Por que `requestAnimationFrame`, e por que a posição é FRACIONÁRIA
//
// No ritmo de leitura são ~0,37 px por quadro. Escrevendo `scrollTop` inteiro, a
// folha anda 1 px a cada três quadros e fica parada nos outros dois — e é esse
// liga-desliga que se vê como TREMOR. Não é jitter de relógio: é quantização.
// Por isso a posição é NOSSA ([cifraPos], `Number`) e é escrita com a fração;
// quem suaviza é o compositor do navegador, que rola em subpixel. Reler o
// `scrollTop` para acumular seria perder a fração a cada quadro, que é o mesmo
// defeito por outro caminho.
//
// O delta tem TETO ([CIFRA_DT_MAX]) porque a página estrangulada em segundo
// plano voltaria dando um salto. **Com o `auto` integrando, isso passou a valer
// para os DOIS modos** — no desenho antigo o `auto` era imune por ser função do
// tempo da música, e essa imunidade foi embora junto com o resto dela.
//
// ## O dedo NÃO briga com a rolagem, e não a desliga
//
// Voltar uma linha para reler é a coisa mais comum aqui, e um sistema que se
// desligasse a cada toque obrigaria a religá-lo o tempo todo. Como o avanço é
// RELATIVO nos dois modos, um arrasto só muda a origem — para trás ou para
// frente, *"vale tanto para volta como para avanços"* — e a rolagem continua
// dali. É a mesma linha que já cobria o modo livre: `cifraPos` reassume o
// `scrollTop` sempre que alguém que não fomos nós o escreveu.
const CIFRA_VELOCIDADES = ['auto', 0.5, 0.75, 1, 1.5, 2, 3];
const CIFRA_VEL_PADRAO = 0; // 'auto'
/** Pixels por segundo no 1× do modo livre. Ritmo de leitura, não de lista. */
const CIFRA_PX_POR_S = 22;
/** Teto do delta de um quadro: acima disso houve pausa, e pausa não é avanço. */
const CIFRA_DT_MAX = 250;

let cifraVelIdx = CIFRA_VEL_PADRAO;
let cifraRolando = false;
let cifraSegurando = false;
let cifraRaf = 0;
let cifraQuadroT = 0;
let cifraRolarBtnEl = null;
let cifraVelBtnEl = null;
/** De QUAL música é a rolagem em curso — ver a guarda no `lvBuildCifra`. */
let cifraRolandoChave = '';
/**
 * O RELÓGIO da espera inicial, em `t` de `requestAnimationFrame` — ver
 * "A ESPERA INICIAL", perto de `cifraRolarQuadro`. `-1` é o sentinel "ainda
 * não armado neste ciclo"; `cifraRolarAlternar` o zera para -1 de propósito,
 * e é o PRIMEIRO quadro que o arma de verdade, porque só ali o `pxPorS` já
 * está calculado.
 */
let cifraEsperaFimMs = -1;
/**
 * `true` enquanto a folha está PARADA de propósito, esperando o operador ler
 * antes de rolar. Não é o mesmo que "não anda" — a folha também não anda
 * quando `cifraSegurando` é verdadeiro, e ali não há indicador nenhum, porque
 * quem está com o dedo nela já sabe que ela não é a que está travada.
 *
 * Vive FORA do DOM, no padrão de `linhasCarregando`: `cifraPintarRolar` REFAZ
 * o botão inteiro a cada chamada (troca de velocidade, redesenho da folha), e
 * uma marca escrita só no nó sumiria no primeiro repintar durante a espera.
 */
let cifraEsperando = false;
/**
 * A POSIÇÃO DA FOLHA EM FRAÇÃO DE PIXEL — a nossa, não a do elemento.
 *
 * O `scrollTop` de volta vem arredondado, e um acumulador que se relesse a cada
 * quadro perderia a fração toda vez: no ritmo de leitura são ~0,37 px por
 * quadro, então a folha andava 1 px a cada três quadros e ficava parada nos
 * outros dois. É esse liga-desliga que o operador vê como TREMOR — não é
 * jitter de relógio, é quantização.
 *
 * Guardando a posição aqui em `Number` e escrevendo o valor fracionário, quem
 * suaviza é o compositor do navegador, que rola em subpixel.
 */
// Quantas colunas a folha EM CENA foi quebrada para caber — a régua da guarda
// de `cifraRemedir`. -1 é "não há folha medida".
let cifraColunasAtual = -1;
let cifraPos = 0;
/** O que ESCREVEMOS por último — é a régua para saber se outro mexeu. */
let cifraEscrito = -1;

/**
 * O RITMO do modo `auto`, em pixels por segundo — ou 0 quando não há duração de
 * onde tirá-lo (e aí quem responde é o ritmo fixo do modo livre).
 *
 * **A POSIÇÃO DA MÍDIA NÃO ENTRA AQUI** (v1.5.6), e é essa ausência que é o
 * recurso: a folha anda com a música parada, e um seek não a puxa de volta. O
 * que se toma da música é a DURAÇÃO TOTAL, e mais nada.
 *
 * Ela sai da BARRA DE PROGRESSO, não de um cálculo paralelo: é a única fonte que
 * cobre todos os tipos de mídia (o `<video>` do stage não sabe nada de um vídeo
 * do YouTube), e é a mesma escolha que o `pushNowPlaying` já faz.
 */
function cifraRitmoDoRelogio(rolavel) {
  // A REGRA é do módulo puro (o fecho, os pisos e tetos da janela): daqui sai só
  // o que existe no DOM — a duração da barra e o percurso da folha.
  return AVCifra.ritmoDaRolagem(rolavel, cifraDuracaoNoAr());
}

/**
 * A duração da mídia no ar, ou 0 quando não há linha do tempo.
 *
 * Uma função, e não um estado guardado: o `title` do botão a consulta no
 * instante em que é pintado, e a folha é desenhada muito antes de o laço de
 * rolagem existir. Um valor em cache responderia pelo culto passado.
 *
 * ===== "NO AR" É `midiaNoAr`, NUNCA A BARRA SOZINHA (v1.2.3) =====
 *
 * Relato do operador: *"o modo automático não está se movendo quando usado
 * apenas a letra da música"*.
 *
 * A barra de progresso responde "este ITEM tem linha do tempo?", que não é a
 * pergunta daqui — e as duas divergem no caso mais comum de quem só lê a letra:
 * `renderNowPlaying` termina em `seekEl.disabled = !isTimed`, com `isTimed`
 * saindo do `kind` do item ATUAL. Um louvor que já foi selecionado continua
 * sendo `currentItem` depois do Parar, depois do fim da faixa e durante uma
 * letra avulsa — então a barra seguia habilitada, com o `max` da faixa, sobre
 * um telão vazio.
 *
 * E o desfecho disso é justamente "não se move", não um erro: com duração o
 * modo `auto` vira uma FUNÇÃO de `authoritativeTime()`, que ali vale 0. A folha
 * é ancorada na abertura da janela de rolagem e fica parada para sempre — o
 * modo LIVRE, que deveria ter assumido, nunca é alcançado.
 *
 * `midiaNoAr` é a pergunta certa, e é a mesma que o reenvio de cena e o Parar
 * por camada já fazem. Ela continua VERDADEIRA com a mídia PAUSADA, e desde a
 * v1.5.6 é isso que faz a folha andar com a música parada: o que se lê daqui é a
 * DURAÇÃO, não a posição. (Até a v1.5.5 pausar a música parava a folha, e o
 * operador chamou isso de defeito: *"se a música não está tocando, ele não
 * anda"*.)
 */
function cifraDuracaoNoAr() {
  // E COM UM ALVO DA BIBLIOTECA NÃO HÁ RELÓGIO NENHUM (v1.2.14). A folha aberta
  // no ensaio não é a música em cena: seguir o `authoritativeTime()` faria ela
  // andar no compasso de OUTRO louvor — e, ao contrário de uma folha parada,
  // isso parece funcionar. Sem relógio o modo `auto` cai no LIVRE, que é o que
  // um ensaio sem gravação de fato quer.
  if (!lvNaCena()) return 0;
  if (!midiaNoAr || seekEl.disabled) return 0;
  return parseFloat(seekEl.max) || 0;
}

/** O rótulo do degrau atual. Vírgula decimal — é o que o operador lê. */
function cifraVelRotulo() {
  const v = CIFRA_VELOCIDADES[cifraVelIdx];
  if (v === 'auto') return 'Auto';
  return (v % 1 === 0 ? String(v) : v.toFixed(2).replace(/0$/, '')).replace('.', ',') + '×';
}

/**
 * O que o botão de velocidade PROMETE, dito por extenso.
 *
 * `Auto` sem relógio não é erro — é o caso normal de um ensaio sem tocar a
 * gravação —, mas também não pode ficar mudo: o rótulo mostra a ESCOLHA e esta
 * frase mostra o que está de fato acontecendo. Sem ela, "por que a folha não
 * acompanha a música?" não tem resposta em lugar nenhum.
 */
function cifraVelTitulo() {
  if (CIFRA_VELOCIDADES[cifraVelIdx] !== 'auto') return 'Velocidade da rolagem';
  return cifraDuracaoNoAr() > 0
    ? 'Rolagem no ritmo da música (toque para escolher uma velocidade fixa)'
    : 'Sem duração da música: rolagem em ritmo fixo (toque para escolher a velocidade)';
}

// Os dois botões vivem no DOM, que `renderLyricsView` refaz inteiro — então o
// ESTADO mora aqui fora e quem acabou de nascer vem perguntar como se pintar.
function cifraPintarRolar() {
  if (cifraVelBtnEl) {
    cifraVelBtnEl.textContent = cifraVelRotulo();
    const t = cifraVelTitulo();
    cifraVelBtnEl.title = t;
    cifraVelBtnEl.setAttribute('aria-label', t);
  }
  if (!cifraRolarBtnEl) return;
  cifraRolarBtnEl.classList.toggle('ativa', cifraRolando);
  cifraRolarBtnEl.innerHTML = '';
  // Pelo `ICON`, nunca por um caractere literal solto: é a tabela que o
  // `tools/glifos.test.mjs` varre, e um glifo fora dela não desenha NADA sem
  // erro nenhum — o botão existiria, tocável e invisível.
  const ico = msym(cifraRolando ? ICON.pause : ICON.play);
  ico.setAttribute('aria-hidden', 'true');
  cifraRolarBtnEl.appendChild(ico);
  // O ANEL DA ESPERA INICIAL (v1.5.20): a MESMA linguagem visual do download em
  // curso (`aroDeEspera`), só que sem seta — não há bytes chegando, há um
  // relógio correndo. Ele diz "em andamento", não "travado"; o botão sozinho
  // pausado e imóvel é indistinguível de um botão quebrado.
  if (cifraRolando && cifraEsperando) cifraRolarBtnEl.appendChild(aroDeEspera());
  const rotulo = !cifraRolando ? 'Rolar sozinho'
    : (cifraEsperando ? 'Lendo a introdução antes de rolar…' : 'Parar a rolagem');
  cifraRolarBtnEl.title = rotulo;
  cifraRolarBtnEl.setAttribute('aria-label', rotulo);
}

function cifraRolarParar() {
  cifraRolando = false;
  cifraEsperaFimMs = -1;
  cifraEsperando = false;
  if (cifraRaf) cancelAnimationFrame(cifraRaf);
  cifraRaf = 0;
  cifraEscrito = -1;
  cifraPintarRolar();
}

function cifraRolarQuadro(t) {
  cifraRaf = 0;
  if (!cifraRolando) return;
  // As mesmas condições do `cifraRemedir`: fora daqui não há folha para rolar.
  if (!lyricsPopupEl.classList.contains('open') || lvActiveSource() !== 'cifra') {
    cifraRolarParar();
    return;
  }
  const dt = cifraQuadroT ? Math.min(CIFRA_DT_MAX, t - cifraQuadroT) : 0;
  cifraQuadroT = t;

  const el = lyricsViewBodyEl;
  const rolavel = el.scrollHeight - el.clientHeight;

  // OUTRO MEXEU NA FOLHA? Um arrasto, um `scrollIntoView`, o teclado do sistema
  // — qualquer coisa que não tenha sido a linha de escrita lá embaixo. O
  // `scrollTop` de volta vem arredondado, então a régua tem folga de um pixel:
  // sem ela, a nossa própria escrita fracionária se leria como intervenção
  // alheia a cada quadro, e a posição nunca sairia do lugar.
  //
  // **É ESTA LINHA que atende o "vale tanto para volta como para avanços"**: o
  // avanço é relativo nos dois modos, então adotar o que o dedo deixou é adotar
  // a origem nova — para trás ou para frente, sem nada a compensar.
  if (cifraEscrito < 0 || Math.abs(el.scrollTop - cifraEscrito) > 1) cifraPos = el.scrollTop;

  if (cifraSegurando || dt <= 0) {
    cifraEscrito = -1; // a folha é de quem está com o dedo nela
    cifraRaf = requestAnimationFrame(cifraRolarQuadro);
    return;
  }

  // ---- UM LAÇO SÓ: o que muda entre os modos é DE ONDE SAI O px/s ----
  // `auto` tira o ritmo da duração da música (e cai no fixo quando não há
  // duração); os degraus numéricos multiplicam o fixo. Eram dois ramos — um por
  // POSIÇÃO e outro por velocidade —, e virar um só é a mudança da v1.5.6 dita
  // como código.
  const ehAuto = CIFRA_VELOCIDADES[cifraVelIdx] === 'auto';
  const ritmo = ehAuto ? cifraRitmoDoRelogio(rolavel) : 0;
  const pxPorS = ritmo > 0
    ? ritmo
    : CIFRA_PX_POR_S * (ehAuto ? 1 : CIFRA_VELOCIDADES[cifraVelIdx]);

  // ===== A ESPERA INICIAL: ler antes de rolar (v1.5.20) =====
  //
  // Pedido do operador: *"o sistema de rolagem automática de cifra não está
  // sendo parado no início para permitir ler e executar a introdução da
  // música durante um instrumental… o objetivo não é ter a linha a ser lida
  // no topo, mas no centro. Desse modo, o sistema deve esperar o usuário 'ler
  // até chegar no ponto médio' antes de se preocupar em mover
  // automaticamente."*
  //
  // A REGRA é do módulo puro (`AVCifra.esperaInicialDaRolagem`, com o piso e o
  // teto). Daqui sai só o que existe no DOM — a altura da caixa e o `pxPorS`
  // JÁ CALCULADO acima, o MESMO que o movimento vai usar: a espera não é um
  // número à parte, é o tempo de ler o pedaço que ainda não rolou, NO
  // COMPASSO em que a folha vai de fato seguir.
  //
  // **Armada UMA VEZ por ciclo de rolagem** (`cifraEsperaFimMs < 0`): o
  // sentinel nasce -1 em `cifraRolarAlternar`, porque ali o `pxPorS` ainda não
  // existe — só o PRIMEIRO quadro sabe o ritmo de verdade. Rearmar a cada
  // quadro empurraria o fim da espera para sempre um pouco mais à frente.
  //
  // **`rolavel <= 0` pula a espera inteira** — não há o que ler antes de uma
  // rolagem que não vai acontecer, e é o mesmo caso em que o laço já parava
  // no quadro seguinte (ver o `if` de fim de rolagem, abaixo).
  if (rolavel > 0) {
    if (cifraEsperaFimMs < 0) {
      cifraEsperaFimMs = t + AVCifra.esperaInicialDaRolagem(el.clientHeight, pxPorS);
    }
    if (t < cifraEsperaFimMs) {
      cifraRaf = requestAnimationFrame(cifraRolarQuadro);
      return;
    }
  }
  // O indicador SOME no exato instante em que o movimento de fato começa — daí
  // em diante a própria folha andando já diz "está funcionando", e o anel
  // deixaria de ser verdade (ele promete "ainda não", não "sempre").
  if (cifraEsperando) { cifraEsperando = false; cifraPintarRolar(); }

  const antes = el.scrollTop;
  cifraPos = Math.min(rolavel, cifraPos + (pxPorS * dt) / 1000);
  cifraAplicarPos(el);
  // Chegou ao fim? Continuar é pedir ao aparelho um quadro por segundo para não
  // fazer coisa nenhuma. A pergunta é pelo TETO (`rolavel`) e não por "o
  // scrollTop não andou": com fração de pixel, um quadro sem avanço visível é
  // normal, e mediria "está lento", não "acabou".
  //
  // **Vale para os DOIS modos desde a v1.5.6.** No desenho antigo o `auto`
  // seguia até o fim da música e "descansava" no fim da folha — o que ele
  // descansava esperando era o relógio, e não há mais relógio a esperar: com a
  // folha no fim, a rolagem cumpriu o que prometeu.
  if (cifraPos >= rolavel && antes >= rolavel - 1) { cifraRolarParar(); return; }
  cifraRaf = requestAnimationFrame(cifraRolarQuadro);
}

/**
 * Escreve a posição no elemento, com a FRAÇÃO. O navegador rola em subpixel; o
 * que ele devolve na leitura é arredondado, e por isso guardamos o que
 * escrevemos ANTES de reler — é essa cópia que distingue a nossa escrita de um
 * arrasto do operador no quadro seguinte.
 */
function cifraAplicarPos(el) {
  el.scrollTop = cifraPos;
  cifraEscrito = el.scrollTop;
}

function cifraRolarAlternar() {
  if (cifraRolando) { cifraRolarParar(); return; }
  cifraRolando = true;
  // A CHAVE É DA FOLHA, NÃO DA CENA — e a distinção nasceu com o `lvAlvo`
  // (v1.2.14). Enquanto ela era `cifraChave(currentItem)`, ler a folha de uma
  // música da Biblioteca gravava a chave da música PROJETADA, e a guarda
  // "música nova é folha nova" do `lvBuildCifra` — que compara com
  // `cifraChave(lvItem())` — parava a rolagem no primeiro redesenho da folha.
  // Transpor meio tom, tocar em A+/A− ou girar o aparelho bastavam: os três
  // redesenham. Sem erro nenhum, e justamente no ENSAIO, que é o caso para o
  // qual a folha sem telão existe. As duas pontas têm de perguntar a mesma
  // coisa; quem responde "de que música é esta folha?" é `lvItem()`.
  cifraRolandoChave = cifraChave(lvItem());
  cifraQuadroT = 0;
  // A ORIGEM É ONDE A FOLHA ESTÁ (v1.5.6): ligar a rolagem é pedir para andar
  // DAQUI, e não para saltar ao ponto em que a música estaria — que era o que a
  // v1.1.20 fazia, e é metade do relato que a trocou.
  cifraPos = lyricsViewBodyEl.scrollTop;
  cifraEscrito = -1;
  // A ESPERA INICIAL nasce ARMADA-PARA-ARMAR: o sentinel `-1` diz "ainda não
  // sei quanto tempo esperar" (só o primeiro quadro conhece o `pxPorS`), e
  // `cifraEsperando` liga o indicador JÁ NESTE TOQUE — não faz sentido o botão
  // ficar mudo por um quadro só porque o cálculo ainda não rodou.
  cifraEsperaFimMs = -1;
  cifraEsperando = true;
  // Rolar sozinho e ACOMPANHAR a estrofe no ar são dois donos do mesmo scroll.
  // Quem tocou no botão escolheu este.
  lvFollow = false;
  if (!cifraRaf) cifraRaf = requestAnimationFrame(cifraRolarQuadro);
  cifraPintarRolar();
}

/**
 * Adota o degrau guardado. Por FUNÇÃO (hoisted) e não por atribuição direta: o
 * estado da rolagem mora no fim do arquivo, e o `load()` que hidrata roda muito
 * antes na leitura — um `let` alcançado de cima é uma zona morta esperando a
 * ordem de chamada mudar.
 *
 * Degrau desconhecido cai no padrão: a escada pode encolher numa versão futura,
 * e o que estava salvo continua sendo lido sem erro.
 */
function cifraAdotarVelocidade(v) {
  const i = CIFRA_VELOCIDADES.indexOf(v);
  cifraVelIdx = i >= 0 ? i : CIFRA_VEL_PADRAO;
}

async function cifraVelPasso() {
  cifraVelIdx = (cifraVelIdx + 1) % CIFRA_VELOCIDADES.length;
  // Nada a zerar: os dois modos integram a partir da posição atual, e o degrau
  // só troca o px/s do próximo quadro. (A v1.1.20 zerava aqui o `cifraDesvio`,
  // que era medido contra um alvo absoluto — ele saiu com o alvo.)
  cifraPintarRolar();
  try { await AVDB.setState('cifraVelocidade', CIFRA_VELOCIDADES[cifraVelIdx]); }
  catch (_) { /* sem banco: vale a sessão */ }
}

// A LARGURA MUDA SEM NINGUÉM TOCAR EM NADA: girar o aparelho, o teclado do
// sistema subindo, a janela mudando de tamanho. A medida da folha é em
// CARACTERES, então qualquer um deles deixa a quebra valendo para a largura
// anterior. `cifraRemedir` já se recusa a trabalhar fora da aba de cifra.
// Em ARROW, e não a referência nua: `cifraRemedir` passou a receber a fração de
// leitura no primeiro argumento (v1.6.0), e um `Event` de `resize` — ou o
// carimbo de tempo que o `requestAnimationFrame` entrega — chegaria no lugar
// dela. O `typeof` de lá é a segunda guarda; esta é a primeira.
window.addEventListener('resize', () => cifraRemedir());
window.addEventListener('orientationchange', () => { requestAnimationFrame(() => cifraRemedir()); });


/** O aro de espera com uma frase — três chamadores, um desenho. */
function cifraEspera(frase) {
  const box = document.createElement('div');
  box.className = 'lv-cifra-estado';
  const anel = document.createElement('span');
  anel.className = 'dl-ring';
  const txt = document.createElement('span');
  txt.textContent = frase;
  box.append(anel, txt);
  return box;
}

/**
 * A FOLHA em si — as linhas medidas, quebradas e transpostas.
 *
 * Continua separada do `lvBuildCifra` (a PRÉVIA, que era o segundo desenho da
 * mesma coisa, saiu na v1.3.3) porque quem chama é quem decide o QUE desenhar,
 * e ela decide só COMO: a medida de colunas, a quebra do par acorde/letra e a
 * transposição são um assunto só, e é o assunto que este arquivo mais quebra
 * quando se mexe nele com pressa.
 */
function cifraDesenharFolha(el, pagina, semitons) {
  const folha = document.createElement('div');
  folha.className = 'lv-cifra-folha';
  el.appendChild(folha);
  // O QUE ESTA FOLHA USOU, guardado para a guarda de `cifraRemedir` (v1.6.0):
  // ela pergunta se a folha em cena foi quebrada para a largura que ela TEM
  // agora, e a única resposta honesta é a medida que a construiu. Guardar em
  // vez disso o último valor medido faria a folha aberta com largura ZERO (o
  // `renderLyricsView` de dentro do `openLyricsPopup`, antes do `.open`)
  // coincidir com um número velho e nunca ser requebrada.
  cifraColunasAtual = cifraColunas(folha);
  const linhas = AVCifra.quebrarPares(pagina.linhas, cifraColunasAtual);
  linhas.forEach((linha) => {
    const div = document.createElement('div');
    div.className = 'lv-cifra-linha lv-cifra-' + linha.tipo;
    div.textContent = linha.tipo === 'acordes'
      ? AVCifra.transporLinha(linha.texto, semitons) : linha.texto;
    folha.appendChild(div);
  });
}

// Desenha a folha dentro de `el`, e os controles dentro de `barra` — que fica
// FORA do que rola, para o pausar continuar alcançável com a folha andando.
function lvBuildCifra(el, barra) {
  const item = lvItem();
  // OS BOTÕES MORREM COM O RENDER ANTERIOR. Sem soltá-los aqui, um render que
  // caia em "procurando" ou em erro deixa `cifraPintarRolar` escrevendo num nó
  // já desligado da árvore — sem erro, e sem efeito nenhum na tela.
  cifraRolarBtnEl = null;
  cifraVelBtnEl = null;
  const entrada = cifraGarantir(item);
  const nome = cifraNomeDoItem(item);

  if (!entrada || entrada.estado === 'buscando') {
    el.appendChild(cifraEspera('Procurando a cifra…'));
    return;
  }

  if (entrada.estado !== 'ok') {
    // CADA MOTIVO PEDE UMA AÇÃO DIFERENTE, e por isso são frases diferentes.
    // Um "não foi possível carregar" genérico é o que faz o operador tentar de
    // novo quando o certo era desistir, e desistir quando o certo era tentar.
    const frases = {
      [AVCifra.MOTIVO_SEM_REDE]: 'Sem resposta da internet. A cifra é lida na hora — sem rede, não há como buscá-la.',
      [AVCifra.MOTIVO_NAO_TEM]: 'Não encontrei a cifra de “' + nome + '”.',
      [AVCifra.MOTIVO_RECUSOU]: 'O site respondeu, mas recusou a página. Tente de novo daqui a pouco.',
      // A FRASE DIZ O QUE FOI OBSERVADO, não o que se conclui dele (v1.2.21).
      // Ela afirmava "o site não tem os acordes desta música" — e MEDIDO: o
      // Cifra Club serve VARIANTES no mesmo endereço (cifra, letra, partituras
      // para teclado), e a página de letra chegando não prova ausência de cifra
      // nenhuma. Afirmar a conclusão errada é pior que descrever o fato.
      [AVCifra.MOTIVO_SEM_CIFRA]: 'O Cifra Club tem “' + nome + '”, mas não a cifra dela '
        + '— só a letra ou a partitura.',
      [AVCifra.MOTIVO_ILEGIVEL]: 'Achei a página e não consegui lê-la — o site mudou de formato. '
        + 'Isso se corrige numa atualização da base; o Registro em Configurações tem o detalhe.',
    };
    const box = document.createElement('div');
    box.className = 'lv-cifra-estado lv-cifra-erro';
    box.textContent = frases[entrada.motivo] || 'Não foi possível carregar a cifra.';
    el.appendChild(box);

    // A BUSCA MANUAL SAIU (v1.3.3), a pedido do operador — com ela saíram a
    // lista de resultados, a prévia, o campo de consulta e a escolha fixada.
    // O que fica é a FRASE do motivo: são cinco, e cada uma pede uma ação
    // diferente de quem lê (ver `cifraPedir`). Por isso a frase é a resposta
    // inteira agora, e não a introdução de uma tela de correção.
    return;
  }

  const p = entrada.pagina;
  const n = entrada.semitons;

  // O CABEÇALHO: tom e transposição. O tom mostrado é o TRANSPOSTO — mostrar o
  // original ao lado de uma folha já transposta é a folha e o rótulo dizendo
  // coisas diferentes sobre a mesma tela.
  const topo = barra || el;
  topo.className = 'lyricsview-bar lv-cifra-topo';
  if (barra) barra.hidden = false;
  const tom = document.createElement('span');
  tom.className = 'lv-cifra-tom';
  const tomAtual = AVCifra.transporTom(p.tom, n);
  tom.textContent = tomAtual ? 'Tom: ' + tomAtual : '';
  const ctl = document.createElement('div');
  ctl.className = 'lv-cifra-ctl';
  const menos = document.createElement('button');
  menos.type = 'button';
  menos.className = 'lv-fonte-btn';
  menos.textContent = '−½';
  menos.title = 'Descer meio tom';
  menos.setAttribute('aria-label', 'Descer meio tom');
  menos.addEventListener('click', () => cifraTranspor(-1));
  const mais = document.createElement('button');
  mais.type = 'button';
  mais.className = 'lv-fonte-btn';
  mais.textContent = '+½';
  mais.title = 'Subir meio tom';
  mais.setAttribute('aria-label', 'Subir meio tom');
  mais.addEventListener('click', () => cifraTranspor(1));
  // MÚSICA NOVA É FOLHA NOVA, e a rolagem era da anterior. Sem esta guarda o
  // louvor seguinte já entrava rolando, do meio de uma folha que ninguém mandou
  // andar — e o botão diria que está tudo certo.
  if (cifraRolando && cifraRolandoChave !== cifraChave(item)) cifraRolarParar();

  // A ROLAGEM AUTOMÁTICA, à ESQUERDA da transposição: ela é a ação que se usa
  // durante a música inteira, e a transposição é a que se usa uma vez, antes.
  // Os dois botões nascem AQUI porque `renderLyricsView` refaz a folha inteira
  // a cada transposição — o estado vive fora do DOM e eles vêm perguntar.
  cifraRolarBtnEl = document.createElement('button');
  cifraRolarBtnEl.type = 'button';
  cifraRolarBtnEl.className = 'lv-fonte-btn lv-cifra-rolar';
  cifraRolarBtnEl.addEventListener('click', cifraRolarAlternar);
  cifraVelBtnEl = document.createElement('button');
  cifraVelBtnEl.type = 'button';
  cifraVelBtnEl.className = 'lv-fonte-btn lv-cifra-vel';
  cifraVelBtnEl.title = 'Velocidade da rolagem';
  cifraVelBtnEl.setAttribute('aria-label', 'Velocidade da rolagem');
  cifraVelBtnEl.addEventListener('click', cifraVelPasso);
  ctl.append(cifraRolarBtnEl, cifraVelBtnEl, menos, mais);
  topo.append(tom, ctl);
  cifraPintarRolar();

  // A FOLHA. Um nó por linha, com a classe dizendo o que ela é — é o que deixa
  // o acorde ganhar cor sem o CSS ter de adivinhar nada do conteúdo. Só a linha
  // de ACORDES é transposta: passar a de letra pela mesma função reescreveria
  // palavras que casam com a gramática de acorde. Ver `cifraDesenharFolha`.
  cifraDesenharFolha(el, p, n);

  // A ORIGEM, dita e clicável — mas COMO LINK, no rodapé, à direita.
  //
  // Ela era um botão de corpo inteiro no fim da folha, e cobrava altura de uma
  // caixa cuja única função é mostrar texto: *"está cortando absurdamente a
  // área disponível para o texto"*. O peso de um botão prometia uma ação
  // principal, e esta é a menos principal da aba — quem abre a cifra quer LER a
  // cifra; ir ao site é o caminho de quem não achou o que queria.
  //
  // No FIM do conteúdo que rola, não fixo no rodapé da folha: fixo, ele
  // cobraria a mesma altura que acabou de ser devolvida ao texto.
  const rodape = document.createElement('div');
  rodape.className = 'lv-cifra-rodape';
  // A CIFRA É SÓ AUTOMÁTICA (v1.3.3): não há seletor manual em lugar nenhum —
  // nem aqui, nem no ramo de `estado !== 'ok'` acima, onde a frase é a resposta
  // inteira. O preço, dito: uma cifra que ABRIU errada (uma versão
  // simplificada, um homônimo) não tem mais como ser trocada dentro do app;
  // resta o site, no link que as linhas abaixo desenham.
  const fonte = document.createElement('button');
  fonte.type = 'button';
  fonte.className = 'lv-cifra-link';
  fonte.textContent = 'Ver no Cifra Club';
  fonte.addEventListener('click', () => { if (entrada.url) AVNative.openExternal(entrada.url); });
  rodape.appendChild(fonte);
  el.appendChild(rodape);
}

// Desenha as estrofes da música em cena dentro de `el`, destacando `cur`.
function lvBuildSong(el, cur) {
  const lyrics = lvItem().lyrics;
  lyrics.forEach((slide, i) => {
    // O slide de capa não tem letra (no telão é o título do hino). Vira uma
    // linha curta "Início": some do texto, mas continua sendo uma posição real
    // da música — é ela que fica destacada durante a introdução, e ocultá-la
    // faria o destaque sumir justo aí.
    const row = document.createElement('div');
    row.className = 'lv-row' + (slide.cover ? ' lv-row--cover' : '');
    row.dataset.i = String(i);
    if (slide.cover) {
      row.textContent = 'Início';
    } else {
      if (slide.auxText) {
        const aux = document.createElement('div');
        aux.className = 'lv-aux';
        aux.textContent = slide.auxText;
        row.appendChild(aux);
      }
      // A DIVISÃO DENTRO DO SLIDE (v5.142).
      //
      // Um slide da API pode trazer mais de uma estrofe, separadas por uma
      // LINHA EM BRANCO (`<br><br>` na origem, que o `normalizeLyricText`
      // converte em `\n\n`). O visualizador desenhava tudo num nó só com
      // `white-space: pre-line` — e é aí que a divisão se perdia: `pre-line`
      // COLAPSA sequências de espaço em branco, então `\n\n` vira UMA quebra
      // simples e as duas estrofes encostam uma na outra como se fossem um
      // bloco só. Era literalmente o relato: "alguns hinos não estão dividindo,
      // mesmo na realidade tendo divisões".
      //
      // Cada bloco vira um parágrafo próprio. A LINHA continua sendo UMA (o
      // mesmo `data-i`, o mesmo destaque, a mesma posição no tempo): o que se
      // divide é a apresentação do texto, não a unidade de projeção — dividir a
      // unidade quebraria o realce da estrofe em cena e o ⏮/⏭.
      String(slide.text || '')
        .split(/\n[ \t]*\n+/)
        .map((b) => b.trim())
        .filter(Boolean)
        .forEach((bloco) => {
          const txt = document.createElement('div');
          txt.className = 'lv-text';
          txt.textContent = bloco;
          row.appendChild(txt);
        });
    }
    if (i === cur) row.classList.add('current');
    el.appendChild(row);
  });
}

// Desenha o capítulo em leitura dentro de `el`, destacando `cur`.
function lvBuildBible(el, cur) {
  const s = bibleSession;
  s.verses.forEach((v, i) => {
    const row = document.createElement('div');
    row.className = 'lv-row lv-row--verse';
    row.dataset.i = String(i);
    const n = document.createElement('span');
    n.className = 'lv-num';
    n.textContent = String(v.n);
    const txt = document.createElement('span');
    txt.className = 'lv-text';
    txt.textContent = v.text;
    row.append(n, txt);
    if (i === cur) row.classList.add('current');
    el.appendChild(row);
  });
}

// ===== A APRESENTAÇÃO INTEIRA, EM PÁGINAS (v1.4.24) =====
//
// Pedido do operador: *"preciso de um visualizador futuro dos slides de toda a
// apresentação e a referência do slide atual (do mesmo molde vertical que já
// temos nos versos da bíblia na aba da bíblia)"*.
//
// É o MESMO molde do `lvBuildBible`, e de propósito: uma coluna de linhas
// numeradas, com a que está no ar marcada e centralizada pelo `lvScroll` que já
// existe. O que muda é o corpo da linha — ali onde o versículo tem texto, a
// página tem a própria imagem.
//
// **O valor está no que vem DEPOIS.** Quem opera não precisa da página que já
// está projetada (ela está no telão, e na preview): precisa saber o que vem a
// seguir para anunciar, para acompanhar o pregador e para não passar de duas.
//
// TRÊS coisas que este desenho não pode perder:
//
//  - **`loading="lazy"`**: uma apresentação de 300 páginas decodificada de uma
//    vez são centenas de bitmaps de 1920×1080 na memória do renderer — o mesmo
//    processo dos dois WebViews e da Presentation. Só o que entra na tela é
//    decodificado.
//  - **A ALTURA É RESERVADA NO CSS** (`aspect-ratio`), e é o que torna o `lazy`
//    seguro: uma imagem ainda não carregada tem altura ZERO, e `lvScroll` mede
//    `offsetTop` — sem a reserva a coluna cresceria à medida que as imagens
//    entrassem e a página em cena apareceria fora da tela.
//  - **As URLs são REVOGADAS** (ver `lvDeckSoltarUrls`, chamado no ponto único
//    em que o corpo é esvaziado).
let lvDeckUrls = [];

/**
 * Solta as URLs de UMA lista.
 *
 * A lista é PARÂMETRO porque há DOIS lugares que desenham a coluna de páginas —
 * a folha do modo avançado e a zona de leitura do Modo Fácil (v1.4.30) —, e uma
 * lista única faria o redesenho de um revogar as imagens do outro: a coluna
 * ficaria com os quadros vazios, sem erro em lugar nenhum, porque uma `<img>`
 * com `src` revogado simplesmente não pinta.
 */
function lvSoltarUrls(lista) {
  for (const u of lista) { try { URL.revokeObjectURL(u); } catch (_) { /* já foi */ } }
  lista.length = 0;
}
function lvDeckSoltarUrls() { lvSoltarUrls(lvDeckUrls); }

// `urls` é o SUMIDOURO das URLs de objeto criadas aqui — ver `lvSoltarUrls`.
function lvBuildDeck(el, cur, urls) {
  const rec = lvDeckRec();
  const pages = (rec && rec.pages) || [];
  // O TOQUE PULA PARA A PÁGINA (v1.4.26), a pedido do operador: *"preciso da
  // capacidade de tocar nos slides para passar ou pular diretamente para um
  // slide em específico"*.
  //
  // SÓ COM A APRESENTAÇÃO EM CENA. Com um alvo da Biblioteca não há para onde
  // pular — aquela apresentação não está projetando —, e a folha de um alvo é
  // leitura pura: *nada ali projeta* é a regra do `lvAlvo`, e um toque que
  // mandasse um `page` a partir dela romperia justamente a promessa de abrir
  // uma mídia sem que a congregação veja.
  const tocavel = lvNaCena() && !!deckNoAr();
  pages.forEach((p, i) => {
    const row = document.createElement('div');
    row.className = 'lv-row lv-row--slide' + (tocavel ? ' lv-row--tocavel' : '');
    row.dataset.i = String(i);
    // ===== O NÚMERO É SOBREPOSTO, E O "NO AR" MORA AO LADO DELE (v1.4.35) =====
    //
    // Pedido do operador: *"coloque o número da página sobreposto ao slide, para
    // o slide poder ficar centralizado, e use um 'no ar', ao lado do indicador
    // de página para indicar a página atual, assim como já usamos em diversos
    // elementos no app"*.
    //
    // O número ocupava uma COLUNA à esquerda (MEDIDO: 27px + o respiro, de 408),
    // e era ela que empurrava a miniatura para fora do centro da linha. Fora do
    // fluxo, a miniatura passa a ocupar a largura inteira e uma página 4:3
    // aparece centrada pelo `object-fit` — sem nada a compensar.
    //
    // **O SELO NASCE EM TODA LINHA, e quem o revela é o CSS.** `lvMarkCurrent`
    // move a classe `.current` SEM redesenhar (é o que mantém as URLs de objeto
    // vivas a cada troca de página); criar o "● No ar" no JS obrigaria aquela
    // função a mover um nó também — um segundo lugar para divergir, e o defeito
    // seria o selo ficando na página anterior.
    const selo = document.createElement('span');
    selo.className = 'lv-selo';
    const n = document.createElement('span');
    n.className = 'lv-num';
    n.textContent = String(i + 1);
    // O MESMO texto e a MESMA classe do selo das listas (`pintarSubNoAr`): é o
    // que o operador já lê como "isto está no telão" em toda parte do app.
    const live = document.createElement('span');
    live.className = 'row-live';
    live.textContent = '● No ar';
    selo.append(n, live);
    const img = document.createElement('img');
    img.className = 'lv-slide';
    img.alt = '';
    img.loading = 'lazy';
    img.decoding = 'async';
    // STRING ou BLOB, como o `pages` do `stage.js`: no registro do aparelho as
    // páginas são Blob, e a mesma lista chega como URL quando ela vem de fora.
    if (typeof p === 'string') img.src = p;
    else if (p) { const u = URL.createObjectURL(p); (urls || lvDeckUrls).push(u); img.src = u; }
    // A IMAGEM PRIMEIRO: o selo é absoluto e pousa sobre ela sem `z-index`
    // próprio — a ordem do documento basta, e uma pilha a menos é uma disputa a
    // menos com o resto da folha.
    row.append(img, selo);
    if (i === cur) row.classList.add('current');
    // O MESMO CAMINHO DO ⏮/⏭ (`deckIr`), e não um comando próprio: quem já está
    // na página não emite nada (a guarda mora lá dentro), e o destaque volta
    // pelo `renderSlideNav` como em qualquer outra troca.
    if (tocavel) row.addEventListener('click', () => deckIr(i));
    el.appendChild(row);
  });
}

// Move o destaque dentro de um container já desenhado (sem re-render).
function lvMarkCurrent(el, idx) {
  const prev = el.querySelector('.lv-row.current');
  if (prev) prev.classList.remove('current');
  const row = el.querySelector('.lv-row[data-i="' + idx + '"]');
  if (row) row.classList.add('current');
}

// Chamado no mesmo pulso que a navegação de estrofe (renderSlideNav), que já
// roda a cada tick e a cada troca de versículo/mensagem. Com o popup fechado
// custa uma comparação de classe.
function refreshLyricsView() {
  if (!lyricsPopupEl.classList.contains('open')) return;
  const src = lvActiveSource();
  if (lvSignature(src) !== lvSig) { renderLyricsView(); lvScrollToCurrent(true); return; }
  if (!src) return;
  const idx = lvCurrentIndex(src);
  if (idx === lvCurIdx) return;
  lvCurIdx = idx;
  lvMarkCurrent(lyricsViewBodyEl, idx);
  lvScrollToCurrent(true);
}

// ===== Zona de leitura do Modo Fácil =====
// A mesma coluna do popup de leitura auxiliar, embutida na tela: ali o espaço
// entre as ações e as teclas estava vazio, e é justamente o que o operador
// quer olhar enquanto a música toca. Só leitura (a Bíblia não existe neste
// modo)...
//
// ===== ...E A APRESENTAÇÃO, QUE AQUI NÃO É SÓ LEITURA (v1.4.30) =====
//
// Pedido do operador: *"verifique o modo simples e seu auxiliar de leitura. Ele
// deve adquirir as funções para controle de slides também"*.
//
// MEDIDO antes de mexer: com uma apresentação em cena o Modo Fácil não a
// operava de jeito NENHUM. A zona dizia *"A letra da música aparece aqui"* — a
// projeção no ar negada pela única superfície que deveria descrevê-la —, e as
// teclas eram play · parar · mudo, sem nada que virasse página. O eixo já
// existia (`slideTarget()` respondia `'deck'`); o que faltava era alguém neste
// modo ligado a ele. Uma apresentação entrava pelo compartilhamento, projetava,
// e ficava presa na página 1 até o operador ir ao modo avançado.
//
// A ASSIMETRIA COM A LETRA É O PONTO. A letra anda sozinha, pelo relógio da
// música: ali a zona ilustra e mais nada. Um deck não tem relógio — alguém
// precisa passar a página —, e por isso aqui ela é também CONTROLE: o toque
// numa página pula para ela (o mesmo `deckIr` do modo avançado), e o par de
// teclas abaixo é o ⏮/⏭ em tamanho de dedo.
//
// QUEM ESTÁ NA FRENTE VENCE, e é a mesma pilha do auxiliar do modo avançado
// (v1.4.26): com uma apresentação sobre um louvor de fundo (v1.4.28) a zona
// mostra as PÁGINAS. Há UMA zona neste modo, e mostrar a camada de trás seria
// descrever o que a congregação não está vendo.
let lvSimpleSig = '';
let lvSimpleIdx = -1;
let lvSimpleFollow = true;
// O SUMIDOURO PRÓPRIO das miniaturas desta zona — ver `lvSoltarUrls`. Partilhar
// a lista com a folha do modo avançado faria o redesenho de uma revogar as
// imagens da outra, e uma `<img>` com `src` revogado não pinta nem erra.
const lvSimpleDeckUrls = [];

function refreshSimpleLyrics() {
  if (appMode !== 'simple') return;
  const deck = deckNoAr();
  const lyrics = (!deck && currentItem && Array.isArray(currentItem.lyrics)
    && currentItem.lyrics.length) ? currentItem.lyrics : null;
  // A PÁGINA FICA FORA DA ASSINATURA, pela razão do `lvSignature`: o destaque
  // anda por classe, e com ela aqui dentro cada toque no ⏭ revogaria e
  // recriaria as miniaturas de uma apresentação inteira no meio do sermão.
  const sig = deck ? ('deck|' + (deck.id || deck.name) + '|' + deck.pages.length)
    : lyrics ? ('letra|' + currentId + '|' + lyrics.length) : 'none';
  if (sig !== lvSimpleSig) {
    lvSimpleSig = sig;
    lvSimpleFollow = true;   // cena nova: volta a acompanhar
    simpleLyricsEl.innerHTML = '';
    lvSoltarUrls(lvSimpleDeckUrls);
    lvSimpleIdx = deck ? deckPagina
      : lyrics ? findSlideIndex(lyrics, authoritativeTime()) : -1;
    if (!deck && !lyrics) {
      const empty = document.createElement('div');
      empty.className = 'lv-empty';
      empty.textContent = 'A letra da música aparece aqui.';
      simpleLyricsEl.appendChild(empty);
      return;
    }
    // A GRADE DE DUAS COLUNAS é do DECK e só dele (v1.4.35) — ver `.lv-grade`.
    // Ela mora numa classe do CONTAINER porque é o container que muda de eixo;
    // a linha continua sendo a mesma `.lv-row--slide` dos dois modos, e é isso
    // que faz o selo, o toque e o `lvScroll` valerem aqui sem um segundo
    // desenho.
    simpleLyricsEl.classList.toggle('lv-grade', !!deck);
    if (deck) lvBuildDeck(simpleLyricsEl, lvSimpleIdx, lvSimpleDeckUrls);
    else lvBuildSong(simpleLyricsEl, lvSimpleIdx);
    requestAnimationFrame(() => lvScroll(simpleLyricsEl, lvSimpleFollow, false));
    return;
  }
  if (!deck && !lyrics) return;
  const idx = deck ? deckPagina : findSlideIndex(lyrics, authoritativeTime());
  if (idx === lvSimpleIdx) return;
  lvSimpleIdx = idx;
  lvMarkCurrent(simpleLyricsEl, idx);
  lvScroll(simpleLyricsEl, lvSimpleFollow, true);
}

// Rolar com o dedo para de disputar o scroll, como no popup — até a próxima
// música (ou o próximo `sig`, que religa o acompanhamento).
simpleLyricsEl.addEventListener('pointerdown', () => { lvSimpleFollow = false; });
simpleLyricsEl.addEventListener('wheel', () => { lvSimpleFollow = false; }, { passive: true });

// Centraliza a linha no ar. `smooth` só na atualização ao vivo — na abertura o
// conteúdo precisa já nascer na posição certa, sem uma rolagem visível.
// Rola o PRÓPRIO corpo do popup (scrollTop), não scrollIntoView: este último
// mexeria também nos ancestrais, e a lista do app fica atrás da folha.
function lvScrollToCurrent(smooth) {
  lvScroll(lyricsViewBodyEl, lvFollow, smooth);
}

function lvScroll(el, follow, smooth) {
  if (!follow) return;
  const row = el.querySelector('.lv-row.current');
  if (!row) return;
  const top = row.offsetTop - (el.clientHeight - row.offsetHeight) / 2;
  el.scrollTo({ top: Math.max(0, top), behavior: smooth ? 'smooth' : 'auto' });
}

function resetAfterEnd() {
  // stage.js já voltou ao wallpaper internamente (ended flag);
  // apenas atualiza a UI sem limpar currentId (replay possível com play)
  //
  // E o telão está no wallpaper: o item continua SELECIONADO (é o que permite
  // repetir com o ▶), mas não está mais EM CENA. Sem esta linha, todo dongle
  // que caísse depois do fim de um louvor trazia a faixa de volta à TV — que é
  // o "ele tenta exibir a primeira tela/thumbnail" do relato.
  midiaNoAr = false;
  midiaNoArId = '';
  midiaNoArOrigem = '';
  // E O BANCO PRECISA SABER: é este `noAr` que solta o detentor da cena (ver
  // `persistCurrent`). Sem ele o item que acabou de tocar ficaria protegido do
  // coletor até o operador escolher outro.
  persistCurrent();
  setPlaying(false);
  seekEl.value = 0;
  curTimeEl.textContent = '0:00';
  seekEl.disabled = false;
  durTimeEl.textContent = fmtTime(preview.getDuration());
  // E A LISTA PRECISA SABER (v5.301, relato do operador: *"ao encerrar a mídia no
  // player, a demarcação em vermelho do próprio item no cronograma não
  // desaparece, parecendo que o item ainda está no ar"*).
  //
  // Zerar `midiaNoAr` é só ESTADO; quem apaga o preenchimento e o selo "● No ar"
  // da linha é `marcarNoAr` — e este era o único dos caminhos que baixam a
  // bandeira sem chamá-lo (`stopClear` e `retirarDoAr` sempre chamaram, e
  // `pararMidia` é o corpo dos dois). A faixa terminava, o telão voltava ao
  // wallpaper e a linha continuava vermelha até um redesenho por outro motivo,
  // que num culto pode nunca vir.
  //
  // SÓ ELE. `renderNowPlaying` termina em `seekEl.disabled = !isTimed`, com
  // `isTimed` saindo de um `cur` que pode ser nulo (item fora das duas listas):
  // ele desfaria a linha acima, que devolve a barra de propósito para o ▶ poder
  // repetir a faixa. O cartão do player já é republicado pelo `setPlaying`.
  marcarNoAr();
}

// TODO `send` DAQUI PASSA `daFila` (v5.312): a imagem que chega pelo avanço
// automático é o PRÓXIMO item da sequência, não um cartão que alguém pediu por
// cima do atual. Sem a marca, a fila pararia de andar sozinha na primeira
// imagem — com o áudio anterior tocando para sempre por baixo dela.
function autoAdvance() {
  if (repeat === 'off') { resetAfterEnd(); return; }
  if (repeat === 'one') { if (currentId) send(currentId, true); return; }
  if (plItems.length === 0) return;
  if (repeat === 'shuffle') {
    if (plItems.length === 1) { send(plItems[0].id, true); return; }
    let i; do { i = Math.floor(Math.random() * plItems.length); } while (plItems[i].id === currentId);
    send(plItems[i].id, true);
    return;
  }
  // all
  const idx = plItems.findIndex((m) => m.id === currentId);
  const target = idx === -1 ? 0 : (idx + 1) % plItems.length;
  send(plItems[target].id, true);
}

async function cycleRepeat() {
  repeat = REPEATS[(REPEATS.indexOf(repeat) + 1) % REPEATS.length];
  await AVDB.setState('repeat', repeat);
  renderRepeat();
}

async function setView(v) {
  view = v; await persistCurrent();
  // Com a Camada de Texto em cena — Bíblia OU Mensagem, o mesmo cartão —,
  // 'view' só liga/desliga a cortina compartilhada (mesmo modelo do YouTube):
  // não passa por preview.handle, que recobriria na hora, já que o stage da
  // preview está sem `current` (a camada é paralela) e computeCover() daria
  // true. O Display já trata os dois provedores por `textActive`; checar só
  // `bibleSession` fazia a mensagem sumir da preview enquanto seguia no telão.
  if (pvTextActive) {
    AVDB.sendCommand({ type: 'view', view });
    // Cortina com fade (coverIn/coverOut respeitam a config de transições).
    if (v === 'wallpaper') preview.coverIn(false); else preview.coverOut();
    renderControls();
    return;
  }
  cmd({ type: 'view', view });
  renderControls();
}
async function toggleMute() {
  // Sem áudio no Display (bloqueio do navegador, não é mudo do operador):
  // o clique vira "liberar o som" — pede uma retentativa imediata.
  if (displayAudioBlocked && !muted) {
    AVDB.sendCommand({ type: 'audio-retry' });
    // (idem: no-op legado. Quem relata o áudio bloqueado é o próprio botão
    //  de mudo, que veste `.blocked` — ver `renderControls`.)
    return;
  }
  // ===== O COMANDO VAI NA FRENTE DA GRAVAÇÃO (v1.5.6) =====
  // Relato do operador: *"ativar o mudo durante a exibição de um vídeo online do
  // YouTube está travando momentaneamente, engasgando a visualização"*.
  //
  // Este era o ÚNICO controle do app que punha uma transação de banco na frente
  // do comando: `await persistCurrent()` é uma escrita no IndexedDB, e o `mute`
  // só saía depois do commit dela. O irmão que mexe no mesmo áudio
  // (`applyVolume`) sempre mandou primeiro — a assimetria não tinha razão.
  //
  // **Por que isto pesa numa TRANSMISSÃO e não num arquivo:** os dois WebViews
  // dividem UM processo, e a transmissão direta é a única mídia do app que
  // precisa de JavaScript rodando enquanto toca (o `shared/mse.js` repõe o
  // buffer). Tudo que segura a thread principal entre o toque e o comando segura
  // o abastecimento junto — um arquivo local não sente, porque o `<video>` lê do
  // disco sem passar por JS nenhum.
  //
  // A gravação continua acontecendo, agora SEM prender o comando: o que ela
  // guarda é o ajuste da mesa para a próxima sessão, e ninguém a espera.
  // (`persistCurrent` já é usado assim em quatro outros pontos.)
  //
  // **O QUE ISTO NÃO PROVA, dito:** o engasgo do relato não foi reproduzido fora
  // do aparelho — aqui a escrita mede ~2 ms num banco vazio. O que se corrige é
  // uma latência REAL e mensurável no caminho exato do relato, não um defeito
  // observado. Se o engasgo persistir, o próximo suspeito não é este arquivo: é
  // o que o Chromium faz com um `<video>` de MediaSource ao trocar de estado de
  // áudio.
  muted = !muted;
  cmd({ type: 'mute', muted });
  renderControls();
  persistCurrent();
}

/**
 * TIRAR A MÍDIA DO AR — o corpo comum do Parar e do stop por camada.
 *
 * O que ele NÃO faz é o que o distingue: nada aqui encosta na Camada de Texto.
 * Quem encerra a cena inteira é o [stopClear], que chama isto e depois derruba o
 * texto; quem tira só a música de fundo é o [retirarDoAr], que chama isto e para
 * por aqui.
 *
 * [tipo] é o comando que vai ao telão — `clear` (o ponto final, com a cortina
 * indo ao wallpaper) ou `media-clear` (só a mídia; ver `display.js`).
 */
async function pararMidia(tipo) {
  // Parar também é um comando do operador: arma a mesma janela de
  // `pausaPedida` que o ▶ arma, senão o `pause` que o 'clear' provoca no
  // <video> da preview entrava no diário como "PAUSA ESPONTÂNEA" — um falso
  // alarme no instrumento que existe para achar as pausas de verdade.
  pausaEm = Date.now();
  diagC('parou a mídia (' + tipo + ')');
  cmd({ type: tipo });
  // O TELÃO ESTÁ VAZIO A PARTIR DAQUI, e isso precisa ser dito ANTES do fade
  // terminar: quem pergunta a `preview.getCurrent()` recebe "ainda tem mídia"
  // durante todo o esmaecimento do `clearFaded` (ver `midiaNoAr`).
  midiaNoAr = false;
  midiaNoArId = '';
  midiaNoArOrigem = '';
  await persistCurrent();   // solta o detentor da cena — ver `persistCurrent`
  setPlaying(false);
  // Item de LINK: o `clear` derruba a cena, e o próximo ▶ precisa passar pelo
  // `send` (que hoje o RESOLVE — ver `resolverLinkYoutube`), não só reenviar
  // 'play'.
  if (currentItem && currentItem.kind === 'youtube') ytEnded = true;
  playPauseEl.querySelector('.msym').textContent = ICON.play;
  seekEl.value = 0; seekEl.disabled = true;
  curTimeEl.textContent = '0:00';
}

/**
 * Parar = limpar o display (volta ao wallpaper); mantém currentId para replay
 * com play.
 *
 * ===== COM AS DUAS CAMADAS NO AR, ELE FALA SÓ DA DE BAIXO (v1.2.0) =====
 *
 * Pedido do operador: *"considerando que o preview tem um botão apenas para
 * remover as camadas superiores, ajuste o botão de stop para em caso onde há
 * mídia de fundo e mensagens ou sobreposição de elementos na tela como bíblia
 * e etc… o botão de stop funciona apenas para a mídia de fundo"*.
 *
 * O app já tinha as DUAS portas — `encerrarCamadaDeCima` (o selo `#pvCamadaBtn`
 * sobre a preview) para a de cima, `pararMidia('media-clear')` para a de baixo
 * —, e o Parar era o único controle que não escolhia nenhuma: ele derrubava as
 * duas de uma vez. Com um louvor de fundo sob um versículo (o uso normal, e o
 * que a independência áudio × texto existe para permitir), tirar a música
 * levava o versículo junto, e devolvê-lo custava reprojetar a cena na frente da
 * congregação.
 *
 * A regra é: **cada botão fala de UMA camada, e o Parar fala da mídia** — o
 * mesmo desdobramento que o `retirarDoAr` da linha já faz. Com uma camada só no
 * ar não há o que escolher, e ele volta a ser o ponto final de sempre.
 *
 * A PERGUNTA É `midiaNoAr`, NUNCA `currentId`: este último sobrevive ao Parar
 * de propósito (é ele que deixa o ▶ repetir a faixa), então perguntar por ele
 * faria o SEGUNDO Parar seguido — o que encerraria o versículo — virar no-op
 * para sempre. É a mesma régua do reenvio de cena.
 */
async function stopClear() {
  // As duas camadas no ar: sai só a de baixo, e a Camada de Texto fica onde
  // está. O `clearManualText` NÃO pode entrar aqui — ele é a escrituração que
  // apaga as seis sessões, e sem elas o operador perderia a navegação do
  // versículo que continua projetado.
  if (cenaDeRoteiroNoAr() && midiaNoAr) {
    await pararMidia('media-clear');
    marcarNoAr();
    renderNowPlaying();
    await persistCurrent();
    return;
  }
  await pararMidia('clear');
  clearManualText();
  // A cena de roteiro caiu junto (o `clearManualText` acima), e o realce dela
  // precisa cair com ela: ele vem do `cueNoArId`, que nenhuma re-renderização
  // da lista está agendada para reler. Sem isto, uma linha continuaria marcada
  // como "no ar" sobre um telão vazio até a próxima troca de aba.
  marcarNoAr();
  await persistCurrent();
}

/**
 * ===== O PALCO SAI DE CENA NO INSTANTE DO TOQUE (v1.4.6) =====
 *
 * "Tocar agora" num vídeo do YouTube leva SEGUNDOS até a primeira mudança na
 * tela (a extração de rede do `ytStream`), e nesse intervalo o app não dizia
 * nada. **A interrupção é o reconhecimento do toque**: o comando não tem
 * ambiguidade — a cena atual vai sair de qualquer jeito —, então tirá-la no ato
 * não antecipa nada, apenas para de esconder o que já foi decidido.
 *
 * É o mesmo protocolo visual que o `stage.load` já usa (esmaece o que está no
 * ar e segura o aro de espera até `PRONTO_STREAM_MS`); o que muda é COMEÇAR no
 * instante do comando, e não no instante em que os bytes são conhecidos.
 *
 * **NÃO É `stopClear`**, e a diferença é o `clearManualText`: aquele encerra as
 * seis sessões de texto, e aqui não há razão para isso — a mídia é que está
 * sendo trocada. Um versículo projetado sobre o louvor continua projetado, como
 * continuaria numa troca de faixa qualquer. A escolha da camada é a MESMA
 * (`media-clear` com cena de roteiro no ar, `clear` sem ela): duas réguas para
 * a mesma pergunta divergiriam no primeiro ajuste.
 *
 * **NÃO ESPERA A GRAVAÇÃO.** O efeito visível de `pararMidia` é síncrono (o
 * `cmd` sai na hora, e chega ao telão e às telas da rede); o que ele aguarda é
 * o `persistCurrent`, um `await` de IndexedDB. Segurar o toque nele seria
 * trocar uma espera de rede por uma de disco — menor, e igualmente sem motivo.
 *
 * **O preço está dito:** falhando a transmissão, a cena cai no download, que
 * leva minutos, e o telão passa esses minutos no wallpaper com o cartão
 * explicando. É a leitura honesta de *"pedi outra mídia e ela está vindo"* —
 * devolver a anterior seria o app decidir por cima do operador.
 */
function cederOPalco(nome) {
  if (midiaNoAr) {
    pararMidia(cenaDeRoteiroNoAr() ? 'media-clear' : 'clear')
      .then(() => { marcarNoAr(); renderNowPlaying(); })
      .catch(() => { /* o `finally` do chamador solta o cartão de qualquer jeito */ });
  }
  const cartao = previewBusy('Preparando', nome);
  // A senha é lida AQUI e não no chamador: `cederOPalco` é o ponto por onde as
  // duas portas do link passam (o item de lista e o "Tocar agora" da busca).
  registrarPalcoEmVoo(cartao);
  return cartao;
}



// ===== gestos da biblioteca =====
// **O deslize lateral da linha SAIU na v5.50.** Ele adicionava o item à
// playlist (`dx <= -SWIPE`), e a pista disso era um ícone a 22% de opacidade
// atrás da linha — um atalho que praticamente ninguém descobria e que, ainda
// assim, reservava para si o eixo horizontal da maior parte da tela. Era ele
// que impedia o carrossel de abas de funcionar onde o operador de fato desliza:
// sobre a lista. Trocar um atalho invisível por uma navegação que todo aparelho
// Android tem é a troca certa — e a playlist continua a UM toque, pelo botão
// `+` de cada resultado do acervo e pelo popup da playlist.
//
// O que fica: toque (troca a cena) e toque longo (entra na seleção múltipla).
// O movimento agora só CANCELA o gesto da linha, em qualquer direção: quem
// estiver deslizando está falando com o carrossel ou com a rolagem, não com o
// item.
const MOVE = 10, LONGPRESS = 450;

function attachRowGestures(row, item) {
  let startX = 0, startY = 0, startT = 0, longFired = false, lp = null, pid = null;
  // A opção `semSelecao` viveu aqui da v5.271 à v5.286, para os Favoritos: a
  // lista não tem seleção múltipla, e o toque longo ligava um modo que ali não
  // tinha o que operar. Ela saiu na v5.287 com o último chamador — a linha de
  // favorito deixou de responder a estes gestos e passou a abrir a gaveta da
  // Biblioteca. Quem usa isto agora é só a lista principal, que TEM o modo.
  //
  // **E A GUARDA DELA FICOU PARA TRÁS, lendo um nome que deixou de existir.**
  // O parâmetro saiu da assinatura e o `if (semSelecao) return` continuou no
  // corpo: num script clássico (sem `type=module` e sem `'use strict'`), LER um
  // identificador não declarado lança `ReferenceError` — só a ATRIBUIÇÃO é que
  // criaria uma global. Então todo `pointerdown` numa linha do Cronograma
  // estourava ali, ANTES do `setTimeout`, e o toque longo simplesmente deixou
  // de existir: com ele, a seleção múltipla — e o `deleteSelected`, que é o
  // único excluir em lote do app — ficaram sem porta nenhuma.
  //
  // O modo de falhar é o pior desta base: o `pid` já tinha sido escrito na
  // linha anterior, então o TOQUE CURTO continuava projetando normalmente e
  // nada na tela mudava. O que sumia era só o gesto que ninguém usa todo dia —
  // e um toque um pouco mais demorado que 450 ms passou a não fazer NADA.

  row.addEventListener('pointerdown', (e) => {
    // `.row-slot` (v1.4.27): a coluna do `⋮` emprestada ao processo fica FORA
    // da faixa, e o que existe por baixo dela é esta linha — cujo toque
    // PROJETA. Sem a guarda, tocar na lixeira da pergunta poria no ar a mídia
    // que se está perguntando se apaga; e o toque longo abriria a seleção
    // múltipla por cima de uma confirmação aberta.
    if (e.target.closest('.row-btn,.row-acoes,.row-slot')) return;
    pid = e.pointerId; startX = e.clientX; startY = e.clientY; startT = Date.now(); longFired = false;
    lp = setTimeout(() => { longFired = true; enterSelection(item.id); }, LONGPRESS);
  });
  row.addEventListener('pointermove', (e) => {
    if (pid === null) return;
    // Saiu do lugar? O toque deixou de ser um toque. `pid = null` encerra o
    // gesto DESTA linha sem tocar no evento — ele segue subindo para o
    // carrossel de abas e para a rolagem da lista, que são de quem o dedo está
    // falando agora.
    if (Math.abs(e.clientX - startX) > MOVE || Math.abs(e.clientY - startY) > MOVE) {
      clearTimeout(lp); pid = null;
    }
  });
  row.addEventListener('pointerup', (e) => {
    if (pid === null) return;
    clearTimeout(lp);
    if (!longFired && Date.now() - startT < LONGPRESS) onTap(item);
    pid = null;
  });
  row.addEventListener('pointercancel', () => { clearTimeout(lp); pid = null; });
}

// Trocar de música do zero: a playlist passa a ser SÓ este item.
//
// Junto vai o `repeat='one'`: repetir a mesma música é uma escolha sobre a
// música que estava tocando, não uma preferência permanente — mantê-la aqui
// prenderia o item novo em laço, que é o oposto de "escolhi outra coisa para
// tocar". `all`/`shuffle` ficam: são comportamentos da FILA, e continuam
// valendo quando o operador acrescentar itens a ela.
async function replacePlaylistWith(rec) {
  await AVDB.listSet('playlist', [rec.id]);
  plItems = [rec];
  renderPlaylist();
  if (repeat === 'one') {
    repeat = 'off';
    await AVDB.setState('repeat', repeat);
    renderRepeat();
  }
}

/**
 * TOCAR DE NOVO NO QUE JÁ ESTÁ NO AR = TIRAR DO AR.
 *
 * É a convenção que a Bíblia, a Mensagem, o cronômetro e o sorteio já seguiam,
 * e que faltava nos itens do Cronograma: ali a única saída era o **Parar**, que
 * é outra coisa — ele encerra a CENA INTEIRA. Com um louvor de fundo sob um
 * versículo (que é o uso normal, e que a independência áudio × texto existe
 * para permitir), tirar o versículo pelo Parar levava a música junto.
 *
 * Por isso o desligamento é POR CAMADA, e não um `clear` genérico:
 *
 *  - **cena de roteiro** (versículo, mensagem, letra, cronômetro, sorteio) sai
 *    pela Camada de Texto e **não toca na mídia** — o áudio de fundo continua;
 *  - **mídia** sai pelo mesmo caminho do Parar, porque ali ela É a cena.
 *
 * `currentId` NÃO é zerado, de propósito: é ele que permite ao ▶ repetir o
 * item sem precisar reabri-lo, e é um contrato que o CLAUDE.md descreve. Quem
 * responde "há algo no telão?" é `midiaNoAr`, e é ele que o `stopClear` baixa.
 */
async function retirarDoAr(item) {
  // A IMAGEM SOBREPOSTA sai pela porta da CAMADA, não pela da mídia — e por
  // isso ela vem antes das duas. O ramo de baixo chamaria `pararMidia`, que
  // encerra o ÁUDIO: o operador toca na imagem para tirá-la e o louvor é que
  // some, com a imagem de pé. É o simétrico exato do `text-hide` do ramo de
  // cue, aplicado ao único item de mídia que projeta por aquela porta.
  if (item && visualSobreNaLinha(item.id)) { hideVisualSobre(); return; }
  if (isCue(item)) {
    // O `text-hide` É O QUE TIRA DA TELA — e ele faltava.
    //
    // `clearManualText()` é BOOKKEEPING: as SEIS `clear*Session` zeram o
    // estado do Controle, re-renderizam a navegação e não mandam um único
    // comando ao telão. Nos outros chamadores isso está certo, porque logo
    // atrás vem um `load` (que esconde o texto no Display) ou um `clear`. Aqui
    // não vem nada — e o resultado era o defeito que o operador relatou com
    // todas as letras: o segundo toque "não remove no player". Ele removia a
    // SESSÃO, e o versículo continuava projetado na frente da congregação, sem
    // nenhuma linha na tela do operador que o dissesse.
    //
    // `text-hide` encerra só a Camada de Texto — é o mesmo comando do "tirar do
    // ar" da Bíblia e da Mensagem, e é justamente o que o `clear` NÃO é: o
    // áudio de fundo segue tocando.
    cmd({ type: 'text-hide' });
    clearManualText();
    // O realce sai da CENA e fica na MÍDIA, se houver — era isto que o
    // `remove('active')` cego apagava junto. Tirar o versículo do ar não tira o
    // louvor que continua tocando por baixo dele, e a lista precisa continuar
    // dizendo isso.
    marcarNoAr();
    renderNowPlaying();
    return;
  }
  // MÍDIA: sai SÓ ELA (v5.178). Até aqui este caminho chamava `stopClear()`, que
  // é o Parar do transporte — ele encerra a CENA INTEIRA. Com um louvor de fundo
  // sob a contagem regressiva de abertura (o uso normal, e o que a independência
  // áudio × texto existe para permitir), tirar a música do ar levava o
  // cronômetro junto, e a única saída era parar tudo e reprojetar a cena na
  // frente da congregação. É o simétrico exato do `text-hide` acima: cada camada
  // sai pela sua porta, e o botão de cada linha fala da camada DAQUELA linha.
  await pararMidia('media-clear');
  marcarNoAr();
  renderNowPlaying();
  await persistCurrent();
}

/**
 * O REALCE DA LISTA marca as DUAS coisas que podem estar no ar ao mesmo tempo.
 *
 * Ele era uma linha só (`el.dataset.id === id`), e por isso um louvor de fundo
 * apagava o realce do versículo que continuava projetado: o operador perdia de
 * vista a única linha em que o segundo toque tinha efeito. Duas camadas, dois
 * realces — é o mesmo modelo que a independência áudio × texto já descreve.
 */
// ===== "CARREGANDO" NA PRÓPRIA LINHA (v1.4.21) =====
//
// Pedido do operador: *"ao carregar um link do YouTube… o item só entra em modo
// 'no ar' quando o vídeo realmente está visível na tela, e isso está correto,
// mas o item deve ter também um 'carregando' no próprio item da lista, para
// representação visual e percepção correta de que está carregando aquele item…
// semelhante à ideia de como já fazemos para representar visualmente
// downloads"*.
//
// **O cartão sobre a preview responde "o que vai entrar em cena?"; a linha
// responde "o que este toque está fazendo?"** — e são perguntas diferentes.
// Resolver um link leva segundos (a extração) ou minutos (o download); nesse
// intervalo o "no ar" ainda não pode acender, porque nada está no ar, e sem
// nada na linha o toque não deixou marca nenhuma no lugar onde ele nasceu.
//
// A ANATOMIA É A DO `.baixando`, de propósito: o mesmo aro, na mesma miniatura,
// no mesmo tamanho. Duas formas para a mesma espera fariam o operador perguntar
// se são coisas diferentes. O que muda é o DESENHO — aqui o aro vai SEM a seta,
// pela regra da v1.4.20: não há bytes chegando, e prometê-los é o que aquele
// lote acabou de tirar do cartão.
//
// E o estado vive num SET, não na classe do nó: a lista é reconstruída no meio
// da espera (o `load()` do caminho do download), e uma classe escrita no nó
// sumiria no redesenho seguinte. É a mesma razão do `songRowBusy`.
const linhasCarregando = new Set();

function linhaCarregando(id) {
  return !!id && linhasCarregando.has(id);
}

// O aro SEM seta. `data-espera` o distingue do aro de um download que esteja na
// mesma miniatura — a repintura só pode remover o que ela mesma pôs.
function aroDeEspera() {
  const a = document.createElement('span');
  a.className = 'dl-ring';
  a.dataset.espera = '1';
  a.setAttribute('aria-hidden', 'true');
  return a;
}

// A METADE DE CONSTRUÇÃO: chamada pelos montadores de linha, para o estado
// sobreviver a um redesenho. Espelha o `linhaNoAr(item.id)` que eles já leem.
function porCarregando(li, thumb, id) {
  if (!linhaCarregando(id)) return;
  li.classList.add('carregando');
  if (thumb) thumb.appendChild(aroDeEspera());
}

// A METADE DE REPINTURA, irmã do `marcarNoAr`: o toque acontece com a lista já
// na tela, e refazê-la inteira (como o `libBusy` faz) reconstruiria dezenas de
// linhas com object URLs de miniatura só para acender um aro.
function pintarCarregando() {
  document.querySelectorAll('.lib-item,.row-item').forEach((el) => {
    const on = linhaCarregando(el.dataset.id);
    if (on === el.classList.contains('carregando')) return;
    el.classList.toggle('carregando', on);
    const thumb = el.querySelector('.thumb');
    if (!thumb) return;
    const meu = thumb.querySelector('.dl-ring[data-espera]');
    if (on) { if (!meu) thumb.appendChild(aroDeEspera()); }
    else if (meu) meu.remove();
  });
}

function marcarCarregando(id, on) {
  if (!id) return;
  if (on) linhasCarregando.add(id); else linhasCarregando.delete(id);
  pintarCarregando();
}

function marcarNoAr() {
  // O SELO DE CAMADAS responde a DUAS coisas, e esta função é a que sabe da
  // segunda: a mídia entrando ou saindo do ar muda a resposta dele tanto quanto
  // a camada de texto muda. `renderNowPlaying` cobre o outro lado.
  renderCamadaBtn();
  document.querySelectorAll('.lib-item,.row-item').forEach((el) => {
    const id = el.dataset.id;
    el.classList.toggle('active', linhaAtiva(id));
    const noAr = linhaNoAr(id);
    el.classList.toggle('no-ar', noAr);
    // O SELO acompanha a classe: ele é a metade que se LÊ, e sem ele o estado
    // volta a ser só uma cor a mais numa tela que já tem várias.
    const sub = el.querySelector('.row-sub');
    if (sub) { pintarSubNoAr(sub, noAr); pintarFalha(sub, id); }
  });
}

/**
 * ESTA LINHA ESTÁ NO TELÃO AGORA?
 *
 * Diferente de [linhaAtiva], que também marca "o item atual" — aquele que o ▶
 * repete e que sobrevive de propósito ao Parar. Um item selecionado depois de um
 * Parar continua sendo o atual e **não** está no ar; dizer "No ar" sobre ele
 * seria mentir na única linha da tela que existe para não mentir.
 *
 * As duas camadas respondem separadas porque elas coexistem: um louvor de fundo
 * sob um versículo põe DUAS linhas no ar ao mesmo tempo.
 */
function linhaNoAr(id) {
  if (!id) return false;
  if (visualSobreNaLinha(id)) return true;
  if (midiaNoAr && (id === midiaNoArId || id === midiaNoArOrigem)) return true;
  return !!cueNoArId && id === cueNoArId && cenaDeRoteiroNoAr();
}

/**
 * O SELO "● No ar" na segunda linha da linha — o MESMO desenho da Bíblia
 * (`renderBibleReading`), onde ele é prefixado à referência do versículo
 * central em `--live-strong`.
 *
 * Ele mora no subtítulo, e não numa faixa própria, porque essa linha já existe e
 * já é onde o operador procura o que o item É. Um selo em elemento novo
 * empurraria a altura de toda a lista para dizer algo que só vale em uma linha
 * de cada vez.
 */
/**
 * A FALHA MORA NA LINHA QUE FOI TOCADA (v5.207).
 *
 * Projetar uma cena de roteiro pode não dar: o capítulo não está no aparelho, a
 * mensagem foi apagada, a música saiu do acervo, as mídias do pacote sumiram.
 * As quatro saíam por uma faixa flutuante no TOPO da tela — enquanto o dedo e o
 * olho estavam numa linha do Cronograma, no meio ou no fim da lista. A
 * informação deslocada do alvo de foco é o que o operador pediu para acabar.
 *
 * Aqui ela usa o MESMO lugar e o MESMO desenho do selo "● No ar": um `<span>`
 * prefixado ao subtítulo da própria linha. O subtítulo não é reescrito — o
 * selo é um nó à parte —, então o tipo e a duração continuam legíveis ao lado
 * do motivo, e nenhum dos dois pintores atrapalha o outro.
 *
 * Ela se apaga sozinha: um motivo que ficasse para sempre viraria parte da
 * descrição do item.
 */
const FALHA_ITEM_MS = 6000;
const falhaItem = new Map();
function notaNoItem(id, texto, tipo) {
  if (!id || !texto) return;
  const antes = falhaItem.get(id);
  if (antes && antes.timer) clearTimeout(antes.timer);
  falhaItem.set(id, {
    texto,
    tipo: tipo || 'erro',
    timer: setTimeout(() => { falhaItem.delete(id); marcarNoAr(); }, FALHA_ITEM_MS),
  });
  marcarNoAr();
}
// Açúcar para o caso mais comum, que é o de falha.
function falharNoItem(id, texto) { notaNoItem(id, texto, 'erro'); }

function pintarFalha(sub, id) {
  const antigo = sub.querySelector('.row-nota');
  const f = falhaItem.get(id);
  if (!f) {
    if (antigo && antigo.nextSibling && antigo.nextSibling.nodeType === 3) antigo.nextSibling.remove();
    if (antigo) antigo.remove();
    return;
  }
  if (antigo) {
    antigo.textContent = f.texto;
    antigo.className = 'row-nota row-nota--' + f.tipo;
    return;
  }
  const selo = document.createElement('span');
  selo.className = 'row-nota row-nota--' + f.tipo;
  selo.textContent = f.texto;
  sub.prepend(selo);
  if (sub.textContent.replace(f.texto, '').trim()) selo.after(' · ');
}

function pintarSubNoAr(sub, noAr) {
  const antigo = sub.querySelector('.row-live');
  if (noAr === !!antigo) return;
  if (!noAr) {
    // O separador vai junto com o selo — ele é um nó de texto solto criado ao
    // lado dele, e deixá-lo para trás daria " · Áudio · 3:14".
    if (antigo && antigo.nextSibling && antigo.nextSibling.nodeType === 3) antigo.nextSibling.remove();
    if (antigo) antigo.remove();
    return;
  }
  const selo = document.createElement('span');
  selo.className = 'row-live';
  selo.textContent = '● No ar';
  sub.prepend(selo);
  if (sub.textContent.replace('● No ar', '').trim()) selo.after(' · ');
}

/**
 * Esta linha deve estar realçada?
 *
 * `currentId` continua valendo — ele é "o item atual", o que o ▶ repete — e o
 * que se ACRESCENTA é a cena de roteiro no ar, que pode ser outra: com um louvor
 * de fundo sob um versículo, `currentId` é a música e a cena é o versículo.
 * Marcar só um dos dois é esconder metade do que está no telão.
 */
function linhaAtiva(id) {
  if (!id) return false;
  if (visualSobreNaLinha(id)) return true;
  if (id === currentId) return true;
  // A linha que RESOLVEU um link é a atual enquanto a mídia dela estiver no ar
  // (ver `midiaNoArOrigem`). Sem isto ela alternaria entre "no ar" e nada,
  // porque as duas marcas saem de campos diferentes.
  if (midiaNoAr && id === midiaNoArOrigem) return true;
  return !!cueNoArId && id === cueNoArId && cenaDeRoteiroNoAr();
}

/**
 * Está no ar AGORA? É o que decide entre projetar e retirar.
 *
 * As duas camadas respondem por caminhos diferentes de propósito: a MÍDIA é o
 * `currentId` (ela é a cena), e a CENA DE ROTEIRO é o `cueNoArId` — porque ela
 * convive com uma mídia de fundo, e nesse caso `currentId` é da música. Ver
 * `cueNoArId`: era essa confusão que fazia o segundo toque não funcionar
 * exatamente no caso em que ele mais importa.
 */
function noArAgora(item) {
  if (!item) return false;
  if (visualSobreNaLinha(item.id)) return true;
  if (isCue(item)) return !!cueNoArId && item.id === cueNoArId && cenaDeRoteiroNoAr();
  // A ORIGEM entra aqui pelo mesmo motivo que entra no `linhaNoAr`: sem ela a
  // linha do link ganhava o selo "● No ar" e o segundo toque continuava
  // reprojetando — o realce dizendo uma coisa e o gesto fazendo outra, que é
  // pior que o defeito inteiro.
  if (midiaNoAr && item.id === midiaNoArOrigem) return true;
  return item.id === currentId && midiaNoAr;
}

async function onTap(item) {
  if (selectionMode) { toggleSelect(item.id); return; }
  // O SEGUNDO TOQUE RETIRA — ver `retirarDoAr`.
  if (noArAgora(item)) { await retirarDoAr(item); return; }
  // Cena de roteiro: PROJETA, e não mexe na playlist. Um versículo não é uma
  // fila de reprodução — trocar a playlist por ele apagaria o bloco de louvores
  // que o operador acabou de montar, e o áudio de fundo (que a Camada de Texto
  // deixa tocando de propósito) morreria junto.
  if (isCue(item)) { await send(item.id); return; }
  // Toque direto na biblioteca: define a playlist como este item apenas.
  // ACRESCENTAR à fila (sem substituir) é outra coisa: o `+` dos resultados do
  // acervo (`addSongToPlaylist`) e, para itens da biblioteca, o botão de
  // playlist da barra de seleção (`addSelectedToPlaylist`) — que substituiu o
  // deslize à esquerda na v5.50.
  await replacePlaylistWith(item);
  send(item.id);
}

// Acrescenta os SELECIONADOS à playlist, sem substituir a fila. É o que o
// deslize à esquerda na linha fazia até a v5.50, agora num botão da barra de
// seleção: visível, e para vários itens de uma vez. Sem isto a única coisa que
// um item da biblioteca sabia fazer era SUBSTITUIR a fila (o toque simples) —
// montar uma sequência de culto dependeria de um gesto que a tela não anuncia.
// Favoritar o CONJUNTO. Marca todos quando há algum desmarcado (a intenção de
// quem selecionou cinco itens e toca na estrela é "quero estes cinco nos
// favoritos"); com todos já marcados, o mesmo toque desmarca — é o alternador
// de sempre, aplicado ao conjunto.
async function favoritarSelecionados() {
  const ids = [...selected];
  if (!ids.length) return;
  const marcar = ids.some((id) => !favSet.has(id));
  let mexidos = 0;
  for (const id of ids) {
    if (marcar === favSet.has(id)) continue;
    mexidos++;
    if (marcar) { favSet.add(id); await AVDB.listAdd('favs', id); }
    else { favSet.delete(id); await AVDB.listRemove('favs', id); }
  }
  const tipo = marcar ? tipoLote(mexidos, ids.length) : 'ok';
  responder(selFavEl, tipo, marcar
    ? textoLote(mexidos, ids.length, LISTA_ROTULO.favs)
    : (ids.length === 1 ? 'Removido dos favoritos' : mexidos + ' removidos dos favoritos'));
  await recarregarFavoritos();
  // A barra sai DEPOIS do pulso: `exitSelection` a esconde (`hidden`), e sair
  // na hora arrancaria da tela justamente o botão que está confirmando.
  sairDaSelecaoDepois();
}

// A SELEÇÃO SOBREVIVE AO DESTINO (v5.141).
//
// Até aqui um destino encerrava a seleção: mandar cinco louvores para a playlist
// E para os Favoritos exigia selecioná-los duas vezes, um por um, na mão. É o
// mesmo defeito que a folha de destinos tinha — "só um caminho por vez" —, com
// a diferença de que aqui não é preciso caixa de marcação nenhuma: os destinos
// já são três botões lado a lado, e o único que os separava era a barra sumindo
// no primeiro toque.
//
// A barra continua sendo fechada pelo ✕ (`#selCancel`), pelo botão voltar do
// aparelho e por desmarcar o último item — três saídas que já existiam. O que
// muda é ela não decidir sozinha que o operador terminou.
//
// O redesenho espera o pulso do botão pelo mesmo motivo de sempre: remontar a
// lista agora arrancaria da tela justamente o botão que está confirmando.
function sairDaSelecaoDepois() {
  setTimeout(() => { load(); }, PULSO_MS);
}

// A conta é do LOTE: "3 de 4 adicionados" diz, numa linha, que um deles já
// estava lá — com um aviso por item o operador veria quatro mensagens piscando
// e não leria nenhuma.
async function addSelectedToPlaylist() {
  if (!selected.size) return;
  const total = selected.size;
  // A forma ATÔMICA do `listSet` (a fn roda dentro da MESMA transação que
  // grava — a forma que o db.js manda preferir): o laço anterior pagava duas
  // transações por item (`listHas` + `listAdd`), e a contagem de novos sai da
  // própria fn, sobre a MESMA lista que foi gravada.
  let novos = 0;
  await AVDB.listSet('playlist', (atual) => {
    for (const id of selected) {
      if (atual.includes(id)) continue;
      atual.push(id); novos++;
    }
    return atual;
  });
  responder(selPlaylistEl, tipoLote(novos, total), textoLote(novos, total, LISTA_ROTULO.playlist));
  sairDaSelecaoDepois();
}

// O aviso de uma operação em lote (playlist, favoritos, atalho).
function tipoLote(novos, total) { return novos === total ? 'ok' : 'dup'; }

function textoLote(novos, total, onde) {
  if (novos === total) return total === 1 ? 'Adicionado ' + onde.para : total + ' itens adicionados ' + onde.para;
  if (novos === 0) return total === 1 ? 'Já está ' + onde.em : 'Todos já estavam ' + onde.em;
  return novos + ' de ' + total + ' adicionados ' + onde.para + ' — o resto já estava lá';
}

// (===== ARRASTAR PARA REORDENAR — REMOVIDO NA v5.285 =====
//
// Saiu inteiro a pedido do operador: `attachHandle`, `measureDrag`,
// `dropIndex`, `showDropLine`/`hideDropLine`, `endDrag`, `dragGeom` e o
// `reorder` por índice de destino. Quem reordena agora é `botoesDeOrdem` →
// `moverNaLista`, um par ↑↓ dentro da gaveta do `⋮`.
//
// O que a remoção leva junto, e vale saber que sumiu: a linha-guia absoluta
// (com o bloco contendor garantido pelo JS, v5.272), a medição ÚNICA no
// `pointerdown` com re-medição na rolagem, e o `data-fixa` das pastas do
// aparelho — que existia só para elas não contarem como posição no arrasto.)

// ===== seleção múltipla =====
function enterSelection(id) {
  selectionMode = true;
  selected.clear();
  selected.add(id);
  renderLibrary(); renderSelbar();
}
function toggleSelect(id) {
  if (selected.has(id)) selected.delete(id); else selected.add(id);
  if (selected.size === 0) exitSelection();
  else { renderLibrary(); renderSelbar(); }
}
function exitSelection() {
  selectionMode = false; selected.clear();
  renderLibrary(); renderSelbar();
}
async function deleteSelected() {
  // O ✓ "já está aqui" da busca do YouTube vive num Map em memória
  // (`ytEstado`) e nunca é recalculado enquanto a entrada existir — excluir a
  // mídia sem invalidá-lo deixava a busca prometendo, pela sessão inteira, um
  // download que não existe mais. A marca cai ANTES da remoção porque depois
  // do gc o registro pode já não existir para dizer QUAL era o vídeo; se ele
  // sobreviver em outra lista, `marcarYtProntos` remarca a partir do IDB.
  for (const id of selected) {
    const it = libItems.find((m) => m.id === id) || await AVDB.getMedia(id);
    if (it && it.youtubeId) setYtEstado(it.youtubeId, null);
  }
  // (Os DOIS ramos de `'folders'` saíram na v5.294, com a gaveta: um apagava o
  // ARQUIVO FÍSICO dos selecionados dentro de uma pasta do aparelho, o outro
  // desmarcava favoritos na raiz dela. Nenhum dos dois era alcançável — a
  // seleção múltipla só existe na lista principal desde a v5.290. Quem apaga
  // arquivos de uma pasta hoje é o "Excluir pasta e arquivos sincronizados" da
  // linha da própria pasta.)
  {
    for (const id of selected) { await AVDB.listRemove('imports', id); await soltarAvulso(id); }
  }
  exitSelection(); load();
}

// A PRATELEIRA INVISÍVEL não sobrevive a uma exclusão explícita.
//
// `avulsos` é a única lista que o operador NÃO vê: ela existe para "Tocar
// agora" não sujar o Cronograma e para não rebaixar o mesmo vídeo duas vezes no
// mesmo culto (ver `fixarAvulso`). Mas ela conta para o `isReferenced` — então,
// removendo só da aba ATIVA, excluir um vídeo do Cronograma deixava a
// prateleira segurando o registro: blob no aparelho, invisível em toda tela, e
// o resultado do YouTube ainda marcando "já está aqui" sem lugar onde removê-lo.
//
// REGRA: excluir é uma DECLARAÇÃO DE INTENÇÃO, e vale para os detentores que o
// operador não pode enxergar. A prateleira é cache, não biblioteca.
//
// A ÚNICA exceção é o que está EM CENA: ali ela está fazendo o trabalho para o
// qual existe, e soltá-la apagaria o blob de baixo de uma projeção — o vídeo
// seguiria tocando (o Display tem os bytes), mas uma queda do dongle o traria de
// volta e o `getMedia` não acharia nada. O rodízio de `fixarAvulso` a solta
// quando a cena mudar.
//
// `listRemove` decide sozinho se o blob morre: esta função nunca apaga nada —
// ela só deixa de esconder um detentor.
async function soltarAvulso(id) {
  if (!id || id === currentId) return;
  await AVDB.listRemove('avulsos', id);
}
async function renameSelected() {
  if (selected.size !== 1) return;
  const id = [...selected][0];
  const item = libItems.find((m) => m.id === id);
  const name = await appPrompt({ title: 'Renomear', message: 'Novo nome:', value: item ? item.name : '', okText: 'Renomear' });
  if (name && name.trim()) await AVDB.renameMedia(id, name.trim());
  exitSelection(); load();
}

// ===== pastas =====
//
// (`garantirGaveta`, `openFavorites`, `closeFavorites`, `favVoltarPara` e o
// `hostSelbar` de duas casas saíram na v5.294, com a gaveta `#favPopup` — ver o
// bloco no topo do arquivo. A pasta do aparelho abre INLINE dentro da seção de
// Favoritos da Biblioteca desde a v5.290, e era ela a única tela que a gaveta
// ainda servia.)

// A barra de seleção múltipla vive no RODAPÉ DA LISTA, fora do `<ul>` rolável e
// por isso sempre à vista. Ela MUDA de casa com o `<input type="file">` que
// ocupa a mesma fatia (ver `renderListFoot`): um nó só, movido, em vez de dois
// que divergem.
//
// A casa dela era a caixa de controles, no lugar da faixa de ABAS (v5.107 tirou
// de lá). As ações são da LISTA; trocar a navegação de lugar para mostrá-las
// mexe no que não é da seleção, e some com as abas justamente quando o operador
// pode querer sair da tela.
//
// (Até a v5.292 esta função escolhia entre DUAS casas — o rodapé e a folha da
// gaveta de Favoritos —, porque selecionar itens dentro de uma pasta deixaria a
// barra invisível atrás dela. A gaveta saiu; sobrou uma casa, e a função ficou
// para o `<input type="file">` não voltar a disputar a fatia com a `#selbar`.)
function hostSelbar() {
  if (selbarEl.parentElement !== listFootEl) listFootEl.appendChild(selbarEl);
}

function navigateBack() {
  if (bibliaAberta()) {
    if (bibleScreen === 'reading') gotoBibleScreen('chapters');
    else if (bibleScreen === 'chapters') gotoBibleScreen('books');
    return;
  }
  // A GAVETA SÓ EXISTE COMO TELA DE DENTRO (v5.238): ela deixou de ter porta
  // própria — os favoritos são a primeira seção da Biblioteca —, e o único jeito
  // de chegar aqui é entrando numa pasta. Então o voltar sempre FECHA, e a tela
  // de trás é a Biblioteca, com a seção de onde o operador veio. Subir para uma
  // "raiz" que ninguém mais alcança seria devolvê-lo a uma tela sem porta.
  rememberScroll();
  // A seleção pertence à lista que está sendo deixada — mesmo motivo do
  // `exitSelection` que `switchTab` faz ao trocar de aba.
  if (selectionMode) exitSelection();
  load({ restaurarScroll: true });
}

// ===== A MIGRAÇÃO DOS ATALHOS DE PASTA (v5.254) =====
//
// O operador pediu para o app não ter mais atalhos de pasta — só as pastas
// sincronizadas do armazenamento do aparelho. Apagar o recurso e ir embora
// seria PERDER MÍDIA: um item cujo único detentor era um atalho vira um
// registro que nenhuma lista aponta, e o coletor de lixo (que existe
// justamente para isso) o apagaria na varredura seguinte. Um vídeo grande
// sumiria do app e do disco sem nada na tela que o explicasse.
//
// Então o conteúdo dos atalhos SOBE para os favoritos, na ordem em que estava,
// e só depois os atalhos são derrubados. A ordem das duas metades é a garantia:
// `folderDrop` apaga a mídia que ficou sem detentor, e depois do `listAdd` ela
// tem um — a própria lista `favs`.
//
// Roda uma vez por aparelho, e é idempotente por construção: sem `folders` no
// banco, ela devolve na primeira linha. Fire-and-forget na abertura, ANTES do
// `load()` — a lista que o operador vê já é a migrada.
async function migrarPastasParaFavoritos() {
  let pastas = [];
  try { pastas = (await AVDB.getState('folders')) || []; } catch (_) { return; }
  if (!Array.isArray(pastas) || !pastas.length) return;
  for (const p of pastas) {
    if (!p || !p.id) continue;
    let ids = [];
    try { ids = await AVDB.listIds('folder_' + p.id); } catch (_) { continue; }
    for (const id of ids) {
      // `listHas` antes do `listAdd`: um item favoritado E guardado num atalho
      // é o caso comum, e duplicá-lo na lista deixaria duas linhas iguais.
      try { if (!(await AVDB.listHas('favs', id))) await AVDB.listAdd('favs', id); } catch (_) {}
    }
  }
  // Só agora — e pelo `folderDrop`, que tira o atalho do índice, apaga a lista
  // dele e coleta na MESMA transação o que de fato ficou sem dono.
  for (const p of pastas) {
    if (!p || !p.id) continue;
    try { await AVDB.folderDrop(p.id); } catch (_) {}
  }
}

// ===== pastas sincronizadas (OPFS) =====

// A pasta do dispositivo é copiada para o Origin Private File System em uma
// única operação com permissão (showDirectoryPicker). Depois disso o acesso é
// permanente: nenhuma permissão é pedida para listar, buscar ou reproduzir —
// o catálogo (metadados + thumbnails) fica no IDB e os bytes no OPFS.

function uid() {
  return crypto.randomUUID ? crypto.randomUUID() : String(Date.now() + Math.random());
}

// (`refreshOpfsFolderCount` SAIU: zero chamadores. A contagem de uma pasta é
// mantida por quem a percorre — `syncDeviceFolder` a escreve junto com o
// catálogo, no MESMO ponto em que grava a pasta —, e uma segunda função que
// recontasse por fora seria uma segunda fonte de verdade sobre o mesmo número.)

// Abre uma pasta do dispositivo e devolve uma FONTE uniforme, para que o
// corpo da sincronização (abaixo) seja um só nos dois contextos:
//
//   { name, uri?, handle?, entries: [{ name, stat(), read() }] }
//
// - No NAVEGADOR: File System Access API (showDirectoryPicker + handles).
// - No APP NATIVO: Storage Access Framework via AVNative.pickFolder/listFolder.
//   A File System Access API **não existe no Android** — era por isso que a
//   sincronização de pastas, no PWA, sempre caía no aviso "navegador não
//   suporta seleção de pastas" em qualquer celular. Aqui ela funciona.
//
// `stat()` devolve { size, mtime } SEM ler os bytes: é o que permite pular
// arquivos inalterados de graça (no SAF os metadados já vêm na listagem; no
// navegador o File é obtido uma vez e reaproveitado por `read()`).
// `botao` é quem foi tocado — o único alvo de foco quando ainda não há linha
// de pasta em que responder. Ver `syncDeviceFolder`.
async function openFolderSource(existing, botao) {
  if (window.__NATIVE__) {
    let picked = existing && existing.uri ? { uri: existing.uri, name: existing.name } : null;
    let list = picked ? await AVNative.listFolder(picked.uri) : null;
    // Sem URI salvo, ou permissão revogada / pasta movida (listagem vazia
    // onde antes havia arquivos): pede a pasta de novo.
    if (!picked || (list.length === 0 && existing && existing.count > 0)) {
      picked = await AVNative.pickFolder();
      if (!picked) return null; // operador cancelou
      list = await AVNative.listFolder(picked.uri);
    }
    return {
      name: picked.name,
      uri: picked.uri,
      entries: list.map((f) => ({
        name: f.name,
        stat: async () => ({ size: f.size, mtime: f.mtime }),
        read: async () => {
          // A ponte entrega URL servível, não bytes: isto é um fetch local
          // em streaming, o mesmo padrão já usado com o OPFS.
          const res = await fetch(f.url);
          if (!res.ok) throw new Error('leitura falhou');
          return await res.blob();
        },
      })),
    };
  }

  // NAVEGADOR SEM A API — caso que não existe no app (lá o seletor é o SAF) e
  // que no navegador é permanente. O pulso vermelho no botão que foi tocado diz
  // "não vai dar" sem uma camada nova para uma frase que ninguém pode resolver.
  if (!('showDirectoryPicker' in window)) { pulsar(botao, 'erro'); return null; }

  // Re-sync: tenta reutilizar o handle salvo (browsers que persistem a
  // permissão nem mostram prompt); senão cai no picker.
  let handle = existing && existing.handle;
  if (handle) {
    try {
      let perm = await handle.queryPermission({ mode: 'read' });
      if (perm !== 'granted') perm = await handle.requestPermission({ mode: 'read' });
      if (perm !== 'granted') handle = null;
    } catch (_) { handle = null; }
  }
  if (!handle) {
    try { handle = await window.showDirectoryPicker({ mode: 'read' }); }
    catch (_) { return null; } // usuário cancelou
  }

  const entries = [];
  for await (const [name, entry] of handle.entries()) {
    if (entry.kind !== 'file') continue;
    let cached = null;
    const file = async () => (cached || (cached = await entry.getFile()));
    entries.push({
      name,
      stat: async () => { const f = await file(); return { size: f.size, mtime: f.lastModified }; },
      read: file,
    });
  }
  return { name: handle.name, handle, entries };
}

// Sincroniza (ou re-sincroniza) uma pasta do dispositivo para o OPFS.
// `existing` = registro de opfsFolders para re-sync; undefined para nova pasta.
// A cada quantos arquivos o índice de pastas é regravado. Ver `syncDeviceFolder`.
const CHECKPOINT_PASTA = 25;

// `botao` = quem foi tocado (a linha da pasta ou "adicionar"). Ele existe para
// as duas recusas abaixo terem onde responder: nelas ainda não há pasta, logo
// não há linha — e o único alvo de foco é o botão que o dedo acabou de soltar.
async function syncDeviceFolder(existing, botao) {
  // NAVEGADOR SEM OPFS: caso que não existe no app (o WebView tem OPFS) e que
  // no navegador é permanente. O pulso vermelho no próprio botão diz "não vai
  // dar" sem inventar uma camada para uma frase que ninguém pode resolver.
  if (!AVDB.opfsSupported()) { pulsar(botao, 'erro'); return; }
  // JÁ HÁ UMA SINCRONIZAÇÃO CORRENDO, e o motivo está VISÍVEL na mesma tela: a
  // pasta que está sincronizando mostra o progresso no contador dela (ver
  // `statusPasta`). Repetir isso numa faixa seria dizer duas vezes o que já
  // está escrito a duas linhas dali.
  if (syncBusy) { pulsar(botao, 'dup'); return; }

  const source = await openFolderSource(existing, botao);
  if (!source) return;

  syncBusy = true;
  // Copiar uma pasta inteira do dispositivo para o OPFS é longo (vídeos
  // grandes); mesma proteção contra o congelamento ao minimizar.
  bgWorkBegin();
  let folderNotifId = 0; // fora do try: o finally precisa encerrar a tarefa
  // E `folder` TAMBÉM fora: é ele que diz em qual LINHA a falha vai ser escrita
  // (ver `statusPasta`), e um `let` dentro do `try` não existe para o `catch` —
  // a mensagem de erro morreria com um ReferenceError em cima da falha que ela
  // estava tentando relatar.
  let folder = null;
  try {
    // Pede armazenamento persistente para o browser não descartar os arquivos.
    if (navigator.storage && navigator.storage.persist) navigator.storage.persist().catch(() => {});

    folder = existing || opfsFolders.find((f) => f.name === source.name);
    if (!folder) {
      folder = { id: uid(), name: source.name, count: 0, syncedAt: 0 };
      opfsFolders.push(folder);
    }
    // `handle` (web) e `uri` (nativo) cumprem o mesmo papel: acelerar o
    // re-sync sem pedir a pasta de novo.
    if (source.handle) folder.handle = source.handle;
    if (source.uri) folder.uri = source.uri;
    // A PASTA É PERSISTIDA ANTES DO PRIMEIRO ARQUIVO, e isto é uma correção.
    //
    // Cada arquivo já era gravado de imediato (OPFS + um registro na store
    // `files`, com `folder: folder.id`), mas o ÍNDICE DE PASTAS só ia para o
    // banco depois do laço. Uma pasta de 600 vídeos interrompida na metade
    // deixava 300 arquivos escritos e **nenhuma pasta que os apontasse**: eles
    // ficavam órfãos, invisíveis na tela, ocupando gigabytes — e o coletor de
    // lixo, que existe justamente para recolher registro sem dono, os apagava.
    // Do lado de fora isso se lê como "não salvou progresso nenhum", que foi
    // exatamente o relato.
    //
    // Gravar aqui custa uma escrita e transforma a interrupção em RETOMADA: o
    // laço abaixo já pula o que está em dia (mesmo tamanho e mesma data), então
    // rodar a sincronização de novo continua de onde parou. O mecanismo de
    // retomada sempre existiu; o que faltava era ele ter o que retomar.
    await AVDB.setState('opfs-folders', opfsFolders);

    const existingRecs = await AVDB.filesByFolder(folder.id);
    const bySrcName = new Map(existingRecs.map((r) => [r.srcName, r]));

    const entries = [];
    for (const entry of source.entries) {
      const type = guessMediaType(entry.name);
      if (AVDB.kindFromType(type) === 'other') continue;
      entries.push([entry, type]);
    }

    let done = 0, added = 0;
    // O QUE FALHOU POR ARQUIVO TEM DE CHEGAR AO DESFECHO. Os três `catch` do
    // laço seguem (um arquivo ilegível não pode derrubar a pasta inteira), mas
    // seguir CALADO fazia o pior caso mentir: com o armazenamento cheio no
    // arquivo 1, os 600 `opfsWriteFile` falham, o `catch (e)` externo nunca é
    // alcançado, `added` fica em 0 — e a linha da pasta anuncia "em dia" sobre
    // uma pasta em que nada foi copiado.
    //
    // A CAUSA é a do PRIMEIRO, não a do último: é ela que nomeia o que começou
    // a dar errado (`QuotaExceededError`), e as que vêm depois são consequência.
    let falhou = 0, causa = '';
    const falha = (err) => {
      falhou++;
      if (!causa) causa = (err && err.name) || 'desconhecido';
    };
    folderNotifId = bgTaskStart('Pasta · ' + folder.name, entries.length);
    for (const [entry, type] of entries) {
      done++;
      // O PROGRESSO NO CONTADOR DA PRÓPRIA PASTA (v5.207): é o número que esta
      // cópia está mudando, na linha em que o operador tocou. Sem prazo — quem
      // o substitui é o desfecho, no fim do laço. (A notificação do sistema
      // continua sendo o canal de quando o app está minimizado.)
      statusPasta(folder.id, done + '/' + entries.length, 0);
      bgTaskStep(folderNotifId, done);
      const name = entry.name;
      bgItemOnly(folderNotifId, name);
      let st;
      try { st = await entry.stat(); } catch (err) { falha(err); continue; }
      const prev = bySrcName.get(name);
      // Já sincronizado e inalterado (mesmo tamanho e data) → pula.
      if (prev && prev.size === st.size && prev.mtime === st.mtime) continue;
      let file;
      try { file = await entry.read(); } catch (err) { falha(err); continue; }
      const kind = AVDB.kindFromType(type);
      const path = 'folders/' + folder.id + '/' + name;
      try { await AVDB.opfsWriteFile(path, file); } catch (err) { falha(err); continue; }
      const thumb = await makeThumb(file, kind);
      await AVDB.fileAdd({
        id: prev ? prev.id : uid(),
        folder: folder.id,
        opfsPath: path,
        srcName: name,
        name: name.replace(/\.[^.]+$/, ''),
        type, kind,
        size: st.size,
        mtime: st.mtime,
        thumb,
        blob: null, url: null,
        addedAt: prev ? prev.addedAt : Date.now(),
      });
      added++;
      // E O PONTO DE CONTROLE, a cada CHECKPOINT_PASTA arquivos: sem ele, a
      // contagem da pasta ficaria em zero até o fim e uma interrupção deixaria
      // a linha dizendo "0 arquivos" sobre uma pasta com centenas dentro. É
      // barato (uma escrita a cada 25) e é o que faz a tela contar a verdade
      // enquanto a cópia anda.
      if (added % CHECKPOINT_PASTA === 0) {
        folder.count = (await AVDB.filesByFolder(folder.id)).length;
        folder.syncedAt = Date.now();
        try { await AVDB.setState('opfs-folders', opfsFolders); } catch (_) { /* segue */ }
      }
    }

    folder.count = (await AVDB.filesByFolder(folder.id)).length;
    folder.syncedAt = Date.now();
    await AVDB.setState('opfs-folders', opfsFolders);
    // O desfecho é o que a faixa existe para dizer: "já em dia" é a resposta
    // que evita re-sincronizar à toa, e ela precisa se distinguir de "entrou".
    // O desfecho vai para o CONTADOR da própria pasta: "já em dia" é a
    // resposta que evita re-sincronizar à toa, e ela precisa se distinguir de
    // "entrou". Some sozinho e o número volta.
    //
    // FALHA VENCE OS DOIS, e fica na tela o mesmo tempo que o `catch` externo
    // reserva (9 s): é ela que o operador precisa LER. `+N` sobre uma pasta em
    // que 300 arquivos não entraram descreve o culto pela metade certa.
    statusPasta(folder.id,
      falhou ? falhou + ' falharam: ' + causa : (added > 0 ? '+' + added : 'em dia'),
      falhou ? 9000 : 4000);
  } catch (e) {
    // A CAUSA VAI JUNTO. "Erro" sozinho não distingue disco cheio de permissão
    // revogada de arquivo ilegível, e as três têm saídas diferentes — a
    // primeira é a provável numa pasta de 600 vídeos. Fica mais tempo na tela
    // que o desfecho bom, porque é ele que o operador precisa ler.
    if (folder) statusPasta(folder.id, 'erro: ' + ((e && e.name) || 'desconhecido'), 9000);
  } finally {
    syncBusy = false;
    bgTaskEnd(folderNotifId);
    bgWorkEnd();
  }
  load();
}

// (`openOpfsFolder` saiu na v5.290: a pasta do aparelho passou a abrir INLINE,
// no corpo da própria linha, como um álbum — ver `renderFolderList`. Ele era o
// ÚNICO caminho para a gaveta `#favPopup`, e a v5.294 a removeu por inteiro —
// a lápide está no topo deste arquivo, junto da lista do que saiu com ela.)

// Remove uma leva de registros do catálogo OPFS (store "files") e limpa as
// referências que tenham sobrado nas listas. Usado ao excluir uma pasta OPFS
// ou o Hinário inteiro — os bytes já são apagados em bloco por opfsDeleteDir,
// então aqui não é preciso opfsDeleteFile por registro.
async function purgeCatalogRecords(recs) {
  for (const r of recs) {
    await AVDB.fileDelete(r.id);
    // `favs` entra junto: um arquivo de pasta favoritado e depois excluído
    // deixaria uma estrela apontando para um registro que não existe mais — a
    // linha some da gaveta pelo `filter(Boolean)` do `listItems`, mas o id fica
    // na lista, contando como favorito para sempre.
    for (const l of ['imports', 'playlist', 'avulsos', 'favs']) await AVDB.listRemove(l, r.id);
  }
}

async function deleteOpfsFolder(f) {
  if (!(await appConfirm({ title: 'Excluir pasta', message: 'Excluir a pasta "' + f.name + '" e todos os arquivos sincronizados?', okText: 'Excluir', perigo: true }))) return;
  const recs = await AVDB.filesByFolder(f.id);
  await purgeCatalogRecords(recs);
  await AVDB.opfsDeleteDir('folders/' + f.id);
  opfsFolders = opfsFolders.filter((x) => x.id !== f.id);
  await AVDB.setState('opfs-folders', opfsFolders);
  load();
}

// Fonte única extensão→MIME. Usada por guessMediaType (arquivos OPFS) e, via
// AVDB.kindFromType, por detectUrlKind (URLs) — antes as duas mantinham listas
// de extensões separadas que podiam divergir.
const MEDIA_MIME = {
  jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', gif: 'image/gif',
  webp: 'image/webp', svg: 'image/svg+xml', avif: 'image/avif', bmp: 'image/bmp',
  mp4: 'video/mp4', webm: 'video/webm', ogv: 'video/ogg', mov: 'video/mp4',
  m4v: 'video/mp4', mkv: 'video/x-matroska',
  mp3: 'audio/mpeg', wav: 'audio/wav', ogg: 'audio/ogg', aac: 'audio/aac',
  flac: 'audio/flac', m4a: 'audio/mp4', opus: 'audio/opus',
  // A apresentação entra como PDF e vira IMAGENS no aparelho (ver
  // `deckImportar`). Os formatos de origem — .pptx, .odp — ficam de fora de
  // propósito: não existe no Android quem os desenhe, e aceitar o arquivo para
  // depois não conseguir projetá-lo é pior do que dizer na hora o que fazer.
  pdf: 'application/pdf',
};
function guessMediaType(filename) {
  const ext = (filename.split('.').pop() || '').toLowerCase();
  return MEDIA_MIME[ext] || 'application/octet-stream';
}

// ===== Coleções de mídia (LouvorJA) — sincronização e download =====
// Carrega em memória o estado de todas as coleções (índices por coll.id) + o
// catálogo de álbuns, aplicando a migração do estado legado 'hymnal2022' →
// 'coll:hymnal-2022' (mesma pasta OPFS 'hymnal-2022', então os downloads já
// feitos continuam válidos). Chamado uma vez no init, antes do primeiro load().
async function loadCollections() {
  const legacy = await AVDB.getState('hymnal2022');
  const has2022 = await AVDB.getState('coll:' + HYMNAL_2022_ID);
  if (legacy && !has2022) await AVDB.setState('coll:' + HYMNAL_2022_ID, legacy);

  // Migração: até a v4.90 o catálogo era um ARRAY achatado [{id_album,name}].
  // Um array antigo é aceito como o índice de álbuns, sem categorias — a
  // próxima `fetchAlbumCatalog` (roda ao abrir o app) traz a hierarquia.
  const savedCatalog = await AVDB.getState('albumCatalog');
  albumCatalog = Array.isArray(savedCatalog)
    ? { categories: [], albums: savedCatalog }
    : (savedCatalog && Array.isArray(savedCatalog.albums) ? savedCatalog : { categories: [], albums: [] });
  const cols = allCollections();
  const states = await Promise.all(cols.map((c) => AVDB.getState('coll:' + c.id)));
  collState = {};
  cols.forEach((c, i) => { collState[c.id] = states[i] || { indexSyncedAt: 0, songs: [] }; });
  await carregarPesos();
  await loadLyricStore();
}

// Descobre os álbuns disponíveis no banco (pt_categories) e persiste a
// hierarquia categoria → álbum (com subtítulo, cor e ordem) — alimenta os
// cards de álbum da aba Álbuns (um por álbum), visíveis offline. Álbuns cujo
// nome parece de hinário são pulados: já têm card dedicado (evita duplicar).
// Lança em falha (sem rede/resposta inválida).
async function fetchAlbumCatalog() {
  const cats = await Louvorja.fetchList(Louvorja.CATEGORIES_FILE);
  if (!Array.isArray(cats)) throw new Error('Resposta inválida (categorias)');
  const seen = new Map();
  const categories = [];
  for (const cat of cats) {
    if (!cat || cat.id_category == null) continue;
    const catAlbums = [];
    for (const a of (Array.isArray(cat.albums) ? cat.albums : [])) {
      if (!a || a.id_album == null) continue;
      const name = a.name || ('Álbum ' + a.id_album);
      // subtitle/order vêm do PIVÔ (variam por categoria) — ficam na entrada
      // da categoria; name/color são do álbum e vão pro índice deduplicado.
      catAlbums.push({
        id_album: a.id_album,
        subtitle: a.subtitle || '',
        order: Number(a.order) || 0,
      });
      if (!seen.has(a.id_album)) seen.set(a.id_album, { id_album: a.id_album, name, color: a.color || null });
    }
    catAlbums.sort((x, y) => x.order - y.order);
    categories.push({
      id_category: cat.id_category,
      name: cat.name || 'Sem categoria',
      order: Number(cat.order) || 0,
      albums: catAlbums,
    });
  }
  categories.sort((x, y) => x.order - y.order);
  albumCatalog = { categories, albums: Array.from(seen.values()) };
  await AVDB.setState('albumCatalog', albumCatalog);
  // Garante entrada em collState pros álbuns novos (índice vazio até sincronizar).
  for (const coll of allCollections()) {
    if (!collState[coll.id]) collState[coll.id] = { indexSyncedAt: 0, songs: [] };
  }
  refreshCollectionsIfVisible();
}

// Busca o índice (metadados leves) de UMA coleção e atualiza collState[coll.id],
// preservando fileIdFull/fileIdPlayback já conhecidos de cada música. Para
// hinários, o arquivo de lista (coll.source) já é o índice; para álbuns, o
// índice vem de album_{id}.musics. Lança em caso de falha (sem rede/resposta
// inválida); quem chama decide se avisa o operador ou ignora silenciosamente.
/**
 * O ÍNDICE DE UMA SÉRIE — as playlists mensais do canal viram faixas do álbum.
 *
 * Duas etapas, e a segunda é sequencial de propósito: são ~12 playlists de 4-5
 * itens, e disparar doze extrações do YouTube em paralelo é justamente o que o
 * `NET_CONCURRENCY` existe para não fazer — aqui cada chamada é uma EXTRAÇÃO
 * (segundos), não um GET.
 *
 * **A mutação é IN-PLACE**, pelo mesmo motivo do índice do LouvorJA: o
 * `syncCollection` tira um snapshot do array e grava `fileIdFull` nos objetos
 * DELE conforme baixa. Recriar os objetos deixaria o snapshot apontando para
 * órfãos — os bytes iam para o OPFS e os ids eram descartados no `setState`
 * seguinte, com o item aparecendo como não baixado e sendo rebaixado.
 *
 * Falha com EXCEÇÃO, e não com lista vazia: quem chama (`syncCollection`) já
 * trata isso como "sem internet — falha ao atualizar" e PRESERVA o índice
 * anterior. Devolver zero itens apagaria da tela a série inteira que o operador
 * já tem baixada, por uma oscilação de rede.
 */

/**
 * O item da REGRA vira a faixa que o `collState` guarda.
 *
 * Ela é uma função nomeada, e não um `map` anônimo lá dentro, por uma razão só:
 * é o CÓDIGO dela que entra na assinatura do índice (ver `AVSerie.impressao`).
 * Guardar um campo novo aqui obsoleta todo índice já escrito, e a única forma
 * de isso não virar o defeito mudo da v5.233 é a assinatura enxergar esta
 * função. Um `map` anônimo não tem nome para passar.
 *
 * **A mutação é IN-PLACE** (recebe `s` e devolve `s`): ver o KDoc acima.
 */
function serieFaixaDoItem(s, it) {
  s.name = AVSerie.nomeDoItem(it);
  s.ytUrl = it.url;
  // A DATA DO EPISÓDIO, guardada no índice (v5.256). Ela já foi lida do título
  // aqui em cima; o que muda é que agora ela SOBREVIVE — e sobrevive por um
  // motivo só: a lista mostra o episódio três dias antes do sábado dele (a
  // quarta-feira em que o roteiro é montado), e nesses três dias o vídeo pode
  // ainda não estar público. Quando o download falha ali, quem explica é
  // `serieComoYoutube`, e sem a data no registro não haveria como saber que
  // aquela falha tem essa causa. `null` quando o título não declarou data — e
  // aí não há nada a afirmar sobre ele.
  s.serieData = it.dia ? { dia: it.dia, mes: it.mes } : null;
  // `duration` como STRING "M:SS", que é a forma do LouvorJA — assim o
  // `parseTimeToSeconds` e toda a conta de peso do álbum (`medirColecao`,
  // `fracaoPeso`, a estimativa antes de baixar) valem sem uma linha nova.
  s.duration = fmtDur(it.seconds);
  // A MINIATURA (v5.236). O extrator já a entrega em toda listagem de playlist
  // e ela era descartada aqui — e é ela que responde, para um VÍDEO, a mesma
  // pergunta que a letra responde para um hino: "é este mesmo?". É uma URL
  // remota (a mesma forma que o resultado da busca do YouTube já desenha em
  // `thumbEl`), então ela vale como ilustração e nunca como dado: sem internet
  // a imagem não carrega, e o detalhe do item continua inteiro sem ela.
  s.thumb = it.thumb || '';
  // O TÍTULO CRU E O CANAL (v1.5.21) — os dois dados que a regra tinha na mão e
  // jogava fora, e que a gaveta de detalhe existe para mostrar.
  //
  // `s.name` é o RÓTULO ("15/Ago · Quando o evangelho sussurra"): a data na
  // frente porque é por ela que se procura, e o título já podado. No modo
  // `TITULO_SERIE` (o Informativo) ele nem chega a conter o nome do episódio —
  // o que fica é o rótulo da série mais a data. O CRU é a outra pergunta,
  // *"é este mesmo?"*, e ela é a razão de o detalhe existir num vídeo.
  //
  // Guardados no ÍNDICE e não pedidos na hora de abrir a gaveta: quem os tem é
  // a extração da playlist, que custa rede, e a gaveta abre no sábado de manhã
  // no Wi-Fi da igreja. Persistir é o que faz o card valer OFFLINE.
  s.nomeOriginal = String(it.nomeOriginal || '').trim();
  s.canal = String(it.canal || '').trim();
  // E os SEGUNDOS CRUS ao lado da string formatada. `s.duration` continua sendo
  // o "M:SS" que toda conta de peso do álbum lê; este é o número, e ele existe
  // por um consumidor só: `serieComoYoutube`, que o repassa ao registro quando
  // o episódio é guardado como LINK (ali não há blob de onde medir nada).
  s.seconds = it.seconds || 0;
  // Um vídeo não tem Playback. Sem isto, `songVariantsNeeded` pediria uma
  // segunda variante que nunca vai existir e o álbum nunca ficaria completo.
  s.has_instrumental_music = false;
  s._norm = normalizeForSearch(s.name);
  return s;
}

// ===== O DIÁRIO DA VARREDURA DE UMA SÉRIE =====
//
// A regra decide a partir de NOMES que um canal muda sem avisar, e os dois
// modos de errar são silenciosos: playlist recusada some da Biblioteca sem erro
// no console, vídeo aceito sem data entra fora de ordem. O aparelho sabia as
// duas coisas ao decidir e as jogava fora — quem opera vê o RESULTADO e nunca o
// CAMINHO, então "falta julho" e "julho veio com outro nome" chegam iguais.
//
//  - Guarda o VEREDITO, nunca uma segunda opinião: os motivos saem de
//    `AVSerie.avaliarPlaylist`/`avaliarVideo`, as MESMAS funções que decidem.
//    Um log que discorda do aparelho é pior que nenhum — ele é lido a
//    distância, por quem não tem como conferir.
//  - Sobrevive ao fechamento do app (`state`, IndexedDB): a varredura acontece
//    na abertura e o Registro é aberto quando o operador se lembra.
//  - DUAS METADES com datas próprias: a aba do canal é lida em toda passada, as
//    playlists não (a assinatura pula as extrações). Um carimbo só faria o
//    Registro anunciar como "de agora" uma lista de três dias atrás.
const SERIE_DIARIO_KEY = 'serieDiag:';

async function serieDiarioLer(id) {
  try { return (await AVDB.getState(SERIE_DIARIO_KEY + id)) || null; } catch (_) { return null; }
}
// Grava por MESCLA: escrever só a metade do canal preserva a metade dos vídeos
// da última varredura completa, que é exatamente o que o bloco precisa dizer
// quando a assinatura pulou a extração.
//
// E A MESCLA É UMA TRANSAÇÃO SÓ (`AVDB.updateState`), nunca `getState` +
// `setState`. DUAS varreduras da mesma série correm juntas com facilidade — a
// abertura dispara `autoRefreshCollections()` sem `await`, e "Atualizar a
// lista" é um toque por cima disso —, e com duas transações a que leu primeiro
// grava por último e apaga a metade da outra. O que some é a metade dos
// vídeos: sem `quandoVideos` o bloco perde as linhas derivadas dela (os nomes
// na ordem, o que o canal anuncia e não veio, os futuros), e o Registro passa a
// responder como se a varredura nunca tivesse acontecido. Um diário que
// discorda do aparelho é o pior artefato que este projeto sabe produzir.
async function serieDiarioGravar(id, campos) {
  try {
    await AVDB.updateState(SERIE_DIARIO_KEY + id, (atual) => Object.assign(atual || {}, campos));
  } catch (_) { /* diagnóstico não pode derrubar a sincronização */ }
}

async function fetchSerieIndex(coll) {
  const serie = coll.serie;
  // O `hoje` DA VARREDURA, lido UMA vez e no TOPO. Duas razões, e as duas já
  // morderam este projeto: a regra do corte (`AVSerie.aindaNaoSaiu`), o diário e
  // o carimbo do índice têm de julgar contra o MESMO dia — duas leituras do
  // relógio separadas por uma extração de rede podem cair em lados diferentes da
  // meia-noite —, e o caminho da economia logo abaixo já o consome, isto é,
  // declará-lo mais adiante seria zona morta temporal (a armadilha das v5.184,
  // v5.193, v5.195 e v5.199).
  const hoje = new Date();
  const doCanal = await AVNative.ytCanalPlaylists(serie.canal);

  // A METADE DO CANAL, gravada ANTES do `throw` logo abaixo — e essa ordem é o
  // ponto. "Nenhuma playlist no canal" é justamente o caso em que o operador
  // mais precisa saber POR QUÊ (o canal renomeou? o ano virou? é a versão em
  // Libras?), e gravar depois deixaria o Registro mudo exatamente ali.
  await serieDiarioGravar(coll.id, {
    canal: serie.canal,
    quandoCanal: Date.now(),
    playlists: (Array.isArray(doCanal) ? doCanal : []).map((pl) => {
      const v = AVSerie.avaliarPlaylist(pl && pl.name, serie);
      return {
        nome: String((pl && pl.name) || ''), count: (pl && pl.count) | 0,
        mes: v.mes, motivo: v.motivo,
      };
    }),
  });

  const playlists = AVSerie.playlistsDaSerie(doCanal, serie);
  if (!playlists.length) throw new Error('Nenhuma playlist de "' + serie.name + '" no canal');

  // A ASSINATURA DAS PLAYLISTS — url:contagem, na ordem. A aba do canal já diz
  // quantos vídeos cada playlist tem: batendo, as ~12 EXTRAÇÕES são puladas
  // (extração é a parte frágil deste caminho). Um episódio novo refaz a
  // assinatura inteira — "tudo ou nada" de propósito, porque casar item a item
  // exigiria guardar de qual playlist veio cada faixa.
  //
  // TUDO O QUE DECIDE O ÍNDICE ENTRA NA ASSINATURA, e este é o modo de falhar
  // que se repete: o índice guarda nomes JÁ FORMADOS e a ordem JÁ decidida, o
  // canal não muda, a contagem bate — e o índice velho fica de pé PARA SEMPRE,
  // no IndexedDB, onde limpar o cache não alcança. Já mordeu três vezes:
  //   · a REGRA (`AVSerie.impressao` — episódio sem data continuou sem data);
  //   · o MONTADOR da faixa (a função logo abaixo, que decide o que o índice
  //     GUARDA — ao passar a guardar a miniatura, todo índice ficou obsoleto);
  //   · o DIA, quando a série esconde o que ainda não saiu (a lista é função do
  //     dia, então a assinatura também tem de ser: senão a economia devolve o
  //     índice de ONTEM, sem o episódio de hoje, carimbado como de hoje).
  const assinatura = AVSerie.impressao(serieFaixaDoItem) + '|'
    + (serie.futuros === AVSerie.FUTUROS_ESCONDER ? serieDiaLocal(hoje) + '|' : '')
    + playlists.map((p) => p.url + ':' + p.count).join('|');
  const guardado = collState[coll.id];
  if (guardado && guardado.serieAssinatura === assinatura && (guardado.songs || []).length) {
    guardado.indexSyncedAt = Date.now();
    // O CARIMBO DO DIÁRIO (v5.249) vale para os dois caminhos: ele é o que diz
    // "este índice já passou por uma versão que registra o que achou". Sem ele
    // no caminho da economia, um aparelho cuja assinatura bate ficaria sendo
    // varrido a cada abertura, para sempre, pela guarda do `autoRefresh`.
    guardado.serieDiarioEm = Date.now();
    guardado.serieDiaEm = serieDiaLocal(hoje);
    await AVDB.setState('coll:' + coll.id, guardado);
    return;
  }

  const itens = [];
  // A METADE DOS VÍDEOS do diário. Ela é acumulada AQUI, e não dentro do
  // `itensDaPlaylist`, porque aquele é a REGRA e devolve os itens que entram —
  // o que o diagnóstico precisa é justamente do que NÃO entrou, mais o título
  // CRU de tudo, que a regra descarta ao formar o rótulo.
  const vistos = [];
  const vazias = [];
  for (const pl of playlists) {
    const info = await AVNative.ytPlaylist(pl.url);
    if (!info || !Array.isArray(info.items)) { vazias.push(pl.name); continue; }
    for (const v of info.items) {
      const ver = AVSerie.avaliarVideo(v, serie, hoje);
      vistos.push({
        nome: String((v && v.name) || ''), motivo: ver.motivo, semData: !ver.motivo && !ver.data,
        // A data viaja com o veredito só para os que ainda não saíram: é ela
        // que ordena o "o mais próximo" da linha do Registro.
        dia: (ver.data && ver.data.dia) || 0, mes: (ver.data && ver.data.mes) || 0,
      });
    }
    itens.push(...AVSerie.itensDaPlaylist(info.items, pl.mes, serie, hoje));
  }
  if (!itens.length) throw new Error('As playlists de "' + serie.name + '" vieram vazias');

  const byId = new Map(collSongs(coll.id).map((s) => [s.id_music, s]));
  const songs = AVSerie.ordenarItens(itens).map((it) => serieFaixaDoItem(
    byId.get(it.id) || { id_music: it.id, fileIdFull: null, fileIdPlayback: null }, it));

  await serieDiarioGravar(coll.id, {
    quandoVideos: Date.now(),
    // O DIA em que o corte foi aplicado, para o Registro dizer contra o quê ele
    // julgou. Um relógio errado no aparelho é uma causa possível de "sumiu o
    // episódio de hoje", e sem esta linha ela seria indistinguível das outras.
    serieDiaEm: serieDiaLocal(hoje),
    // O QUE O CANAL ANUNCIOU, somado das playlists aceitas. Ele é a única
    // referência externa que este caminho tem, e é ele que torna visível o
    // episódio que a extração NÃO trouxe — um vídeo só para membros, um
    // removido, um engasgo do extrator. Sem esta soma, um sábado ausente é
    // indistinguível de um sábado que o canal não publicou.
    anunciados: playlists.reduce((n, p) => n + (p.count | 0), 0),
    vazias,
    total: vistos.length,
    // OS FUTUROS SAEM DA LISTA DE RECUSADOS, e não é cosmético: são dezessete
    // por trimestre e afogariam as recusas de VERDADE, que são uma ou nenhuma.
    // Eles não são um defeito — são o estado normal de um canal que sobe o
    // trimestre e libera aos poucos —, e por isso viram uma linha de contagem.
    recusados: vistos.filter((x) => x.motivo && x.motivo !== AVSerie.MOTIVO_FUTURO),
    futuros: vistos.filter((x) => x.motivo === AVSerie.MOTIVO_FUTURO)
      .map((x) => ({ nome: x.nome, dia: x.dia, mes: x.mes })),
    semData: vistos.filter((x) => x.semData).map((x) => x.nome),
    nomes: songs.map((s) => s.name),
  });

  collState[coll.id] = {
    indexSyncedAt: Date.now(), songs, isHymnal: false, serieAssinatura: assinatura,
    serieDiarioEm: Date.now(),
    // O DIA em que esta lista foi decidida. Ver `indiceVencido`: quando a série
    // esconde o que ainda não saiu, a lista é função do DIA — e um índice de
    // ontem esconde o episódio de hoje, que é o do culto.
    serieDiaEm: serieDiaLocal(hoje),
  };
  await AVDB.setState('coll:' + coll.id, collState[coll.id]);
  refreshCollectionsIfVisible();
  // PELO GUARDA, nunca direto: `renderSearchResults` faz `hymnResultsEl
  // .innerHTML = ''`, e o que ABRE uma linha vive no `li` que ele joga fora
  // (ver `interacaoAbertaNoAcervo`). Um índice que chega enquanto o operador
  // tem uma gaveta aberta fecharia a gaveta e apagaria os destinos marcados —
  // e `renderBuscaQuandoPuder` já confere a Biblioteca aberta, adia e REARMA,
  // então a lista nova entra assim que a gaveta fechar.
  renderBuscaQuandoPuder(false);
}

async function fetchCollectionIndex(coll) {
  if (coll.kind === 'serie') return fetchSerieIndex(coll);
  const raw = await Louvorja.fetchList(coll.source);
  const list = coll.kind === 'album'
    ? (raw && Array.isArray(raw.musics) ? raw.musics : null)
    : (Array.isArray(raw) ? raw : null);
  if (!list) throw new Error('Resposta inválida do servidor (' + coll.source + ')');

  // Um "álbum" cujo registro traz uma categoria começando com `hymnal.` é, na
  // verdade, um hinário — o app-ja redireciona a abertura dele para o módulo
  // do hinário em vez de listar faixas (ver docs/FONTE-DE-DADOS-LOUVORJA.md
  // §5.2). Aqui os dois hinários já têm card fixo, então marcamos para não
  // mostrar um card duplicado. É o critério AUTORITATIVO; até o índice do
  // álbum chegar, `isHymnalAlbum()` se vira com o nome.
  const isHymnal = coll.kind === 'album' && raw && Array.isArray(raw.categories)
    && raw.categories.some((c) => String(c).startsWith('hymnal.'));

  const byId = new Map(collSongs(coll.id).map((s) => [s.id_music, s]));
  // MUTAÇÃO IN-PLACE, não objetos novos: `syncCollection` tira um snapshot do
  // array e grava `fileIdFull`/`fileIdPlayback` nos objetos DELE conforme baixa.
  // Esta atualização de índice roda a cada retomada do app — ou seja, no meio
  // de uma sincronização em massa, que é justamente quando o operador minimiza.
  // Recriar os objetos deixava o snapshot apontando para órfãos: os bytes iam
  // pro OPFS, mas os ids eram descartados no `setState` seguinte e a música
  // aparecia como não baixada (e era rebaixada). Reaproveitar o objeto também
  // preserva de graça qualquer campo extra (ex.: `_norm` da busca).
  let colheu = false;   // o índice trouxe letra de graça? (ver abaixo)
  const songs = list.map((row) => {
    const s = byId.get(row.id_music)
      || { id_music: row.id_music, fileIdFull: null, fileIdPlayback: null };
    s.track = row.track;
    s.name = row.name;
    s.duration = row.duration;
    // A API PODE mandar a letra já no índice (o app-ja busca por esse campo —
    // ver docs/FONTE-DE-DADOS-LOUVORJA.md §5.3). Quando manda, é de graça:
    // aproveitamos e a música nem entra na fila de download de letras.
    if (row.lyric) {
      const est = typeof row.lyric === 'string'
        ? [{ a: null, l: normalizeLyricText(row.lyric).split('\n').map((x) => x.trim()).filter(Boolean) }]
        : lyricStanzasFromMeta(row);
      if (est && est.length) { lyricStoreFor(coll.id)[row.id_music] = est; colheu = true; }
    }
    s.has_instrumental_music = !!row.has_instrumental_music;
    s._norm = normalizeForSearch(row.name);
    return s;
  });
  collState[coll.id] = { indexSyncedAt: Date.now(), songs, isHymnal };
  await AVDB.setState('coll:' + coll.id, collState[coll.id]);
  // Só grava se houve colheita: um `setState` do acervo de letras a cada
  // atualização de índice reescreveria megabytes por nada.
  if (colheu) { await saveLyricStore(coll.id); invalidateLyricIndex(); }
  refreshCollectionsIfVisible();
  // Popup de busca aberto durante a atualização: reflete a lista nova sem
  // esperar o operador reabrir o popup — pelo guarda, que ADIA enquanto há
  // gaveta aberta (`interacaoAbertaNoAcervo`) e rearma sozinho. `autoRefresh
  // Collections` relê os dois hinários em toda retomada do app, sem TTL: sem
  // o guarda, voltar para o app fechava a gaveta que estava aberta.
  renderBuscaQuandoPuder(false);
}


// Executa `fn` sobre `items` com concorrência limitada (no máximo `limit` em
// voo ao mesmo tempo). Usado pra buscar o índice de dezenas de álbuns sem
// disparar todas as requisições de uma vez.
async function runLimited(items, limit, fn) {
  let i = 0;
  async function worker() {
    while (i < items.length) { const idx = i++; await fn(items[idx], idx); }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
}

// Índices de álbum são considerados "frescos" por este tempo — dentro dele,
// uma retomada do app não refaz a requisição (evita N requisições a cada
// visibilitychange). Álbuns novos ou ainda sem índice são sempre buscados.
const ALBUM_INDEX_TTL = 12 * 60 * 60 * 1000; // 12 h

// Atualização automática e silenciosa — ao abrir o app e ao retomar do 2º
// plano (ver o handler de visibilitychange no fim do arquivo), sem aviso de erro:
//  1. índices leves dos HINÁRIOS (fixos) + catálogo de ÁLBUNS (nomes dos cards);
//  2. índice leve (só metadados — album_{id}.musics, SEM áudio) de CADA álbum,
//     pra a busca do acervo cobrir TODAS as músicas de TODOS os álbuns mesmo
//     sem nada baixado (tocar num resultado baixa sob demanda — igual ao
//     hinário). Concorrência limitada + TTL (pula álbuns indexados há pouco,
//     mas sempre busca os novos/vazios). Uma falha (ex: sem rede) só mantém o
//     que já está em cache.
let collectionsRefreshing = false;
// O DIA CORRENTE como 'AAAA-MM-DD', no fuso do aparelho. É a chave de
// validade do índice de uma série que esconde o que ainda não saiu — e é local
// de propósito: o sábado do operador é o do relógio dele, não o de UTC.
function serieDiaLocal(d) {
  const x = d instanceof Date ? d : new Date();
  return x.getFullYear() + '-' + String(x.getMonth() + 1).padStart(2, '0')
    + '-' + String(x.getDate()).padStart(2, '0');
}

// ===== A PROCURA DO EPISÓDIO DESTA SEMANA (v1.2.22) =====
//
// Pedido do operador: *"faça o provai e vede e o informativo das missões serem
// atualizados, em especial buscando apenas o vídeo dessa semana, busca de se
// atualizar diretamente quando o app é aberto. Não para baixar o vídeo nem
// nada, apenas verificar a listagem em busca do vídeo atual."*
//
// **O piso entre duas procuras, e ele existe porque a pergunta é feita também
// no `visibilitychange`:** o operador troca de app dezenas de vezes durante um
// culto, e uma extração da aba do canal a cada volta seria a rajada de
// requisições na Wi-Fi da igreja que o KDoc do `autoRefreshCollections` recusa.
// Meia hora enquanto FALTA é no máximo duas extrações por hora — e ZERO assim
// que o episódio entra, que é o desenho inteiro desta regra.
const SERIE_PROCURA_MIN_MS = 30 * 60 * 1000; // 30 min

/**
 * A PRIMEIRA passada da SESSÃO ignora o piso — *"quando o app é aberto"* é o
 * pedido, ao pé da letra.
 *
 * Uma CARGA DE PÁGINA é rara (o app fica vivo o culto inteiro, segurado pelos
 * serviços em primeiro plano) e é o instante em que o operador está perguntando
 * *"já saiu?"*. O `visibilitychange`, que roda a mesma função, é o oposto: são
 * dezenas de voltas por culto, e é dele que o piso protege.
 *
 * O caso concreto que ela cobre: o Android mata o app, o operador o reabre
 * quinze minutos depois da última varredura, e o episódio saiu no meio desses
 * quinze minutos. Com o piso sozinho, abrir o app não responderia — que é a
 * queixa que este lote existe para consertar.
 *
 * **Quem a desarma é `autoRefreshCollections`, não o `indiceVencido`:** aquele
 * é um PREDICADO, chamado dentro de um `filter` sobre todas as coleções, e um
 * efeito colateral ali a apagaria na primeira coleção da lista — que pode nem
 * ser uma série. Ela morre com a página, que é o significado de "sessão".
 */
let serieProcuraDaAbertura = true;

/**
 * O índice desta série JÁ TEM o episódio do sábado desta semana?
 *
 * Quem responde é `AVSerie.ehDoSabadoAtual`, a MESMA função que decide o bloco
 * de destaque no topo da lista — e é essa identidade que importa: uma segunda
 * conta de calendário escrita aqui divergiria dela, e o desfecho seria o app
 * procurando para sempre um episódio que a tela já mostra (ou parando de
 * procurar um que ela diz faltar). Foi uma divergência dessas que produziu o
 * defeito da v1.2.19.
 *
 * `serieData` é `{ dia, mes }` guardado no índice por `serieFaixaDoItem`, ou
 * `null` quando o título não declarou data — e `ehDoSabadoAtual` recusa `null`,
 * que é o certo: não há como afirmar de que semana é um episódio sem data.
 *
 * **O PREÇO DISSO ESTÁ DITO:** um episódio publicado SEM data no título nunca
 * satisfaz esta pergunta, e a série fica sendo procurada a cada meia hora
 * enquanto o operador estiver com o app aberto. É o teto de duas extrações por
 * hora, e o Registro já nomeia esse caso (`! entrou SEM data`) — o conserto é
 * na leitura da data, não aqui.
 */
function serieTemODaSemana(c, agora) {
  const st = collState[c.id];
  const hoje = new Date(agora);
  return (st.songs || []).some(
    (s) => AVSerie.ehDoSabadoAtual(s.serieData, c.serie, hoje));
}

// O ÍNDICE DE UMA COLEÇÃO PRECISA SER REFEITO?
//
// Ela é uma função nomeada, e não o corpo de um `filter`, porque o oráculo
// precisa fazer a MESMA pergunta que o app faz — uma segunda escrita da regra
// no teste provaria que o teste concorda consigo mesmo. É o mesmo argumento do
// `avaliarPlaylist` do `serie.js`, um nível acima.
function indiceVencido(c, agora) {
  const st = collState[c.id];
  if (!st || !st.songs.length) return true;
  if ((agora - (st.indexSyncedAt || 0)) > ALBUM_INDEX_TTL) return true;
  // UM ÍNDICE ANTERIOR AO DIÁRIO conta como vencido (v5.249). Sem isto, o bloco
  // das séries no Registro diria "ainda não varrido" por até 12 h depois de a
  // atualização chegar — e é justamente ali que o operador vai buscá-lo, porque
  // foi a atualização que o fez olhar. Custa UMA varredura, uma vez, num
  // aparelho que já tem o índice; o carimbo é escrito nos DOIS caminhos do
  // `fetchSerieIndex`, senão ele voltaria a extrair o canal a cada abertura.
  if (c.kind !== 'serie') return false;
  if (!st.serieDiarioEm) return true;
  // ENQUANTO FALTAR O EPISÓDIO DESTA SEMANA, O ÍNDICE ESTÁ VENCIDO (v1.2.22).
  //
  // O TTL de 12 h responde *"a lista envelheceu?"*; esta linha responde a
  // pergunta que o operador de fato faz ao abrir o app — *"já saiu o vídeo
  // deste sábado?"*. As duas não são a mesma: um índice de onze horas atrás é
  // FRESCO para o TTL e pode ser de antes de o episódio ser publicado, e era
  // por isso que o **Provai e Vede** (que não tem a regra do dia, logo abaixo)
  // podia passar um sábado inteiro sem o vídeo do culto.
  //
  // **Ela se desarma sozinha:** achado o episódio, `serieTemODaSemana` passa a
  // responder `true` e esta série volta a custar ZERO requisição até o TTL, ou
  // até a semana virar. É o que separa "procurar o que falta" de "revarrer
  // sempre" — e revarrer sempre seria o peso que o pedido exclui.
  //
  // **Só o ANO CORRENTE**, e a guarda não é detalhe: o `ano` do catálogo é
  // explícito, então em 2027 nenhum episódio do álbum de 2026 pode ser "o desta
  // semana" — sem ela, um álbum antigo que ficasse na Biblioteca seria
  // procurado a cada meia hora, para sempre, sem nada a achar.
  //
  // NADA AQUI BAIXA VÍDEO: quem roda é `fetchCollectionIndex`, que só refaz a
  // LISTA (`fetchSerieIndex`). O download continua sendo item a item, pela
  // folha de destinos.
  if (c.serie && c.serie.ano === new Date(agora).getFullYear()
      && (serieProcuraDaAbertura
        || (agora - (st.indexSyncedAt || 0)) > SERIE_PROCURA_MIN_MS)
      && !serieTemODaSemana(c, agora)) return true;
  // E O DIA VENCE O ÍNDICE quando a série esconde o que ainda não saiu (v5.255).
  // Ali a lista é função do DIA: o episódio do culto de hoje estava escondido
  // ontem, e sem isto ele só apareceria quando o TTL de 12 h vencesse — que
  // pode ser depois do culto. Custa uma varredura por dia, e só nessa série.
  return c.serie && c.serie.futuros === AVSerie.FUTUROS_ESCONDER
    && st.serieDiaEm !== serieDiaLocal(new Date(agora));
}

/**
 * ===== A VERIFICAÇÃO DE ÁLBUM VIRA AUTOMÁTICA (v1.1.16) =====
 *
 * Pedido do operador: *"agora a verificação é feita de forma automática, no
 * segundo plano toda vez que o app abre (tente fazer de forma a ser algo
 * invisível para o usuário e sem efeito de peso significativo de processamento,
 * para não ser notado), e se tiver alguma diferença ele mostra o botão de
 * download"*.
 *
 * **O QUE FALTAVA ERA POUCO, e é a razão de o botão ter podido sair.** Esta
 * função já roda na abertura e relê os índices; a fase 2 é que só pegava os
 * VENCIDOS pelo TTL de 12 h. O botão "Verificar" existia exatamente para pular
 * esse TTL, e só aparecia num álbum COMPLETO — o caso em que não há o que
 * baixar e a única pergunta é "o catálogo cresceu?".
 *
 * `forcarIndice` reproduz aquele toque, sem o toque: relê o índice dos álbuns
 * que o operador DE FATO tem no aparelho. O desfecho é o mesmo que o botão
 * dava — o índice cresce, `colecaoCompleta` vira falso, e o botão de BAIXAR
 * aparece na barra do card, que é onde o pedido manda mostrá-lo.
 *
 * ===== E ELE PRECISA SER INVISÍVEL, QUE É A METADE DIFÍCIL =====
 *
 *  - **UMA VEZ POR SESSÃO, não por retomada** (`indicesForcados`). Esta função
 *    roda também no `visibilitychange`, e o operador troca de app dezenas de
 *    vezes durante um culto: forçar a cada volta seria uma rajada de
 *    requisições na Wi-Fi da igreja toda vez que ele olha uma mensagem. O
 *    conjunto vive no módulo e morre com a página — que é exatamente o
 *    significado de "toda vez que o app abre".
 *  - **SÓ ÁLBUM, e só o que tem download.** A conta é proporcional ao que o
 *    operador guardou (tipicamente um punhado), nunca ao catálogo inteiro
 *    (~40). Num aparelho sem nada baixado o custo é ZERO — nenhuma requisição
 *    a mais que hoje.
 *  - **A SÉRIE NÃO É FORÇADA POR TER DOWNLOAD**, e essa é a exceção que precisa
 *    estar dita: o índice dela custa uma extração do canal do YouTube, não um
 *    GET de JSON, e forçá-la por aqui seria o "peso significativo de
 *    processamento" que o pedido exclui. Ela entra pelo `indiceVencido`, que
 *    desde a v1.2.22 tem uma pergunta a mais e ESPECÍFICA: enquanto faltar o
 *    episódio do sábado desta semana, o índice está vencido (com piso de meia
 *    hora entre procuras). É o contrário de forçar — a procura existe enquanto
 *    há o que achar e se desarma sozinha quando acha.
 *  - **Os HINÁRIOS já eram relidos sem TTL** (fase 1, sempre): para eles não
 *    muda nada, e nunca fez falta.
 *
 * O erro possível aqui é o BARATO: uma releitura a mais de um JSON de lista.
 * O caro seria o oposto — o operador com um álbum incompleto e nenhum botão
 * para baixá-lo —, e é contra isso que `colecaoCompleta` decide sozinha.
 */
const indicesForcados = new Set();

async function autoRefreshCollections() {
  if (collectionsRefreshing) return;
  collectionsRefreshing = true;
  try {
    // Coleção sincronizando agora não é atualizada por aqui: o download em
    // massa está escrevendo nos objetos desta lista, e mesmo com a mutação
    // in-place do `fetchCollectionIndex` não há por que competir pelo
    // `setState` da mesma chave no meio do trabalho pesado.
    const idle = (c) => !ui(c.id).syncBusy;
    // Fase 1: hinários + catálogo de álbuns (barato).
    await Promise.all([
      ...FIXED_COLLECTIONS.filter(idle).map((c) => fetchCollectionIndex(c).catch(() => {})),
      fetchAlbumCatalog().catch(() => {}),
    ]);
    // Fase 2: índice de cada álbum (só os que estão vazios ou vencidos pelo TTL).
    const now = Date.now();
    // As SÉRIES entram nesta mesma fase (v5.231), e não na 1: o índice delas
    // custa uma extração do YouTube para a aba do canal — barato quando a
    // assinatura das playlists não mudou (ver `fetchSerieIndex`), e caro quando
    // mudou. O TTL é o mesmo dos álbuns porque a pergunta é a mesma ("a lista
    // envelheceu?"); a pergunta PRÓPRIA da série — "já saiu o vídeo deste
    // sábado?" — mora no `indiceVencido`, com piso de meia hora.
    // O álbum COM DOWNLOAD é relido nesta abertura mesmo dentro do TTL — é o
    // que o botão "Verificar" fazia, e ver o KDoc acima para o porquê de a
    // série ficar de fora. `countDownloaded` varre as faixas em memória (sem
    // rede, sem disco), e só para os álbuns, uma vez por sessão.
    const forcarIndice = (c) => c.kind === 'album'
      && !indicesForcados.has(c.id)
      && countDownloaded(c.id) > 0;
    const stale = allCollections().filter(
      (c) => (c.kind === 'album' || c.kind === 'serie') && idle(c)
        && (indiceVencido(c, now) || forcarIndice(c)));
    // O carimbo é posto ANTES da rede, e para TODOS os escolhidos: uma falha de
    // rede não pode fazer a próxima retomada tentar de novo — aí o "uma vez por
    // sessão" viraria "a cada volta ao app" justamente no aparelho com a pior
    // conexão. Quem retenta é a abertura seguinte.
    stale.forEach((c) => { if (c.kind === 'album') indicesForcados.add(c.id); });
    // E A ABERTURA JÁ FOI. Daqui em diante quem governa a procura do episódio
    // da semana é o piso de meia hora — o `visibilitychange` chama esta mesma
    // função, e é ele que produziria a rajada. Desarmado AQUI, e não no
    // `indiceVencido`, porque aquele é um predicado dentro de um `filter`.
    serieProcuraDaAbertura = false;
    await runLimited(stale, NET_CONCURRENCY, (c) => fetchCollectionIndex(c).catch(() => {}));
    // Fase 3: as LETRAS dos hinários, como informação padrão do acervo — o
    // índice sozinho não responde "qual hino fala em…". Fire-and-forget: é
    // longa (uma requisição por música) e nada na tela espera por ela; o
    // progresso vai para a notificação, como qualquer trabalho de massa.
    syncLyrics().catch(() => {});
    // Fase 4: as CIFRAS dos hinários, pelo mesmo motivo e pelo mesmo caminho.
    //
    // ELA PRECISOU SAIR DO DOWNLOAD (v1.1.30). Pendurada no fim do
    // `syncCollection`, a v1.1.28 nunca alcançou quem MAIS precisa dela: um
    // hinário já completo faz aquela função retornar em "Já completo offline",
    // muito antes do gancho. MEDIDO em dois Registros seguidos: `0 de 601`
    // depois de o operador tocar a sincronização. Aqui é como o `syncLyrics`
    // sempre foi — informação padrão do acervo, uma vez por sessão, em segundo
    // plano —, e o download deixa de ser a única porta.
    syncCifrasAcervo().catch(() => {});
  } finally { collectionsRefreshing = false; }
}

// Sincroniza (ou re-sincroniza) UMA coleção da API do LouvorJA para uso 100%
// offline. Duas fases: (1) Índice leve (nomes/números/duração) — a busca usa
// só isso; (2) Download pesado: para cada música ainda não baixada (ou cujo
// arquivo catalogado tenha sido apagado por fora, ou que ainda não tenha a
// letra sincronizada — backfill sem rebaixar o áudio), busca music_{id} e
// grava áudio Cantado + Playback (se houver) + capa/letra no OPFS/catálogo
// (mesma pasta `folders/<coll.id>/`). Aditiva e resumível: interromper e
// sincronizar de novo continua de onde parou, sem duplicar.
// `opts.allowMobile`: a pergunta de rede já foi feita para o LOTE (ver
// syncGroup) — não repetir por álbum.
// `opts.fromGroup`: a chamada é PROGRAMÁTICA (o laço do lote), não um toque do
// operador — ver o guard de cancelamento abaixo.
//
// Devolve `{ ok, baixados, falhou }`. Antes devolvia `undefined` em todos os
// caminhos, e por isso uma queda de rede era invisível para o chamador: o lote
// varria 40 álbuns em segundos sem baixar nada e ainda anunciava "Coleção
// completa" (ver syncGroup). `ok:false` = não deu para baixar (rede,
// armazenamento, erro); cancelar ou já estar completo é `ok:true`.
async function syncCollection(coll, opts) {
  const allowMobile = !!(opts && opts.allowMobile);
  const u = ui(coll.id);
  // Tocar de novo com a sincronização em andamento CANCELA. Antes isto era um
  // `return` mudo: um álbum de centenas de faixas, uma vez começado, não tinha
  // como ser interrompido a não ser fechando o app.
  if (u.syncBusy) {
    // …mas só quando quem tocou foi o OPERADOR. Vindo do lote, o álbum já
    // está baixando por conta própria: reinterpretar isso como "segundo
    // toque" ABORTAVA o download em curso — o operador pedia dois downloads e
    // o efeito líquido era parar um. Aqui o lote apenas pula o álbum.
    if (opts && opts.fromGroup) return { ok: true, baixados: 0, falhou: 0 };
    u.cancel = true;
    setCollStatus(coll.id, 'Cancelando…');
    renderCollectionsNow();
    return { ok: true, baixados: 0, falhou: 0 };
  }
  if (!AVDB.opfsSupported()) {
    setCollStatus(coll.id, 'Armazenamento OPFS indisponível', 5000);
    return { ok: false, baixados: 0, falhou: 0 };
  }
  u.syncBusy = true; u.cancel = false;
  setCollStatus(coll.id, 'Atualizando lista…');
  renderCollectionsNow(); // resposta ao toque é imediata; só o PROGRESSO é coalescido
  // Cancelamento: o próprio álbum (botão) ou o lote que o contém (syncGroup).
  // Declarado antes de tudo porque a VARREDURA do que falta também é longa num
  // álbum de centenas de faixas — cancelar ali já precisa valer.
  const cancelled = () => u.cancel || !!(opts && opts.cancelled && opts.cancelled());
  try {
    if (navigator.storage && navigator.storage.persist) navigator.storage.persist().catch(() => {});

    try { await fetchCollectionIndex(coll); }
    catch (_) {
      setCollStatus(coll.id, 'Sem internet — falha ao atualizar', 5000);
      return { ok: false, baixados: 0, falhou: 0 };
    }
    // SÓ O ÍNDICE (v5.230) — é o que o botão de uma SÉRIE faz. A lista chegou,
    // e é só ela que foi pedida: os episódios são baixados um a um, pela folha
    // de destinos, como um vídeo do YouTube. Cair no laço abaixo aqui seria
    // exatamente o "download direto" que este lote existe para tirar.
    if (opts && opts.soIndice) {
      setCollStatus(coll.id, 'Lista atualizada', 4000);
      return { ok: true, baixados: 0, falhou: 0 };
    }
    const songs = collSongs(coll.id);

    const pending = [];
    // Em pedaços de 8, e não em série: cada música custa até 2 `fileGet`
    // (Cantado + Playback), e num hinário de ~600 faixas a varredura serial
    // eram ~1200 leituras de IDB uma a uma antes do primeiro byte de download.
    // O cancelamento continua valendo por iteração — conferido a cada pedaço,
    // e um pedaço em voo custa no máximo 8 leituras, não o álbum.
    const PASSO_VARREDURA = 8;
    for (let i = 0; i < songs.length; i += PASSO_VARREDURA) {
      if (cancelled()) { setCollStatus(coll.id, 'Cancelado', 4000); return { ok: true, baixados: 0, falhou: 0 }; }
      const fatia = songs.slice(i, i + PASSO_VARREDURA);
      const flags = await Promise.all(fatia.map((s) => songVariantsNeeded(coll, s)));
      flags.forEach((f, k) => { if (f.needsFull || f.needsPlayback) pending.push(fatia[k]); });
    }
    if (pending.length === 0) {
      setCollStatus(coll.id, 'Já completo offline', 4000);
      // …mas as CIFRAS podem faltar. Um hinário com todo o áudio no disco sai
      // por aqui, e era exatamente este o caminho em que o download de cifras
      // da v1.1.28 nunca acontecia. Tocar em sincronizar tem de fazer alguma
      // coisa quando ainda há o que buscar.
      await syncCifrasColecao(coll).catch(() => {});
      return { ok: true, baixados: 0, falhou: 0 };
    }
    if (cancelled()) { setCollStatus(coll.id, 'Cancelado', 4000); return { ok: true, baixados: 0, falhou: 0 }; }

    // Fora do Wi-Fi a sincronização em massa NÃO é bloqueada — ela pergunta.
    // Baixar um hinário inteiro pode ser bastante coisa, e só o operador sabe
    // se o plano dele aguenta; o que o app não pode é decidir sozinho por ele,
    // em nenhuma das duas direções. A escolha vale **só para esta
    // sincronização deste álbum**: não vira uma preferência do app, e o
    // próximo álbum pergunta de novo.
    if (!isConfirmedWifi() && !allowMobile) {
      const est = estimatePendingBytes(coll);
      const proceed = await appConfirm({
        title: 'Baixar usando dados móveis?',
        message: 'Você não está numa rede Wi-Fi confirmada. Baixar ' + pending.length
          + ' música(s) pendente(s) de "' + coll.name + '" agora vai usar a internet móvel'
          + (est ? ' (aproximadamente ' + fmtBytes(est) + ')' : '') + '.\n\n'
          + 'Esta escolha vale só para este álbum, agora. Se preferir esperar o Wi-Fi, a lista '
          + 'já foi atualizada e cada música continua sendo baixada sozinha quando você tocá-la.',
        okText: 'Usar dados móveis', cancelText: 'Só no Wi-Fi',
      });
      if (!proceed) {
        setCollStatus(coll.id, 'Lista atualizada', 5000);
        return { ok: true, baixados: 0, falhou: 0 };
      }
    }

    let done = 0, falhou = 0;
    const CONCURRENCY = NET_CONCURRENCY;
    // A CADA QUANTAS FAIXAS O ÍNDICE DA COLEÇÃO VAI AO DISCO — o irmão do
    // `CHECKPOINT_PASTA` e do `LYRIC_BATCH`, e pelo mesmo motivo. Gravar por
    // MÚSICA reescreve o índice INTEIRO cada vez: MEDIDO num índice do tamanho
    // do Hinário 2022, 119 kB × 601 = 68 MB no IndexedDB por sincronização
    // completa, disputando transação com o `state` que a mesma sessão usa
    // (`lyrics:`, `opfs-folders`, `ota-intencao`) enquanto 6 downloads correm.
    //
    // O que a gravação protege é a RETOMADA: os `fileIdFull`/`fileIdPlayback`
    // que `songVariantsNeeded` lê. O pior caso do lote é o processo ser morto e
    // até 24 faixas serem rebaixadas — contra as centenas que nenhuma gravação
    // custaria. Mesma troca que o `CHECKPOINT_PASTA` já aceitou.
    const CHECKPOINT_COLECAO = 25;
    let next = 0;
    // Dentro de um lote (syncGroup) o rótulo da notificação já traz o contexto
    // do grupo; sozinho, é o nome do álbum.
    const notifLabel = (opts && opts.notifLabel) || coll.name;
    // Dentro de um lote a tarefa da notificação é do LOTE (notifOwned) — este
    // álbum só repassa o passo, sem abrir uma tarefa concorrente.
    const notifId = (opts && opts.notifOwned) ? 0 : bgTaskStart(notifLabel, pending.length);
    // Qual tarefa da notificação recebe os nomes: a do lote, quando há um.
    const itemTaskId = (opts && opts.notifTaskId) || notifId;
    async function worker() {
      while (next < pending.length) {
        // FECHAR A FILA é o que cancelar significa aqui: nenhuma música nova
        // entra, e as que já estão no ar (até NET_CONCURRENCY) terminam. Parar
        // no meio de um download deixaria um arquivo truncado catalogado como
        // completo — e o custo de esperar é uma faixa, não um álbum de 600.
        if (cancelled()) return;
        const s = pending[next++];
        bgItemStart(itemTaskId, s.name);
        // `done` conta TENTATIVAS (é ele que move a barra), `falhou` conta as
        // que voltaram sem áudio. Sem essa separação, uma queda de rede fazia
        // o rodapé anunciar "Atualizado (60 baixado(s))" com zero bytes no
        // disco: downloadCollectionSong engole a falha e o worker contava a
        // música como baixada.
        let okSong = true;
        try { okSong = (await downloadCollectionSong(coll, s)) !== false; }
        finally { bgItemEnd(itemTaskId, s.name); }
        done++;
        if (!okSong) falhou++;
        setCollStatus(coll.id, cancelled()
          ? 'Cancelando — concluindo o que já começou…'
          : 'Baixando ' + done + '/' + pending.length + '…');
        if (opts && opts.onSong) opts.onSong();
        else bgTaskStep(notifId, done);
        // `done` é compartilhado pelos CONCURRENCY workers e cada incremento é
        // conferido uma vez, então o ponto de controle sai exatamente a cada
        // CHECKPOINT_COLECAO faixas. O lote parcial do fim é gravado pelo
        // `finally` do `Promise.all` — sem ele o cancelamento (que só fecha a
        // fila) perderia o que veio depois do último múltiplo de 25.
        if (done % CHECKPOINT_COLECAO === 0) {
          await AVDB.setState('coll:' + coll.id, collState[coll.id]);
        }
      }
    }
    // Sincronização em massa: dezenas ou centenas de áudios — o operador
    // dispara e sai do app. Sem a proteção, parava ao minimizar.
    //
    // `bgTaskEnd` DENTRO do `withBgWork` (ver a mesma nota em syncGroup): o
    // `finally` de withBgWork roda antes de um `finally` externo e já limpa o
    // registro de tarefas, então encerrar a tarefa depois dele não tinha mais
    // efeito nenhum.
    await withBgWork(async () => {
      try {
        await Promise.all(Array.from({ length: CONCURRENCY }, worker));
      } finally {
        bgTaskEnd(notifId);
        // O ÚLTIMO LOTE, SEMPRE — e no `finally` porque um worker pode LANÇAR
        // (o `catch` externo só troca a faixa de status). Sem esta gravação as
        // até 24 faixas depois do último ponto de controle ficariam no OPFS sem
        // `fileIdFull` no índice: rebaixadas na passada seguinte, e o arquivo
        // órfão recolhido pelo coletor.
        try { await AVDB.setState('coll:' + coll.id, collState[coll.id]); }
        catch (_) { /* a passada seguinte rebaixa o lote */ }
      }
    });
    setCollStatus(coll.id, (cancelled() ? 'Cancelado (' : 'Atualizado (') + (done - falhou) + ' baixado(s))'
      + (falhou ? ' · ' + falhou + ' sem rede' : ''), 4000);
    // AS CIFRAS DO HINÁRIO VÊM JUNTO (v1.1.28), e só do hinário: é o único
    // acervo cujo endereço no site é deduzível do nome. Depois do áudio, nunca
    // antes — o que o operador pediu foi o hinário, e a cifra é o extra que
    // torna a folha utilizável sem rede. `await` de propósito: ela usa a mesma
    // proteção de segundo plano, e soltá-la aqui deixaria o `finally` desligar
    // o serviço com centenas de requisições ainda por fazer.
    if (!cancelled()) await syncCifrasColecao(coll).catch(() => {});
    // Tudo o que se tentou falhou: para o lote isso é o mesmo que não ter
    // baixado nada, e o cabeçalho do grupo precisa saber.
    return { ok: !(falhou > 0 && falhou >= done), baixados: done - falhou, falhou };
  } catch (_) {
    setCollStatus(coll.id, 'Erro na sincronização', 5000);
    return { ok: false, baixados: 0, falhou: 0 };
  } finally {
    u.syncBusy = false; u.cancel = false;
    // RECONFERIR O PESO AO FIM DO LOTE (v5.134). Durante o download o número
    // sobe por acumulação (`u.bytes +=` a cada arquivo), que é o certo para dar
    // movimento na tela mas erra em toda borda: uma faixa que falhou no meio,
    // um download repetido que sobrescreveu o arquivo anterior, um cancelamento
    // no meio do lote. O fim do lote é o momento em que perguntar ao disco é
    // barato — não há mais IO concorrente — e é o único ponto em que o número
    // exibido pode ser trocado pelo real sem custo visível.
    updateCollBytes(coll.id);
    refreshCollectionsIfVisible();
  }
}

// Baixa (ou completa) uma música: busca os metadados individuais (URLs reais) e
// grava áudio Cantado + Playback (se houver) + capa/letra sincronizada no
// OPFS/catálogo. `s` é mutado in-place (fileIdFull/fileIdPlayback), refletido
// no collState[coll.id] compartilhado.
//
// Devolve `false` quando nem os metadados vieram (sem rede) — quem chama
// precisa poder distinguir "baixou" de "desistiu em silêncio", senão o status
// final conta como baixada uma música que não saiu do lugar.
/**
 * Baixa UM episódio de uma série e o grava na pasta do álbum.
 *
 * Não passa pelo `ytBaixarNativo`: aquele é o caminho de um download AVULSO —
 * abre tarefa própria na notificação, desenha cartão na preview e registra
 * intenção de resgate. Aqui quem já é dono de tudo isso é o `syncCollection`
 * (a barra, o nome do item na notificação, o cancelamento, o `withBgWork`), e
 * empilhar uma segunda tarefa por episódio faria a notificação disputar consigo
 * mesma a cada um dos 52.
 *
 * O registro vai para `folder: coll.id`, como o de uma música de coleção — é
 * isso que faz o card contar "completo offline", o peso somar e o coletor de
 * lixo não recolher o arquivo. E `lyrics: null` **não é enfeite**: o
 * `songVariantsNeeded` pergunta `fullRec.lyrics === undefined` para decidir se
 * a faixa ainda falta, então um registro sem o campo seria rebaixado a cada
 * sincronização, para sempre, sem nada na tela que o explicasse.
 */
async function downloadSerieItem(coll, s) {
  if (!s.ytUrl) return false;
  let r;
  try { r = await AVNative.ytFetch(s.ytUrl, null, false, 0); }
  catch (_) { return false; }
  if (!r || !r.url) return false;
  try {
    const res = await fetch(r.url);
    if (!res.ok) return false;
    const blob = await res.blob();
    if (!blob.size) return false;
    const thumb = await makeThumb(blob, 'video');
    const id = s.fileIdFull || uid();
    const path = 'folders/' + coll.id + '/' + s.id_music + '.mp4';
    try { await AVDB.opfsWriteFile(path, blob); } catch (_) { return false; }
    await AVDB.fileAdd({
      id, folder: coll.id, opfsPath: path,
      srcName: s.id_music,
      name: s.name,
      // A procedência, como nas músicas do acervo (v5.219): é a segunda linha
      // do slide de capa, e quem projeta é o Display, que não tem acesso a
      // coleção nenhuma.
      hymnName: s.name, hymnTrack: null, hymnAlbum: coll.name || '',
      type: blob.type || 'video/mp4', kind: 'video',
      height: (r.height | 0) || null,
      // O id do vídeo GRAVADO: é ele que faz um "Tocar agora" do mesmo
      // episódio, vindo da busca do YouTube, reaproveitar este arquivo.
      youtubeId: s.id_music,
      size: blob.size, mtime: Date.now(), thumb, lyrics: null,
      blob: null, url: null, addedAt: Date.now(),
    });
    s.fileIdFull = id;
    ui(coll.id).bytes += blob.size || 0;
    salvarPesos();
    return true;
  } finally {
    // No `finally`, como no caminho avulso: falhando a cópia, o arquivo do
    // cache não pode ficar para trás — ninguém mais tem o token dele.
    AVNative.ytDiscard(r.url);
  }
}

async function downloadCollectionSong(coll, s) {
  if (coll.kind === 'serie') return downloadSerieItem(coll, s);
  let meta;
  try { meta = await Louvorja.fetchList('music_' + s.id_music); }
  catch (_) { return false; } // sem rede agora; a próxima sincronização tenta de novo

  // Cache de imagens por URL, compartilhado entre as duas variantes (Cantado
  // e Playback quase sempre usam as mesmas imagens da letra) — evita baixar a
  // mesma imagem mais de uma vez.
  const imgCache = new Map();
  async function resolveImage(url) {
    if (!url) return null;
    if (imgCache.has(url)) return imgCache.get(url);
    const result = await downloadCollectionImage(coll.id, url, s.id_music, imgCache.size);
    imgCache.set(url, result);
    return result;
  }

  const coverImage = meta.url_image ? await resolveImage(meta.url_image) : null;
  const thumb = coverImage ? coverImage.thumbBlob : null;

  await ensureSongVariant(coll, s, 'fileIdFull', meta.url_music, 'Cantado', meta, 'time', thumb, resolveImage);
  if (s.has_instrumental_music) {
    await ensureSongVariant(coll, s, 'fileIdPlayback', meta.url_instrumental_music, 'Playback', meta, 'instrumental_time', thumb, resolveImage);
  }
}

// Garante que uma variante (Cantado/Playback) tenha áudio E letra
// sincronizada. Cobre 3 casos: nunca baixado (baixa tudo); áudio já baixado
// mas ainda sem `lyrics` (só recalcula e grava a letra no registro existente,
// SEM rebaixar o áudio — backfill dos itens baixados antes da letra existir);
// já completo (não faz nada).
async function ensureSongVariant(coll, s, fileKey, urlPath, variantLabel, meta, timeField, thumb, resolveImage) {
  // "NÃO EXISTE" NÃO É "NÃO BAIXEI" (v5.134). Uma música cuja origem não traz o
  // arquivo (`url_music`/`url_instrumental_music` vazios no `music_{id}`) nunca
  // ia ganhar id de arquivo — e, como toda a tela contava a ausência do id como
  // "falta baixar", a coleção NUNCA ficava completa: o botão de baixar não sumia
  // mais, e cada sincronização voltava a buscar o metadado dela só para
  // redescobrir que não há o que baixar. A marca fica no índice da coleção, e o
  // `fetchCollectionIndex` a preserva de graça (ele reaproveita o objeto).
  const semFonte = fileKey === 'fileIdFull' ? 'semAudio' : 'semPlayback';
  if (!urlPath) { s[semFonte] = true; return; }
  // E o contrário também: a origem pode ter ganhado o arquivo depois. Sem
  // apagar a marca, o app continuaria dizendo "não existe" para sempre.
  if (s[semFonte]) delete s[semFonte];
  const existingId = s[fileKey];
  const existingRec = existingId ? await AVDB.fileGet(existingId) : null;
  if (existingRec && existingRec.lyrics !== undefined) {
    // JÁ COMPLETO — mas pode ser anterior ao `hymnAlbum` (v5.218). Sem este
    // preenchimento, a linha do álbum só apareceria em música baixada DEPOIS
    // desta versão: a biblioteca que o operador já tem — que é justamente a
    // que ele usa — ficaria sem ela para sempre. Uma escrita por registro, na
    // varredura que a sincronização já faz, e nunca mais.
    if (!existingRec.hymnAlbum && coll.name) {
      existingRec.hymnAlbum = coll.name;
      await AVDB.fileAdd(existingRec);
    }
    return;
  }

  const lyrics = await buildLyricSlides(meta, timeField, resolveImage);

  if (existingRec) {
    existingRec.lyrics = lyrics;
    existingRec.hymnName = s.name;
    existingRec.hymnTrack = s.track;
    existingRec.hymnAlbum = coll.name || '';
    await AVDB.fileAdd(existingRec);
    invalidateLyricIndex();   // letra nova no aparelho: a busca precisa vê-la
    return;
  }
  // (A guarda de `urlPath` vazio está lá em cima, junto com a marca de "não
  // existe na origem" — aqui ela seria tarde: a letra já teria sido montada.)
  const id = await downloadCollectionFile(coll, s, urlPath, variantLabel, thumb, lyrics);
  if (id) { s[fileKey] = id; invalidateLyricIndex(); }
}

async function downloadCollectionFile(coll, s, urlPath, variantLabel, thumb, lyrics) {
  if (!urlPath) return null;
  let blob;
  try {
    const res = await fetch(Louvorja.fileUrl(urlPath));
    if (!res.ok) throw new Error('HTTP ' + res.status);
    blob = await res.blob();
  } catch (_) { return null; }
  const ext = (urlPath.split('.').pop() || 'mp3').toLowerCase().split('?')[0];
  const id = uid();
  const path = 'folders/' + coll.id + '/' + s.id_music + '-' + variantLabel.toLowerCase() + '.' + ext;
  try { await AVDB.opfsWriteFile(path, blob); } catch (_) { return null; }
  await AVDB.fileAdd({
    id, folder: coll.id, opfsPath: path,
    srcName: s.id_music + '-' + variantLabel,
    name: songLabel(coll, s, true) + ' (' + variantLabel + ')',
    // `hymnTrack` é o número NO HINÁRIO, não a faixa do disco: fora de um
    // hinário fica nulo, e com isso o slide de capa, o título do popup de
    // letra e a preview param de numerar sem precisar saber de coleção
    // nenhuma (nenhum deles tem acesso a ela — o Display, em especial, só
    // recebe o registro do arquivo).
    hymnName: s.name, hymnTrack: collNumbersSongs(coll) ? s.track : null,
    // O ÁLBUM/COLEÇÃO de onde a música veio (v5.218) — a segunda linha do
    // cartão de capa. É o único metadado de procedência que a fonte publica:
    // o LouvorJA não tem campo de AUTOR (ver docs/FONTE-DE-DADOS-LOUVORJA.md),
    // e o nome da coleção é o que o operador reconhece de qualquer jeito
    // ("Hinário Adventista", "Vocal Livre"). Vai no REGISTRO, e não numa
    // consulta na hora de projetar, porque quem projeta é o Display: ele só
    // recebe o registro do arquivo e não tem acesso a coleção nenhuma.
    hymnAlbum: coll.name || '',
    type: blob.type || 'audio/mpeg', kind: 'audio',
    size: blob.size, mtime: Date.now(), thumb, lyrics,
    blob: null, url: null, addedAt: Date.now(),
  });
  // Peso da coleção: soma incremental, sem tocar o IDB. Recalcular com um
  // `filesByFolder` a cada arquivo baixado significava um getAll do catálogo
  // inteiro (registros COM thumb e letra) por música — ver updateCollBytes.
  ui(coll.id).bytes += blob.size || 0;
  salvarPesos();
  return id;
}

// Baixa uma imagem em resolução real pro OPFS (fundo dos slides de letra) e
// gera a miniatura do catálogo (mesmo `drawThumb`) a partir do MESMO blob —
// evita baixar a capa duas vezes (uma pro fundo, outra só pra miniatura).
async function downloadCollectionImage(folderId, url, songId, index) {
  let blob;
  try {
    const res = await fetch(Louvorja.fileUrl(url));
    if (!res.ok) throw new Error('HTTP ' + res.status);
    blob = await res.blob();
  } catch (_) { return null; }
  const ext = (url.split('.').pop() || 'jpg').toLowerCase().split('?')[0];
  const path = 'folders/' + folderId + '/' + songId + '-img-' + index + '.' + ext;
  try { await AVDB.opfsWriteFile(path, blob); } catch (_) { return null; }
  // ELAS TAMBÉM PESAM (v5.134). As imagens de fundo da letra vão para a MESMA
  // pasta dos áudios e ocupam disco como eles — mas não viram registro no
  // catálogo (são referenciadas de dentro dos slides, não são mídia da
  // biblioteca), e por isso ficavam de fora de toda conta: da soma incremental
  // daqui e da recontagem, que somava o catálogo. Num hinário inteiro isso é
  // centenas de MB que a tela não mostrava — e que o operador via sumir do
  // aparelho sem explicação.
  ui(folderId).bytes += blob.size || 0;
  salvarPesos();

  let thumbBlob = null;
  let objUrl = null;
  try {
    objUrl = URL.createObjectURL(blob);
    const img = await new Promise((resolve, reject) => {
      const im = new Image();
      im.onload = () => resolve(im);
      im.onerror = reject;
      im.src = objUrl;
    });
    thumbBlob = await drawThumb(img, img.naturalWidth, img.naturalHeight);
  } catch (_) {
    // sem miniatura, mas a imagem de fundo já foi gravada — segue normalmente
  } finally {
    if (objUrl) URL.revokeObjectURL(objUrl);
  }
  return { opfsPath: path, thumbBlob };
}

// "HH:MM:SS" (ou variações com menos partes) → segundos. `null` se
// vazio/inválido — nunca 0, pra não colidir com o tempo fixo do slide de capa.
function parseTimeToSeconds(str) {
  if (!str) return null;
  const parts = String(str).split(':').map(Number);
  if (parts.some((n) => isNaN(n))) return null;
  while (parts.length < 3) parts.unshift(0);
  const [h, m, sec] = parts;
  return h * 3600 + m * 60 + sec;
}

// Monta os slides de letra sincronizada de uma variante (Cantado usa `time`,
// Playback usa `instrumental_time`): slide de capa (tempo 0, sem texto,
// imagem da música) + uma entrada por linha de `meta.lyric` marcada como
// `show_slide`, ordenadas por tempo. Uma linha sem imagem própria herda a da
// anterior (fallback "grudento", igual ao app original); linhas sem tempo
// utilizável no campo ativo são ignoradas. Retorna `null` se não sobrar
// nenhuma linha real (só a capa) — sinaliza "sem letra utilizável", pra não
// tentar de novo a cada sincronização (ver ensureSongVariant).
// A API do LouvorJA embute quebras de linha manuais como tags `<br>` literais
// dentro do texto (confirmado no app-ja: ele usa `v-html` pra renderizar
// essas tags como quebra real) — sem isso, a letra ficaria como um único
// parágrafo e o navegador quebraria a linha sozinho, de forma diferente da
// quebra original pretendida pelo hino. Convertemos pra `\n` real (não
// `innerHTML`/`v-html` — mais seguro, sem risco de injeção) e `white-space:
// pre-line` no CSS (`.lyrics-line`/`.lyrics-aux`) respeita essas quebras.
function normalizeLyricText(str) {
  return (str || '').replace(/<br\s*\/?>/gi, '\n').trim();
}

async function buildLyricSlides(meta, timeField, resolveImage) {
  let prevImage = meta.url_image ? await resolveImage(meta.url_image) : null;
  let prevImagePosition = meta.image_position;

  const cover = {
    time: 0, text: null, auxText: null, cover: true,
    imageOpfsPath: prevImage ? prevImage.opfsPath : null,
    imagePosition: prevImagePosition,
  };

  const lines = Object.values(meta.lyric || {})
    .filter((l) => l.show_slide === 1)
    .sort((a, b) => a.order - b.order);

  const slides = [cover];
  for (const line of lines) {
    const time = parseTimeToSeconds(line[timeField]);
    if (time === null) continue;
    if (line.url_image) {
      const resolved = await resolveImage(line.url_image);
      if (resolved) { prevImage = resolved; prevImagePosition = line.image_position; }
    }
    slides.push({
      time,
      text: normalizeLyricText(line.lyric),
      auxText: line.aux_lyric ? normalizeLyricText(line.aux_lyric) : null,
      cover: false,
      imageOpfsPath: prevImage ? prevImage.opfsPath : null,
      imagePosition: prevImagePosition,
    });
  }

  if (slides.length <= 1) return null; // só a capa — nada de real pra sincronizar

  slides.sort((a, b) => a.time - b.time);
  return slides;
}

async function deleteCollection(coll) {
  if (!(await appConfirm({ title: 'Excluir ' + coll.name, message: 'Excluir o que foi baixado de "' + coll.name + '" (áudios e capas) e a lista offline?', okText: 'Excluir', perigo: true }))) return;
  const recs = await AVDB.filesByFolder(coll.id);
  await purgeCatalogRecords(recs);
  await AVDB.opfsDeleteDir('folders/' + coll.id);
  collState[coll.id] = { indexSyncedAt: 0, songs: [] };
  await AVDB.setState('coll:' + coll.id, collState[coll.id]);
  const u = ui(coll.id); u.bytes = 0;
  pesoConferido.add(coll.id);   // zerado por exclusão, não por falta de medida
  salvarPesos();
  load();
}

// ---- popup de busca ----
// Debounce comum aos dois campos de busca (pasta e acervo): digitar não deve
// disparar um re-render completo por tecla.
const SEARCH_DEBOUNCE_MS = 130;
function debounce(fn, ms) {
  let t = null;
  return function debounced(...args) {
    clearTimeout(t);
    t = setTimeout(() => fn.apply(this, args), ms);
  };
}
const DIACRITICS_RE = new RegExp('[' + String.fromCharCode(0x0300) + '-' + String.fromCharCode(0x036f) + ']', 'g');
function normalizeForSearch(s) {
  return String(s || '').normalize('NFD').replace(DIACRITICS_RE, '').toLowerCase();
}

// ===== Acervo de LETRAS (texto puro, para busca) =====
// A letra deixou de depender do áudio: ela é baixada junto com o índice, como
// informação padrão do acervo. Antes, só quem tinha a música no aparelho podia
// buscá-la — e o operador que procura "aquele hino que fala em…" quase nunca
// tem os 600 baixados.
//
// É um acervo SEPARADO do `files`, e de propósito:
//   - `files[].lyrics` são SLIDES (tempo, imagem, capa) e só existem com áudio
//     baixado. É o que a projeção sincronizada consome.
//   - `lyricStore` é só TEXTO, por música, e existe para toda música do índice.
//     É o que a busca consome.
// Fundi-los faria a busca carregar tempos e caminhos de imagem à toa, e faria
// o download do índice arrastar o peso dos slides.
//
// Guardado em `state` por coleção (`lyrics:<collId>`), gravado em LOTES: são
// centenas de músicas, e reescrever o blob inteiro a cada uma tornaria o
// download quadrático.
let lyricStore = {};          // { [collId]: { [id_music]: [{a,l}] | string[] (legado) | 0 } }
let lyricSyncRunning = false;

// `0` (e não ausência) marca "já perguntamos e esta música não tem letra" —
// sem isso, toda abertura do app tentaria de novo as mesmas centenas.
const LYRIC_NONE = 0;
const LYRIC_BATCH = 25;       // músicas por gravação

function lyricStoreFor(id) { return lyricStore[id] || (lyricStore[id] = {}); }

async function loadLyricStore() {
  const cols = allCollections();
  const saved = await Promise.all(cols.map((c) => AVDB.getState('lyrics:' + c.id)));
  lyricStore = {};
  cols.forEach((c, i) => { lyricStore[c.id] = (saved[i] && typeof saved[i] === 'object') ? saved[i] : {}; });
}

function saveLyricStore(collId) {
  return AVDB.setState('lyrics:' + collId, lyricStoreFor(collId));
}

// ===== A letra é uma lista de ESTROFES, não de linhas soltas =====
// O banco já entrega assim: cada entrada de `music_{id}.lyric` **é** uma
// estrofe, com `order`, o texto (linhas separadas por `<br>`) e `aux_lyric`,
// que é o RÓTULO da seção ("Refrão", "1ª Estrofe"). Até a v5.42 guardávamos só
// as linhas achatadas — o formato de que a BUSCA precisa —, e a visualização da
// letra completa herdava esse achatamento: trinta linhas seguidas, sem respiro
// e sem dizer onde entra o refrão, que é justamente o que o operador procura
// quando abre a letra.
//
// Guardar por estrofe não custa nada à busca: ela achata na hora de indexar
// (`lyricFlatLines`). O caminho inverso — inferir estrofes de linhas soltas —
// não existe, e é por isso que a mudança é no armazenamento e não só na tela.
//
// Formato: `[{ a: rótulo|null, l: [linhas] }]`. O legado (`['linha', ...]`)
// continua sendo lido; `lyricStanzas` normaliza os dois.
function lyricIsStanzas(v) {
  return Array.isArray(v) && v.length > 0 && typeof v[0] === 'object' && v[0] !== null;
}

// Sempre `[{a, l}]`, venha do formato novo ou do antigo. Uma letra legada vira
// UMA estrofe só — que é exatamente o que ela era na tela antes disto.
function lyricStanzas(v) {
  if (lyricIsStanzas(v)) return v.map((e) => ({ a: e.a || null, l: e.l || [] }));
  if (Array.isArray(v) && v.length) return [{ a: null, l: v.filter((x) => typeof x === 'string') }];
  return null;
}

// Achata para a BUSCA (índice e casamento por trecho). O rótulo entra junto:
// "refrão" é palavra que se digita, e ignorá-la tiraria da busca um texto que
// está na letra.
function lyricFlatLines(v) {
  const est = lyricStanzas(v);
  if (!est) return null;
  const out = [];
  for (const e of est) {
    if (e.a) out.push(e.a);
    for (const ln of e.l) if (ln) out.push(ln);
  }
  return out.length ? out : null;
}

// Extrai as ESTROFES de um registro `music_{id}`, na ordem do banco. Ao
// contrário de `buildLyricSlides`, NÃO filtra por `show_slide`: uma estrofe que
// não vira slide continua sendo letra da música, e para BUSCAR isso só ajuda.
function lyricStanzasFromMeta(meta) {
  const linhas = Object.values((meta && meta.lyric) || {})
    .filter(Boolean)
    .sort((a, b) => (a.order || 0) - (b.order || 0));
  const out = [];
  for (const l of linhas) {
    const texto = normalizeLyricText(l.lyric);
    const rotulo = normalizeLyricText(l.aux_lyric).replace(/\n+/g, ' ').trim();
    const ls = texto ? texto.split('\n').map((x) => x.trim()).filter(Boolean) : [];
    if (!ls.length && !rotulo) continue;
    out.push({ a: rotulo || null, l: ls });
  }
  return out.length ? out : null;
}

// ===== Busca DENTRO da letra =====
// "Qual é o hino que fala em 'firme nas promessas'?" é a pergunta que o
// operador faz de verdade, e até aqui a busca só respondia por título e número.
//
// A letra JÁ está no aparelho: `buildLyricSlides` a grava no registro do
// arquivo (store `files`) quando a música é baixada. Então o índice sai de UMA
// leitura do IDB, sem nenhuma requisição — e funciona offline, que é o estado
// normal no meio de um culto.
//
// **Duas fontes, uma chave.** O índice é montado por `collId:id_music` e puxa
// de onde houver: do `lyricStore` (baixado com o índice — cobre os hinários
// inteiros) ou dos slides do arquivo baixado (`files[].lyrics` — cobre álbuns e
// qualquer música já no aparelho). A linha encontrada aparece no resultado
// justamente para o operador ver POR QUE aquele item casou.
let lyricIndex = null;        // Map<'collId:idMusic', { norm, lines }> | null
let lyricIndexPending = null;

// Mínimo de caracteres para a busca entrar na letra. Com menos que isso o
// trecho casaria em quase todo hino ("de", "ao") e afogaria os resultados por
// título, que é o que o operador procura na maior parte das vezes.
const LYRIC_MIN_Q = 3;

// Linhas a partir dos SLIDES de um arquivo baixado. Uma estrofe pode ter
// várias linhas (o `<br>` da API vira `\n` em normalizeLyricText); quebrar aqui
// faz o trecho exibido ser UMA linha, e não o bloco inteiro.
// Cada slide já É uma estrofe — `text` com as linhas e `auxText` com o rótulo.
// Este é o caminho do que está BAIXADO no aparelho, e ele nunca precisou de
// upgrade de formato: a estrutura sempre esteve ali, só era descartada.
function stanzasFromSlides(slides) {
  const out = [];
  for (const slide of slides || []) {
    if (!slide || slide.cover) continue;
    const ls = String(slide.text || '').split('\n').map((x) => x.trim()).filter(Boolean);
    const rotulo = String(slide.auxText || '').trim();
    if (!ls.length && !rotulo) continue;
    out.push({ a: rotulo || null, l: ls });
  }
  return out;
}

async function buildLyricIndex() {
  const map = new Map();
  let porArquivo = new Map();
  try {
    const files = await AVDB.filesAll();
    for (const f of files) {
      if (f && Array.isArray(f.lyrics) && f.lyrics.length) porArquivo.set(f.id, f.lyrics);
    }
  } catch (_) { /* sem os arquivos ainda dá para indexar o lyricStore */ }

  for (const coll of allCollections()) {
    // O índice da busca por TRECHO. Uma coleção sem letra não tem o que
    // indexar, e varrê-la é percorrer ~52 itens por série a cada reconstrução
    // para não achar nada — a mesma pergunta sem sentido do `syncLyrics`, aqui
    // sem custo de rede.
    if (!temLetra(coll)) continue;
    const store = lyricStore[coll.id] || null;
    for (const s of collSongs(coll.id)) {
      // O acervo de letras vem PRIMEIRO: é texto puro e completo. Os slides
      // são o complemento para o que ele não cobre (álbuns, músicas avulsas).
      let lines = store ? lyricFlatLines(store[s.id_music]) : null;
      if (!lines) {
        const slides = porArquivo.get(s.fileIdFull) || porArquivo.get(s.fileIdPlayback);
        if (slides) lines = lyricFlatLines(stanzasFromSlides(slides));
      }
      if (!lines || !lines.length) continue;
      map.set(coll.id + ':' + s.id_music, { norm: normalizeForSearch(lines.join('\n')), lines });
    }
  }
  return map;
}

// Constrói sob demanda e redesenha quando ficar pronto — `renderSearchResults`
// é síncrona (roda a cada tecla) e não pode esperar o IDB.
//
// ELA DEVOLVE A PROMESSA (v5.303), e o redesenho tardio continua acontecendo
// para quem a ignora: a busca segue disparando e esquecendo, e o SORTEIO
// TEMÁTICO — que manda a faixa para o telão sem tela intermediária — a espera.
// Sem isto ele sortearia com o índice pela metade, ignorando a palavra tema e
// projetando mesmo assim; ali não há redesenho que conserte depois.
function ensureLyricIndex() {
  if (lyricIndex) return Promise.resolve(lyricIndex);
  if (lyricIndexPending) return lyricIndexPending;
  lyricIndexPending = buildLyricIndex().then((m) => {
    lyricIndex = m;
    lyricIndexPending = null;
    // Só redesenha se o popup ainda estiver aberto — e pelo guarda, que ADIA
    // enquanto há gaveta aberta. Este índice fica pronto SEGUNDOS depois de o
    // operador digitar, isto é, com uma linha do resultado já aberta na mão.
    renderBuscaQuandoPuder(false);
    return m;
  }).catch(() => { lyricIndexPending = null; return null; });
  return lyricIndexPending;
}

// A letra de uma música só entra no índice quando é baixada; um download novo
// torna o índice obsoleto. Invalidar (em vez de reconstruir) evita pagar a
// leitura no meio de uma sincronização em massa.
function invalidateLyricIndex() { lyricIndex = null; }

// Linhas da letra de UMA música, das duas fontes (acervo de texto primeiro,
// slides do arquivo baixado como complemento). Assíncrona por causa do
// `fileGet`; o acervo de texto, que cobre os hinários, resolve sem esperar IDB.
async function songLyricStanzas(coll, s) {
  const store = lyricStore[coll.id];
  const doAcervo = store ? lyricStanzas(store[s.id_music]) : null;
  // O acervo de texto vem primeiro, MAS um registro legado (linhas soltas, uma
  // "estrofe" só) perde para os slides do arquivo baixado, que trazem a divisão
  // de verdade. Enquanto a fila não reescreve o legado, quem já tem a música no
  // aparelho já vê a letra dividida.
  if (doAcervo && (doAcervo.length > 1 || doAcervo[0].a)) return doAcervo;
  for (const fid of [s.fileIdFull, s.fileIdPlayback]) {
    if (!fid) continue;
    const rec = await AVDB.fileGet(fid).catch(() => null);
    if (!rec || !Array.isArray(rec.lyrics)) continue;
    const est = stanzasFromSlides(rec.lyrics);
    if (est.length) return est;
  }
  return doAcervo;
}

// Devolve a LINHA da letra que casa com a busca, ou null.
function lyricMatch(coll, s, q) {
  if (!lyricIndex || q.length < LYRIC_MIN_Q) return null;
  const e = lyricIndex.get(coll.id + ':' + s.id_music);
  if (!e || !e.norm.includes(q)) return null;
  for (const ln of e.lines) {
    if (normalizeForSearch(ln).includes(q)) return ln;
  }
  return e.lines[0];   // casou no todo mas não numa linha (busca cruzou a quebra)
}

// ===== Download das letras (roda no arranque, como o índice) =====
// TODO o acervo indexado, hinários e álbuns: "aquele hino que fala em…" e
// "aquela música do álbum que fala em…" são a mesma pergunta.
//
// HINÁRIOS PRIMEIRO na fila — são o que mais se busca, e a fila leva minutos na
// primeira abertura; interrompida, o que já desceu é o que mais importa.
//
// ADIA SÓ EM REDE MÓVEL CONHECIDA (`type === 'cellular'`), nunca
// `isConfirmedWifi()`: `navigator.connection.type` devolve `'unknown'` em boa
// parte dos aparelhos, e exigir Wi-Fi CONFIRMADO faria o recurso nunca rodar
// neles — no-op silencioso. Na dúvida, baixa. A assimetria com `syncCollection`
// é deliberada: lá são centenas de MB de áudio, aqui é JSON de texto.
// Falta letra, OU a que existe está no formato antigo (linhas soltas, sem
// estrofe). O legado entra na mesma fila: inferir estrofes a partir de linhas
// achatadas não é possível, então o upgrade custa uma releitura do `music_{id}`.
// `LYRIC_NONE` (0) NÃO entra: já sabemos que essa música não tem letra.
function songsMissingLyric(coll) {
  const store = lyricStoreFor(coll.id);
  return collSongs(coll.id).filter((s) => {
    const v = store[s.id_music];
    if (v === undefined) return true;
    return Array.isArray(v) && v.length > 0 && !lyricIsStanzas(v);
  });
}

async function syncLyrics() {
  if (lyricSyncRunning) return;
  if (networkType() === 'cellular') return;
  // Ver `rotinaDeAcervoPodeCorrer`: a varredura é adiável, o louvor não.
  if (!rotinaDeAcervoPodeCorrer()) return;

  // Hinários antes dos álbuns (ver acima). Dentro de cada grupo, a ordem do
  // acervo.
  //
  // **SÓ QUEM TEM LETRA** (v5.236). Sem esta guarda, os ~52 episódios de cada
  // série entravam na fila e cada um virava um `music_<id>` pedido ao LouvorJA
  // com um id que é do YOUTUBE — uma pergunta que aquele banco não tem como
  // responder. Falha de rede não grava `LYRIC_NONE` de propósito (ver o
  // `catch`), então elas eram repetidas a cada abertura do app, para sempre, e
  // ainda infladas no total da notificação "Letras das músicas", que o operador
  // lê. Ninguém percebia porque o modo de falhar é o mais silencioso que existe:
  // um `catch` vazio numa tarefa de segundo plano.
  const cols = allCollections()
    .filter((c) => temLetra(c) && collSongs(c.id).length)
    .sort((a, b) => (a.kind === 'hymnal' ? 0 : 1) - (b.kind === 'hymnal' ? 0 : 1));

  // Agrupado por `id_music`, e não por (coleção, música): a MESMA faixa aparece
  // em várias coletâneas, e `music_{id}` é o mesmo documento para todas. Uma
  // busca por par custaria três requisições para uma música em três álbuns —
  // aqui custa uma, e o resultado é distribuído para todas as coleções que a
  // contêm. É o que torna varrer o acervo inteiro viável.
  const porMusica = new Map();  // id_music → { nome, destinos: [collId, ...] }
  for (const coll of cols) {
    for (const s of songsMissingLyric(coll)) {
      let e = porMusica.get(s.id_music);
      if (!e) porMusica.set(s.id_music, (e = { nome: s.name, destinos: [] }));
      e.destinos.push(coll.id);
    }
  }
  const pendentes = [...porMusica.entries()].map(([id, e]) => ({ id, ...e }));
  if (!pendentes.length) return;

  lyricSyncRunning = true;
  const notifId = bgTaskStart('Letras das músicas', pendentes.length);
  let done = 0;
  let desdeGravacao = 0;
  const sujas = new Set();
  try {
    // `bgTaskEnd` DENTRO do withBgWork (mesma nota de syncGroup): o `finally`
    // dele roda antes do de fora e já limpa o registro de tarefas.
    await withBgRotina(async () => {
     try {
      await runLimited(pendentes, NET_CONCURRENCY, async (item) => {
      // A CENA ENTROU NO MEIO DA VARREDURA. A guarda da porta cobre "começar
      // com cena no ar"; esta cobre o caso NORMAL do culto — o app é aberto
      // vazio, a varredura parte, e só então o operador toca o primeiro item.
      // Sem ela, as 12 requisições continuavam até o fim do acervo. Sair aqui
      // drena a fila sem rede; o que já foi gravado fica, e a próxima passada
      // continua de onde parou. Ver `rotinaDeAcervoPodeCorrer`.
      if (!rotinaDeAcervoPodeCorrer()) return;
      bgItemStart(notifId, item.nome);
      try {
        const meta = await Louvorja.fetchList('music_' + item.id);
        const linhas = lyricStanzasFromMeta(meta) || LYRIC_NONE;
        for (const collId of item.destinos) {
          lyricStoreFor(collId)[item.id] = linhas;
          sujas.add(collId);
        }
      } catch (_) {
        // Falha de rede não vira LYRIC_NONE: sem a marca, a próxima abertura
        // tenta de novo. Marcar aqui gravaria "não tem letra" por causa de um
        // wi-fi que oscilou, e a música ficaria fora da busca para sempre.
      } finally { bgItemEnd(notifId, item.nome); }
      done++;
      bgTaskStep(notifId, done);
      if (++desdeGravacao >= LYRIC_BATCH) {
        desdeGravacao = 0;
        // Tirar a lista e limpar o conjunto ANTES de gravar. Os 6 workers
        // correm juntos: durante o `await` os outros continuam marcando
        // coleções sujas, e um `clear()` DEPOIS apagava essas marcas — a
        // letra ficava só na memória e, se aquela coleção já tivesse
        // acabado, nunca mais era marcada e a gravação final a ignorava.
        // Sintoma medido: 48 de 48 buscadas, 45 de 50 pares no disco, e um
        // álbum inteiro pela metade em ~1 de 6 aberturas.
        const lote = [...sujas];
        sujas.clear();
        await Promise.all(lote.map(saveLyricStore));
      }
      });
     } finally { bgTaskEnd(notifId); }
    });
  } finally {
    await Promise.all([...sujas].map(saveLyricStore)).catch(() => {});
    lyricSyncRunning = false;
    invalidateLyricIndex();   // o acervo cresceu: a busca precisa reindexar
  }
}

// Busca GLOBAL (botão de lupa): escopo null = varre todas as coleções.
/**
 * ===== AS DUAS PORTAS DA BIBLIOTECA (v1.5.0) =====
 *
 * Pedido do operador: *"sua forma de abertura da biblioteca agora vai ser
 * através do foco na barra de texto, ou no toque do que seria o botão de fechar
 * a biblioteca (que quando fechado seria uma seta) … no caso de abrir pelo
 * foco, já abre o teclado junto, se abrir pelo botão de abrir, ela abre sem o
 * foco de digitação"*.
 *
 * São duas INTENÇÕES diferentes, e é por isso que elas abrem diferente:
 * *"procurar o hino 37"* chega pelo campo e quer o teclado; *"ver o que eu
 * tenho"* chega pela seta e quer a lista inteira à vista, sem metade da tela
 * ocupada por um teclado que ninguém pediu.
 *
 * `comFoco` é explícito e não derivado de `document.activeElement`: quando o
 * ouvinte de `focus` chama esta função o campo JÁ está focado, e quando o botão
 * a chama ele pode estar focado por um toque anterior — as duas leituras dariam
 * a mesma resposta e ela seria a errada em um dos dois casos.
 */
// ===== O VÉU DAS BORDAS DA LISTA (v1.5.16) =====
//
// Pedido do operador: *"um efeito de blur na borda interna superior ou
// inferior, quando algum elemento da tela ir para debaixo dessa borda. Para
// melhor perceber que há mais itens no scroll da lista."*
//
// O véu inteiro é CSS (ver "O VÉU DAS BORDAS DA LISTA" em `controle.css`); o
// que o JS responde é a única coisa que a folha não sabe: **há conteúdo escondido
// deste lado?** Nos extremos não há, e um borrão sobre a primeira linha com a
// lista no topo é o app dizendo que há mais quando não há.
//
// ESCREVE SÓ QUANDO O BOOLEANO VIRA. `scroll` dispara dezenas de vezes por
// gesto; `classList.toggle` com o mesmo valor é barato, mas a comparação
// explícita é o que garante ZERO trabalho de estilo no caso comum (rolar no
// meio da lista, onde os dois já estão ligados).
//
// A FOLGA DE 2px não é superstição: `scrollTop` é fracionário em telas de alta
// densidade, e o fim da lista costuma dar `scrollHeight - scrollTop -
// clientHeight` de 0,5px. Com zero, o véu de baixo piscava no último pixel.
function acertarVeuDaLista() {
  const el = hymnResultsEl;
  if (!el) return;
  const acima = el.scrollTop > 2;
  const abaixo = el.scrollHeight - el.scrollTop - el.clientHeight > 2;
  if (el.classList.contains('tem-acima') !== acima) el.classList.toggle('tem-acima', acima);
  if (el.classList.contains('tem-abaixo') !== abaixo) el.classList.toggle('tem-abaixo', abaixo);
}
// Coalescido por quadro: o `scroll` de um gesto chega mais de uma vez por
// quadro e a conta acima lê `scrollHeight`, que força layout.
let veuPedido = false;
function pedirVeuDaLista() {
  if (veuPedido) return;
  veuPedido = true;
  requestAnimationFrame(() => { veuPedido = false; acertarVeuDaLista(); });
}
// UM ouvinte, no boot: `#hymnResults` é o MESMO nó entre uma abertura e a
// seguinte (é a razão de o `openHymnSearch` precisar zerar o `scrollTop` à
// mão), então registrar por abertura empilharia ouvintes para sempre.
// `passive` porque ele não cancela nada — sem isso o Chromium não pode
// adiantar a rolagem.
if (hymnResultsEl) hymnResultsEl.addEventListener('scroll', pedirVeuDaLista, { passive: true });

function openHymnSearch(comFoco) {
  hymnSearchInputEl.placeholder = 'Nome, número ou trecho da letra…';
  // (O CAMPO É LIMPO AO FECHAR, não aqui — ver `closeHymnSearch`. Continua
  //  havendo um `renderSearchResults('')` nesta abertura porque o desenho do
  //  acervo é o que a Biblioteca mostra, e ele depende de estado que o
  //  `resetarBiblioteca` acabou de zerar.)
  renderSearchResults('');
  hymnSearchPopupEl.classList.add('open');
  // NO `body`, e não só na camada: quem sai de cena com o teclado é a CAIXA DE
  // CONTROLES, que não é descendente dela.
  document.body.classList.add('lib-aberta');
  renderLibToggle();
  medirBarraDaBiblioteca();
  // ===== A LISTA ABRE NO TOPO (v5.280) =====
  //
  // Decisão do operador: *"ao invés de ter um scroll de tela inteira, deixar
  // apenas os itens abaixo da barra de pesquisa ficarem dentro de um scroll, e
  // apenas rolar esse scroll para o topo quando a biblioteca é aberta"*.
  //
  // A rolagem SEMPRE foi só da lista — a barra e o ✕ vivem fora dela —, e o
  // que faltava é esta linha: `#hymnResults` é o mesmo nó entre uma abertura e
  // a seguinte, então ele guardava a posição de rolagem da vez anterior e a
  // Biblioteca reabria no meio de um hinário. Isto REVOGA o mecanismo da
  // v5.278 (a camada fixa seguindo a viewport visual): com a barra no topo da
  // folha e nada rolando além da lista, não há o que acompanhar.
  hymnResultsEl.scrollTop = 0;
  // O véu conferido AQUI e não só no `scroll`: um render muda o `scrollHeight`
  // sem que nenhuma rolagem aconteça, e a Biblioteca abre com a lista parada.
  acertarVeuDaLista();
  // O TECLADO SOBE NOS DOIS MODOS, um tempo DEPOIS da tela (260 ms: o fade de
  // .25s mais um quadro). Simultâneos, o teclado ENCOLHE a faixa visível
  // (`--kb`/`--vv-top`) enquanto a folha ainda aparece — dois movimentos sobre
  // a mesma peça, que é o que se lê como piscar.
  //
  // ARMADILHA CONHECIDA, e o risco fica dito: `focus()` adiado sai da interação
  // do toque, e o WebView pode aceitar o foco sem abrir o teclado. Nenhum teste
  // daqui prova o contrário (Chromium de mesa não tem teclado virtual). O que
  // sustenta o adiamento é a janela de ATIVAÇÃO TRANSITÓRIA do Chromium, que é
  // de segundos. Se o teclado parar de subir no aparelho, a causa é esta linha
  // e a volta é uma só: `hymnSearchInputEl.focus()` aqui, síncrono.
  clearTimeout(hymnFocoTimer);
  hymnFocoTimer = null;
  // SEM FOCO NA PORTA DA SETA. O adiamento continua valendo para a outra porta
  // — e só para ela, porque ali o campo já está focado e o que o `focus()`
  // atrasado faz é reafirmar o foco depois de a janela ter subido, que é o que
  // impede o teclado de encolher a tela no meio da animação.
  if (!comFoco) return;
  hymnFocoTimer = setTimeout(() => {
    hymnFocoTimer = null;
    hymnSearchInputEl.focus();
  }, ABRIR_TECLADO_MS);
}

/**
 * AS DUAS MEDIDAS DA JANELA (v1.5.2), e as duas saem de uma leitura só.
 *
 * A Biblioteca é uma coluna `[barra][lista]` de tela cheia. Aberta, ela é
 * `translateY(0)` — a barra no topo da tela. Fechada, ela desce até a barra
 * pousar no LUGAR dela: o topo da caixa de controles, acima do nome da mídia em
 * exibição (pedido do operador na v1.5.2 — na v1.5.1 o lugar era a base da
 * tela, e ali a conta era `100% - a barra`, sem medida nenhuma de posição).
 *
 *  · **`--lib-bar-h`** — a altura da barra. É o que a `.bottombar` RESERVA no
 *    `padding-top`, isto é, o lugar em que a barra pousa.
 *  · **`--lib-caixa-h`** — a altura da CAIXA DE CONTROLES, de onde o CSS deduz o
 *    topo dela sem perguntar onde ele está (ver `.popup-sheet--lib`).
 *
 * (O RECORTE da folha fechada — o que impede a lista e o fundo dela de caírem
 * por cima do transporte, em pixel e em toque — NÃO entra aqui: ele é medido no
 * espaço da própria folha, `100% - a barra`, e o único número que ele pede é a
 * altura dela. Uma versão anterior o media na tela, e a transição com atraso que
 * ele precisa ter prendia toda REMEDIÇÃO por 0,28 s — num oráculo sem quadros
 * desenhados, para sempre. Ver `.popup-sheet--lib`.)
 *
 * SÃO AS DUAS ALTURAS, e nenhuma POSIÇÃO — é a correção da v1.5.3, e ela veio de
 * um relato: *"o alinhamento da barra está completamente errado, está sendo
 * cortado e deslocado em suas animações … você pode estar usando números fixos
 * considerando a sua tela de testes, mas a tela do smartphone tem variação de
 * tamanho, pixels e espaços variáveis"*. O que se media era o TOPO da caixa, uma
 * coordenada de tela — e uma coordenada envelhece por caminhos que ninguém
 * observa: o teclado encolhendo o corpo do app, a área segura entrando depois do
 * primeiro layout, a viewport mudando de altura sem a caixa mudar de tamanho.
 * **O `ResizeObserver` vigia TAMANHO, e nada disso muda o tamanho da caixa: muda
 * o lugar dela.** Medindo só alturas, o instrumento e a grandeza passam a ser a
 * mesma coisa, e quem sabe onde a caixa está é o CSS, que refaz a conta a cada
 * quadro.
 *
 * MEDIDAS e não escritas no CSS: a barra muda de altura com o corpo de fonte do
 * sistema, e a caixa muda de altura com a proporção da preview, com o título em
 * duas linhas e com o modo do app.
 *
 * PELO `offsetHeight`, nunca pelo `getBoundingClientRect`: a janela está
 * TRANSLADADA quando fechada e a caixa do cliente vem transformada junto — a
 * conta se alimentaria do próprio resultado. Os `offset*` são do layout, que é o
 * que a translação não move.
 *
 * ELAS ANIMAM, ENTÃO SÓ SE ESCREVE O QUE MUDOU. A translação transiciona (e o
 * recorte, com atraso), e um `ResizeObserver` que reescreve o mesmo valor
 * dispara outra passada — o laço que o navegador denuncia como
 * "ResizeObserver loop". Escrever só a mudança fecha isso na origem.
 *
 * NA RAIZ e não no popup: quem lê `--lib-bar-h` é a `.bottombar`, que não é
 * descendente dele.
 */
function medirBarraDaBiblioteca() {
  if (!libBarEl || !bottombarEl) return;
  const alturaDaBarra = libBarEl.offsetHeight;
  // Barra sem altura = folha ainda não montada, ou o app escondido. Escrever 0
  // encostaria a janela inteira na tela e tiraria a reserva da caixa de
  // controles; a medida boa que já está lá é a resposta certa.
  if (!alturaDaBarra) return;
  const raiz = document.documentElement;
  let mudou = false;
  const escrever = (nome, px) => {
    const valor = Math.round(px) + 'px';
    // SÓ O QUE MUDOU: ver o bloco acima — reescrever o mesmo valor num
    // `ResizeObserver` é o laço que o navegador denuncia.
    if (raiz.style.getPropertyValue(nome) === valor) return;
    raiz.style.setProperty(nome, valor);
    mudou = true;
  };
  escrever('--lib-bar-h', alturaDaBarra);
  // A RESERVA ENTRA ANTES DA ALTURA SER LIDA: o `padding-top` da caixa sai desta
  // altura, então medi-la antes de escrevê-la mediria uma caixa que ainda não
  // reservou o lugar da barra.
  const alturaDaCaixa = bottombarEl.offsetHeight;
  // Caixa sem altura é ELA FORA DA TELA — o Modo Fácil a esconde, e desde a
  // v1.5.6 o teclado com a Biblioteca aberta também. Zero não é uma medida, é a
  // AUSÊNCIA de uma: escrevê-lo levaria a barra à base da tela, e a medida boa
  // que já está no lugar é a resposta certa para quando a caixa voltar. Quem
  // responde por esses dois estados é o CSS, que manda a janela até a base sem
  // consultar este número.
  if (alturaDaCaixa) escrever('--lib-caixa-h', alturaDaCaixa);
  // FORA do `if`: uma mudança só na altura da BARRA também precisa desarmar a
  // transição, e ficar presa atrás da caixa oculta era o mesmo defeito por outra
  // porta.
  if (mudou) semAnimarAJanela();
}

/**
 * UMA REMEDIÇÃO NÃO É UMA ANIMAÇÃO (v1.5.2).
 *
 * A janela ANIMA entre dois lugares — o topo da tela e o lugar da barra —, e o
 * segundo é uma MEDIDA. Uma transição não distingue as duas razões de o valor
 * mudar: com o tempo ligado, remedir vira a barra DESLIZANDO até o lugar novo
 * enquanto a caixa de controles já saltou para lá, e o que se vê é a barra
 * correndo atrás da caixa.
 *
 * FOI MEDIDO ANTES DE CHEGAR AO APARELHO, e num lugar que não desenha quadros:
 * no `controles-layout.test.mjs` a transição atrasada ficou PARADA no valor de
 * partida, e a janela FECHADA cobria a preview inteira — o toque na cortina
 * caindo na lista da Biblioteca, com a Biblioteca fechada.
 *
 * A resposta é desligar o tempo no quadro em que a medida entra: a classe sai
 * (e com ela `--lib-anim`), o valor novo é aplicado no mesmo recálculo — uma
 * transição usa a duração do estilo DEPOIS da mudança —, e a classe volta no
 * quadro seguinte, quando já não há nada a animar.
 *
 * É O MESMO MECANISMO DA CARGA, e por isso não há dois: a primeira medida
 * também é uma mudança de valor, e é ela que arma a animação pela primeira vez.
 * MEDIDO: a barra mede 28,6px no primeiro quadro (antes de a folha assentar) e
 * 51px depois — sem isto, a correção seria a janela varrendo a tela na abertura
 * do app.
 */
let libRearmar = 0;
function semAnimarAJanela() {
  document.body.classList.remove('lib-pronta');
  cancelAnimationFrame(libRearmar);
  libRearmar = requestAnimationFrame(() => {
    libRearmar = requestAnimationFrame(
      () => document.body.classList.add('lib-pronta'));
  });
}

/**
 * ===== A BIBLIOTECA VOLTA AO ESTADO PADRÃO AO FECHAR (v1.1.4) =====
 *
 * Pedido do operador: *"inclusive toda vez que fechar a biblioteca, reset para o
 * estado padrão"*.
 *
 * O que ele resolve é ACÚMULO: `grupoAberto`, `favAberto`, `pastaAberta` e o
 * `expanded` de cada card sobrevivem ao fechamento do popup — o nó é o mesmo
 * entre uma abertura e a seguinte (a mesma razão do `scrollTop = 0` do
 * `openHymnSearch`). Sem isto, a Biblioteca reabria com o hinário de 613 hinos
 * escancarado de uma consulta de meia hora atrás, e o operador pagava dois
 * toques para voltar a ver o índice. Com uma série nova a cada ano, a tela em
 * que ele reabre é a que menos cabe.
 *
 * **É a única definição de "estado padrão" que existe**, e ela é a mesma que o
 * módulo carrega: nada aberto. Escrever a lista de zeragens aqui e os valores
 * iniciais lá em cima seria duas verdades sobre a mesma coisa — daí os
 * comentários dos dois lados apontarem um para o outro.
 *
 * Por `collUI` e não por `allCollections()`: quem tem estado é o que já foi
 * tocado, e esta função roda também durante a CARGA do módulo (via
 * `renderSimpleGate` → `closeHymnSearch`), quando ainda não há catálogo.
 */
function resetarBiblioteca() {
  grupoAberto = '';
  favAberto = false;
  pastaAberta = null;
  // A animação de abertura é um RECADO de um toque que já não vale: reabrir a
  // Biblioteca veria as seções "abrindo" sozinhas por um gesto de outra sessão.
  gruposAnimar.clear();
  for (const id of Object.keys(collUI)) {
    const u = collUI[id];
    u.expanded = false;
    // A paginação zera junto, como no acordeão do card: reabrir um hinário que
    // ficou rolado até o fim traria as 613 linhas de uma vez.
    u.shown = 0;
    u.animarAbertura = false;
  }
}

function closeHymnSearch() {
  // O FOCO PENDENTE MORRE COM A TELA, e isto não é higiene: fechar a Biblioteca
  // dentro da janela do adiamento deixaria o `focus()` cair num campo que já
  // saiu de cena — o teclado subiria sozinho por cima do app, sem nada na tela
  // que o explicasse, e a única saída seria o voltar do Android.
  clearTimeout(hymnFocoTimer);
  hymnFocoTimer = null;
  hymnSearchPopupEl.classList.remove('open');
  document.body.classList.remove('lib-aberta');
  renderLibToggle();
  // O CAMPO PERDE O FOCO ao fechar: sem isto o teclado fica de pé sobre o app
  // com a janela já fora de cena — a mesma classe de defeito do foco pendente
  // logo acima, pelo outro caminho.
  try { hymnSearchInputEl.blur(); } catch (_) {}
  // ===== E O CAMPO SE LIMPA AQUI, NÃO NA ABERTURA (v1.5.6) =====
  // Relato do operador: *"ajuste a caixa de buscas para que ela resete seu texto
  // quando for fechada, pois agora ela está mantendo a palavra de filtro após
  // ser fechada e limpando apenas quando aberta"*.
  //
  // A limpeza na abertura era certa enquanto o campo VIVIA DENTRO da Biblioteca
  // (até a v1.5.0): fechada, ninguém o via, e o texto velho morria antes de
  // aparecer. **Hoje a barra fica à vista o culto inteiro**, na caixa de
  // controles — o filtro da busca anterior é a primeira coisa que o operador lê
  // quando volta ao transporte, e ele descreve uma tela que não está mais lá.
  //
  // É a mesma razão que já trouxe o `resetarBiblioteca` para cá, e agora vale
  // para o texto pelo motivo oposto: aquele se faz no fechamento para não ser
  // VISTO acontecendo, este para não ficar VISÍVEL depois.
  hymnSearchInputEl.value = '';
  // FECHAR é o momento certo, e não abrir: aqui a tela já saiu de cena, então
  // nada do que se colapsa é visto colapsando. No `openHymnSearch` o mesmo
  // trabalho apareceria como a Biblioteca se desmontando na frente do operador.
  resetarBiblioteca();
}

// Duas telas no mesmo popup, e **o campo é a chave**: vazio = o ACERVO (as
// categorias, pílulas e cards, com as músicas de cada coleção dentro do próprio
// acordeão); com texto = a lista de músicas que casam, de todo o acervo.
//
// Não há mais um "modo coleção" separado (v5.45). Entrar numa coleção era trocar
// de tela e voltar; agora o álbum abre no lugar, com o acervo inteiro ainda
// visível em volta — o operador não perde onde estava para ver o que tem dentro.
function searchIsBrowsing(q) { return !q; }

// A casca do `renderSearchResults`, na forma que o `renderCollectionsList` já
// usa: o miolo tem saídas antecipadas (índice vazio, zero resultados) e o véu
// das bordas precisa ser reconferido depois de TODAS elas — um render muda o
// `scrollHeight` sem que nenhuma rolagem aconteça. `finally` porque uma exceção
// no miolo não pode deixar o véu descrevendo a lista anterior.
function renderSearchResults(query) {
  try { renderSearchResultsMiolo(query); } finally { acertarVeuDaLista(); }
}

function renderSearchResultsMiolo(query) {
  const q = normalizeForSearch(query).trim();
  // Digitou outra coisa: os resultados do YouTube da busca anterior saem de
  // cena. Deixá-los ali embaixo de um termo novo é oferecer a resposta errada.
  if (!ytBuscando && ytBuscaItens && ytBuscaTermo !== (query || '').trim()) ytBuscaItens = null;
  if (searchIsBrowsing(q)) {
    hymnResultsEl.innerHTML = '';
    renderCollectionsList(hymnResultsEl, () => renderSearchResults(hymnSearchInputEl.value));
    // (A linha de uso do disco saiu na v5.239, a pedido do operador: *"esse
    // valor é falso, irreal e disputa com os cabeçalhos que já dizem o peso
    // atual e total dos arquivos"*. E ele está certo pela régua da própria
    // medida: `navigator.storage.estimate()` fala do ORIGIN inteiro — com
    // padding deliberado contra ataques de tempo — e a cota é o que o navegador
    // ACHA que pode ceder, não o que o cartão tem. Os dois números eram
    // arredondados sem casa acima de 10, e nenhum dos dois respondia a pergunta
    // que a tela já responde uma linha acima: quanto ESTE acervo pesa.)
    return;
  }
  const cols = allCollections();
  // A letra só é varrida com busca de verdade (ver LYRIC_MIN_Q).
  if (q.length >= LYRIC_MIN_Q) ensureLyricIndex();

  const porNome = [];    // { coll, song }
  const porLetra = [];   // { coll, song, hit }
  let totalIndexed = 0;
  for (const coll of cols) {
    const songs = collSongs(coll.id);
    const numera = collNumbersSongs(coll);
    totalIndexed += songs.length;
    for (const s of songs) {
      // `_norm` é calculado UMA vez, ao montar o índice (fetchCollectionIndex /
      // loadCollections). Normalizar aqui significava três alocações de string
      // por música a cada tecla, sobre um nome que nunca muda — e a busca
      // global varre os dois hinários (~1100) mais todos os álbuns indexados.
      const norm = s._norm || (s._norm = normalizeForSearch(s.name));
      // Busca por NÚMERO só onde o número identifica a música: digitar "3"
      // traria a faixa 3 de cada álbum indexado, dezenas de resultados que
      // ninguém pediu, empurrando o hino 3 para o fim da lista.
      if (q === '' || norm.includes(q) || (numera && String(s.track) === q)) {
        porNome.push({ coll, song: s });
        continue;   // já casou pelo título: não procura na letra à toa
      }
      const hit = lyricMatch(coll, s, q);
      if (hit) porLetra.push({ coll, song: s, hit });
    }
  }
  // Título ANTES de letra, sempre. Quem digita "Firme nas Promessas" quer o
  // hino de mesmo nome no topo — não os quinze que citam a expressão numa
  // estrofe. Dentro de cada grupo a ordem do acervo é preservada.
  const matches = porNome.concat(porLetra);
  hymnResultsEl.innerHTML = '';
  if (totalIndexed === 0) {
    hymnResultsEl.innerHTML = '<li class="empty">Índice da biblioteca ainda não carregado.'
      + '<br>Precisa de internet na primeira vez.</li>';
    appendYoutubeSearch(query);
    return;
  }
  if (matches.length === 0) {
    // "na biblioteca" não é detalhe: logo abaixo vem o cabeçalho dos resultados
    // do YouTube, e sem dizer ONDE não achou a frase parece negar a busca
    // inteira. E não diz "música" (v5.236) — a Biblioteca também guarda vídeo, e
    // negar o que não foi procurado manda o operador buscar noutro lugar.
    hymnResultsEl.innerHTML = '<li class="empty">Nada encontrado na biblioteca.</li>';
    appendYoutubeSearch(query);
    return;
  }
  // Teto na busca: ela varre milhares de músicas de todos os álbuns, e
  // renderizar tudo a cada tecla travaria o campo. Folhear uma coleção INTEIRA
  // não passa mais por aqui — é o acordeão do card, que lista tudo.
  const LIMIT = 60;
  matches.slice(0, LIMIT).forEach((m) => hymnResultsEl.appendChild(hymnResultRow(m.coll, m.song, m.hit)));
  if (matches.length > LIMIT) {
    const li = document.createElement('li'); li.className = 'empty';
    li.textContent = '+' + (matches.length - LIMIT) + ' resultado(s). Refine a busca.';
    hymnResultsEl.appendChild(li);
  }
  appendYoutubeSearch(query);
}

// ===== "Pesquisar <texto> no YouTube", no fim da busca do acervo =====
// O acervo é o LouvorJA, e ele não tem tudo: um louvor especial gravado pelo
// coral da igreja, um clipe, um hino numa versão específica. Hoje a saída é
// sair do app, abrir o YouTube, digitar tudo de novo e compartilhar de volta —
// e o "digitar tudo de novo" acontece com o texto já digitado aqui, na tela em
// que se acabou de descobrir que a música não está no acervo. Esta linha é o
// atalho desse caminho: leva a busca pronta e devolve o operador ao ponto em
// que o compartilhamento (`ShareIntake`) já sabe receber o vídeo.
//
// Ela fecha o fim da lista em TODOS os desfechos da busca — inclusive (e
// principalmente) "Nenhuma música encontrada", que é justamente quando a
// pergunta "e agora?" aparece.
// Estado da busca do YouTube dentro do acervo: `null` = nem pediram; array =
// resultados do termo em `ytBuscaTermo`. Zerado a cada tecla nova (ver o
// chamador), porque uma lista de resultados de OUTRA busca embaixo do campo é
// pior que nenhuma.
let ytBuscaTermo = '';
let ytBuscaItens = null;
let ytBuscando = false;

function appendYoutubeSearch(texto) {
  const termo = (texto || '').trim();
  if (!termo) return;
  // No navegador é sempre `window.open`; no app, `AVNative.openExternal` — a
  // navegação para fora do origin é BLOQUEADA no WebView
  // (WebViewFactory.shouldOverrideUrlLoading).

  // Onde o shell sabe pesquisar, o BOTÃO SAIU (v5.91). Ele existia para quem
  // decidisse antes de rolar — mas chegar no fim da lista já dispara a busca
  // sozinho, e as duas coisas juntas viraram um botão que quase sempre era
  // apertado depois de a busca já ter começado, ou que simplesmente não tinha
  // mais função. No lugar dele fica uma LINHA DE ESTADO: ela é a sentinela que
  // o observador vigia (precisa de altura de verdade), o sinal de que a busca
  // está em curso e, depois, o rótulo que separa o acervo dos resultados do
  // YouTube. O botão continua onde ele é a ÚNICA saída: navegador e shell < 18,
  // que não sabem pesquisar de dentro do app e abrem o YouTube por fora.
  const aquiDentro = !!window.__NATIVE__;
  const li = document.createElement('li');
  if (aquiDentro) {
    const buscou = ytBuscaItens && ytBuscaTermo === termo;
    // CABEÇALHO DE SEÇÃO, não uma linha de aviso solta (v5.92): o que vem
    // abaixo dele não é mais o acervo, e a lista não dava esse degrau — as duas
    // origens vinham coladas, com a mesma anatomia de linha, e só o nome do
    // canal no subtítulo denunciava a troca. O filete em cima é a separação; o
    // alinhamento à esquerda e o peso são o que fazem ler como título de seção
    // e não como mais um item.
    li.className = 'yt-head';
    if (buscou) {
      li.textContent = ytBuscaItens.length
        ? 'Resultados do YouTube:'
        : 'Nada encontrado no YouTube.';
    } else {
      // Ainda não buscou, ou está buscando: os dois estados desenham a mesma
      // coisa de propósito. A linha só é VISTA quando a lista chega ao fim, e
      // ver a linha é o que dispara a busca — o intervalo entre uma coisa e
      // outra é o antirruído de 500 ms, não uma promessa em falso.
      const anel = document.createElement('span');
      anel.className = 'dl-ring';
      const txt = document.createElement('span');
      // Sem repetir o termo entre aspas: ele era necessário no BOTÃO, que
      // prometia levar AQUELE texto para fora do app. Numa linha de estado logo
      // abaixo do campo em que o operador acabou de digitar, ele só faz a
      // frase quebrar em duas linhas e desalinhar o anel.
      txt.textContent = 'Procurando no YouTube…';
      li.append(anel, txt);
    }
  } else {
    const btn = document.createElement('button');
    btn.className = 'yt-search-btn';
    btn.innerHTML = searchIconSvg();
    const txt = document.createElement('span');
    txt.className = 'yt-search-txt';
    // O termo entre aspas é o que diz que a busca vai levar ISTO, e não abrir o
    // YouTube na página inicial.
    txt.textContent = 'Pesquisar “' + termo + '” no YouTube';
    btn.appendChild(txt);
    btn.addEventListener('click', () => buscarNoYoutube(termo, true));
    li.appendChild(btn);
  }
  hymnResultsEl.appendChild(li);
  // CHEGAR NO FIM DA LISTA JÁ PESQUISA. Rolar até o fim do que o acervo tem é
  // exatamente o gesto de quem não achou o que queria.
  armarAutoBuscaYt(li, termo);

  // Os RESULTADOS, na mesma lista — é isto que dispensa sair do app. Só do
  // termo atual: uma lista de outra busca embaixo do campo é pior que nenhuma.
  if (ytBuscaItens && ytBuscaTermo === termo) {
    // Vazio: quem já disse isso foi a própria linha de estado (ou, no caminho
    // do botão, a linha abaixo).
    if (!ytBuscaItens.length) {
      if (!aquiDentro) {
        const vazio = document.createElement('li');
        vazio.className = 'empty';
        vazio.textContent = 'Nada encontrado no YouTube.';
        hymnResultsEl.appendChild(vazio);
      }
      return;
    }
    ytBuscaItens.forEach((r) => hymnResultsEl.appendChild(ytResultRow(r)));
    marcarYtProntos(ytBuscaItens);
  }
}

// O resultado que JÁ está no aparelho nasce marcado como concluído. O ✓ passa
// a dizer as duas coisas ao mesmo tempo — "acabou de baixar" e "já estava
// aqui" —, que é a informação de que o operador precisa antes de escolher o
// destino: tocar agora não vai custar um download. Assíncrono de propósito: a
// lista não espera pelo IDB, e o estado mora no Map (`ytEstado`), então
// sobrevive ao próximo render.
async function marcarYtProntos(itens) {
  // As consultas são independentes (índice `youtubeId`, sem blob) — em
  // paralelo, a página inteira de resultados é respondida no tempo de UMA ida
  // ao IDB, não de vinte em série.
  await Promise.all(itens.map(async (r) => {
    if (!r || !r.id || ytEstado.has(r.id)) return;
    const rec = await AVDB.mediaByYoutube(r.id);
    if (rec && rec.blob) setYtEstado(r.id, 'pronto');
  }));
}

// CANCELAR O DOWNLOAD EM CURSO (v5.131 · shell 28).
//
// O que o shell pode parar é o download; a EXTRAÇÃO (segundos, antes do
// primeiro byte) segue até o fim e só então o pedido é notado. Na prática o
// operador toca durante o download, que é a parte longa.
//
// Quem foi cancelado entra neste conjunto para o desfecho ser SILENCIOSO: a
// ponte devolve `null` como em qualquer falha, e sem esta marca o `ytAcao`
// pintaria a linha de vermelho e diria que deu erro — para algo que o próprio
// operador pediu.
const ytCancelados = new Set();

/** O aparelho sabe parar um download? (o `ytCancel` é do shell 28.) */
function podeCancelarDownload() {
  // Sem o método na ponte não há o que oferecer: um "cancelar" que só some com
  // a marca da tela enquanto o aparelho continua baixando centenas de MB é
  // pior que não ter botão, porque o operador acredita que parou.
  return !!window.__NATIVE__;
}

/**
 * O NÚCLEO DO CANCELAMENTO, e ele é um só para os três lugares onde o operador
 * pode pedir (v5.191): a linha do resultado da busca, o cartão sobre a preview
 * e a linha provisória do Cronograma.
 *
 * `aindaVale` é a segunda leitura do estado, feita DEPOIS da pergunta: o
 * download pode ter terminado enquanto o diálogo estava aberto, e um pedido que
 * chegasse ao shell depois do fim ficaria armado contra o PRÓXIMO download do
 * mesmo vídeo.
 *
 * **E ele esquece a INTENÇÃO** — é essa linha que impede o vídeo cancelado de
 * ressuscitar no lançamento seguinte (ver `resgatarDownloads`). Sem ela, "parei
 * o download" durava até o operador fechar o app.
 */
async function cancelarDownload({ link, youtubeId, nome, soAudio, aindaVale }) {
  if (!podeCancelarDownload() || !link) return false;
  if (aindaVale && !aindaVale()) return false;
  const ok = await appConfirm({
    title: 'Cancelar o download?',
    message: (nome || 'Este vídeo') + '\n\nO que já baixou é descartado.',
    okText: 'Cancelar download',
    cancelText: 'Continuar baixando',
  });
  if (!ok || (aindaVale && !aindaVale())) return false;
  if (youtubeId) ytCancelados.add(youtubeId);
  try { AVNative.ytCancel(link); } catch (_) { /* shell antigo: a guarda acima já barrou */ }
  await esquecerIntencao(link, !!soAudio);
  if (youtubeId) setYtEstado(youtubeId, null);
  return true;
}

async function cancelarDownloadYt(r) {
  if (!r || !r.id) return;
  const parou = await cancelarDownload({
    link: r.url,
    youtubeId: r.id,
    nome: r.name,
    soAudio: false,
    aindaVale: () => (ytEstado.get(r.id) || {}).estado === 'baixando',
  });
  // A FORMA não é conhecida aqui — a linha da busca não sabe se o que está em
  // curso é o download do vídeo ou o do áudio —, então o cancelamento esquece
  // as DUAS intenções possíveis do mesmo link: é o que "cancelar este vídeo"
  // quer dizer. Só quando ele de fato aconteceu: quem escolheu "continuar
  // baixando" não pode perder a intenção que faria o resgate funcionar.
  if (parou) await esquecerIntencao(r.url, true);
}

// O estado de cada resultado (`baixando` / `pronto`) vive num Map, e não na
// classe do nó: a lista do acervo é RECONSTRUÍDA a cada tecla e a cada
// redesenho, e uma classe escrita no elemento sumiria no próximo render — com o
// download ainda correndo. É a mesma razão do `songRowBusy` das músicas.
const ytEstado = new Map();
// Existe alguma LINHA na tela mostrando este vídeo? É por ela que todo o
// retorno do YouTube acontece — o anel de download, o ✓ e o vermelho da falha
// moram na miniatura do resultado.
//
// A pergunta passou a importar na v5.137, quando um link COMPARTILHADO ganhou a
// mesma folha de escolhas da busca: ali não há busca aberta atrás, então não há
// miniatura nenhuma para pintar, e um download de minutos terminaria em
// silêncio absoluto — que é exatamente o que a v5.112 tirou deste caminho.
function ytLinhaVisivel(id) {
  // Comparação por `dataset`, sem seletor de atributo — o mesmo padrão de
  // `setYtEstado`/`setSongRowBusy`: montar um seletor a partir de dado é o
  // tipo de coisa que quebra calada no dia em que um id trouxer outro
  // caractere.
  if (!id) return false;
  return [...document.querySelectorAll('.yt-result')].some((li) => li.dataset.yt === id);
}

// De qual LINHA DE COLEÇÃO cada vídeo do YouTube veio (id → chave de
// `songRowKey`). Só episódios de série entram aqui; um resultado da busca não
// tem linha de coleção nenhuma. Vive tanto quanto a página, como o `ytEstado`
// ao lado: são poucas entradas, e esquecê-las custaria o sinal no redesenho.
const ytLinhas = new Map();
function setYtEstado(id, estado, pct) {
  if (estado) ytEstado.set(id, { estado, pct: typeof pct === 'number' ? pct : -1 });
  else ytEstado.delete(id);
  document.querySelectorAll('.yt-result').forEach((li) => {
    if (li.dataset.yt !== id) return;
    pintarYtLinha(li, ytEstado.get(id));
  });
  // E A LINHA DA COLEÇÃO, quando o vídeo veio de uma (ver `serieComoYoutube`).
  // O anel dela é montado DENTRO da linha, então a marca sobrevive ao redesenho
  // do acervo — que roda a cada 400 ms durante uma sincronização.
  const chave = ytLinhas.get(id);
  if (chave) {
    const reg = ytEstado.get(id);
    const ocupada = !!reg && reg.estado === 'baixando';
    // Espelhar em vez de somar: este ponto é chamado várias vezes com o MESMO
    // estado (o `onPct` bate a cada fatia), e um contador incrementado a cada
    // batida nunca voltaria a zero — o anel ficaria girando para sempre.
    if (ocupada !== songRowBusy.has(chave)) setSongRowBusyKey(chave, ocupada);
  }
}
// Quanto tempo a linha fica marcada como falha antes de voltar ao normal. Curto
// o bastante para não parecer permanente (o vídeo continua lá, e tentar de novo
// costuma funcionar), longo o bastante para ser visto por quem estava olhando a
// tela quando o download terminou.
const YT_ERRO_MS = 4000;
function pintarYtLinha(li, reg) {
  li.classList.toggle('baixando', !!reg && reg.estado === 'baixando');
  li.classList.toggle('pronto', !!reg && reg.estado === 'pronto');
  li.classList.toggle('erro', !!reg && reg.estado === 'erro');
  const t = li.querySelector('.dl-pct');
  if (t) t.textContent = (reg && reg.estado === 'baixando' && reg.pct >= 0) ? reg.pct + '%' : '';
}

// A folha de ações do resultado — as MESMAS três escolhas das músicas do
// acervo, pela mesma folha (`#songMenuPopup`) e com os mesmos ícones. Antes o
// toque baixava direto e pronto: o operador não escolhia nada e o vídeo caía no
// Cronograma quisesse ele ou não.
// Os tetos oferecidos, do melhor ao mais leve. 1080p é o telão da igreja e o
// padrão; 720p corta o tamanho pela metade sem doer numa tela dessas; 480p é a
// escolha de quem está no chip do celular minutos antes do culto — ali um
// louvor que TERMINA vale mais que um que não.
//
// 360p ficou de fora de propósito: num telão de salão ele é ruim o suficiente
// para não valer ser oferecido, e é justamente o piso em que o app ficou preso
// por sete versões. Acima de 1080p também não: o telão não mostra a diferença e
// o aparelho ainda guarda hinário e Bíblia.
const YT_ALTURAS = [1080, 720, 480];
// ===== "ONLINE": A QUALIDADE QUE NÃO BAIXA (v5.249) =====
//
// Pedido do operador: *"adicione a opção nas qualidades de opções do download,
// para que tenha o 'Online' que mesmo ao levar para o cronograma, levaria
// apenas o link, ao invés de obrigar a baixar."*
//
// Até aqui, os três destinos que GUARDAM (playlist · Cronograma · Favoritos)
// obrigavam o download, e a razão estava escrita no `ytAcao`: eles guardam o
// item para depois, e um manifesto de transmissão expira em horas. O que ela
// não considerava é que **o LINK não expira** — e é ele, não o manifesto, que o
// item de `kind: 'youtube'` guarda desde sempre. Um vídeo que só vai ser visto
// uma vez, num culto com internet, não precisa dos ~300 MB no aparelho para
// entrar no roteiro de sábado.
//
// Ela mora no MESMO seletor das resoluções porque é a mesma pergunta ("quanto
// deste vídeo eu quero no aparelho?"), com "nada" na ponta da escala — e um
// segundo seletor para uma escolha de uma linha seria a cerimônia que a folha
// de destinos existe para não ter.
//
// O sentinela é negativo de propósito: `0` já significa "sem teto, o padrão do
// shell" em `ytFetch`/`ytAcao`, e reusá-lo faria "Online" e "melhor qualidade"
// serem o mesmo valor.
const YT_ONLINE = -1;

// ===== O AVISO DE RESOLUÇÃO LIMITADA (v1.4.11) =====
//
// Pedido do operador, depois de projetar 360p numa TV 4K sem nada na tela
// dizendo isso: *"coloque o aviso sobre a resolução estar limitada"*.
//
// O app SEMPRE soube a altura real — ela vem do shell e vira o subtítulo da
// linha ("Vídeo · 1080p"). O buraco é que o "Tocar agora" põe o item na
// prateleira `avulsos`, **que não tem lista visível**: a informação existia e
// não tinha onde aparecer. O operador projetava 360p e a leitura possível era
// *"o app está ruim"*.
//
// A CAUSA de hoje é externa e não tem conserto nosso: o YouTube apertou o SABR
// e o extrator só devolve o progressivo legado, que é 360p por construção (ver
// `docs/ACHADOS-EM-ABERTO.md` §3). O aviso não conserta nada — ele impede que a
// falta de resolução seja lida como defeito do app, que é a única coisa que
// ainda estava ao nosso alcance.
//
// ---- A REGRA, e ela é DUAS condições ----
//
// Só avisa quando o entregue está ABAIXO DO PEDIDO **e** abaixo de um piso em
// que a diferença aparece na tela. Uma condição só erra para os dois lados:
//
//   · só "abaixo do pedido": escolher 480p de propósito passaria a render um
//     aviso a cada toque, dizendo ao operador o que ele acabou de pedir;
//   · só "abaixo do piso": um teto de 480p escolhido à mão viraria alarme.
//
// O PISO é 720p porque é o degrau em que a imagem ainda se sustenta num telão
// de salão — 360p é o que produziu a queixa. Entre 720p e o teto o Registro
// continua contando a diferença; a tela fica quieta.
const YT_ALTURA_BAIXA = 720;

// ===== O CENSO DA SESSÃO: "com que frequência?", não "da última vez?" (v1.4.13) =====
//
// O Registro guardava a ÚLTIMA extração de cada tipo, e só ela. Isso responde
// *"o que aconteceu da última vez?"* — e a pergunta de uma falha INTERMITENTE é
// outra. MEDIDO em campo: três Registros deram três respostas (duas extrações
// degeneradas em 360p, uma com o visionOS entregando 19 faixas e 1080p no ar),
// e nenhuma delas contava. A leitura que saiu disso — *"é sempre"* — foi uma
// generalização de duas amostras, e ela estava errada.
//
// É o mesmo problema que o `AVStream.fome` já resolve para os travamentos, e a
// forma é a mesma: CONTADORES de sessão, sem log e sem disco. Um log
// responderia mais e custaria o que este projeto não paga (tamanho, privacidade
// do que se copia, uma segunda fonte de verdade); dois números respondem a
// pergunta que o operador faz.
//
// MORRE COM A PÁGINA, de propósito — "nesta sessão" é o que a linha diz, e é o
// que ela pode honrar sem gravar nada.
const ytCenso = {
  pedidos: 0,      // quantas vezes pedimos um manifesto ao shell
  transmitiu: 0,   // …e quantas de fato viraram transmissão
  limitadas: 0,    // quantas projeções saíram abaixo do pedido (ver `avisarResolucaoLimitada`)
  menor: 0,        // a MENOR altura que chegou a ir ao ar limitada
};

// O TETO EFETIVO de um pedido. `0` e o `YT_ONLINE` significam "o padrão do
// shell" (ver `ytBaixarNativo`), que é o primeiro da escada — só um teto
// EXPLÍCITO vale por si, e é ele que o operador escolheu na folha.
function tetoEfetivo(altura) {
  const a = altura | 0;
  return YT_ALTURAS.includes(a) ? a : YT_ALTURAS[0];
}

// O aviso propriamente, e ele é do CARTÃO DA PREVIEW — o mesmo que acabou de
// dizer "Preparando". É ali que a mídia vai aparecer, então é ali que se diz
// que ela vai aparecer pior do que se pediu; e a carência de saída do cartão
// (`PV_BUSY_SAIDA_MS`) faz a troca de mensagem se ler como uma frase só, sem
// piscar entre as duas.
//
// SILENCIOSO POR CONSTRUÇÃO quando não há o que dizer: altura desconhecida
// (shell antigo, ou um caminho que não a reporta) não vira aviso. Inventar
// "qualidade limitada" sem número seria trocar uma ausência de informação por
// uma afirmação que não se pode conferir.
function avisarResolucaoLimitada(entregue, teto) {
  const h = entregue | 0;
  if (h <= 0) return;
  if (h >= tetoEfetivo(teto) || h >= YT_ALTURA_BAIXA) return;
  // O VEREDITO fica na caixa alta (como o "Não deu") e o corpo traz o NÚMERO e
  // DE QUEM é a limitação — sem o segundo o operador procura um ajuste que não
  // existe. As DUAS chamadas são a mecânica do cartão: ele precisa ser ABERTO
  // por um dono antes de poder falar, e `avisar` é o desfecho desse dono.
  //
  // O TEXTO É CURTO PORQUE A CAIXA É PEQUENA, e isso foi MEDIDO: o rótulo tem
  // `-webkit-line-clamp: 2` e o cartão, com a folga simétrica da v1.4.9, mede
  // ~163px de conteúdo a 360px de tela. "só havia 360p neste vídeo — o YouTube
  // não liberou as melhores" corta ali (49px de texto numa caixa de 32), e o que
  // sobra é a metade sem a causa. Esta cabe nas duas larguras, com as duas
  // informações inteiras.
  // O CENSO É CONTADO AQUI, e não em quem chama: esta função é o único ponto
  // que já sabe que a altura entregue é baixa, e os dois caminhos (transmissão
  // e download) passam por ela. Contar do lado de fora seria escrever a regra
  // duas vezes, e as duas divergiriam no primeiro ajuste.
  ytCenso.limitadas++;
  if (!ytCenso.menor || h < ytCenso.menor) ytCenso.menor = h;
  const cap = 'Qualidade limitada';
  const texto = 'o YouTube só liberou ' + h + 'p';
  previewBusy(cap, texto).avisar(cap, texto);
}

// Uma linha de segmentos da folha de download — o MESMO desenho de
// Cantada/Playback das músicas do acervo. Duas perguntas usam este formato
// (forma e qualidade), e escrevê-lo duas vezes era garantir que a segunda
// divergisse da primeira no primeiro ajuste de estilo.
function ytSegRow(opcoes, atual, onPick, nota) {
  const li = document.createElement('li'); li.className = 'song-menu-seg-row';
  // A LINHA PODE DIZER O QUE ELA GOVERNA, e uma delas precisa: a escala de
  // qualidade começa em "Online", que é escolha de ARMAZENAMENTO, e o resto lê
  // como "qualidade do download". O operador não tinha como saber que os três
  // últimos degraus também valem para o "Tocar agora" — e a instrução "escolha
  // 480p numa rede ruim" era, por isso, tecnicamente certa e inútil.
  if (nota) {
    const n = document.createElement('small');
    n.className = 'song-menu-seg-nota';
    n.textContent = nota;
    li.appendChild(n);
  }
  const wrap = document.createElement('div'); wrap.className = 'fit-seg song-menu-seg';
  opcoes.forEach(([valor, rotulo]) => {
    const b = document.createElement('button');
    b.className = 'fit-opt' + (atual === valor ? ' active' : '');
    b.textContent = rotulo;
    b.addEventListener('click', () => onPick(valor));
    wrap.appendChild(b);
  });
  li.appendChild(wrap);
  return li;
}

function openYtMenu(r, alvoDado) {
  // A qualidade nasce no padrão A CADA ITEM, como a forma e como a variante das
  // músicas. Deliberado: um teto que grudasse faria o operador escolher 480p
  // numa rede ruim e receber, sem aviso, o vídeo principal do domingo seguinte
  // em 480p no telão. O atrito de dois toques é visível; a regressão silenciosa
  // não seria.
  if (!songMenuFor || songMenuFor.yt !== r) {
    songMenuFor = { yt: r, variant: 'full', audio: false, alt: YT_ALTURAS[0], alvo: alvoDado || null };
    // Item novo, folha nova: os destinos marcados são da FOLHA ABERTA e não
    // atravessam de um vídeo para o outro. (Os toques nos seletores de forma e
    // qualidade remontam a folha para o MESMO `r` e passam por aqui sem zerar
    // nada, que é o que preserva o que já foi marcado.)
    destLimpar();
  }
  // O ALVO pode ser o corpo da linha (v5.285) em vez da folha — ver a nota em
  // `renderSongMenu`. Ele mora em `songMenuFor` porque os seletores de forma e
  // qualidade remontam a lista, e precisam refazê-la no mesmo lugar.
  const alvo = songMenuFor.alvo || songMenuListEl;
  if (!songMenuFor.alvo) songMenuTitleEl.textContent = r.name || 'Vídeo do YouTube';
  alvo.innerHTML = '';
  // VÍDEO × SÓ ÁUDIO, no MESMO seletor de Cantada/Playback das músicas do
  // acervo — é a mesma pergunta ("qual faixa deste item?") e não havia por que
  // inventar um segundo desenho para ela. A escolha vale para as quatro ações
  // abaixo, em vez de dobrar a folha para oito linhas.
  //
  // Só aparece com shell ≥ 23 (`ytFetchAudio` na ponte). Num anterior o botão
  // não faria nada, e botão que não faz nada no meio de um culto é pior que
  // botão nenhum — mesma regra do botão de busca no YouTube.
  //
  // **E ele NÃO existe para um episódio de série** (`semSoAudio`, v5.230): um
  // testemunho em vídeo não tem versão de áudio que faça sentido projetar, e
  // uma escolha que não muda nada é pior que escolha nenhuma.
  // **E ele some com "Online" escolhido**: ali nada é baixado, e a forma da
  // faixa é decidida na hora de tocar, pelo `resolverLinkYoutube` — oferecer a
  // escolha aqui seria oferecer uma que não muda nada.
  if (window.__NATIVE__ && !r.semSoAudio
      && (songMenuFor.alt | 0) !== YT_ONLINE) {
    alvo.appendChild(ytSegRow(
      [[false, 'Vídeo'], [true, 'Só áudio']],
      !!songMenuFor.audio,
      (v) => { songMenuFor.audio = v; openYtMenu(r); },
    ));
  }
  // A QUALIDADE, logo abaixo da forma — e só quando há vídeo para qualificar:
  // com "Só áudio" escolhido não existe resolução nenhuma, e deixar a linha na
  // tela seria oferecer uma escolha que não faz nada (a mesma regra do botão de
  // busca no YouTube num shell antigo).
  //
  // Shell ≥ 25, pelo método `ytFetchAte` da ponte. Num anterior a linha não
  // aparece e o download sai no padrão de sempre — que é exatamente o que este
  // app fazia até agora, então nada regride.
  // "ONLINE" é o primeiro degrau da escala: nada no aparelho. Ele NÃO depende do
  // shell 25 (não há teto a pedir — o item guardado é o link), mas a linha
  // inteira só existe a partir dele; num shell anterior o operador continua com
  // o download de sempre, que é o que este app fazia até agora.
  if (window.__NATIVE__ && !songMenuFor.audio) {
    alvo.appendChild(ytSegRow(
      [[YT_ONLINE, 'Online']].concat(YT_ALTURAS.map((h) => [h, h + 'p'])),
      songMenuFor.alt | 0,
      (v) => { songMenuFor.alt = v; openYtMenu(r); },
      // TETO, e não escolha fixa: desde o shell 60 o app MEDE a rede nos
      // primeiros bytes e desce sozinho o que não couber. O que o operador
      // escolhe aqui é o limite de cima, e ele vale para o "Tocar agora"
      // também — que é justamente o que a escala não dizia.
      'Teto de qualidade — vale para o "Tocar agora" também',
    ));
  }
  // O subtítulo do "Tocar agora" DIZ que o Cronograma fica de fora: é a
  // diferença entre as três opções, e ela não se adivinha olhando o ícone.
  // A escolha é lida AGORA, na montagem, e viaja no fecho de cada ação: o
  // `songMenuItem` chama `closeSongMenu()` antes da ação, e `closeSongMenu`
  // zera o `songMenuFor` — consultá-lo lá dentro encontraria null e todo
  // download sairia como vídeo. É o mesmo cuidado que a `variante` das músicas
  // já tomava, e a folha é remontada a cada toque no seletor, então o valor
  // capturado é sempre o vigente.
  const soAudio = !!songMenuFor.audio;
  // A altura viaja no fecho junto com a forma, e pelo MESMO motivo: o
  // `songMenuItem` chama `closeSongMenu()` antes da ação, e ela zera o
  // `songMenuFor` — ler o teto lá dentro encontraria null e todo download sairia
  // no padrão, calado.
  const altura = soAudio ? 0 : (songMenuFor.alt | 0);
  // OS DESTINOS SÃO MARCÁVEIS (v5.141), e aqui o ganho é maior que no acervo: um
  // vídeo do YouTube custa MINUTOS de download. Até aqui, querer o mesmo louvor
  // no Cronograma e nos Favoritos era baixá-lo duas vezes — e o operador só
  // descobria isso na segunda espera. Agora o download é um só e o arquivo entra
  // nas listas marcadas.
  //
  // "Tocar agora" NÃO ganha caixa: ele não é uma lista, é o telão. E ele
  // continua honrando o que estiver marcado (o `songMenuItem` passa a união),
  // então "marcar Cronograma + tocar agora" projeta e guarda no mesmo toque —
  // que é exatamente o que se faz com o louvor que acabou de chegar.
  const remontar = () => openYtMenu(r);
  destRemontar = remontar;
  destExecutor = (alvos, btn) => ytAcao(r, alvos, btn, soAudio, altura);
  // "Tocar agora" é o único desta folha que GUARDA NADA, e é isso que o rótulo
  // não diz — daí ele manter subtítulo enquanto os três destinos perderam o
  // deles. No caminho de só-áudio o que ele não diz é outra coisa: o telão não
  // muda (o kind `audio` mantém o wallpaper).
  //
  // E COM "ONLINE" ELE DIZ OUTRA COISA AINDA, pedido do operador: **este toque
  // toca direto da internet, e a qualidade depende dela**. A frase é sobre a
  // CONEXÃO e não sobre o teto, porque desde o shell 60 é a banda medida que
  // escolhe o degrau — e porque o modo de errar aqui é o de sempre neste app:
  // uma imagem pior que a esperada, sem nada na tela dizendo por quê. Ela
  // substitui "Sem entrar em lista nenhuma" em vez de somar-se a ela: com
  // "Online" nada é guardado de qualquer forma (o item é o link), então aquela
  // frase deixa de ser a informação que falta.
  const subTocar = soAudio
    ? 'Sem mexer no telão'
    : (altura === YT_ONLINE
      ? 'Toca direto da internet — a qualidade varia bastante conforme a conexão'
      : 'Sem entrar em lista nenhuma');
  alvo.appendChild(songMenuItem(msym(ICON.play), 'Tocar agora', subTocar,
    (vr, btn, alvos) => ytAcao(r, alvos, null, soAudio, altura), 'tocar', remontar));
  // COM "ONLINE" os três destinos guardam o LINK, e isso precisa estar dito:
  // eles são as três linhas que, em toda outra qualidade, significam "espere o
  // download". O subtítulo é o mesmo nos três porque a diferença entre eles
  // continua sendo só a lista.
  const subGuardar = (songMenuFor.alt | 0) === YT_ONLINE ? 'Só o link, sem baixar' : '';
  alvo.appendChild(songMenuItem(msym(ICON.queue), 'Adicionar à playlist', subGuardar,
    (vr, btn, alvos) => ytAcao(r, alvos, btn, soAudio, altura), 'playlist', remontar));
  alvo.appendChild(songMenuItem(msym(ICON.cronoAdd), 'Adicionar ao Cronograma', subGuardar,
    (vr, btn, alvos) => ytAcao(r, alvos, btn, soAudio, altura), 'cronograma', remontar));
  alvo.appendChild(songMenuItem(msym(ICON.star), 'Favoritar', subGuardar,
    (vr, btn, alvos) => ytAcao(r, alvos, btn, soAudio, altura), 'favoritos', remontar));
  const go = destConfirmRow();
  if (go) alvo.appendChild(go);
  // Só a FOLHA abre; no corpo da linha quem abre é o acordeão do chamador.
  if (!songMenuFor.alvo) songMenuPopupEl.classList.add('open');
}

// Baixa e faz o que foi escolhido.
//
// "Tocar agora" FECHA o acervo — mesma regra de `playSongVariant`: o cartão de
// progresso mora na preview, e a preview está atrás desta bandeja. As duas
// opções de "adicionar" MANTÊM o acervo aberto, porque o operador está no meio
// de uma busca e provavelmente vai pegar mais de um; ali o aviso é a própria
// linha, que fica marcada como concluída em vez de voltar ao estado inicial —
// era essa volta silenciosa que fazia parecer que nada tinha acontecido.
//
// Cada escolha vai para O SEU lugar, e só para ele. Até a v5.86 as três caíam
// no Cronograma, porque `addMedia` era quem escolhia a lista e ela era sempre
// "imports": pedir "Tocar agora" enchia a lista do culto de vídeo que o
// operador só quis ver uma vez. A lista de destino agora é decidida AQUI e
// entregue ao `addMedia`, que continua gravando registro e lista na mesma
// transação.
// (`YT_LISTA` e `YT_DESTINO_NOME` saíram na v5.141: eram uma segunda tabela de
// destinos, só para o YouTube, com os mesmos três nomes e as mesmas três listas
// da `DESTINOS`/`LISTA_ROTULO`. Duas tabelas divergiriam no primeiro destino que
// alguém acrescentasse a uma só — e o multi-destino precisava justamente de uma
// fonte única para montar a frase "adicionado à playlist e ao Cronograma".)

// Projeta um vídeo do YouTube SEM baixá-lo antes: o shell monta o manifesto das
// duas faixas adaptativas e o `MediaSource` do lado web as transforma num
// `<video>` comum (ver shared/mse.js).
//
// Devolve `true` quando assumiu a projeção. `false` significa "não deu" e o
// chamador segue para o download — não há nenhum aviso ao operador nesse
// caminho, de propósito: ele pediu o louvor, não o método, e um cartão dizendo
// "não deu para transmitir, vou baixar" seria ruído sobre uma decisão que não
// é dele.
// POR QUE a última tentativa de transmitir não entrou. Lido pelo Registro.
//
// Ele existe porque `tentarTransmitir` desiste em CINCO pontos e todos eram
// mudos: do lado do operador, "Tocar agora" simplesmente baixava, como sempre
// fizera, sem nada dizendo que uma transmissão tinha sido tentada. E o
// diagnóstico do shell não cobria estes casos — três deles acontecem ANTES de a
// ponte ser chamada.
let motivoStream = '';

async function tentarTransmitir(r, altura, somenteAudio) {
  // A SENHA DESTA PROJEÇÃO (ver `palcoEmVoo`), lida na entrada e conferida
  // depois da extração — o único await longo desta função.
  const senha = projecaoSeq;
  const soAudio = !!somenteAudio;
  motivoStream = '';
  if (window.AVStream) window.AVStream.ultimoErro = '';
  if (!window.__NATIVE__) { motivoStream = 'navegador (sem ponte)'; return false; }
  if (!window.AVStream) { motivoStream = 'shared/mse.js não carregou'; return false; }
  if (!r || !r.url) { motivoStream = 'resultado sem URL'; return false; }
  let man = null;
  // O PEDIDO conta AQUI, e não na entrada da função: acima dela há quatro
  // recusas (sem ponte, sem `mse.js`, sem URL) que nunca chegam a perguntar
  // nada ao shell. Contá-las inflaria o denominador com o que não é extração.
  ytCenso.pedidos++;
  try {
    man = await AVNative.ytStream(r.url, altura | 0);
  } catch (e) {
    motivoStream = 'a ponte falhou: ' + ((e && e.message) || '?');
    return false;
  }
  if (!man) { motivoStream = 'o shell não montou o manifesto (ver a linha "transmissão" abaixo)'; return false; }
  // PERDEU A VEZ? A extração leva segundos, e nesse intervalo o operador pode
  // ter projetado outra coisa. Aqui, e não mais adiante: este é o ponto mais
  // cedo em que a espera acabou, e daqui para baixo tudo tem efeito — o
  // registro no banco, o aviso de resolução limitada, o censo e o `send`.
  if (projecaoSeq !== senha) {
    motivoStream = 'outra projeção assumiu enquanto a extração corria';
    return PROJECAO_PERDIDA;
  }
  // SÓ ÁUDIO: a faixa de vídeo é DESCARTADA aqui, no lado web, e o shell não
  // precisa saber de nada. Ele já monta o par no mesmo manifesto, então pedir
  // "só o áudio" é jogar fora um descritor — não um segundo pedido, não uma
  // segunda extração, e sobretudo nenhum byte de 1080p baixado para nada. É por
  // isso que este recurso chega por OTA, sem APK novo.
  if (soAudio) man = Object.assign({}, man, { video: null, height: null });
  // O `suportado` é do APARELHO, não do manifesto: um WebView sem o codec
  // precisa cair no download em vez de projetar preto. E quando ele recusa, o
  // que interessa é QUAL string foi recusada — sem ela a informação é "não
  // deu", que não leva a lugar nenhum.
  if (!AVStream.suportado(man)) {
    const testar = (t) => {
      if (!t) return 'ausente';
      try { return MediaSource.isTypeSupported(t) ? 'ok' : 'RECUSADO'; } catch (_) { return 'erro'; }
    };
    const parte = (rotulo, faixa) => rotulo + ' [' + ((faixa && faixa.mime) || '—') + '] '
      + testar(faixa && faixa.mime);
    motivoStream = !window.MediaSource ? 'este WebView não tem MediaSource'
      : 'codecs recusados — ' + (soAudio ? '' : parte('vídeo', man.video) + ' · ')
        + parte('áudio', man.audio);
    return false;
  }
  const rec = await AVDB.addStreamMedia(man, {
    // ===== O NOME DO APP VENCE O TÍTULO DO YOUTUBE (v1.4.10) =====
    //
    // Relato do operador: *"o nome no card de preparação está se alterando na
    // segunda metade do processo… deixe apenas o primeiro nome, que ao que
    // parece é o nome do item ou renomeação que temos já no app"*.
    //
    // A ordem era `man.name || r.name`, e `man.name` é o título que o shell
    // extraiu do YouTube. Ele chega SEGUNDOS depois do toque, e nesse instante
    // trocava o nome debaixo de tudo: o cartão de espera (que abre com
    // `r.name`), a barra do que está tocando, a notificação de mídia, a linha
    // da lista. Pior no caminho que mais importa — um item de link do
    // Cronograma ou dos Favoritos leva o nome que o OPERADOR deu, e o título do
    // canal o apagava.
    //
    // `r.name` é o que o app já tem: o resultado da busca (já com o
    // `tituloLimpo` do shell) ou o nome guardado do item, rename incluído.
    // `man.name` fica como o que ele sempre deveria ter sido — a resposta para
    // quando NÃO temos nome, e não uma correção do nosso.
    name: r.name || man.name || 'Vídeo',
    youtubeId: r.id || null,
    height: man.height || null,
    seconds: man.seconds || null,
    somenteAudio: soAudio,
    list: 'avulsos',
  });
  if (!rec) { motivoStream = 'o registro da mídia não foi criado'; return false; }
  motivoStream = soAudio ? 'transmitindo só o áudio' : 'transmitindo ' + (man.height || '?') + 'p';
  // SÓ NO VÍDEO: num "só áudio" a resolução não existe, e avisar sobre ela ali
  // seria o app falando de uma coisa que o operador acabou de dispensar.
  if (!soAudio) avisarResolucaoLimitada(man.height, altura);
  ytCenso.transmitiu++;
  setYtEstado(r.id, null);
  await fixarAvulso(rec.id);
  await load();
  await send(rec.id);
  return true;
}

// ============================================================================
// O ITEM DE LINK RESOLVE ANTES DE IR AO TELÃO
// ============================================================================
//
// Um registro `kind: 'youtube'` é o LINK sem bytes — a última carta de quando
// transmissão e download falharam. Sem o embed (removido na v5.212) ele deixa
// de ser tocável como link e é RESOLVIDO no toque:
//   1. transmissão direta (`tentarTransmitir`), que já projeta sozinha;
//   2. download (`ytArquivo`).
// É a MESMA escada do "Tocar agora" e do `recuperarStream`.
//
// O DOWNLOAD TROCA O ITEM NA LISTA; A TRANSMISSÃO NÃO. O arquivo é durável e
// toma o lugar do link EM POSIÇÃO — `listSet` com função é read-modify-write
// atômico, e `listAdd`+`listRemove` mandaria o item para o fim de um Cronograma
// que alguém montou à mão. O manifesto de uma transmissão expira em horas.
const LISTAS_DO_OPERADOR = ['playlist', 'imports', 'favs'];

async function trocarLinkPeloArquivo(velhoId, novoId) {
  if (!velhoId || !novoId || velhoId === novoId) return;
  for (const l of LISTAS_DO_OPERADOR) {
    if (!(await AVDB.listHas(l, velhoId))) continue;
    await AVDB.listSet(l, (antes) => {
      const fora = [];
      for (const x of antes) {
        const y = x === velhoId ? novoId : x;
        // O arquivo pode já estar na lista (o operador baixou o mesmo vídeo
        // antes): trocar sem deduplicar deixaria a mesma faixa duas vezes.
        if (!fora.includes(y)) fora.push(y);
      }
      return fora;
    });
  }
}

/**
 * Resolve um item de link e o projeta. Devolve `true` quando algo foi ao ar.
 *
 * Toda saída negativa FALA — na linha do próprio item, que é onde o toque
 * nasceu (a régua da v5.207). Um link que não resolve e não diz nada é
 * indistinguível de um toque que não pegou, e o operador toca de novo.
 */
// ===== E ELE VALE PARA TODO CAMINHO QUE PÕE UM LINK NO AR (v1.4.7) =====
//
// Relato do operador: *"o tocar agora tem o sistema de reação instantânea, mas
// o resto não. Por exemplo, tocar em um item de link que esteja no cronograma ou
// dos favoritos e outras fontes"*.
//
// A v1.4.6 pôs o reconhecimento do toque no `ytAcao` — a folha da BUSCA —, e
// deixou de fora a outra porta do mesmo trabalho: um item `kind: 'youtube'` já
// guardado numa lista. Ele é a MESMA espera (o `tentarTransmitir` abaixo começa
// pela mesma extração de rede de segundos) e não tinha sinal nenhum.
//
// A guarda mora AQUI, e não no `send`, pelo motivo que este arquivo já aplica
// duas vezes: `resolverLinkYoutube` é o ponto por onde TODOS os caminhos do link
// passam — o toque na linha, o avanço da playlist, o ⏮/⏭ do transporte, a
// notificação nativa. Pôr no chamador seria escolher um deles.
//
// SAÍDA ÚNICA pelo mesmo motivo do invólucro do `ytAcao`: são quatro `return`
// aqui, e um sem a liberação prenderia o cartão sobre a preview para sempre.
async function resolverLinkYoutube(rec) {
  const cartao = cederOPalco((rec && rec.name) || 'o vídeo');
  // O "CARREGANDO" NA PRÓPRIA LINHA (v1.4.21), ao lado do cartão. Ele mora aqui
  // pelo mesmo motivo que o cartão: `resolverLinkYoutube` é o ponto por onde
  // TODOS os caminhos do link passam — o toque na linha, o avanço da playlist,
  // o ⏮/⏭ do transporte, a notificação nativa.
  //
  // E ele SOBREVIVE a perder a vez (v1.4.18): quem toca noutra coisa no meio da
  // espera não interrompe o trabalho, só a projeção dele. Apagar o aro ali
  // faria a linha dizer que parou o que continua acontecendo.
  const idDaLinha = rec && rec.id;
  marcarCarregando(idDaLinha, true);
  try {
    return await resolverLinkInterno(rec);
  } finally {
    marcarCarregando(idDaLinha, false);
    cartao.soltar();
  }
}

// ===== A RECUSA FALA NOS DOIS LUGARES (v1.4.14) =====
//
// Relato do operador, num episódio de série: *"ele carrega um tempo, mas ele não
// toca nada e nem dá nenhuma mensagem de erro nem nada"*. REPRODUZIDO: o
// caminho da BUSCA falava pelo cartão da preview (`previewBusy(…).falhar`) e
// este aqui não — a única saída era o `notaNoItem`, que escreve na LINHA do
// item.
//
// **E a linha some justamente neste caso.** Um episódio de série mora dentro do
// álbum, na Biblioteca, e o "Tocar agora" a FECHA (`closeHymnSearch`) antes de
// começar. A nota era escrita num lugar que já tinha saído da tela: silêncio
// completo, depois de segundos de espera.
//
// O cartão é a resposta certa pela régua de sempre — **o aviso mora onde o
// resultado ia aparecer**, e o resultado ia para a projeção. A nota FICA: ela é
// o certo quando a linha está à vista (o item de link do Cronograma), e as duas
// não disputam nada.
function recusarLink(rec, frase, senha) {
  notaNoItem(rec.id, frase);
  // O CARTÃO SÓ SE A VEZ AINDA FOR DESTA RESOLUÇÃO (v1.4.18). A nota vai para a
  // LINHA do item e é sempre certa — ela descreve aquele item, onde quer que o
  // operador esteja. O cartão fica sobre a PREVIEW, e ali ele falaria por cima
  // de uma cena que já é de outro: "Não deu" sobre um louvor que está tocando
  // perfeitamente é o app acusando o que funcionou.
  if (senha !== undefined && projecaoSeq !== senha) return false;
  // Cartão PRÓPRIO, e não o do `cederOPalco`: o do invólucro é solto no
  // `finally` logo a seguir, e `falhar()` precisa de um dono que segure a
  // mensagem pelo prazo de leitura. É o mesmo padrão do `ytAcaoInterno`, e a
  // carência de saída (`PV_BUSY_SAIDA_MS`) faz a troca não piscar.
  previewBusy('Preparando', (rec && rec.name) || 'o vídeo').falhar(frase);
  return false;
}

// A CAUSA, quando o shell a nomeia (v1.4.14).
//
// "Não foi possível transmitir nem baixar" e "este vídeo não está disponível"
// mandam fazer coisas OPOSTAS: a primeira convida a tentar de novo, a segunda a
// escolher outro. MEDIDO em campo — o Registro trouxe
// `extração falhou: ContentNotAvailableException` nas duas linhas, e o app
// dizia a frase genérica.
//
// Lê o diagnóstico do shell e procura a MARCA. É acoplamento a uma string do
// Kotlin, e por isso ele só ESPECIALIZA: não achando a marca, a frase genérica
// vale como sempre. O dia em que o nome da exceção mudar, isto volta ao
// comportamento de hoje — nunca a uma afirmação errada. (Mesmo raciocínio do
// `recuperarStream`, que reconhece a URL expirada pela mensagem.)
const YT_INDISPONIVEL = /ContentNotAvailable/i;
async function motivoDaRecusa(padrao) {
  if (!window.__NATIVE__) return padrao;
  let diag = '';
  try { diag = String((await AVNative.ytDiag()) || ''); } catch (_) { return padrao; }
  return YT_INDISPONIVEL.test(diag)
    ? 'este vídeo não está disponível no YouTube — pode ser privado, só para membros ou removido'
    : padrao;
}

async function resolverLinkInterno(rec) {
  const senha = projecaoSeq;   // ver `palcoEmVoo`
  const vid = (rec && rec.youtubeId) || extractYouTubeId((rec && rec.url) || '');
  if (!vid) return recusarLink(rec, 'Sem o vídeo de origem — não há o que projetar.', senha);
  if (!window.__NATIVE__) {
    // No navegador não há ponte: nem transmissão, nem download. Dizer isso é
    // melhor que projetar nada em silêncio.
    return recusarLink(rec, 'Este link só toca pelo app — o navegador não baixa vídeo.', senha);
  }
  const link = 'https://www.youtube.com/watch?v=' + vid;
  // SEM GENÉRICO AQUI. O `name` deste alvo vira o nome do registro nos dois
  // caminhos abaixo, e um "Vídeo" fabricado venceria o título de verdade que o
  // shell traz — que é justamente o caso em que ele deve valer. Quem precisa de
  // algo para MOSTRAR põe o genérico dele (ver o `rotulo` do `ytBaixarNativo`).
  const alvo = { id: vid, url: link, name: rec.name || '' };
  // A FORMA do registro manda: quem guardou só o áudio não pode receber o vídeo
  // de volta. (Um item de link nasce como `youtube`; a leitura fica dita para o
  // dia em que houver um link só de áudio.)
  const soAudio = rec.kind === 'audio';
  const transmitiu = await tentarTransmitir(alvo, 0, soAudio);
  // PERDEU A VEZ: nem projeta, nem CAI NO DOWNLOAD. Baixar aqui seria começar
  // minutos de rede por um toque que o operador já substituiu — e terminar
  // projetando por cima, que é o defeito inteiro por outro caminho.
  if (transmitiu === PROJECAO_PERDIDA) return false;
  if (transmitiu) {
    // A LINHA QUE RESOLVEU O LINK É A QUE ESTÁ NO AR (v5.269, pedido do
    // operador). `tentarTransmitir` termina em `send(<id do avulso>)`, e é ele
    // que zera a origem — então ela é escrita AQUI, depois, e não antes: um
    // `send` no meio do caminho apagaria a marca que ela existe para pôr.
    //
    // O caminho do DOWNLOAD, logo abaixo, não precisa disto: o arquivo toma o
    // lugar do link EM POSIÇÃO (`trocarLinkPeloArquivo`), então a linha passa a
    // ser a mídia e o `midiaNoArId` de sempre já a alcança.
    midiaNoArOrigem = rec.id;
    marcarNoAr();
    renderNowPlaying();
    return true;
  }
  const novo = await ytArquivo(alvo, { lista: 'avulsos', aviso: 'preview', somenteAudio: soAudio });
  if (!novo) {
    return recusarLink(rec, await motivoDaRecusa('Não foi possível transmitir nem baixar este vídeo.'), senha);
  }
  await fixarAvulso(novo.id);
  await trocarLinkPeloArquivo(rec.id, novo.id);
  await load();
  // PERDEU A VEZ — e aqui o desfecho é ASSIMÉTRICO de propósito: o arquivo FICA.
  // Ele já foi baixado e já tomou o lugar do link na lista do operador
  // (`trocarLinkPeloArquivo`), que é valor durável e foi o que o toque pediu; o
  // que ele não pode é subir ao palco por cima do que está no ar. Da próxima vez
  // aquela linha toca do disco, sem rede.
  if (projecaoSeq !== senha) return false;
  await send(novo.id);
  return true;
}

// A RECUPERAÇÃO quando um stream falha em cena.
//
// A causa esperada é a URL expirada: o manifesto vale algumas horas, e o
// registro pode ficar na prateleira mais que isso. Pedir um manifesto NOVO para
// o mesmo vídeo é barato (uma extração) e resolve o caso comum sem o operador
// saber que houve algo.
//
// Uma tentativa só: se a segunda também falhar, o problema não é a validade — é
// rede, codec ou um vídeo que ficou restrito —, e insistir num laço em cima de
// uma projeção morta é pior que parar. Aí a mídia é substituída pelo DOWNLOAD,
// que é o caminho que sempre funcionou.
// ===== A RETENTATIVA É POR EPISÓDIO, NÃO POR SESSÃO (v1.4.19) =====
//
// Isto era um `Set` que nunca era limpo. A intenção escrita é *"uma tentativa
// só"* por episódio de falha; o que o código fazia era *"uma tentativa por item,
// para o resto da sessão"* — e a sessão é o PROCESSO, que neste app quase nunca
// morre (os serviços em primeiro plano o mantêm vivo).
//
// **O cenário que morde é o do sábado.** Ensaio de manhã: o vídeo é transmitido,
// a URL expira no meio, isto re-extrai e conserta — invisível, como deve ser.
// Culto: o MESMO vídeo, o mesmo `rec.id`, a URL guardada expirada de novo. O
// conjunto já tinha o id, então NÃO havia re-extração: a cena saía do telão e o
// app começava a baixar centenas de MB na frente da congregação, por um conserto
// de dois segundos que ele sabe fazer e se proibiu de tentar.
//
// A JANELA é o que mantém as duas propriedades ao mesmo tempo: uma falha
// SEGUIDA (o manifesto novo que também não presta) continua caindo no download,
// porque ela chega em segundos; e um episódio NOVO horas depois volta a ter
// direito à sua tentativa. Cinco minutos é folgadamente mais que a duração de um
// laço de falha (cada volta custa uma extração, ~2 s) e folgadamente menos que
// qualquer intervalo real entre um ensaio e um culto.
const STREAM_RETENTAR_MS = 5 * 60 * 1000;
const streamRetentado = new Map();   // id → carimbo da última re-extração
async function recuperarStream(rec, porque) {
  console.warn('[stream] falhou:', porque);
  if (!rec || !rec.youtubeId) {
    // Sem o vídeo de origem não há para onde cair, e insistir numa cena morta é
    // pior que assumir. Tira do telão e diz por quê.
    stopClear();
    return;
  }
  const link = 'https://www.youtube.com/watch?v=' + rec.youtubeId;
  // RE-EXTRAIR SÓ QUANDO A CAUSA É EXPIRAÇÃO, que é a única coisa que um
  // manifesto novo conserta — e ela se manifesta como 401/403 do googlevideo.
  // O discriminador já existia na mensagem desde a v5.124 (`HTTP n` × `a
  // requisição não completou`) e não era usado: qualquer falha pagava ~2 s de
  // extração para projetar uma SEGUNDA cena morta antes de baixar. São os dois
  // pares "play 0s / PAUSA ESPONTÂNEA 0s" da linha do tempo.
  const expirou = /HTTP 40[13]\b/.test(String(porque || ''));
  // A FORMA do registro manda em tudo o que vem abaixo: quem pediu só o áudio
  // não pode receber o vídeo de volta — nem no manifesto novo, nem no download
  // do fim da linha. É o mesmo reaproveitamento por forma do `ytArquivo`, e o
  // `kind` é o que separa as duas.
  const soAudio = rec.kind === 'audio';
  const ultima = streamRetentado.get(rec.id) || 0;
  if (expirou && Date.now() - ultima > STREAM_RETENTAR_MS) {
    streamRetentado.set(rec.id, Date.now());
    let man = null;
    try { man = await AVNative.ytStream(link, rec.height | 0); } catch (_) {}
    if (man && soAudio) man = Object.assign({}, man, { video: null, height: null });
    if (man && window.AVStream && AVStream.suportado(man)) {
      await AVDB.setMediaStream(rec.id, man);
      if (currentId === rec.id) await send(rec.id);
      return;
    }
  }
  // O TELÃO SAI DA CENA MORTA ANTES DO DOWNLOAD, que leva minutos. Sem isto a
  // projeção fica no preto o tempo todo, com o operador sem saber se o app
  // ainda está fazendo alguma coisa — o wallpaper diz "nada em cena", que é a
  // verdade, e o aviso do download aparece na preview.
  if (currentId === rec.id) stopClear();
  // Fim da linha da transmissão: o vídeo vira ARQUIVO, que é o caminho de sempre.
  const novo = await ytArquivo(
    { id: rec.youtubeId, url: link, name: rec.name },
    { lista: 'avulsos', aviso: 'preview', somenteAudio: soAudio },
  );
  if (!novo) return;
  await fixarAvulso(novo.id);
  await AVDB.listRemove('avulsos', rec.id);
  await load();
  if (currentId === rec.id || !currentId) await send(novo.id);
}
// `destinos` é a LISTA de escolhas da folha — uma ou várias chaves de
// `DESTINOS`, mais o `tocar`, que não é lista nenhuma (v5.141). Uma string
// solta continua valendo: os chamadores de fora da folha (o link já no
// Cronograma) mandam um destino só, e escrever `['cronograma']` neles seria
// ruído.
// ===== O TOQUE RESPONDE NA HORA, e não quando os bytes chegam =====
//
// Relato do operador: *"após a seleção, ele leva algum tempo para reagir e
// sequer aparecer o spinner do carregamento do vídeo… nem que tenha mais tempo
// de carregamento, mas o feedback deve ser instantâneo"*.
//
// A janela era real e longa: `tentarTransmitir` começa por um `ytStream`, que é
// uma EXTRAÇÃO DE REDE de segundos, e só depois dela vem o `send` que muda
// alguma coisa na tela. No meio-tempo o único sinal era o `setYtEstado` — que
// acende uma LINHA da Biblioteca que o `closeHymnSearch` acabou de fechar. Do
// lado do operador: nada. E o caminho do DOWNLOAD já tinha o cartão (`ytArquivo`
// chama `previewBusy`); o da TRANSMISSÃO nunca teve. **A assimetria era o
// defeito.**
//
// ESTE INVÓLUCRO EXISTE PELA SAÍDA ÚNICA. `ytAcaoInterno` tem meia dúzia de
// `return` — transmitiu, guardou o link, já estava na lista, o download falhou
// — e um deles sem a liberação prenderia o cartão sobre a preview para sempre.
// Um `finally` cobre todos, e é por isso que a chamada não foi enfiada no corpo.
//
// Só no `tocar`: os outros destinos não vão ao telão, e interromper a cena para
// guardar um vídeo numa lista seria o oposto do que o toque pediu.
async function ytAcao(r, destinos, btn, somenteAudio, altura) {
  const alvos = typeof destinos === 'string' ? [destinos] : (destinos || []);
  if (!alvos.includes('tocar')) return ytAcaoInterno(r, destinos, btn, somenteAudio, altura);
  closeHymnSearch();
  const cartao = cederOPalco(r.name || 'o vídeo');
  try {
    return await ytAcaoInterno(r, destinos, btn, somenteAudio, altura);
  } finally {
    // O cartão do DOWNLOAD (aberto por `ytArquivo` no meio do caminho) segura o
    // próprio contador, então soltar o meu não apaga a legenda dele — nem a
    // mensagem de falha, que `falhar()` trava sem liberar. Ver `previewBusy`.
    cartao.soltar();
  }
}

async function ytAcaoInterno(r, destinos, btn, somenteAudio, altura) {
  const senhaDoToque = projecaoSeq;   // ver `palcoEmVoo`
  const escolhas = [...new Set(typeof destinos === 'string' ? [destinos] : (destinos || []))];
  // Sem destino nenhum o download não teria dono e o item ficaria pendurado no
  // slot avulso, invisível — pior que o Cronograma, que é a lista à vista e de
  // onde se apaga com um toque. Não há caminho na UI que chegue aqui vazio; a
  // guarda existe para não haver.
  if (!escolhas.length) escolhas.push('cronograma');
  const tocar = escolhas.includes('tocar');
  // Os destinos que GUARDAM, na ordem da folha. `tocar` fica de fora: ele é o
  // telão, e o telão não é uma lista.
  const guardar = escolhas.filter((d) => d !== 'tocar');
  if (tocar) closeHymnSearch();
  // De onde este vídeo veio, para o `setYtEstado` saber que linha acender. É
  // registrado ANTES do primeiro estado, senão o 'baixando' de baixo passa sem
  // encontrar a chave — e o sinal só apareceria na segunda batida do progresso.
  if (r.__linha) ytLinhas.set(r.id, r.__linha);
  setYtEstado(r.id, 'baixando');
  // O DOWNLOAD NASCE NA PRIMEIRA lista escolhida e é ESPALHADO para as demais
  // depois — o arquivo é um só, e o que muda entre os destinos é apenas em
  // quantos conjuntos de ids o mesmo registro aparece. Sem nenhum destino de
  // guarda (só "Tocar agora"), o slot avulso é quem segura os bytes, como
  // sempre.
  const listas = listasDosDestinos(guardar);
  const lista = listas[0] || 'avulsos';
  // "JÁ ESTAVA LÁ?" PRECISA SER PERGUNTADO AGORA, antes do download: um vídeo
  // novo NASCE na lista (o `addMedia` lá dentro já recebe o destino), então
  // perguntar depois anunciaria todo download novo como "já estava lá" — o
  // aviso mais confuso possível justamente no caminho mais demorado.
  // Só vale quando há arquivo no aparelho: é esse o registro que o `ytArquivo`
  // reaproveita. Um item de PLAYER (o link, sem bytes) não conta — dele sai um
  // registro novo, com id novo.
  // A FORMA escolhida no seletor do topo da folha (vídeo ou só áudio), que
  // chega por parâmetro porque a folha já fechou quando esta função roda. Ela
  // atravessa tudo o que vem abaixo: a pergunta "já está na lista?", o
  // reaproveitamento do arquivo e o download.
  const soAudio = !!somenteAudio;

  // TRANSMISSÃO DIRETA, e só em "Tocar agora". As outras três ações GUARDAM o
  // item, e um manifesto de stream expira em algumas horas — guardar um seria
  // guardar algo que não abre no domingo. Combinada com um destino de guarda, a
  // transmissão fica de fora e o download é obrigatório.
  //
  // Falhando qualquer coisa (shell antigo, vídeo sem par adaptativo, WebView
  // sem o codec) o caminho segue para o download. Nada aqui é caminho único.
  //
  // VALE PARA "SÓ ÁUDIO" também: o pedido não é "rápido", é NÃO ESPERAR — a
  // transmissão começa a tocar com o primeiro fragmento, na casa dos kB.
  //
  // E VALE COM AS TELAS DA REDE NO AR. Houve aqui um `pularTransmissao` que
  // mandava tudo ao download com a transmissão ligada e sem TV — e como esse é
  // o estado NORMAL do operador, o recurso inteiro parou de acontecer. A saída
  // não foi relaxar a guarda: o shell serve as mesmas faixas em `/s/<token>` e
  // o `telaEnriquecer` reescreve o manifesto.
  if (tocar && !guardar.length && await tentarTransmitir(r, altura, soAudio)) return;

  // ===== "ONLINE": GUARDA O LINK, NÃO O ARQUIVO (v5.249) =====
  //
  // Ele entra DEPOIS da transmissão e ANTES do download, e a ordem é o desenho
  // inteiro: com "Tocar agora" sozinho não há o que guardar e o caminho de
  // sempre já resolveu; daqui para baixo mora o download, que é justamente o
  // que esta qualidade existe para não fazer.
  //
  // O item é o `kind: 'youtube'` que este app já conhece — o link sem bytes. Ele
  // não é uma novidade nem um caso à parte: é o que o compartilhamento cria
  // quando a transmissão e o download falham, e desde a v5.212 tocá-lo RESOLVE
  // no toque (`resolverLinkYoutube`), transmitindo. **Transmitir não troca o
  // item**, então o link continua link no domingo seguinte — que é o que
  // "Online" promete.
  //
  // O que o operador paga por isso está dito na folha e é uma coisa só: sem
  // internet no culto, não há o que projetar. O caminho de recuperação já
  // existe e não precisou de linha nenhuma — falhando a transmissão,
  // `resolverLinkYoutube` baixa e troca o item na posição em que ele está.
  if (altura === YT_ONLINE) {
    // Um link do MESMO vídeo já guardado é reaproveitado: dois registros para o
    // mesmo endereço seriam duas linhas iguais na lista, e o segundo não
    // acrescenta nada (não há bytes que os distingam).
    let rec = r && r.id ? await AVDB.mediaByYoutube(r.id, 'youtube') : null;
    if (!rec) {
      const thumb = (await thumbYoutube(r.id)) || ('https://img.youtube.com/vi/' + r.id + '/hqdefault.jpg');
      rec = await AVDB.addUrlMedia(r.url || ('https://www.youtube.com/watch?v=' + r.id), {
        kind: 'youtube',
        type: 'video/youtube',
        name: r.name || ('YouTube: ' + r.id),
        thumb,
        youtubeId: r.id,
        // O QUE O LINK LEVA CONSIGO (v1.5.21). Os dois já estavam na mão de quem
        // cria — a busca do YouTube devolve `seconds`/`author`, e um episódio de
        // série chega por `serieComoYoutube` com os mesmos — e eram descartados
        // aqui. É a única chance de gravá-los: um link não tem bytes de onde
        // medir, então o que não entrar agora não existe mais offline.
        seconds: r.seconds || null,
        canal: r.author || null,
        list: lista,
      });
    }
    if (!rec) { setYtEstado(r.id, 'erro'); pulsar(btn, 'erro'); return; }
    const novas = [];
    for (const l of listas) {
      if (!(await AVDB.listHas(l, rec.id))) novas.push(l);
      await AVDB.listAdd(l, rec.id);
    }
    // Promovido a lista de verdade, sai do slot avulso — a mesma ordem do
    // caminho do arquivo: primeiro entra, depois sai, senão o `listRemove`
    // coletaria o registro.
    if (guardar.length) await AVDB.listRemove('avulsos', rec.id);
    setYtEstado(r.id, 'pronto');
    pulsar(btn, novas.length ? 'ok' : 'dup');
    if (!guardar.length) await fixarAvulso(rec.id);
    if (listas.includes('playlist')) {
      plItems = await AVDB.listItems('playlist');
      renderPlaylist();
    }
    if (listas.includes('favs')) await recarregarFavoritos();
    await load();
    if (tocar) {
      // `resolverLinkYoutube` TRANSMITE, e transmitir não troca o item — o link
      // continua link depois de tocado, que é a promessa desta qualidade.
      await send(rec.id);
      return;
    }
    // Sem linha na tela e sem botão visível (o link compartilhado), os dois
    // canais de sempre estão mudos — e aqui não há download que se anuncie na
    // miniatura. A nota vai para a LINHA do item, como no caminho do arquivo.
    if (!ytLinhaVisivel(r.id)) {
      const onde = juntarFrases((novas.length ? novas : listas)
        .map((l) => (LISTA_ROTULO[l] || ROTULO_PADRAO).em));
      notaNoItem(rec.id, (novas.length ? 'link ' : 'já estava ') + onde,
        novas.length ? 'ok' : 'dup');
    }
    return;
  }

  const existente = r && r.id ? await AVDB.mediaByYoutube(r.id, soAudio ? 'audio' : 'video') : null;
  // "Já estava lá" é sobre o CONJUNTO: com mais de um destino, o que interessa
  // é se sobrou algo a fazer. Um vídeo que já está no Cronograma e não está nos
  // Favoritos não é uma duplicata — metade do pedido é nova.
  const listasNovas = [];
  for (const l of listas) {
    if (!(existente && existente.blob && await AVDB.listHas(l, existente.id))) listasNovas.push(l);
  }
  const jaNaLista = listas.length > 0 && listasNovas.length === 0;
  const rec = await ytArquivo(r, {
    lista,
    somenteAudio: soAudio,
    altura,
    naPreview: tocar,
    // O aviso na biblioteca só cala quando NENHUM destino é visível ali — e a
    // playlist é o único que não é. Com ela combinada ao Cronograma, o cartão
    // volta a valer.
    aviso: (guardar.length === 1 && guardar[0] === 'playlist') ? 'nenhum' : (tocar ? 'preview' : 'lib'),
    onPct: (pct) => setYtEstado(r.id, 'baixando', pct),
  });
  // FALAR QUANDO NÃO DEU. Até a v5.112 o download que falhava só apagava a
  // marca de "baixando" e sumia — nem item, nem erro, nem pista. Um download de
  // minutos que termina em nada é o pior silêncio possível do app, e ele valia
  // para todos os destinos, não só para o áudio.
  if (!rec) {
    // CANCELADO PELO OPERADOR não é falha: ele sabe o que aconteceu, porque
    // acabou de pedir. Pintar a linha de vermelho aqui seria o app discordando
    // de uma decisão dele.
    if (ytCancelados.has(r.id)) { ytCancelados.delete(r.id); setYtEstado(r.id, null); return; }
    // A FALHA FICA NA PRÓPRIA LINHA, não numa faixa flutuante (v5.119). O
    // estado `erro` pinta a miniatura do resultado — o mesmo canto que já
    // mostrava o anel de download e o ✓ de concluído. Ele é transitório: some
    // sozinho, e a linha volta a aceitar o toque, porque tentar de novo é
    // justamente o que se quer depois de uma falha de rede.
    setYtEstado(r.id, 'erro');
    setTimeout(() => { if ((ytEstado.get(r.id) || {}).estado === 'erro') setYtEstado(r.id, null); }, YT_ERRO_MS);
    pulsar(btn, 'erro');
    // SEM LINHA NA TELA, o vermelho não tem onde aparecer — é o caso do link
    // COMPARTILHADO (v5.137), que abre a folha sem busca nenhuma atrás. Quem
    // responde então é o CARTÃO DA PREVIEW: é o mesmo lugar em que este
    // download vinha se anunciando (`aviso: 'preview'`), e ele fica sobre a
    // preview, que é para onde o operador olha na tela principal. "Um download
    // de minutos que termina em nada" é o silêncio que este app não pode ter.
    // A FRASE DA JANELA DE ANTECEDÊNCIA vem na frente de "não foi possível
    // baixar" quando ela existe (v5.256): as duas descrevem o mesmo desfecho, e
    // só uma delas diz o que fazer a respeito.
    // A JANELA DE ANTECEDÊNCIA continua vencendo: ela é mais específica que
    // qualquer coisa que o shell saiba, e é a única das três que diz o que
    // fazer ("tente mais perto de 22/Ago"). Abaixo dela, o motivo do shell
    // quando ele nomeia um (v1.4.14) — o mesmo do caminho do item de link,
    // senão o MESMO vídeo conta duas histórias conforme onde foi tocado.
    const porque = r.avisoSeFalhar || await motivoDaRecusa('não foi possível baixar');
    if (r.avisoOnde) setCollStatus(r.avisoOnde, porque, 8000);
    if (!ytLinhaVisivel(r.id)) previewBusy('Baixando', r.name || 'o vídeo').falhar(porque);
    return;
  }
  setYtEstado(r.id, 'pronto');
  // O registro REAPROVEITADO pode estar em outra lista (ou só no slot avulso):
  // o download novo já nasceu na PRIMEIRA lista, mas nas outras não — e um
  // reaproveitado pode não estar em nenhuma. `listAdd` é idempotente, então o
  // laço vale para os dois casos sem perguntar qual é.
  if (guardar.length) {
    for (const l of listas) await AVDB.listAdd(l, rec.id);
    // Promovido a lista de verdade, sai do slot avulso — que existe só para
    // segurar o que não tem outro dono. A ordem importa: primeiro entra nas
    // listas novas, senão o `listRemove` coletaria o blob.
    await AVDB.listRemove('avulsos', rec.id);
    // SEM AVISO NO FIM DO DOWNLOAD (v5.119). No caminho do YouTube o botão
    // tocado NUNCA está visível quando a ação termina: a folha de destinos
    // fecha antes. O MOTIVO de uma falha vai para o cartão sobre a preview
    // (`previewBusy(…).falhar`) ou para a folha de origem (`#castMsg`) — a
    // faixa flutuante (`avisar()`) saiu na v5.207.
    //
    // E ela não fazia falta: quem já responde é a MINIATURA do resultado, que
    // troca o anel de download pelo ✓ (`setYtEstado('pronto')`), e a linha que
    // aparece na lista de destino. O aviso repetia por escrito o que a tela
    // acabara de mostrar.
    //
    // O `pulsar` fica, e só ele: quando o botão POR ACASO está visível (a
    // conversão de um link já no Cronograma, que não passa por folha nenhuma),
    // o pulso é o feedback no lugar certo. Sem botão visível, silêncio — a
    // miniatura já falou.
    pulsar(btn, jaNaLista ? 'dup' : 'ok');
    // E o mesmo raciocínio no desfecho BOM. Sem linha na tela e sem botão
    // visível, os dois canais de sempre estão mudos — e o item pode ter ido
    // para a playlist ou os Favoritos, que não são a lista à vista. Uma frase
    // curta dizendo PARA ONDE ele foi é o que fecha o compartilhamento.
    if (!ytLinhaVisivel(r.id)) {
      const onde = juntarFrases((jaNaLista ? listas : listasNovas)
        .map((l) => (LISTA_ROTULO[l] || ROTULO_PADRAO).em));
      // A NOTA VAI PARA A LINHA DO ITEM QUE ACABOU DE NASCER (v5.207) — e ele
      // existe agora, com id, em pelo menos uma lista. `focarImportado` leva o
      // operador até ela, e é lá que a frase o espera, em vez de numa faixa no
      // topo de uma tela que ele está deixando.
      notaNoItem(rec.id, (jaNaLista ? 'já estava ' : 'foi ') + onde, jaNaLista ? 'dup' : 'ok');
    }
  } else {
    await fixarAvulso(rec.id);
  }
  if (listas.includes('playlist')) {
    plItems = await AVDB.listItems('playlist');
    renderPlaylist();
  }
  if (listas.includes('favs')) await recarregarFavoritos();
  await load();
  // PERDEU A VEZ? (ver `palcoEmVoo`) A porta da BUSCA tem a mesma espera e o
  // mesmo desfecho da porta do item de link: o download leva minutos, e o
  // operador projeta outra coisa no meio. O arquivo já está guardado — o que
  // não pode é subir ao palco por cima da cena de outro.
  if (tocar && projecaoSeq === senhaDoToque) {
    // A mídia avulsa não está em `libItems` nem em `plItems`, então quem
    // resolve o nome dela é o `send` (que cai no `getMedia`).
    await send(rec.id);
  }
}

// Uma linha de resultado do YouTube. Mesma anatomia das linhas de música do
// acervo — miniatura à esquerda, nome e subtítulo — para a lista continuar
// sendo UMA lista, e não duas coladas.
function ytResultRow(r) {
  const li = document.createElement('li');
  li.className = 'lib-item hymn-result yt-result';
  li.dataset.yt = r.id;

  const row = document.createElement('div'); row.className = 'row hymn-row';
  const thumb = document.createElement('div'); thumb.className = 'thumb yt-thumb';
  if (r.thumb) {
    const im = document.createElement('img'); im.src = r.thumb; im.alt = ''; im.loading = 'lazy';
    thumb.appendChild(im);
  }
  const anel = document.createElement('span'); anel.className = 'dl-ring';
  anel.innerHTML = downloadArrowIconSvg();
  thumb.appendChild(anel);
  // O ✓ de concluído mora no mesmo lugar do anel: são os dois estados do mesmo
  // canto da miniatura, e a classe da linha decide qual aparece.
  const ok = document.createElement('span'); ok.className = 'yt-ok';
  ok.innerHTML = checkIconSvg();
  thumb.appendChild(ok);
  // E o TERCEIRO estado do mesmo canto: a falha. Ela morava numa faixa
  // flutuante no fim da tela, que foi para onde todo aviso deste app já não
  // vai — e o lugar certo é o mesmo em que o download foi anunciado.
  const err = document.createElement('span'); err.className = 'yt-err';
  err.innerHTML = closeIconSvg();
  thumb.appendChild(err);

  const info = document.createElement('div'); info.className = 'hymn-info';
  const nome = document.createElement('span'); nome.className = 'row-name';
  nome.textContent = r.name || '';
  const sub = document.createElement('span'); sub.className = 'hymn-sub';
  sub.textContent = [r.author, fmtDur(r.seconds)].filter(Boolean).join(' · ');
  info.append(nome, sub);

  const pct = document.createElement('span'); pct.className = 'dl-pct';
  row.append(thumb, info, pct);
  li.appendChild(row);
  pintarYtLinha(li, ytEstado.get(r.id));
  // O toque abre a MESMA folha de três escolhas das músicas do acervo — menos
  // no SIMPLIFICADO, onde ele toca e pronto: abrir uma folha com três opções
  // seria devolver ao operador exatamente a decisão que este modo poupa, e
  // duas delas (playlist, Cronograma) são listas que essa tela nem mostra. É a
  // mesma regra do toque numa música ali (`simplePlaySong`).
  li.addEventListener('click', () => {
    // BAIXANDO: o toque agora CANCELA (v5.131). Antes ele não fazia nada, e um
    // download começado por engano — o vídeo errado, o teto errado, a rede
    // ruim — só terminava esperando ele acabar. A confirmação existe porque o
    // toque nesta linha era inerte até ontem: quem tocar por reflexo não pode
    // perder um download de dez minutos por isso.
    if (li.classList.contains('baixando')) { cancelarDownloadYt(r); return; }
    // O teto vai EXPLÍCITO (`YT_ALTURAS[0]`, o padrão), como no share do
    // simplificado — deixá-lo implícito (undefined) fazia o mesmo "tocar"
    // viajar ora com altura, ora sem, e a diferença só aparecia em quem lê o
    // parâmetro lá na frente.
    if (appMode === 'simple') { ytAcao(r, 'tocar', null, false, YT_ALTURAS[0]); return; }
    openYtMenu(r);
  });
  return li;
}

// A mesma formatação de `fmtTime` — só a resposta ao zero difere: aqui a
// duração ausente vira string vazia (o subtítulo do resultado simplesmente
// não mostra nada), não "0:00".
function fmtDur(seg) {
  const n = Math.max(0, Math.floor(Number(seg) || 0));
  return n ? fmtTime(n) : '';
}

// O observador da sentinela de auto-busca. Um só, recriado a cada render — a
// lista é reconstruída a cada tecla, e um observador por render vazaria.
let ytAutoObs = null;
let ytAutoTimer = 0;
// A espera existe porque a lista é redesenhada A CADA TECLA: com poucos
// resultados o botão nasce visível, e sem ela a busca dispararia com o termo
// pela metade ("Fir"), uma vez por letra digitada. Meio segundo parado é o
// sinal de que o operador terminou de escrever.
const YT_AUTO_MS = 500;
function armarAutoBuscaYt(sentinela, termo) {
  if (ytAutoObs) { ytAutoObs.disconnect(); ytAutoObs = null; }
  clearTimeout(ytAutoTimer);
  // Nada a fazer se já pesquisou este termo, se está pesquisando, ou se o shell
  // não sabe pesquisar (ali o botão abre o YouTube por fora — disparar isso
  // sozinho seria tirar o operador do app sem ele ter pedido).
  if (ytBuscando || (ytBuscaItens && ytBuscaTermo === termo)) return;
  if (!window.__NATIVE__) return;
  ytAutoObs = new IntersectionObserver((entradas) => {
    if (!entradas.some((e) => e.isIntersecting)) { clearTimeout(ytAutoTimer); return; }
    clearTimeout(ytAutoTimer);
    ytAutoTimer = setTimeout(() => {
      // O termo pode ter mudado durante a espera — e aí esta busca é a de uma
      // pergunta que ninguém está mais fazendo.
      if (hymnSearchInputEl.value.trim() !== termo) return;
      if (!hymnSearchPopupEl.classList.contains('open')) return;
      buscarNoYoutube(termo);
    }, YT_AUTO_MS);
  }, { rootMargin: '0px' });
  ytAutoObs.observe(sentinela);
}

/**
 * ===== O RESULTADO DO YOUTUBE ESPERA A GAVETA FECHAR (v1.1.8) =====
 *
 * Relato do operador: *"se pesquiso na biblioteca e vou tocar uma música que já
 * está na biblioteca, ele fecha as opções de play quando mostra as opções do
 * YouTube, como um refresh da tela, semelhante ao que já acontecia durante o
 * download das coletâneas"*.
 *
 * É a MESMA armadilha do progresso dos downloads (`interacaoAbertaNoAcervo`),
 * por outra porta: `renderSearchResults` faz `hymnResultsEl.innerHTML = ''` e
 * remonta a lista, e o que ABRE uma linha vive no `li` que ele acabou de jogar
 * fora. Aqui é ainda menos esperado — a gaveta é de uma música que JÁ ESTÁ no
 * acervo, e quem redesenha é uma busca que o operador não pediu: a auto-busca
 * dispara sozinha quando a sentinela do rodapé entra em cena, e **ABRIR a gaveta
 * é justamente o que empurra a sentinela para dentro do campo de visão**.
 *
 * **A BUSCA não espera; só o REDESENHO dela.** Os bytes chegam no tempo deles e
 * a lista se atualiza assim que a gaveta fechar — o que não pode é a resposta de
 * uma pergunta lateral tirar do lugar o que o operador está usando.
 *
 * `imediato` é o toque EXPLÍCITO no botão de buscar: ali quem redesenha é o
 * operador, e a regra deste app é que a ação dele sempre vence (é o mesmo motivo
 * pelo qual uma tecla nova redesenha a lista sem perguntar por gaveta nenhuma).
 * O preço, dito: uma gaveta aberta DURANTE a busca que ele mesmo pediu se fecha.
 * O contrário seria um toque que não faz nada — que é pior.
 */
let ytRedesenhoTimer = 0;
const YT_REDESENHO_MS = 400;
function renderBuscaQuandoPuder(imediato) {
  clearTimeout(ytRedesenhoTimer);
  ytRedesenhoTimer = 0;
  // Biblioteca fechada: não há lista a redesenhar, e reabri-la a monta do zero.
  if (!hymnSearchPopupEl.classList.contains('open')) return;
  if (!imediato && interacaoAbertaNoAcervo()) {
    // REARMA em vez de marcar um pendente — a mesma escolha do tique do
    // progresso: a espera dura exatamente o tempo em que há gaveta aberta, e o
    // desfecho sai sozinho, sem depender de alguém lembrar de chamar isto de
    // dentro de cada caminho que fecha uma gaveta.
    ytRedesenhoTimer = setTimeout(() => renderBuscaQuandoPuder(false), YT_REDESENHO_MS);
    return;
  }
  renderSearchResults(hymnSearchInputEl.value);
}

// Pede a busca ao shell e redesenha a lista com o resultado. No navegador (e
// num shell antigo) não há como pesquisar de dentro do app: ali o toque volta a
// ser o que sempre foi — abrir o YouTube por fora.
async function buscarNoYoutube(termo, imediato) {
  if (!window.__NATIVE__) {
    openYoutubeSearch(termo);
    return;
  }
  if (ytBuscando) return;
  ytBuscando = true;
  ytBuscaTermo = termo;
  ytBuscaItens = null;
  renderBuscaQuandoPuder(imediato);
  try {
    const r = await AVNative.ytSearch(termo);
    ytBuscaItens = Array.isArray(r) ? r : [];
  } catch (_) {
    ytBuscaItens = [];
  } finally {
    ytBuscando = false;
    ytBuscaTermo = termo;
    renderBuscaQuandoPuder(imediato);
  }
}

function openYoutubeSearch(termo) {
  const url = 'https://www.youtube.com/results?search_query=' + encodeURIComponent(termo);
  if (!window.__NATIVE__) { window.open(url, '_blank', 'noopener'); return; }
  AVNative.openExternal(url);
}

// SVG inline (fora do subset da fonte): lupa. Deliberadamente NÃO é o logotipo
// do YouTube — o que este botão faz é uma BUSCA, e desenhar a marca de outro
// app num botão do nosso promete que ele abre lá dentro em algum lugar
// específico. Quem nomeia o destino é o texto ao lado.
//
// O DESENHO mora no sprite do `index.html` desde a v5.264 (`#icoLupa`), porque
// a barra de busca da Biblioteca passou a usá-lo também: duas cópias do mesmo
// ícone divergem no primeiro ajuste, e é para isso que aquele sprite existe.
function searchIconSvg() {
  return '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="#icoLupa"/></svg>';
}

// ===== OS DETALHES DE UM VÍDEO: EM MEMÓRIA, E SÓ EM MEMÓRIA (v1.5.21) =====
//
// Pedido do operador: *"coloque dados como duração, nome completo, canal e
// descrição se for possível obter"*. Duração e canal são do índice da série e
// valem OFFLINE (ver `serieFaixaDoItem`); a DESCRIÇÃO não vem em listagem
// nenhuma — ela custa uma extração POR VÍDEO —, e por isso ela é a única dos
// quatro que precisa de rede e a única que exigiu um método novo da ponte
// (`AVNative.ytDetalhes`, shell 62).
//
// E O TÍTULO CRU ENTROU NA MESMA CARONA (v1.6.0). O índice de uma SÉRIE o
// guarda (`serieFaixaDoItem`), mas um LINK salvo nunca teve título cru: o
// registro guarda só o `name` já tratado, então a linha do título simplesmente
// não existia ali — que foi o relato (*"não estou vendo o título completo e
// original do vídeo do link"*). O `ytDetalhes` já devolvia o `titulo` ao lado
// da descrição e ele era descartado no caminho; guardar o OBJETO em vez do
// texto custa zero requisição a mais.
//
// **NADA DISTO VAI PARA O DISCO, e o precedente é o da CIFRA, palavra por
// palavra:** um `Map` que morre com o app, nada em IndexedDB, nada no bundle do
// OTA, nada no repositório. Guardar mudaria o recurso de NATUREZA — o app
// deixaria de LER conteúdo de terceiro no aparelho do operador e passaria a
// DISTRIBUIR uma cópia dele. As duas coisas não são degraus da mesma escada.
//
// O CACHE É POR VÍDEO E NÃO POR LINHA: a mesma lista é remontada a cada tecla
// da busca e a cada marca de destino, e sem ele reabrir a gaveta do mesmo
// episódio gastaria uma extração nova — na fila que o "Tocar agora" divide.
//
// **`null` NÃO É GUARDADO.** A ponte separa "não houve resposta" (`null`) de
// "respondeu e não há descrição" (`descricao: ''`), e é a mesma disciplina do
// `sem-rede` da cifra: um Wi-Fi que oscilou não pode custar um buraco que só
// some fechando o app. O vazio, esse, é resposta — e guardá-lo é o que impede a
// gaveta de gastar uma extração por abertura num vídeo sem descrição.
const ytDetalhesCache = new Map();   // id do vídeo → { titulo, canal, descricao } saneados

/**
 * Os detalhes de UM vídeo, do cache ou da ponte — `{ titulo, canal, descricao }`,
 * cada campo já saneado para string (`''` = não veio). `null` quando não houve
 * RESPOSTA: sem ponte (navegador), sem URL e sem rede.
 *
 * A distinção entre `null` e campo vazio é o recurso, não um detalhe: o
 * primeiro não é guardado e é retentado, o segundo é resposta e fica no cache —
 * é o que impede a gaveta de gastar uma extração por abertura num vídeo sem
 * descrição.
 *
 * A guarda é `window.__NATIVE__`, e SÓ ela — nunca uma comparação de
 * `__SHELL_VERSION__`. O bundle declara `minShell`, então o piso garante a
 * ponte inteira e não há método a conferir; guarda de versão no lado web é
 * proibida por escrito. O que separa navegador de app é esta linha, e nada mais.
 */
async function detalhesDoVideo(id, url) {
  if (!window.__NATIVE__ || !url) return null;
  const chave = id || url;
  const guardado = ytDetalhesCache.get(chave);
  if (guardado !== undefined) return guardado;
  const d = await AVNative.ytDetalhes(url);
  if (!d) return null;         // não houve resposta: nada guardado, tenta de novo
  const det = {
    titulo: String(d.titulo || ''),
    canal: String(d.canal || ''),
    descricao: String(d.descricao || ''),
  };
  ytDetalhesCache.set(chave, det);
  return det;
}

// ===== UMA LINHA, UM TOQUE, UMA GAVETA =====
//
// A linha era `[▶] [nome / subtítulo] [+]` — dois botões, cada um abrindo uma
// FOLHA com metade das escolhas. Com dois alvos, decidir "o que fazer com este
// hino?" exigia primeiro decidir QUAL DOS DOIS é o dono da pergunta, e essa é
// uma pergunta sobre a UI, não sobre o culto. Um alvo só, e a lista inteira do
// outro lado, no corpo da linha (nunca um popup). Os dois botões custavam
// 40 + 34 px mais os vãos numa linha de celular; o nome recebe isso de volta.
//
// A GAVETA NÃO PERDEU A LETRA: opções em cima, letra (ou detalhe do vídeo)
// logo abaixo, na mesma abertura. A letra responde "é este mesmo?" e é dela que
// sai o trecho marcado quando a busca casou no meio de uma estrofe.
//
// `semColecao` = a linha já está DENTRO do card da coleção (acordeão do
// acervo): repetir o nome do álbum em cada faixa é ruído.
function hymnResultRow(coll, s, lyricHit, semColecao) {
  const li = document.createElement('li');
  li.className = 'lib-item hymn-result';

  // A chave da linha: é por ela que o indicador de download reencontra esta
  // música depois de um redesenho (ver setSongRowBusy).
  const chave = songRowKey(coll, s);
  li.dataset.song = chave;

  const row = document.createElement('div'); row.className = 'row hymn-row';
  // O QUADRADO DA ESQUERDA DEIXOU DE SER UM BOTÃO (v5.285) e virou um
  // INDICADOR. Ele fica porque carrega o ANEL DE DOWNLOAD — a única coisa que
  // aquele canto sempre informou de verdade — e porque é ele que dá à faixa a
  // altura e a coluna que a lista inteira alinha. `<span>`, sem `title` e sem
  // ouvinte: um alvo que não é alvo, num canto onde o dedo mira, seria pior que
  // não ter nada. Quem responde ao toque agora é a linha inteira.
  const play = document.createElement('span');
  play.className = 'hymn-play-thumb' + (songRowBusy.has(chave) ? ' busy' : '');
  play.setAttribute('aria-hidden', 'true');
  play.appendChild(msym(ICON.play));
  // O anel de download convive com o ▶ no mesmo lugar: a classe `busy` troca
  // qual dos dois aparece. Montá-lo aqui, e não na hora, é o que faz a marca
  // sobreviver ao redesenho da lista (o progresso da sincronização redesenha o
  // acervo a cada 400 ms).
  const anel = document.createElement('span');
  anel.className = 'dl-ring'; anel.setAttribute('aria-hidden', 'true');
  anel.innerHTML = downloadArrowIconSvg();
  play.appendChild(anel);

  const info = document.createElement('div'); info.className = 'hymn-info';
  const name = document.createElement('span'); name.className = 'row-name hymn-name';
  name.textContent = songLabel(coll, s);
  info.appendChild(name);
  // Subtítulo: a coleção de origem. A duração saiu daqui e virou coluna própria
  // à direita.
  if (!semColecao) {
    const sub = document.createElement('span'); sub.className = 'hymn-sub';
    sub.textContent = coll.name;
    info.appendChild(sub);
  }
  // Casou pela LETRA: mostra a linha. Sem ela, o resultado apareceria sem
  // nenhuma relação visível com o que foi digitado — e o operador não teria
  // como saber se é o hino certo sem abrir um por um.
  if (lyricHit) {
    const hit = document.createElement('span'); hit.className = 'hymn-lyric-hit';
    hit.textContent = lyricHit.length > 100 ? lyricHit.slice(0, 100) + '…' : lyricHit;
    info.appendChild(hit);
  }

  // A COLUNA DA DIREITA ESTÁ VAZIA, e é a segunda vez que ela esvazia. A
  // DURAÇÃO saiu dela na v5.62 ("ninguém escolhe o louvor pelo tempo dele") e o
  // lugar foi para o `+`; o `+` saiu na v5.285, e agora quem recebe a largura é
  // o NOME — a única coisa da linha que não se adivinha, e a que mais cortava.
  row.append(play, info);

  // ===== A GAVETA DA LINHA: o que ela abre depende do TIPO =====
  //
  // Ela responde uma pergunta só — **"é este mesmo?"** —, e a resposta muda com
  // o item. Numa música é a LETRA: é por ela que se reconhece o hino certo, e é
  // dela que sai o trecho marcado quando a busca casou no meio de uma estrofe.
  // Num VÍDEO não existe letra nenhuma, e até a v5.235 a gaveta abria assim
  // mesmo, para anunciar "Letra ainda não baixada" — uma promessa de algo que
  // nunca vai chegar, e o relato que abriu este lote. Ali a mesma pergunta é
  // respondida pela MINIATURA e pela duração, que é o que o operador tem para
  // reconhecer um episódio de que ele só sabe a data.
  //
  // Só é montada quando a linha ABRE (e uma vez só): montá-la para todos os
  // resultados encheria a lista de centenas de nós que ninguém pediu — e a
  // lista é reconstruída a cada tecla.
  // A GAVETA DE UMA MÚSICA É SÓ AS OPÇÕES (v1.2.25). Ela teve duas metades —
  // opções em cima, letra embaixo — e a de baixo saiu: a letra numa CAIXA DE
  // TEXTO dentro da gaveta era uma segunda leitura, pior que a que o app já
  // tem. Quem quer ler abre o LEITOR (`openLyricsPopup`), com cifra, tom,
  // corpo de letra e rolagem; e quem só quer conferir "é este mesmo?" já tem o
  // trecho casado na própria linha do resultado (`hymn-lyric-hit`).
  //
  // Num VÍDEO a metade de baixo FICA: ali ela não é letra, é a miniatura, a
  // duração e o estado no aparelho — a única forma de reconhecer um episódio
  // de que se sabe só a data, e nada disso cabe num leitor de letra.
  const gaveta = document.createElement('div');
  gaveta.className = 'hymn-gaveta';
  const opcoes = document.createElement('ul');
  opcoes.className = 'song-menu-list hymn-opcoes';
  const conteudo = document.createElement('div');
  conteudo.className = 'item-detalhe';
  gaveta.append(opcoes);
  if (!temLetra(coll)) gaveta.appendChild(conteudo);
  let gavetaMontada = false;

  // A gaveta de um VÍDEO. Sem prometer nada que dependa de rede: a miniatura é
  // ilustração (sai de cena sozinha se não carregar) e as duas linhas de texto
  // valem offline.
  // AS OPÇÕES DA LINHA. Elas são exatamente as da folha que existia até a
  // v5.284 — os mesmos executores, os mesmos destinos marcáveis, o mesmo
  // confirmar —, escritas no corpo em vez de num popup. O que muda é o ALVO, e
  // é por isso que nada aqui reimplementa nada: `renderSongMenu`/`openYtMenu`
  // ganharam para onde escrever (`songMenuFor.alvo`).
  //
  // UM EPISÓDIO DE SÉRIE desvia para a lista do YouTube, como a folha já fazia
  // desde a v5.230 (`openSongMenu` → `openYtMenu`): ali as escolhas são outras
  // — transmitir sem baixar, o teto de qualidade — e o resto desta função monta
  // justamente o que não se aplica a ele.
  //
  // `destLimpar()` a cada abertura: os destinos marcados são DESTA linha e não
  // atravessam de um item para o outro. O acordeão fecha a linha anterior, então
  // há no máximo uma gaveta aberta — é isso que deixa `songMenuFor`,
  // `destExecutor` e `destRemontar` continuarem sendo um só.
  function montarOpcoes() {
    destLimpar();
    // O BOTÃO IRMÃO do confirmar (v5.286): quem revela a metade de baixo da
    // gaveta. Ele é recriado a cada remontagem da lista (o seletor de variante,
    // cada marca de destino), então o ESTADO não pode morar nele — mora na
    // classe do `li`, que sobrevive.
    const aoLado = () => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'song-menu-btn song-menu-letra';
      // NUMA MÚSICA O BOTÃO ABRE O LEITOR (v1.2.25), e não uma caixa de texto
      // aqui embaixo: é a MESMA folha do transporte — letra, cifra, tom, corpo
      // e rolagem —, apontada para esta faixa e SEM levar nada ao telão.
      // Reusar, nunca reconstruir: uma segunda leitura divergiria da primeira
      // no primeiro ajuste, e quem lesse por ela veria a versão de ontem.
      if (temLetra(coll)) {
        const cx = document.createElement('span');
        cx.className = 'song-menu-label';
        cx.textContent = 'Ver a letra';
        b.appendChild(cx);
        b.addEventListener('click', async (e) => {
          e.stopPropagation();
          openLyricsPopup(await lvItemDaBiblioteca(coll, s));
        });
        return b;
      }
      // Num VÍDEO ele continua sendo o interruptor da metade de baixo da
      // gaveta, que ali é a miniatura e o estado no aparelho.
      const nome = 'os detalhes';
      // ===== A LARGURA NÃO MUDA COM O ESTADO (v5.287) =====
      //
      // Pedido do operador: *"fixe a largura do botão de ver/ocultar letra, para
      // que tenha o mesmo tamanho nos dois estados"*. "Ocultar" é mais longo que
      // "Ver", então o botão crescia ao ser tocado e o CONFIRMAR ao lado
      // encolhia junto — um toque que muda a largura do vizinho é a coisa que
      // mais parece defeito numa faixa de dois botões.
      //
      // As DUAS frases entram, empilhadas na mesma célula de uma grade 1×1: a
      // largura passa a ser a da MAIOR e a troca só alterna qual delas se vê.
      // Um `min-width` em `ch` seria um número a manter contra a fonte e contra
      // a tradução; isto não tem número nenhum.
      const cx2 = document.createElement('span');
      cx2.className = 'song-menu-label song-menu-letra-cx';
      const ver = document.createElement('span'); ver.textContent = 'Ver ' + nome;
      const ocultar = document.createElement('span'); ocultar.textContent = 'Ocultar ' + nome;
      cx2.append(ver, ocultar);
      b.appendChild(cx2);
      b.addEventListener('click', (e) => {
        e.stopPropagation();
        // ===== O GATILHO DOS DETALHES É A REVELAÇÃO, e não a abertura da linha =====
        //
        // Eles custam uma extração de rede na fila que o "Tocar agora" divide, e
        // são a única parte do card que custa alguma coisa. Pendurá-la no toque
        // na LINHA gastaria uma extração por gaveta aberta — inclusive nas que o
        // operador abre só para mandar o episódio ao Cronograma —, e pendurá-la
        // na montagem da LISTA gastaria uma por episódio do álbum, que é
        // exatamente a varredura que a fila de extração proíbe.
        //
        // Aqui é uma por vídeo OLHADO, e só quando a metade de baixo entra em
        // cena: é a mesma regra do `cifraCabe`, pelo mesmo motivo.
        //
        // E roda com o card JÁ VISÍVEL, o que resolve de graça o acordeão: ele
        // já mediu e terminou muito antes, esta revelação não é animada, e a
        // altura da gaveta é `auto` quando o texto chega.
        if (li.classList.toggle('vendo-letra')) pedirDetalhes();
      });
      return b;
    };
    if (ehLink(coll)) {
      // O MESMO `r` nas duas chamadas, e isso é o que faz a segunda funcionar:
      // `openYtMenu` só rearma o estado quando o item MUDA (`songMenuFor.yt !==
      // r`), então repetir com o mesmo objeto preserva o `aoLado` que acabou de
      // ser posto e apenas redesenha a lista com ele. Um `serieComoYoutube`
      // novo seria outro objeto — o estado seria zerado e o irmão sumiria.
      const r = serieComoYoutube(coll, s);
      openYtMenu(r, opcoes);
      if (songMenuFor) { songMenuFor.aoLado = aoLado; openYtMenu(r, opcoes); }
      return;
    }
    songMenuFor = { coll, s, variant: 'full', alvo: opcoes, aoLado };
    // A marca nasce AQUI e não em `renderSongMenu`: aquela função é também o
    // `destRemontar` (o seletor Cantada/Playback e cada marca de destino a
    // chamam de volta), e remarcar lá dentro tornaria o "Tocar agora"
    // impossível de DESMARCAR — o toque tiraria a marca e o redesenho a
    // devolveria, no mesmo quadro.
    destPadraoTocar();
    renderSongMenu();
  }

  // OS DETALHES DA REDE, quando eles chegam — o título cru e a descrição.
  // Row-scoped porque o alvo é o `conteudo` desta linha; o CACHE é de módulo
  // (`ytDetalhesCache`), e é ele que impede uma segunda extração quando a mesma
  // gaveta é reaberta.
  let detPedidos = false;
  async function pedirDetalhes() {
    if (detPedidos || !ehLink(coll)) return;
    detPedidos = true;
    let det = null;
    try {
      det = await detalhesDoVideo(s.id_music, s.ytUrl);
    } catch (_) { det = null; }
    // SEM RESPOSTA, SEM BLOCO — e a tentativa volta a valer. Um card sem a
    // linha da descrição é o mesmo card de antes deste lote; um bloco vazio (ou
    // com um "não foi possível obter") seria o app contando o próprio
    // funcionamento a quem perguntou pelo vídeo.
    if (!det) { detPedidos = false; return; }
    // AS DUAS COISAS, e cada uma com a guarda dela: um vídeo pode ter título e
    // não ter descrição (e vice-versa), e a resposta certa a um campo vazio é a
    // ausência da linha, nunca uma linha vazia.
    if (det.titulo) pintarTitulo(det.titulo);
    if (det.descricao) pintarDescricao(det.descricao);
  }

  // ===== O TÍTULO CRU QUE VEIO DA REDE (v1.6.0) =====
  //
  // Ele entra NO TOPO da coluna de texto, e não no fim: a ordem do card é
  // título → canal → duração → estado, e este chega depois de todos os outros
  // já estarem desenhados. `insertBefore` no primeiro filho é o que preserva a
  // ordem das PERGUNTAS (*o que é isto?* antes de *de quem?*).
  //
  // DUAS GUARDAS, e nenhuma é redundante. A primeira: num EPISÓDIO de série o
  // índice já deu o título cru (`s.nomeOriginal`) e a linha já está lá —
  // desenhar de novo seria a mesma frase duas vezes. A segunda é a régua que o
  // `montarDetalhe` já usa: um título IGUAL ao rótulo da linha logo acima não
  // acrescenta nada.
  function pintarTitulo(titulo) {
    const txt = conteudo.querySelector('.item-detalhe-txt');
    if (!txt || conteudo.querySelector('.item-detalhe-titulo')) return;
    const t = String(titulo).trim();
    if (!t || t === String(s.name || '').trim()) return;
    const el = document.createElement('span');
    el.className = 'item-detalhe-linha item-detalhe-titulo';
    // `textContent` e nunca `innerHTML`: é texto de TERCEIRO, e o Controle roda
    // no origin que injeta `__AVBridge` em toda página que carrega.
    el.textContent = t;
    txt.insertBefore(el, txt.firstChild);
  }

  // ===== A DESCRIÇÃO É TEXTO, E ELA VEM INTEIRA (v1.6.0) =====
  //
  // `textContent` e NUNCA `innerHTML`: isto é texto de TERCEIRO e o Controle
  // roda no origin privilegiado, o que injeta `__AVBridge` em toda página que
  // carrega. A outra metade da regra mora no Kotlin, e é ela que torna esta
  // barata: `YoutubeGrab.detalhes` já achata o HTML que o YouTube manda quando
  // a descrição tem links, então o que chega aqui é texto e a tela não mostra
  // marcação literal.
  //
  // SEM CLAMP E SEM "VER MAIS". Pedido do operador: *"ajuste para que não
  // precise do 'ver mais' nos detalhes, já deixe tudo aberto de uma vez"*. O
  // recorte em quatro linhas custava um toque a mais para ler o que o card foi
  // buscar, e a gaveta já é um acordeão que se abre e se fecha inteiro — o
  // segundo grau de revelação dentro dele não respondia a pergunta nenhuma.
  // (O único teto que sobra é o do Kotlin, `DESCRICAO_MAX`, e ele é de
  // TRANSPORTE — não é o que a tela mostra.)
  function pintarDescricao(texto) {
    if (!conteudo.isConnected || conteudo.querySelector('.item-detalhe-desc')) return;
    const cx = document.createElement('div');
    cx.className = 'item-detalhe-desc';
    const p = document.createElement('p');
    p.className = 'item-detalhe-desc-txt';
    p.textContent = texto;
    cx.appendChild(p);
    conteudo.appendChild(cx);
  }

  async function montarDetalhe() {
    conteudo.innerHTML = '';
    if (s.thumb) {
      const im = document.createElement('img');
      im.className = 'item-detalhe-thumb';
      im.src = s.thumb; im.alt = ''; im.loading = 'lazy';
      // A imagem é de fora e pode simplesmente não vir (sem internet, canal que
      // trocou a arte). Um retângulo quebrado no meio da gaveta é pior que
      // gaveta sem imagem, e o resto dela continua verdadeiro sem a foto.
      im.addEventListener('error', () => im.remove());
      conteudo.appendChild(im);
    }
    const txt = document.createElement('div'); txt.className = 'item-detalhe-txt';
    // ===== O QUE O CARD DIZ, E EM QUE ORDEM (v1.5.21) =====
    //
    // Pedido do operador: *"coloque dados como duração, nome completo, canal e
    // descrição se for possível obter"*. Os três primeiros já chegavam do
    // extrator e eram descartados no caminho (ver `serieFaixaDoItem`); a
    // DESCRIÇÃO não existe em lugar nenhum deste lado e é a única que exige um
    // método novo da ponte — ela entra como mais uma `linha()` aqui, sem mexer
    // no resto, e é por isso que este montador não ganhou estrutura para ela.
    //
    // A ORDEM é a das perguntas: *o que é isto?* (título) · *de quem?* (canal) ·
    // *quanto dura?* · *já está aqui?* (o estado, e só quando está). A
    // identidade vem primeiro porque é ela que decide se o operador vai
    // adiante — o resto são atributos do que ele já reconheceu.
    //
    // CADA LINHA SÓ EXISTE SE O DADO EXISTIR, e a guarda é POR CAMPO e nunca
    // por versão de bundle: entre este bundle chegar por OTA e a varredura
    // refazer o índice há uma janela em que `canal` e `nomeOriginal` são
    // `undefined` no que já está guardado. É a mesma regra do Registro — a
    // linha ausente some, nunca escreve "undefined" num card que alguém lê.
    const linha = (texto, classe) => {
      const t = String(texto == null ? '' : texto).trim();
      if (!t) return;
      const el = document.createElement('span');
      el.className = 'item-detalhe-linha' + (classe ? ' ' + classe : '');
      // `textContent` e nunca `innerHTML`: isto é texto de TERCEIRO (o título e
      // o nome do canal saem do YouTube) e o Controle roda no origin
      // privilegiado, o que injeta `__AVBridge`. A mesma regra governa a
      // DESCRIÇÃO (`pintarDescricao`), que é o campo em que ela custa caro — o
      // YouTube o entrega em HTML quando há links, e por isso quem o achata é o
      // Kotlin, antes de a string atravessar a ponte.
      el.textContent = t;
      txt.appendChild(el);
    };
    // O TÍTULO COMPLETO, e só quando ele acrescenta alguma coisa. O rótulo da
    // lista é podado por construção (a data na frente, o pedaço à esquerda da
    // barra — e no `TITULO_SERIE` o nome do episódio some inteiro), então o cru
    // quase sempre difere; comparar em vez de desenhar sempre é o que impede a
    // MESMA frase duas vezes na tela quando eles coincidem.
    //
    // Aqui ele vem do ÍNDICE, que é o caminho OFFLINE e vale para um episódio
    // de série. Um LINK salvo não tem título cru guardado — quem o traz é a
    // rede, no `pintarTitulo`, com as mesmas duas guardas.
    if (s.nomeOriginal && s.nomeOriginal !== String(s.name || '').trim()) {
      linha(s.nomeOriginal, 'item-detalhe-titulo');
    }
    linha(s.canal);
    if (s.duration) linha('Duração ' + s.duration);
    conteudo.appendChild(txt);
    // ===== O ESTADO SÓ APARECE QUANDO ELE É FATO DO ARQUIVO (v1.6.0) =====
    //
    // A linha nascia sempre, com "Toca sem baixar", e virava "Já no aparelho"
    // quando havia bytes. Pedido do operador: *"remover a frase 'toca sem
    // baixar' que tem na descrição do ver detalhes"* — *"essa informação é útil
    // apenas quando estiver escolhendo a qualidade, no caso, não é um 'detalhe
    // do arquivo', mas sim uma das características da opção de play"*.
    //
    // Ele separa duas coisas que estavam na mesma linha: "toca sem baixar"
    // descreve a OPÇÃO DE PLAY — e o "Tocar agora", duas linhas acima no mesmo
    // card, já diz *"Toca direto da internet…"* —, enquanto "já no aparelho" é
    // FATO DO ARQUIVO, que é do que este card fala. Logo a linha existe só no
    // segundo caso; no comum ela simplesmente não é desenhada, e o card fica
    // com o que ele de fato sabe.
    //
    // Assíncrono e DEPOIS de a coluna já estar montada — e é seguro porque este
    // montador é AWAITADO antes do `expandAccordion` (ver o ouvinte da `.row`):
    // o acordeão mede a altura com a linha já no lugar.
    try {
      // `mediaByYoutube` devolve UM registro (ou `null`), nunca um array — e a
      // pergunta é pelo BLOB, como em `marcarYtProntos` e `ytArquivo`. Um item
      // criado pela qualidade "Online" (`addUrlMedia`, kind `youtube`) tem
      // registro e NÃO tem bytes: anunciá-lo como "Já no aparelho" trocaria um
      // defeito por outro.
      const rec = await AVDB.mediaByYoutube(s.id_music);
      if (rec && rec.blob) linha('Já no aparelho', 'item-detalhe-estado done');
    } catch (_) { /* sem resposta do banco, sem linha: é o caso comum */ }
  }


  row.addEventListener('click', async () => {
    // No simplificado a linha TOCA — não abre gaveta nenhuma.
    if (appMode === 'simple') { simplePlaySong(coll, s); return; }
    const aberta = li.classList.contains('expanded');
    // Acordeão: abrir uma fecha a anterior — duas linhas abertas ao mesmo
    // tempo empurrariam a lista e tirariam do lugar o que o operador mira. O
    // escopo é a LISTA desta linha, não `hymnResultsEl`: as linhas de dentro do
    // card de um álbum vivem noutra `<ul>`, e ali a regra simplesmente não
    // valia — abrir a terceira faixa deixava as duas anteriores abertas.
    const lista = li.parentElement;
    if (lista) {
      lista.querySelectorAll(':scope > .hymn-result.expanded').forEach((el) => {
        if (el !== li) el.classList.remove('expanded');
      });
    }
    if (aberta) { collapseAccordion(gaveta, () => li.classList.remove('expanded')); return; }
    // ===== A MARCA DE "ABRINDO" É SÍNCRONA (v1.1.2) =====
    // Ela existe para o `interacaoAbertaNoAcervo` enxergar esta linha ANTES do
    // primeiro `await` abaixo: com um download correndo, o redesenho do
    // progresso (a cada 400 ms) alcançava a lista no meio da montagem, o `li`
    // deste toque virava órfão e o `expanded` das últimas linhas caía num nó
    // fora do documento — o toque não abria nada e nada explicava por quê.
    // Sem CSS próprio de propósito: é estado, como `expanded` e `vendo-letra`.
    li.classList.add('abrindo');
    try {
      // A gaveta é montada ANTES de abrir: a animação mede a altura do que vai
      // ficar em cena, e uma caixa ainda vazia mediria zero. Uma vez só — a
      // guarda vive AQUI, e não dentro de cada montador, para os dois não terem
      // de repeti-la (e para o próximo tipo não poder esquecê-la).
      if (!gavetaMontada) {
        gavetaMontada = true;
        montarOpcoes();
        if (!temLetra(coll)) await montarDetalhe();
      }
      li.classList.add('expanded');
      expandAccordion(gaveta);
    } finally {
      // No `finally` porque um montador que lance não pode deixar a marca
      // presa: ela seguraria o redesenho do acervo até a linha sair da tela.
      li.classList.remove('abrindo');
    }
  });

  li.append(row, gaveta);
  return li;
}

// ===== A folha rápida de um item do acervo =====
// Dois botões na linha, duas folhas. Cada uma lista as três coisas que aquele
// botão pode fazer, ESCRITAS — é o que os seis ícones mudos da versão anterior
// não conseguiam dizer.
let songMenuFor = null;   // { coll, s, variant } — `variant` é a escolha da folha de adicionar

// ===== MARCAR MAIS DE UM DESTINO NA MESMA FOLHA (v5.141) =====
//
// A folha nasceu como "uma pergunta, uma resposta": cada linha era uma ação
// completa e o toque fechava tudo. O toque continua sendo isso — nada do que
// funcionava mudou de lugar —, mas cada linha de DESTINO ganhou uma caixa de
// marcação na borda direita.
//
// A regra é uma só, e vale para as duas folhas (acervo e YouTube):
//
//  - **Toque no corpo da linha** = executa AGORA, para aquele destino MAIS o
//    que já estiver marcado. É o caminho de um toque de sempre quando não há
//    nada marcado, e é o que fecha a escolha quando há: marcar "Playlist" e
//    tocar em "Cronograma" manda para os dois. Ignorar o que está marcado seria
//    o app desfazer, calado, uma escolha que o operador acabou de fazer.
//  - **Toque na caixa** = só marca (ou desmarca) e a folha CONTINUA aberta.
//  - Com pelo menos um marcado aparece a linha de confirmação no fim da folha,
//    para o caso em que todos os destinos desejados já estão marcados e não
//    sobrou nenhuma linha para tocar.
//
// O conjunto é da FOLHA ABERTA, não do item: ele nasce vazio a cada abertura,
// pelo mesmo motivo que o teto de resolução do YouTube nasce no padrão a cada
// item — uma marcação que grudasse mandaria para os Favoritos, sem aviso, o
// vídeo que se quis ver uma vez no domingo seguinte.
const destMarcados = new Set();
// Quem sabe EXECUTAR os destinos desta folha: `(chaves, btn) => Promise`. É
// definido por quem monta a folha (o acervo e o YouTube fazem coisas diferentes
// com a mesma lista de destinos) e lido pela linha de confirmação.
let destExecutor = null;
// E quem sabe REDESENHÁ-LA. Ele existe por um defeito medido (v5.254): marcar
// uma opção muda o desenho de DUAS coisas — a caixa daquela linha e o rótulo do
// confirmar —, e quem as reconstrói é o redesenho da folha. Ele era um
// argumento por linha (`aoMudar`), e a linha do "Tocar agora" foi a única que
// não o recebeu quando ela virou selecionável: o toque marcava o destino e a
// tela não mudava um pixel. Do lado de quem opera, "o check não funciona".
//
// Argumento que cada chamador precisa lembrar de passar é a mesma classe de
// erro que o `native.js` já cobra em outro lugar (campo novo = campo novo lá).
// Como hook de módulo, definido UMA vez por folha, a linha nova nasce
// funcionando — e um esquecimento deixa de ser possível.
let destRemontar = null;

function destLimpar() { destMarcados.clear(); destExecutor = null; destRemontar = null; }

// A união do que está marcado com a linha em que se tocou, na ordem da tabela —
// para o aviso sair sempre na mesma ordem, e não na ordem em que o operador
// marcou.
function destUniao(chave) {
  const alvo = new Set(destMarcados);
  if (chave) alvo.add(chave);
  const ordem = DESTINOS.map((d) => d.chave).filter((c) => alvo.has(c));
  // Chaves que não estão na tabela (o `tocar` do YouTube) entram no fim: elas
  // não são lista nenhuma, e quem as trata é o executor.
  return ordem.concat([...alvo].filter((c) => !ordem.includes(c)));
}

/**
 * UM EPISÓDIO DE SÉRIE É UM VÍDEO DO YOUTUBE, e a folha dele é a mesma (v5.230).
 *
 * Pedido do operador: *"o tratamento que deve ter os itens da lista do provai e
 * vede, e suas opções, devem ser o mesmo dos vídeos do YouTube (sem a opção de
 * apenas áudio). no caso eu não quero um download direto, e também quero a opção
 * de tocar diretamente em stream pelo link sem o download"*.
 *
 * A v5.228 tratou a série como uma coleção do LouvorJA porque é dali que a
 * casca do card veio — e naquele mundo o toque BAIXA (uma faixa de hinário são
 * poucos MB e o acervo existe para ficar offline). Aqui a premissa não vale: são
 * ~300 MB por episódio, e o vídeo do sábado é visto uma vez. Quem já resolvia
 * isso é o caminho do YouTube, com a TRANSMISSÃO DIRETA no "Tocar agora" e o
 * download só nos destinos que GUARDAM.
 *
 * `semSoAudio` é a única diferença: o seletor Vídeo × Só áudio some. Um
 * testemunho em vídeo não tem versão de áudio que faça sentido projetar, e uma
 * escolha que não muda nada é pior que escolha nenhuma.
 */
function serieComoYoutube(coll, s) {
  const r = { id: s.id_music, url: s.ytUrl, name: s.name, semSoAudio: true,
    // OS DOIS QUE VIAJAM PARA O REGISTRO (v1.5.21). Um episódio guardado como
    // LINK ("Online") ou baixado nasce com a duração e o canal que o índice já
    // sabe — sem eles, o mesmo vídeo perdia os dois ao sair do álbum para o
    // Cronograma. Os nomes são os do `r` da BUSCA (`seconds`/`author`), porque
    // quem os consome é o mesmo caminho: `ytAcaoInterno` e `ytArquivo` não
    // podem ter de perguntar de onde o item veio.
    seconds: s.seconds || 0, author: s.canal || '' };
  // A LINHA DE ONDE ELE VEIO. Um episódio é um vídeo do YouTube, mas ele não é
  // desenhado por `ytResultRow` — a lista dele é a da COLEÇÃO (`hymnResultRow`,
  // com `data-song`), e o indicador de download de lá é o anel do quadrado à
  // esquerda. `setYtEstado` pintava só `.yt-result`, então mandar um episódio
  // para o Cronograma não acendia NADA: nem ao confirmar, nem durante os ~300
  // MB de download. O único sinal era a notificação do sistema — fora do app.
  //
  // O carimbo é aqui e não nos dois chamadores porque é aqui que `coll` e `s`
  // existem juntos: um chamador novo herda o comportamento sem saber dele.
  r.__linha = songRowKey(coll, s);
  // O AVISO DA JANELA DE ANTECEDÊNCIA (v5.256).
  //
  // A lista mostra o episódio três dias antes do sábado dele — o pedido do
  // operador, porque o roteiro do culto é montado durante a semana. O preço é
  // que nesses dias o vídeo pode ainda não estar público (o canal sobe o
  // trimestre e libera aos poucos), e aí o download simplesmente não vem.
  //
  // Sem esta frase, aquela falha é indistinguível de uma queda de rede: o
  // operador tenta de novo, falha de novo, e conclui que o app está quebrado
  // justamente no item que ele acabou de ver aparecer. Com ela, a resposta diz
  // o que fazer — esperar chegar mais perto — e diz até QUANDO.
  //
  // Ela só é anexada enquanto o sábado não chegou: passado o dia, uma falha ali
  // é uma falha de verdade e a frase seria uma desculpa falsa.
  const dias = s.serieData ? AVSerie.diasAte(s.serieData, coll.serie) : 0;
  if (dias > 0) {
    r.avisoSeFalhar = 'ainda não liberado pelo canal — tente mais perto de '
      + AVSerie.rotuloData(s.serieData);
    // ONDE a frase aparece, e são DOIS lugares porque são dois fluxos. Com
    // "Tocar agora" a Biblioteca FECHA (o `closeHymnSearch` no topo do
    // `ytAcao`) e quem responde é o cartão sobre a preview; mandando para o
    // Cronograma ela continua aberta por cima da preview, e a resposta tem de
    // nascer onde o toque nasceu — que ali é o card da própria série.
    r.avisoOnde = coll.id;
  }
  return r;
}
// (`ehSerie` mora com o resto do modelo de coleção, junto de `tipoDaColecao`.)

// (`openSongMenu` — a FOLHA de um item do acervo — saiu na v5.285: os dois
// botões que a abriam deixaram de existir, e a mesma lista passa a ser montada
// no corpo da linha por `montarOpcoes`. A folha `#songMenuPopup` continua de
// pé, com os dois donos que sobraram: os resultados do YouTube (`openYtMenu`) e
// o seletor de destinos da importação (`escolherDestinos`) — por isso
// `closeSongMenu` fica.)

function closeSongMenu() {
  // A folha é reusada como SELETOR DE DESTINOS da importação (ver
  // `escolherDestinos`), e ali fechá-la é uma resposta — a promessa fica
  // pendente para sempre se ninguém a resolver. Fechar por ✕, pelo fundo ou
  // pelo botão voltar do aparelho entra todo aqui, então é aqui que a
  // desistência é dita.
  if (destPromptResolve) { fecharDestPrompt(null); return; }
  destLimpar();
  songMenuFor = null;
  songMenuPopupEl.classList.remove('open');
}

// A caixa de marcação de uma linha de destino. `stopPropagation` porque ela vive
// DENTRO do botão da linha: sem isso, marcar dispararia a ação da linha e a
// folha fecharia — o oposto exato do que a caixa existe para permitir.
function destCheck(chave) {
  const cx = document.createElement('span');
  cx.className = 'song-menu-check' + (destMarcados.has(chave) ? ' on' : '');
  cx.setAttribute('role', 'checkbox');
  cx.setAttribute('aria-checked', destMarcados.has(chave) ? 'true' : 'false');
  cx.title = destMarcados.has(chave) ? 'Marcado — tocar para desmarcar' : 'Tocar para marcar';
  // ELA NÃO TEM MAIS OUVINTE PRÓPRIO (v5.252). Quem alterna é a LINHA, e a caixa
  // é o indicador dentro dela: um `stopPropagation` aqui faria o toque que cai
  // exatamente nos 20px da caixa não fazer nada, que é o pior lugar possível
  // para um ponto morto — é o pedaço da linha que mais parece o alvo.
  // `pointer-events: none` no CSS fecha isso pelo lado do navegador; este
  // comentário fecha pelo lado de quem for reintroduzir o ouvinte.
  return cx;
}

// Uma linha da folha: ícone + rótulo + (às vezes) uma segunda linha explicando.
// `destino` (opcional) é a chave da tabela `DESTINOS`: com ela a linha ganha a
// caixa de marcação e a ação recebe a UNIÃO do marcado com esta linha.
function songMenuItem(icone, rotulo, sub, acao, destino, aoMudar) {
  const li = document.createElement('li');
  const btn = document.createElement('button'); btn.className = 'song-menu-btn';
  if (typeof icone === 'string') {
    const cx = document.createElement('span'); cx.className = 'song-menu-icon';
    cx.innerHTML = icone; btn.appendChild(cx);
  } else {
    icone.classList.add('song-menu-icon'); btn.appendChild(icone);
  }
  const txt = document.createElement('span'); txt.className = 'song-menu-text';
  const t = document.createElement('span'); t.className = 'song-menu-label'; t.textContent = rotulo;
  txt.appendChild(t);
  if (sub) {
    const d = document.createElement('span'); d.className = 'song-menu-sub'; d.textContent = sub;
    txt.appendChild(d);
  }
  btn.appendChild(txt);
  // ===== UMA LINHA DE DESTINO É SELECIONÁVEL, DE CORPO INTEIRO (v5.252) =====
  //
  // Pedido do operador: *"faça um método universal, o botão de confirmar sempre
  // visível, e todas as outras opções (inclusive o tocar agora) são opções
  // selecionáveis, não apenas tocando no check, mas de corpo inteiro."*
  //
  // A folha tinha DUAS gramáticas na mesma linha: o corpo EXECUTAVA (aquele
  // destino mais o que estivesse marcado, fechando tudo) e a caixinha de 20px na
  // borda apenas MARCAVA. Duas coisas diferentes a dois centímetros uma da
  // outra, e a de marcar era o menor alvo da folha — quem quisesse dois destinos
  // tinha de acertar a caixa do primeiro e o corpo do segundo, nessa ordem. E o
  // botão de confirmar só existia depois de a primeira marca ter sido feita, o
  // que o tornava invisível justamente para quem ainda não tinha entendido o
  // mecanismo.
  //
  // Agora a folha é o que ela sempre pareceu ser: uma lista de opções que se
  // marcam, e um botão que executa. A caixa fica como INDICADOR (é ela que diz
  // o estado), e o alvo passa a ser a linha toda.
  //
  // Vale para TODA linha que tenha `destino` — inclusive o "Tocar agora" do
  // YouTube, que ganhou caixa junto. Ele não é uma lista, e por dezenas de
  // versões isso bastou para lhe negar a marca; com um confirmar único, negá-la
  // seria manter a exceção que o pedido veio remover.
  if (destino) {
    btn.classList.add('song-menu-sel');
    btn.appendChild(destCheck(destino));
    const marcar = () => {
      if (destMarcados.has(destino)) destMarcados.delete(destino); else destMarcados.add(destino);
      const redesenhar = aoMudar || destRemontar;
      if (redesenhar) redesenhar();
    };
    btn.addEventListener('click', marcar);
    li.appendChild(btn);
    return li;
  }
  // A variante escolhida no seletor do topo é LIDA AQUI e passada para a ação:
  // `closeSongMenu()` zera `songMenuFor`, e uma ação que fosse consultá-lo
  // depois disso encontraria null.
  btn.addEventListener('click', () => {
    const variante = songMenuFor ? songMenuFor.variant : 'full';
    closeSongMenu();
    // O botão VAI com a ação mesmo assim: a folha fecha aqui (o download de uma
    // música ou de um vídeo leva de segundos a minutos, e uma folha aberta
    // durante isso é uma tela travada), então o `responder` cai na faixa de
    // aviso — mas se um dia alguma dessas ações deixar de fechar a folha, o
    // pulso passa a valer sem precisar lembrar de ligá-lo.
    acao(variante, btn, null);
  });
  li.appendChild(btn);
  return li;
}

// A linha de confirmação, no fim da folha e só com algo marcado. Ela existe
// para o caso em que já não há linha a tocar: marcados Playlist e Favoritos,
// tocar numa terceira linha acrescentaria um destino que ninguém pediu.
// O CONFIRMAR É SEMPRE VISÍVEL (v5.252). Ele só aparecia depois da primeira
// marca — isto é, era invisível justamente para quem ainda não sabia que dava
// para marcar, e a folha parecia não ter conclusão. Sem nada escolhido ele fica
// desabilitado e DIZ o que falta, que é o mesmo desenho que o seletor de
// destinos da importação (`renderDestPrompt`) já usava desde a v5.141: esta
// mudança é as duas folhas convergindo num modelo só.
function destConfirmRow(aoLado) {
  if (!destExecutor) return null;
  const alvos = destUniao(null);
  const li = document.createElement('li');
  li.className = 'song-menu-go-row';
  const btn = document.createElement('button');
  btn.type = 'button'; btn.className = 'song-menu-btn song-menu-go';
  const txt = document.createElement('span'); txt.className = 'song-menu-text';
  const t = document.createElement('span'); t.className = 'song-menu-label';
  // SEM LISTAR OS NOMES (v5.195): eles são as caixas marcadas, visíveis a três
  // linhas daqui. O contador responde "quantos?" sem repetir "quais?".
  //
  // "CONFIRMAR", e não mais "Enviar" (v5.252): com o "Tocar agora" selecionável
  // ao lado das listas, nem toda opção marcada é um destino — "Enviar aos 2
  // destinos" chamaria o telão de lista. O verbo neutro é o que cobre o
  // conjunto, e é como o próprio operador nomeou este botão.
  t.textContent = !alvos.length ? 'Escolha uma opção'
    : (alvos.length > 1 ? 'Confirmar (' + alvos.length + ')' : 'Confirmar');
  txt.appendChild(t);
  btn.appendChild(txt);
  btn.disabled = !alvos.length;
  btn.addEventListener('click', () => {
    if (!alvos.length) return;
    const variante = songMenuFor ? songMenuFor.variant : 'full';
    const exec = destExecutor;
    closeSongMenu();
    // A folha pode ter sido remontada por outra porta entre o desenho desta
    // linha e o toque nela; sem executor não há o que fazer, e uma exceção aqui
    // derrubaria o handler no meio de um culto.
    if (exec) exec(alvos, btn, variante);
  });
  li.appendChild(btn);
  // ===== O BOTÃO IRMÃO (v5.286) =====
  //
  // Pedido do operador: *"faça a letra escrita ficar escondida atrás de um
  // botão que fica lado a lado com o 'escolha uma opção'"*. No corpo da linha a
  // gaveta tem duas metades (opções + letra), e a letra é a mais alta das duas:
  // ela empurrava as opções para longe do dedo em toda abertura, quando o que
  // se abre a gaveta para fazer é DECIDIR. Atrás de um botão ela continua a um
  // toque, e o toque é de quem quer conferir.
  //
  // Ele vive aqui, e não numa faixa própria abaixo: "lado a lado" é o pedido, e
  // um segundo controle numa linha só sua seria mais uma faixa entre as opções
  // e a letra. Quem o fornece é o DONO da lista, porque a folha não tem letra
  // nenhuma a esconder — ali o campo não existe e nada muda.
  //
  // ===== ELE VEM POR ARGUMENTO, E ISSO NÃO É ESTILO (v5.302) =====
  //
  // `songMenuFor` é um slot GLOBAL e quem chama esta função é o `desenhar()` de
  // UMA linha — um fecho que sobrevive ao global por dois caminhos: a gaveta da
  // Biblioteca é montada UMA vez (`gavetaMontada`, em `hymnResultRow`), então
  // reabrir uma linha DE LÁ não reescreve `songMenuFor`; e `closeSongMenu()` o
  // ANULA com a gaveta ainda aberta. O segundo vale para todas — a gaveta de
  // `linhaDeItem` inclusive, que REMONTA ao reabrir (ver `abrir()` lá).
  //
  // Enquanto o irmão era um botão NOVO a cada chamada ("Ver a letra"), a
  // divergência era invisível. Desde que ele passou a ser um NÓ VIVO ligado a um
  // item (a faixa de ações de um Favorito), lê-lo do global produzia as duas
  // coisas que um destrutivo não pode ter: a faixa de uma linha MOVIDA para
  // dentro da gaveta de outra — com a lixeira de uma excluindo o item da outra —
  // e, depois de um Confirmar, a faixa simplesmente não reanexada, deixando uma
  // exclusão em curso com a lixeira na miniatura e nenhum botão que a responda.
  //
  // O fallback para o global é o caminho da BIBLIOTECA (`renderSongMenu` e
  // `openYtMenu`), que continua pondo o irmão em `songMenuFor` — ali ele é uma
  // fábrica, e não tem alvo a trocar.
  const dono = typeof aoLado === 'function'
    ? aoLado
    : (songMenuFor && typeof songMenuFor.aoLado === 'function' ? songMenuFor.aoLado : null);
  if (dono) {
    const irmao = dono();
    // ===== O CONFIRMAR É SEMPRE O ÚLTIMO, e isso deixou de ser negociável =====
    //
    // Relato do operador (v1.4.7): *"nos favoritos o botão de confirmar play
    // está na direita, mas no resto da biblioteca está na esquerda; pode
    // padronizar na direita?"*.
    //
    // O lado era DECISÃO DO IRMÃO (v5.307, `data-antes`), e um irmão que não a
    // tomava caía no `appendChild` — isto é, no lado oposto. Duas portas para o
    // mesmo botão primário, e a divergência era o padrão de quem esquecesse a
    // marca. **A escolha some junto com a inconsistência**: quem entra antes é
    // sempre o irmão, quem decide fica sempre na direita, e não há mais o que
    // um chamador novo possa esquecer.
    //
    // Continua sendo o DOM, e não `order`/`row-reverse`: a ordem visual e a de
    // foco precisam concordar numa faixa que hospeda um destrutivo (a lixeira da
    // `.fav-acoes`).
    if (irmao) li.insertBefore(irmao, btn);
  }
  return li;
}

// ===== A MESMA FOLHA, COMO PERGUNTA (importação e compartilhamento) =====
//
// Um arquivo importado ou compartilhado ia SEMPRE para o Cronograma, sem
// pergunta — a lista era escolhida no código (`destinoDoShare`). Para um louvor
// que se quer nos Favoritos, isso significava importar, achar o item na lista e
// marcá-lo à mão, um por um.
//
// Aqui a folha de destinos vira uma PERGUNTA: as mesmas três linhas marcáveis,
// o Cronograma já marcado (o destino de sempre, para quem só quer confirmar) e
// um botão que fecha. É a única porta em que a folha PRECISA de confirmação:
// nas outras cada linha é uma ação completa, e aqui não há ação nenhuma até o
// operador dizer para onde.
//
// **Desistir não perde o item.** Fechar por ✕, pelo fundo ou pelo voltar do
// aparelho resolve `null`, e quem chamou importa no destino padrão — a mesma
// regra do link compartilhado, que "nunca se perde".
let destPromptResolve = null;

function fecharDestPrompt(valor) {
  const r = destPromptResolve;
  destPromptResolve = null;
  destLimpar();
  songMenuFor = null;
  songMenuPopupEl.classList.remove('open');
  if (r) r(valor);
}

function escolherDestinos(titulo, padrao) {
  // No simplificado não existe Cronograma nem playlist: perguntar por listas que
  // a tela não tem seria pior que não perguntar (a mesma regra do link
  // compartilhado ali). Quem chama já sabe disso, mas a guarda fica: uma folha
  // aberta sobre a tela bloqueada não teria como ser respondida.
  if (simplificado()) return Promise.resolve(null);
  return new Promise((resolve) => {
    destPromptResolve = resolve;
    destLimpar();
    (padrao && padrao.length ? padrao : ['cronograma']).forEach((c) => destMarcados.add(c));
    songMenuFor = { destPrompt: true };
    songMenuTitleEl.textContent = titulo;
    renderDestPrompt();
    songMenuPopupEl.classList.add('open');
  });
}

const DEST_ICONE = { playlist: 'queue', cronograma: 'cronoAdd', favoritos: 'star' };

function renderDestPrompt() {
  songMenuListEl.innerHTML = '';
  const remontar = () => renderDestPrompt();
  destRemontar = remontar;
  // AS MESMAS LINHAS DAS OUTRAS FOLHAS (v5.252). Até aqui esta função montava
  // as suas próprias, e o comentário explicava por quê: lá o corpo da linha
  // EXECUTAVA e fechava a folha, e aqui não há ação por trás dele. Essa razão
  // deixou de existir — `songMenuItem` com `destino` agora MARCA, que sempre foi
  // o que esta folha fazia. As duas convergiram, e vinte linhas de marcação
  // duplicada saíram com a divergência.
  DESTINOS.forEach((d) => {
    songMenuListEl.appendChild(songMenuItem(
      msym(ICON[DEST_ICONE[d.chave]] || ICON.add), d.rotulo, '',
      () => {}, d.chave, remontar));
  });
  const li = document.createElement('li');
  li.className = 'song-menu-go-row';
  const go = document.createElement('button');
  go.type = 'button'; go.className = 'song-menu-btn song-menu-go';
  const txt = document.createElement('span'); txt.className = 'song-menu-text';
  const t = document.createElement('span'); t.className = 'song-menu-label';
  const escolhidos = destUniao(null);
  t.textContent = escolhidos.length ? 'Importar' : 'Escolha um destino';
  txt.appendChild(t);
  go.appendChild(txt);
  go.disabled = !escolhidos.length;
  go.addEventListener('click', () => fecharDestPrompt(escolhidos));
  li.appendChild(go);
  songMenuListEl.appendChild(li);
}

function renderSongMenu() {
  // A folha é compartilhada com os resultados do YouTube (`openYtMenu`), com o
  // seletor de destinos da importação (`escolherDestinos`), que não tem
  // `coll`/`s` — e o seletor de variante do topo chama isto de volta.
  // (`songMenuFor.folha` era a terceira: o "Adicionar pasta" dos Favoritos, que
  // saiu na v5.254 com o atalho de pasta. A guarda fica: ela é a que impede
  // qualquer abertura futura sem `coll` de desestruturar o que não existe.)
  if (!songMenuFor || songMenuFor.yt || songMenuFor.destPrompt || songMenuFor.folha
      || songMenuFor.item) return;
  const { coll, s } = songMenuFor;
  const temPlayback = !!s.has_instrumental_music;
  // ===== O ALVO PODE NÃO SER A FOLHA (v5.285) =====
  //
  // Pedido do operador: as opções do item da Biblioteca deixam de ser um popup e
  // passam a abrir NO CORPO da linha, onde hoje abre a letra. A folha continua
  // existindo para quem ainda a usa — os resultados do YouTube e o seletor de
  // destinos da importação —, então o que muda é só PARA ONDE isto escreve.
  // O alvo viaja em `songMenuFor` porque o `remontar` (o seletor Cantada/
  // Playback e cada marca de destino) refaz a lista, e ele precisa refazê-la no
  // mesmo lugar.
  const alvo = songMenuFor.alvo || songMenuListEl;
  alvo.innerHTML = '';
  // (O PARÂMETRO `modo` saiu na v5.286. Ele escolhia entre a metade de TOCAR e a
  // de ADICIONAR, porque cada botão da linha abria a sua — e a v5.285 já tinha
  // acrescentado um terceiro valor, `tudo`, para o corpo da linha. Sem os
  // botões, a pergunta deixou de ter metades: é uma lista só, e o parâmetro
  // virou uma constante disfarçada.)

  // ===== O SELETOR DECIDE O QUÊ; AS OPÇÕES, ONDE =====
  //
  // O seletor responde o QUÊ (cantada · playback · letra) e as quatro opções
  // respondem ONDE (o telão e as três listas). Sem essa divisão a variante
  // aparecia duas vezes — uma como segmento e outra como linha ("Tocar música
  // cantada" / "Tocar playback").
  //
  // "LETRA" É UMA VARIANTE, não um destino: é a mesma música sem áudio nenhum.
  // Com ela escolhida, "Tocar agora" projeta a letra (`projectSongLyricsOnly`)
  // e cada lista recebe a CENA de letra (`addLyricCue`) — o que torna a linha
  // "Só a letra, no Cronograma" redundante (era `Letra` + `Cronograma`).
  //
  // O SELETOR APARECE SEMPRE (toda música tem letra); só o segmento do meio
  // depende do acervo.
  const variantes = [['full', 'Cantada']];
  if (temPlayback) variantes.push(['playback', 'Playback']);
  variantes.push(['letra', 'Letra']);
  if (!variantes.some(([v]) => v === songMenuFor.variant)) songMenuFor.variant = 'full';
  alvo.appendChild(ytSegRow(variantes, songMenuFor.variant,
    (v) => { songMenuFor.variant = v; renderSongMenu(); }));

  const remontar = () => renderSongMenu();
  destRemontar = remontar;
  // O EXECUTOR ÚNICO. Ele separa o TELÃO das listas (a chave `tocar` não é um
  // destino de `DESTINOS`, é o "sem entrar em lista nenhuma") e a variante
  // `letra` do resto: uma cena de letra não é a música noutra lista, é outro
  // registro — sem áudio, e sem baixar nada.
  //
  // O TELÃO VEM PRIMEIRO quando marcado: ele é a única metade que o operador
  // está esperando ver acontecer, e as listas podem terminar depois.
  destExecutor = async (alvos, btn, vr) => {
    const marcados = alvos || [];
    const listas = marcados.filter((a) => a !== 'tocar');
    const tocar = marcados.includes('tocar');
    if (vr === 'letra') {
      if (tocar) projectSongLyricsOnly(coll, s);
      if (listas.length) await addLyricCue(coll, s, btn, listasDosDestinos(listas));
      return;
    }
    if (tocar) await playSongVariant(coll, s, vr);
    if (listas.length) await addSongToDestinos(coll, s, vr, listas, btn);
  };
  // "Tocar agora" é o único que NÃO guarda nada, e é isso que o rótulo não diz
  // — daí ele manter subtítulo enquanto os três destinos perderam o deles
  // (v5.195). É a mesma linha, com o mesmo texto, da folha do YouTube.
  alvo.appendChild(songMenuItem(msym(ICON.play), 'Tocar agora',
    'Sem entrar em lista nenhuma',
    (vr, btn, alvos) => destExecutor(alvos, btn, vr), 'tocar', remontar));
  alvo.appendChild(songMenuItem(msym(ICON.queue), 'Adicionar à playlist', '',
    (vr, btn, alvos) => destExecutor(alvos, btn, vr), 'playlist', remontar));
  alvo.appendChild(songMenuItem(msym(ICON.cronoAdd), 'Adicionar ao Cronograma', '',
    (vr, btn, alvos) => destExecutor(alvos, btn, vr), 'cronograma', remontar));
  alvo.appendChild(songMenuItem(msym(ICON.star), 'Favoritar', '',
    (vr, btn, alvos) => destExecutor(alvos, btn, vr), 'favoritos', remontar));
  const go = destConfirmRow();
  if (go) alvo.appendChild(go);
}

// Cena de roteiro da LETRA de uma música do acervo.
// A CENA DE LETRA pode ir para MAIS DE UMA LISTA (v5.286). Ela nasceu presa ao
// Cronograma porque era uma linha própria da folha ("Só a letra, no
// Cronograma"); com "Letra" virando uma VARIANTE, ela passa a valer para os
// mesmos três destinos das outras duas — é a mesma música, sem áudio.
//
// UM registro para todas: `criarCue` o cria na primeira lista e as demais
// recebem o mesmo id, como qualquer item multi-destino deste app. Criar um por
// lista daria três cenas idênticas que o operador teria de apagar uma a uma.
async function addLyricCue(coll, s, btn, listas) {
  const alvo = (listas && listas.length) ? listas : ['imports'];
  const rec = await criarCue('songlyrics',
    { collId: coll.id, songId: s.id_music },
    songLabel(coll, s), alvo[0], btn);
  if (!rec) { responder(btn, 'erro', 'Não foi possível adicionar'); return; }
  for (const l of alvo.slice(1)) await AVDB.listAdd(l, rec.id);
}

// A seta de download dentro do `.dl-ring` — o mesmo desenho que o `#pvBusy`
// traz no HTML. (Aqui precisa ser JS: a linha é construída em tempo de
// execução.) Fora do subset da fonte, como a de `downloadAllIconSvg`.
function downloadArrowIconSvg() {
  return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    + '<path d="M12 4v9"/><polyline points="8 9.5 12 13.5 16 9.5"/>'
    + '<path d="M5 16v2a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-2"/>'
    + '</svg>';
}

// ===== "Baixando" na LINHA da música =====
// Contador por música, não booleano: dois pedidos para a mesma faixa (adicionar
// à playlist e, em seguida, ao Cronograma) não podem fazer o primeiro a
// terminar apagar a marca do outro.
const songRowBusy = new Map();
function songRowKey(coll, s) { return coll.id + ':' + s.id_music; }

// O estado vive no Map, e não só na classe do botão, porque a lista do acervo é
// RECONSTRUÍDA durante o download (o progresso da sincronização redesenha a
// cada 400 ms): uma classe escrita no nó some no redesenho seguinte, e a linha
// voltava a mostrar ▶ com o download ainda correndo. `hymnResultRow` relê o
// Map ao montar; esta função cuida das linhas que já estão na tela.
function setSongRowBusy(coll, s, on) {
  setSongRowBusyKey(songRowKey(coll, s), on);
}
// A MESMA marca, pela CHAVE. Quem vem do YouTube (um episódio de série) tem a
// chave e não tem o par `coll`/`s` na mão — e duplicar o contador daria dois
// donos para a mesma classe no DOM, que é a forma de eles discordarem.
function setSongRowBusyKey(key, on) {
  const n = (songRowBusy.get(key) || 0) + (on ? 1 : -1);
  if (n > 0) songRowBusy.set(key, n); else songRowBusy.delete(key);
  const ligado = songRowBusy.has(key);
  // Comparação por `dataset`, sem seletor de atributo: a chave carrega `:` e
  // `-`, e montar um seletor a partir de dado é o tipo de coisa que quebra
  // calada no dia em que um id novo trouxer outro caractere.
  document.querySelectorAll('.hymn-result').forEach((li) => {
    if (li.dataset.song !== key) return;
    const btn = li.querySelector('.hymn-play-thumb');
    if (btn) btn.classList.toggle('busy', ligado);
  });
}

// (O desenho de "só a letra" — `lyricsOnlyIconSvg` — saiu com o chamador: a
// v5.286 transformou "Só a letra, no Cronograma" no terceiro SEGMENTO do
// seletor de variante, e o segmento é rótulo escrito, não ícone.)

// Verifica quais variantes de uma música ainda precisam ser baixadas: o
// arquivo não existe no catálogo (nunca baixado ou apagado por fora) OU existe
// mas ainda não tem a letra sincronizada (`lyrics === undefined` → backfill sem
// rebaixar o áudio). Regra única usada pela sincronização em massa e pelo
// download sob demanda.
async function songVariantsNeeded(coll, s) {
  // As duas leituras em paralelo: são independentes, e em série cada música
  // pagava duas idas ao IDB uma atrás da outra — multiplicado pela varredura
  // de um hinário inteiro (ver o laço de `syncCollection`).
  const [fullRec, playbackRec] = await Promise.all([
    s.fileIdFull ? AVDB.fileGet(s.fileIdFull) : null,
    s.fileIdPlayback ? AVDB.fileGet(s.fileIdPlayback) : null,
  ]);
  // `semAudio`/`semPlayback`: a origem NÃO TEM essa variante (v5.134). Sem essa
  // ressalva a música ficava pendente para sempre — cada sincronização buscava
  // o `music_{id}` dela de novo, só para redescobrir que não há URL, e o álbum
  // nunca chegava a "Já completo offline". A marca é apagada assim que uma URL
  // aparece (ver `ensureSongVariant`), então uma faixa que a origem publicar
  // depois volta sozinha para a fila.
  return {
    needsFull: !s.semAudio && (!fullRec || fullRec.lyrics === undefined),
    needsPlayback: !!(s.has_instrumental_music && !s.semPlayback
      && (!playbackRec || playbackRec.lyrics === undefined)),
  };
}

// Baixa uma música sob demanda ("conforme o uso") — diferente da sincronização
// em massa (gated por Wi-Fi), um download disparado por tocar/adicionar é
// sempre permitido, mesmo em dados móveis: é exatamente a música que o operador
// pediu pra usar, nunca o acervo inteiro de uma vez. Reaproveita
// downloadCollectionSong — a música sai já com áudio, capa e letra, pronta pra
// tocar 100% offline nas próximas vezes.
// O PARÂMETRO `opts.toast` SAIU na v5.207, e com ele o último motivo de existir
// desta assinatura. Ele calava um `avisar('Baixando "X"…')` numa faixa
// flutuante, e existia porque o caminho de TOCAR já anunciava o mesmo download
// no cartão da preview — dois canais para um fato, com um `if` para escolher.
//
// Sem a faixa não há o que calar: quem diz que ESTA música está baixando é a
// linha dela (`setSongRowBusy`, logo abaixo), que fica à vista porque o acervo
// continua aberto, e o cartão da preview quando o caminho é o de tocar. Os dois
// são in-place e coexistem sem se atropelar.
async function ensureSongDownloaded(coll, s) {
  const { needsFull, needsPlayback } = await songVariantsNeeded(coll, s);
  if (!needsFull && !needsPlayback) return;

  // A LINHA da música mostra que ela está baixando. A marca é acesa AQUI, e não
  // no chamador, porque este é o único ponto que já sabe que existe download de
  // verdade: acendê-la antes da checagem acima faria a miniatura piscar em toda
  // música que já está no aparelho — e um indicador que pisca lê-se como falha.
  // Como consequência, todo caminho que baixa sob demanda ganha a marca sem
  // precisar lembrar dela.
  setSongRowBusy(coll, s, true);
  try {
    const key = coll.id + ':' + s.id_music;
    if (songDownloadInFlight.has(key)) { await songDownloadInFlight.get(key); return; }
    const p = withBgWork(async () => {
      await downloadCollectionSong(coll, s);
      await AVDB.setState('coll:' + coll.id, collState[coll.id]);
      refreshCollectionsIfVisible();
    });
    songDownloadInFlight.set(key, p);
    try { await p; } finally { songDownloadInFlight.delete(key); }
  } finally {
    setSongRowBusy(coll, s, false);
  }
}

async function resolveSongMediaId(coll, s, variant) {
  await ensureSongDownloaded(coll, s);
  const fileId = variant === 'full' ? s.fileIdFull : s.fileIdPlayback;
  if (!fileId) return null;
  const rec = await AVDB.fileGet(fileId);
  return rec ? fileId : null;
}

// Toca a versão CANTADA direto (modo simplificado). Se a música ainda não
// estiver no aparelho, pergunta ANTES de gastar internet — uma vez só: quem
// respondeu "baixar" já disse como quer que o app se comporte, e repetir a
// pergunta a cada música viraria ruído no meio do culto.
async function simplePlaySong(coll, s) {
  // NO MODO FÁCIL A SÉRIE TAMBÉM TRANSMITE (v5.230), e aqui isso vale ainda
  // mais: este modo existe para não perguntar nada, e a alternativa seria o
  // operador esperar ~300 MB de download com o culto rodando. `ytAcao` com
  // "tocar" e nenhum destino de guarda é exatamente o caminho da transmissão
  // direta — e, falhando ela, o download de sempre, calado.
  if (ehLink(coll)) { await ytAcao(serieComoYoutube(coll, s), ['tocar'], null, false, 0); return; }
  const { needsFull } = await songVariantsNeeded(coll, s);
  if (needsFull && !(await ensureDownloadConsent())) return;
  playSongVariant(coll, s, 'full');
}

// Persistido em `state.downloadOk`: a resposta vale para as próximas sessões
// também — "só aparece na primeira vez" seria falso se voltasse toda semana.
let downloadConsent = false;
async function ensureDownloadConsent() {
  if (downloadConsent) return true;
  const ok = await appConfirm({
    title: 'Baixar a música?',
    message: 'Esta música ainda não está no aparelho. Baixar agora usa a internet '
      + '(Wi-Fi ou dados móveis).\n\nEsta pergunta aparece só desta vez.',
    okText: 'Baixar',
    cancelText: 'Agora não',
  });
  if (!ok) return false;
  downloadConsent = true;
  await AVDB.setState('downloadOk', true);
  return true;
}

// ===== "Baixando…" na preview =====
// Tocar uma música que ainda não está no aparelho abre um download de dezenas
// de segundos. Até a v5.63 o toque não mudava NADA na tela: o acervo continuava
// aberto na mesma lista e o único sinal era um toast na tela principal, atrás
// do popup. Do lado de quem opera, "toquei e não aconteceu nada" — e o reflexo
// é tocar de novo.
//
// A correção tem duas metades, e a primeira é a que resolve o problema: a
// resposta ao toque é IMEDIATA e igual à de uma música já baixada — o acervo
// fecha na hora. A segunda diz o que está acontecendo, e diz **na miniatura da
// preview**: é ali que a mídia vai aparecer, então é ali que se anuncia que ela
// está a caminho. Um aviso na tela principal seria mais um cartaz avulso a
// interpretar; na preview a espera vira estado do próprio destino.
const PV_BUSY_DELAY_MS = 180;
// Quanto o cartão SEGURA um motivo de falha antes de sair (ver `falhar`).
// Generoso de propósito: "Baixando…" o operador vê de relance, mas "sem
// internet para baixar" ele precisa LER — e é a única resposta que ele vai ter.
const PV_FALHA_MS = 5000;
// ===== A SAÍDA TAMBÉM ESPERA UM RESPIRO — pela PASSAGEM DE BASTÃO (v1.4.8) =====
//
// O `PV_BUSY_DELAY_MS` acima existe para o cartão não PISCAR ao entrar. Este é o
// mesmo problema na outra ponta, e ele nasceu quando o aro do palco saiu e as
// DUAS metades da mesma espera viraram o MESMO cartão.
//
// Uma espera de transmissão tem dois donos em sequência: o toque (`cederOPalco`,
// que cobre a extração de rede) e a carga do stream (o `onEspera` do palco). O
// primeiro solta no `finally`, assim que `tentarTransmitir` volta; o segundo só
// acende lá dentro do `load`, depois do fade de saída e do `getMedia`. Entre os
// dois o contador passa por ZERO — e sem esta carência o cartão sai e volta no
// meio da mesma espera, que é exatamente o "dois modelos de carregamento" que
// este lote existe para acabar, com outra roupa.
//
// **A carência cobre o pior caso do vão**, que é o `FADE.time` (0,6 s) mais a
// leitura do IndexedDB. **O preço está dito:** um cartão que de fato acabou fica
// esse tanto a mais na tela — e ele é um indicador de estado, não um modal.
const PV_BUSY_SAIDA_MS = 700;
let pvBusyCount = 0;
let pvBusyTimer = null;
// A saída adiada em voo (`null` = nenhuma). Um dono novo a CANCELA: é isso que
// transforma "sai e volta" em "continua".
let pvBusySaidaTimer = null;
// As liberações que `falhar()` adiou pelo prazo de leitura e que ainda não
// venceram. Um trabalho NOVO as consome ao nascer: ver o topo de `previewBusy`.
const pvFalhasPendentes = [];

// Devolve `{ visivel, soltar }`. `visivel` é falso no simplificado, onde a
// preview não está na tela — ali quem avisa continua sendo o toast, e é por
// isso que o chamador precisa saber.
// ===== "Baixando" NA LINHA DO CRONOGRAMA =====
//
// O cartão sobre a preview diz "isto vai entrar em cena". É a mensagem certa
// quando o toque foi TOCAR — e a errada quando ele foi só ADICIONAR: um vídeo
// compartilhado que apenas entra na lista não vai ao telão a seguir, e anunciar
// o download ali insinua o contrário. A regra passa a ser (v5.84): **o aviso
// mora onde o resultado vai aparecer.**
//
// Aqui o resultado é uma linha do Cronograma — só que ela ainda NÃO EXISTE
// enquanto o arquivo baixa. Por isso a linha é criada provisória: o operador vê
// o item entrar na lista na hora, com o anel e o percentual, e ele vira o item
// de verdade quando os bytes chegam. É a mesma ideia do `setSongRowBusy` no
// acervo, com um passo a mais porque lá a linha já existia.
//
// A chave é o ID DA MÍDIA quando ela já existe (o botão de converter um item de
// player), e uma chave provisória quando não existe (um link recém-chegado).
const libBaixando = new Map();

function libBusy(nome, chaveExistente, aoCancelar) {
  const chave = chaveExistente || ('dl:' + Math.random().toString(36).slice(2, 9));
  libBaixando.set(chave, { nome: nome || 'Baixando…', pct: -1, cancelar: aoCancelar || null });
  load();
  let solto = false;
  return {
    visivel: true,
    atualizar(_acao, _nome, pct) {
      const r = libBaixando.get(chave);
      if (!r || solto) return;
      r.pct = typeof pct === 'number' ? pct : r.pct;
      // Repinta SÓ o texto, sem refazer a lista: o percentual chega a cada
      // megabyte, e um `load()` por atualização reconstruiria dezenas de linhas
      // (com object URLs de miniatura) enquanto o operador rola a lista.
      document.querySelectorAll('.lib-item').forEach((li) => {
        if (li.dataset.dl !== chave) return;
        const t = li.querySelector('.dl-pct');
        if (t) t.textContent = r.pct >= 0 ? r.pct + '%' : '';
      });
    },
    soltar() {
      if (solto) return;
      solto = true;
      libBaixando.delete(chave);
      load();
    },
  };
}

// A linha provisória: mesma anatomia de uma linha de mídia (miniatura + nome),
// com o anel no lugar da miniatura — que é justamente o que ela ainda não tem.
function libBusyRow(chave, reg) {
  const li = document.createElement('li');
  li.className = 'lib-item baixando';
  li.dataset.dl = chave;
  const row = document.createElement('div'); row.className = 'row';
  const t = document.createElement('div'); t.className = 'thumb thumb--icon';
  const anel = document.createElement('span'); anel.className = 'dl-ring';
  anel.innerHTML = downloadArrowIconSvg();
  t.appendChild(anel);
  const nome = document.createElement('span'); nome.className = 'row-name';
  nome.textContent = reg.nome;
  const pct = document.createElement('span'); pct.className = 'dl-pct';
  pct.textContent = reg.pct >= 0 ? reg.pct + '%' : '';
  row.append(t, nome, pct);
  // O CANCELAR MORA NA PRÓPRIA LINHA (v5.191). É o pedido do operador em
  // palavras dele — "a opção de cancelar no mesmo elemento visual do item na
  // listagem onde está baixando" —, e ele resolve o caso que o toque na linha
  // da busca não cobria: um download que foi para o Cronograma e cuja busca já
  // está fechada não tinha mais nenhuma superfície onde ser parado.
  if (reg.cancelar) {
    const x = document.createElement('button');
    x.type = 'button';
    x.className = 'dl-cancel';
    x.title = 'Cancelar o download';
    x.setAttribute('aria-label', 'Cancelar o download');
    x.innerHTML = '<span class="msym" aria-hidden="true">' + ICON.close + '</span>';
    // A linha inteira tem gestos próprios (abrir, arrastar para reordenar):
    // sem isto, cancelar dispararia também o de baixo.
    x.addEventListener('click', (ev) => { ev.stopPropagation(); reg.cancelar(); });
    row.appendChild(x);
  }
  li.appendChild(row);
  return li;
}

// Quem o botão de cancelar do cartão da preview aciona AGORA. Uma variável só,
// e não uma pilha: com dois downloads ao mesmo tempo o cartão já mostrava o
// último a escrever (a legenda é uma só), e o botão segue a mesma regra — o que
// se lê na tela e o que o toque faz são sempre o mesmo download.
let pvBusyCancelar = null;
function pintarPvBusyCancelar() {
  if (!pvBusyCancelEl) return;
  pvBusyCancelEl.hidden = !pvBusyCancelar;
}

// ===== O ÍCONE DO CARTÃO SEGUE A LEGENDA (v1.4.19) =====
//
// Pedido do operador, sobre o cartão de um link do YouTube: *"seu ícone segue
// sendo um ícone de download, enquanto que deveria ser só o spinner, sem um
// ícone de download nesse tipo de preparação, já que não está realmente baixando
// algo, para diferenciar do download em si"*.
//
// O `.dl-ring` são DOIS desenhos: o aro que gira e a SETA parada. O aro diz
// "espere"; a seta diz "bytes chegando" — e só uma delas era verdade numa
// PREPARAÇÃO. Preparar é a extração de um link, a montagem de uma playlist, a
// rasterização de um PDF **e a própria fase pré-bytes de um download**, que
// nasce em "Preparando vídeo" e só vira "Baixando vídeo · 12%" no primeiro
// progresso (ver `ytBaixarNativo`). Nos três primeiros a seta prometia o que não
// estava acontecendo; no quarto ela chegava cedo demais.
//
// **A REGRA É "O ÍCONE SEGUE A LEGENDA"**, e não uma bandeira a mais na
// assinatura. A legenda já carrega essa distinção na tela, em português, e é
// escrita em DOIS pontos (a criação do cartão e o `atualizar` do progresso) —
// derivá-la ali faz o desenho e a palavra nunca discordarem, que é o defeito
// que este pedido nomeia. O teste é pelo começo da palavra porque as legendas de
// download são quatro e todas dele: "Baixando", "Baixando a letra", "Baixando
// vídeo · N%", "Baixando áudio · N%".
//
// **E ele falha para o lado certo:** uma legenda nova escrita de outro jeito
// perde a seta e vira um spinner puro — nunca o contrário. Um cartão que
// promete download sem download é a queixa; um que não promete é apenas menos
// específico.
const CARTAO_BAIXANDO = /^\s*baixando/i;
function pintarSetaDoCartao(acao) {
  pvBusyEl.classList.toggle('sem-seta', !CARTAO_BAIXANDO.test(String(acao || '')));
}

function previewBusy(acao, nome, aoCancelar) {
  // No simplificado a preview só está na tela com um telão conectado (ver
  // hostPreview/`.simple.sem-tela`); bloqueado, quem avisa continua sendo o
  // toast — é por isso que o chamador precisa saber.
  // `falhar` entra no stub junto com os outros: um chamador que só quer relatar
  // uma falha não pode explodir porque o cartão não existe neste modo.
  if (appMode === 'simple' && !simpleDisplay()) {
    return { visivel: false, atualizar: () => {}, soltar: () => {}, falhar: () => {}, avisar: () => {} };
  }
  // O CARTÃO DE FALHA FICA NO AR (ver `falhar`), então um trabalho NOVO pode
  // nascer sobre ele — e ao nascer ele TOMA A LEGENDA, o que encerra o prazo de
  // leitura do anterior: a mensagem que aquele prazo protegia acabou de ser
  // sobrescrita, e o `pvBusyCount` que ele ainda segurava só prenderia o cartão
  // DESTE trabalho depois que ele terminasse. É a regra que o botão de cancelar
  // já segue no `liberar` ("sai com o DONO dele"), aplicada à legenda.
  // ANTES do `pvBusyCount++`, para o contador do falho sair sem cruzar com o novo.
  pvFalhasPendentes.splice(0).forEach((f) => f());
  // A PASSAGEM DE BASTÃO: um dono novo dentro da carência cancela a saída, e o
  // cartão nunca chega a piscar. Antes do `pvBusyCount++`, para a carência de um
  // ciclo anterior não sobreviver a este.
  clearTimeout(pvBusySaidaTimer); pvBusySaidaTimer = null;
  pvBusyCount++;
  // Sem tirar as marcas, `.falhou`/`.avisou` esconderiam o aro que gira e
  // pintariam "Baixando…" em vermelho ou âmbar — o cartão dizendo duas coisas
  // opostas.
  pvBusyEl.classList.remove('falhou', 'avisou');
  pvBusyCapEl.textContent = acao;
  pintarSetaDoCartao(acao);
  pvBusyLabelEl.textContent = nome;
  // O botão segue o ÚLTIMO a escrever, exatamente como a legenda — inclusive
  // quando o novo dono NÃO sabe cancelar (um hino baixando por cima de um vídeo
  // do YouTube): o cartão diria uma coisa e o botão faria outra, e o operador
  // pararia o download errado.
  const meuCancelar = aoCancelar || null;
  pvBusyCancelar = meuCancelar;
  pintarPvBusyCancelar();
  // Só acende depois de um respiro: uma música JÁ baixada resolve em poucos
  // milissegundos, e um cartão que pisca é pior que nenhum — lê-se como falha.
  if (!pvBusyTimer && !pvBusyEl.classList.contains('on')) {
    pvBusyTimer = setTimeout(() => {
      pvBusyTimer = null;
      if (pvBusyCount > 0) pvBusyEl.classList.add('on');
    }, PV_BUSY_DELAY_MS);
  }
  let solto = false;
  // A LIBERAÇÃO de verdade, separada da trava `solto`. `soltar()` faz as duas
  // coisas; `falhar()` TRAVA SEM LIBERAR e só chega aqui no fim do prazo de
  // leitura — é essa separação que faz o `finally` do chamador virar no-op em
  // vez de apagar a mensagem no mesmo quadro em que ela nasce.
  const liberar = () => {
    // O botão sai com O DONO dele: se outro download assumiu o cartão nesse
    // meio-tempo, quem manda é o novo — a mesma regra da legenda.
    if (meuCancelar && pvBusyCancelar === meuCancelar) {
      pvBusyCancelar = null;
      pintarPvBusyCancelar();
    }
    pvBusyCount = Math.max(0, pvBusyCount - 1);
    if (pvBusyCount) return;
    clearTimeout(pvBusyTimer); pvBusyTimer = null;
    // A RETIRADA É ADIADA (ver `PV_BUSY_SAIDA_MS`): quem assumir dentro da
    // carência a cancela, e a espera se lê como um estado só. O que sai AGORA é
    // só o botão de cancelar — ele é uma AÇÃO, e uma ação sem dono não pode
    // ficar tocável nem por meio segundo.
    pvBusyCancelar = null;
    pintarPvBusyCancelar();
    clearTimeout(pvBusySaidaTimer);
    pvBusySaidaTimer = setTimeout(() => {
      pvBusySaidaTimer = null;
      // Redundância DECLARADA, não guarda órfã: hoje todo caminho que cria um
      // dono cancela este relógio, então ele não deveria achar contador nenhum
      // de pé. Ela fica porque o custo de errar aqui é o cartão sumir DEBAIXO de
      // um trabalho vivo, e o de acertar é uma comparação.
      if (pvBusyCount > 0) return;
      pvBusyEl.classList.remove('on', 'falhou', 'avisou');
    }, PV_BUSY_SAIDA_MS);
  };
  // OS DOIS DESFECHOS QUE FALAM (`falhar` e `avisar`) — a mecânica é UMA.
  //
  // Eles TRAVAM SEM LIBERAR, e é aí que a promessa se cumpre: quase todo
  // chamador solta num `finally` que roda no MESMO tick (`playSongVariant`,
  // `projectSongLyricsOnly`). Marcar `solto` faz esse `soltar()` virar no-op —
  // sem isto o `pvBusyCount` caía a zero na hora, as classes saíam, e o
  // operador via o aro girar e sumir sem uma palavra: indistinguível do toque
  // não ter funcionado. Quem devolve o contador é o prazo, e só ele.
  const encerrarCom = (classe, cap, texto) => {
    if (solto) return;
    solto = true;
    pvBusyEl.classList.add('on', classe);
    pvBusyCapEl.textContent = cap;
    pvBusyLabelEl.textContent = texto;
    if (meuCancelar && pvBusyCancelar === meuCancelar) {
      pvBusyCancelar = null;
      pintarPvBusyCancelar();
    }
    // UMA vez, venha o fim pelo prazo ou por outro trabalho tomar a legenda
    // (ver o topo de `previewBusy`): as duas portas chamam o MESMO `fim`, e a
    // trava `feito` é o que impede o contador de cair duas vezes — o que
    // apagaria o cartão de um trabalho que ainda está correndo.
    let feito = false;
    const fim = () => { if (feito) return; feito = true; liberar(); };
    pvFalhasPendentes.push(fim);
    setTimeout(fim, PV_FALHA_MS);
  };
  return {
    visivel: true,
    // Reescreve a legenda sem abrir um cartão novo — é por aqui que o
    // percentual de um download longo aparece. Com dois downloads ao mesmo
    // tempo o último a escrever ganha, exatamente como já acontecia quando os
    // dois chamavam `previewBusy`.
    // O 3º parâmetro (percentual) existe só para a assinatura bater com a de
    // `libBusy`: aqui quem mostra o número é o próprio texto da legenda.
    atualizar(acaoNova, nomeNovo) {
      if (solto) return;
      pvBusyCapEl.textContent = acaoNova;
      // A SETA ACENDE AQUI, e é este ponto que a torna honesta: é o primeiro
      // progresso de um download que troca "Preparando vídeo" por "Baixando
      // vídeo · N%". Antes dele não havia byte nenhum.
      pintarSetaDoCartao(acaoNova);
      if (nomeNovo != null) pvBusyLabelEl.textContent = nomeNovo;
    },
    // Contado, e não um booleano: o operador pode disparar dois downloads
    // (tocar um hino e, enquanto ele baixa, projetar a letra de outro) — o
    // primeiro a terminar não pode apagar o indicador do outro.
    soltar() {
      if (solto) return;
      solto = true;
      liberar();
    },
    // O MESMO CARTÃO DIZ QUE NÃO DEU (v5.207).
    //
    // Ele já é o lugar em que este trabalho se anuncia, e é sobre a PREVIEW —
    // isto é, exatamente onde a mídia apareceria se tivesse dado certo. O
    // motivo ("sem internet para baixar") saía antes por uma faixa flutuante no
    // topo da tela, longe do cartão que estava dizendo "Baixando…" um segundo
    // antes: duas camadas para as duas metades da mesma frase.
    //
    // Ele SEGURA o cartão pelo tempo da leitura e só então solta — a mecânica
    // está no `encerrarCom`, partilhada com o `avisar`.
    falhar(motivo) { encerrarCom('falhou', 'Não deu', motivo); },
    // O MESMO CARTÃO DIZ QUE DEU, MAS COM RESSALVA (v1.4.11).
    //
    // Terceiro desfecho, e ele não é uma falha: a mídia ENTROU EM CENA e há uma
    // coisa sobre ela que quem opera precisa saber — hoje, que a única
    // resolução disponível era muito baixa. Chamar isso de "Não deu" seria
    // falso nas duas pontas (manda investigar o que funcionou, e some com a
    // informação que interessa).
    //
    // Mesma mecânica do `falhar`: segura o cartão pelo prazo de leitura, um
    // trabalho novo toma a legenda antes. Muda a COR e a palavra — âmbar, não
    // vermelho, porque vermelho neste app é ação destrutiva ou o que está no ar,
    // e este aviso não é nenhum dos dois.
    avisar(cap, texto) { encerrarCom('avisou', cap, texto); },
  };
}

async function playSongVariant(coll, s, variant) {
  // A RESPOSTA VEM PRIMEIRO. Fechar o acervo aqui, e não depois do download, é
  // o que faz o toque parecer ter funcionado — que é exatamente o que ele fez.
  closeSongMenu();
  closeHymnSearch();
  const bg = previewBusy('Baixando', songLabel(coll, s));
  try {
    const id = await resolveSongMediaId(coll, s, variant);
    // As duas falhas falam pelo MESMO cartão que estava dizendo "Baixando…", e
    // é ele que fica na tela — sobre a preview, que é onde a música apareceria.
    if (!id) { bg.falhar('sem internet para baixar'); return; }
    const rec = await AVDB.getMedia(id);
    if (!rec) { bg.falhar('não foi possível abrir a mídia'); return; }
    await replacePlaylistWith(rec);
    await send(id);
  } finally {
    bg.soltar();
  }
}

// Quem anuncia o download aqui é a miniatura da linha da música
// (`setSongRowBusy`), que fica à vista porque o acervo continua aberto de
// propósito. O RESULTADO é outra informação, e ele responde no botão que foi
// tocado (ver `adicionarNasListas`).
// UM download, VÁRIAS listas (v5.141). O caro aqui é `resolveSongMediaId` — ele
// baixa o áudio quando ele ainda não está no aparelho —, e o item resultante é
// o MESMO id em todas as listas. Fazer a conta uma vez e distribuir depois é a
// diferença entre esperar um download e esperar três para a mesma música.
async function addSongToDestinos(coll, s, variant, destinos, btn) {
  const alvos = (destinos && destinos.length) ? destinos : ['cronograma'];
  const id = await resolveSongMediaId(coll, s, variant);
  // A RECUSA RESPONDE NO BOTÃO QUE FOI TOCADO: ele é o alvo de foco, e o pulso
  // vermelho é o mesmo vocabulário que o sucesso já usa nesta mesma folha.
  if (!id) { pulsar(btn, 'erro'); return; }
  await adicionarNasListas(listasDosDestinos(alvos), id, songLabel(coll, s), btn);
  // Cada destino redesenha o que ele mudou, e só isso: os Favoritos aparecem na
  // estrela de cada linha do acervo, e o Cronograma só precisa ser remontado se
  // ele for a lista em cena.
  if (alvos.includes('favoritos')) renderLibrary();
  if (alvos.includes('cronograma')) load();
}

// (`addSongToFavorites` e `addSongToPlaylist` saíram na v5.141: eram três
// funções que diferiam APENAS na lista de destino, e o multi-destino as
// unificou em `addSongToDestinos`. Favoritar uma música do acervo continua
// BAIXANDO o arquivo, e isso é deliberado: um favorito é o que se usa toda
// semana, e o que o operador espera dele num domingo de manhã é que ele TOQUE —
// inclusive com a rede da igreja fora do ar. Um marcador que só guardasse a
// referência seria mais barato de criar e falharia justamente na hora em que ele
// é usado.)

// ============================================================================
// PLAYLIST AUTOMÁTICA — o sorteio temático da Biblioteca (v5.303)
// ============================================================================
//
// Pedido do operador: *"um sistema de play aleatório temático, tanto para
// música/mídia individual ou para montar playlists automáticas … você escolhe
// uma palavra tema (que vai fazer a busca na biblioteca sobre palavras-chave e
// filtrar a lista) e então aleatoriamente escolhe uma ou mais para tocar."*
//
// ## A divisão de trabalho
//
// A REGRA — quem pode ser sorteado e por quê — mora em `controle/sorteio.js`,
// pura e com oráculo em Node (`tools/sorteio.test.mjs`, no `apk.yml` **sem
// `continue-on-error`**). Este arquivo faz as três coisas que ela se recusa a
// fazer: pergunta ao acervo, baixa e projeta — e as três por funções que já
// existem. Nada aqui reimplementa busca, download ou projeção:
//
//   `normalizeForSearch` + `lyricMatch`  →  o tema casa (o MESMO da busca)
//   `resolveSongMediaId`                 →  variante → id, baixando se faltar
//   `playSongVariant`                    →  "uma só": ela já fecha, baixa e envia
//   `AVDB.listSet` + `send`              →  a fila, pelo caminho do `abrirPacote`
//
// ## As três decisões que precisam estar ditas
//
// **O QUE NÃO ENTRA, e por construção.** As séries (o grupo "Arquivos oficiais")
// saem por `temLetra(coll)` — a pergunta é pela CAPACIDADE, nunca por
// `kind === 'serie'`. As pastas do aparelho e os Favoritos nem chegam: eles não
// são coleções, são listas, e `allCollections()` não os conhece. O hinário
// ENTRA e sai por um filtro, porque foi assim que o operador pediu.
//
// **A FILA VAI PARA O PLAYER, e substitui o que havia.** Pedido do operador:
// *"vai direto para a playlist do player, para ser tocada"*. É o caminho do
// `abrirPacote` (`listSet('playlist', ids)` + `send` do primeiro), e é a mesma
// semântica de todo "Tocar agora" do acervo, que já passa por
// `replacePlaylistWith`. Não é o Cronograma: aquele é a ordem do culto, montada
// à mão, e um sorteio não a apaga.
//
// **A ESPERA DO ÍNDICE DE LETRAS É OBRIGATÓRIA AQUI.** Na busca, `ensureLyricIndex`
// é disparado e esquecido: o índice chega e a lista se redesenha. Aqui não há
// redesenho — o toque no botão manda a faixa para o telão. Sortear com o índice
// pela metade produziria um sorteio que IGNORA a palavra tema e mesmo assim
// projeta. Por isso `ensureLyricIndex()` passou a DEVOLVER a promessa, e por
// isso a folha se redesenha quando ela resolve (senão o contador anuncia menos
// faixas do que existem, e é ele que o operador lê antes de tocar).

const sorteioPopupEl = document.getElementById('sorteioPopup');
const sorteioBtnEl = document.getElementById('sorteioBtn');
const sorteioCloseEl = document.getElementById('sorteioClose');
const sorteioListEl = document.getElementById('sorteioList');

// A escolha do operador, guardada entre sessões. Os padrões são os do
// `AVSorteio.sanear` — declará-los aqui de novo seria a segunda lista a
// divergir da primeira.
let sorteioPrefs = AVSorteio.sanear(null);
// O último sorteio, para o Registro. Não é cache: é o VEREDITO, e ele sai da
// mesma passada que decidiu (regra do projeto — um bloco guarda o veredito,
// nunca uma segunda opinião).
let sorteioDiario = null;
// Sortear é assíncrono (índice de letras, downloads). Sem esta trava, dois
// toques no confirmar montam duas filas que brigam pelo `listSet`.
let sorteioRodando = false;
// O cancelar do cartão da preview. Ele para a fila ENTRE faixas — o download em
// curso termina, porque interrompê-lo no meio deixaria um parcial que o
// `YoutubeGrab` não retoma para faixa do acervo.
let sorteioCancelado = false;

// A ESCOLHA É LIDA NA PRIMEIRA ABERTURA DA FOLHA, e não no `load()`.
//
// `load()` roda a cada mexida em lista — reordenar um favorito, adicionar ao
// Cronograma, terminar um download — e cada `getState` dele é uma transação de
// IndexedDB em série. Uma leitura a mais ali é paga por toda a interface, para
// um dado que só uma folha usa e que é lido uma vez por sessão. (Custou uma
// medição: a reabertura da gaveta depois de uma casa de reordenação é um caso
// já apertado no `boot-nativo.test.mjs`, e ela mede o `load()` inteiro.)
let sorteioPrefsLidas = false;
function applySorteioPrefs(p) {
  // `sanear` já valida campo a campo e por tipo (é ele que impede um
  // `variante` gravado por engano de virar playback no `resolveSongMediaId`).
  sorteioPrefs = AVSorteio.sanear(p);
}
async function lerSorteioPrefs() {
  if (sorteioPrefsLidas) return;
  sorteioPrefsLidas = true;
  try { applySorteioPrefs(await AVDB.getState('sorteioPrefs')); } catch (_) { /* o padrão serve */ }
}
// A PALAVRA TEMA NÃO É GRAVADA (v5.307), e as outras cinco escolhas são. A
// diferença é o que cada uma significa: modo, variante, filtros e quantidade são
// AJUSTES — como o operador quer que este recurso se comporte —, e a palavra é
// uma PERGUNTA, feita uma vez. Reencontrar "natal" no campo em fevereiro é o
// recurso lembrando de algo que não é para ser lembrado; pior, é um filtro
// silencioso sobre o primeiro sorteio de quem só queria abrir e tocar.
function saveSorteioPrefs() {
  return AVDB.setState('sorteioPrefs', {
    modo: sorteioPrefs.modo, variante: sorteioPrefs.variante,
    semHinario: sorteioPrefs.semHinario, soNoAparelho: sorteioPrefs.soNoAparelho,
    semInfantis: sorteioPrefs.semInfantis,
    quantos: sorteioPrefs.quantos,
  });
}

// AS CAPACIDADES que a regra pede. Cada uma é um ponteiro para o que já existe
// — e é essa a razão de a injeção existir: `normalizeForSearch` é o
// normalizador ÚNICO da Biblioteca, e `lyricMatch` é o casamento por letra da
// busca. Uma segunda escrita de qualquer um dos dois faria o sorteio achar um
// conjunto e a busca achar outro para a MESMA palavra, na mesma tela.
//
// `noAparelho` usa o critério BARATO (`fileIdFull`/`fileIdPlayback`), o mesmo
// de `levantarColecao`: o autoritativo é `songVariantsNeeded`, que vai ao IDB, e
// perguntar por faixa varreria o acervo inteiro a cada tecla. O erro possível é
// o seguro — uma faixa marcada como presente que precise de retoque apenas
// passa pelo `resolveSongMediaId` de sempre.
function sorteioCap() {
  return {
    norm: normalizeForSearch,
    // O MESMO cache preguiçoso da busca (`renderSearchResults`): `s._norm` é
    // gravado na construção do índice, e normalizar aqui de novo custaria três
    // alocações por música sobre os dois hinários mais todos os álbuns.
    nomeNorm: (s) => s._norm || (s._norm = normalizeForSearch(s.name)),
    ehMusica: temLetra,
    ehHinario: collNumbersSongs,
    // O HINÁRIO NOVO, e só ele: a faixa 508–557 dos infantis é a numeração DELE
    // (ver `AVSorteio.INFANTIL_DE`). O de 1996 numera outra coisa, e emprestar
    // estes números para lá recusaria cinquenta hinos escolhidos ao acaso.
    ehHinarioNovo,
    faixas: (coll) => collSongs(coll.id),
    letraCasa: (coll, s, q) => !!lyricMatch(coll, s, q),
    noAparelho: (coll, s, variante) => !!(variante === AVSorteio.VARIANTE_PLAYBACK
      ? s.fileIdPlayback : s.fileIdFull),
  };
}

function sorteioPool() {
  return AVSorteio.montarPool(allCollections(), sorteioPrefs, sorteioCap());
}

// ---- A folha ----------------------------------------------------------------

async function abrirSorteio() {
  // ANTES de abrir, e não depois: a folha desenhada com os padrões e corrigida
  // um quadro depois faria a escolha da semana passada piscar por cima da nova.
  await lerSorteioPrefs();
  sorteioPopupEl.classList.add('open');
  renderSorteio();
  // O índice de letras é o que faz a palavra tema alcançar o que não está no
  // título. Pedido AQUI e não no primeiro caractere: a folha inteira depende
  // dele, e montá-lo enquanto o operador ainda escolhe o modo é o único
  // instante em que a espera não custa nada.
  ensureLyricIndex().then(() => {
    if (sorteioPopupEl.classList.contains('open')) renderSorteio();
  });
}
function fecharSorteio() {
  sorteioPopupEl.classList.remove('open');
  calarSorteio();
  // A CAIXA DA PALAVRA É LIMPA A CADA FECHAMENTO (v5.307, pedido do operador).
  // A folha é reaberta em outro momento do culto, para outra coisa — e o campo
  // preenchido a espera com um filtro que ela não pediu, que é o pior estado
  // possível para um recurso cujo botão dispara sem tela intermediária. Fechar
  // sem sortear é o gesto de quem desistiu daquela palavra.
  //
  // AQUI e não no `abrirSorteio`: os dois pontos limpariam o mesmo campo, e este
  // é o único que também vale para o ✕, o toque no fundo e o botão voltar do
  // aparelho — os três caminhos que a tabela `POPUPS` liga a esta função.
  sorteioPrefs.tema = '';
  saveSorteioPrefs();
}

// A CONTA, atualizada sem remontar a folha — é o único caminho que pode rodar
// com o campo de texto em foco, e remontar ali apagaria o foco no meio da
// palavra. Tudo o mais (chips, segmentos) remonta, porque tocar num botão já
// tira o foco do campo.
function atualizarContaSorteio() {
  const conta = sorteioListEl.querySelector('.sorteio-conta');
  if (!conta) return;
  const pool = sorteioPool();
  const n = pool.itens.length;
  conta.classList.toggle('vazio', n === 0);
  pintarContaSorteio(conta, pool);
  // OS DOIS botões, e não `.song-menu-go`: desde a v5.306 a faixa de fecho tem
  // "Tocar agora" e "Ao Cronograma", e um seletor que pegasse só o primeiro
  // deixaria o segundo habilitado sobre um pool vazio.
  sorteioListEl.querySelectorAll('.sorteio-acao').forEach((b) => { b.disabled = n === 0; });
}

// ===== A CONTA FALA DE MÚSICA, NÃO DE VARREDURA (v5.306) =====
//
// Pedido do operador: *"dê uma aprimorada na forma que descreve os resultados.
// algo como: x músicas relacionadas, x delas já estão baixadas… mais funcional
// e menos técnico"*.
//
// Ela saía como `12 faixas casam · 3 já no aparelho · sorteia 5` — três números
// no vocabulário de quem escreveu a regra ("casam", "faixas", "no aparelho"),
// empilhados numa linha só. O que o operador precisa saber antes de tocar o
// botão são DUAS coisas, e elas têm pesos diferentes:
//
//   1. **o tema achou o quê?** — decide se vale mudar a palavra;
//   2. **quanto disso toca agora?** — decide se o culto espera a rede.
//
// Daí DUAS LINHAS com hierarquia, e não uma frase com separadores: a primeira
// responde a primeira pergunta e é a que se lê de relance; a segunda é o custo,
// em `--muted`. Uma linha só obrigava as duas a disputarem o mesmo peso.
function pintarContaSorteio(conta, pool) {
  conta.innerHTML = '';
  // A FALA EMPRESTADA VENCE, e ela é lida AQUI e não escrita no nó: o
  // `executarSorteio` REDESENHA a folha no `finally`, e uma frase escrita
  // direto no span era apagada no mesmo quadro em que nascia — o "adicionadas
  // ao Cronograma" nunca chegou a ser visto. Guardá-la em estado e deixar o
  // desenho consultá-la faz qualquer redesenho preservá-la, que é a única forma
  // que sobrevive a um caminho de render que ainda não existe.
  const [forte, fraca] = sorteioFala ? [sorteioFala, ''] : frasesDaContaSorteio(pool);
  const a = document.createElement('span');
  a.className = 'sorteio-conta-forte';
  a.textContent = forte;
  conta.appendChild(a);
  if (fraca) {
    const b = document.createElement('span');
    b.className = 'sorteio-conta-fraca';
    b.textContent = fraca;
    conta.appendChild(b);
  }
}

// ===== SEM PALAVRA, O ACERVO INTEIRO ENTRA — E A FRASE O DIZ (v5.307) =====
//
// Pedido do operador: *"permita (e descreva/identifique) que ao não filtrar por
// nenhuma palavra, o sistema considere todo o acervo disponível para sortear (é
// claro, considerando os outros filtros e configurações)"*.
//
// A REGRA já permitia — `AVSorteio.ondeCasa` devolve `CASOU_SEM_TEMA` com a
// busca vazia, e o pool sai com o acervo inteiro. O que faltava era DIZÊ-LO: a
// frase era "28 músicas na biblioteca", que informa o tamanho e não o ESCOPO, e
// deixava a pergunta "então ele vai sortear de tudo?" sem resposta na tela.
//
// A frase LIDERA COM O ESCOPO em vez do número, porque com a caixa vazia é o
// escopo que está em dúvida. E ela é HONESTA sobre os dois filtros que
// encolhem o "tudo": dizer "toda a biblioteca" com o hinário fora seria uma
// frase errada — e uma frase errada é pior que nenhuma, porque produz a decisão
// errada. A VARIANTE (Cantada × Playback) fica de fora desta conta de
// propósito: ela não encolhe um acervo, ela escolhe QUAL faixa de cada música,
// e o segmento acima já a mostra.
function escopoSemPalavra(n) {
  const base = sorteioPrefs.soNoAparelho
    ? 'Só o que já está no aparelho'
    : 'Toda a biblioteca';
  const menos = (sorteioPrefs.semHinario ? ', sem o hinário' : '')
    + (sorteioPrefs.semInfantis ? ', sem os infantis' : '');
  return base + menos + ' — ' + numeroPt(n) + (n === 1 ? ' música' : ' músicas');
}

// Números do acervo passam de mil (os dois hinários somam ~1.100): sem o
// separador, "1243" se lê como um código.
function numeroPt(n) {
  try { return n.toLocaleString('pt-BR'); } catch (_) { return String(n); }
}

// Devolve `[linha forte, linha fraca]`. A fraca pode ser vazia.
function frasesDaContaSorteio(pool) {
  const n = pool.itens.length;
  if (!n) return [fraseDoVazioSorteio(pool), ''];

  // `palavra`, e NÃO `tema`: aquele é o nome de módulo do tema claro × escuro
  // (topo do arquivo), e sombreá-lo aqui é a zona morta temporal que o
  // `sombra.test.mjs` existe para pegar — ele pegou.
  const palavra = sorteioPrefs.tema.trim();
  // "relacionadas a X" é a palavra do operador. Sem tema não há relação a
  // declarar — ali o acervo INTEIRO é o pool, e dizê-lo é o que explica um
  // número na casa dos milhares.
  const forte = palavra
    ? numeroPt(n) + (n === 1 ? ' música relacionada a ' : ' músicas relacionadas a ')
      + '“' + palavra + '”'
    : escopoSemPalavra(n);

  const baixadas = pool.noAparelho;
  const jaTem = baixadas === 0 ? 'nenhuma baixada ainda'
    : baixadas === n ? 'todas já baixadas'
      : numeroPt(baixadas) + (baixadas === 1 ? ' já baixada' : ' já baixadas');

  if (sorteioPrefs.modo !== AVSorteio.MODO_PLAYLIST) {
    // Sortear UMA: o que decide a espera é se HÁ alguma baixada, porque o
    // sorteio prefere as que estão (ver `AVSorteio.sortear`).
    return [forte, baixadas ? jaTem + ' — toca na hora' : jaTem + ' — vai baixar antes de tocar'];
  }

  // MONTAR A FILA. Aqui o custo é EXATO e não uma estimativa: o sorteio esgota
  // as baixadas antes de pegar as que faltam, então quantas precisam de rede é
  // uma subtração, não um palpite.
  const leva = Math.min(sorteioPrefs.quantos, n);
  const baixar = Math.max(0, leva - baixadas);
  const custo = baixar === 0 ? 'todas já baixadas'
    : baixar === leva ? 'todas para baixar'
      : baixar + ' para baixar';
  return [forte, 'A playlist leva ' + leva + ' · ' + custo];
}

// O motivo das COLEÇÕES que a frase do vazio deve nomear ('' se nenhuma foi
// recusada). A régua é ACIONABILIDADE, e não contagem — fica escrito porque
// "o mais numeroso" é o reflexo de quem vier depois, e ele PRODUZ FRASE FALSA:
// `cap.ehMusica` é o `temLetra`, então toda série do YouTube é recusada por
// `sem-musica`. Num aparelho com duas séries e um hinário ainda sem índice o
// mais numeroso é `sem-musica`, e a tela diria "nenhuma coleção de música neste
// aparelho" com o hinário inteiro instalado — além de falsa, sem ação nenhuma.
// A ordem é a do conserto possível: `sem-indice` vence sempre (abrir o card e
// carregar a lista), depois `hinario` (desligar o filtro), e `sem-musica` por
// último — só sobra quando é de fato o caso.
function motivoAcionavelDasColecoes(pool) {
  const vistos = Object.create(null);
  for (const c of (pool && pool.colecoesRecusadas) || []) vistos[c.motivo] = true;
  if (vistos[AVSorteio.MOTIVO_SEM_INDICE]) return AVSorteio.MOTIVO_SEM_INDICE;
  if (vistos[AVSorteio.MOTIVO_HINARIO]) return AVSorteio.MOTIVO_HINARIO;
  if (vistos[AVSorteio.MOTIVO_SEM_MUSICA]) return AVSorteio.MOTIVO_SEM_MUSICA;
  return '';
}

// VAZIO, ELA DIZ O MOTIVO. Sem ele, "nada encontrado" tem cinco causas que pedem
// ações OPOSTAS — trocar a palavra, desligar um filtro, trocar a variante, ou
// abrir a Biblioteca com internet. A ordem é a do que o operador consegue
// consertar mais depressa, nunca a do motivo mais numeroso.
function fraseDoVazioSorteio(pool) {
  if (!pool.colecoesUsadas) {
    // PELO MOTIVO QUE TEM CONSERTO, e não pelo filtro que estava ligado: com
    // "sem hinário" marcado E as coleções recusadas por falta de índice, a
    // pergunta do filtro respondia "só há hinário aqui" — o operador desligava
    // o filtro, continuava vazio, e nada dizia que faltava carregar a
    // biblioteca. Quem sabe por que cada coleção ficou de fora é a própria
    // regra (`avaliarColecao`), e é dela que a frase sai. `sem-indice` e "nenhuma
    // recusa" caem na última frase, que é a que manda carregar a biblioteca.
    const dom = motivoAcionavelDasColecoes(pool);
    if (dom === AVSorteio.MOTIVO_HINARIO) return 'Só há hinário neste aparelho, e o filtro pediu sem ele.';
    if (dom === AVSorteio.MOTIVO_SEM_MUSICA) return 'Nenhuma coleção de música neste aparelho.';
    return 'A biblioteca ainda não foi carregada. Abra-a uma vez com internet.';
  }
  const r = pool.recusas;
  if (sorteioPrefs.soNoAparelho && r[AVSorteio.MOTIVO_FORA]) {
    // Sem palavra não há "o que combina" — o que falta é download, e a frase
    // tem de dizer isso em vez de culpar um tema que não existe.
    return sorteioPrefs.tema.trim()
      ? 'Nada do que combina está baixado. Desligue “Só no aparelho” para baixar na hora.'
      : 'Nada baixado ainda. Desligue “Só no aparelho” para baixar na hora.';
  }
  if (sorteioPrefs.variante === AVSorteio.VARIANTE_PLAYBACK && r[AVSorteio.MOTIVO_VARIANTE]) {
    return 'Nenhuma delas tem fundo musical. Troque para Cantada.';
  }
  // O FILTRO QUE NINGUÉM LIGOU. Ele nasce aceso, então é o único capaz de
  // esvaziar a lista sem que o operador tenha tocado em nada — e sem esta frase
  // o desfecho seria "nada combina com a palavra", mandando reescrever um tema
  // que não é o problema. Ela vem DEPOIS das duas acima porque aquelas falam de
  // escolhas explícitas: quem ligou "Só no aparelho" quer ouvir sobre ele
  // primeiro.
  if (sorteioPrefs.semInfantis && r[AVSorteio.MOTIVO_INFANTIL]) {
    return 'Só sobraram hinos infantis. Desligue “Sem infantis” para incluí-los.';
  }
  const palavra = sorteioPrefs.tema.trim();
  return palavra ? 'Nada combina com “' + palavra + '” na biblioteca.'
    : 'Nenhuma música disponível com esses filtros.';
}

// Uma linha "rótulo à esquerda, pílulas à direita".
function sorteioLinhaChips(rotulo, opcoes) {
  const li = document.createElement('li');
  li.className = 'sorteio-linha';
  const lab = document.createElement('span');
  lab.className = 'sorteio-rotulo';
  lab.textContent = rotulo;
  li.appendChild(lab);
  const cx = document.createElement('div');
  cx.className = 'misc-opts';
  opcoes.forEach(({ nome, ativo, aoTocar, titulo }) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'misc-chip' + (ativo ? ' active' : '');
    b.textContent = nome;
    if (titulo) b.title = titulo;
    b.setAttribute('aria-pressed', ativo ? 'true' : 'false');
    b.addEventListener('click', aoTocar);
    cx.appendChild(b);
  });
  li.appendChild(cx);
  return li;
}

function renderSorteio() {
  const alvo = sorteioListEl;
  alvo.innerHTML = '';

  // ---- O MODO: quanto? ----
  // O mesmo `.fit-seg` do seletor Cantada/Playback da folha da música: é a
  // mesma classe de pergunta ("qual destes dois?"), e um segundo desenho para
  // ela leria como outro tipo de controle.
  alvo.appendChild(ytSegRow(
    [[AVSorteio.MODO_UMA, 'Tocar uma só'], [AVSorteio.MODO_PLAYLIST, 'Montar playlist']],
    sorteioPrefs.modo,
    (v) => { sorteioPrefs.modo = v; saveSorteioPrefs(); renderSorteio(); },
  ));

  // ---- A PALAVRA TEMA ----
  const liCampo = document.createElement('li');
  liCampo.className = 'sorteio-campo';
  const campo = document.createElement('div');
  campo.className = 'lib-search-campo';
  campo.innerHTML = '<svg class="lib-search-lupa" viewBox="0 0 24 24" fill="none" stroke="currentColor"'
    + ' stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    + '<use href="#icoLupa"/></svg>';
  const inp = document.createElement('input');
  inp.className = 'lib-search';
  inp.type = 'search';
  // O PLACEHOLDER DIZ O QUE O VAZIO SIGNIFICA. É a única superfície em que essa
  // pergunta é feita — "e se eu não escrever nada?" — e responder ali custa uma
  // linha; responder na conta obrigaria o operador a tocar no botão para
  // descobrir. Ele some no primeiro caractere, que é exatamente quando a
  // resposta deixa de valer.
  inp.placeholder = 'Palavra tema (vazio = toda a biblioteca)';
  inp.value = sorteioPrefs.tema;
  inp.setAttribute('aria-label', 'Palavra tema');
  // A PALAVRA É ASSINADA NA HORA; SÓ A CONTA ESPERA.
  //
  // O `debounce` cobria a atribuição TAMBÉM, e isso era um defeito latente:
  // digitar "natal" e tocar no botão dentro dos 130 ms sorteava com a palavra
  // ANTERIOR — sem erro, sem sinal, e com a conta ainda por cima mostrando o
  // número certo, porque ela e o sorteio liam a mesma variável defasada.
  //
  // O que precisa do atraso é só o RECONTAR: ele varre os dois hinários mais
  // todos os álbuns indexados e, para cada faixa que não casa pelo título, o
  // texto inteiro da letra — a mesma varredura que o campo ao lado já paga com
  // `debounce`. Digitar depressa não pode custar uma passada pelo acervo por
  // tecla; escrever uma string, pode.
  const recontar = debounce(atualizarContaSorteio, SEARCH_DEBOUNCE_MS);
  inp.addEventListener('input', () => { sorteioPrefs.tema = inp.value; recontar(); });
  campo.appendChild(inp);
  liCampo.appendChild(campo);
  alvo.appendChild(liCampo);

  // ---- A VARIANTE: o quê? ----
  // "Músicas cantadas" e "apenas o instrumental" são os DOIS valores da mesma
  // pergunta, não dois filtros: marcar os dois não significa nada e não marcar
  // nenhum tem de significar alguma coisa. Como segmento a escolha é sempre
  // uma, e é o mesmo desenho que a folha de uma música do acervo usa.
  //
  // O RÓTULO AQUI É "FUNDO MUSICAL", E NÃO "PLAYBACK" — a pedido do operador,
  // *"pois ela reflete melhor o propósito do filtro"*. Na folha de UMA música
  // "Playback" nomeia o ARQUIVO que se vai tocar (a gravação sem voz, ao lado
  // da cantada); aqui a escolha é o PROPÓSITO da fila inteira, e o propósito é
  // som por baixo do culto com o telão coberto — que é o que a nota abaixo
  // afirma e o que a cortina de fato faz. Duas perguntas diferentes, dois
  // rótulos diferentes.
  //
  // **O VALOR guardado continua sendo `'playback'`** (`VARIANTE_PLAYBACK`), e
  // isso não é descuido: ele é a preferência já gravada nos aparelhos E o
  // argumento de `resolveSongMediaId`, onde qualquer coisa != `'full'` resolve
  // o `fileIdPlayback`. Renomear o valor junto com o rótulo trocaria a variante
  // de todo mundo que já escolheu, em silêncio.
  alvo.appendChild(ytSegRow(
    [[AVSorteio.VARIANTE_CANTADA, 'Cantada'], [AVSorteio.VARIANTE_PLAYBACK, 'Fundo musical']],
    sorteioPrefs.variante,
    (v) => { sorteioPrefs.variante = v; saveSorteioPrefs(); renderSorteio(); },
  ));

  // A NOTA DO FUNDO MUSICAL. Ela aparece SÓ com ele escolhido, que é exatamente
  // quando a pergunta existe — "isto vai aparecer no telão?" —, e é uma
  // AFIRMAÇÃO e não um controle: o que o operador decide já está decidido no
  // segmento acima. Sem ela, a cortina posta pelo sorteio seria uma mudança de
  // estado do telão que ninguém anunciou.
  if (sorteioPrefs.variante === AVSorteio.VARIANTE_PLAYBACK) {
    const nota = document.createElement('li');
    nota.className = 'sorteio-nota';
    nota.textContent = 'Fundo musical: toca sem letra e sem nada no telão.';
    alvo.appendChild(nota);
  }

  // ---- OS FILTROS ----
  alvo.appendChild(sorteioLinhaChips('Filtros', [
    {
      nome: 'Sem hinário', ativo: sorteioPrefs.semHinario,
      titulo: 'Não sortear dos hinários',
      aoTocar: () => { sorteioPrefs.semHinario = !sorteioPrefs.semHinario; saveSorteioPrefs(); renderSorteio(); },
    },
    {
      // NASCE LIGADO (ver `sanear`). É o único chip desta linha que já está
      // aceso quando a folha abre, e é por isso que ele existe como CHIP e não
      // como regra fixa: um filtro que decide sozinho precisa estar à vista, e
      // ser desligável por quem quiser sortear um infantil de propósito.
      nome: 'Sem infantis', ativo: sorteioPrefs.semInfantis,
      titulo: 'Não sortear os hinos infantis do Hinário 2022 ('
        + AVSorteio.INFANTIL_DE + ' a ' + AVSorteio.INFANTIL_ATE + ')',
      aoTocar: () => { sorteioPrefs.semInfantis = !sorteioPrefs.semInfantis; saveSorteioPrefs(); renderSorteio(); },
    },
    {
      nome: 'Só no aparelho', ativo: sorteioPrefs.soNoAparelho,
      titulo: 'Sortear só o que já está baixado — nenhum download',
      aoTocar: () => { sorteioPrefs.soNoAparelho = !sorteioPrefs.soNoAparelho; saveSorteioPrefs(); renderSorteio(); },
    },
  ]));

  // ---- QUANTAS (só montando fila) ----
  // Um teto, e ele é obrigatório: um tema genérico ("Deus" casa em quase toda
  // letra) montaria uma fila de centenas — no pior caso centenas de downloads
  // antes da primeira nota.
  if (sorteioPrefs.modo === AVSorteio.MODO_PLAYLIST) {
    alvo.appendChild(sorteioLinhaChips('Quantas', AVSorteio.QUANTIDADES.map((q) => ({
      nome: String(q), ativo: sorteioPrefs.quantos === q,
      aoTocar: () => { sorteioPrefs.quantos = q; saveSorteioPrefs(); renderSorteio(); },
    }))));
  }

  // ---- A CONTA ----
  const pool = sorteioPool();
  const liConta = document.createElement('li');
  liConta.className = 'sorteio-conta' + (pool.itens.length ? '' : ' vazio');
  pintarContaSorteio(liConta, pool);
  alvo.appendChild(liConta);

  // ---- OS DESFECHOS ----
  //
  // Mesma faixa de fecho da folha de destinos (`.song-menu-go-row`): é a mesma
  // gramática de folha, e o botão desabilitado com a conta acima explicando o
  // porquê é o padrão que esta tela já usa. Ela já sabia hospedar um IRMÃO à
  // direita (o "Ver a letra" da gaveta), então dois botões não custam CSS novo.
  //
  // MONTANDO A FILA HÁ DOIS DESTINOS (v5.306, pedido do operador). Eles não são
  // duas versões da mesma ação: um TOCA (substitui a fila do player e projeta
  // agora) e o outro GUARDA (acrescenta ao Cronograma, sem tocar em nada do que
  // está no ar). Montar o louvor da semana e projetar no domingo são dois
  // momentos, e antes só o primeiro tinha porta.
  //
  // SORTEANDO UMA SÓ o botão continua sendo um: "sorteie uma e guarde" é o
  // caminho que a Biblioteca já dá pela gaveta da linha, com a música escolhida
  // à vista — aqui ele seria um destino a mais para uma decisão que o operador
  // toma justamente por não querer decidir.
  const liGo = document.createElement('li');
  liGo.className = 'song-menu-go-row';
  const fila = sorteioPrefs.modo === AVSorteio.MODO_PLAYLIST;
  const travado = !pool.itens.length || sorteioRodando;

  const botao = (rotulo, classe, aoTocar) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'song-menu-btn sorteio-acao ' + classe;
    const t = document.createElement('span'); t.className = 'song-menu-text';
    const r = document.createElement('span'); r.className = 'song-menu-label';
    r.textContent = rotulo;
    t.appendChild(r); b.appendChild(t);
    b.disabled = travado;
    b.addEventListener('click', () => aoTocar(b));
    return b;
  };

  // O PRIMÁRIO É O DE TOCAR, nos dois modos: é o que o recurso existe para
  // fazer, e o preenchimento em accent é o vocabulário do app para "a ação
  // principal desta folha". O de guardar veste o recesso do irmão secundário.
  liGo.appendChild(botao(fila ? 'Tocar agora' : 'Sortear e tocar', 'song-menu-go',
    (b) => executarSorteio(b, 'tocar')));
  // O SEGUNDO DESFECHO NÃO EXISTE NO MODO FÁCIL. Ele guarda a fila sorteada no
  // Cronograma — e o Modo Fácil não tem Cronograma: não há aba, não há lista, e
  // o que fosse guardado ali só reapareceria para quem trocasse de modo. Um
  // botão que promete um destino invisível é pior que um botão a menos.
  // (Mesma razão da seção de Favoritos — ver `renderCollectionsList`.)
  if (fila && appMode !== 'simple') {
    liGo.appendChild(botao('Ao Cronograma', 'song-menu-letra',
      (b) => executarSorteio(b, 'cronograma')));
  }
  alvo.appendChild(liGo);
}

// ===== PLAYBACK SORTEADO É SOM DE FUNDO (v5.311) =====
//
// Pedido do operador: *"quando for apenas uma música ou playlist de playback,
// quero que trate eles como apenas áudio, sem aparecer nada na tela… essa função
// é para som de fundo, então não deve ter propósitos de ver letra ou elementos
// visuais"*.
//
// **A CORTINA JÁ FAZ EXATAMENTE ISSO, e é por isso que não há mecanismo novo.**
// `view: 'wallpaper'` põe o wallpaper por cima, e o `#lyrics` do Display vive no
// MESMO z-index dos layers de mídia — a cortina cobre os dois de graça (o
// comentário está no `display.js`). O áudio segue tocando: a cortina é visual.
// E ela viaja DENTRO do `load`, então o telão nunca chega a desenhar a letra
// para escondê-la um quadro depois. Nada de campo novo no barramento, nada de
// `SHELL_VERSION`, e a tela da rede — que roda o mesmo `display.js` — herda.
//
// **A DECISÃO É EXPLÍCITA NOS DOIS SENTIDOS**, e não só "ligar quando playback":
// o operador que sorteou um playback fica com a cortina posta, e o sorteio
// seguinte de uma CANTADA precisa revelá-la — senão o louvor entra mudo de
// imagem e sem letra, por causa de uma escolha de dois minutos atrás. O sorteio
// passa a dizer o estado do telão em vez de herdá-lo.
//
// Ela é chamada ANTES do `load` de propósito (ver acima), e usa o `setView` de
// sempre: ele persiste, redesenha o botão da cortina — que é onde o operador vê
// que o telão está coberto — e trata a Camada de Texto em cena.
// QUAL CORTINA ESTA ESCOLHA PEDE. Separada de quem AGE porque há dois
// momentos: quem PROJETA aplica agora, e o pacote guardado no Cronograma
// carrega a decisão para aplicá-la quando for aberto, semanas depois — sem ela
// um pacote chamado "Fundo musical" abriria com a letra no telão, desmentindo o
// próprio nome.
function cortinaDoSorteio(f) {
  return f.variante === AVSorteio.VARIANTE_PLAYBACK ? 'wallpaper' : 'visual';
}
async function acertarCortinaDoSorteio(f) {
  const alvo = cortinaDoSorteio(f);
  if (view !== alvo) await setView(alvo);
}

// ---- O sorteio -------------------------------------------------------------

// `desfecho` = `'tocar'` (a fila do player, projetando a primeira) ou
// `'cronograma'` (guardar, sem mexer no que está no ar). Sorteando UMA SÓ só o
// primeiro existe — ver a nota da faixa de fecho.
async function executarSorteio(btn, desfecho) {
  if (sorteioRodando) return;
  sorteioRodando = true;
  try {
    // O índice de letras ANTES do sorteio, sempre — ver o cabeçalho. Já pronto,
    // resolve no mesmo instante e nada espera.
    await ensureLyricIndex();
    const f = AVSorteio.sanear(sorteioPrefs);
    const pool = AVSorteio.montarPool(allCollections(), f, sorteioCap());
    const quantos = f.modo === AVSorteio.MODO_PLAYLIST ? f.quantos : 1;
    const escolhidos = AVSorteio.sortear(pool.itens, quantos);
    // O VEREDITO sai da passada que decidiu, e é o que o Registro imprime.
    sorteioDiario = {
      quando: Date.now(), filtros: f, pool,
      escolhidos: escolhidos.map((i) => ({
        nome: songLabel(i.coll, i.s), colecao: i.coll.name,
        casou: i.casou, noAparelho: i.noAparelho,
      })),
    };
    if (!escolhidos.length) {
      // A conta já diz o motivo por extenso, dois centímetros acima do botão —
      // o pulso é o "não deu" que a mão precisa, e não uma segunda frase.
      pulsar(btn, 'erro');
      atualizarContaSorteio();
      return;
    }
    // A cortina só é acertada por quem PROJETA. "Ao Cronograma" guarda e não
    // toca em nada do que está no ar — mexer no telão ali seria o oposto do que
    // aquele botão promete.
    if (f.modo !== AVSorteio.MODO_PLAYLIST) {
      await acertarCortinaDoSorteio(f);
      await tocarSorteada(escolhidos[0]);
    } else if (desfecho === 'cronograma') {
      await guardarSorteadasNoCronograma(escolhidos, btn, f);
    } else {
      await acertarCortinaDoSorteio(f);
      await montarFilaSorteada(escolhidos);
    }
  } finally {
    sorteioRodando = false;
    // E A FOLHA VOLTA A ACEITAR TOQUE. Ela costuma já ter sido fechada aqui,
    // mas há um caminho em que não: recusar o consentimento de download desiste
    // sem fechar nada. Sem este redesenho, um render que tenha acontecido
    // DURANTE a corrida (o índice de letras chegando) deixaria o confirmar
    // desabilitado pelo `sorteioRodando` — e nada mais o reabilitaria.
    if (sorteioPopupEl.classList.contains('open')) renderSorteio();
  }
}

// UMA SÓ. `playSongVariant` já faz tudo — fecha o acervo, abre o cartão de
// espera sobre a preview, baixa se faltar, substitui a fila e envia. O que sobra
// aqui é fechar ESTA folha antes, para a resposta aparecer numa tela livre.
async function tocarSorteada(escolha) {
  if (!escolha.noAparelho && !(await ensureDownloadConsent())) return;
  fecharSorteio();
  await playSongVariant(escolha.coll, escolha.s, escolha.variante);
}

// AO CRONOGRAMA. Ele guarda, e é essa a diferença que justifica o segundo botão:
// não toca no que está no ar, não substitui a fila do player e não projeta nada.
// O operador monta o louvor da semana numa terça e projeta no domingo.
//
// A FOLHA FICA ABERTA, ao contrário do "Tocar agora". É o mesmo princípio das
// listas de destino do acervo: uma ação que GUARDA não encerra a conversa, e
// aqui o segundo sorteio é o uso normal — o operador acrescenta cinco, olha a
// lista, acrescenta mais cinco. Fechar a folha cobraria três toques por rodada.
//
// A RESPOSTA NASCE NO BOTÃO TOCADO (`responder` + `textoLote`), que é a regra do
// projeto para feedback, e a frase separa o que ENTROU do que JÁ ESTAVA — sem
// isso, sortear duas vezes seguidas com o mesmo tema pareceria não ter feito
// nada na segunda.
// `f` são os FILTROS SANEADOS da passada que decidiu, e não `sorteioPrefs`:
// o nome do pacote e a cortina que ele guarda têm de descrever o sorteio que
// de fato aconteceu. A folha continua aberta depois de guardar, então mexer
// num controle enquanto o download corre reescreveria as preferências — e o
// pacote sairia com o nome de uma escolha que ninguém sorteou.
async function guardarSorteadasNoCronograma(escolhidos, btn, f) {
  const faltam = escolhidos.filter((i) => !i.noAparelho).length;
  if (faltam && !(await ensureDownloadConsent())) return;

  sorteioCancelado = false;
  const total = escolhidos.length;
  const bg = previewBusy('Preparando', total + ' para o Cronograma',
    () => { sorteioCancelado = true; });
  const tarefa = bgTaskStart('Playlist automática', total);
  const ids = [];
  const nomes = [];
  try {
    await withBgWork(async () => {
      for (let i = 0; i < escolhidos.length; i++) {
        if (sorteioCancelado) break;
        const { coll, s, variante } = escolhidos[i];
        const nome = songLabel(coll, s);
        bgItemStart(tarefa, nome);
        bg.atualizar('Preparando', (i + 1) + ' de ' + total + ' · ' + nome);
        let id = null;
        try { id = await resolveSongMediaId(coll, s, variante); } catch (_) { id = null; }
        if (id && !ids.includes(id)) { ids.push(id); nomes.push(nome); }
        bgTaskStep(tarefa, i + 1);
        bgItemEnd(tarefa, nome);
      }
    });
  } finally {
    bgTaskEnd(tarefa);
  }

  // CANCELAR AQUI NÃO DESCARTA O QUE JÁ DESCEU, ao contrário do "Tocar agora".
  // Lá o cancelamento evita trocar a fila do culto por meia lista — uma
  // SUBSTITUIÇÃO pela metade. Aqui a ação ACRESCENTA: três de dez no Cronograma
  // é exatamente o que aconteceu, é reversível linha a linha, e jogar fora um
  // download que já custou rede seria o desperdício que ninguém pediu.
  if (!ids.length) {
    bg.falhar(sorteioCancelado ? 'sorteio cancelado' : 'não foi possível baixar nenhuma faixa');
    return;
  }
  bg.soltar();
  // UM PACOTE, NÃO N LINHAS (v5.313), a pedido do operador: *"ajuste o envio ao
  // cronograma para que ele não envie um por um, mas sim um item que seja um
  // pacote de playlist"*.
  //
  // E ele não é um tipo de item novo: é o cue `group` que o botão "Guardar
  // pacote" da fila já cria — mesmo descritor (`{ ids }`), mesmo desenho de
  // linha, mesmo `abrirPacote` no toque. Invariante 5 aplicada ao lado web:
  // ponteiro novo para um mecanismo que existe, nunca um segundo mecanismo.
  //
  // O que isto resolve é a escala. Dez faixas sorteadas eram dez linhas
  // avulsas no meio do roteiro do culto — para tirá-las, dez perguntas; para
  // saber que eram um lote, memória. Uma linha diz o que é, sai num toque, e
  // abre a fila inteira quando chega a hora dela.
  //
  // **A MÍDIA AQUI VIVE NO STORE `files`**, não no `media` — `resolveSongMediaId`
  // devolve o `fileIdFull`/`fileIdPlayback` do hinário, e `getMedia` cai no
  // `fileGet`. É por isso que guardar os ids DENTRO do cue (que o coletor não
  // conta como detentor: `lerDetentores` lê listas e Favoritos, e apaga só do
  // store `media`) não os deixa órfãos. Quem manda na vida deles é a coleção
  // que os baixou, como antes.
  const rec = await criarCue('group', { ids, view: cortinaDoSorteio(f) },
    nomeDoPacoteSorteado(f, ids.length), 'imports', btn);
  if (!rec) { responder(btn, 'erro', 'Não foi possível guardar o pacote'); return; }
  falarNoSorteio(ids.length + (ids.length === 1 ? ' música' : ' músicas')
    + ' num pacote ' + LISTA_ROTULO.imports.em);
}

/**
 * O NOME DA LINHA no Cronograma. Ele é a única coisa que o operador vê semanas
 * depois, e tem de responder às três perguntas que ele vai fazer: o que é isto,
 * de que tema, e quantas.
 *
 * Não usa a palavra "sorteio": ela já é o nome de OUTRA cena de roteiro
 * (`CUES.draw`), e duas linhas do mesmo Cronograma chamadas "Sorteio" fazendo
 * coisas diferentes é o tipo de colisão que só aparece no sábado de manhã.
 * "Playlist" é como o recurso se chama para quem o usa.
 */
function nomeDoPacoteSorteado(f, quantas) {
  const fundo = f.variante === AVSorteio.VARIANTE_PLAYBACK;
  // `palavra`, e não `tema`: `tema` é o nome de MÓDULO do tema claro/escuro, e
  // sombreá-lo aqui é a zona morta temporal que o `sombra.test.mjs` barra.
  const palavra = (f.tema || '').trim();
  return (fundo ? 'Fundo musical ' : 'Playlist ')
    + (palavra ? '“' + palavra + '”' : 'da biblioteca')
    + ' · ' + quantas + (quantas === 1 ? ' música' : ' músicas');
}

// A CONTA EMPRESTA A SI MESMA POR TRÊS SEGUNDOS — o mesmo mecanismo do `#otaRow`
// e do "Guardar como pacote". O pulso do `responder` diz "deu"; nele não cabe
// dizer QUANTAS entraram e quantas já estavam, e essa distinção é o que impede
// o operador de repetir o toque achando que não funcionou.
//
// A frase mora em ESTADO, não no nó (ver `pintarContaSorteio`).
let sorteioFala = '';
let sorteioFalaTimer = null;
function falarNoSorteio(texto, ms) {
  clearTimeout(sorteioFalaTimer);
  sorteioFala = texto;
  atualizarContaSorteio();
  sorteioFalaTimer = setTimeout(() => {
    sorteioFala = '';
    if (sorteioPopupEl.classList.contains('open')) atualizarContaSorteio();
  }, ms || 3000);
}
// A FALA NÃO ATRAVESSA UMA ABERTURA. Fechar e reabrir a folha é o gesto de
// quem foi fazer outra coisa; reencontrar ali o recibo de três minutos atrás
// diria que a conta é o que ela não é.
function calarSorteio() { clearTimeout(sorteioFalaTimer); sorteioFala = ''; }

// A FILA. O caro é o download, e ele é feito UMA vez por faixa, em série: seis
// downloads em paralelo é o que a sincronização de um álbum faz, e ali ninguém
// espera; aqui a primeira faixa tem de tocar o quanto antes.
async function montarFilaSorteada(escolhidos) {
  const faltam = escolhidos.filter((i) => !i.noAparelho).length;
  // UM consentimento para o lote, nunca um por faixa.
  if (faltam && !(await ensureDownloadConsent())) return;
  fecharSorteio();
  closeHymnSearch();

  sorteioCancelado = false;
  const total = escolhidos.length;
  const bg = previewBusy('Montando', 'playlist de ' + total + ' faixas',
    () => { sorteioCancelado = true; });
  // A notificação do sistema, para o app minimizado: UMA tarefa para o lote —
  // uma por faixa faria a barra reiniciar do zero a cada download.
  const tarefa = bgTaskStart('Playlist automática', total);
  const ids = [];
  try {
    await withBgWork(async () => {
      for (let i = 0; i < escolhidos.length; i++) {
        if (sorteioCancelado) break;
        const { coll, s, variante } = escolhidos[i];
        const nome = songLabel(coll, s);
        bgItemStart(tarefa, nome);
        bg.atualizar('Montando', (i + 1) + ' de ' + total + ' · ' + nome);
        // Uma faixa que não desce não derruba a fila: as outras ainda tocam, e
        // é isso que separa "a playlist saiu menor" de "não aconteceu nada".
        let id = null;
        try { id = await resolveSongMediaId(coll, s, variante); } catch (_) { id = null; }
        if (id && !ids.includes(id)) ids.push(id);
        bgTaskStep(tarefa, i + 1);
        bgItemEnd(tarefa, nome);
      }
    });
  } finally {
    bgTaskEnd(tarefa);
  }

  // CANCELAR NÃO DEIXA MEIA FILA. O botão do cartão diz "parar", e trocar a
  // fila do culto por três das dez que o operador acabou de mandar parar é a
  // resposta oposta à que ele pediu — com o agravante de já ter apagado o que
  // estava lá. O que baixou fica no aparelho e o próximo sorteio o encontra
  // pronto: nada do trabalho se perde, só o efeito.
  if (sorteioCancelado) { bg.falhar('sorteio cancelado — a fila não foi trocada'); return; }
  if (!ids.length) {
    bg.falhar('não foi possível baixar nenhuma faixa');
    return;
  }
  try {
    // O CAMINHO DO `abrirPacote`: a fila do player passa a ser esta, e o
    // primeiro item vai ao telão. `listSet` também COLETA o que saiu da lista —
    // é a mesma semântica de todo "Tocar agora" do acervo, que já substitui a
    // fila por `replacePlaylistWith`.
    await AVDB.listSet('playlist', ids);
    plItems = await AVDB.listItems('playlist');
    renderPlaylist();
    await send(ids[0]);
  } finally {
    bg.soltar();
  }
}

// ===== transições (fade in/out) =====
function openFadePopup() {
  renderAppModeSeg();
  renderTemaTile();
  renderFitTile();
  renderRotBtn();
  renderLyricsBgTile();
  renderWallTile();
  // O estado do espelho é relido ao ABRIR (e depois só enquanto a folha dele
  // estiver aberta): a linha precisa dizer a verdade no instante em que o
  // operador olha para ela, e o espelho pode ter saído do ar sozinho por uma
  // falha nomeada desde a última vez.
  lerEspelho();
  pedirDiag();
  fadePopupEl.classList.add('open');
}
function closeFadePopup() {
  fadePopupEl.classList.remove('open');
}

// ===== A caixa-preta do telão, lida em Configurações =====
// Ver o comentário de `diag()` em display.js: é a única janela para o que
// acontece com a projeção enquanto o celular está fora da frente — não há
// console, não há logcat, e este WebView está estrangulado justamente nesse
// intervalo. O despejo é pedido ao ABRIR esta tela, não continuamente: o telão
// guarda o anel dele e entrega quando alguém pergunta.
// O QUE O TELÃO MANDOU no último `diag-dump` — só a metade dele. A linha do
// tempo é montada na hora de desenhar (ver `eventosDiag`), porque o anel do
// celular continua crescendo depois que o telão respondeu — e continua
// crescendo mesmo quando não há telão para responder.
let diagDoTelao = [];

// O CONTROLE TEM O PRÓPRIO ANEL, e ele é o que importa quando o som sai DESTE
// APARELHO (v5.215, `acertarSaidaDeAudio`): ali quem toca é o `<video>` desta
// página, não o do telão — o registro do Display não veria nada. Foi exatamente
// essa distinção que faltou nas tentativas anteriores.
// O ANEL DO CELULAR: 40 cobriam minutos, e um culto dura duas horas.
//
// O teto existia para o texto não estourar um visor que NÃO EXISTE MAIS — o
// `<pre>` do Registro saiu na v5.207, e desde então este texto só existe para
// ser COPIADO e lido num computador. Guardar mais não custa tela nenhuma; custa
// memória de um array de objetos pequenos, e 200 deles são alguns kB num
// processo que hospeda dois WebViews e um vídeo.
const DIAG_MAX_C = 200;
const diarioC = [];
function diagC(ev, extra) {
  diarioC.push(Object.assign({
    t: Date.now(), ev, oculto: document.visibilityState !== 'visible', onde: 'celular',
  }, extra || {}));
  if (diarioC.length > DIAG_MAX_C) diarioC.shift();
}
document.addEventListener('visibilitychange', () => diagC('visibilidade'));
// A REDE DO CELULAR. Ela é a causa comum de três sintomas que parecem
// independentes — a tela da rede que cai, o download que trava, a atualização
// que não chega —, e sem esta linha os três chegam ao Registro sem a coisa que
// os une.
window.addEventListener('offline', () => diagC('rede do celular: OFFLINE'));
window.addEventListener('online', () => diagC('rede do celular: online'));
window.addEventListener('freeze', () => diagC('congelou'));
window.addEventListener('resume', () => diagC('descongelou'));
(function vigiarPreview() {
  const v = document.getElementById('pvVideo') || document.querySelector('#preview video');
  if (!v) return;
  // A PÁGINA OCULTA PAUSA A PREVIEW, e isso é o Chromium fazendo o certo — não
  // um roubo de foco. MEDIDO no Registro de um aparelho: minimizar o app
  // produzia "PAUSA ESPONTÂNEA [oculto]", e três das cinco linhas de pausa da
  // linha do tempo eram esse falso positivo. É o mesmo defeito do fim natural
  // (v1.1.9) noutro arquivo: a linha reservada ao caso grave gasta no banal, e
  // quem lê a distância conclui que o telão vive caindo.
  //
  // A preview escondida NEM DEVE ser tocada — é a regra do `preverPodeMexer`,
  // que existe justamente porque o navegador a pausa de volta.
  v.addEventListener('pause', () => diagC(
    pausaPedida() ? 'pausa (comando)'
      : (document.visibilityState !== 'visible' ? 'pausa (página oculta)' : 'PAUSA ESPONTÂNEA'),
    { t2: Math.round(v.currentTime || 0) }));
  v.addEventListener('play', () => diagC('play', { t2: Math.round(v.currentTime || 0) }));
})();
// Uma pausa é "comandada" se o operador tocou em algo nos últimos instantes.
let pausaEm = 0;
function pausaPedida() { return Date.now() - pausaEm < 500; }

// O QUE ESTE APARELHO É — o cabeçalho do registro.
//
// Ele existe porque um log colado sem contexto obriga a primeira resposta a ser
// sempre a mesma pergunta ("qual versão? tem transmissão?"). Todo campo aqui é
// coisa que só o aparelho sabe e que muda a leitura do resto.
function cabecalhoDiag() {
  const l = [];
  l.push('Web v' + WEB_VERSION
    + (window.__SHELL_NAME__ ? ' · Shell v' + window.__SHELL_NAME__ : ' · navegador')
    + (window.__NATIVE__ ? ' · ponte ' + (window.__SHELL_VERSION__ | 0) : ''));
  // DO DADO, NÃO DO DOM (v5.193). As duas linhas saíram do rodapé desta folha
  // — quem está conectado é assunto da folha de conexão —, e o Registro lia
  // justamente aqueles elementos. Ler de variável é o que deveria ter sido
  // desde sempre: um diagnóstico que depende de um elemento de UI existir
  // emudece no dia em que alguém o esconde, e emudece em silêncio.
  l.push('Telão: ' + descreverTelao());
  // QUEM É A RÉGUA DO TEMPO agora. A preview ILUSTRA e nunca mede (v5.173), e
  // "a preview voltou dessincronizada" tem causas opostas conforme a projeção
  // seja o telão, uma tela da rede, ou ninguém — este bloco é lido a distância,
  // e sem a linha a pergunta não tem resposta. (`refFonte` já era escrito a
  // cada status e NENHUMA linha o lia: um diagnóstico que ninguém publica é a
  // mesma dívida que um produtor sem consumidor, do outro lado.)
  // E ela é lida com a RECÊNCIA junto: `refFonte` guarda quem reportou por
  // último e não zera sozinho (o status para de chegar quando a mídia sai), então
  // sem esta guarda a linha continuaria dizendo "o telão" com o palco vazio há
  // meia hora — um diagnóstico que envelhece calado é o que este Registro existe
  // para não produzir. O prazo é o mesmo `DISPLAY_TIMEOUT` com que a preview
  // decide assumir.
  const refVelha = !displayStatusAt || (Date.now() - displayStatusAt) > DISPLAY_TIMEOUT;
  l.push('Referência de tempo: ' + (refVelha
    ? 'a preview — nenhuma projeção reportando agora'
    : (refFonte === 'telao' ? 'o telão' : 'uma tela da rede')));
  if (castAlvo) l.push('Espelhar abre: ' + castAlvo);
  // ONDE O SOM ESTÁ SAINDO (v5.215). "Não sai som" tem causas que a tela não
  // separa — mudo, fader em zero, tela conectada sem volume, ou este aparelho
  // calado por haver tela —, e quem lê este bloco está a distância. Ele diz o
  // que o app DECIDIU, não o que o alto-falante fez.
  l.push('Som: ' + (somLocal
    ? 'neste aparelho (nenhuma tela conectada)'
    : (algumaTelaConectada()
      ? 'nas telas conectadas'
      : (somLocalBloqueado
        ? 'em lugar nenhum — o navegador recusou o som deste aparelho'
        : 'em lugar nenhum — sem tela e no Modo Fácil (este aparelho só soa no avançado)'))));
  // SUPORTE A TRANSMISSÃO DIRETA. É o dado mais útil deste bloco desde a
  // v5.120: quando um "Tocar agora" cai no download em vez de transmitir, a
  // primeira pergunta é se o WebView deste aparelho aceita os codecs — e a
  // resposta não se descobre de fora.
  l.push('Transmissão: ' + diagMse());
  // O ALCANCE (v1.4.1). Com a chave fora (v1.4.42) ele responde UMA pergunta, e
  // é a que faz este Registro ser copiado: **o farol chegou a acender?** Sem
  // esta linha, "o número não sobe" é indistinguível de "o farol nunca saiu
  // daqui" — e as duas pedem consertos opostos.
  //
  // O `conta` FICA, e não é sobra: ele é o VEREDITO do shell, e num build
  // debuggável ainda é `false` (o aceso vai para o contador de teste). Sem ele,
  // um Registro tirado de um build de trabalho diria "acendeu" sobre um número
  // que nunca vai aparecer no painel.
  if (farolDiag) {
    l.push('Alcance: este aparelho '
      + (farolDiag.conta ? 'ENTRA na contagem' : 'conta à parte (build de teste)')
      + ' · último aceso: '
      + (farolDiag.ultimo ? new Date(farolDiag.ultimo).toLocaleString() : 'nunca')
      + (farolDiag.diag ? ' · ' + farolDiag.diag : ''));
  }
  // O LOTE QUE ESPERA, e POR QUE ele espera (v5.234).
  //
  // Desde que a pergunta voltou a existir, "por que ainda estou na versão
  // antiga?" tem respostas que a tela não distingue: ninguém foi perguntado
  // ainda, o operador adiou, a pergunta está esperando a cena sair do ar, ou o
  // shell recusou o bundle. As quatro pedem ações diferentes do operador — e
  // este Registro é lido A DISTÂNCIA, então um "esperando…" genérico manda
  // quem o lê investigar a coisa errada.
  const loteReg = loteDaAtualizacao();
  if (loteReg) {
    const oque = [
      loteReg.web ? 'base v' + loteReg.web : '',
      loteReg.shell ? 'app v' + loteReg.shell : '',
    ].filter(Boolean).join(' + ');
    let porque;
    if (loteReg.web && otaRecusadas.has(loteReg.web)) porque = 'o shell RECUSOU aplicá-la';
    else if (otaAdiadas.has(loteReg.chave)) porque = 'o operador adiou nesta sessão';
    else if (apkBaixando) porque = 'baixando o app agora';
    else if (otaPerguntando) porque = 'perguntando agora';
    else if (cenaNoAr()) porque = 'esperando a cena sair do ar';
    // O QUE O OPERADOR PEDIU, e não a rotina (v1.2.28): a varredura de cifras e
    // a de letras rodam sozinhas sobre o acervo inteiro e não seguram mais a
    // pergunta. Dizer "download" sobre elas mandaria procurar um download que
    // ninguém iniciou.
    else if (bgWorkPedido()) porque = 'esperando o download que o operador pediu terminar';
    else porque = 'a pergunta está prestes a aparecer';
    l.push('Atualização: ' + oque + ' esperando — ' + porque);
    // O peso do APK só interessa quando ele está no lote, e interessa muito:
    // é a diferença entre "esperar meio minuto" e "esperar o Wi-Fi da igreja".
    if (loteReg.bytes) l.push('  · o app pesa ' + mb(loteReg.bytes));
    if (loteReg.shell && horaRuimParaAtualizar()) {
      l.push('  · instalar está bloqueado (cena, download pedido ou transmissão no ar)');
    }
  }
  // A PROCURA em si (v5.136). "Não apareceu aviso nenhum" tem quatro causas
  // indistinguíveis da tela — não há versão nova, a busca falhou, o bundle
  // exige um shell mais novo, ou a pergunta está esperando o telão esvaziar —,
  // e a linha acima só cobre a última. Sem esta, a resposta era um palpite.
  if (otaDiagTexto) l.push('Procura: ' + otaDiagTexto);
  // A FAXINA DA ABERTURA. Ela apaga mídia — sem dono, mas mídia —, e uma
  // limpeza que não deixa rastro é indistinguível de um sumiço.
  // SÓ QUANDO ELA APAGOU ALGO. O ramo negativo saía em TODA abertura normal para
  // dizer que nada aconteceu — e a pergunta que esta linha responde ("a mídia
  // sumiu, o que a apagou?") só existe quando o número não é zero.
  if (restosVarridos) {
    l.push('Limpeza: ' + restosVarridos + ' resto(s) sem dono removido(s) nesta abertura');
  }
  // O UA CRU são ~130 caracteres dos quais ~110 são invariantes ("Mozilla/5.0",
  // "AppleWebKit/537.36 (KHTML, like Gecko)", "Mobile Safari/537.36"). O que
  // responde alguma coisa são três campos — a versão do Android, o modelo e a
  // versão do WebView, que é a peça que muda o comportamento de mídia entre dois
  // celulares com o MESMO APK. O cru volta quando o recorte falha, que é
  // exatamente o caso em que ele diz o que o recorte não disse (ROM alternativa,
  // WebView substituído).
  const ua = navigator.userAgent || '';
  const and = /Android (\d+)/.exec(ua);
  const mod = /;\s*([^;)]+?)\s+Build\//.exec(ua);
  const chr = /Chrome\/(\d+)/.exec(ua);
  l.push(and && mod && chr
    ? 'Aparelho: Android ' + and[1] + ' · ' + mod[1].trim() + ' · WebView ' + chr[1]
    : 'Aparelho: ' + ua);
  return l.join('\n');
}

function diagMse() {
  if (!window.MediaSource) return 'sem MediaSource';
  const testes = [
    ['avc1', 'video/mp4; codecs="avc1.640028"'],
    ['aac', 'audio/mp4; codecs="mp4a.40.2"'],
  ];
  const faltam = testes
    .filter(([, t]) => { try { return !MediaSource.isTypeSupported(t); } catch (_) { return true; } })
    .map(([n]) => n);
  const codecs = faltam.length ? 'MediaSource sem ' + faltam.join('+') : 'MediaSource ok (avc1+aac)';
  // POR ONDE A FAIXA VIAJA. É a diferença entre o navegador e o WebView (ver o
  // cabeçalho de `shared/mse.js`), e não se infere da versão que o rodapé
  // mostra — quem decide é o contexto em que a página está rodando.
  if (!window.__NATIVE__) return codecs + ' · navegador (faixa no cabeçalho)';
  return codecs + ' · faixa na URL';
}

// ===== O bloco da TRANSMISSÃO no Registro =====
// (Chamou-se "espelho de pixels" até a v1.2.29. Aquele recurso saiu na v5.187;
// o bloco é do telão por comandos desde então, e os nomes `mirror*` são os do
// contrato da ponte, que não mudou.)
// O Kotlin devolve DADO (JSON) e a frase é montada AQUI. Não é preciosismo: é
// a mesma divisão do `otaDiag`/`ytDiag`, é o que respeita a invariante 5, e é o
// que mantém a sanitização do que veio da rede num ponto só do lado nativo.
//
// TODA LINHA É OPCIONAL, e isso é de propósito: o recurso chega em entregas
// (imagem, depois vídeo, depois áudio), e um bloco que exigisse todos os campos
// quebraria a cada passo. O que o shell não souber responder simplesmente não
// aparece — nunca "undefined" no meio de um log que vai ser repassado.
function mirrorDur(ms) {
  const s = Math.round((Number(ms) || 0) / 1000);
  if (s < 60) return s + ' s';
  const m = Math.round(s / 60);
  return m < 60 ? m + ' min' : Math.floor(m / 60) + ' h ' + (m % 60) + ' min';
}

// `PowerManager.THERMAL_STATUS_*` por índice.
const MIRROR_TERMICA = ['NONE', 'LIGHT', 'MODERATE', 'SEVERE', 'CRITICAL', 'EMERGENCY', 'SHUTDOWN'];

function blocoEspelho(d) {
  if (!d || typeof d !== 'object') return '';
  // O TÍTULO É "TRANSMISSÃO PARA NAVEGADOR" (v5.202). Ele dizia "Espelho de
  // pixels" — o nome do recurso que a v5.187 APOSENTOU por inteiro (o
  // VirtualDisplay → H.264 → MSE). O bloco descreve o telão por comandos há
  // catorze versões, e o operador lê este texto justamente quando algo não está
  // conectando: um título que nomeia um recurso que não existe mais é a pior
  // linha possível num diagnóstico que vai ser repassado. O nome usado aqui é o
  // MESMO do interruptor na folha de conexão, para os dois falarem do mesmo.
  const l = ['Transmissão para navegador'];
  const srv = d.servidor || {};
  const svc = d.servico || {};
  if (srv.ligado) {
    // A VIA SAI DO ESTADO, e não de um literal. Ela era ", ligado à Wi-Fi)"
    // cravado — verdade enquanto a Wi-Fi era a única forma de servir, e mentira
    // no instante em que o ponto de acesso passou a servir também. Este é o
    // artefato que existe para ser COPIADO e lido a distância: uma linha que
    // afirma a rede errada manda investigar o roteador de quem está servindo
    // pelo próprio celular.
    l.push('servidor: ' + (srv.url || '?')
      + ' (' + (srv.tls ? 'HTTPS' : 'HTTP') + ', ' + mirrorVia(srv.via)
      + (srv.iface ? ' — ' + srv.iface : '') + ')'
      + (srv.noArMs ? ' · ' + mirrorDur(srv.noArMs) + ' no ar' : '')
      + (svc.servico ? ' · serviço de pé' : ' · SEM serviço em primeiro plano'));
  } else {
    l.push('servidor: desligado');
  }
  // REGRA (aprendida com os nove ramos que este bloco perdeu na v5.206, todos
  // lendo chaves que o shell parou de publicar): apagar o PRODUTOR de uma
  // métrica e deixar o CONSUMIDOR de pé NÃO produz silêncio — produz um ZERO, e
  // zero é um valor legítimo que o consumidor interpreta. O `ritmo` zerado fazia
  // este bloco imprimir "ALARME: ISTO É UM RETÂNGULO PRETO" em todo culto com
  // vídeo no ar, no artefato que existe para ser COPIADO E REPASSADO quando algo
  // não conecta. Remoção de recurso é remoção dos DOIS lados do fio.
  if (svc.termico != null) {
    l.push('térmica: ' + (MIRROR_TERMICA[svc.termico] || svc.termico)
      + ' (máx na sessão: ' + (MIRROR_TERMICA[svc.termicoMax] || svc.termicoMax) + ')'
      + ' · carregador: ' + (svc.carregando ? 'SIM' : 'NÃO'));
  }
  const telas = Array.isArray(srv.telas) ? srv.telas : [];
  if (srv.ligado) {
    // A BANDA QUE A REDE DIZ TER — estimativa do Android, não medição nossa.
    // Sem `iface` de Wi-Fi é a confirmação estrutural de que o socket está
    // onde deveria.
    //
    // O "cabem ~N tela(s) a 3000 kbps" SAIU na v5.206, e a conta é que morreu:
    // ela dividia a subida do enlace pelo bitrate-alvo do ENCODER, que era um
    // fluxo contínuo de 3 Mbps por tela. O telão por comandos não tem fluxo
    // contínuo nenhum — o que atravessa a rede são objetos JSON pequenos e a
    // mídia SOB DEMANDA, uma vez por item —, então dividir banda por um número
    // que não existe mais dava um teto inventado. Os números crus ficam: eles
    // continuam respondendo "este AP aguenta?" sem fingir precisão.
    const en = srv.enlace;
    if (en && (en.upKbps || en.iface)) {
      l.push('enlace: ' + (en.iface || '?')
        + (en.upKbps > 0 ? ' · subida ' + en.upKbps + ' kbps' : '')
        + (en.downKbps > 0 ? ' · descida ' + en.downKbps + ' kbps' : '')
        + (en.validada === false ? ' · SEM SAÍDA PARA A INTERNET (não impede a transmissão)' : ''));
    }
    // SESSÕES × CONEXÕES, e a discordância é a leitura (v5.183). O teto de três
    // é de SESSÕES; a lista é de CONEXÕES. Uma tela que caiu segura a vaga dela
    // por um tempo, e é nessa janela que o espelho responde "lotado" com menos
    // telas na folha — sem este número, uma contradição sem explicação possível.
    const sess = (typeof srv.sessoes === 'number') ? srv.sessoes : -1;
    // (O "· N pendente(s)" SAIU na v5.206: `srv.pendentes` era a FILA DE
    //  APROVAÇÃO, removida na v5.185 — quem chega entra na hora. O array nunca
    //  mais foi publicado, então a linha escrevia "· 0 pendente(s)" em toda
    //  leitura, e a regra do bloco já dizia que zero não vira linha: um
    //  Registro que repete "0" ensina a pular a linha.)
    l.push('telas: ' + telas.length + ' conectada(s) de ' + (srv.teto || 3)
      + (sess >= 0 && sess !== telas.length ? ' · ' + sess + ' vaga(s) ocupada(s)' : '')
      + ' · ' + (srv.conexoesTotais | 0) + ' conexão(ões) desde que ligou'
      + (sess >= (srv.teto || 3) && telas.length < sess
        ? '  ← LOTADO por vaga(s) de tela que caiu; ela abre sozinha' : ''));
    // O CACHE DA ROTA /m/ — o que o celular tem para SERVIR às telas. Sem esta
    // linha, "a tela não toca o vídeo" não separa o empurrão que nunca chegou do
    // item que o LRU já despejou, e as duas pedem ações opostas. A chave só
    // existe quando há cache (ver `EspelhoServidor.estado`), então a linha some
    // sozinha em vez de anunciar um zero que não é medição — a armadilha do
    // `ritmo` da v5.206. Exige shell 45.
    const mid = srv.midia;
    if (mid && typeof mid === 'object') {
      l.push('cache de mídia: ' + (mid.itens | 0) + ' item(ns) · '
        + fmtBytes(mid.bytes || 0) + ' de ' + fmtBytes(mid.teto || 0));
    }
    // (O FREIO DE IDR saiu na v5.206, com o resto: pedir quadro-chave é
    //  vocabulário de encoder, e não há encoder desde a v5.187.)
    // QUEM BATEU NA PORTA E FOI RECUSADO. Todas respondem o mesmo 404 no fio
    // (não vazar existência), e é só aqui que elas se distinguem: `host` é
    // tentativa de DNS rebinding contra este aparelho, `malformada` em
    // quantidade é um scanner varrendo a rede da igreja.
    const rec = srv.recusadas;
    if (rec && typeof rec === 'object') {
      const partes = Object.keys(rec).filter((k) => rec[k]).map((k) => k + ':' + rec[k]);
      if (partes.length) {
        l.push('recusadas: ' + partes.join(' · ')
          + (rec.host ? '  ← `host` é tentativa de DNS rebinding contra este aparelho' : ''));
      }
    }
    // UMA TELA DE COMANDOS, no que o servidor de fato sabe dela (v5.206).
    //
    // O bloco anterior desenhava treze campos de uma tela do espelho de PIXELS
    // (MSE, fetch-stream, MB entregues, descartes, quadros enviados, o
    // autorrelato inteiro do `cliente.js`) — e o servidor publica OITO campos,
    // nenhum daqueles. O resultado era uma tela saudável saindo do Registro
    // como `tela A  ?  MSE:nao  fetch-stream:nao  seguro:nao  wakeLock:nao`
    // seguida de "(esta tela ainda nao relatou medidas — bundle antigo)":
    // quatro negativas e uma acusação, todas falsas, sobre a única tela que
    // estava funcionando.
    //
    // O que ficou é o que separa dois desfechos com correções diferentes:
    //
    //  · `pronta` é o `display-ready` TER CHEGADO (o `__de` que roteia comando
    //    endereçado). Conectada e NÃO pronta é a tela que abriu o SSE e cujo
    //    `/display/` não subiu — outro defeito, e outra correção, que "a tela
    //    não conecta".
    //  · `fila` cheia é esta tela não escoando; vazia com a projeção parada é o
    //    contrário, e o problema está antes.
    //  · `conectada ha` separa uma tela estável de uma que reconecta em laço —
    //    o rótulo não diz isso, porque ele reinicia junto.
    telas.forEach((c) => {
      l.push('  tela ' + (c.rotulo || '?')
        + ' · ' + (c.pronta ? 'pronta' : 'CONECTADA SEM display-ready')
        + ' · conectada ha ' + mirrorDur(c.conectadaMs)
        + ' · ' + (c.eventos | 0) + ' comando(s) entregue(s)'
        + ' · fila ' + (c.fila | 0)
        + ' · tela acesa ' + (c.telaAcesaMin | 0) + ' min');
      // E A FRASE QUE ESTÁ ESCRITA NAQUELA TELA, quando há uma. É onde a tela
      // já diz a causa — só que para uma sala em que ninguém está.
      if (c.aviso) l.push('          diz: "' + c.aviso + '"');
    });
    // A LINHA MAIS IMPORTANTE DESTE BLOCO quando ela aparece. Servidor de pé,
    // porta escutando e nenhum SYN chegando é AP isolation — e ela é
    // indistinguível de "ninguém abriu ainda" sem que alguém a nomeie. Não há
    // conserto do lado do app: a saída é operacional — outro SSID, um roteador
    // próprio (que NÃO precisa de internet: `NET_CAPABILITY_VALIDATED` está
    // deliberadamente fora do filtro do `redeDaWifi`) ou o PONTO DE ACESSO
    // deste celular.
    //
    // E ESSA TERCEIRA SAÍDA É A MAIS FORTE CONTRA ESTE DEFEITO, não uma
    // alternativa qualquer: isolamento de cliente bloqueia cliente↔cliente, e
    // no ponto de acesso o celular é o GATEWAY — é dele que o computador tira
    // DHCP e DNS, então esse caminho não pode estar fechado. O que aqui é uma
    // falha muda, lá deixa de existir.
    if (srv.semConexaoMs > 120000) {
      l.push('nenhuma conexão desde que ligou (há ' + mirrorDur(srv.semConexaoMs) + ') — '
        + 'se alguém abriu o endereço, o roteador está isolando os clientes');
    }
    // TELAS DE CASTIGO — as que o operador acabou de derrubar. Com o código
    // fora (v5.189) não há recusa a contar, e este é o único freio que existe:
    // é ele que explica uma tela que "não volta" logo depois de um toque em
    // Desconectar sem querer. Zero não vira linha: um Registro que repete "0"
    // a cada leitura ensina a pular a linha.
    if (srv.origensBloqueadas) {
      l.push('telas de castigo agora: ' + (srv.origensBloqueadas | 0)
        + ' (derrubadas ha pouco pelo operador)');
    }
    const saida = srv.ultimaSaida;
    if (saida && typeof saida === 'object') {
      l.push('ultima desconexao: tela ' + (saida.rotulo || '?')
        + ' · ' + (saida.motivo || '?'));
    }
  }
  // AS INTERFACES QUE A REGRA VIU, e o motivo de cada recusa.
  //
  // É a ÚNICA forma de diagnosticar a distância um nome de interface de
  // fabricante — e aqui isso não é conforto: a regra do ponto de acesso é
  // KOTLIN, então quando ela erra num aparelho não há OTA que a conserte, e o
  // conserto começa por saber o nome que aquele aparelho deu à interface.
  //
  // O motivo sai VERBATIM de quem decidiu (`EspelhoInterfaces.escolher`), nunca
  // de uma segunda leitura escrita aqui: duas opiniões divergem no primeiro
  // ajuste, e o que sobra é um log que discorda do aparelho.
  const ifs = d.interfaces;
  if (ifs && typeof ifs === 'object') {
    const ach = Array.isArray(ifs.achados) ? ifs.achados : [];
    const rec = Array.isArray(ifs.recusadas) ? ifs.recusadas : [];
    if (ifs.erro) l.push('interfaces: ' + ifs.erro);
    else if (!ach.length && !rec.length) l.push('interfaces: nenhuma lida');
    else {
      l.push('interfaces servíveis: ' + (ach.length || 'nenhuma'));
      ach.forEach((a) => {
        l.push('  + ' + (a.nome || '?') + ' ' + (a.ip || '?')
          + ' → ' + mirrorTipoIface(a.tipo));
      });
      // As recusadas saem TODAS: são poucas (uma dúzia no pior aparelho), e é
      // justamente a recusada que explica "o hotspot está ligado e o app não o
      // acha". Um Registro não tem pressão de tamanho — ele existe para ser
      // COPIADO —, e o que custa aqui é ENTERRAR, não comprimento.
      rec.forEach((r) => l.push('  - ' + (r.nome || '?') + ' → ' + (r.motivo || '?')));
    }
  }
  const linhas = Array.isArray(d.linhas) ? d.linhas : [];
  if (linhas.length) {
    const hora = (t2) => new Date(t2).toLocaleTimeString('pt-BR', { hour12: false });
    // O ANEL GUARDA 60 e mostrava 12. Num culto de duas horas isso é a última
    // meia dúzia de eventos — e a pergunta que o diário responde ("o que
    // aconteceu ANTES de a tela cair?") mora justamente no que estava sendo
    // descartado. Mostrar tudo o que existe é de graça: o teto é do anel, não
    // desta linha, e a caixa do Registro rola.
    linhas.forEach((x) => l.push('  ' + hora(x.em) + '  ' + x.txt));
  }
  return l.join('\n');
}

// A LINHA DO TEMPO dos dois processos, em ordem de relógio.
function eventosDiag() {
  // A JUNÇÃO ACONTECE AQUI, na hora de desenhar, e não quando o telão responde.
  // O anel do celular (`diarioC`) continua crescendo depois do último
  // `diag-dump` — e continua crescendo mesmo quando não há telão nenhum para
  // mandar um. Montar a lista no `juntarDiag` congelava a linha do tempo no
  // instante da última resposta do telão. Ver o comentário de lá.
  const diagLinhas = diarioC.concat(diagDoTelao || []).sort((a, b) => a.t - b.t);
  if (!diagLinhas.length) {
    return 'Linha do tempo\n(sem registros — minimize o app com algo tocando e volte aqui)';
  }
  const hora = (t) => new Date(t).toLocaleTimeString('pt-BR', { hour12: false });
  const desenha = (l) => hora(l.t) + '  ' + (l.onde === 'celular' ? '📱' : '📺') + ' ' + l.ev
    + (l.oculto ? ' [oculto]' : '') + (l.t2 != null ? '  ' + l.t2 + 's' : '');
  // O `.slice(-16)` SAIU, e ele era o pior corte deste arquivo.
  //
  // `diagLinhas` é `diarioC` + o diário do TELÃO, que manda 60 linhas no
  // `diag-dump`: até 100 linhas JÁ ESTÃO NA MÃO quando esta função roda, e ela
  // jogava fora até 84 — incluindo as 60 que o `diag-ask` acabou de ir buscar.
  // Descartar é irreversível, e o que se poupava era espaço numa tela que não
  // existe (o visor saiu na v5.207; o Registro é copiado, não lido aqui).
  // O argumento já estava escrito uma função acima, no `blocoEspelho`: "o teto
  // é do ANEL, não desta linha — mostrar tudo o que existe é de graça".
  //
  // O QUE ENCURTA SEM APAGAR é colapsar a REPETIÇÃO CONSECUTIVA: sete
  // `visibilidade` seguidas viram uma linha com `×7`. Elas são o ruído de fato
  // (minimizar e voltar), e somadas não dizem mais do que a contagem.
  const saida = [];
  for (const l of diagLinhas) {
    const ant = saida[saida.length - 1];
    if (ant && ant.l.ev === l.ev && ant.l.onde === l.onde && l.t2 == null && ant.l.t2 == null) {
      ant.n++;
      continue;
    }
    saida.push({ l, n: 1 });
  }
  return 'Linha do tempo\n' + saida
    .map((x) => desenha(x.l) + (x.n > 1 ? '  ×' + x.n : ''))
    .join('\n');
}

// ===== O BLOCO DAS SÉRIES (v5.249) =====
//
// O que a regra achou nos dois canais, na forma em que ela achou. O consumidor
// deste texto não é quem opera: é quem AJUSTA a regra, a distância, sem o
// aparelho e sem o canal na frente — e é por isso que ele carrega os nomes
// CRUS. Um rótulo já formado ("15/Ago") prova que a regra rodou; só o título
// que entrou nela diz por que ela produziu aquilo.
//
// Ele é mais um BLOCO da caixa que rola, nunca uma faixa nova em outro canto
// (regra do projeto), e o botão de copiar que já existe no cabeçalho o leva
// junto.

// "há 3 min", ou vazio quando nunca aconteceu. Vazio e não "nunca": a linha
// inteira some, que é a regra deste Registro — o que não se sabe não vira
// palavra.
// 'AAAA-MM-DD' → '15/08' (o dia do corte, como o operador o lê). Recebendo um
// carimbo de tempo em vez da string — um diário anterior à v5.255 —, ela ainda
// responde, que é a regra deste bloco: toda linha é opcional, nenhuma mente.
function serieDiaBr(dia) {
  const t = String(dia || '');
  const m = t.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return m[3] + '/' + m[2];
  const d = new Date(Number(dia) || 0);
  return Number(dia) ? String(d.getDate()).padStart(2, '0') + '/'
    + String(d.getMonth() + 1).padStart(2, '0') : '?';
}

// O SÁBADO da semana de um dia guardado ("2026-08-19" → "22/Ago"). Ele existe
// para o Registro poder dizer a data de corte em vez de um número de dias, e a
// conta é do `AVSerie` — a mesma que a lista usou. Uma segunda conta de
// calendário aqui divergiria dela, e o log passaria a discordar do aparelho.
//
// O dia guardado é o da VARREDURA, não o de hoje: foi o corte DELE que produziu
// a lista de futuros que esta linha descreve.
function serieSabadoDoCorte(dia) {
  const m = String(dia || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return '';
  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  if (isNaN(d.getTime())) return '';
  return AVSerie.rotuloData(AVSerie.sabadoDaSemana(d));
}

function serieHa(quando) {
  return quando ? 'há ' + mirrorDur(Date.now() - quando) : '';
}

// O motivo vira FRASE aqui, e só aqui. Duas delas citam a série, e é isso que
// as torna úteis: "não começa com Informativo" diz o que fazer; "prefixo", não.
function serieMotivoFrase(motivo, serie) {
  switch (motivo) {
    case AVSerie.MOTIVO_PREFIXO: return 'não começa com "' + serie.prefixo + '"';
    case AVSerie.MOTIVO_LIBRAS: return 'é a versão em Libras';
    case AVSerie.MOTIVO_IDIOMA: return 'está em outro idioma';
    case AVSerie.MOTIVO_ANO: return 'não é de ' + serie.ano;
    case AVSerie.MOTIVO_PERIODO: return 'não diz de que '
      + (serie.periodo === AVSerie.PERIODO_TRIMESTRE ? 'trimestre' : 'mês') + ' é';
    case AVSerie.MOTIVO_SEM_ID: return 'veio sem id de vídeo';
    case AVSerie.MOTIVO_VAZIO: return 'veio sem nome';
    default: return motivo || '?';
  }
}

// O TETO das listas longas, e ele é ANUNCIADO quando morde (regra do projeto:
// nenhum corte silencioso). Ele nunca alcança um achado: recusas e episódios
// sem data são o que este bloco existe para mostrar, e são poucos por natureza
// — o que pode crescer é a lista de nomes, que tem 52 por ano e por série.
const SERIE_DIARIO_TETO = 60;
// AS RECUSAS SÃO RESUMIDAS POR MOTIVO, e é isto que devolve o Registro ao
// operador. MEDIDO num aparelho: este bloco ocupou ~140 das ~170 linhas de uma
// cópia, com "não começa com Informativo" repetido SESSENTA vezes — enterrando
// a linha do tempo, que é o único bloco que responde "o que aconteceu no
// culto?".
//
// O corte é do RUÍDO, não do sinal. Sessenta linhas iguais não dizem mais que a
// contagem, mas UM nome cru diz o que a contagem não diz: no dia em que o canal
// renomeia tudo, é lendo o nome que se descobre. Por isso cada motivo mantém os
// primeiros nomes CRUS — e o que foi escondido continua CONTADO, que é a regra
// que este bloco já seguia ("nenhum corte silencioso").
const SERIE_NOMES_POR_MOTIVO = 4;
function serieRecusasResumidas(itens, frase) {
  const porMotivo = new Map();
  for (const it of itens) {
    const m = it.motivo || '?';
    if (!porMotivo.has(m)) porMotivo.set(m, []);
    porMotivo.get(m).push(it.nome);
  }
  const out = [];
  for (const [m, nomes] of porMotivo) {
    out.push('    - ' + nomes.length + '× ' + frase(m));
    nomes.slice(0, SERIE_NOMES_POR_MOTIVO).forEach((n) => out.push('        "' + n + '"'));
    if (nomes.length > SERIE_NOMES_POR_MOTIVO) {
      out.push('        …e mais ' + (nomes.length - SERIE_NOMES_POR_MOTIVO)
        + ' com o mesmo motivo');
    }
  }
  return out;
}
function serieLista(itens, formatar) {
  const out = itens.slice(0, SERIE_DIARIO_TETO).map(formatar);
  if (itens.length > SERIE_DIARIO_TETO) {
    out.push('    …e mais ' + (itens.length - SERIE_DIARIO_TETO) + ' (cortados por este registro, não pela regra)');
  }
  return out;
}

// ===== O BLOCO DA PLAYLIST AUTOMÁTICA (v5.303) =====
//
// A regra do sorteio decide a partir de NOMES e de um índice de letras que pode
// não estar pronto, e o modo de errar é silencioso dos dois lados: uma faixa
// recusada some sem erro no console, e uma faixa aceita por engano toca. Este
// bloco diz o que a última passada achou — e o veredito sai da MESMA passada
// que decidiu (`sorteioDiario` é gravado dentro de `executarSorteio`), nunca de
// uma segunda leitura das mesmas perguntas.
//
// Ele guarda a PALAVRA CRUA e os filtros do momento: um rótulo já formado prova
// que a regra rodou; só a entrada dela diz por que ela produziu aquilo.
const SORTEIO_MOTIVOS = {
  'sem-musica': 'não é acervo de música (séries e vídeos)',
  hinario: 'hinário, e o filtro pediu sem',
  'sem-indice': 'sem índice neste aparelho',
  variante: 'a origem não tem esta variante',
  tema: 'não casa a palavra tema',
  'fora-do-aparelho': 'não está baixada, e o filtro pediu só o que está',
};
const SORTEIO_CASOU = { nome: 'no nome', album: 'no álbum', letra: 'na letra', 'sem-tema': 'sem tema' };

function blocoSorteio() {
  if (!sorteioDiario) return '';
  const d = sorteioDiario;
  const f = d.filtros;
  const p = d.pool;
  const linhas = ['Playlist automática (o que a regra achou)'];
  linhas.push('· ' + serieHa(d.quando) + ' · ' + (f.modo === AVSorteio.MODO_PLAYLIST
    ? 'fila de até ' + f.quantos : 'uma só')
    + ' · ' + (f.variante === AVSorteio.VARIANTE_PLAYBACK
      ? 'fundo musical (telão coberto)' : 'cantada')
    + (f.semHinario ? ' · sem hinário' : '')
    + (f.semInfantis ? ' · sem infantis' : '')
    + (f.soNoAparelho ? ' · só no aparelho' : ''));
  // A palavra CRUA e a normalizada, porque a diferença entre as duas já
  // explicou uma busca que "não achava nada" (espaço à direita, acento).
  linhas.push('  tema: ' + (f.tema.trim() ? '"' + f.tema.trim() + '" → "' + p.tema + '"' : '(nenhum — o acervo inteiro)'));
  linhas.push('  índice de letras: ' + (lyricIndex ? lyricIndex.size + ' faixa(s) com letra' : 'ainda não montado'));
  linhas.push('  coleções: ' + p.colecoesVistas + ' vistas, ' + p.colecoesUsadas + ' usadas');
  // As recusas de COLEÇÃO agrupadas pelo motivo: listar 40 álbuns sem índice um
  // a um afogaria a única linha que importa. O nome só aparece quando são
  // poucos — e é aí que ele responde "qual álbum?".
  const porMotivo = new Map();
  for (const c of p.colecoesRecusadas) {
    if (!porMotivo.has(c.motivo)) porMotivo.set(c.motivo, []);
    porMotivo.get(c.motivo).push(c.nome);
  }
  for (const [motivo, nomes] of porMotivo) {
    linhas.push('    - ' + nomes.length + ' → ' + (SORTEIO_MOTIVOS[motivo] || motivo)
      + (nomes.length <= 3 ? ': ' + nomes.filter(Boolean).join(' · ') : ''));
  }
  linhas.push('  faixas: ' + p.faixasVistas + ' vistas, ' + p.itens.length + ' no sorteio, '
    + p.noAparelho + ' já no aparelho');
  for (const [casou, n] of Object.entries(p.casaram)) {
    linhas.push('    + ' + n + ' casou(casaram) ' + (SORTEIO_CASOU[casou] || casou));
  }
  for (const [motivo, n] of Object.entries(p.recusas)) {
    linhas.push('    - ' + n + ' → ' + (SORTEIO_MOTIVOS[motivo] || motivo));
  }
  // O QUE SAIU, na ordem em que foi para a fila. UM NOME POR LINHA: o separador
  // óbvio (" · ") já é parte do rótulo de uma faixa numerada.
  if (!d.escolhidos.length) {
    linhas.push('  sorteado: NADA — a folha disse o motivo ao operador');
  } else {
    linhas.push('  sorteado (' + d.escolhidos.length + ', nesta ordem):');
    linhas.push(...serieLista(d.escolhidos, (e) => '    ' + e.nome
      + ' [' + e.colecao + ' · ' + (SORTEIO_CASOU[e.casou] || e.casou)
      + ' · ' + (e.noAparelho ? 'no aparelho' : 'baixou') + ']'));
  }
  return linhas.join('\n');
}

// ===== AS COLETÂNEAS: o que a regra dissolveu (v1.5.16) =====
//
// A regra do `coletanea.js` decide, a partir de NOMES que o banco renomeia sem
// avisar, qual coletânea sai da tela e para onde vão os álbuns dela. Os dois
// modos de errar são silenciosos: a origem que não casa mais fica na Biblioteca
// como se nada tivesse sido pedido, e o destino que não casa mais faz a regra
// desistir — o desfecho certo, e igualmente invisível. Este bloco é o que
// distingue os dois a distância.
//
// MONTADO NA HORA, chamando a MESMA função que desenha. Ao contrário do diário
// das séries — que registra um evento de REDE e por isso precisa sobreviver à
// sessão —, aqui a regra é síncrona e pura: uma segunda leitura não pode
// discordar da primeira, e persistir o veredito só criaria uma cópia para
// divergir.
//
// E ELE IMPRIME AS CATEGORIAS VISTAS. É essa lista que permite consertar uma
// grafia por OTA sem pedir captura ao operador — sem ela, "não dissolveu" e
// "dissolveu e você não viu" chegam com a mesma cara.
function blocoColetaneas() {
  if (!window.AVColetanea) return '';
  const cats = (albumCatalog && albumCatalog.categories) || [];
  // SEM CATÁLOGO NÃO HÁ VEREDITO. O diário tem sempre uma entrada por linha da
  // tabela, então sem esta guarda o bloco afirmaria *"a coletânea não existe
  // neste banco"* num aparelho que simplesmente ainda não fez o
  // `fetchAlbumCatalog` — instalação nova sem rede, ou o navegador. São duas
  // causas com consertos opostos ("o banco renomeou, ajuste a tabela e publique"
  // contra "não houve busca ainda") e uma frase só, e é justamente o aparelho
  // que não conectou que produz o Registro que alguém copia.
  if (!cats.length) return '';
  const { diario } = AVColetanea.aplicar(cats);
  if (!diario.length) return '';
  const nomeDoAlbum = (id) => {
    const a = (albumCatalog.albums || []).find((x) => x.id_album === id);
    return a && a.name ? a.name : ('álbum ' + id);
  };
  const linhas = [];
  for (const d of diario) {
    if (d.motivo === AVColetanea.MOTIVO_MOVIDA) {
      // O DADO CRU, e não só a contagem: é lendo o nome de um álbum que se
      // descobre que a regra mexeu no grupo errado.
      linhas.push('· "' + d.de + '" → "' + d.para + '": ' + d.movidos.length
        + ' álbum(ns) movido(s) para o fim'
        + (d.movidos.length ? ' — ' + d.movidos.map(nomeDoAlbum).join(' · ') : ''));
      if (d.jaEstavam.length) {
        // N:N — não é erro, é o banco. Dito porque a conta não fecha sem ele.
        linhas.push('    ' + d.jaEstavam.length + ' já estava(m) no destino (a mesma '
          + 'coletânea em duas): ' + d.jaEstavam.map(nomeDoAlbum).join(' · '));
      }
      if ((d.repetidosNaOrigem || []).length) {
        // OUTRA COISA, e com outro conserto: o banco listou o mesmo álbum duas
        // vezes DENTRO da coletânea de origem. Dizer "já estava no destino"
        // mandaria procurá-lo onde ele não está.
        linhas.push('    ' + d.repetidosNaOrigem.length + ' repetido(s) dentro da '
          + 'própria "' + d.de + '": ' + d.repetidosNaOrigem.map(nomeDoAlbum).join(' · '));
      }
    } else if (d.motivo === AVColetanea.MOTIVO_SEM_DESTINO && d.de === d.para) {
      // A LINHA DEGENERADA. A regra devolve `sem-destino` porque o desfecho é o
      // mesmo (nada é feito), mas a FRASE de lá seria falsa aqui: o destino
      // existe — ele é a própria origem. Quem escolhe a palavra é esta função,
      // e é aqui que a linha da tabela aparece nomeada, que é a única coisa
      // capaz de levar alguém ao erro de digitação que a produziu.
      linhas.push('· "' + d.de + '" tem uma linha em que a ORIGEM e o DESTINO são '
        + 'a mesma coletânea — nada foi feito (confira a tabela DISSOLVER)');
    } else if (d.motivo === AVColetanea.MOTIVO_SEM_DESTINO) {
      linhas.push('· "' + d.de + '" NÃO foi dissolvida: o destino "' + d.para
        + '" não existe neste banco — a coletânea continua na tela, inteira');
    } else {
      linhas.push('· "' + d.de + '" não existe neste banco (nada a dissolver)');
    }
  }
  linhas.push('  coletâneas do banco: '
    + (cats.length ? cats.map((c) => c.name).join(' · ') : 'nenhuma'));
  return 'Coletâneas (o que a regra dissolveu)\n' + linhas.join('\n');
}

async function blocoSeries() {
  if (!serieDisponivel()) return '';
  const linhas = [];
  for (const coll of serieCollections()) {
    const s = coll.serie;
    const d = await serieDiarioLer(coll.id);
    linhas.push('· ' + s.name + ' — ' + s.canal);
    linhas.push('  prefixo "' + s.prefixo + '" · ' + s.ano + ' · playlists por '
      + (s.periodo === AVSerie.PERIODO_TRIMESTRE ? 'trimestre' : 'mês')
      // CADA MODO COM A SUA FRASE: o Informativo é `TITULO_SERIE` desde a
      // v5.271, e uma frase única o classificaria como "pelo título" —
      // justamente a série que IGNORA o título do vídeo. Um log que discorda do
      // aparelho é o pior artefato que este projeto sabe produzir, e este é
      // lido A DISTÂNCIA.
      + ' · rótulo ' + (s.titulo === AVSerie.TITULO_SERIE
        ? 'pela data e pelo nome da série'
        : 'pelo título'));
    if (!d) {
      // O caso mais fácil de ler errado: card na tela, nada no Registro. Ele é
      // normal (a lista só é buscada no primeiro toque ou na retomada) e
      // precisa estar DITO, senão se lê como o recurso quebrado.
      linhas.push('  ainda não varrido neste aparelho — abra o card na Biblioteca'
        + ' (ou toque em "Atualizar a lista")');
      continue;
    }
    const pls = d.playlists || [];
    const aceitas = pls.filter((p) => !p.motivo);
    linhas.push('  aba do canal (' + serieHa(d.quandoCanal) + '): ' + pls.length
      + ' playlist(s), ' + aceitas.length + ' aceita(s)');
    // O RECORTE É O ANO DA SÉRIE, e ele nasceu do primeiro registro real
    // (v5.252): os dois canais publicam há anos, e a aba tem **94 e 145**
    // playlists. Listadas por inteiro, as 9 aceitas do Provai e Vede ficavam
    // enterradas sob oitenta linhas dizendo "não é de 2026" e "não começa com
    // Provai e Vede" — e o teto de 60 cortava justamente o fim, que é onde o
    // sinal poderia estar. Um log que ninguém termina de ler não é diagnóstico.
    //
    // **Some só o que traz OUTRO ano no nome.** É o único corte que não pode
    // esconder o defeito que este bloco existe para achar: um mês do ano
    // corrente que tenha sido renomeado ("Provai & Vede - Julho 2026") continua
    // aparecendo, porque ele traz 2026; e uma playlist SEM ano nenhum aparece
    // também, porque é justamente assim que uma renomeação se disfarça. O que
    // sai é o arquivo dos anos anteriores, que não muda e não decide nada.
    const doAno = new RegExp('\\b' + s.ano + '\\b');
    const temAno = /\b(19|20)\d{2}\b/;
    const perto = pls.filter((p) => !p.motivo || doAno.test(p.nome) || !temAno.test(p.nome));
    // AS ACEITAS SAEM NOMINAIS e uma por linha — são poucas por natureza (nove
    // no Provai e Vede) e são o que prova que a regra achou o que devia.
    linhas.push(...serieLista(perto.filter((p) => !p.motivo),
      (p) => '    + "' + p.nome + '" → mês ' + p.mes + ' · ' + p.count + ' vídeo(s) no canal'));
    // AS RECUSADAS saem agrupadas por motivo (ver `serieRecusasResumidas`).
    linhas.push(...serieRecusasResumidas(perto.filter((p) => p.motivo),
      (m) => serieMotivoFrase(m, s)));
    // O QUE FOI ESCONDIDO É CONTADO, por motivo (nenhum corte silencioso).
    const outras = pls.length - perto.length;
    if (outras) {
      const porMotivo = {};
      pls.filter((p) => perto.indexOf(p) < 0)
        .forEach((p) => { porMotivo[p.motivo] = (porMotivo[p.motivo] || 0) + 1; });
      linhas.push('    (mais ' + outras + ' de outros anos: '
        + Object.keys(porMotivo).map((m) => porMotivo[m] + ' ' + serieMotivoFrase(m, s)).join(' · ') + ')');
    }

    if (!d.quandoVideos) {
      linhas.push('  vídeos: nenhuma varredura completa ainda');
      continue;
    }
    // A segunda metade traz a PRÓPRIA data, e ela é o ponto: com a assinatura
    // batendo, a aba do canal acima é de agora e isto aqui pode ser de dias
    // atrás. Um carimbo só faria o bloco mentir sobre a metade barata.
    const rec = d.recusados || [];
    const nomes = d.nomes || [];
    linhas.push('  vídeos (varredura ' + serieHa(d.quandoVideos) + '): '
      + (d.total | 0) + ' vistos'
      + (d.anunciados ? ' de ' + d.anunciados + ' anunciados pelo canal' : '')
      + ', ' + nomes.length + ' entraram, ' + rec.length + ' recusado(s)');
    // A DIFERENÇA vira uma linha própria, e não uma conta para quem lê fazer.
    // Ela é o achado mais silencioso deste caminho: nada errou, nada recusou —
    // o vídeo simplesmente não veio, e o sábado dele não existe na lista.
    if (d.anunciados && (d.total | 0) < d.anunciados) {
      linhas.push('    ! ' + (d.anunciados - (d.total | 0)) + ' vídeo(s) que o canal conta '
        + 'e a extração NÃO trouxe (só para membros? removido?) — o sábado deles não está na lista');
    }
    if ((d.vazias || []).length) {
      linhas.push('    ! playlist(s) que voltaram vazias: ' + d.vazias.join(' · '));
    }
    linhas.push(...serieRecusasResumidas(rec, (m) => serieMotivoFrase(m, s)));
    // O QUE AINDA NÃO SAIU (v5.255): uma linha de contagem, e não dezessete de
    // recusa. Eles não são um defeito — são o estado normal de um canal que sobe
    // o trimestre inteiro e libera um sábado por vez —, e listá-los afogaria as
    // recusas de verdade, que são uma ou nenhuma.
    //
    // **O MAIS PRÓXIMO vem junto, e é ele que se confere.** A pergunta que este
    // bloco precisa responder é uma só: "o app está escondendo o episódio do
    // culto de amanhã?". O nome cru dele ao lado da data de corte responde sem
    // depender de eu adivinhar o relógio do aparelho.
    const fut = (d.futuros || []).slice()
      .sort((a, b) => (a.mes - b.mes) || (a.dia - b.dia));
    if (fut.length) {
      const p = fut[0];
      // A DATA DE CORTE, dita como ela é (v1.4.16). Esta linha anunciava "a
      // lista alcança 3 dia(s) além de <dia>", e esse número era o piso que
      // saiu — e que, MEDIDO, nunca decidiu nada para estes dois canais. Um
      // Registro é lido A DISTÂNCIA por quem não tem como conferir: uma linha
      // que descreve um corte que o app não aplica é o pior artefato que este
      // projeto sabe produzir. O corte é o SÁBADO DA SEMANA da varredura, e é
      // ele que o nome do mais próximo permite conferir.
      const sab = serieSabadoDoCorte(d.serieDiaEm);
      linhas.push('    (' + fut.length + ' ainda não liberado(s) pelo canal — a lista vai até o '
        + 'sábado da semana da varredura' + (sab ? ' (' + sab + ')' : '')
        + ', que foi ' + serieDiaBr(d.serieDiaEm || d.quandoVideos)
        + '; o mais próximo é "' + p.nome + '")');
    }
    // O ACHADO que não é recusa, e o mais valioso dos dois: o vídeo ENTROU (a
    // regra de ouro manda entrar) e ficou sem identificador de data, fora de
    // ordem. É o sintoma exato da v5.230, e é dele que sai o próximo ajuste do
    // `dataDoVideo` — por isso o título vem CRU.
    if ((d.semData || []).length) {
      linhas.push('    ! ' + d.semData.length + ' entrou(entraram) SEM data no título:');
      linhas.push(...serieLista(d.semData, (n) => '      "' + n + '"'));
    }
    // UM NOME POR LINHA, e não uma lista separada por algum caractere. Dois
    // deles já são parte dos dados: o rótulo formado tem " · " no meio ("15/Ago
    // · Match point") e o título cru — que é o que sobra quando não há data —
    // tem " | ". Qualquer separador escolhido apareceria DENTRO de um item, e
    // quem lê isto a distância não teria como saber onde um nome termina.
    // A LISTA DE NOMES VIRA AS BORDAS. Ela existia para conferir a ORDEM, e
    // ordem se confere nas pontas: um `TITULO_SERIE` que desmontasse ou uma data
    // lida errada aparecem no primeiro ou no último, e o defeito do MEIO tem
    // sinal próprio — é o `! entrou SEM data`, que continua NOMINAL e cru logo
    // acima. Cinquenta e duas linhas para conferir duas é o que enterrava o
    // resto do Registro.
    if (nomes.length) {
      linhas.push('  ' + nomes.length + ' na lista, de "' + nomes[0]
        + '" a "' + nomes[nomes.length - 1] + '"');
    }
  }
  return linhas.length ? 'Séries do YouTube (o que a regra achou)\n' + linhas.join('\n') : '';
}

// O texto INTEIRO do registro — e é ele que o botão de copiar entrega. Guardado
// aparte do `textContent` porque a caixa pode estar rolada: copiar o que está
// VISÍVEL seria copiar meio log, que é o defeito que esta reforma corrigiu.
let diagTexto = '';

// Guarda de sequência: `renderDiag` virou assíncrona (ela pergunta o
// diagnóstico do YouTube à ponte), e é chamada DUAS vezes ao abrir
// Configurações — uma na hora, com o que já se tem, e outra quando a resposta
// do telão chega. Sem isto, a primeira poderia terminar depois da segunda e
// escrever por cima dela a linha do tempo SEM os eventos do telão, que é
// justamente o que se foi buscar.
let diagSeq = 0;

// O ÁUDIO DO APARELHO — por que o som de outro app sai nas caixas.
//
// Existe porque este vazamento NÃO TEM SINTOMA QUE APONTE A CAUSA: o operador
// ouve o WhatsApp na PA e conclui que o app está com defeito. E porque a
// resposta é uma negativa de ARQUITETURA — não há o que consertar —, ela
// precisa estar escrita onde se copia e se repassa, senão a investigação é
// refeita do zero a cada relato.
//
// A FRASE AQUI É MAIS ESTRITA QUE A DA FOLHA DE CONEXÃO. Lá cabe "o som deste
// celular vai junto", que é o que o operador precisa saber para agir. Aqui a
// afirmação é técnica, e o que se sabe tem três graus: a MÍDIA de outros apps
// vai (observado em aparelho); toque e alarme têm guarda explícita no audio
// policy do AOSP (`// no sonification on remote submix (e.g. WFD)`); e som de
// NOTIFICAÇÃO depende do aparelho — a Samsung é implementação própria. Escrever
// as três como certezas seria inventar duas.
// O MICROFONE, NO REGISTRO — a última tentativa de captura, degrau a degrau.
//
// O bloco "Áudio do aparelho" responde ONDE a voz sai; este responde POR QUE ela
// não saiu, e são perguntas diferentes. Ele existe porque o desfecho relatado do
// aparelho — "O Android não liberou o microfone" — é uma frase que acusa a causa
// MENOS provável (uma chamada, um gravador aberto) e não distingue os quatro
// casos que pedem ações opostas.
//
// SÓ APARECE DEPOIS DE UMA TENTATIVA. Num Registro de um culto em que ninguém
// tocou no microfone ele não responde pergunta nenhuma, e a regra deste arquivo
// é que linha que não responde nada não é impressa.
function blocoMicrofone() {
  if (!micUltima) return '';
  const l = [];
  const quando = new Date(micUltima.quando).toLocaleTimeString('pt-BR', { hour12: false });
  l.push(micUltima.origem + ' · ' + quando + ' · '
    + (micUltima.ok ? 'ABRIU' : 'RECUSADO'));
  for (const d of micUltima.degraus) {
    // A MENSAGEM DO NAVEGADOR ao lado do nome do erro: `NotReadableError` é o
    // balde genérico do WebRTC e a frase costuma nomear a etapa que falhou.
    l.push('  ' + d.qual + ': ' + (d.erro || 'abriu') + (d.msg ? ' — ' + d.msg : ''));
  }
  const disp = micUltima.disp;
  if (disp) {
    l.push('  entradas de áudio que o navegador enxerga: ' + disp.length);
    // O RÓTULO É O QUE DIZ QUAL microfone é. Ele só existe com permissão
    // concedida, então a presença dele já responde metade da pergunta — e o
    // nome ("Fone Bluetooth" contra o embutido) responde a outra metade.
    for (const d of disp) {
      l.push('    · ' + (d.label || '(sem rótulo — a permissão não chegou a valer)'));
    }
  }
  // O QUE O SISTEMA DIZ, quando o shell respondeu. Estas linhas são as únicas
  // do bloco que o navegador não podia produzir — e são elas que fecham o caso
  // em que tudo do lado web está em ordem e a captura falha assim mesmo.
  const sh = micUltima.shell;
  if (sh) {
    l.push('  --- o que o SISTEMA diz (shell) ---');
    if (sh.permissao !== null && sh.permissao !== undefined) {
      l.push('  permissão RECORD_AUDIO: ' + (sh.permissao ? 'concedida' : 'NEGADA'));
    }
    if (sh.appops) l.push('  AppOps para gravar: ' + sh.appops);
    if (sh.modAudio !== null && sh.modAudio !== undefined) {
      l.push('  permissão MODIFY_AUDIO_SETTINGS: ' + (sh.modAudio ? 'concedida' : 'AUSENTE'));
    }
    if (sh.mudo !== null && sh.mudo !== undefined) {
      l.push('  microfone mudo no sistema: ' + (sh.mudo ? 'SIM' : 'não'));
    }
    if (sh.modo !== null && sh.modo !== undefined) {
      // 2 = MODE_IN_CALL, 3 = MODE_IN_COMMUNICATION. É a causa que a frase da
      // tela sempre acusou e que nunca tinha sido verificada.
      const emChamada = sh.modo === 2 || sh.modo === 3;
      l.push('  modo de áudio: ' + sh.modo + (emChamada ? ' (EM CHAMADA)' : ''));
    }
    if (sh.gravando !== null && sh.gravando !== undefined) {
      l.push('  sessões de gravação visíveis: ' + sh.gravando);
    }
    if (Array.isArray(sh.entradas)) {
      l.push('  entradas que o SISTEMA enxerga: ' + sh.entradas.length);
      for (const e of sh.entradas) {
        l.push('    · ' + e.tipo + (e.nome ? ' — ' + e.nome : ''));
      }
    }
  }
  // O VEREDITO, e ele é o ponto do bloco: a mesma frase na tela sai de várias
  // causas, e cada uma pede uma ação diferente. Quem lê o Registro está a
  // distância e não pode tentar todas.
  if (!micUltima.ok) {
    const erros = micUltima.degraus.map((d) => d.erro);
    if (sh && sh.modAudio === false) {
      // VENCE TODOS OS OUTROS, e é o único deste bloco cujo conserto é NOSSO.
      // Sem `MODIFY_AUDIO_SETTINGS` no manifest, o Chromium do WebView recusa a
      // abertura ANTES de qualquer AudioRecord existir — e como a recusa é
      // anterior à negociação de restrições, ela produz `NotReadableError` em
      // TODOS os degraus da escada, que é a assinatura exata que se via.
      // Enquanto este ramo acender, investigar AppOps ou fabricante é perseguir
      // a causa errada.
      l.push('→ FALTA A PERMISSÃO MODIFY_AUDIO_SETTINGS NO APK INSTALADO. Não é o '
        + 'aparelho, não é o AppOps e não é o fabricante: o Chromium do WebView exige '
        + 'essa permissão do app HOSPEDEIRO para abrir qualquer captura de áudio, e sem '
        + 'ela toda tentativa morre em NotReadableError. Ela é concedida na instalação '
        + '(não há o que autorizar na tela). O conserto é INSTALAR O APK v1.2.13 OU MAIS '
        + 'NOVO — versões anteriores não têm como funcionar.');
    } else if (sh && sh.appops && sh.appops !== 'permitido' && sh.appops !== 'primeiro plano'
        && sh.appops !== '?') {
      // O CASO QUE QUATRO RODADAS NÃO CONSEGUIRAM NOMEAR. A permissão está
      // concedida e o AppOps a recusa — é o interruptor de privacidade do
      // sistema, o controle do fabricante (o Auto Blocker da Samsung sobre um
      // app instalado fora da loja) ou o mudo global. Nos três a tela do app diz
      // "permissão concedida" e a captura falha assim mesmo.
      l.push('→ O SISTEMA ESTÁ BLOQUEANDO A GRAVAÇÃO (AppOps: ' + sh.appops + '), mesmo com '
        + 'a permissão concedida. Não adianta reconceder a permissão. Veja: o interruptor '
        + '"Acesso ao microfone" nas configurações rápidas; e, num Samsung, o Bloqueio '
        + 'automático (Auto Blocker) em Segurança e privacidade — ele restringe apps '
        + 'instalados fora da Play Store.');
    } else if (sh && (sh.modo === 2 || sh.modo === 3)) {
      l.push('→ O APARELHO ESTÁ EM CHAMADA (modo ' + sh.modo + '): aí o microfone é da '
        + 'chamada, e esta é a única vez em que a frase antiga estava certa.');
    } else if (sh && sh.mudo === true) {
      l.push('→ O MICROFONE ESTÁ MUDO NO SISTEMA. Não é permissão nem app concorrente.');
    } else if (erros.some((e) => e === 'NotAllowedError' || e === 'SecurityError')) {
      l.push('→ PERMISSÃO: o Android (ou o WebView) negou. Autorize o app em '
        + 'Configurações › Aplicativos › Áudio Visual › Permissões.');
    } else if (disp && disp.length === 0) {
      l.push('→ NENHUMA ENTRADA DE ÁUDIO: não é permissão. O aparelho não está '
        + 'entregando microfone nenhum ao app — veja o interruptor de PRIVACIDADE '
        + '"Acesso ao microfone" nas configurações rápidas.');
    } else if (micUltima.degraus.length >= 3 && erros.every(Boolean)) {
      l.push('→ TODOS OS DEGRAUS FALHARAM, inclusive o pedido CRU e o pedido pelo ID '
        + 'do dispositivo: o problema não é o processamento de áudio (que é o que a '
        + 'escada contorna), nem a escolha do "default" do navegador. Com a permissão '
        + 'concedida e o dispositivo à vista, quem recusa é o sistema — outro app '
        + 'segurando o microfone, ou política do fabricante.');
    } else {
      // NÃO AFIRMA QUE A ESCADA FOI INTERROMPIDA — ela pode ter rodado inteira no
      // TELÃO e chegado aqui resumida por um bundle antigo. Um veredito errado é
      // pior que veredito nenhum, e este Registro é lido a distância.
      l.push('→ ' + micUltima.degraus.length + ' tentativa(s) registrada(s). Se o número '
        + 'for menor que a escada, ou o erro não era retentável (permissão), ou o '
        + 'operador soltou o botão, ou quem tentou foi um bundle que ainda não '
        + 'reporta os degraus.');
    }
  }
  return 'Microfone (última tentativa)\n' + l.join('\n');
}

function blocoAudio() {
  if (!window.__NATIVE__) return '';
  const tv = lastDisplays[0] || null;
  const linhas = [
    tv ? 'espelhando para "' + (tv.name || 'TV') + '" — o som deste aparelho vai junto'
       : 'nenhuma TV espelhando agora',
  ];
  // E QUEM ESTÁ TOCANDO, que num relato de "o som some" é a primeira pergunta.
  // Com o telão no chão a preview volta a ser a caixa de som (shell 59) — o que
  // no espelhamento continua chegando à TV, porque o `REMOTE_SUBMIX` leva a
  // mistura do aparelho inteiro. Sem esta linha, "com TV conectada este aparelho
  // fica mudo" descreveria um estado que deixou de ser o único.
  if (tv) {
    linhas.push(tv.telao
      ? 'o telão está no ar: quem toca é a Presentation, este aparelho está mudo'
      : 'O TELÃO NÃO ESTÁ NO AR: quem toca é a preview deste aparelho');
  }
  // AS SEIS LINHAS DE PROSA SÓ SAEM COM TV NO AR. Elas explicam uma
  // consequência do espelhamento, e saíam em toda cópia — inclusive nas de um
  // aparelho que nunca espelhou, onde não respondem pergunta nenhuma e empurram
  // para baixo o que responde. Quem lê um Registro SEM espelhamento não está
  // investigando vazamento de áudio; quem está, tem a TV no ar e recebe tudo.
  if (tv) {
    linhas.push(
      'o espelhamento carrega a mistura de MÍDIA do aparelho: vídeo ou áudio',
      '  tocado em qualquer app sai nas caixas junto com a projeção.',
      'toque de chamada e alarme ficam no celular; notificação depende do aparelho.',
      'não há como isolar: o Android roteia áudio por APARELHO, não por tela — a',
      '  Presentation isola a janela, nunca o som. Não é ajuste que falta.',
      'sem vazamento: "Conectar um computador" (a tela toca o arquivo dela),',
      '  com o espelhamento DESLIGADO — os dois juntos mantêm a mistura no ar.');
  }
  // O MICROFONE, e ONDE ELE SAI. É a pergunta que o operador faz depois de
  // segurar o botão e não ouvir nada, e ela tem duas respostas opostas conforme
  // a TV — sem ela não há telão, e sem telão não há captura em lugar nenhum.
  // As telas da rede NÃO substituem o telão nisto: elas rodam em `http://`, onde
  // `getUserMedia` não existe, e o `setMic` delas sai na guarda de papel.
  if (tv) {
    linhas.push('microfone: capta no telão e sai junto com a mídia, nas caixas da TV.');
  } else {
    linhas.push('microfone: INDISPONÍVEL sem TV — quem capta é o telão, e sem TV',
      '  não há telão. As telas da rede não captam som (o navegador delas não',
      '  entrega microfone em http://).');
  }
  // O PLACAR DA RETOMADA entra AQUI, e não num bloco próprio: ele responde à
  // mesma pergunta deste — o que outro app fez com o som deste aparelho. As
  // "espontâneas" são o censo (quantas vezes o telão parou sem ninguém pedir),
  // e o par recuperadas/desistidas diz se o socorro funcionou.
  const r = diagRetomada;
  if (r) {
    linhas.push('outro app pausou o telão: ' + (r.espontaneas || 0) + 'x'
      + ' · retomado ' + (r.recuperadas || 0) + 'x'
      + ' · desistido ' + (r.desistidas || 0) + 'x');
  }
  return 'Áudio do aparelho\n' + linhas.join('\n');
}

async function renderDiag() {
  const meu = ++diagSeq;
  // O ESTADO DA PROCURA antes de montar o cabeçalho, que o lê (shell 31+). É a
  // única linha do bloco que precisa ir à ponte, e ela é barata: uma string.
  if (window.__NATIVE__) {
    try { otaDiagTexto = await AVNative.otaDiag(); } catch (_) { otaDiagTexto = ''; }
    if (meu !== diagSeq) return;
    // O FAROL na mesma ida: duas leituras de preferência, sem rede.
    try { farolDiag = await AVNative.farolEstado(); } catch (_) { farolDiag = null; }
    if (meu !== diagSeq) return;
  }
  const blocos = [cabecalhoDiag()];
  // A LINHA DO TEMPO VEM EM SEGUNDO, logo depois do cabeçalho, e essa posição é
  // o recurso (v1.1.19). Ela era o ÚLTIMO bloco — depois da extração do
  // YouTube, da cifra, da transmissão, do espelho, do áudio, das Séries e do
  // sorteio —, e "por último, atrás de sete blocos de verificação" é a
  // definição operacional de ENTERRADO: num Registro real ela começava na linha
  // ~150. É ela que responde "o que aconteceu no culto?", que é a pergunta que
  // faz alguém copiar isto; os outros blocos respondem "por que ESTE recurso se
  // comportou assim?", que só se pergunta depois de saber o que aconteceu.
  //
  // Ela é montada AQUI mas só ganha as linhas do telão quando o `diag-ask`
  // responde — e é por isso que o `renderDiag` roda DUAS vezes ao abrir a folha
  // (ver a guarda de sequência). A ordem dos blocos não muda entre as duas.
  blocos.push(eventosDiag());
  // A ÚLTIMA EXTRAÇÃO DO YOUTUBE vinha numa faixa do rodapé, em espaço fixo:
  // uma extração com várias tentativas transbordava e a parte de baixo ficava
  // inalcançável. Aqui ela é só mais um bloco de uma caixa que rola.
  if (window.__NATIVE__) {
    let yt = '';
    try { yt = await AVNative.ytDiag(); } catch (_) {}
    if (yt) blocos.push('Última extração do YouTube\n' + yt);
  }
  // A CIFRA — as DUAS metades, porque elas falham em lugares diferentes e uma
  // sozinha não diz nada.
  //
  //  - a metade do SHELL (`cifraDiag`) responde "a requisição saiu e o que
  //    voltou?" — status, tamanho, host recusado;
  //  - a metade do WEB (`cifraUltimoDiag`) responde "que ENDEREÇOS eu tentei, e
  //    o que o parser entendeu de cada um?".
  //
  // O caso que só as duas juntas resolvem é o pior deles: `HTTP 200` na
  // primeira linha e `ilegivel` na segunda significa que o site mudou de
  // marcação — a página está lá, a rede está boa, e o `cifra.js` é que precisa
  // de um lote novo. Sem a segunda metade isso é indistinguível de "a música
  // não existe no site", e ninguém investigaria.
  if (window.__NATIVE__) {
    let cd = '';
    try { cd = await AVNative.cifraDiag(); } catch (_) { cd = ''; }
    if (meu !== diagSeq) return;
    const linhas = [];
    if (cifraUltimoDiag) linhas.push(cifraUltimoDiag);
    if (cd) linhas.push('shell: ' + cd);
    // O QUE ESTÁ GUARDADO, POR HINÁRIO. Responde "a folha vai abrir sem rede no
    // sábado?" — a pergunta que o download das cifras existe para responder, e a
    // única que nem a linha de tentativas nem o status do shell alcançam.
    // A PERGUNTA BARATA VEM ANTES DO TRABALHO CARO, e o filtro é o MESMO do
    // `syncCifrasAcervo`: quem não tem nada baixado não é varrido, logo não tem
    // o que relatar. `cifraGuardavel` vale para todo acervo de música desde a
    // v1.2.14 e `allCollections()` traz o catálogo INTEIRO do LouvorJA, baixado
    // ou não — ler `cifras:<id>` e varrer `collSongs` de cada um para descartar
    // tudo no `countDownloaded` logo abaixo custava dezenas de leituras de
    // IndexedDB jogadas fora por abertura de Configurações (e `pedirDiag` chama
    // `renderDiag` DUAS vezes), e enchia o bloco de linhas "nada baixado"
    // idênticas — o ruído que os blocos das Séries já tiveram de resumir.
    const cifraSemNada = allCollections().filter((c) => cifraGuardavel(c) && !countDownloaded(c.id));
    for (const c of allCollections().filter((c) => cifraGuardavel(c) && countDownloaded(c.id) > 0)) {
      let n = 0;
      let semCifra = 0;
      let naoAchei = 0;
      // OS NOMES QUE FALTARAM, e SÓ nos hinários (v1.2.15). Ali o endereço é
      // deduzível e toda música existe no site: um "não achei" é a NOSSA regra
      // de slug errando, e é conserto de uma linha no `cifra.js`. Num álbum a
      // ausência é o caso normal (MEDIDO: 35% de acerto), e listar 383 nomes
      // enterraria o Registro sem dizer nada que o número já não diga.
      const faltando = [];
      let porVarrer = 0;
      const total = collSongs(c.id).length;
      try {
        // AS TRÊS CONTAS SÃO SEPARADAS de propósito: uma cifra guardada é uma
        // folha que abre sem rede; um `semCifra` é o site respondendo que a
        // página está lá e a cifra não; um `naoTem` é nenhum endereço ter a
        // página — e este último VENCE em 30 dias, então nem é resposta final.
        // Somá-los faria o número prometer folhas que não existem.
        //
        // E QUEM DIZ SE UMA ENTRADA AINDA VALE É `cifraNoDiscoVale`, a MESMA
        // função com que `syncCifrasColecao` monta a fila. Contar "resolvida"
        // por fora era uma SEGUNDA OPINIÃO, e ela passava a discordar do
        // aparelho no 31º dia: a ausência vence, volta para a varredura, e
        // seguia somada como resolvida — o Registro dizia "0 por varrer" com
        // centenas ainda por refazer. É o pior artefato que este projeto sabe
        // produzir: um log que discorda do aparelho, lido A DISTÂNCIA.
        //
        // E o laço é sobre as MÚSICAS DO ÍNDICE, não sobre as chaves do disco:
        // o "de N" fala do acervo, e uma música que saiu do álbum deixa a
        // entrada dela no mapa — somá-la dava mais resolvidas que o total.
        const guardado = (await AVDB.getState('cifras:' + c.id)) || {};
        const agora = Date.now();
        for (const s of collSongs(c.id)) {
          const k = cifraChaveNoDisco(s.name);
          const v = k ? guardado[k] : null;
          if (!cifraNoDiscoVale(v, agora)) { porVarrer++; continue; }
          if (v.pagina) n++;
          // `soLetra` é a forma ANTIGA da mesma entrada — ver `cifraProcurar`.
          else if (v.semCifra || v.soLetra) semCifra++;
          else { naoAchei++; if (cifraDeduzivel(c)) faltando.push(k); }
        }
      } catch (_) { n = 0; semCifra = 0; naoAchei = 0; porVarrer = 0; }
      linhas.push(c.name + ': ' + n + ' de ' + total + ' cifra(s) no aparelho'
        + (semCifra ? ' · ' + semCifra + ' sem cifra no site' : '')
        + (naoAchei ? ' · ' + naoAchei + ' não achei (repergunto em 30 dias)' : '')
        + (porVarrer ? ' · ' + porVarrer + ' por varrer' : ''));
      // A ÚLTIMA PASSADA, quando ela teve algo a dizer. É a linha que faltava
      // para "N por varrer" deixar de ser um mistério que volta toda sessão:
      // ela diz quantas foram tentadas e o que cada desfecho respondeu.
      let passada = null;
      try { passada = await AVDB.getState(cifraPassadaChave(c.id)); } catch (_) { passada = null; }
      if (passada && (passada.exemplos || []).length) {
        linhas.push('    última passada (' + new Date(passada.em || 0).toLocaleDateString('pt-BR')
          + '): ' + passada.tentadas + ' tentada(s), ' + passada.ok + ' achada(s), '
          + (passada.semCifra || 0) + ' sem cifra no site, '
          + (passada.naoTem || 0) + ' sem página.');
      }
      // OS EXEMPLOS, COM O ENDEREÇO — é isto que permite abrir a página no
      // navegador e ver o que ela é. Um nome sozinho não serve: o que se quer
      // saber é se o endereço está errado ou se a leitura é que está.
      for (const e of (passada && passada.exemplos) || []) {
        linhas.push('      ' + e.nome + ' → ' + e.motivo + (e.url ? '  ' + e.url : ''));
      }
      // E os nomes do que ficou GUARDADO como ausente, com teto — o CORTE É
      // DITO, como em todo bloco deste Registro.
      if (faltando.length) {
        linhas.push('    não achei: ' + faltando.slice(0, CIFRA_FALTANDO_MAX).join(' · ')
          + (faltando.length > CIFRA_FALTANDO_MAX
            ? ' … e mais ' + (faltando.length - CIFRA_FALTANDO_MAX) : ''));
      }
    }
    // NÃO BAIXADO É OUTRA RESPOSTA, não um zero — mas ela cabe em UMA linha. A
    // frase nasceu (v1.2.15) quando o laço via só os DOIS hinários, para
    // responder à pergunta do operador sobre o de 1996: um "0 de 613" seco se lê
    // como recurso quebrado. Por isso os do CATÁLOGO (`cifraDeduzivel`) saem
    // nominais e os álbuns entram só no número — o Registro é RESUMO, não
    // listagem, e nenhum corte aqui é silencioso: o que sai continua contado.
    if (cifraSemNada.length) {
      const nominais = cifraSemNada.filter(cifraDeduzivel).map((c) => c.name);
      linhas.push(cifraSemNada.length
        + ' coleção(ões) sem nada baixado — as cifras delas não são buscadas'
        + (nominais.length ? ': ' + nominais.join(' · ') : ''));
    }
    if (linhas.length) blocos.push('Cifra (última busca)\n' + linhas.join('\n'));
    // A ESTRUTURA da última página que o parser NÃO entendeu — bloco à parte
    // porque responde outra pergunta. As duas linhas acima dizem "tentei estes
    // endereços e não entendi"; esta diz O QUE a página era, que é o que permite
    // ajustar a regra sem ter a página na frente. Só FORMA: contagens, tamanhos
    // e endereços. Nenhum pedaço de letra ou de acorde sai daqui — um Registro
    // é feito para ser copiado para fora, e o contrato deste recurso é ler
    // conteúdo de terceiro no aparelho, nunca distribuí-lo.
    if (cifraEstruturas.length) {
      blocos.push('Cifra (estrutura das páginas que não abriram)\n'
        + cifraEstruturas.map((e) => e.texto).join('\n'));
    }

  }
  // O lado WEB da última tentativa de transmitir. Ele vem à parte do
  // diagnóstico do shell porque três dos cinco pontos de desistência acontecem
  // antes de a ponte ser chamada — ali o Kotlin não tem o que dizer.
  if (motivoStream) {
    // O erro de REPRODUÇÃO entra junto, e é o que faltava: a v5.123 mostrava
    // "transmitindo 1080p" — a decisão — e nada sobre o vídeo ter morrido no
    // segundo zero logo depois. Decidir e conseguir são duas coisas.
    const falha = (window.AVStream && window.AVStream.ultimoErro) || '';
    // E QUANTAS VEZES ELA FICOU SEM DADOS. Relato do operador: *"veio som, porém
    // ficou travando e qualidade de vídeo baixa"* — e a resposta possível era um
    // palpite ("deve ser a estabilidade da internet"), porque um `<video>` que
    // trava por rede e um app quebrado produzem a MESMA tela. O censo é do
    // `stage.js`, e vem em DOIS números: episódios e segundos parados. Dois
    // travamentos de meio segundo é uma rede que oscila; dez de cinco segundos é
    // uma rede que não sustenta a faixa escolhida — e a segunda tem resposta
    // (baixar em vez de transmitir), a primeira não.
    //
    // SÓ APARECE DEPOIS DE ACONTECER: a ausência da linha é "não travou", e uma
    // linha com zeros seria mais uma para o operador ler em toda cópia.
    // O DEGRAU, quando a medição desceu um. Sem esta linha o Registro diria
    // "transmitindo 1080p" (a decisão do shell) sobre uma cena que está em 720p
    // — a divergência que este projeto chama de log que discorda do aparelho.
    const deg = (window.AVStream && window.AVStream.degrau) || '';
    const banda = (window.AVStream && window.AVStream.banda) || 0;
    const linhaDeg = deg
      ? '\na rede mediu ' + Math.round(banda / 1000) + ' kbps e o app DESCEU para ' + deg
      : (banda ? '\na rede mediu ' + Math.round(banda / 1000) + ' kbps (coube no teto)' : '');
    const fome = (window.AVStream && window.AVStream.fome) || null;
    // "NESTA SESSÃO" está escrito porque o censo é CUMULATIVO e o título do
    // bloco diz "último Tocar agora": sem a palavra, um número de cinco
    // travamentos seria lido como cinco naquele vídeo.
    const parou = fome && fome.quantas
      ? '\nficou sem dados ' + fome.quantas + '\u00d7 nesta sessão ('
        + fome.segundos + 's parada no total)'
      : '';
    // O CENSO DA SESSÃO, e ele responde a pergunta que as linhas acima não
    // respondem: elas descrevem a ÚLTIMA vez, e numa falha intermitente o que
    // importa é a proporção. Só sai quando houve pedido — num Registro tirado
    // antes de tocar qualquer coisa, "0 de 0" é ruído.
    //
    // Os dois moram DENTRO do `if (motivoStream)`, e isso não deixa contagem
    // órfã: todo caminho que pode avisar qualidade limitada passa antes por
    // `tentarTransmitir` (o "Tocar agora", o item de link e o share), e ele
    // escreve o `motivoStream` em toda saída. O download que NÃO passa por ali
    // é o que guarda numa lista, e esse não avisa (ver `aviso === 'preview'`).
    const censo = ytCenso.pedidos
      ? '\nnesta sessão: ' + ytCenso.pedidos + ' pedido(s) de transmissão · '
        + ytCenso.transmitiu + ' transmitiu(ram) · '
        + (ytCenso.pedidos - ytCenso.transmitiu) + ' caiu(ram) no download'
      : '';
    // A qualidade limitada é contada à parte porque ela NÃO é a mesma pergunta:
    // um pedido pode transmitir e ainda assim sair abaixo do pedido. O MENOR
    // valor vai junto — é ele que diz se foi um degrau ou o fundo do poço.
    const limitadas = ytCenso.limitadas
      ? '\ne ' + ytCenso.limitadas + '\u00d7 a projeção saiu em qualidade limitada'
        + (ytCenso.menor ? ' (a menor: ' + ytCenso.menor + 'p)' : '')
      : '';
    blocos.push('Transmissão direta (último "Tocar agora")\n' + motivoStream
      + linhaDeg + parou + censo + limitadas
      + (falha ? '\nfalhou ao tocar: ' + falha : ''));
  }
  // A TRANSMISSÃO PARA NAVEGADOR: mais um BLOCO desta caixa, nunca uma faixa
  // nova em outro canto (regra do projeto). É o único lugar em que o estado do
  // servidor e das telas pareadas pode ser LIDO e REPASSADO — e o botão
  // de copiar, que já está no cabeçalho do Registro, os leva junto.
  if (espelhoDisponivel()) {
    let ed = null;
    try { ed = await AVNative.espelhoDiag(); } catch (_) { ed = null; }
    if (meu !== diagSeq) return;
    const bloco = blocoEspelho(ed);
    if (bloco) blocos.push(bloco);
  }
  // O ÁUDIO DO APARELHO — logo depois do estado da transmissão, porque responde
  // à mesma pergunta ("o que está no ar?") pelo lado que ninguém escolheu.
  const ba = blocoAudio();
  if (ba) blocos.push(ba);
  // DEPOIS do áudio, e não antes: aquele responde "onde a voz sai", este
  // responde "por que ela não saiu". Só o segundo é condicional a ter havido
  // tentativa, então ele é o que pode faltar.
  const bm = blocoMicrofone();
  if (bm) blocos.push(bm);
  // AS SÉRIES: o que a regra achou nos canais, com os nomes CRUS. Ele vem
  // depois do estado da transmissão e antes da linha do tempo porque a ordem
  // desta caixa é "quem eu sou → o que tentei → o que está no ar → o que
  // aconteceu": este bloco responde à segunda pergunta.
  const bs = await blocoSeries();
  if (meu !== diagSeq) return;
  if (bs) blocos.push(bs);
  // A PLAYLIST AUTOMÁTICA, ao lado das séries: os dois blocos respondem à mesma
  // pergunta ("o que a regra achou, e por que recusou o resto?") e o operador
  // que abre o Registro depois de um sorteio estranho procura os dois juntos.
  const bso = blocoSorteio();
  if (bso) blocos.push(bso);
  // AS COLETÂNEAS, ao lado das duas acima e pela mesma razão: as três respondem
  // "o que a regra achou, e por que recusou o resto?". Esta é a única que
  // decide o que a Biblioteca MOSTRA, então ela vai por último das três — quem
  // abre o Registro por causa de uma coletânea que sumiu a encontra no fim de
  // um bloco curto, e não no meio de oitenta linhas de playlist.
  const bcol = blocoColetaneas();
  if (bcol) blocos.push(bcol);
  if (meu !== diagSeq) return;   // outro render assumiu durante a espera
  // O TEXTO MORA NA VARIÁVEL, e não num nó do DOM (v5.207). O visor `<pre>`
  // saiu de Configurações — ver o comentário do bloco no `index.html`: ele
  // gastava 240px de espaço sempre visível para exibir, em fonte de 0,68rem,
  // um log cujo consumidor é um humano a distância. Quem o leva até lá é o
  // botão de copiar, e é `diagTexto` que ele copia.
  diagTexto = blocos.join('\n\n');
}
// Junta os dois anéis em ORDEM DE RELÓGIO: celular e telão são dois processos
// da mesma cena, e o que interessa é a sequência entre eles — "o celular ficou
// oculto e ENTÃO o telão pausou" é uma história diferente de "o telão pausou
// sozinho".
// OS CONTADORES DA RETOMADA, vindos do telão no mesmo `diag-dump` das linhas.
// Eles existem porque o anel do diário tem 60 linhas e um culto não cabe nele:
// a pergunta que importa é "quantas vezes o telão precisou ser socorrido?", e só
// um número a responde. `null` = este telão é de um bundle que ainda não os
// manda, e aí a linha não aparece — nunca "undefined" num log que vai ser
// repassado (regra do projeto: toda linha do bloco é opcional).
let diagRetomada = null;
function juntarDiag(doTelao, retomada) {
  // GUARDA O QUE VEIO DO TELÃO; a JUNÇÃO acontece na hora de desenhar.
  //
  // Antes esta função montava `diagLinhas` e pronto — e como ela só roda quando
  // o telão RESPONDE ao `diag-ask`, a linha do tempo era um instantâneo daquele
  // momento. Todo evento do celular registrado depois dele ficava invisível, e
  // SEM TELÃO NENHUM ela congelava de vez: o `diag-ask` não chega a sair, então
  // a última junção era a de quando havia telão, horas antes.
  //
  // MEDIDO num Registro real: a linha do tempo terminava às 09:35:51, no
  // instante em que a TV caiu, e o operador copiou o texto muito depois — com
  // três tentativas de microfone no meio, nenhuma delas na lista. O bloco que
  // existe para responder "o que aconteceu no culto?" parava de responder
  // exatamente quando o culto continuava.
  diagDoTelao = doTelao || [];
  if (retomada && typeof retomada === 'object') diagRetomada = retomada;
  renderDiag();
}
function pedirDiag() {
  // OS CONTADORES MORREM COM O TELÃO, como as linhas dele. Sem esta linha, o
  // bloco "Áudio do aparelho" seguia imprimindo o placar de uma Presentation
  // que já caiu — e o `diag-ask` nem chega a sair sem telão ativo, então o
  // número velho ficava para sempre, ao lado de uma linha do tempo sem um
  // único 📺. Um diagnóstico que responde errado é pior que um que não
  // responde.
  diagRetomada = null;
  juntarDiag([]);
  if (displayActive()) AVDB.sendCommand({ type: 'diag-ask' });
}

// COPIAR UM CAMPO DE LOG. Regra do projeto: todo campo de diagnóstico nasce com
// este botão — ele existe para ser repassado, e a alternativa é transcrever
// números à mão ou fotografar a tela.
//
// `navigator.clipboard` exige contexto seguro, e o app tem um (a base é servida
// por `https://appassets.androidplatform.net`) — mas o WebView pode negar a
// permissão sem aviso, então o caminho antigo (`execCommand`) fica como reserva.
// A confirmação é o mesmo pulso do resto do app: o ícone vira ✓ por um instante.
//
// Ela viveu no meio do bloco do diagnóstico do YouTube até a v5.121, e por isso
// foi APAGADA junto quando aquele bloco saiu — o botão do registro passou a
// chamar uma função inexistente e não fazia nada. Um helper compartilhado
// morando dentro do escopo visual de um único consumidor é um convite a isso;
// agora ele fica ao lado de quem o usa e com o nome do que é.
async function copiarTexto(texto, btn) {
  let ok = false;
  try {
    await navigator.clipboard.writeText(texto);
    ok = true;
  } catch (_) {
    try {
      const ta = document.createElement('textarea');
      ta.value = texto;
      // Fora da vista, mas NÃO `display:none` nem `hidden`: um campo que não
      // está no layout não pode ser selecionado, e sem seleção o `copy` copia
      // nada — em silêncio.
      ta.style.cssText = 'position:fixed;left:-9999px;top:0;opacity:0';
      document.body.appendChild(ta);
      ta.select();
      ok = document.execCommand('copy');
      ta.remove();
    } catch (__) { ok = false; }
  }
  if (btn) responder(btn, ok ? 'ok' : 'erro', ok ? null : 'Não foi possível copiar');
  return ok;
}

// (O BOTÃO DE COPIAR O REGISTRO SAIU na v1.4.44, a pedido do operador: *"pode
//  remover o sistema de copiar registro. o registro está cada vez maior e mais
//  completo e acaba por ele ficar longo de mais para compartilhar via chat de
//  texto"*. A área de transferência era o caminho que CORTA o texto no meio sem
//  avisar — foi esse relato que criou o salvar em arquivo na v1.2.16 —, e o
//  Registro só cresceu desde então. Ficou a porta que não corta.)
//
// O ENDEREÇO DA TRANSMISSÃO continua se copiando, e agora é o ÚNICO consumidor
// do `copiarTexto`. Ele é o caso em que a área de transferência é a ferramenta
// certa: é curto e existe para ser digitado noutro aparelho. Lido do NÓ e não
// de uma variável à parte: quem o escreve é `mirrorEstado`, a cada volta da
// enquete, e uma segunda cópia guardada aqui ficaria para trás no dia em que o
// IP mudasse (o Wi-Fi caindo e voltando é o caso normal).
if (castUrlCopyEl) {
  castUrlCopyEl.addEventListener('click', () => {
    const url = (castUrlEl && castUrlEl.textContent || '').trim();
    if (url) copiarTexto(url, castUrlCopyEl);
  });
}


/**
 * O REGISTRO EM ARQUIVO (v1.2.16).
 *
 * Copiar e colar é o caminho que CORTA o texto no meio sem avisar, e com o
 * acervo inteiro varrido o Registro passou de setenta linhas só na seção de
 * cifras. Um arquivo não corta — e ainda fica no aparelho para ser anexado
 * depois, que é o que o operador de fato faz com ele.
 *
 * O nome carrega a DATA, porque o valor de um Registro é comparar dois: dois
 * arquivos com o mesmo nome viram "registro (1).txt" na pasta e ninguém sabe
 * qual é qual uma semana depois.
 *
 * Só no app: gravar arquivo é `AVNative.salvarTexto` (SAF), e no navegador não
 * há ponte — o botão nasce `hidden` e quem o revela é o `renderVersionLabel`.
 */
if (diagSaveEl) {
  // SÓ NO APP: gravar arquivo é a ponte (SAF), e no navegador um botão que só
  // sabe não funcionar é pior que botão nenhum.
  //
  // Revelado AQUI, e não no `renderVersionLabel` — que seria o lugar natural,
  // e é uma ZONA MORTA TEMPORAL: aquela função roda no topo do arquivo e este
  // `const` só existe centenas de linhas abaixo. O `ReferenceError` aborta o
  // `controle.js` inteiro, e o watchdog do OTA rejeita o bundle sem que nada
  // na tela diga por quê. Medido: o app não subiu.
  diagSaveEl.hidden = !window.__NATIVE__;
  // O RÓTULO VIAJA COM O BOTÃO (v1.4.44). Com o copiar fora, ele é o único
  // alvo da faixa: uma palavra sozinha, sem nada ao lado, é um controle que
  // não existe — e num navegador o Registro não tem como sair do rodapé.
  if (diagRotEl) diagRotEl.hidden = !window.__NATIVE__;
  diagSaveEl.addEventListener('click', async () => {
    if (!window.__NATIVE__) return;
    const d = new Date();
    const p2 = (n) => String(n).padStart(2, '0');
    const nome = 'registro-av-' + d.getFullYear() + p2(d.getMonth() + 1) + p2(d.getDate())
      + '-' + p2(d.getHours()) + p2(d.getMinutes()) + '.txt';
    let salvo = '';
    try { salvo = await AVNative.salvarTexto(nome, diagTexto); } catch (_) { salvo = ''; }
    // VAZIO É "desistiu OU não deu", e a diferença não existe para quem opera:
    // nos dois casos não há arquivo, e o botão continua ali para tentar de novo.
    responder(diagSaveEl, salvo ? 'ok' : 'erro', salvo ? null : 'Não foi salvo');
  });
}

// ===== PINTAR UM TILE DO PAINEL RÁPIDO (v1.4.38) =====
//
// Um ponto só escreve as QUATRO coisas que um tile mostra, e é isso que impede
// que elas divirjam: o `data-estado` (o valor em vigor — é por ele que os
// oráculos perguntam, e nunca pela classe, que é aparência), a palavra do
// estado, o desenho e o aceso.
//
// `aceso` E `alt` SÃO DUAS PERGUNTAS, e não uma (v1.4.40). `aceso` é *"a função
// está ligada?"* — e num tile que não tem "desligado" (tema, preenchimento,
// wallpaper, histórico) ele é SEMPRE verdadeiro, porque apagado ali quer dizer
// INDISPONÍVEL, que é a queixa da v1.4.25 aplicada a este painel. `alt` é
// *"qual dos dois desenhos?"*. Enquanto as duas foram a mesma classe, um tile
// sempre aceso ficava preso no desenho alternativo para sempre.
// Ver as três regras do tile no `index.html`.
function pintarTile(el, estado, rotulo, aceso, alt) {
  if (!el) return;
  el.dataset.estado = String(estado);
  const alvo = el.querySelector('.qs-estado');
  if (alvo) alvo.textContent = rotulo;
  el.classList.toggle('qs-on', !!aceso);
  el.classList.toggle('qs-alt', !!alt);
}

// SEMPRE ACESO: escolher "Ajustar" não desliga nada — é a outra metade de um
// par, e as duas são igualmente uma escolha em vigor. Quem diz QUAL é o desenho
// mais a palavra.
function renderFitTile() {
  pintarTile(fitTileEl, mediaFit, mediaFit === 'cover' ? 'Preencher' : 'Ajustar',
    true, mediaFit === 'cover');
}
// O WALLPAPER TEM UM ÍCONE SÓ — o par de desenhos que distinguiria "padrão" de
// "própria" viraria o `icoImagem` do tile vizinho (ver o comentário do símbolo
// no `index.html`) — e é SEMPRE ACESO: há um wallpaper no telão nos dois
// estados, e "Padrão" não é o recurso desligado. Quem diz qual é a palavra.
function renderWallTile() {
  pintarTile(wallTileEl, customWallpaper ? 'propria' : 'padrao',
    customWallpaper ? 'Própria' : 'Padrão', true, false);
}
async function applyFit(mode) {
  mediaFit = mode;
  renderFitTile();
  await AVDB.setState('fit', mediaFit);
  cmd({ type: 'fit', fit: mediaFit });
}

// ===== GIRAR A MÍDIA (v5.142) =====
//
// Vídeo gravado de lado no celular chega DEITADO no telão. Não havia nada a
// fazer: a mídia é do operador, reencodar no meio de um culto não existe, e
// "grave de pé" não conserta um arquivo já pronto.
//
// UM BOTÃO QUE AVANÇA, não quatro segmentos. Ninguém pensa em "270°" — pensa em
// "gira mais uma vez até ficar de pé", e são no máximo três toques até qualquer
// orientação. O rótulo mostra o ângulo vigente para o estado ser legível sem
// contar toques, e é ele que diz que o giro está ligado quando a mídia em cena
// já está de pé por acaso.
//
// PERSISTIDO como o preenchimento (`state.rotate`), e pelo mesmo motivo: o
// telão pode reconectar, o app pode ser reaberto no meio do culto, e voltar ao
// zero sozinho seria desfazer um ajuste que ninguém pediu para desfazer.
const ROTACOES = [0, 90, 180, 270];
let mediaRot = 0;
function renderRotBtn() {
  // O ÂNGULO É A PALAVRA DO ESTADO deste tile — não há par de ícones para um
  // valor de quatro posições (quatro desenhos que só diferem pelo próprio
  // ângulo não se distinguem a 22px), então quem responde "como está?" é o
  // rótulo, e o aceso diz que o giro não está no padrão.
  pintarTile(rotBtnEl, mediaRot, mediaRot + '°', mediaRot !== 0, false);
  if (rotBtnEl) {
    // A FRASE DIZ ONDE, nas duas pontas: o rótulo do tile já diz "no telão", e
    // o `title` fecha pela negativa — é o app inteiro que NÃO gira.
    rotBtnEl.title = mediaRot
      ? 'A mídia está girada ' + mediaRot + '° no telão — tocar gira mais 90°'
      : 'Girar a mídia no telão — não gira o app nem a tela do celular';
  }
  // ---- E O DESFAZER APARECE NA PREVIEW (v1.4.43) ----
  // Quem o mostra é o render do ESTADO que ele desfaz, e não um render próprio:
  // é a única disciplina que impede o botão de sobreviver ao fato que ele
  // nomeia — `applyRotate` passa por aqui SEMPRE, inclusive na carga (`load`) e
  // na volta ao padrão que o próprio botão dispara.
  if (pvGiroBtnEl) {
    pvGiroBtnEl.hidden = !mediaRot;
    if (pvGiroNumEl) pvGiroNumEl.textContent = mediaRot + '°';
    // O ÂNGULO é o estado (está no número, à vista); o `title` é a AÇÃO — a
    // mesma divisão dos botões da notificação de mídia. Sem ele o ícone de
    // girar sobre a projeção se leria como "girar mais 90°".
    pvGiroBtnEl.title = 'A mídia está girada ' + mediaRot
      + '° no telão — tocar volta à posição padrão';
    pvGiroBtnEl.setAttribute('aria-label', pvGiroBtnEl.title);
  }
}
async function applyRotate(graus) {
  mediaRot = ((graus | 0) % 360 + 360) % 360;
  if (!ROTACOES.includes(mediaRot)) mediaRot = 0;
  renderRotBtn();
  await AVDB.setState('rotate', mediaRot);
  cmd({ type: 'rotate', rotate: mediaRot });
}

// ===== URL / compartilhamento =====
function extractYouTubeId(url) {
  // Extrai apenas a parte http://... sem espaços ou texto extra
  const cleanUrl = (url || '').match(/https?:\/\/\S+/);
  if (!cleanUrl) return null;
  try {
    const u = new URL(cleanUrl[0]);
    let id = null;
    if (u.hostname === 'youtu.be') {
      id = u.pathname.slice(1).split('/')[0];
    } else if (u.hostname.includes('youtube.com')) {
      // watch?v=ID e também /shorts/ID, /live/ID, /embed/ID, /v/ID
      id = u.searchParams.get('v');
      if (!id) {
        const m = u.pathname.match(/^\/(?:shorts|live|embed|v)\/([^/?#]+)/);
        if (m) id = m[1];
      }
    }
    if (id) id = decodeURIComponent(id);
    // Valida formato de ID do YouTube: exatamente 11 chars [A-Za-z0-9_-]
    return (id && /^[A-Za-z0-9_-]{11}$/.test(id)) ? id : null;
  } catch (_) {}
  return null;
}

function detectUrlKind(url) {
  if (extractYouTubeId(url)) return 'youtube';
  const lower = url.toLowerCase().split('?')[0];
  const ext = (lower.split('.').pop() || '');
  const mime = MEDIA_MIME[ext];
  // MEDIA_MIME só contém extensões de image/video/audio → kindFromType nunca
  // devolve 'other' aqui; extensão desconhecida (sem mime) vira 'url'.
  return mime ? AVDB.kindFromType(mime) : 'url';
}

// ===== A via NATIVA: o aparelho extrai e baixa o vídeo sozinho =====
//
// É o caminho principal desde a v5.81, e o que finalmente cumpre "sem
// configurar nada": quem extrai é o shell (`YoutubeGrab.kt`), com a
// requisição saindo do IP do próprio celular. Servidor público — Cobalt,
// Invidious, Piped — roda em IP de datacenter, que é exatamente o que o
// YouTube bloqueia; foi por isso que a via anterior não funcionou, e é por isso
// que ela saiu do app na v5.82 em vez de ficar como alternativa morta.
//
// O nativo entrega uma URL SERVÍVEL (`/saf/<token>`), não bytes: daqui para a
// frente o caminho é o mesmo de um arquivo compartilhado — `fetch` + `Blob` +
// `addMedia`. O arquivo intermediário é apagado logo depois; sem isso o vídeo
// ficaria duas vezes no aparelho.
//
// Exige shell ≥ 16. Num anterior o método não existe e a função devolve null
// na hora, sem custo: o link vira item de player embutido, que é o
// comportamento de sempre e continua sendo o plano B.
// `opts.naPreview` decide ONDE o aviso aparece — e a pergunta que ele responde
// é "isto vai entrar em cena a seguir?". Tocar: sim, o cartão vai sobre a
// preview. Só entrar na lista: não, o aviso vai na linha do Cronograma, que é
// onde o resultado vai aparecer. Ver `libBusy`.
async function ytBaixarNativo(link, nome, opts) {
  if (!window.__NATIVE__) return null;
  // SÓ O ÁUDIO exige shell ≥ 23 (o método `ytFetchAudio` da ponte). Num
  // anterior, pedir áudio devolveria null e o operador ficaria sem nada — e ele
  // pediu o louvor, não o formato: cai no vídeo, que toca igual. Quem desenha a
  // escolha na tela já a esconde nesse shell (ver `openYtMenu`); esta guarda é
  // para o caminho que não passa pela tela.
  const soAudio = !!(opts && opts.somenteAudio);
  // O TETO DE RESOLUÇÃO escolhido pelo operador (v5.118). Ausente = o padrão do
  // shell (1080p), que é o caminho que funciona em qualquer versão: o `ytFetch`
  // do `native.js` só usa o método novo da ponte quando o teto pedido é MENOR
  // que o padrão. Nenhuma guarda de shell aqui, portanto — quem não pode
  // escolher simplesmente não escolhe, e baixa como sempre.
  const altura = (opts && opts.altura) | 0;
  // O nome CRU de quem pediu, sem o genérico: é ele que decide o nome do
  // registro (ver o `addMedia` lá embaixo), e ali um genérico venceria o título
  // de verdade. O `rotulo` é a mesma coisa já pronta para APARECER, onde uma
  // string vazia não serve.
  const rotulo = nome || 'Vídeo do YouTube';
  const rotuloBaixando = soAudio ? 'Baixando áudio' : 'Baixando vídeo';
  const naPreview = !!(opts && opts.naPreview);
  // Três destinos de aviso, não dois. O terceiro (`aviso: 'nenhum'`) é a
  // playlist: ela mora dentro de uma bandeja fechada, então não há linha para
  // marcar — e desenhar a linha provisória no CRONOGRAMA prometeria um item
  // que nunca vai aparecer lá. Ali quem mostra o andamento é a própria linha
  // do resultado (`onPct`) mais a notificação do sistema.
  const aviso = (opts && opts.aviso) || (naPreview ? 'preview' : 'lib');
  // A ALÇA DE CANCELAMENTO (v5.191), entregue a QUEM ESTÁ MOSTRANDO o download.
  //
  // Até aqui só a linha do resultado da busca sabia cancelar — e ela é
  // justamente a que some quando o operador fecha a busca. O cartão sobre a
  // preview e a linha provisória do Cronograma mostravam minutos de download
  // sem oferecer saída nenhuma; a única forma de parar era esperar.
  //
  // `terminado` fecha a janela do fim: um toque no botão depois de o download
  // acabar mandaria ao shell um cancelamento que ficaria armado contra o
  // próximo download do mesmo vídeo.
  let terminado = false;
  let cancelado = false;
  const cancelar = !podeCancelarDownload() ? null : async () => {
    if (cancelado) return;
    const parou = await cancelarDownload({
      link,
      youtubeId: (opts && opts.youtubeId) || null,
      nome: rotulo,
      soAudio,
      aindaVale: () => !terminado && !cancelado,
    });
    if (parou) { cancelado = true; bg.soltar(); }
  };
  const bg = aviso === 'preview'
    ? previewBusy(soAudio ? 'Preparando áudio' : 'Preparando vídeo', rotulo, cancelar)
    : aviso === 'lib' ? libBusy(rotulo, opts && opts.chave, cancelar)
      : { visivel: false, atualizar() {}, soltar() {} };
  const notif = bgTaskStart(rotuloBaixando, 1);
  // O NOME DO VÍDEO na linha da notificação, pela mesma razão do lote de
  // músicas: "Baixando vídeo" sozinho não diz QUAL, e com o app minimizado esta
  // é a única tela que existe. Uma tarefa de um item só nunca chega a trocar de
  // nome, então o compasso não tem o que fazer aqui — vai direto.
  bgItemOnly(notif, rotulo);
  // A INTENÇÃO, GRAVADA ANTES DE COMEÇAR. É o que permite reclamar o download
  // se esta página morrer no meio dele (ver `resgatarDownloads`) — e por isso
  // ela precisa estar no banco ANTES do primeiro byte, não depois.
  await lembrarIntencao({
    link,
    nome: rotulo,
    youtubeId: (opts && opts.youtubeId) || null,
    lista: (opts && opts.lista) || null,
    soAudio,
    altura,
    quando: Date.now(),
    // Quantos resgates este download já custou — o teto que impede uma
    // intenção de voltar a cada abertura (ver `resgatarDownloads`).
    tentativas: (opts && opts.tentativas) | 0,
  });
  try {
    return await withBgWork(async () => {
      const r = await AVNative.ytFetch(link, (lidos, total) => {
        const pct = total ? Math.floor((lidos / total) * 100) : -1;
        bg.atualizar(pct >= 0
          ? rotuloBaixando + ' · ' + pct + '%'
          : rotuloBaixando + ' · ' + fmtBytes(lidos), null, pct);
        // Os MESMOS bytes que a preview já mostrava vão agora para a
        // notificação, que até a v5.117 ficava parada em "0 de 1" (ver
        // `bgTaskBytes`). É a diferença entre uma barra que anda e uma que
        // parece travada durante os minutos inteiros do download.
        bgTaskBytes(notif, lidos, total);
        if (opts && opts.onPct) opts.onPct(pct);
      }, soAudio, altura);
      if (!r || !r.url) return null;
      // CANCELADO NO ÚLTIMO SEGUNDO. O shell para o laço de cópia, mas há uma
      // janela em que ele já terminou de baixar e está juntando as faixas
      // (`MuxMp4`) — e aí o arquivo VEM, depois de o operador ter pedido para
      // parar. Sem esta guarda o item apareceria em cena como se o cancelamento
      // não tivesse acontecido. Os bytes intermediários são descartados aqui
      // mesmo: eles nunca chegaram à biblioteca.
      if (opts && opts.youtubeId && ytCancelados.has(opts.youtubeId)) {
        AVNative.ytDiscard(r.url);
        return null;
      }
      // O shell manda `r.audioOnly` dizendo se a faixa é mesmo só áudio (ver
      // YoutubeGrab.buscar). A UI NÃO usa esse campo: quando o vídeo não
      // oferece faixa separada, o que o operador pediu — tocar no fundo, sem
      // imagem no telão — acontece do mesmo jeito, porque quem manda no telão é
      // o `kind` do registro e não o container do arquivo. Anunciar a diferença
      // seria contar um detalhe de implementação no meio de um culto. Ele
      // continua no JSON porque é o que aparece no `Log.w` de quem for
      // diagnosticar por que um vídeo específico não entregou o áudio.
      try {
        const res = await fetch(r.url);
        if (!res.ok) return null;
        const blob = await res.blob();
        if (!blob.size) return null;
        // SEM MINIATURA quando é só áudio, e isso não é economia: a miniatura
        // de um áudio seria a "capa" que não pode existir. O registro entra com
        // `kind: 'audio'`, e é o kind que faz o telão manter o wallpaper em vez
        // de trocar de imagem (ver `semVisual` em stage.js).
        const thumb = soAudio ? null : await makeThumb(blob, 'video');
        // O AVISO MORA ONDE O RESULTADO VAI APARECER — a régua da v5.84, e ela
        // decide este `if`. `aviso === 'preview'` é o download que vai ENTRAR EM
        // CENA; nos outros destinos o resultado é uma LINHA, e ali a altura já
        // aparece no subtítulo dela ("Vídeo · 360p") sem cartaz nenhum. Um
        // cartão sobre a preview para um vídeo que só está sendo guardado
        // insinuaria que ele vai ao telão a seguir.
        //
        // Vem ANTES do `addMedia` porque a gravação do blob pode demorar, e o
        // cartão que ainda está no ar é o mesmo que vai falar.
        if (!soAudio && aviso === 'preview') avisarResolucaoLimitada(r.height, altura);
        return await AVDB.addMedia(blob, {
          // O sufixo é a MESMA convenção das músicas do acervo, que já se
          // chamam "(Cantado)"/"(Playback)": sem ele, o vídeo e o áudio do
          // mesmo link viram duas linhas com o nome idêntico na lista.
          // O NOME DO APP VENCE O TÍTULO DO YOUTUBE — a mesma regra do
          // `tentarTransmitir`, e os dois caminhos têm de concordar: o mesmo
          // link renomearia o item ou não conforme desse para transmitir.
          // `r.name` aqui é o do SHELL (o `ytFetch` devolve o título extraído);
          // `nome` é o que o app já tem, e é ele que manda. O genérico do
          // `rotulo` fica por último, senão ele venceria o título de verdade
          // quando não temos nome nenhum.
          name: (nome || r.name || rotulo) + (soAudio ? ' (áudio)' : ''),
          type: r.type || (soAudio ? 'audio/mp4' : 'video/mp4'),
          kind: soAudio ? 'audio' : 'video',
          thumb,
          // A ALTURA REAL do que veio, dita pelo shell. Ela vira o subtítulo da
          // linha do Cronograma ("Vídeo · 1080p"), e é a única forma honesta de
          // responder "o que eu tenho aqui?" agora que o teto é escolhido a
          // cada download — inclusive quando o pedido não pôde ser atendido e o
          // que veio foi outra coisa. Descobrir isso depois exigiria decodificar
          // o arquivo.
          height: (r.height | 0) || null,
          // A DURAÇÃO REAL, pelo mesmo argumento e do mesmo lugar (v1.5.21): o
          // shell já a devolvia no `ytFetch` e ela era jogada fora aqui, então
          // um vídeo baixado ficava sem o dado que o áudio ao lado já mostra no
          // subtítulo. Custo zero — nem uma requisição a mais.
          seconds: (r.seconds | 0) || null,
          canal: (opts && opts.canal) || null,
          // O id do vídeo fica GRAVADO no registro: é ele que faz o próximo
          // toque no mesmo resultado reaproveitar este arquivo em vez de
          // baixar tudo de novo (ver `ytArquivo`).
          youtubeId: (opts && opts.youtubeId) || null,
          // E a lista de destino vem de quem pediu: nem todo vídeo baixado
          // pertence ao Cronograma (ver `ytAcao`).
          list: (opts && opts.lista) || 'imports',
        });
      } finally {
        // No `finally`: mesmo que a cópia falhe, o arquivo do cache não pode
        // ficar para trás — ninguém mais tem o token dele.
        AVNative.ytDiscard(r.url);
      }
    });
  } catch (e) {
    console.warn('[yt nativo] falhou:', e && e.message);
    return null;
  } finally {
    terminado = true;
    bgTaskEnd(notif);
    bg.soltar();
    // A INTENÇÃO SAI DO REGISTRO AQUI, e só aqui: chegando neste ponto o
    // download acabou de um jeito ou de outro, e a página está viva para
    // contar. É justamente por ela NÃO chegar aqui — o renderer morreu no meio
    // — que a intenção sobrevive e é reclamada na abertura seguinte (ver
    // `resgatarDownloads`).
    await esquecerIntencao(link, soAudio);
  }
}

// ---------------------------------------------------------------------------
// O DOWNLOAD QUE O RENDERER LEVOU JUNTO (v5.133 · shell 30)
//
// O download roda no shell; quem o espera é um `fetch` DESTA página. Quando o
// renderer morre — dois WebViews, um vídeo grande e o player do YouTube dividem
// o mesmo processo, e o OOM é evento conhecido —, a página é recriada e o
// `fetch` morre com ela: o arquivo termina de baixar e não sobra ninguém para
// recebê-lo. Do lado do operador, dez minutos viram nada, sem explicação.
//
// A recuperação é uma dobradiça de duas metades:
//
// - **O shell guarda o desfecho** até alguém reclamá-lo (`YoutubeGrab.resgatar`).
// - **A página registra a INTENÇÃO** antes de pedir o download e a apaga no
//   fim. Uma intenção que sobrevive a um lançamento é, por definição, um
//   download que ninguém recebeu.
//
// Reclamar é pedir o MESMO download outra vez: o shell devolve o resultado
// guardado na hora (sem rede), ou — se o processo inteiro tiver morrido — baixa
// de novo, agora com a fila de IO livre. O registro fica no `state` do banco,
// que é o único lugar que sobrevive à morte da página.
// ---------------------------------------------------------------------------
const YT_INTENCOES = 'ytIntencoes';
// Uma intenção velha não vale a pena: as URLs do YouTube expiram em horas, e
// reviver o download de um louvor de anteontem na abertura de um domingo é
// gastar rede por algo que ninguém está esperando.
const INTENCAO_VALIDA_MS = 6 * 60 * 60 * 1000;

function mesmaIntencao(a, link, soAudio) {
  return a && a.link === link && !!a.soAudio === !!soAudio;
}

// AS DUAS MEXEM NA LISTA DENTRO DE UMA TRANSAÇÃO SÓ (`AVDB.updateState`).
// Com `getState` + `setState` havia um vão entre ler e gravar, e ele é
// alcançável: um item pode ir para VÁRIOS destinos de uma vez, a fila do shell
// serializa os downloads mas o lado web não, e o `lembrarIntencao` de um corre
// contra o `esquecerIntencao` do `finally` do outro. Quem lê primeiro grava por
// último e leva junto o item que o outro acabou de pôr — a intenção some, e com
// ela a única coisa que faria o download ser reclamado se o renderer morresse.
// O sintoma é a ausência de um sintoma: o vídeo simplesmente não volta.
async function lembrarIntencao(intencao) {
  try {
    await AVDB.updateState(YT_INTENCOES, (atuais) => (atuais || [])
      .filter((i) => !mesmaIntencao(i, intencao.link, intencao.soAudio))
      .concat([intencao]));
  } catch (e) { console.warn('[yt] não deu para registrar a intenção:', e); }
}

async function esquecerIntencao(link, soAudio) {
  try {
    await AVDB.updateState(YT_INTENCOES, (atuais) => (atuais || [])
      .filter((i) => !mesmaIntencao(i, link, soAudio)));
  } catch (e) { console.warn('[yt] não deu para limpar a intenção:', e); }
}

// As listas em que um item RESSURGE para o operador. Uma intenção que não
// aponta para nenhuma delas não tem onde aterrissar: o `avulsos` é a prateleira
// invisível do simplificado, e um vídeo resgatado para lá baixaria centenas de
// MB para não aparecer em lugar nenhum.
const LISTAS_VISIVEIS = ['imports', 'playlist', 'favs'];

/**
 * Quantas vezes uma intenção pode ser reclamada antes de ser desistida.
 *
 * O resgate REGISTRA a intenção de novo (é o `lembrarIntencao` do começo de
 * todo download), então um download que nunca termina — o app fechado no meio,
 * outra vez, e outra — voltava a cada abertura pelas seis horas inteiras de
 * validade. Foi o que o operador relatou: "mesmo depois de fechar o app ele
 * fica sempre querendo baixar o vídeo". Duas tentativas cobrem o caso real (um
 * OOM do renderer) e fecham o laço.
 */
const INTENCAO_MAX_TENTATIVAS = 2;

/**
 * Desiste de uma intenção: apaga o registro e PARA o download no aparelho.
 *
 * "Apagar e cancelar" é a regra que o operador pediu com todas as letras, e ela
 * é a mesma do coletor de lixo do banco: o que não está em lugar nenhum não é
 * guardado — aqui, não é nem baixado. Sem o `ytCancel` o shell seguiria
 * baixando um arquivo que ninguém mais espera, gastando rede e bateria no meio
 * do culto.
 */
async function desistirDaIntencao(p, porque) {
  console.info('[yt] intenção descartada (' + porque + '):', p.nome || p.link);
  try { if (podeCancelarDownload()) AVNative.ytCancel(p.link); } catch (_) { /* nada */ }
  await esquecerIntencao(p.link, !!p.soAudio);
}

// Chamado uma vez por abertura. Silencioso quando não há nada — que é o caso
// normal.
async function resgatarDownloads() {
  if (!window.__NATIVE__) return;
  let pendentes = [];
  try { pendentes = (await AVDB.getState(YT_INTENCOES)) || []; } catch (_) { return; }
  if (!pendentes.length) return;
  const agora = Date.now();
  // Limpa o registro ANTES de tentar: um resgate que falhe não pode ficar
  // tentando de novo a cada abertura, e quem der certo já reescreve a lista
  // pelo caminho normal (`lembrarIntencao` no começo do download).
  try { await AVDB.setState(YT_INTENCOES, []); } catch (_) { /* segue */ }
  for (const p of pendentes) {
    if (!p || !p.link) continue;
    if ((agora - (p.quando || 0)) > INTENCAO_VALIDA_MS) {
      await desistirDaIntencao(p, 'venceu');
      continue;
    }
    // SEM DESTINO VISÍVEL, NÃO SE RESGATA. Um "Tocar agora" é do INSTANTE em
    // que o operador tocou: reclamá-lo num lançamento seguinte baixa minutos de
    // vídeo para uma cena que já passou, e o item não aparece em lista nenhuma
    // para ser achado depois. Era o caso exato do relato — "esse vídeo não está
    // mais indo para o player e ele continua querendo baixar".
    if (LISTAS_VISIVEIS.indexOf(p.lista) < 0) {
      await desistirDaIntencao(p, 'sem destino');
      continue;
    }
    if ((p.tentativas | 0) >= INTENCAO_MAX_TENTATIVAS) {
      await desistirDaIntencao(p, 'tentou demais');
      continue;
    }
    console.info('[yt] reclamando download interrompido:', p.nome || p.link);
    try {
      const rec = await ytArquivo(
        { id: p.youtubeId || null, url: p.link, name: p.nome },
        {
          lista: p.lista,
          somenteAudio: p.soAudio,
          altura: p.altura,
          // O RESGATE APARECE, e na linha da lista de destino: até aqui ele era
          // `aviso: 'nenhum'` — dez minutos de download invisíveis, sem nada
          // que o operador pudesse tocar para parar. Com a linha provisória ele
          // vê o que está acontecendo e tem onde cancelar (v5.191).
          aviso: 'lib',
          // A CONTAGEM ATRAVESSA o novo `lembrarIntencao` de dentro do
          // `ytArquivo`: sem ela o contador nasceria zerado a cada resgate e o
          // teto nunca seria alcançado.
          tentativas: (p.tentativas | 0) + 1,
        },
      );
      if (!rec) continue;
      // O DESTINO ORIGINAL é honrado: quem pediu "para o Cronograma" recebe no
      // Cronograma, mesmo que o app tenha morrido no meio. `listAdd` é
      // idempotente, e o registro pode já ter nascido na lista certa.
      if (p.lista) await AVDB.listAdd(p.lista, rec.id);
      await load();
    } catch (e) { console.warn('[yt] resgate falhou:', e && e.message); }
  }
}

function ehPdf(item) {
  const t = String((item && item.type) || '').toLowerCase();
  const n = String((item && item.name) || '').toLowerCase();
  return t === 'application/pdf' || n.endsWith('.pdf');
}
function ehPptx(item) {
  const t = String((item && item.type) || '').toLowerCase();
  const n = String((item && item.name) || '').toLowerCase();
  return n.endsWith('.pptx')
    || t === 'application/vnd.openxmlformats-officedocument.presentationml.presentation';
}
// O que o app sabe transformar em páginas: PDF (pelo shell) e PPTX (aqui).
function ehApresentacao(item) { return ehPdf(item) || ehPptx(item); }

// O MOTIVO da última falha de importação de documento, para o aviso poder
// dizê-lo. Uma variável só, escrita logo antes de quem avisa ler: o aviso
// aparece uma vez por lote, e é sempre do último arquivo que falhou.
//
// Existe porque este código roda no aparelho do operador, num domingo de
// manhã, e quem desenvolve não tem o aparelho na mão. Sem o motivo na tela,
// todo defeito daqui chega como a mesma frase e o diagnóstico vira palpite.
let deckUltimoErro = '';

// Arquivo que o app aceitou mas não conseguiu abrir. DIÁLOGO, e não um aviso
// que some sozinho: o operador acabou de escolher (ou compartilhar) um arquivo,
// e nada acontecer leria como "importou".
function avisarNaoAbriu(nome) {
  const motivo = deckUltimoErro;
  deckUltimoErro = '';
  return appConfirm({
    title: 'Não deu para abrir',
    message: '"' + nome + '" não pôde ser lido. Um PDF com senha precisa de uma cópia '
      + 'sem proteção; um PowerPoint muito antigo (.ppt) precisa ser salvo como .pptx.'
      // O detalhe técnico fica no FIM e entre parênteses: quem só quer resolver
      // lê as duas frases acima e ignora esta; quem está diagnosticando (às
      // vezes por mensagem, sem o aparelho em mãos) tem o que precisa sem
      // logcat.
      + (motivo ? '\n\n(detalhe: ' + motivo + ')' : ''),
    okText: 'Entendi', cancelText: null,
  });
}
function nomeSemExtensao(n) { return String(n || '').replace(/\.[^.]+$/, ''); }

// ===== APRESENTAÇÃO (PDF / Google Apresentações) =====
//
// O que chega é um PDF — ou um link do Google Apresentações, que o shell baixa
// já exportado. O que o app guarda é uma IMAGEM POR PÁGINA: daí para a frente
// a apresentação é mídia comum, com fade, cortina, `MediaSession` e o telão
// que já existem. Ver SlideDeck.kt para por que o desenho é nativo e por que o
// formato de entrada é PDF e não `.pptx`.
//
// Exige shell >= 19. Num anterior o método não existe e a função devolve null
// na hora: o PDF volta a ser um arquivo qualquer e o link, um item de URL —
// exatamente o comportamento de antes.
let deckPagina = 0;   // página em cena da apresentação atual

function isDeck(rec) {
  return !!(rec && rec.kind === 'deck' && Array.isArray(rec.pages) && rec.pages.length);
}

/**
 * Vai para uma página da apresentação em cena.
 *
 * UM ponto só, e o ⏮/⏭ passou a ser um caso dele: o toque numa página do
 * auxiliar de leitura precisa fazer exatamente o que o par de botões faz — o
 * mesmo comando, o mesmo redesenho do eixo e do cabeçalho. Duas escritas do
 * mesmo salto divergiriam no primeiro campo novo do comando `page`.
 */
function deckIr(alvo) {
  const d = deckNoAr();
  if (!d) return;
  const n = Math.min(Math.max(alvo | 0, 0), d.pages.length - 1);
  if (n === deckPagina) return;
  deckPagina = n;
  // DOIS CAMINHOS, PORQUE SÃO DUAS CENAS — e a escolha é do ponto único, não
  // dos chamadores. Como MÍDIA a apresentação está no slot do `stage.js` e a
  // página anda por `page`; como CAMADA ela é o cartão de texto, e a página
  // anda reenviando o mesmo `text` com o número novo (é o que o `showText` já
  // faz numa troca de versículo: repinta e faz o fade no lugar). Um `page`
  // mandado para a camada não acharia deck nenhum no motor e não faria NADA —
  // sem erro, com o operador apertando o botão na frente da congregação.
  if (deckSobreProjetando()) {
    cmd({ type: 'text', mode: 'image', mediaId: visualSession.id, page: deckPagina, sub: '', view: 'visual' });
  } else {
    cmd({ type: 'page', page: deckPagina });
  }
  renderSlideNav();
  renderNowPlaying();
}

function deckStep(delta) {
  if (!deckNoAr()) return;
  deckIr(deckPagina + delta);
}

// ===== .pptx → páginas, DENTRO do WebView =====
//
// O Android não desenha PowerPoint: a plataforma só traz o `PdfRenderer` (que
// é o caminho do PDF). As bibliotecas nativas que fazem isso são comerciais, e
// converter num servidor exigiria conta, chave e mandar o material do culto
// para fora do aparelho. Sobrou uma saída, e ela roda AQUI.
//
// A TRADUÇÃO MORA EM `controle/deck.js` (`AVDeck`), ao lado das outras regras
// próprias do Controle e pelo mesmo motivo: ela tem três modos de falhar
// CALADOS — a mídia `blob:` que não atravessa o `<foreignObject>`, os pixels de
// um `<canvas>` que o `cloneNode` não copia, e a fonte de símbolo que o
// aparelho não tem — e um oráculo (`tools/apresentacao.test.mjs`) só alcança o
// que tem porta de entrada. Aqui fica só o que é do APP: a lista de destino, o
// aviso e a linha que nasce.

// Importa um `.pptx` já lido como File/Blob.
async function pptxImportar(file, nome, opts) {
  const rotulo = nome || 'Apresentação';
  const naPreview = !!(opts && opts.naPreview);
  const bg = naPreview
    ? previewBusy('Preparando apresentação', rotulo)
    : libBusy(rotulo, opts && opts.chave);
  const notif = bgTaskStart('Preparando apresentação', 1);
  // O NOME DA APRESENTAÇÃO na linha da notificação, pela mesma razão do vídeo
  // (ver `ytArquivo`): "Preparando apresentação" sozinho não diz QUAL, e com o
  // app minimizado esta é a única tela que existe.
  bgItemOnly(notif, rotulo);
  try {
    return await withBgWork(async () => {
      const feito = await AVDeck.paginasDoPptx(file, (feitas, total) => {
        const pct = total ? Math.floor((feitas / total) * 100) : -1;
        bg.atualizar('Preparando página ' + feitas + (total ? ' de ' + total : '') + '…', null, pct);
        // E OS MESMOS NÚMEROS VÃO PARA A NOTIFICAÇÃO. Até aqui só o cartão na
        // tela andava: a tarefa nascia com `total = 1` e ninguém a fazia
        // avançar, então a barra ficava em 0% do começo ao fim e a estimativa
        // em zero — exatamente o defeito que o download de vídeo teve até a
        // v5.117, e no caso em que a notificação MAIS importa (app minimizado,
        // dezenas de páginas, minutos de espera). A página é a unidade certa
        // aqui, e o total só existe depois que o arquivo abre.
        bgTaskStep(notif, feitas, null, total);
      });
      if (!feito) { deckUltimoErro = 'pptx: nenhuma página desenhada'; return null; }
      const thumb = await makeThumb(feito.pages[0], 'image');
      const criado = await AVDB.addDeck(feito.pages, {
        name: rotulo, thumb, list: (opts && opts.lista) || 'imports',
      });
      // O CORTE É DITO, e pela mesma porta do PDF (ver `deckImportar`): uma
      // apresentação cortada sem aviso leria como "o arquivo era assim", e o
      // operador só descobriria na frente da congregação, na página que não
      // existe. A nota vai para a LINHA DO ITEM, que é onde mora um fato sobre
      // aquele item.
      if (feito.truncado && criado) {
        falharNoItem(criado.id, 'truncada em ' + feito.pages.length + ' páginas');
      }
      return criado;
    });
  } catch (e) {
    console.warn('[pptx] falhou:', e && e.message);
    deckUltimoErro = 'pptx: ' + ((e && e.message) || 'erro sem mensagem');
    return null;
  } finally {
    bgTaskEnd(notif);
    bg.soltar();
  }
}

async function deckImportar(origem, nome, opts) {
  // Quantas páginas o shell entregou quando ele CORTOU o deck (0 = não cortou).
  // Ver o ponto em que ela é lida, logo abaixo: a nota pertence à linha do item.
  let truncadaEm = 0;
  if (!window.__NATIVE__) return null;
  const rotulo = nome || 'Apresentação';
  const naPreview = !!(opts && opts.naPreview);
  const bg = naPreview
    ? previewBusy('Preparando apresentação', rotulo)
    : libBusy(rotulo, opts && opts.chave);
  const notif = bgTaskStart('Preparando apresentação', 1);
  bgItemOnly(notif, rotulo);
  let primeira = null;   // uma página basta para o descarte: ele apaga a pasta
  try {
    return await withBgWork(async () => {
      const r = await AVNative.deckPages(origem, rotulo, (feitas, total) => {
        const pct = total ? Math.floor((feitas / total) * 100) : -1;
        bg.atualizar('Preparando página ' + feitas + (total ? ' de ' + total : '') + '…', null, pct);
        // A NOTIFICAÇÃO ANDA JUNTO — ver o mesmo ponto em `pptxImportar`.
        //
        // O total é `N + 1`, e o +1 é a CÓPIA das páginas para a biblioteca,
        // logo abaixo: ela é a última fatia de trabalho desta importação, e
        // sem ela na conta a barra fecharia em 100% com o operador ainda
        // esperando. Somar as duas fases inteiras (2N) seria pior no outro
        // sentido — a rasterização é o que leva segundos por página e a cópia
        // lê o cache local, então a barra passaria metade da vida numa fase
        // que custa uma fração do tempo. É a mesma escolha do download em duas
        // faixas: a barra nunca recomeça e nunca anda para trás.
        bgTaskStep(notif, feitas, null, total + 1);
      });
      if (!r || !Array.isArray(r.pages) || !r.pages.length) {
        // Num shell < 22 não vem `erro` nenhum: o aviso sai sem detalhe, que é
        // exatamente o que ele já fazia.
        deckUltimoErro = (r && r.erro) ? String(r.erro) : 'o shell não devolveu páginas';
        return null;
      }
      primeira = r.pages[0];
      // TRUNCADA PELO SHELL (`truncado`, campo que o shell novo passa a
      // enviar): um deck cortado sem aviso leria como "o arquivo era assim", e
      // o operador só descobriria na frente da congregação, na página que não
      // existe. Campo ausente (shell antigo) = sem aviso, como sempre.
      // A NOTA VAI PARA A LINHA DO ITEM QUE VAI NASCER (v5.207), e por isso ela
      // é guardada aqui e aplicada lá embaixo, quando o registro já tem id: uma
      // apresentação cortada é um fato SOBRE AQUELE ITEM, e o lugar de um fato
      // sobre um item é a linha dele — não uma faixa no topo da tela, que já
      // teria sumido quando o operador chegasse ao Cronograma.
      truncadaEm = r.truncado ? r.pages.length : 0;
      // Uma página de cada vez: as imagens já estão no cache do aparelho, e
      // buscar as dezenas de uma vez só encheria a memória sem ganhar tempo.
      //
      // E ESTA FASE FALAVA COM NINGUÉM. O cartão da tela ficava na última
      // mensagem da rasterização e a notificação parava de receber eventos —
      // e parar de receber eventos não é neutro: `idleMs` cresce, e passado
      // `BG_STALL_MS` a notificação troca a estimativa por "sem resposta há
      // X". Ou seja, o trecho em que tudo está indo bem era o único capaz de
      // anunciar que travou.
      const pages = [];
      bg.atualizar('Guardando as páginas…', null, -1);
      // A TROCA DE RÓTULO VAI COM `force`, pela regra que o primeiro nome já
      // segue: o piso de envio (`BG_NOTIF_MIN_MS`) existe para segurar
      // contador, não estado. Uma cópia rápida cabe inteira dentro do piso, e
      // sem o forçar a notificação terminaria a importação ainda dizendo
      // "Preparando apresentação" — o rótulo da fase anterior.
      bgTaskStep(notif, r.pages.length, 'Guardando as páginas');
      bgTaskSend(true);
      for (const u of r.pages) {
        const res = await fetch(u);
        if (!res.ok) { deckUltimoErro = 'página ' + (pages.length + 1) + ': HTTP ' + res.status; return null; }
        const b = await res.blob();
        if (!b.size) { deckUltimoErro = 'página ' + (pages.length + 1) + ' veio vazia'; return null; }
        pages.push(b);
        // O `done` fica onde a rasterização o deixou: a cópia inteira é o
        // ÚLTIMO passo do total (ver o `total + 1` acima), e não N passos. O
        // que estes envios fazem é manter a tarefa VIVA — sem eles o relógio de
        // ociosidade corre durante toda a cópia, e passado `BG_STALL_MS` a
        // notificação troca a estimativa por "sem resposta há X" no trecho em
        // que tudo está indo bem.
        bgTaskStep(notif, r.pages.length);
      }
      const thumb = await makeThumb(pages[0], 'image');
      const criado = await AVDB.addDeck(pages, {
        name: r.name || rotulo, thumb, list: (opts && opts.lista) || 'imports',
      });
      // Um deck cortado sem aviso leria como "o arquivo era assim", e o
      // operador só descobriria na frente da congregação, na página que não
      // existe. (Campo ausente = shell antigo = sem aviso, como sempre.)
      if (truncadaEm && criado) falharNoItem(criado.id, 'truncada em ' + truncadaEm + ' páginas');
      return criado;
    });
  } catch (e) {
    console.warn('[apresentação] falhou:', e && e.message);
    deckUltimoErro = 'web: ' + ((e && e.message) || 'erro sem mensagem');
    return null;
  } finally {
    // No `finally`, como o `ytDiscard`: mesmo que a cópia falhe, as páginas do
    // cache não podem ficar para trás — ninguém mais tem o token delas.
    if (primeira) AVNative.deckDiscard(primeira);
    bgTaskEnd(notif);
    bg.soltar();
  }
}

// O arquivo do vídeo: o que JÁ está no aparelho, ou um download novo.
//
// Até a v5.86 cada destino baixava por conta própria — tocar agora, adicionar
// à playlist e adicionar ao Cronograma eram três downloads do MESMO vídeo, de
// dezenas de MB, muito provavelmente em rede de celular. O registro guarda o
// `youtubeId` desde que é criado, então a pergunta "já tenho isto?" custa uma
// leitura de índice (`AVDB.mediaByYoutube`), sem desserializar blob nenhum.
//
// Só reaproveita quem tem BLOB — arquivo de verdade no aparelho. Um item de
// PLAYER (o link, sem bytes) carrega o mesmo `youtubeId` e é justamente o que
// esta função existe para substituir: aceitá-lo faria o botão "baixar o vídeo"
// da linha do Cronograma devolver o próprio link e parecer que não fez nada.
async function ytArquivo(alvo, opts) {
  const vid = alvo && alvo.id ? alvo.id : null;
  // O REAPROVEITAMENTO É POR FORMA (v5.112): quem pediu só o áudio não pode
  // receber o vídeo de 80 MB que já estava aqui — e quem pediu o vídeo não pode
  // receber um arquivo sem imagem. As duas formas convivem no banco com o mesmo
  // `youtubeId`, e é o `kind` que as separa.
  const soAudio = !!(opts && opts.somenteAudio);
  const ja = vid ? await AVDB.mediaByYoutube(vid, soAudio ? 'audio' : 'video') : null;
  if (ja && ja.blob) return ja;
  // O CANAL viaja por `opts` porque o `ytFetch` não o devolve (o shell manda
  // `name`, `type`, `height` e `seconds`, e mais nada): quem o tem é o `alvo`,
  // que já passou por aqui. Um ponto só, e todo chamador o herda sem saber.
  return ytBaixarNativo(alvo.url, alvo.name,
    Object.assign({ youtubeId: vid, canal: (alvo && alvo.author) || null }, opts || {}));
}

// A prateleira da mídia avulsa — a que está em cena sem pertencer a lista
// nenhuma. É o que permite "Tocar agora" (e o share no simplificado) não
// encostar no Cronograma sem deixar registro órfão, que o gc nunca alcançaria.
//
// Ela é PEQUENA e tem tamanho fixo, porque os dois extremos são ruins: com um
// lugar só, voltar ao vídeo anterior baixa tudo de novo — exatamente o
// desperdício que a v5.87 existe para acabar; sem limite, a mídia que a tela
// não mostra vira uma pilha de centenas de MB que o operador não tem como
// apagar (não há tela de liberar espaço). Três cobre o uso real — alternar
// entre dois ou três vídeos num mesmo culto — e para por aí.
//
// Sai o mais ANTIGO (a lista guarda ordem de chegada), e quem sai passa pelo
// `listRemove`, que decide sozinho se o blob morre: ele fica inteiro se o
// Cronograma, a playlist ou um Favorito também o tiverem.
//
// Aceita um LOTE, e o lote nunca é podado: um share pode trazer cinco arquivos
// de uma vez, e com o limite aplicado item a item os primeiros seriam apagados
// pelos últimos DA MESMA LEVA — inclusive o que vai ser projetado, que é o
// primeiro. Quem cede lugar é sempre o que já estava aqui de antes.
const AVULSO_MAX = 3;
async function fixarAvulso(novos) {
  const lote = (Array.isArray(novos) ? novos : [novos]).filter(Boolean);
  if (!lote.length) return;
  const ids = await AVDB.listIds('avulsos');
  for (const id of lote) if (!ids.includes(id)) await AVDB.listAdd('avulsos', id);
  const outros = ids.filter((x) => !lote.includes(x));
  const cabem = Math.max(0, AVULSO_MAX - lote.length);
  const excedente = outros.slice(0, Math.max(0, outros.length - cabem));
  for (const velho of excedente) await AVDB.listRemove('avulsos', velho);
}

// Sentinela: o link SE RESOLVEU SOZINHO e não sobrou registro para entregar.
// Não é erro (`null`) nem item pronto, e são dois casos:
//
//  - no avançado, a folha de escolhas está NA TELA e quem decide agora é o
//    operador;
//  - no simplificado, o vídeo JÁ ESTÁ NO TELÃO, transmitido.
//
// Nos dois, o `focarImportado` do `importShare` só faria estrago: ele passa por
// `sairDasCamadas`, que fecharia a folha — e no simplificado redesenharia a
// tela por cima de uma projeção que acabou de começar.
const SHARE_TRATADO = Symbol('tratado');

// Devolve o registro criado — quem compartilhou precisa saber QUAL item
// chegou para poder levar o operador até ele (ver focarImportado).
async function handleSharedUrl(url, title) {
  if (!url) return null;
  const ytId = extractYouTubeId(url);
  if (ytId) {
    // NO AVANÇADO, AS MESMAS QUATRO ESCOLHAS DA BUSCA (v5.137).
    //
    // Um link compartilhado e um resultado da busca são o MESMO item — um vídeo
    // do YouTube que o operador quer no app —, e as duas portas davam em
    // lugares diferentes: a busca PERGUNTA (tocar · playlist · Cronograma ·
    // Favoritos, mais vídeo/só-áudio e o teto de resolução) e o share DECIDIA
    // sozinho, sempre vídeo, sempre no Cronograma, sempre no padrão de
    // qualidade. Quem compartilha um louvor de 40 min para tocar no fundo
    // recebia 1080p inteiro, sem ter como dizer que só queria o áudio.
    //
    // NO SIMPLIFICADO continua sem pergunta, e não por esquecimento: ali não
    // existe Cronograma nem playlist, o item vai direto ao telão, e uma folha
    // com destinos que a tela não tem seria pior que folha nenhuma. É a mesma
    // regra do toque numa música do acervo naquele modo (`simplePlaySong`).
    if (!simplificado()) {
      // O `sairDasCamadas()` do `importShare` já rodou: a folha abre sobre o
      // Cronograma, com todo popup anterior fechado.
      // O `title` do share é o `EXTRA_SUBJECT` do Android, e nem todo app o
      // preenche com o TÍTULO: alguns repetem a própria URL ali. Uma folha com
      // um endereço cru no cabeçalho não diz nada a mais que "vídeo do
      // YouTube" — e diz pior. O nome definitivo do item vem da extração, de
      // qualquer jeito (ver `ytBaixarNativo`); isto aqui é só o cabeçalho.
      const rotulo = (title && !/^https?:\/\//i.test(title.trim())) ? title : 'Vídeo do YouTube';
      openYtMenu({ id: ytId, url, name: rotulo });
      return SHARE_TRATADO;
    }
    // NO SIMPLIFICADO, TOCA DIRETO DA REDE (v5.138) — o mesmo que o "Tocar
    // agora" do avançado já faz. Ali o link compartilhado É um "tocar agora":
    // ele vai direto ao telão, não entra em lista visível nenhuma e ninguém
    // pediu para GUARDAR nada. Esperar centenas de MB baixarem para começar a
    // projetar era exatamente a espera que a transmissão direta existe para
    // acabar, e ela estava disponível o tempo todo — só não era tentada por
    // esta porta.
    //
    // `tentarTransmitir` já faz tudo quando dá certo: grava o registro em
    // `avulsos` (o mesmo destino que o share do simplificado usa), redesenha e
    // projeta. Falhando qualquer coisa — shell antigo, vídeo sem par
    // adaptativo, WebView sem o codec — ela devolve `false` e a linha abaixo
    // segue para o download de sempre, calado: o operador pediu o louvor, não
    // o método.
    const alvoStream = { id: ytId, url, name: title || ('YouTube: ' + ytId) };
    if (await tentarTransmitir(alvoStream, YT_ALTURAS[0], false)) return SHARE_TRATADO;
    // O link vira ARQUIVO — é a via que toca em segundo plano e não depende da
    // rede durante o culto. Falhando (vídeo restrito, shell antigo), cai no
    // item de player de sempre: um link compartilhado nunca se perde.
    // A via NATIVA — extração no próprio aparelho, sem servidor nenhum no meio
    // (ver `ytBaixarNativo` e YoutubeGrab.kt). Não pede configuração, não
    // depende de instância de terceiro e sai do IP do chip do operador, que é
    // justamente o que o YouTube não bloqueia.
    // No simplificado o item vai DIRETO ao telão (ver focarImportado), então o
    // aviso pertence à preview; no avançado ele só entra no Cronograma.
    // Compartilhar DE NOVO o mesmo vídeo não baixa de novo: `ytArquivo`
    // devolve o que já está no aparelho. Ele pode estar só no slot avulso
    // (foi tocado sem entrar em lista), e no avançado um share vai para o
    // Cronograma — daí o `listAdd`, idempotente para o caso de já estar lá.
    const nativo = await ytArquivo(
      { id: ytId, url, name: title || ('YouTube: ' + ytId) },
      { lista: destinoDoShare(), naPreview: simplificado() },
    );
    if (nativo) return guardarShare(nativo);
    const thumb = (await thumbYoutube(ytId)) || ('https://img.youtube.com/vi/' + ytId + '/hqdefault.jpg');
    return guardarShare(await AVDB.addUrlMedia(url, {
      kind: 'youtube',
      type: 'video/youtube',
      name: title || ('YouTube: ' + ytId),
      thumb,
      youtubeId: ytId,
      list: destinoDoShare(),
    }));
  }
  // APRESENTAÇÃO DO GOOGLE: o link vira PDF exportado e, daí, imagens — quem
  // sabe montar a URL de exportação é o shell (`deckExportUrl`), porque é ele
  // que sabe o que consegue abrir. Precisa estar compartilhada por link, que é
  // como um roteiro de culto circula; sem permissão a exportação falha e o link
  // cai no caminho de sempre (item de URL).
  if (window.__NATIVE__) {
    const exportacao = AVNative.deckExportUrl(url);
    if (exportacao) {
      const rec = await deckImportar(exportacao, title || 'Apresentação', {
        naPreview: simplificado(), lista: destinoDoShare(),
      });
      if (rec) return guardarShare(rec);
    }
  }
  const kind = detectUrlKind(url);
  const fallbackName = url.split('/').pop().split('?')[0] || url;
  return guardarShare(await AVDB.addUrlMedia(url, {
    kind,
    type: kind + '/url',
    name: title || fallbackName,
    thumb: null,
    list: destinoDoShare(),
  }));
}

// No SIMPLIFICADO um link compartilhado só toca — não existe Cronograma nesse
// modo, e pendurar o vídeo numa lista que a tela não mostra é guardar sem
// pedir. É a mesma regra do toque numa música do acervo ali (`simplePlaySong`,
// que também não abre folha de escolha) e a mesma de "Tocar agora": o destino
// é o slot avulso, que segura a mídia enquanto ela é a cena e a solta quando
// outra entra.
//
// Vale para LINK, não para arquivo. Um share de arquivos pode trazer vários de
// uma vez, e com um slot só cada um apagaria o anterior — ali o Cronograma
// continua sendo o destino nos dois modos.
function simplificado() { return appMode === 'simple'; }

// OS DESTINOS DO LOTE QUE ESTÁ ENTRANDO (v5.141). No avançado quem os escolhe é
// o operador, na folha (ver `escolherDestinos`); no simplificado a pergunta não
// existe e o valor é ignorado, porque lá tudo vai para a prateleira avulsa.
//
// Uma variável de módulo, e não um parâmetro carregado por dez funções: o
// caminho do share atravessa `handleSharedUrl`, `deckImportar`, `pptxImportar` e
// `AVDB.addMedia`, todos já recebendo `lista` como um nome só. O que mudou é
// quantas listas existem DEPOIS da primeira — e essa parte é sempre a mesma
// (`espalharShare`).
let shareDestinos = ['cronograma'];
function destinoDoShare() {
  return simplificado() ? 'avulsos' : listaDoDestino(shareDestinos[0]);
}
// As listas ALÉM da primeira. Quem cria o registro já o grava na primeira, na
// mesma transação; as outras são um `listAdd` idempotente por item.
async function espalharShare(id) {
  if (simplificado() || !id) return;
  const listas = listasDosDestinos(shareDestinos).slice(1);
  for (const l of listas) await AVDB.listAdd(l, id);
}
async function guardarShare(rec) {
  if (!rec) return rec;
  // No simplificado quem prende o registro na prateleira é o `importShare`, de
  // uma vez só para todo o lote (ver `fixarAvulso`). Aqui só resta o avançado.
  if (!simplificado()) {
    // O registro pode ser um REAPROVEITADO que estava só na prateleira avulsa.
    await AVDB.listAdd(destinoDoShare(), rec.id);
    await espalharShare(rec.id);
    await AVDB.listRemove('avulsos', rec.id);
  }
  return rec;
}

// Importa um share já normalizado. Aceita as DUAS formas de arquivo:
//   - `File` (navegador: o SW gravou o POST multipart em pending-share);
//   - `{ name, type, url }` (app nativo: a ponte entrega URL servível e os
//     bytes vêm por fetch, nunca base64).
// Daqui pra baixo o caminho é o mesmo dos arquivos importados à mão.
async function importShare(pending) {
  if (!pending) return false;
  let added = false;
  let primeiro = null;   // o 1º item que entrou: é ele que o foco vai buscar
  // A RESPOSTA VEM PRIMEIRO. Um link do YouTube vira arquivo em minutos e um
  // vídeo compartilhado leva segundos para ser copiado; sair do acervo (ou da
  // Bíblia, ou de uma pasta) só no fim disso deixava o operador olhando a tela
  // que ele já tinha deixado, sem sinal de que algo chegou. O cartão de
  // progresso aparece sobre a preview — que agora está à vista justamente
  // porque saímos das camadas antes, e não depois.
  await sairDasCamadas();

  const files = pending.files || [];
  // PARA ONDE VAI ISTO? (v5.141) — a pergunta que o app respondia sozinho.
  //
  // Ela não vale para TUDO o que chega: um link do YouTube abre a folha própria
  // dele logo abaixo (com os mesmos destinos, mais a forma e a qualidade), e
  // perguntar duas vezes pelo mesmo item seria pior que não perguntar. E no
  // simplificado `escolherDestinos` já devolve `null` sozinho — ali não existe
  // Cronograma nem playlist.
  //
  // Desistir (✕, fundo, voltar) devolve `null` e o lote entra no Cronograma,
  // como sempre entrou: um compartilhamento nunca se perde por causa de uma
  // pergunta.
  shareDestinos = ['cronograma'];
  const temLinkYt = !!(pending.url && extractYouTubeId(pending.url));
  if (files.length || (pending.url && !temLinkYt)) {
    const titulo = files.length > 1 ? 'Importar ' + files.length + ' itens' : 'Importar';
    const escolha = await escolherDestinos(titulo, ['cronograma']);
    if (escolha && escolha.length) shareDestinos = escolha;
  }
  // No simplificado NADA de um share vai para lista visível — arquivo inclusive
  // (v5.89): a tela não tem Cronograma nem playlist, e o que chega ali chega
  // para ir ao telão. Os ids do lote são fixados JUNTOS no fim, senão o quinto
  // arquivo empurraria o primeiro para fora — e o primeiro é justamente o que
  // vai ser projetado.
  const lote = [];
  let naoAbriu = null;   // o último arquivo que o app não conseguiu abrir
  let ok = 0;
  for (const item of files) {
    // DOCUMENTO (PDF ou PowerPoint): vira uma imagem por página, e cada formato
    // pelo caminho que existe para ele. O desvio acontece ANTES da leitura
    // porque o PDF não pode virar blob aqui — quem o desenha é o shell, e ele
    // precisa do arquivo ORIGINAL (a URL `/saf/`), não de uma cópia já lida.
    //
    // Este ramo atende as DUAS portas de entrada, que entregam a mesma forma:
    // o compartilhamento e o seletor do sistema (`importarPeloSistema`).
    if (ehApresentacao(item)) {
      const nome = nomeSemExtensao((item && item.name) || 'Apresentação');
      let rec = null;
      if (ehPdf(item) && !item.url) {
        // PDF sem URL servível: veio como `File` (o `<input type="file">` do
        // navegador, ou de um shell antigo). Quem desenha o PDF é o shell, e
        // ele precisa do ARQUIVO — não há caminho daqui.
        deckUltimoErro = window.__NATIVE__
          ? 'PDF precisa do seletor de arquivos do app (instale a versão nova)'
          : 'o navegador não desenha PDF; use o app';
      } else if (ehPdf(item)) {
        // PDF: quem desenha é o shell, e ele precisa do ARQUIVO (a URL `/saf/`),
        // não de uma cópia já lida — por isso o desvio acontece ANTES da leitura.
        rec = await deckImportar(item.url, nome, {
          naPreview: simplificado(), lista: destinoDoShare(),
        });
      } else if (ehPptx(item)) {
        // PPTX: quem desenha é o próprio WebView (ver `controle/deck.js`), então
        // aqui os bytes SERVEM — e é o único caminho que existe para ele.
        let arquivo = item instanceof File ? item : null;
        if (!arquivo && item.url) {
          try {
            const res = await fetch(item.url);
            if (res.ok) arquivo = await res.blob();
            else deckUltimoErro = 'não deu para ler o arquivo (HTTP ' + res.status + ')';
          } catch (e) {
            arquivo = null;
            deckUltimoErro = 'não deu para ler o arquivo: ' + ((e && e.message) || 'erro');
          }
        }
        if (arquivo) rec = await pptxImportar(arquivo, nome, {
          naPreview: simplificado(), lista: destinoDoShare(),
        });
      }
      if (rec) {
        // O registro nasceu na PRIMEIRA lista escolhida; as demais são um
        // `listAdd` por item (ver `espalharShare`).
        await espalharShare(rec.id);
        if (!primeiro) primeiro = rec.id;
        lote.push(rec.id);
        ok++;
      } else {
        // Arquivo que não abre (PDF com senha, PPTX corrompido): DIÁLOGO, e não
        // silêncio. O operador acabou de escolher um arquivo; nada acontecer
        // leria como "importou".
        naoAbriu = nome;
      }
      continue;
    }
    // O AVISO VEM ANTES DO TRABALHO (v1.3.12), e não depois.
    //
    // Um vídeo do armazenamento leva SEGUNDOS até virar linha: o `fetch` do
    // `/saf/` copia o arquivo inteiro, o `prepararMidia` decodifica um quadro
    // para a miniatura e mede a duração, e o `addMedia` grava tudo no
    // IndexedDB. Até aqui nada disso aparecia: a folha de destinos já tinha
    // fechado, a lista continuava igual, e do lado de quem opera é
    // indistinguível de o app ter travado — que foi a queixa do operador
    // ("não soube se ele travou ou se estava importando").
    //
    // A REGRA É A DE SEMPRE: o aviso mora onde o resultado vai aparecer, e o
    // par é o MESMO da importação de apresentação (ver `deckImportar`), que já
    // fazia isto — este ramo é que tinha ficado sem. No avançado o resultado é
    // uma LINHA, e `sairDasCamadas`, lá em cima, já pôs o operador no
    // Cronograma; no Modo Fácil não há lista e o item vai ao TELÃO a seguir,
    // onde o cartão sobre a preview é literalmente verdadeiro.
    //
    // SEM PERCENTUAL, de propósito: `fetch().blob()` não reporta progresso, e
    // um número parado em 0% mente mais do que o aro girando. O que o operador
    // precisa saber aqui é que HÁ trabalho em curso e sobre QUAL arquivo.
    const rotulo = nomeSemExtensao((item && item.name) || 'Arquivo');
    const bgImport = simplificado()
      ? previewBusy('Importando', rotulo)
      : libBusy(rotulo, null);
    try {
      let blob = null;
      let name = '';
      if (item instanceof File) {
        blob = item;
        name = item.name;
      } else if (item && item.url) {
        try {
          const res = await fetch(item.url);
          if (!res.ok) continue;
          blob = await res.blob();
        } catch (_) { continue; }
        name = item.name || 'arquivo';
      } else {
        continue;
      }
      // O tipo vem da extensão (mesma fonte usada na sincronização de pastas):
      // provedores do Android costumam devolver MIME genérico.
      const type = guessMediaType(name) || blob.type;
      const kind = AVDB.kindFromType(type);
      const { thumb, height, seconds } = await prepararMidia(blob, kind);
      const rec = await AVDB.addMedia(blob, {
        name: name.replace(/\.[^.]+$/, ''), type, kind, thumb, height, seconds,
        list: destinoDoShare(),
      });
      // Só conta o que DE FATO entrou: um `addMedia` que falha com `ok++` fora
      // da guarda fazia o share terminar como sucesso sem item nenhum.
      if (rec) {
        await espalharShare(rec.id);
        if (!primeiro) primeiro = rec.id;
        lote.push(rec.id);
        ok++;
      }
    } finally {
      // NO `finally`, e os três `continue` acima são a razão: um arquivo que
      // não abre sai do laço por eles, e sem isto a linha provisória ficaria na
      // lista para sempre — um item fantasma que nenhum toque remove.
      bgImport.soltar();
    }
  }
  if (ok > 0) added = true;

  // O LINK PODE SE RESOLVER SOZINHO (ver `SHARE_TRATADO`): a folha de escolhas
  // está na tela, ou a transmissão já está no telão. Nos dois casos não há item
  // a entregar, e chamar o `focarImportado` logo abaixo só faria estrago.
  let tratado = false;
  if (pending.url) {
    const rec = await handleSharedUrl(pending.url, pending.title);
    if (rec === SHARE_TRATADO) tratado = true;
    else {
      if (rec && !primeiro) primeiro = rec.id;
      if (rec) lote.push(rec.id);
    }
    added = true;
  }
  // Um share traz arquivos OU um link, mas a fixação é uma só de propósito: se
  // um dia vierem os dois, duas chamadas fariam a segunda expulsar a primeira.
  if (simplificado()) await fixarAvulso(lote);
  // As listas que não são a que está em cena precisam ser relidas: a estrela de
  // cada linha vem de `favSet`, e a fila da playlist de `plItems`.
  const listasEscolhidas = simplificado() ? [] : listasDosDestinos(shareDestinos);
  if (listasEscolhidas.includes('favs')) await recarregarFavoritos();
  if (listasEscolhidas.includes('playlist')) {
    plItems = await AVDB.listItems('playlist');
    renderPlaylist();
  }
  if (added && !tratado) await focarImportado(primeiro);
  // DIZER PARA ONDE FOI, e só quando não for óbvio. `focarImportado` leva o
  // operador ao Cronograma — a resposta visual de sempre —, mas um item que foi
  // para os Favoritos ou para a playlist não aparece ali, e sem isso o import
  // terminaria parecendo que nada entrou.
  //
  // A frase mora na LINHA do primeiro item do lote (v5.207), que é justamente a
  // linha para a qual o `focarImportado` acabou de rolar: o operador está
  // olhando para ela quando a resposta aparece. Antes era uma faixa flutuante
  // no topo, e ela chegava enquanto a tela ainda estava trocando de aba.
  if (added && !tratado && lote.length
    && (listasEscolhidas.length > 1 || (listasEscolhidas.length === 1 && listasEscolhidas[0] !== 'imports'))) {
    const quantos = lote.length === 1 ? 'foi ' : lote.length + ' itens ';
    // `primeiro` JÁ É o id (os três pontos que o preenchem gravam `rec.id`), e é
    // assim que ele é passado ao `focarImportado` acima. Um `.id` a mais aqui dá
    // `undefined`, e `notaNoItem` sai calado na primeira linha: o import termina
    // parecendo que nada entrou, que é o desfecho que este bloco existe para
    // impedir.
    notaNoItem(primeiro, quantos + ondeDe(listasEscolhidas, 'para'), 'ok');
  }
  if (naoAbriu) await avisarNaoAbriu(naoAbriu);
  return added;
}

// O QUE CHEGOU PRECISA FICAR NA FRENTE DO OPERADOR.
//
// Um compartilhamento é um pedido explícito e imediato, e o app pode estar em
// qualquer lugar quando ele chega. Duas respostas, uma por modo:
//  - Simplificado: PROJETA na hora — a lista sequer aparece ali, então
//    "adicionei ao Cronograma" não significaria nada.
//  - Avançado: leva para o Cronograma, onde o item entrou, e deixa a decisão de
//    projetar com o operador (pode haver outra coisa no ar agora).
// A metade que RESPONDE AO TOQUE é separada da que projeta, porque as duas
// acontecem em momentos diferentes: um link do YouTube leva minutos para virar
// arquivo, e sair do acervo só no fim do download deixa o operador sem sinal
// nenhum de que algo está acontecendo. "A resposta vem primeiro", como em
// `playSongVariant`.
async function sairDasCamadas() {
  // 1. Sai de tudo que está POR CIMA da lista, em qualquer modo: um acervo em
  //    tela cheia esconderia tanto o Cronograma quanto a tela simplificada.
  if (selectionMode) exitSelection();
  POPUPS.forEach(([backdrop, , close]) => {
    if (backdrop.classList.contains('open')) close();
  });
  // 2. A preview em tela cheia só sai quando há TELÃO. Sem telão conectado ela
  //    É a projeção (ver "Divergências"), e derrubá-la para mostrar uma lista
  //    tiraria do ar o que estiver em cena — caro demais para um import.
  if (document.fullscreenElement && displayActive()) {
    try { await document.exitFullscreen(); } catch (_) {}
  }

  // 3. Fora do Cronograma, volta para ele. No simplificado não há abas: basta
  //    redesenhar.
  if (appMode !== 'simple') fecharBiblia();
  else await load();
}

// E a metade que PROJETA, chamada quando o item finalmente existe.
async function focarImportado(id) {
  await sairDasCamadas();
  // No simplificado o item vai direto ao telão: esse modo existe para quem não
  // vai operar nada, e a lista sequer aparece nele.
  if (appMode === 'simple' && id) await send(id);
}

// (A leitura do estado `pending-share` saiu: quem o escrevia era o service
// worker dos dois PWAs, removido do bundle na v5.48 — era uma chave que
// ninguém escreve desde então.)
function registrarShareNativo() {
  // App nativo: o share chega por intent (AVNative.onShare) — o intent-filter
  // entrega o conteúdo direto, sem depender de um POST interceptado.
  if (!window.__NATIVE__) return;
  AVNative.onShare((share) => {
    importShare(share).catch((e) => {
      // O intent já foi CONSUMIDO no Kotlin: não existe segunda entrega. Sem
      // este catch a rejeição virava unhandled rejection no console e o
      // compartilhamento evaporava sem nenhum rastro visível.
      diagC('share falhou: ' + ((e && e.message) || e));
      // ESTE É O ÚNICO PONTO SEM INTERFACE DE ORIGEM: o compartilhamento vem de
      // FORA do app, o intent já foi consumido no Kotlin (não existe segunda
      // entrega) e nenhum item chegou a nascer — não há linha, botão ou folha
      // em que responder. O diálogo do próprio app é a resposta certa aqui, e
      // não uma faixa flutuante: ele toma o foco, exige um toque e não some
      // sozinho enquanto o operador olha para outro lugar. Perder um
      // compartilhamento em silêncio é o desfecho que isto existe para impedir.
      appConfirm({
        title: 'Não deu para importar',
        message: 'O que foi compartilhado não pôde ser lido, e o Android já entregou '
          + 'o item — não há como tentar de novo daqui. Compartilhe outra vez pelo '
          + 'app de origem.',
        okText: 'Entendi', cancelText: null,
      });
    });
  });
}


// ===== O LINK DO YOUTUBE QUE ESTÁ NA ÁREA DE TRANSFERÊNCIA (v1.1.8) =====
//
// Pedido do operador: *"ao entrar no app com um link do YouTube copiado, ele
// ofereça a mesma opção de quando se compartilha um link via share normal"*.
//
// **A DIFERENÇA ENTRE COPIAR E COMPARTILHAR É QUE COPIAR NÃO É UM PEDIDO.** Um
// share é um ato dirigido a ESTE app; um link na área de transferência pode
// estar ali por qualquer razão, inclusive nenhuma. Por isso o caminho não é o
// do share: aqui há uma PERGUNTA antes, e só o "sim" entrega o link ao
// `importShare` — que dali em diante é literalmente o mesmo código, com as
// mesmas escolhas (tocar · playlist · Cronograma · Favoritos, mais a forma e o
// teto de qualidade).
//
// A pergunta também é o que torna o recurso seguro no MODO FÁCIL: ali um link
// compartilhado vira transmissão direta SEM perguntar nada — e um link
// projetado na frente da congregação porque estava copiado seria o pior
// desfecho possível deste recurso.
//
// ===== O AVISO DO SISTEMA É O CUSTO, E ELE É PAGO UMA VEZ POR LINK =====
//
// Do Android 12 em diante, LER a área de transferência que outro app preencheu
// mostra um aviso na tela. Ler a cada vinda ao app daria esse aviso em toda
// retomada — o recurso seria pior que a ausência dele. Quem evita isso é o
// CARIMBO (`ClipDescription.getTimestamp`), consultado pelo shell ANTES de ler:
// consultar a descrição não mostra aviso nenhum, então o conteúdo só é lido
// quando ele é novo. Ver `BridgeHost.readClipboardUrl`.
//
// O carimbo do último conteúdo já examinado mora no BANCO (`clip-carimbo`), e
// não em memória: o processo morre, o app reabre, e um carimbo perdido faria a
// mesma pergunta de novo — com o aviso do sistema junto.
const CLIP_ESTADO = 'clip-carimbo';
let clipConferindo = false;

async function conferirLinkCopiado() {
  // No navegador não existe: `navigator.clipboard.readText()` pede permissão e
  // exige gesto, que é exatamente o oposto do que este caminho quer ser.
  if (!window.__NATIVE__ || clipConferindo) return;
  clipConferindo = true;
  try {
    const desde = (await AVDB.getState(CLIP_ESTADO)) || 0;
    const achado = await AVNative.areaTransferencia(desde);
    if (!achado || !achado.carimbo) return;
    const vid = extractYouTubeId(achado.texto || '');
    if (!vid) {
      // NÃO É DO YOUTUBE: o carimbo avança do mesmo jeito. Sem isto, um texto
      // qualquer copiado seria relido a cada retomada — e cada releitura é um
      // aviso do sistema na tela por um link que nunca vai ser oferecido.
      await AVDB.updateState(CLIP_ESTADO, () => achado.carimbo);
      return;
    }
    // UM DIÁLOGO JÁ NA TELA ADIA A PERGUNTA, e o carimbo NÃO avança: o
    // `openAppDialog` resolve o anterior como cancelado ao abrir o próximo, e a
    // pergunta que estaria ali é a da atualização — recusá-la por baixo, sem
    // ninguém ter tocado em nada, é o desfecho que esta guarda existe para
    // impedir. A retomada seguinte pergunta de novo, e o carimbo intacto é o
    // que garante que ela ainda tem o que perguntar.
    if (appDialogResolve) return;
    await AVDB.updateState(CLIP_ESTADO, () => achado.carimbo);
    const usar = await appConfirm({
      title: 'Link do YouTube copiado',
      message: 'Você tem um link do YouTube na área de transferência. '
        + 'Quer usá-lo agora?\n\n' + achado.texto,
      okText: 'Usar o link', cancelText: 'Agora não',
    });
    if (!usar) return;
    await importShare({ url: achado.texto });
  } catch (e) {
    // O caminho inteiro é opcional: nada aqui pode derrubar a abertura do app
    // nem o handler de retomada, que faz meia dúzia de outras coisas depois.
    diagC('area de transferencia: ' + ((e && e.message) || e));
  } finally {
    clipConferindo = false;
  }
}

// ===== O FEEDBACK MORA NA INTERFACE DE ORIGEM =====
//
// NÃO existe alerta flutuante neste app: a resposta de uma ação nasce onde a
// ação nasceu. Nada de camada por cima da tela levando a informação para longe
// do alvo de foco. (`tools/smoke.mjs` trava isto por estrutura, não por nome —
// o próximo toast pode se chamar qualquer coisa.)
//
// OS CANAIS, todos in-place:
//  · `pulsar(btn, tipo)` — o botão tocado responde (adicionar/favoritar/copiar).
//  · `notaNoItem(id, texto, tipo)` — a LINHA do item, prefixada ao subtítulo, no
//    desenho do selo "● No ar". Para fatos sobre um item de lista.
//  · `previewBusy(...).falhar(motivo)` — o cartão sobre a preview, para o que
//    aconteceria nela e não aconteceu.
//  · `statusPasta(id, texto)` — o contador da própria pasta.
//  · `falarNoOta` / `falarNoPacote` / `#otaRow` — o rótulo do controle empresta
//    a si mesmo por alguns segundos e volta.
//  · `#castMsg` — a linha de estado da folha de conexão.
//  · `appConfirm` — o ÚNICO caso sem interface de origem (compartilhamento que
//    chega de fora e falha inteiro). Toma o foco e exige um toque.
//
// Caminho novo sem onde responder: a pergunta certa não é "qual camada uso?" —
// é "por que esta ação não tem uma interface?".

// ===== O PULSO NO PRÓPRIO BOTÃO (v5.106) =====
// É este o feedback de adicionar/favoritar, e não a faixa de aviso: o dedo já
// está no botão e o olho também, e com dois destinos lado a lado (as
// Ferramentas têm "Cronograma" e "Favoritos") uma mensagem genérica não diria
// em qual dos dois se tocou.
//
// `tipo`: 'ok' (entrou) | 'dup' (já estava lá) | 'erro'. A distinção é o ponto:
// "já estava nos favoritos" é a resposta que impede a duplicação acidental, e
// ela precisa ser visivelmente diferente de "adicionado".
//
// Quando o botão tocado já saiu de cena — a folha do acervo, por exemplo, que
// fecha porque o download pode levar minutos —, `responder` devolve `false` e
// QUEM CHAMOU decide onde a frase aparece: o cartão sobre a preview ou a folha
// de origem. (A faixa flutuante `avisar()` saiu na v5.207.)
const PULSO_MS = 1100;

// "Está na tela?" não é `isConnected`: as folhas deste app fecham por
// `opacity: 0` (o nó continua no documento), e a barra de seleção some pelo
// atributo `hidden`. Sem os dois testes, o pulso "aconteceria" numa folha
// fechada e o caminho ficaria mudo — que é justamente o defeito que ele veio
// resolver.
function visivelNaTela(el) {
  if (!el || !el.isConnected) return false;
  if (el.offsetParent === null) return false;            // display:none em algum ancestral
  return !el.closest('.popup-backdrop:not(.open)');      // folha fechada
}

function pulsar(btn, tipo) {
  if (!visivelNaTela(btn)) return false;
  clearTimeout(btn._pulsoTimer);
  const classes = ['btn-pulso', 'btn-pulso--' + (tipo || 'ok')];
  btn.classList.remove('btn-pulso--ok', 'btn-pulso--dup', 'btn-pulso--erro');
  // Reinicia a transição quando o mesmo botão é tocado duas vezes seguidas:
  // sem o reflow, o segundo pulso não se distingue do primeiro ainda em cena.
  void btn.offsetWidth;
  btn.classList.add(...classes);
  btn._pulsoTimer = setTimeout(() => {
    btn.classList.remove('btn-pulso', 'btn-pulso--ok', 'btn-pulso--dup', 'btn-pulso--erro');
  }, PULSO_MS);
  return true;
}

// Responde no BOTÃO. Devolve `false` quando ele não está mais na tela (folha
// fechada, lista redesenhada) — e é o CHAMADOR que decide o que fazer com
// isso, porque só ele sabe qual é a interface de origem daquela ação.
//
// Até a v5.206 havia aqui um `else avisar(texto)`: um ponto único de decisão
// que mandava toda resposta órfã para a faixa flutuante. Era cômodo e era
// justamente o mecanismo que levava a informação para longe do alvo de foco —
// e ele escondia a pergunta que importa, que é por que uma ação ficou sem
// interface em que responder. O parâmetro `texto` saiu com ele; nenhum dos
// catorze chamadores o passava.
function responder(btn, tipo) {
  return pulsar(btn, tipo);
}

// ===== O ECO: "o comando saiu" =====
// `pulsar` TROCA o conteúdo do botão por um ✓ — certo para salvar/copiar,
// errado para o transporte (o ▶ virando ✓ esconde o ícone que diz o estado).
// O eco é um anel curto em accent que NÃO mexe no conteúdo. Ele existe porque
// a resposta de verdade está a ~1 s quando a projeção são as telas da rede
// (ver `cmd`), e um botão que não responde por um segundo é tocado de novo.
// DELEGADO por SELETOR, nunca um `eco()` por handler: os handlers do
// transporte são vários e um esquecido seria um botão mudo sem ninguém notar.
// Botão desabilitado não emite `click`, então o eco nunca promete o que não
// aconteceu.
const ECO_MS = 420;
// ===== QUEM RECEBE O ECO: TODO BOTÃO CUJO RESULTADO MORA NO TELÃO =====
// Ele valia para `.transport .t-btn, .mixer-mid button` — e `.mixer-mid` NÃO
// EXISTE desde a v1.3.8, quando o mixer saiu (o próprio CSS lista
// `.mixer-top/mid/bottom` entre o que foi removido). Isto é: na prática o eco
// era exclusivo dos seis botões do transporte, e foi assim que o operador o
// leu — *"o feedback único dos botões de play, com bordas flutuantes
// totalmente exclusivo no app"*.
//
// Ele está certo sobre a exclusividade e o conserto não é apagar o sinal: a
// razão dele continua valendo, e vale IGUAL para os outros botões que mandam
// alguma coisa para a projeção. O que faltava era a REGRA — um anel que
// aparece em seis botões e em nenhum outro parece enfeite daqueles seis; o
// mesmo anel em todos os que falam com o telão é um sinal do app.
//
// A regra: **o eco é de quem MANDA ALGO PARA A PROJEÇÃO.** Ele não se
// confunde com a resposta de toque (`--press`, o recuo mais a luz), que diz
// "recebi o dedo" e vale para todo controle. Este diz outra coisa — "o comando
// saiu" —, e existe porque a resposta de verdade pode estar a ~1 s quando a
// projeção são as telas da rede (ver `cmd`).
//
// Fica de fora o que NÃO vai ao telão: navegação, Configurações, a folha de
// leitura auxiliar, a lupa do acervo. Um eco ali prometeria uma viagem que não
// acontece.
const ECO_SELETOR = [
  '.transport .t-btn',        // repetir, playlist, ⏮, ▶, ■, ⏭
  '.slide-btn',               // os dois que flanqueiam a preview: passam slide NO telão
  // A CORTINA E O MUDO SAÍRAM DAQUI (v1.4.36) — eles entraram na v1.3.14 e o
  // operador os devolveu: *"ainda estou vendo a onda azulada de feedback de
  // toque tanto no botão de mudo quanto no botão da cortina"*. Duas razões
  // independentes, e cada uma bastaria:
  //
  //  · **Eles TROCAM O DESENHO.** São alternadores: no mesmo instante do toque
  //    o ícone vira o oposto (imagem ↔ imagem riscada, som ↔ som riscado) e a
  //    cor vai para `--stage-alert`. Isso É "o comando saiu", dito pelo próprio
  //    botão. O eco é a segunda vez que a mesma coisa é dita — e os ⏮/▶/⏭ do
  //    transporte, que ficam, não têm esse sinal: é justamente por isso que ele
  //    existe lá.
  //  · **Eles não têm CAIXA.** O eco desenha `inset: 0` + `border-radius:
  //    inherit` — a caixa do botão. Um `.t-btn` tem uma; um `.pv-fab` tem
  //    `background: none` e é só o traço sobre a projeção. O que aparecia era um
  //    retângulo AZUL (`--accent`, um token de cromo) materializando-se em volta
  //    de um ícone solto, em cima da imagem no ar — a mesma classe de erro que a
  //    família `--stage-*` existe para impedir (ver "O PALCO NÃO TEM TEMA").
  //
  // A COLUNA DA TELA CHEIA FICA, e a assimetria é deliberada: lá os ⏮/▶/⏭ não
  // trocam de desenho e são a única superfície que existe — sem o eco eles não
  // teriam como dizer que o comando saiu.
  '.pv-fsctl .pv-fab',        // a coluna da tela cheia (sem TV, ela É a projeção)
  '.misc-project',            // "Projetar no telão"
].join(', ');

document.addEventListener('click', (ev) => {
  const alvo = ev.target && ev.target.closest ? ev.target.closest(ECO_SELETOR) : null;
  if (!alvo || alvo.disabled) return;
  clearTimeout(alvo._ecoTimer);
  alvo.classList.remove('btn-eco');
  // Reinicia a animação quando o mesmo botão é tocado duas vezes seguidas —
  // sem o reflow o segundo toque não se distingue do primeiro ainda em cena, e
  // é exatamente no toque repetido que o eco precisa aparecer.
  void alvo.offsetWidth;
  alvo.classList.add('btn-eco');
  alvo._ecoTimer = setTimeout(() => { alvo.classList.remove('btn-eco'); }, ECO_MS);
}, true);

// (`avisar()` SAIU na v5.207, com a faixa flutuante que ela desenhava. Ver o
//  bloco "O FEEDBACK MORA NA INTERFACE DE ORIGEM", acima, para onde foi cada
//  uma das mensagens que passavam por aqui.)

// ===== Proporção da preview =====
// A preview é uma MINIATURA FIEL do telão, e isso só se sustenta se ela tiver a
// PROPORÇÃO do telão. Ela era 16:9 fixo — contra uma TV 2,17:1 (3120×1440, um
// dongle comum), toda mídia mentia: uma imagem que preenche a preview ganha
// barras laterais na projeção, um vídeo enquadrado aqui aparece cortado lá, e um
// versículo que cabe em 3 linhas no telão aparecia truncado no meio da palavra.
//
// O resto do dimensionamento (letra, camada de texto) já é em `cq*`, relativo ao
// container — ou seja, INVARIANTE DE ESCALA: com a proporção certa, os mesmos
// números dão a mesma composição numa caixa de 280px e num telão de 3120px. Por
// isso a calibração da preview deixou de ser uma cópia com valores próprios e
// passou a repetir exatamente os do Display: o que fazia os valores divergirem
// era a proporção errada, não o tamanho.
//
// Sem TV conectada a projeção é a própria preview em tela cheia, no celular —
// então o alvo passa a ser a tela do aparelho em paisagem.
// Limites: a preview divide a linha com os dois botões de estrofe, que precisam
// continuar sendo alvos de toque utilizáveis. Telas reais de projeção ficam
// entre 4:3 e ~2,2:1, bem dentro da faixa; um painel 32:9 bateria no teto e
// deixaria de ser proporcional — troca deliberada, e o clamp é o que impede a
// linha de estourar.
const PV_AR_MIN = 1.2;
const PV_AR_MAX = 2.4;
function applyPreviewAspect(tv) {
  let ar = 16 / 9;
  if (tv && tv.w > 0 && tv.h > 0) {
    ar = tv.w / tv.h;
  } else if (window.screen && screen.width && screen.height) {
    // Projeção por tela cheia: a "tela real" é este aparelho, deitado.
    ar = Math.max(screen.width, screen.height) / Math.min(screen.width, screen.height);
  }
  ar = Math.min(PV_AR_MAX, Math.max(PV_AR_MIN, ar));
  document.documentElement.style.setProperty('--pv-ar', String(ar));
}
// Vale também no navegador (sem ponte): ali o alvo é sempre a tela do aparelho.
applyPreviewAspect(null);

// ===== Wallpaper personalizado =====
// A cortina do telão (e da preview) aceita uma imagem no lugar do gradiente
// padrão. O blob mora no state `wallpaper`, compartilhado com o Display; o
// comando `wallpaper` só avisa que mudou.
let pvWallpaperUrl = null;
// Há imagem escolhida agora? O seletor do popup de Exibição usa o mesmo
// componente segmentado do Preenchimento, mas nunca acendia nenhum segmento —
// o operador não tinha como saber qual wallpaper estava no telão sem fechar o
// popup e olhar a preview, e "Padrão" (que descarta a imagem) parecia um
// estado desmarcado em vez de uma ação.
let customWallpaper = false;

async function applyPvWallpaper() {
  let blob = null;
  try { blob = await AVDB.getState('wallpaper'); } catch (_) { /* segue no padrão */ }
  customWallpaper = blob instanceof Blob;
  renderWallTile();
  if (pvWallpaperUrl) { URL.revokeObjectURL(pvWallpaperUrl); pvWallpaperUrl = null; }
  if (blob instanceof Blob) {
    pvWallpaperUrl = URL.createObjectURL(blob);
    pvWallEl.style.backgroundImage = 'url("' + pvWallpaperUrl + '")';
  } else {
    pvWallEl.style.backgroundImage = '';
  }
}

// Reduz a imagem escolhida para caber num telão 1080p. O operador costuma
// pegar uma foto do próprio celular (12 MP): guardar e decodificar isso a
// cada abertura do Display seria desperdício puro — a cortina nunca passa da
// resolução da TV.
async function fitWallpaperImage(file) {
  const MAX_W = 1920;
  const MAX_H = 1080;
  const url = URL.createObjectURL(file);
  try {
    const img = await new Promise((resolve, reject) => {
      const im = new Image();
      im.onload = () => resolve(im);
      im.onerror = reject;
      im.src = url;
    });
    const scale = Math.min(1, MAX_W / img.naturalWidth, MAX_H / img.naturalHeight);
    if (scale >= 1) return file; // já cabe: guarda o original, sem recomprimir
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(img.naturalWidth * scale);
    canvas.height = Math.round(img.naturalHeight * scale);
    canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
    const blob = await new Promise((res) => canvas.toBlob(res, 'image/jpeg', 0.9));
    return blob || file; // toBlob pode falhar em imagens enormes
  } catch (_) {
    return file; // formato exótico: guarda como veio
  } finally {
    URL.revokeObjectURL(url);
  }
}

async function setWallpaper(file) {
  const blob = file ? await fitWallpaperImage(file) : null;
  await AVDB.setState('wallpaper', blob);
  customWallpaper = blob instanceof Blob;
  renderWallTile();
  await applyPvWallpaper();
  // O Display lê o mesmo state — o comando só avisa que mudou.
  AVDB.sendCommand({ type: 'wallpaper' });
}

// ===== trabalho pesado com o app minimizado =====
// No app nativo, minimizar faz o Android tratar o processo como descartável e
// congelá-lo — e a sincronização (hinos, álbuns, Bíblia, pastas) morria no
// meio. Como ninguém fica olhando a tela enquanto um hinário inteiro baixa,
// isso acontecia justamente no uso normal.
//
// A ponte declara esse trabalho ao sistema (SyncService, um serviço em
// primeiro plano). Aqui só contamos quantos downloads estão em curso, para
// ligar no primeiro e desligar no último — dois downloads simultâneos não
// podem fazer o primeiro a terminar desligar a proteção do outro.
//
// No NAVEGADOR tudo isto é no-op: a aba já continua baixando em segundo plano.
let bgWorkCount = 0;

// ===== E QUANTO DELE É ROTINA, e não pedido do operador (v1.2.28) =====
//
// `bgWorkCount` responde ao SISTEMA: *"o processo pode ser congelado?"*. Para
// isso ele está certo do jeito que está — a varredura de cifras é rede, e rede
// congelada morre no meio como qualquer outra.
//
// Mas ele passou a responder uma segunda pergunta, e para essa ele está errado:
// *"é hora de perguntar sobre a atualização?"* (`horaRuimParaPerguntar`). A
// varredura de cifras e a de letras rodam SOZINHAS na abertura, sobre o acervo
// inteiro — MEDIDO num aparelho: 309 hinos num hinário e 145 no outro, mais
// dezenas de álbuns, numa passada só. Enquanto ela corre, a pergunta não
// aparece; e ela corre justamente na janela em que o operador abre o app.
//
// É a MESMA armadilha que a v5.151 já pagou com o espelho: uma condição quase
// sempre verdadeira não adia a pergunta, ela a APAGA. E o desfecho aqui é o
// pior que este canal sabe produzir — com o shell abaixo do `minShell`, a
// válvula recusa toda base web e o APK é a única saída; suprimir a pergunta
// deixa o aparelho preso, em silêncio, sem nunca ser avisado do que o destrava.
//
// A distinção é *quem pediu*: o que o OPERADOR mandou fazer (baixar um álbum,
// a Bíblia, uma pasta) é o que ele está esperando terminar. A ROTINA de
// manutenção ninguém pediu, ninguém está olhando, e ela é retomável de graça —
// o que já está guardado não é pedido de novo na abertura seguinte.
let bgRotinaCount = 0;

function bgWorkBegin(rotina) {
  if (!window.__NATIVE__) return;
  if (rotina) bgRotinaCount++;
  if (++bgWorkCount === 1) AVNative.keepAlive(true);
}

// O trabalho que o OPERADOR está esperando — o único que adia uma pergunta.
function bgWorkPedido() { return bgWorkCount - bgRotinaCount > 0; }

function bgWorkEnd(rotina) {
  if (!window.__NATIVE__) return;
  if (rotina && bgRotinaCount > 0) bgRotinaCount--;
  if (bgWorkCount > 0 && --bgWorkCount === 0) {
    // O contador de rotina ZERA junto, pela mesma razão do `bgTasks.clear()`
    // abaixo: um `withBgRotina` que perdesse o `finally` (renderer morto no meio)
    // deixaria a pergunta suprimida pelo resto da sessão, que é exatamente o
    // defeito que esta separação existe para tirar.
    bgRotinaCount = 0;
    // O `clear()` é a rede de segurança para uma tarefa que ficou órfã, mas
    // ele SOZINHO deixava o compasso ligado para sempre: com o `bgTasks` já
    // vazio, o `bgTaskEnd` que vinha depois achava o Map vazio, o `delete`
    // devolvia false e nem o `bgPacerSync()` nem o envio final rodavam — o
    // `setInterval` de 250 ms vazava pelo resto da sessão, batendo na ponte a
    // cada 2 s com uma tarefa vazia (notificação "Baixando mídias" presa) e,
    // pior, fazendo o próximo `bgTaskStart` reusar um pacer órfão.
    // Sincronizar aqui torna `bgWorkEnd` idempotente: a ordem entre ele e o
    // `bgTaskEnd` deixa de importar.
    bgTasks.clear();
    bgPacerSync();
    bgTaskSend(true);
    AVNative.keepAlive(false);
  }
}

// Envolve um trecho pesado. O `finally` é o ponto crítico: uma falha de rede
// no meio do download não pode deixar o serviço (e o wake lock) ligado.
async function withBgWork(fn) {
  bgWorkBegin();
  try { return await fn(); } finally { bgWorkEnd(); }
}

// O MESMO, para a ROTINA que ninguém pediu (ver `bgRotinaCount`): protege o
// processo do congelamento igual, e NÃO adia a pergunta da atualização.
async function withBgRotina(fn) {
  bgWorkBegin(true);
  try { return await fn(); } finally { bgWorkEnd(true); }
}

// ===== progresso na notificação do sistema =====
// A notificação do serviço em primeiro plano era estática ("Baixando mídias").
// Com o app minimizado — o uso normal durante uma sincronização — ela é a ÚNICA
// janela para o download, e não dizia quanto falta nem se ainda anda.
//
// REGISTRO de tarefas, não um slot único: o app tem downloads SIMULTÂNEOS (é
// por isso que `bgWorkCount` conta, em vez de ser um booleano) — entrar na aba
// Bíblia enquanto um lote de álbuns baixa dispara os dois ao mesmo tempo. Com
// um slot só, as duas tarefas escreviam uma por cima da outra: o `done` de uma
// aparecia com o `total` e o `startedAt` da outra, e a estimativa pulava de
// 1h30 para 2h40 e voltava. Cada tarefa agora tem seu próprio registro.
const bgTasks = new Map();
let bgTaskSeq = 0;

function bgTaskStart(label, total) {
  if (!window.__NATIVE__) return 0;
  const id = ++bgTaskSeq;
  bgTasks.set(id, {
    label, total: Math.max(1, total), done: 0,
    // FILA de exibição: nomes que entraram em download e ainda não passaram
    // pela linha da notificação. É um buffer, não o conjunto do que está no ar
    // — cada nome sai daqui UMA vez, o que torna a lista fluida e sem repetir.
    fila: [],
    spot: null,          // o nome que está na linha agora
    spotAt: 0,           // desde quando — o compasso decide quando trocar
    lastEventAt: 0,      // último evento REAL (item entrou/saiu, passo) — ver idleMs
    // Marcado no PRIMEIRO item concluído, não aqui: antes dele corre o
    // preparo (índice, varredura do que falta) e contá-lo como se fosse tempo
    // de download inflava a primeira estimativa, que depois despencava.
    firstStepAt: 0,
    shownEta: 0,
    etaAt: 0,        // quando shownEta foi suavizada pela última vez
    // `done`/`total` em BYTES em vez de itens — ver `bgTaskBytes`. Fica no
    // registro (e não num parâmetro do envio) porque a notificação mostra a
    // tarefa DOMINANTE, e um lote de músicas pode estar rodando ao lado de um
    // download de vídeo: a unidade é de cada tarefa, não do envio.
    bytes: false,
  });
  bgPacerSync();
  bgTaskSend(true);
  return id;
}

// COMPASSO da exibição — uma FILA, não um espelho do que está no ar.
//
// A concorrência existe para reduzir o tempo PROPORCIONAL de cada item: se os
// 6 juntos levam X, cada um custou X/6. A exibição segue essa mesma conta —
// cada nome ocupa a linha por X/6 e sai, um depois do outro. É deliberadamente
// ILUSTRATIVO e não em tempo real: os nomes vêm de um buffer do que já entrou
// em download, escoado num ritmo constante.
//
// Duas coisas que só a fila dá:
// - **Não repete.** Um rodízio entre os 6 em voo trazia o mesmo nome de volta
//   várias vezes; a fila consome cada um UMA vez, e a lista anda para a frente.
// - **Não engasga.** Os 6 workers andam em lockstep — começam e terminam
//   quase juntos —, então os eventos chegam em rajada (meia dúzia em poucos
//   ms) seguida de segundos de silêncio. Sem buffer, a rajada rendia UMA troca
//   de nome e o resto era descartado: o nome ficava parado até a rajada
//   seguinte, que é exatamente a sensação de travado.
//
// O ritmo é MEDIDO, não chutado: `decorrido / concluídos` é o tempo médio por
// item — com 6 em paralelo, o tal X/6. Se a fila acumula (rede acelerou), o
// escoamento acelera junto para a lista não ficar exibindo passado velho.
const BG_TICK_MS = 250;        // granularidade do compasso
const BG_SPIN_MIN = 400;       // abaixo disso ninguém consegue ler
const BG_SPIN_MAX = 5000;      // acima disso parece parado
const BG_SPIN_PADRAO = 1200;   // antes do 1º item concluído não há média
const BG_FILA_FOLGA = 3;       // itens em espera tolerados sem acelerar
const BG_REENVIO_MS = 2000;    // reenvio mínimo (faz o idleMs crescer na tela)
const BG_STALL_MS = 90000;     // mesmo limiar do lado nativo (SyncService)

let bgPacer = null;
function bgPacerSync() {
  if (bgTasks.size && !bgPacer) {
    bgPacer = setInterval(bgPacerTick, BG_TICK_MS);
  } else if (!bgTasks.size && bgPacer) {
    clearInterval(bgPacer); bgPacer = null;
  }
}

// Quanto tempo cada nome fica na linha, em ms.
function bgSpinMs(t) {
  let ms = (t.done > 0 && t.firstStepAt)
    ? (Date.now() - t.firstStepAt) / t.done
    : BG_SPIN_PADRAO;
  // Fila crescendo = a exibição está atrasada em relação ao download; escoa
  // proporcionalmente mais rápido em vez de acumular um passado cada vez mais
  // antigo.
  if (t.fila.length > BG_FILA_FOLGA) ms /= (t.fila.length / BG_FILA_FOLGA);
  return Math.min(BG_SPIN_MAX, Math.max(BG_SPIN_MIN, ms));
}

function bgPacerTick() {
  const now = Date.now();
  let mudou = false;
  for (const t of bgTasks.values()) {
    if (!t.fila.length) continue;
    // Travado: a lista CONGELA. Animar durante uma queda de rede esconderia
    // justamente o que precisa ser visto — e aqui não há novidade nenhuma para
    // mostrar, só passado. O `idleMs` cresce e os dois sinais concordam.
    if (t.lastEventAt && (now - t.lastEventAt) >= BG_STALL_MS) continue;
    if (t.spot && (now - t.spotAt) < bgSpinMs(t)) continue;
    t.spot = t.fila.shift();
    t.spotAt = now;
    mudou = true;
  }
  if (mudou || (now - bgLastSentAt) >= BG_REENVIO_MS) bgTaskSend(true);
}

// O `total` é OPCIONAL e chega DEPOIS, pela mesma razão do `bgTaskBytes`: há
// trabalho cujo tamanho só se conhece depois de começar. Uma apresentação é o
// caso — quantas páginas ela tem só se sabe quando o arquivo abre, e até lá a
// tarefa precisa existir (é ela que segura o processo vivo). Sem esta via a
// alternativa era abrir com `total = 1`, e aí os dois números que a notificação
// existe para dar não existem: barra em 0% do começo ao fim e ETA ZERO, porque
// `bgTaskEta` precisa de pelo menos um item concluído para ter média.
//
// Ele só SOBE de 1: um total que encolhesse faria a barra andar para trás.
function bgTaskStep(id, done, label, total) {
  if (!window.__NATIVE__) return;
  const t = bgTasks.get(id);
  if (!t) return;
  if (!t.firstStepAt) t.firstStepAt = Date.now();
  if (total > 1) t.total = total;
  t.done = done;
  t.lastEventAt = Date.now();
  if (label) t.label = label;
  bgTaskSend(false);
}

// Progresso em BYTES — a tarefa passa a ser medida em bytes transferidos, não
// em itens concluídos (v5.118).
//
// O registro nasceu contando ITENS, e para um lote é a unidade certa: 54
// músicas, 1189 capítulos. Mas o download de UM vídeo do YouTube abria a tarefa
// com `total = 1`, e aí os dois números que a notificação existe para dar
// simplesmente não existiam: a barra ficava em 0% do começo ao fim, e
// `bgTaskEta` devolvia ZERO porque ela precisa de pelo menos um item concluído
// para ter uma média. Ou seja, o caso em que a notificação é a ÚNICA janela —
// app minimizado, centenas de MB, minutos de espera — era o caso em que ela não
// dizia nada.
//
// Os bytes sempre estiveram à mão: o shell os reporta a cada MB pelo
// `onProgresso` do `ytFetch`. Faltava um canal para eles. Como percentual e ETA
// são RAZÕES, toda a matemática que já existe vale sem mudar uma linha — trocar
// a unidade é só isto. Quem muda é a apresentação, e essa é a bandeira `bytes`
// que viaja até o `SyncService`.
//
// O `total` vem AQUI e não no `bgTaskStart` porque ele só é conhecido na
// primeira resposta do servidor. Pelo mesmo motivo o `firstStepAt` é marcado no
// primeiro byte: a estimativa passa a medir a taxa de transferência real, sem
// contar a extração (que roda antes e pode levar segundos).
function bgTaskBytes(id, lidos, total) {
  if (!window.__NATIVE__) return;
  const t = bgTasks.get(id);
  if (!t || !(total > 0)) return;
  t.bytes = true;
  t.total = total;
  if (!t.firstStepAt) t.firstStepAt = Date.now();
  t.done = Math.min(lidos, total);
  t.lastEventAt = Date.now();
  bgTaskSend(false);
}

// Um item concreto entrou em download: entra na FILA de exibição. É isto que
// dá a impressão de progresso — "23 de 54" é um número abstrato, "002. Ó
// Adorai o Senhor" é o que o operador reconhece, e ver a lista andar é o que
// mostra que a coisa se move.
//
// Quem decide QUANDO ele aparece é o compasso (bgPacerTick), não este momento:
// os 6 workers entram quase juntos, e mostrar a rajada crua daria uma troca
// só. O primeiro item de todos é promovido na hora, para a notificação não
// nascer sem nome.
function bgItemStart(id, nome) {
  if (!window.__NATIVE__ || !nome) return;
  const t = bgTasks.get(id);
  if (!t) return;
  t.lastEventAt = Date.now();
  if (!t.spot) {
    t.spot = nome; t.spotAt = t.lastEventAt;
    // `force`: este envio vem logo depois do de abertura da tarefa e seria
    // engolido pelo piso — e aí o PRIMEIRO nome da lista nunca apareceria,
    // porque o compasso já o teria substituído no primeiro passo.
    bgTaskSend(true);
    return;
  }
  t.fila.push(nome);
}

// Fluxo SEQUENCIAL (um item por vez, com vários `continue` no laço). Vai para
// a mesma fila: como ali os itens chegam um a um, o ritmo medido acompanha o
// real e a fila praticamente não acumula.
function bgItemOnly(id, nome) {
  bgItemStart(id, nome);
}

// Um item concluiu. Ele NÃO entra na fila aqui — já entrou ao começar; o que
// isto registra é que a tarefa deu sinal de vida, que é o que separa "está
// devagar" de "travou" (ver `idleMs` e BG_STALL_MS).
function bgItemEnd(id, nome) {
  if (!window.__NATIVE__ || !nome) return;
  const t = bgTasks.get(id);
  if (t) t.lastEventAt = Date.now();
}

function bgTaskEnd(id) {
  if (!window.__NATIVE__) return;
  if (bgTasks.delete(id)) { bgPacerSync(); bgTaskSend(true); }
}

// Tempo restante de UMA tarefa, em ms. 0 = ainda não dá para estimar.
//
// Média desde o primeiro item concluído (decorrido/concluídos x restantes),
// depois SUAVIZADA: itens têm tamanhos muito diferentes (uma música só Cantado
// x outra com Playback, capa e imagens de estrofe) e a rede oscila, então o
// valor bruto sobe e desce. A suavização é assimétrica de propósito — cai
// rápido, sobe devagar: uma contagem regressiva que aumenta parece quebrada,
// mesmo quando o número novo está certo.
// A suavização é por TEMPO (constante de tempo), não por chamada. Antes era um
// fator fixo aplicado a cada chamada, o que amarrava a estabilidade do número à
// frequência com que alguém pedia a estimativa: o compasso da fila
// (`bgPacerTick`) a chama muito mais vezes que os eventos chamavam, e o mesmo
// fator faria o valor exibido colar no bruto e voltar a pular — justamente o
// que a suavização existe para evitar. Com constante de tempo, o comportamento
// visto é o mesmo seja qual for a cadência das chamadas.
//
// Os valores reproduzem o que havia antes (0,5 e 0,15 por item, a ~1,7 s por
// item concluído com 6 em paralelo): τ = −Δt / ln(1 − α).
const ETA_TAU_DOWN = 2500;    // reage rápido quando a estimativa melhora
const ETA_TAU_UP = 10000;     // sobe com cautela
function bgTaskEta(t) {
  if (!t.firstStepAt || t.done <= 0 || t.total <= t.done) return 0;
  const now = Date.now();
  const bruto = ((now - t.firstStepAt) / t.done) * (t.total - t.done);
  if (!t.shownEta) { t.shownEta = bruto; t.etaAt = now; return bruto; }
  const dt = Math.max(0, now - (t.etaAt || now));
  t.etaAt = now;
  const a = 1 - Math.exp(-dt / (bruto < t.shownEta ? ETA_TAU_DOWN : ETA_TAU_UP));
  t.shownEta += (bruto - t.shownEta) * a;
  return t.shownEta;
}

// O Android limita a taxa de atualização de notificação e passa a DESCARTAR o
// excesso — sem freio, a barra parece travada. O piso vale só para a
// atualização de ROTINA (`bgTaskStep`, em que só o contador andou); tudo o que
// precisa chegar na hora passa `force`.
//
// HOUVE um segundo piso (250 ms) "escolhido pelo chamador" por um parâmetro
// `destaque`. Ele foi REMOVIDO porque nenhum dos cinco chamadores o passava —
// era código morto, e mexer na constante não produzia efeito nenhum no
// aparelho. Quem de fato dá o ritmo do item que entra em download é o compasso
// (`bgPacerTick`, BG_TICK_MS = 250 ms), que envia com `force` sempre que o
// nome na linha troca; o resultado na tela é o mesmo, e agora só há um
// mecanismo para entender. Repor o piso curto aqui seria PIOR que o `force`:
// o primeiro nome de uma tarefa nasce a poucos ms do envio de abertura e
// ficaria retido até o batimento de 2 s.
const BG_NOTIF_MIN_MS = 700;        // rotina: só o contador andou
let bgLastSentAt = 0;
function bgTaskSend(force) {
  const now = Date.now();

  // Com mais de uma tarefa em curso, a notificação mostra a DOMINANTE — a de
  // maior tempo restante, que é a que decide quando tudo acaba — e diz quantas
  // outras existem. Somar tarefas de naturezas diferentes (capítulos da Bíblia
  // + músicas) num total único daria um número que não significa nada.
  let alvo = null, etaAlvo = -1;
  for (const t of bgTasks.values()) {
    const eta = bgTaskEta(t);
    if (!alvo || eta > etaAlvo) { alvo = t; etaAlvo = eta; }
  }
  if (!alvo) {
    bgLastSentAt = now;
    try { AVNative.bgProgress({ label: '', done: 0, total: 0, etaMs: 0, items: [] }); } catch (_) {}
    return;
  }
  const outras = bgTasks.size - 1;
  // UM nome por vez (ver bgItemStart): `items` continua sendo lista só porque
  // é o formato da ponte — quem escolhe qual mostrar é o rodízio, não o Kotlin.
  const item = alvo.spot || null;
  if (!force && now - bgLastSentAt < BG_NOTIF_MIN_MS) return;
  bgLastSentAt = now;
  try {
    AVNative.bgProgress({
      label: alvo.label + (outras > 0 ? ' (+' + outras + ')' : ''),
      done: alvo.done,
      total: alvo.total,
      etaMs: Math.max(0, Math.round(etaAlvo)),
      items: item ? [item] : [],
      bytes: !!alvo.bytes,
      // Há quanto tempo NADA acontece nesta tarefa. É o que separa "travado" de
      // "esta faixa é grande" — sem isso os dois casos são a mesma tela parada.
      idleMs: alvo.lastEventAt ? Math.max(0, now - alvo.lastEventAt) : 0,
    });
  } catch (_) { /* shell antigo: a notificação segue estática */ }
}

// ===== Diálogo padrão do app (confirmações / prompts) =====
// Modal no tema do app que substitui os confirm()/prompt() nativos em TODA
// interação do tipo (excluir, renomear, avisos). Assíncrono: retorna uma
// Promise — confirm → true/false; prompt → string (OK) ou null (cancelar).
const appDialogEl = document.getElementById('appDialog');
const appDialogTitleEl = document.getElementById('appDialogTitle');
const appDialogMsgEl = document.getElementById('appDialogMsg');
const appDialogItensEl = document.getElementById('appDialogItens');
const appDialogRodapeEl = document.getElementById('appDialogRodape');
const appDialogInputEl = document.getElementById('appDialogInput');
const appDialogOkEl = document.getElementById('appDialogOk');
const appDialogCancelEl = document.getElementById('appDialogCancel');
let appDialogResolve = null;
// O DIÁLOGO QUE NÃO SE PERDE NUM TOQUE FORA (v5.249).
//
// O padrão do app é o do navegador: tocar no fundo cancela, e para quase tudo
// isso está certo — é a saída barata de quem abriu a coisa errada. Para a
// ATUALIZAÇÃO não estava: aquele diálogo aparece sozinho, no meio do que o
// operador estava fazendo, e um toque em qualquer lugar da tela o resolvia como
// "Deixar para depois" — que silencia a pergunta pelo resto da sessão. O
// operador perdia a atualização por um gesto que nem sabia ter dado.
//
// O que ele NÃO faz é prender ninguém: o "Deixar para depois" continua ali, e o
// Esc/voltar continua valendo, porque os dois são a recusa DELIBERADA. O que
// deixa de existir é a recusa por acidente.
let appDialogFixo = false;

function closeAppDialog(result) {
  document.removeEventListener('keydown', onAppDialogKey);
  appDialogEl.classList.remove('open');
  const r = appDialogResolve; appDialogResolve = null;
  if (r) r(result);
}
// Esc cancela TAMBÉM o confirm. O comentário de `appConfirm` sempre prometeu
// isso, mas o único handler de Escape morava no keydown do INPUT — que só
// existe (e só tem foco) no prompt. O handler vive no documento e só está
// registrado enquanto o diálogo está aberto; resolve exatamente como o botão
// Cancelar do tipo em cena (false no confirm, null no prompt). O Esc vindo do
// input não resolve duas vezes: o `closeAppDialog` de lá remove este listener
// antes de o evento borbulhar até o documento.
function onAppDialogKey(e) {
  if (e.key !== 'Escape') return;
  closeAppDialog(appDialogInputEl.hidden ? false : null);
}
function openAppDialog(opts) {
  const { title, message, okText, cancelText, input, value, placeholder, fixo, itens, rodape, perigo } = opts || {};
  return new Promise((resolve) => {
    // Se já houver um diálogo aberto, resolve o anterior como cancelado.
    if (appDialogResolve) closeAppDialog(input ? null : false);
    appDialogResolve = resolve;
    appDialogFixo = !!fixo;
    appDialogTitleEl.textContent = title || '';
    appDialogTitleEl.hidden = !title;
    appDialogMsgEl.textContent = message || '';
    appDialogMsgEl.hidden = !message;
    // A LINHA DO TEMPO, quando o chamador tem uma. `textContent` por item, e
    // não uma string com `innerHTML`: hoje o único chamador é a atualização, e
    // o texto dela sai de um arquivo que veio da REDE dentro de um zip. O
    // caminho seguro custa uma linha e não precisa ser reconsiderado nunca.
    appDialogItensEl.replaceChildren();
    const lista = Array.isArray(itens) ? itens.filter((t) => t && String(t).trim()) : [];
    for (const t of lista) {
      const li = document.createElement('li');
      li.textContent = String(t);
      appDialogItensEl.appendChild(li);
    }
    appDialogItensEl.hidden = lista.length === 0;
    appDialogRodapeEl.textContent = rodape || '';
    appDialogRodapeEl.hidden = !rodape;
    appDialogOkEl.textContent = okText || 'OK';
    // `perigo: true` = a confirmação APAGA alguma coisa. Ela troca o azul
    // primário pelo par destrutivo da paleta — a mesma regra que o "Remover do
    // dispositivo" de um álbum e o "Desconectar" de uma tela já seguiam. É a
    // única tela do app em que uma decisão é irreversível, e era a única em que
    // a cor não dizia isso.
    appDialogOkEl.classList.toggle('perigo', !!perigo);
    appDialogOkEl.classList.toggle('primary', !perigo);
    // `cancelText: null` é o diálogo de AVISO: ele não pergunta nada, só conta
    // o que aconteceu, e um "Cancelar" ao lado do "Entendi" ofereceria uma
    // escolha que não existe.
    appDialogCancelEl.hidden = cancelText === null;
    appDialogCancelEl.textContent = cancelText || 'Cancelar';
    if (input) {
      appDialogInputEl.hidden = false;
      appDialogInputEl.value = value || '';
      appDialogInputEl.placeholder = placeholder || '';
    } else {
      appDialogInputEl.hidden = true;
    }
    appDialogEl.classList.add('open');
    document.addEventListener('keydown', onAppDialogKey);
    if (input) setTimeout(() => { appDialogInputEl.focus(); appDialogInputEl.select(); }, 60);
  });
}
// confirm → resolve true (OK) / false (cancelar/fora/Esc)
function appConfirm(opts) { return openAppDialog({ okText: 'Confirmar', cancelText: 'Cancelar', ...opts, input: false }); }
// prompt → resolve o texto (OK) / null (cancelar/fora/Esc)
function appPrompt(opts) { return openAppDialog({ okText: 'OK', cancelText: 'Cancelar', ...opts, input: true }); }

appDialogOkEl.addEventListener('click', () => closeAppDialog(appDialogInputEl.hidden ? true : appDialogInputEl.value));
appDialogCancelEl.addEventListener('click', () => closeAppDialog(appDialogInputEl.hidden ? false : null));
appDialogEl.addEventListener('click', (e) => {
  if (e.target !== appDialogEl || appDialogFixo) return;
  closeAppDialog(appDialogInputEl.hidden ? false : null);
});
appDialogInputEl.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') { e.preventDefault(); closeAppDialog(appDialogInputEl.value); }
  else if (e.key === 'Escape') closeAppDialog(null);
});

// ===== popup de playlist =====
// A fila em cena vira um PACOTE: um item do Cronograma que, ao ser tocado,
// devolve exatamente estes itens nesta ordem. O nome sai do primeiro item mais
// a contagem — "Abertura · 4 itens" é o que se reconhece numa lista de culto.
// O BOTÃO DE PACOTE EMPRESTA O PRÓPRIO RÓTULO (v5.207) — mesmo mecanismo do
// `#otaRow` e do rótulo de versão: a resposta nasce onde o toque nasceu, e o
// botão volta a ser o que era. O `<span>` de texto é o segundo filho (o
// primeiro é o glifo), e é só ele que troca.
let pacoteFalaTimer = null;
const PACOTE_ROTULO = 'Guardar como pacote no Cronograma';
function falarNoPacote(texto, ms) {
  if (!plPackEl) return;
  const alvo = plPackEl.querySelector('span:not(.msym)');
  if (!alvo) return;
  clearTimeout(pacoteFalaTimer);
  alvo.textContent = texto;
  pacoteFalaTimer = setTimeout(() => { alvo.textContent = PACOTE_ROTULO; }, ms || 3000);
}

async function guardarPacote() {
  // Só MÍDIA entra num pacote. Uma cena de roteiro dentro dele abriria a porta
  // para um pacote que contém outro pacote — e dois que se contenham
  // mutuamente fariam `abrirPacote` chamar `send` em laço, travando o app. Um
  // pacote é uma FILA de reprodução; cena de roteiro se põe no Cronograma.
  const midias = plItems.filter((m) => !isCue(m));
  const ids = midias.map((m) => m.id);
  // Este é o único caso em que o pulso NÃO basta: ele diz "não deu", e aqui o
  // que o operador precisa saber é POR QUE (a fila tem menos de dois itens).
  // Motivo não cabe num botão — então os dois sinais saem juntos.
  if (ids.length < 2) {
    pulsar(plPackEl, 'erro');
    // O MOTIVO NO PRÓPRIO BOTÃO (v5.207). O comentário acima dizia que "motivo
    // não cabe num botão" e por isso os dois sinais saíam juntos — o pulso aqui
    // e a frase numa faixa no topo da tela. Cabe: o botão tem rótulo, e ele
    // empresta o rótulo por três segundos. É o mesmo mecanismo do `#otaRow` e
    // do rótulo de versão, e mantém a resposta onde o toque aconteceu.
    falarNoPacote('Precisa de 2 itens ou mais');
    return;
  }
  // O nome sai do primeiro item QUE ENTRA no pacote (`midias[0]`), não de
  // `plItems[0]`: com uma cena de roteiro no topo da fila, a sugestão citava
  // um item que o filtro acabara de deixar de fora.
  const sugestao = midias[0].name + ' +' + (ids.length - 1);
  const nome = await appPrompt({
    title: 'Guardar pacote', message: 'Nome do pacote:', value: sugestao, okText: 'Guardar',
  });
  if (nome === null) return;
  const rec = await criarCue('group', { ids }, (nome || '').trim() || sugestao, 'imports', plPackEl);
  if (!rec) { responder(plPackEl, 'erro', 'Não foi possível guardar'); return; }
  setTimeout(closePlPopup, PULSO_MS);
}

/**
 * ESVAZIAR A FILA (v5.309), a pedido do operador: *"faça um botão para limpar
 * toda a playlist tocando agora"*. Tirar item a item era o único caminho, e uma
 * fila de culto tem oito ou dez linhas — cada uma com a própria pergunta.
 *
 * ELA NÃO MEXE NO QUE ESTÁ NO AR, e é a MESMA semântica do excluir de uma linha
 * da fila (ver `renderPlaylist`): sair da fila não é sair de uma lista de
 * acervo. O item que está projetando segue projetando, e o que estiver guardado
 * no Cronograma, nos Favoritos, numa pasta ou no slot avulso segue inteiro — o
 * `listSet` coleta só o que NENHUMA outra lista aponta, que é a mesma conta que
 * o `listRemove` faz item a item. Limpar dez de uma vez é dez remoções, não uma
 * operação nova.
 *
 * A forma com FUNÇÃO (`() => []`), não `listSet('playlist', [])`: ela roda
 * dentro da transação que grava, e é a única que não perde um item acrescentado
 * entre a leitura e a escrita.
 */
async function limparPlaylist() {
  await AVDB.listSet('playlist', () => []);
  await load();
}

// ============================================================================
// O HISTÓRICO DO CULTO (v1.2.0)
// ============================================================================
//
// Pedido do operador: *"crie um botão de histórico, que lista todos os itens
// que já tocaram naquela sessão. deve ser uma lista tipo a do cronograma, mas
// sem opções de exclusão, mas com opções de enviar para o cronograma. essa
// lista deve ter a hora de cada apresentação de cada item e deve ser apagada a
// cada nova sessão do app"*.
//
// ## Por que ele resolve algo que nenhuma lista do app resolve
//
// O Cronograma é o que se PRETENDE tocar, a playlist é o que vem A SEGUIR, e as
// duas são voláteis por natureza — um toque numa mídia da Biblioteca redefine a
// fila inteira. Nenhuma das duas responde *"o que eu já toquei hoje?"*, e é essa
// a pergunta de quem monta o culto seguinte ou precisa repetir um louvor que
// entrou de improviso e não ficou guardado em lugar nenhum.
//
// ## O QUE ELE GUARDA, e por que não é só um id
//
// Um item pode DEIXAR DE EXISTIR entre tocar e ser consultado: a prateleira
// `avulsos` tem teto de três, e o coletor recolhe os bytes de quem sai da última
// lista (ver o KDoc de `LISTS` em `db.js`). Guardar só o id daria uma lista de
// linhas em branco no fim de um culto normal. Por isso o nome e o subtítulo são
// copiados NO INSTANTE da projeção — o histórico é um registro do que aconteceu,
// e um registro não pode depender de o objeto ainda estar lá.
//
// ## ELE ATRAVESSA SESSÕES, E ELAS NÃO SE MISTURAM (v1.4.31)
//
// Pedido do operador: *"adicione um sistema extra, armazene os dados entre
// sessões, separando as sessões. mantenha os itens usáveis apenas na categoria
// da sessão atual. para as sessões antigas, deixe usáveis apenas itens padrões
// do sistema, como músicas, textos, links e etc... que não dependem de um
// arquivo que pode já ter sido excluído, para não ser obrigado a manter aquele
// arquivo"*.
//
// Isto REVOGA o "apagada a cada nova sessão" do pedido original, e as duas
// coisas não se contradizem porque o que substitui o apagamento é a SEPARAÇÃO:
// a sessão de hoje continua sozinha no topo da folha, e as antigas ficam abaixo
// dela, com cabeçalho próprio (ver `renderHistorico`).
//
// **Uma SESSÃO é uma carga do documento**, e essa continua sendo a única
// definição que o lado web tem como observar — minimizar não abre sessão nova,
// fechar e reabrir abre. Ela nasce na PRIMEIRA projeção, não na carga: um app
// aberto e fechado sem projetar nada não deixa uma sessão vazia na lista de
// quem for consultá-la no sábado seguinte.
//
// **A GRAVAÇÃO SAI DO CAMINHO QUENTE.** O `send` é o ponto por onde todo
// caminho de projeção passa, e uma escrita no IndexedDB ali era o argumento
// que manteve este artefato em memória por vinte e nove versões. Ela continua
// fora: `historicoRegistrar` mexe só na memória e AGENDA a gravação
// (`HIST_GRAVA_MS`), que coalesce a rajada de um culto inteiro em uma escrita a
// cada dois segundos de silêncio. O preço, dito: os últimos segundos podem se
// perder numa morte do renderer — e é por isso que a saída de cena
// (`visibilitychange`) força a gravação pendente.
//
// **`updateState`, nunca `setState`**: só ela espera o COMMIT (ver o KDoc dela
// em `db.js`). Um histórico que perde a última projeção porque a transação
// ficou em voo é o defeito exato que este lote existe para não ter.
const HIST_MAX = 300;
// QUANTAS SESSÕES FICAM. Um culto por sábado, mais dois menores na semana: doze
// cobrem cerca de um mês de programação, que é o alcance da pergunta ("o que
// tocamos no sábado passado?"). Acima disso o custo não é tela — a folha rola —,
// é a leitura na abertura e o tamanho da chave de `state`.
const HIST_SESSOES_MAX = 12;
// O SILÊNCIO que fecha a rajada. Dois segundos: mais curto devolve uma escrita
// por item numa sequência de toques, mais longo alarga a janela que uma morte
// do renderer leva junto.
const HIST_GRAVA_MS = 2000;

// AS SESSÕES, da mais RECENTE para a mais antiga — e cada uma com os itens na
// mesma ordem, pelo mesmo motivo: uma lista de culto cresce para trás, e o que
// interessa é o que acabou de sair de cena.
let historico = [];
// A SESSÃO DESTA CARGA. `null` até a primeira projeção — ver acima.
let histSessao = null;
let histGravaTimer = 0;

/**
 * A RECEITA: o mínimo para trazer o item de volta SEM depender de um arquivo.
 * É ela que decide o que uma sessão antiga ainda oferece (ver `histAcionavel`),
 * e por isso ela nasce no instante da projeção — o registro pode não existir
 * mais quando alguém abrir a folha.
 *
 * Três formas, e cada uma responde a uma das coisas que o operador nomeou:
 *
 *  · **cena** (`textos`) — a cena de roteiro inteira cabe no descritor
 *    (versículo, mensagem, cronômetro). Ela se remonta sem tocar em byte nenhum.
 *  · **link** (`links`) — o endereço, e o id do YouTube para reaproveitar um
 *    registro que já exista em vez de criar o segundo.
 *  · **acervo** (`músicas`) — `folder` + `srcName`, a chave NATURAL de tudo que
 *    vem de uma coleção ou de uma pasta do aparelho. O `id` não serve: um hino
 *    reapagado e rebaixado ganha id novo, e é justamente esse o caso.
 *
 * SEM RECEITA fica o que só existe porque um arquivo foi importado ou
 * compartilhado — exatamente o que o coletor recolhe, e exatamente o que o
 * operador não quer ser obrigado a manter.
 */
function histReceita(item) {
  if (!item) return null;
  if (isCue(item)) return { t: 'cena', c: item.cue, d: item.data || {} };
  if (item.kind === 'youtube' && item.url) {
    return { t: 'link', u: item.url, y: item.youtubeId || null };
  }
  if (item.folder && item.srcName) return { t: 'acervo', f: item.folder, s: item.srcName };
  return null;
}

/**
 * REGISTRA UMA PROJEÇÃO. Chamado de UM lugar só: o `send`, que é o ponto por
 * onde todos os caminhos passam (o toque na lista, o avanço automático da fila,
 * o ⏮/⏭ do transporte, a notificação nativa, o roteiro). É o mesmo argumento
 * das três guardas do topo daquela função e do `diagC` ao lado desta chamada.
 *
 * **REPETIÇÃO CONSECUTIVA NÃO VIRA LINHA NOVA.** `repeat: 'one'` reenvia o
 * mesmo id a cada fim de faixa, e um louvor deixado em laço durante a oração
 * encheria a lista inteira com trinta cópias do mesmo nome — enterrando tudo o
 * que veio antes, que é justamente o que se foi consultar. O que se atualiza é
 * a HORA: a linha passa a dizer quando a última volta começou.
 */
function historicoRegistrar(id, item) {
  if (!id) return;
  // A SESSÃO NASCE AQUI, na primeira projeção desta carga — ver o cabeçalho.
  if (!histSessao) {
    histSessao = { inicio: Date.now(), itens: [] };
    historico.unshift(histSessao);
    if (historico.length > HIST_SESSOES_MAX) historico.length = HIST_SESSOES_MAX;
  }
  const itens = histSessao.itens;
  const topo = itens[0];
  if (topo && topo.id === id) { topo.hora = Date.now(); topo.vezes++; histAgendarGravacao(); return; }
  itens.unshift({
    id,
    // O NOME E O SUBTÍTULO SÃO CÓPIAS, não ponteiros — ver o cabeçalho: o
    // registro pode não existir mais quando alguém abrir a folha.
    nome: (item && item.name) || 'Item',
    sub: subtituloItem(item),
    hora: Date.now(),
    vezes: 1,
    rec: histReceita(item),
  });
  // Um culto não passa de algumas dezenas de projeções; o teto existe para o
  // caso patológico (o app aberto a semana inteira), não para o uso normal.
  if (itens.length > HIST_MAX) itens.length = HIST_MAX;
  histAgendarGravacao();
}

// A GRAVAÇÃO, COALESCIDA. Um só temporizador: cada projeção o reagenda, e a
// rajada de uma sequência de toques rende uma escrita.
function histAgendarGravacao() {
  clearTimeout(histGravaTimer);
  histGravaTimer = setTimeout(histGravar, HIST_GRAVA_MS);
}

// GRAVA O QUE ESTÁ NA MEMÓRIA. A `fn` é SÍNCRONA e devolve o retrato inteiro —
// este documento é o único escritor desta chave (o Display não registra
// projeção nenhuma), então não há metade de ninguém a preservar; o que
// `updateState` compra aqui é o COMMIT confirmado.
async function histGravar() {
  clearTimeout(histGravaTimer);
  histGravaTimer = 0;
  const retrato = historico.map((s) => ({ inicio: s.inicio, itens: s.itens.slice() }));
  try { await AVDB.updateState('historico', () => retrato); } catch (_) { /* o culto não para por isto */ }
}

/**
 * LÊ O QUE FICOU DAS SESSÕES ANTERIORES. Chamado na abertura, ANTES de qualquer
 * projeção — se rodasse depois, o `unshift` da sessão nova seria sobrescrito
 * pela lista lida do disco.
 *
 * Saneia por FORMA, e não por confiança: a chave é gravada por este app, mas
 * uma versão antiga (ou um bundle interrompido no meio de uma escrita) pode
 * deixar qualquer coisa ali, e uma folha que lança no `forEach` é uma folha que
 * não abre.
 */
async function histCarregar() {
  let bruto = null;
  try { bruto = await AVDB.getState('historico'); } catch (_) { return; }
  if (!Array.isArray(bruto)) return;
  historico = bruto
    .filter((s) => s && Array.isArray(s.itens) && s.inicio)
    .map((s) => ({ inicio: s.inicio, itens: s.itens.filter((h) => h && h.id).slice(0, HIST_MAX) }))
    .slice(0, HIST_SESSOES_MAX);
}

// HH:MM, que é a precisão da pergunta ("antes ou depois do sermão?"). Segundos
// só acrescentariam dígitos a uma coluna que existe para ser percorrida de
// relance.
function histHora(t) {
  const d = new Date(t);
  return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
}

// O DIA de uma sessão, para o cabeçalho dela. Escrito à mão e não por
// `toLocaleDateString`: os nomes de dia e a ordem dos campos saem dos dados de
// locale do navegador, que variam entre um aparelho e o Chromium do oráculo —
// e o que se ganharia com isso é zero, porque as duas formas que interessam
// ("Hoje", "Ontem") não vêm de locale nenhum.
const HIST_DIAS = ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb'];
function histDia(t) {
  const d = new Date(t);
  const hoje = new Date();
  const dia = (x) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();
  const passados = Math.round((dia(hoje) - dia(d)) / 86400000);
  if (passados <= 0) return 'Hoje';
  if (passados === 1) return 'Ontem';
  return HIST_DIAS[d.getDay()] + ', ' + String(d.getDate()).padStart(2, '0')
    + '/' + String(d.getMonth() + 1).padStart(2, '0');
}

/**
 * ESTE ITEM AINDA FAZ ALGUMA COISA? Na sessão ATUAL, tudo faz — é o culto que
 * está acontecendo, e o registro que acabou de tocar está vivo por construção.
 * Numa sessão antiga, só o que tem RECEITA: é a linha exata do pedido — nada
 * aqui pode obrigar o aparelho a guardar um arquivo para o histórico continuar
 * funcionando.
 */
function histAcionavel(h, atual) { return atual || !!h.rec; }

/**
 * ACHA (ou REMONTA) O ITEM. A ordem é o que importa:
 *
 *  1. **pelo id**, que é de graça e devolve o registro ORIGINAL — o caso normal
 *     dentro do culto de hoje;
 *  2. **pela receita**, e só aí. `acervo` PROCURA (folder + srcName é a chave
 *     natural; o id de um hino rebaixado é outro); `cena` e `link` CRIAM, que é
 *     o que os torna independentes de qualquer arquivo.
 *
 * `destino` é a lista em que um item CRIADO nasce — `avulsos` quando o toque é
 * para projetar (a prateleira volátil, com o teto de três que `fixarAvulso`
 * mantém) e `imports` quando o operador mandou ao Cronograma. Sem lista, o
 * registro nasceria órfão e o `gcOrfaos` da abertura seguinte o apagaria.
 *
 * DEVOLVE `{ rec, criado }`, e o segundo campo não é enfeite: **ACHAR e CRIAR
 * terminam em lugares diferentes**. Um item criado já NASCE no destino; um
 * achado (pelo id, ou pelo par `folder`/`srcName` de uma coleção) está onde
 * sempre esteve, e ainda precisa entrar na lista. Sem a distinção, o "ao
 * Cronograma" de um hino reapagado responderia "adicionado" sem adicionar nada
 * — o pior desfecho desta folha, porque ele é indistinguível do certo até o
 * sábado seguinte.
 */
async function histResolver(h, destino) {
  const vivo = await AVDB.getMedia(h.id);
  if (vivo) return { rec: vivo, criado: false };
  const r = h.rec;
  if (!r) return null;
  if (r.t === 'acervo') {
    let irmaos = [];
    try { irmaos = await AVDB.filesByFolder(r.f); } catch (_) { return null; }
    const achado = irmaos.find((x) => x.srcName === r.s);
    return achado ? { rec: achado, criado: false } : null;
  }
  if (r.t === 'cena') {
    return { rec: await AVDB.addCue(r.c, r.d, { name: h.nome, list: destino }), criado: true };
  }
  if (r.t === 'link') {
    // Um link do MESMO vídeo já guardado é reaproveitado: dois registros para o
    // mesmo endereço seriam duas linhas iguais na lista, e o segundo não
    // acrescenta nada (não há bytes que os distingam). É a mesma regra do
    // caminho "Online" da busca.
    const pronto = r.y ? await AVDB.mediaByYoutube(r.y, 'youtube') : null;
    if (pronto) return { rec: pronto, criado: false };
    const thumb = r.y
      ? (await thumbYoutube(r.y)) || ('https://img.youtube.com/vi/' + r.y + '/hqdefault.jpg')
      : null;
    return { rec: await AVDB.addUrlMedia(r.u, {
      kind: 'youtube', type: 'video/youtube', name: h.nome,
      thumb,
      youtubeId: r.y || null, list: destino,
    }), criado: true };
  }
  return null;
}

/**
 * A FOLHA. Linha do Cronograma, com duas subtrações e uma soma.
 *
 *  - **sem excluir e sem reordenar**: o histórico é o que JÁ aconteceu, e um
 *    fato não se edita. (Foi o pedido, e ele é o certo: um destrutivo aqui
 *    apagaria o registro sem apagar nada do aparelho.) O que se apaga é a
 *    SESSÃO inteira, ou o histórico todo — ver `histLimpar`.
 *  - **sem tocar na linha** quando ela não tem o que oferecer (ver
 *    `histAcionavel`): num culto antigo, um arquivo importado é só o registro
 *    de que ele tocou.
 *  - **mais a HORA**, que é a coluna pela qual esta lista se lê.
 *
 * OS CABEÇALHOS DE SESSÃO SÃO `<li>` DA MESMA LISTA (v1.4.31), e não um bloco
 * por fora: a folha rola inteira, e um cabeçalho fora do `<ul>` ficaria parado
 * sobre o conteúdo errado.
 */
function renderHistorico() {
  histListEl.innerHTML = '';
  // A faixa do "limpar tudo" some com a lista vazia, e cancela uma pergunta
  // pendente ao sumir — a mesma regra do `#plClearFaixa`.
  if (!historico.length && histClearFaixaEl.classList.contains('confirmando')) fecharConfirmacaoNaLinha();
  histClearFaixaEl.hidden = !historico.length;
  if (!historico.length) {
    histListEl.innerHTML = '<li class="empty">Nada projetado ainda.'
      + '<br>Cada item que for ao telão aparece aqui, com a hora — e o histórico'
      + ' fica guardado, separado por sessão.</li>';
    return;
  }
  historico.forEach((ses) => {
    const atual = ses === histSessao;
    histListEl.appendChild(histCabecalho(ses, atual));
    ses.itens.forEach((h) => histListEl.appendChild(histLinha(h, atual)));
  });
  // E A CONFERÊNCIA DE TODAS AS LINHAS VEM DEPOIS DO DESENHO, nunca antes: a
  // folha abre com a lista JÁ na tela e as linhas mortas esmaecem no quadro
  // seguinte. Perguntar ao banco antes de desenhar trocaria uma marca que
  // chega tarde por uma folha que abre vazia, que é o defeito pior.
  histConferirVivos();
}

/**
 * O CABEÇALHO DE UMA SESSÃO — o rótulo do dia e a saída dela.
 *
 * O SUBTÍTULO É A JANELA DE HORAS, e ela sai das pontas da própria lista (que
 * é do mais novo para o mais antigo, daí o último item ser o primeiro fato).
 * Ela responde o que o rótulo do dia não responde: se a sessão de sábado é a
 * do culto da manhã ou a do ensaio da noite.
 */
function histCabecalho(ses, atual) {
  const li = document.createElement('li');
  li.className = 'hist-sessao';
  li.dataset.histSessao = String(ses.inicio);

  const txt = document.createElement('div');
  txt.className = 'hist-sessao-txt';
  const tit = document.createElement('span');
  tit.className = 'hist-sessao-tit';
  tit.textContent = atual ? 'Esta sessão' : histDia(ses.inicio);
  const sub = document.createElement('span');
  sub.className = 'hist-sessao-sub';
  const n = ses.itens.length;
  const ultimo = ses.itens[n - 1];
  const primeiro = ses.itens[0];
  const janela = ultimo
    ? histHora(ultimo.hora) + (primeiro !== ultimo ? '–' + histHora(primeiro.hora) : '')
    : histHora(ses.inicio);
  sub.textContent = n + (n === 1 ? ' item' : ' itens') + ' · ' + janela;
  txt.append(tit, sub);

  const acoes = document.createElement('div');
  acoes.className = 'hist-sessao-acoes';
  const limpar = document.createElement('button');
  limpar.type = 'button';
  limpar.className = 'row-btn';
  limpar.title = 'Limpar esta sessão do histórico';
  limpar.setAttribute('aria-label', limpar.title);
  limpar.appendChild(msym(ICON.del));
  limpar.addEventListener('click', (e) => {
    e.stopPropagation();
    pedirConfirmacaoNaLinha(limpar, {
      ok: 'Limpar',
      dica: 'Apaga só o registro desta sessão — nenhum arquivo do aparelho é tocado',
      aoConfirmar: () => histLimpar(ses.inicio),
    });
  });
  acoes.appendChild(limpar);

  li.append(txt, acoes);
  return li;
}

// UMA LINHA. `atual` decide o que ela oferece — ver `histAcionavel`.
function histLinha(h, atual) {
  const li = document.createElement('li');
  li.className = 'row-item';
  const acionavel = histAcionavel(h, atual);

  const row = document.createElement('div');
  row.className = 'row';

  const hora = document.createElement('span');
  hora.className = 'hist-hora';
  hora.textContent = histHora(h.hora);

  const texto = document.createElement('div');
  texto.className = 'row-text';
  const nome = document.createElement('span');
  nome.className = 'row-name'; nome.textContent = h.nome;
  const sub = document.createElement('span');
  sub.className = 'row-sub';
  // "×3" é a repetição consecutiva colapsada (ver `historicoRegistrar`) — o
  // mesmo recurso que a linha do tempo do Registro usa, e pela mesma razão:
  // ele encurta sem apagar nada.
  //
  // "só registro" É A EXPLICAÇÃO DA LINHA INERTE, e ela é obrigatória: uma
  // linha que não responde ao toque e não diz por quê é indistinguível de um
  // app quebrado. Duas palavras, no fim do subtítulo, onde o que se lê antes
  // continua sendo o que identifica o item.
  sub.textContent = (h.vezes > 1 ? '×' + h.vezes + ' · ' : '') + (h.sub || '')
    + (acionavel ? '' : (h.sub ? ' · ' : '') + 'só registro');
  texto.append(nome, sub);
  row.append(hora, texto);

  if (!acionavel) {
    li.classList.add('hist-arquivada');
    li.appendChild(row);
    return li;
  }

  // AO CRONOGRAMA — a única ação da linha, e a que o pedido nomeia. Ela é
  // ASSÍNCRONA na decisão de existir: só o banco sabe se o item ainda está
  // lá, e perguntar a ele por linha, a cada render, é barato (a folha é
  // desenhada quando alguém a abre, não a 400 ms como o acervo).
  const add = document.createElement('button');
  add.type = 'button';
  add.className = 'row-btn';
  add.title = 'Adicionar ao Cronograma';
  add.setAttribute('aria-label', 'Adicionar ao Cronograma');
  add.appendChild(msym(ICON.cronoAdd));
  add.addEventListener('click', async (e) => {
    e.stopPropagation();
    // A CONFERÊNCIA SE REPETE NO TOQUE, e não só no desenho: entre abrir a
    // folha e tocar o botão o item pode ter saído (o coletor roda em TODA
    // remoção de lista, e a prateleira `avulsos` despeja sozinha). Sem ela,
    // `adicionarNasListas` gravaria um id órfão e o Cronograma ganharia uma
    // linha que não abre nada — pior que o botão ter falhado.
    //
    // NUMA SESSÃO ANTIGA a resolução pode CRIAR o item, e aí ele já nasce no
    // Cronograma (`destino`) — chamar `adicionarNasListas` depois disso seria
    // a segunda gravação do mesmo id, com o aviso dizendo "já está lá" sobre
    // algo que acabou de chegar. Um item ACHADO segue o caminho de sempre: ele
    // está onde sempre esteve, e ainda precisa entrar na lista.
    const alvo = await histResolver(h, 'imports');
    if (!alvo) { histMarcarSumido(li, add, true); return; }
    if (alvo.criado) {
      responder(add, 'ok', rotuloItem(h.nome) + 'adicionado ao Cronograma');
      await load();
      return;
    }
    await adicionarNasListas(['imports'], alvo.rec.id, h.nome, add);
  });
  row.appendChild(add);

  // ===== E O TOQUE NA LINHA PROJETA (v1.2.3) =====
  //
  // Pedido do operador: *"pode fazer o item do histórico ser executável
  // diretamente no toque"*. A v1.2.0 tinha recusado isto — o argumento era
  // que uma lista consultada durante o culto não podia mandar coisa ao telão
  // por um toque de rolagem —, e ele **não se sustenta**: um `click` não sai
  // de um gesto que rolou a lista (o navegador o cancela), que é a mesma
  // proteção sob a qual a folha da playlist já projeta desde sempre.
  //
  // O que sobra é a razão de o histórico existir: ele é a lista de onde se
  // repete um louvor que entrou de improviso e não ficou guardado em lista
  // nenhuma. Obrigar a passar pelo Cronograma para tocá-lo de novo é cobrar
  // dois toques e uma linha permanente por uma repetição.
  //
  // **`projetarItem`, e não um `send` cru:** é a mesma porta do toque numa
  // linha da Biblioteca, e é ela que distingue CENA de MÍDIA (uma cena vai
  // direto ao `send`; uma mídia redefine a fila para si antes). Duplicar essa
  // decisão aqui era garantir que as duas divergissem no primeiro ajuste.
  //
  // **E A FOLHA FECHA.** Ela cobre a preview e o transporte, que é onde a
  // resposta ao toque aparece — projetar por trás dela seria o operador
  // tocando e não vendo nada acontecer. É o mesmo desfecho do "Guardar como
  // pacote" da playlist, pela mesma razão.
  //
  // **NUMA SESSÃO ANTIGA o item pode ser CRIADO agora**, e ele nasce em
  // `avulsos`: a prateleira volátil é o destino certo de quem só quer projetar
  // — quem quiser guardar tem o botão ao lado, que nasce em `imports`.
  row.addEventListener('click', async (e) => {
    if (e.target.closest('.row-btn')) return;
    const alvo = await histResolver(h, 'avulsos');
    if (!alvo) { histMarcarSumido(li, add, false); return; }
    // O CRIADO passa pelo teto da prateleira; o ACHADO já tem dono e não entra
    // nela — pô-lo ali despejaria um avulso de verdade por um item que não
    // precisa de abrigo.
    if (alvo.criado) await fixarAvulso(alvo.rec.id);
    closeHistPopup();
    await projetarItem(alvo.rec);
  });

  li.appendChild(row);
  li.dataset.histId = h.id;
  return li;
}

/**
 * A LINHA CUJO ARQUIVO SAIU DO APARELHO. Ela FICA — o histórico responde o que
 * aconteceu, e apagá-la apagaria o fato —, mas perde a ação e ganha o motivo no
 * subtítulo.
 *
 * `tocado` separa os DOIS chamadores, e a diferença é toda a razão do
 * parâmetro: a varredura acha isto sozinha, e um pulso vermelho num botão que
 * ninguém encostou é o app alarmando sobre nada. Vindo do toque, o pulso é a
 * resposta ao dedo — e o botão só sai DEPOIS dele, senão o quadro que responde
 * é o mesmo em que ele desaparece.
 */
function histMarcarSumido(li, add, tocado) {
  if (!li.classList.contains('hist-sumiu')) {
    li.classList.add('hist-sumiu');
    const sub = li.querySelector('.row-sub');
    if (sub) sub.textContent = 'Não está mais no aparelho';
  }
  if (!add) return;
  if (tocado && responder(add, 'erro')) setTimeout(() => add.remove(), PULSO_MS);
  else add.remove();
}

// Quais linhas ainda têm arquivo no banco. Em PARALELO (as leituras são
// independentes, e em série uma folha de quarenta linhas pagaria quarenta idas
// ao IndexedDB uma atrás da outra — a mesma razão do `Promise.all` de
// `ensureBibleMeta`).
//
// SÓ A SESSÃO ATUAL (v1.4.31), e não é economia: numa sessão antiga a linha sem
// receita já nasce inerte, e a linha COM receita não depende do id — perguntar
// por ela marcaria como "sumida" justamente o item que a receita traz de volta.
async function histConferirVivos() {
  const cab = histListEl.querySelector('.hist-sessao');
  const atual = histSessao && cab && cab.dataset.histSessao === String(histSessao.inicio);
  if (!atual) return;
  const linhas = [];
  for (let no = cab.nextElementSibling; no && !no.classList.contains('hist-sessao'); no = no.nextElementSibling) {
    if (no.dataset.histId) linhas.push(no);
  }
  await Promise.all(linhas.map(async (li) => {
    const vivo = await AVDB.getMedia(li.dataset.histId);
    // A FOLHA PODE TER SIDO REDESENHADA no meio (outra abertura): mexer num
    // `li` órfão é inofensivo, mas conferir é de graça e diz a intenção.
    if (!vivo && li.isConnected) histMarcarSumido(li, li.querySelector('.row-btn'), false);
  }));
}

/**
 * LIMPA. `inicio` é a sessão; sem ele, tudo — as duas metades do pedido
 * *"limpar todo o histórico ou por sessões"*.
 *
 * Limpar a sessão ATUAL a REMOVE, e não a esvazia: `histSessao` volta a `null`
 * e a próxima projeção abre uma sessão nova, com o `inicio` da hora em que ela
 * de fato recomeçou. Uma sessão esvaziada guardaria um cabeçalho dizendo
 * "0 itens" com a hora de um culto que o operador acabou de mandar apagar.
 *
 * NENHUM ARQUIVO É TOCADO — daqui não sai `listRemove` nenhum, e por isso o
 * coletor não roda: o que se apaga é o registro do que aconteceu.
 */
async function histLimpar(inicio) {
  if (inicio == null) { historico = []; histSessao = null; }
  else {
    historico = historico.filter((s) => s.inicio !== inicio);
    if (histSessao && histSessao.inicio === inicio) histSessao = null;
  }
  await histGravar();
  renderHistorico();
}

function openHistPopup() {
  renderHistorico();
  histPopupEl.classList.add('open');
}
function closeHistPopup() {
  // FECHAR CANCELA A PERGUNTA — a mesma regra da gaveta da linha e da folha da
  // playlist: perder a pergunta custa um toque, herdar um "sim" pendente
  // apagaria um histórico na abertura seguinte.
  fecharConfirmacaoNaLinha();
  histPopupEl.classList.remove('open');
}

function openPlPopup() {
  renderPlaylist();
  plPopupEl.classList.add('open');
}
function closePlPopup() {
  // FECHAR CANCELA A PERGUNTA — a mesma regra da gaveta da linha: o erro
  // possível aqui é o seguro, porque perder a pergunta custa um toque e herdar
  // um "sim" pendente esvaziaria a fila na próxima abertura da folha.
  fecharConfirmacaoNaLinha();
  plPopupEl.classList.remove('open');
}

// ===== eventos =====
fileEl.addEventListener('change', async () => {
  const files = Array.from(fileEl.files || []);
  let naoAbriu = null;
  for (const file of files) {
    // APRESENTAÇÃO escolhida por aqui (navegador, ou shell antigo sem o seletor
    // do sistema): vira páginas como qualquer outra. Sem este desvio um `.pptx`
    // entraria como mídia 'other' — importada e impossível de projetar. O PDF
    // não tem caminho AQUI: quem o desenha é o shell, que precisa do arquivo e
    // não de um `File` já lido — e é justamente por isso que, no app, este
    // botão abre o seletor do sistema.
    if (ehApresentacao(file)) {
      let rec = null;
      if (ehPptx(file)) rec = await pptxImportar(file, nomeSemExtensao(file.name), {});
      else deckUltimoErro = window.__NATIVE__
        ? 'PDF precisa do seletor de arquivos do app (instale a versão nova)'
        : 'o navegador não desenha PDF; use o app';
      if (!rec) naoAbriu = nomeSemExtensao(file.name);
      continue;
    }
    // O tipo vem da EXTENSÃO, com o do arquivo como reserva: um seletor de
    // documentos do Android pode entregar `application/octet-stream`, e aí a
    // mídia entraria como 'other' — importada mas impossível de reproduzir.
    // Mesma regra do share e da sincronização de pastas.
    const type = guessMediaType(file.name) || file.type;
    const kind = AVDB.kindFromType(type);
    const { thumb, height, seconds } = await prepararMidia(file, kind);
    await AVDB.addMedia(file, {
      name: file.name.replace(/\.[^.]+$/, ''), type, kind, thumb, height, seconds,
    });
  }
  fileEl.value = '';
  // Importar sempre cai no Cronograma (lista `imports`, via addMedia), e a
  // folha da Bíblia sai da frente para o operador ver o que acabou de entrar.
  fecharBiblia();
  load();
  if (naoAbriu) await avisarNaoAbriu(naoAbriu);
});

playPauseEl.addEventListener('click', () => {
  pausaEm = Date.now();
  // Texto manual em cena SEM áudio de fundo: play/pause não faz nada (navega-se
  // pelos botões de slide). Com um áudio de fundo tocando (preview.getCurrent),
  // o play/pause controla esse áudio — a projeção do texto é independente.
  // Vale para os DOIS provedores da camada (Bíblia e Mensagem): sem a Mensagem
  // aqui, um toque no ▶ caía em `send(currentId)`, que chama clearManualText()
  // e tirava a mensagem do telão no meio do culto.
  if (pvTextActive && !preview.getCurrent()) return;
  if (playing) { cmd({ type: 'pause' }); }
  // YouTube sem player vivo no Display (fim natural ou stop manual) → recarrega
  else if (ytEnded && currentItem && currentItem.kind === 'youtube' && currentId) { send(currentId); }
  // RETOMAR só vale com a mídia AINDA EM CENA. `preview.getCurrent()` sozinho
  // não respondia isso: depois de um stop ele continua devolvendo o registro
  // durante todo o fade de saída do `clearFaded` (~0,6 s), e o `play` mandado
  // nessa janela era apagado pelo `clear` que terminava logo atrás — o ▶ não
  // fazia nada, e o operador aprendia a tocar em STOP DUAS VEZES para
  // destravar. `midiaNoAr` cai no mesmo instante em que o stop é dado, então o
  // primeiro toque no ▶ já cai no `send` e recarrega. (v5.142)
  else if (midiaNoAr && preview.getCurrent()) { cmd({ type: 'play' }); }
  else if (currentId) { send(currentId); } // após stop: recarrega e inicia do início
});
stopEl.addEventListener('click', stopClear);
slidePrevBtnEl.addEventListener('click', () => stepSlide(-1));
slideNextBtnEl.addEventListener('click', () => stepSlide(1));

// ===== Um par de botões, dois eixos =====
// UM par de ⏮/⏭ servindo aos DOIS eixos, separados pelo TEMPO do toque:
//   • toque curto → o eixo da CENA: passa estrofe quando há estrofe a passar
//     (letra, versículo ou mensagem no ar), e passa de mídia quando não há;
//   • toque longo → SEMPRE mídia (a saída para quando a cena tem estrofes e
//     mesmo assim se quer trocar de música).
//
// ISTO NÃO VALE MAIS PARA O TRANSPORTE (v1.3.5). Lá o par voltou a ter um
// significado só — MÍDIA anterior/próxima —, porque a preview passou a ser
// flanqueada por dois botões de slide de altura inteira, e um eixo escondido
// atrás do tempo do toque não se justifica quando o outro tem botão próprio a
// dois centímetros dali. O que resta aqui são as DUAS superfícies em que não
// há botão de slide nenhum e o par continua sendo tudo o que existe:
//   • a COLUNA DA TELA CHEIA (sem TV ela É a projeção, e nada mais é desenhado);
//   • a NOTIFICAÇÃO nativa, onde o eixo é dito no RÓTULO do botão
//     (`slideMode`/`slideLabel` em `pushNowPlaying`) — ali cabe rótulo, então
//     o modo nunca precisa ser adivinhado.
//
// A regra de qual eixo vale é `slideTarget()`, a MESMA nas duas. Quem executa
// continua sendo `#slidePrevBtn`/`#slideNextBtn` por `.click()`: é neles que
// `applySlideLimits` guarda "dá para passar slide agora?", e um botão
// `disabled` é no-op natural.
//
// O limiar é o mesmo `LONGPRESS` (450 ms) dos itens da biblioteca: dois tempos
// para "segurar" no mesmo app seriam duas coisas para o dedo aprender. O toque
// longo dispara NA HORA em que vence o prazo, não ao soltar.
function attachTransportStep(btn, dir) {
  let timer = null, fired = false;
  const slideBtn = () => (dir < 0 ? slidePrevBtnEl : slideNextBtnEl);
  btn.addEventListener('pointerdown', () => {
    fired = false;
    clearTimeout(timer);
    timer = setTimeout(() => { fired = true; step(dir); }, LONGPRESS);
  });
  const cancel = () => { clearTimeout(timer); timer = null; };
  ['pointerup', 'pointercancel', 'pointerleave'].forEach((ev) => btn.addEventListener(ev, cancel));
  btn.addEventListener('click', () => {
    if (fired) { fired = false; return; }   // o toque longo já agiu
    if (slideTarget()) slideBtn().click();
    else step(dir);
  });
}
// O TRANSPORTE PASSA MÍDIA E MAIS NADA (v1.3.5): sem toque longo, sem eixo a
// descobrir. Quem passa slide são os dois botões que flanqueiam a preview.
prevEl.addEventListener('click', () => step(-1));
nextEl.addEventListener('click', () => step(1));
repeatEl.addEventListener('click', cycleRepeat);


seekEl.addEventListener('input', () => { curTimeEl.textContent = fmtTime(parseFloat(seekEl.value)); });
seekEl.addEventListener('change', () => cmd({ type: 'seek', time: parseFloat(seekEl.value) }));

viewToggleEl.addEventListener('click', () => setView(view === 'visual' ? 'wallpaper' : 'visual'));
muteToggleEl.addEventListener('click', toggleMute);
// Configurações: a porta fixa no cabeçalho da tela (v1.2.0 — ela nasceu sobre a
// preview, passou pelo topo da coluna do mixer e subiu para cá, o mesmo canto do
// gêmeo do Modo Fácil). A engrenagem da preview sumia com um toque na
// miniatura, e uma configuração escondida atrás de um estado de UI é a que
// ninguém acha.
settingsBtnEl.addEventListener('click', openFadePopup);
// O HISTÓRICO abre de DENTRO de Configurações (v1.4.31) — a folha de cima
// FICA aberta atrás dele, e é o `z-index` de `#histPopup` que garante a ordem.
// Fechá-la aqui devolveria o operador à tela principal ao fechar o histórico,
// e não à folha de onde ele saiu.
histOpenRowEl.addEventListener('click', openHistPopup);
// LIMPAR TUDO. A pergunta mora na faixa do próprio botão — mesma porta do
// "Limpar a playlist", e por isso o `#histClearFaixa` existe (a confirmação
// substitui os IRMÃOS de quem a pediu).
histClearEl.addEventListener('click', (e) => {
  e.stopPropagation();
  pedirConfirmacaoNaLinha(histClearEl, {
    ok: 'Limpar',
    dica: 'Apaga o registro de todas as sessões — nenhum arquivo do aparelho é tocado',
    aoConfirmar: () => histLimpar(null),
  });
});
// O CANCELAR do cartão sobre a preview (v5.191). A preview inteira tem gestos
// próprios (arrastar o volume, tocar para tela cheia): sem o `stopPropagation`,
// cancelar um download dispararia também o de baixo.
if (pvBusyCancelEl) {
  pvBusyCancelEl.addEventListener('click', (e) => {
    e.stopPropagation();
    const fn = pvBusyCancelar;
    if (fn) fn();
  });
}
// A FOLHA DO TRANSPORTE É SEMPRE A CENA, e o parêntese vazio é quem diz isso.
// `openLyricsPopup` ganhou `(item, fonte)` na v1.2.14, e um ouvinte registrado
// POR REFERÊNCIA entrega o EVENTO no lugar do item: `lvAlvo` virava um
// `PointerEvent`, `lvItem().lyrics` era `undefined`, `cifraCabe` recusava, e
// `lvNaCena()` passava a ser falso — o que apagava também a reserva da Bíblia.
// As três fontes sumiam de uma vez e a folha abria dizendo "Nada em exibição
// com letra ou texto bíblico" para TODA música. Nada erra alto: a função que
// decide continua certa, e só a tela denuncia.
lyricsViewBtnEl.addEventListener('click', () => openLyricsPopup());
// Letra × Bíblia (só aparece com as duas em cena — ver renderLyricsView).
lyricsViewSegEl.addEventListener('click', (e) => {
  const btn = e.target.closest('.fit-opt');
  if (!btn) return;
  lvSource = btn.dataset.lvsrc;
  lvFollow = true; // trocar de fonte é pedir para ver onde ela está
  cifraRolarParar(); // e a rolagem é da FOLHA, não da aba que entrou no lugar
  renderLyricsView();
  lvScrollToCurrent(false);
});
// Rolou com o dedo? Então o operador está lendo adiante — o acompanhamento
// automático para de disputar o scroll com ele, até reabrir o popup (ou trocar
// de fonte). Sem isso, a estrofe seguinte puxaria a lista de volta no meio da
// leitura.
lyricsViewBodyEl.addEventListener('pointerdown', () => { lvFollow = false; });
lyricsViewBodyEl.addEventListener('wheel', () => { lvFollow = false; }, { passive: true });
// A ROLAGEM AUTOMÁTICA NÃO BRIGA COM O DEDO — e também não se desliga por ele.
// O avanço é relativo (`scrollTop += px`), então um arrasto só muda a origem e
// a folha segue de onde o dedo a deixou; o que não pode é somar pixels ENQUANTO
// o dedo segura. `pointercancel` entra junto porque um arrasto que vira gesto
// do sistema não emite `pointerup`, e sem ele a folha ficaria travada para
// sempre — com o botão dizendo que está rolando.
lyricsViewBodyEl.addEventListener('pointerdown', () => { cifraSegurando = true; });
for (const ev of ['pointerup', 'pointercancel', 'pointerleave']) {
  lyricsViewBodyEl.addEventListener(ev, () => { cifraSegurando = false; });
}
// FUNDO DA LETRA: as imagens que vêm baixadas com cada estrofe, mostradas ou
// removidas (o telão deixa a letra sobre preto). Um tile, dois estados.
lyricsBgTileEl.addEventListener('click', () => {
  setLyricsBg(lyricsBg === 'image' ? 'black' : 'image');
});
// ===== O FADER É UMA ESPIADA, E SÓ (v1.3.9) =====
// Ele não tem mais botão que o abra: a ÚNICA porta é a tecla física de volume,
// e a única saída é o relógio dela. Isso é o que o operador pediu — o botão de
// tela saiu, a espiada ficou —, e simplifica a máquina: `cancelVolPeek` e
// `bumpVolPeek` existiam para o caso "aberto na mão", que deixou de existir.
//
// POR QUE O APP CONTINUA CONSUMINDO A TECLA, que é o ponto do recurso: quem
// não consome deixa o ANDROID desenhar o painel de volume dele — e com
// espelhamento ativo esse painel aparece SOBRE A PROJEÇÃO, na frente da
// congregação. O fader daqui é o que o substitui: ele mora no celular, some
// sozinho, e nada disso chega ao telão.
const VOL_ANIM = 190;   // ms — casa com as durações das animações no CSS
const VOL_PEEK_MS = 2800;
let volAnimTimer = null;
let volPeekTimer = null;

function abrirFader() {
  clearTimeout(volAnimTimer);
  deckEl.classList.remove('vol-closing');
  deckEl.classList.add('vol-open');
}
function fecharFader() {
  if (!deckEl.classList.contains('vol-open')) return;
  clearTimeout(volAnimTimer);
  deckEl.classList.add('vol-closing');
  volAnimTimer = setTimeout(() => {
    deckEl.classList.remove('vol-open', 'vol-closing');
  }, VOL_ANIM);
}

// A tecla física ESPIA o fader: sem isso ela mexeria no volume de forma
// INVISÍVEL — o operador mudaria sem ver quanto ficou nem quanto ainda cabe.
// Mexer no fader enquanto ele está no ar reinicia a contagem (`peekVolume` é
// chamada de novo): recolher debaixo do dedo seria o oposto do que ela faz.
function peekVolume() {
  // No Modo Fácil a barra de volume já é a lateral inteira da tela: não há o
  // que espiar, e mexer numa classe do deck escondido não teria efeito nenhum.
  if (appMode === 'simple') return;
  abrirFader();
  clearTimeout(volPeekTimer);
  volPeekTimer = setTimeout(() => { volPeekTimer = null; fecharFader(); }, VOL_PEEK_MS);
}

// O fader continua sendo ARRASTÁVEL enquanto está no ar — ele é o mesmo
// `<input type=range>` de sempre. Quem impede `syncFader` de reescrever o valor
// debaixo do dedo é `volArrastando`, declarada JUNTO DELA lá em cima: um `let`
// aqui embaixo seria uma zona morta esperando a ordem de chamada mudar, e
// `renderControls` roda muito antes desta linha na leitura do arquivo.
volSliderEl.addEventListener('pointerdown', () => { volArrastando = true; peekVolume(); });
volSliderEl.addEventListener('pointerup', () => { volArrastando = false; });
volSliderEl.addEventListener('input', () => {
  applyVolume(parseFloat(volSliderEl.value) / 100);
  peekVolume();
});
volSliderEl.addEventListener('change', () => { volArrastando = false; persistCurrent(); });

// Se a largura mudar (ex: rotação), remede o título rolante — e o vazado da
// faixa de abas, que é posicionado em PIXELS medidos: numa rotação as células
// mudam de largura e ele ficaria sobre a aba errada. Sem animação, porque isto
// não é uma troca de aba: é a mesma aba num tamanho novo.
let titleResizeTimer = null;
window.addEventListener('resize', () => {
  clearTimeout(titleResizeTimer);
  titleResizeTimer = setTimeout(applyTitleMarquee, 150);
});

// ===== A FAIXA VISÍVEL (deslocamento com o teclado virtual) =====
// O meta viewport pede `interactive-widget=resizes-content`, o que já faz o
// navegador encolher o layout quando o teclado abre. Este handler é o FALLBACK
// para quando o hint não é honrado, e ele NÃO é hipotético: com `targetSdk` 35 o
// app é edge-to-edge, e nessa condição o `android:windowSoftInputMode=
// "adjustResize"` do manifest deixa de ter efeito — a viewport de LAYOUT
// continua do tamanho da tela e só a VISUAL diminui.
//
//   --kb      quanto o teclado come EMBAIXO.
//   --vv-top  quanto a viewport VISUAL foi rolada para baixo dentro da de
//             layout (o navegador revelando o campo em foco). É ele que arrasta
//             para fora do topo tudo o que é `position: fixed`, porque fixo é
//             fixo em relação à viewport de LAYOUT.
//
// Consumidores: `body` (desconta `--kb`) e as camadas fixas — folhas e diálogo.
// Sem eles, `inset: 0` é a tela inteira, inclusive o pedaço sob o teclado. Ver
// `.popup-backdrop` em controle.css. Com o layout já redimensionado (ou teclado
// fechado) as duas contas dão ~0 e os dois mecanismos convivem sem brigar.
(function keyboardShift() {
  const vv = window.visualViewport;
  if (!vv) return;
  let raf = 0;
  // O TECLADO EXIGE UM CAMPO EM FOCO, e sem esta pergunta a conta acima é uma
  // porta aberta para o app inteiro encolher por um motivo que não é teclado
  // nenhum. `--kb` desconta altura do `<body>`, `main` é `flex: 1`: qualquer
  // encolhimento espúrio da viewport VISUAL — e o WebView do Android tem mais
  // de um caminho para produzir um, do redimensionamento da janela ao
  // reajuste de escala diante de conteúdo novo — some com a lista e sobe a
  // caixa de controles até o topo. É o relato do operador na importação de um
  // `.pptx` (o palco de rasterização, hoje uma caixa 0×0 — ver `deck.js`).
  //
  // A pergunta é EXATA, não uma heurística de tamanho: um teclado só existe
  // sobre um campo editável, e nenhum limiar em pixels distingue teclado de
  // acidente (num aparelho pequeno em paisagem o teclado passa de metade da
  // tela). Fechar o campo antes de o teclado terminar de sair devolve o layout
  // um quadro mais cedo, que é o que ele faria de qualquer jeito.
  const temCampoEmFoco = () => {
    const a = document.activeElement;
    if (!a) return false;
    const t = (a.tagName || '').toLowerCase();
    return t === 'input' || t === 'textarea' || a.isContentEditable === true;
  };
  // ===== E HÁ CAMPO QUE PEDE O TECLADO POR CIMA, NÃO O APP ENCOLHIDO =====
  //
  // Relato do operador, sobre o renomear na linha: *"o teclado está arrastando
  // e encolhendo a tela com o controle ao invés de sobrepor o controle/tela
  // como já faz na biblioteca"*.
  //
  // A régua já estava escrita — no `.popup-backdrop` do CSS, para a Biblioteca:
  // *"O TECLADO SOBREPÕE, NÃO DESLOCA… nada aqui embaixo precisa ser revelado e
  // quem rola é a LISTA"*. Ela vale igual aqui, e por um motivo a mais: o que o
  // app encolhe para caber é justamente a PREVIEW e o TRANSPORTE, isto é, a
  // projeção e os controles do culto — comprimidos para revelar um campo que
  // já está à vista, dentro de uma lista que rola sozinha.
  //
  // A DECLARAÇÃO É DO CAMPO (`data-teclado="sobrepoe"`), não uma classe que
  // este handler conheça: o próximo campo que nascer dentro de uma lista já diz
  // o que quer, sem ninguém precisar voltar aqui. O padrão continua sendo
  // DESLOCAR — é o que o `appPrompt` precisa, um cartão CENTRADO cuja metade de
  // baixo é exatamente onde o teclado sobe.
  //
  // O QUE ISTO ALCANÇA, dito: só o mundo em que o hint
  // `interactive-widget=resizes-content` é IGNORADO — a viewport de LAYOUT não
  // muda e quem encolhe o `<body>` é este `--kb`. É o WebView em edge-to-edge
  // do Android 15+, o aparelho do operador. Onde o hint é HONRADO quem encolhe
  // é o próprio navegador (o `100svh` do `body` passa a valer menos) e não há
  // daqui como impedir.
  const campoSobrepoe = () => {
    const a = document.activeElement;
    return !!a && !!a.dataset && a.dataset.teclado === 'sobrepoe';
  };
  const apply = () => {
    raf = 0;
    // Altura coberta pelo teclado = o que sobra abaixo da viewport visual.
    const kb = (temCampoEmFoco() && !campoSobrepoe())
      ? Math.max(0, Math.round(window.innerHeight - vv.height - vv.offsetTop))
      : 0;
    document.documentElement.style.setProperty('--kb', kb + 'px');
    document.documentElement.style.setProperty('--vv-top', Math.max(0, Math.round(vv.offsetTop)) + 'px');
    // ===== E O TECLADO GANHA NOME (v1.5.6) =====
    // `--kb` é uma MEDIDA, e o CSS não sabe perguntar se uma medida é maior que
    // zero. Quem precisa da pergunta é a caixa de controles, que sai de cena
    // quando a Biblioteca está aberta E o teclado está no ar (ver `.bottombar`
    // em controle.css). A classe é escrita AQUI, no mesmo ponto e no mesmo
    // quadro que a medida: um segundo dono seria um segundo instante, e os dois
    // discordariam durante a subida do teclado, que é justamente quando a regra
    // vale.
    document.body.classList.toggle('teclado', kb > 0);
    // E O VÉU DAS BORDAS DA LISTA (v1.5.16). O teclado é a porta NORMAL da
    // Biblioteca (`openHymnSearch(true)` põe o foco no campo) e ele muda a
    // ALTURA da lista sem rolagem e sem render — `body.lib-aberta.teclado` tira
    // a caixa de controles de cena e a camada passa a terminar em `var(--kb)`.
    // Os outros três donos do véu (os dois renders e o `scroll`) não cobrem
    // isso, e o erro é nos DOIS sentidos: o véu de baixo fica aceso sobre uma
    // lista que passou a caber, ou apagado sobre uma que passou a não caber.
    // Aqui, no mesmo ponto e no mesmo quadro em que a medida é escrita.
    pedirVeuDaLista();
  };
  const schedule = () => { if (!raf) raf = requestAnimationFrame(apply); };
  vv.addEventListener('resize', schedule);
  vv.addEventListener('scroll', schedule);
  // O FOCO entra na conta, então ele também tem de reagendá-la: o caminho
  // normal (teclado abre/fecha) sempre traz um evento da viewport junto, mas um
  // campo que perde o foco sem que a viewport mexa deixaria `--kb` parado no
  // último valor — o app encolhido, sem teclado nenhum na tela.
  document.addEventListener('focusin', schedule);
  document.addEventListener('focusout', schedule);
  apply();
})();

// Fonte única de "o operador mexeu no volume": as teclas FÍSICAS, o arrasto no
// fader e as teclas +/− do Modo Fácil passam todas por aqui, então nunca
// divergem entre si (nem do mudo, que sai sozinho). E este número não é o
// volume do aparelho: ele viaja no comando `volume` e chega também às TELAS DA
// REDE, que são outros aparelhos.
function applyVolume(v) {
  volume = Math.max(0, Math.min(1, v));
  if (volume > 0 && muted) { muted = false; cmd({ type: 'mute', muted }); }
  cmd({ type: 'volume', volume });
  renderControls();   // e por ele o fader e a leitura do Modo Fácil
}


// ===== Modos de uso: simplificado × sonoplasta completo =====
// Duas pessoas: quem só conecta a tela e toca um louvor, e o sonoplasta que
// opera o culto inteiro.
//
// Abre no ÚLTIMO MODO USADO (`storedAppMode`), nunca por pergunta na abertura —
// ela cobraria um toque de quem nem sabe que há dois modos. Cair no avançado
// sem querer custa um toque no "← Modo simplificado" do cabeçalho.
//
// O simplificado NÃO é uma segunda implementação do transporte: os botões
// acionam os MESMOS controles do avançado por `.click()` (o padrão da
// notificação nativa) e o volume passa pelo mesmo `applyVolume`. Assim nenhuma
// regra de borda existe em dois lugares.
//
// (`appMode`, `lastDisplays` e `reconferirTelas` são declarados no TOPO do
// arquivo, junto do resto do estado lido por caminhos de render — ver a zona
// morta temporal lá em cima. `reconferirTelas` é ATRIBUÍDO pelo bloco nativo
// mais abaixo; no navegador segue no-op, e ali quem responde "há tela?" é a
// janela do Display, observada por relógio próprio.)

function setAppMode(mode) {
  appMode = mode === 'simple' ? 'simple' : 'full';
  // O "tocar neste celular" VALE O USO ATUAL, e uma ida ao avançado encerra
  // esse uso: voltar ao Modo Fácil devolve a tela de bloqueio. É por isto que
  // não há botão de desfazer — este é um dos três caminhos de volta, e o único
  // que o operador percorre de propósito.
  tocarNoCelular = false;
  // A escolha é do operador, e ele não deveria refazê-la a cada abertura.
  try { localStorage.setItem(APP_MODE_KEY, appMode); } catch (_) { /* storage bloqueado */ }
  document.body.classList.toggle('mode-simple', appMode === 'simple');
  simpleModeEl.classList.toggle('open', appMode === 'simple');
  // A preview troca de casa junto com o modo (ver hostPreview) — antes dos
  // renders, para que eles já a encontrem no lugar certo.
  hostPreview();
  // E TROCA DE PAPEL JUNTO: só no avançado ela é a caixa de som deste aparelho
  // (ver `acertarSaidaDeAudio`). Voltar ao Modo Fácil a emudece, porque lá sem
  // tela a cortina já cobre tudo.
  acertarSaidaDeAudio();
  renderAppModeSeg();
  renderSimple();
  renderSimpleCast();
  renderSimpleGate();   // `renderSimpleCast` volta cedo fora do simplificado
  // Sair do simplificado com a busca aberta deixaria o popup por cima da tela
  // completa sem nada que explicasse por quê.
  if (appMode === 'full') closeHymnSearch();
  // E AS MINIATURAS DA APRESENTAÇÃO SAEM COM O MODO (v1.4.30). `refreshSimpleLyrics`
  // volta cedo fora do simplificado, então ninguém mais passaria por elas: uma
  // apresentação são dezenas de Blobs segurados pelo resto da sessão, num
  // processo que já hospeda os dois WebViews. A assinatura é zerada junto,
  // senão a volta ao modo encontraria o `sig` igual e não redesenharia nada —
  // a zona ficaria com os quadros vazios.
  if (appMode === 'full' && lvSimpleDeckUrls.length) {
    lvSoltarUrls(lvSimpleDeckUrls);
    simpleLyricsEl.innerHTML = '';
    simpleLyricsEl.classList.remove('lv-grade');
    lvSimpleSig = '';
  }
  // A caixa de controles fica oculta no simplificado, e medir um elemento
  // escondido dá 0 — o vazado da faixa só pode ser posicionado quando ela
  // aparece. Sem animação: aqui ele POUSA, não viaja.
}

function renderAppModeSeg() {
  // O `data-modo` É O ESTADO (v1.4.43), e a classe é aparência — a mesma
  // disciplina do `data-estado` dos tiles. É por ele que o CSS desliza o
  // polegar do interruptor e por ele que os oráculos perguntam qual modo está
  // em vigor; a classe `.active` de cada botão continua carregando só a COR do
  // rótulo sobre o polegar.
  appModeSegEl.dataset.modo = appMode;
  appModeSegEl.querySelectorAll('.fit-opt').forEach((btn) => {
    btn.classList.toggle('active', btn.dataset.mode === appMode);
  });
}

// ---- Tema (a leitura e a pintura estão no topo do arquivo) ----
// Trocar de tema NÃO fecha o popup, ao contrário do modo do app: o modo troca
// a tela inteira atrás dele (não há o que ver com o popup na frente), e o tema
// troca a cor DO PRÓPRIO POPUP — é olhando para ele que o operador decide se
// gostou. Escolher e continuar vendo é a resposta.
function setTema(t) {
  const novo = t === 'claro' ? 'claro' : 'escuro';
  if (novo === tema) return;
  tema = novo;
  try { localStorage.setItem(TEMA_KEY, tema); } catch (_) { /* storage bloqueado */ }
  pintarTema();
  renderTemaTile();
}

// SEMPRE ACESO, pelo motivo do preenchimento: escuro e claro são as duas
// metades de um par, e nenhuma delas é "o tema desligado".
function renderTemaTile() {
  pintarTile(temaTileEl, tema, tema === 'claro' ? 'Claro' : 'Escuro',
    true, tema === 'claro');
}

// (A CHAVE "este aparelho entra na contagem" saiu na v1.4.42, a pedido do
//  operador: *"descarte a opção de contagem de uso como opcional, deixe sempre
//  ativo, não preciso do sistema de exclusividade"*. Ela foi um tile do painel
//  rápido (v1.4.1–v1.4.40) e uma linha do rodapé do Registro (v1.4.41).
//
//  O QUE SOBRA É LEITURA: `farolDiag` alimenta a linha "Alcance:" do Registro,
//  que responde *"o farol chegou a acender?"* — e essa pergunta não tem nada a
//  ver com haver ou não uma chave.)
// A tela simplificada é um ESPELHO dos controles reais: copia o glifo e o
// estado dos botões do mixer/transporte em vez de recalcular play/pause e
// mudo por conta própria. Se a regra mudar lá, muda aqui junto.
function renderSimple() {
  if (appMode !== 'simple') return;
  simpleNpNameEl.textContent = npNameInnerEl.textContent || 'Nada tocando';
  simplePlayEl.querySelector('.msym').textContent = playPauseEl.querySelector('.msym').textContent;
  // O botão espelhado deixou de ter glifo na v1.3.5 (subiu para a preview e
  // virou SVG), então o que se copia agora é a CLASSE de estado — `.alternado`
  // é a mesma chave que lá troca o desenho. O espelho continua LENDO o controle
  // de verdade em vez de reler `muted`/`displayAudioBlocked` por conta própria:
  // uma segunda leitura divergiria no primeiro caso de borda.
  simpleMuteEl.querySelector('.msym').textContent =
    muteToggleEl.classList.contains('alternado') ? ICON.volOff : ICON.volOn;
  simpleMuteEl.classList.toggle('muted', muteToggleEl.classList.contains('muted'));
  simpleMuteEl.classList.toggle('blocked', muteToggleEl.classList.contains('blocked'));
  simpleMuteEl.title = muteToggleEl.title;
  // Volume por teclas: o número é o indicador, e `--vol` desenha a barrinha de
  // curso na base dele (ver .simple-vol-read::after).
  const pct = Math.round(volume * 100);
  simpleVolValueEl.textContent = String(pct);
  simpleVolWrapEl.style.setProperty('--curso', String(pct / 100));
  renderSimpleTime();
  refreshSimpleLyrics();
}

// Linha do tempo do simplificado. Espelha a MESMA barra do modo avançado
// (`#seek`) em vez de reconstruir a posição: aquela já é alimentada pelas três
// fontes possíveis — a preview local, o `display-status` do telão e o polling
// do YouTube — e é ela que sabe quando o item nem tem duração (imagem, texto).
function renderSimpleTime() {
  if (appMode !== 'simple') return;
  const dur = parseFloat(seekEl.max) || 0;
  const cur = parseFloat(seekEl.value) || 0;
  const timed = !seekEl.disabled && dur > 0;
  simpleTimeEl.hidden = !timed;
  if (!timed) return;
  // DURANTE O ARRASTE quem escreve a barra é o dedo (ver `setupSimpleSeek`).
  // Sem esta guarda, o `timeupdate` da mídia — que continua tocando enquanto se
  // procura o ponto — puxaria o preenchimento de volta a cada quadro e o dedo
  // brigaria com ele.
  if (simpleSeeking) return;
  simpleTimeCurEl.textContent = fmtTime(cur);
  simpleTimeDurEl.textContent = fmtTime(dur);
  simpleTimeFillEl.style.width = Math.max(0, Math.min(100, (cur / dur) * 100)) + '%';
  if (simpleTimeHitEl) {
    simpleTimeHitEl.setAttribute('aria-valuemax', String(Math.round(dur)));
    simpleTimeHitEl.setAttribute('aria-valuenow', String(Math.round(cur)));
  }
}

// ===== A BARRA DE TEMPO DO SIMPLIFICADO É INTERATIVA (v5.142) =====
//
// Ela nasceu como indicador — "neste modo não se arrasta nada; quem precisa
// saltar no tempo usa o modo avançado". Só que saltar no tempo é a coisa mais
// comum que se faz durante um louvor (voltar o refrão, pular a introdução), e
// mandar o operador SAIR do modo para fazê-la é o oposto do que o modo existe
// para dar. As teclas grandes continuam sendo a regra; o que muda é que a barra
// deixou de ser um enfeite.
//
// Tocar salta; arrastar procura, e o comando só sai ao SOLTAR — um `seek` por
// quadro de movimento faria a mídia engasgar durante todo o gesto. O tempo
// enquanto o dedo anda é escrito na tela pelo próprio gesto (`simpleSeeking`),
// que é como o operador enxerga para onde está indo.
let simpleSeeking = false;
function setupSimpleSeek() {
  if (!simpleTimeHitEl) return;
  const dur = () => parseFloat(seekEl.max) || 0;
  const posicao = (e) => {
    const r = simpleTimeHitEl.getBoundingClientRect();
    if (!r.width) return 0;
    const f = Math.max(0, Math.min(1, (e.clientX - r.left) / r.width));
    return f * dur();
  };
  const pintar = (t) => {
    const d = dur();
    simpleTimeCurEl.textContent = fmtTime(t);
    simpleTimeFillEl.style.width = (d > 0 ? Math.max(0, Math.min(100, (t / d) * 100)) : 0) + '%';
  };
  simpleTimeHitEl.addEventListener('pointerdown', (e) => {
    if (seekEl.disabled || dur() <= 0) return;
    simpleSeeking = true;
    // `seeking` é o MESMO sinal que a barra do modo avançado arma: é ele que
    // impede a sessão de mídia de republicar uma posição que ainda está sob o
    // dedo (ver `pushNowPlaying`). Dois estados para a mesma coisa divergiriam.
    seeking = true;
    simpleTimeHitEl.classList.add('seeking');
    try { simpleTimeHitEl.setPointerCapture(e.pointerId); } catch (_) {}
    pintar(posicao(e));
  });
  simpleTimeHitEl.addEventListener('pointermove', (e) => {
    if (!simpleSeeking) return;
    pintar(posicao(e));
  });
  const soltar = (e) => {
    if (!simpleSeeking) return;
    simpleSeeking = false;
    seeking = false;
    simpleTimeHitEl.classList.remove('seeking');
    try { simpleTimeHitEl.releasePointerCapture(e.pointerId); } catch (_) {}
    const t = posicao(e);
    // A barra do modo avançado é a fonte de verdade da posição em toda a tela
    // (o `renderSimpleTime` a espelha, e `pushNowPlaying` a lê): escrevê-la aqui
    // é o que mantém os dois modos contando a mesma coisa até o próximo pulso
    // do `display-status` chegar.
    seekEl.value = String(t);
    curTimeEl.textContent = fmtTime(t);
    cmd({ type: 'seek', time: t });
    renderSimpleTime();
  };
  simpleTimeHitEl.addEventListener('pointerup', soltar);
  simpleTimeHitEl.addEventListener('pointercancel', (e) => {
    // Cancelado (o sistema tomou o gesto): NÃO salta. Um `seek` para onde o
    // dedo por acaso estava quando a chamada entrou seria um salto que ninguém
    // pediu; a barra volta sozinha ao valor real no próximo render.
    simpleSeeking = false;
    seeking = false;
    simpleTimeHitEl.classList.remove('seeking');
    try { simpleTimeHitEl.releasePointerCapture(e.pointerId); } catch (_) {}
    renderSimpleTime();
  });
}
setupSimpleSeek();

// Volume em passos, como num controle remoto — o MESMO passo dos botões
// físicos (VOL_KEY_STEP), para os dois caminhos não discordarem, e a mesma
// `applyVolume` de sempre (clamp, desmutar ao subir de 0, comando, render).
function simpleVolStep(dir) {
  applyVolume(volume + dir * VOL_KEY_STEP);
  persistCurrent();
}

// Segurar a tecla repete, como num controle de verdade. O primeiro passo sai
// no `pointerdown` (resposta imediata); a repetição só começa depois de uma
// pausa, senão um toque comum viraria dois.
function holdRepeat(btn, fn) {
  let delay = null, timer = null;
  const stop = () => { clearTimeout(delay); clearInterval(timer); delay = timer = null; };
  btn.addEventListener('pointerdown', () => {
    fn();
    delay = setTimeout(() => { timer = setInterval(fn, 120); }, 420);
  });
  ['pointerup', 'pointercancel', 'pointerleave'].forEach((ev) => btn.addEventListener(ev, stop));
}

/**
 * Quantas telas da REDE estão recebendo agora — 0 com o espelho desligado.
 *
 * Deliberadamente separado do `simpleDisplay()`: aquele responde "há um TELÃO?"
 * e governa coisas de peso (a cortina do modo simplificado, o atraso da preview,
 * quem é a referência de tempo). Aqui a pergunta é só "há alguém recebendo?",
 * que é o que o ícone de conectar tem a dizer.
 */
function espelhoRecebendo() {
  const e = mirrorEstado;
  if (!e || !e.ligado || !Array.isArray(e.telas)) return 0;
  return e.telas.length;
}

// O ÍCONE DE CAST SOBRE A PREVIEW — e ele vale nos DOIS modos (v5.142).
//
// Esta função morava dentro de `renderSimpleCast`, que começa com
// `if (appMode !== 'simple') return`. O efeito era duplo e o segundo é o do
// relato: no modo avançado o ícone NUNCA era repintado, então o vermelho de
// "conectado" que o simplificado deixou aceso ficava para sempre — o operador
// trocava de modo, a tela caía, e o ícone seguia dizendo que havia telão. O
// estado da tela não é uma decoração de um dos modos; é o mesmo fato nos dois.
function renderCastBtn() {
  const tv = simpleDisplay();
  // AS TELAS DA REDE CONTAM COMO CONEXÃO — e é o ÍCONE que passa a dizer isso
  // (v5.176), no lugar do cartão na barra de notificações.
  //
  // A notificação do `EspelhoService` não pode sumir (um serviço em primeiro
  // plano é obrigado a ter uma, e é ele que mantém o espelho no ar com o app
  // minimizado), mas ela também não era o lugar certo para essa informação: o
  // operador olha para o app, e o app já tem um ícone cujo trabalho é
  // exatamente esse. O cartão foi para `IMPORTANCE_MIN` — sai da barra de
  // status — e o fato subiu para cá.
  //
  // Mesma classe, mesma cor, mesmo efeito do telão: `.connected` quer dizer "há
  // uma tela recebendo", e três navegadores da rede são três telas recebendo.
  // Inventar um segundo estado visual para o mesmo fato seria pedir ao operador
  // que aprendesse duas convenções para uma coisa só.
  const naRede = espelhoRecebendo();
  // `.connected` marca "há uma tela recebendo". (O terceiro estado, `.testing`
  // da liberação de teste em `--warn`, saiu na v5.199 com a própria liberação.)
  pvCastBtnEl.classList.toggle('connected', !!tv || naRede > 0);
  const naRedeTxt = naRede === 1 ? '1 tela na rede' : naRede + ' telas na rede';
  pvCastBtnEl.title = tv
      ? 'Conectado: ' + (tv.name || 'TV') + (naRede ? ' · ' + naRedeTxt : '')
        + ' — toque para trocar ou desconectar'
      : naRede
        ? naRedeTxt + ' recebendo — toque para ver quem está conectado'
        : 'Conectar uma TV';
}

// O QUE SOBROU DE "renderizar a conexão no Modo Fácil" (v5.197): o ícone de
// cast da preview e o bloqueio. O cartão que esta função existia para pintar —
// rótulo, subtítulo, estado, `title` do gesto de 5 s — saiu com o botão único,
// que estava morto desde a v5.193 (escondido por duas regras de `display: none`
// que juntas cobriam todos os estados).
//
// O nome fica: são treze chamadores, e a função continua sendo "acerte o que
// depende de haver tela conectada" — só que hoje isso é o ícone e a cortina.
function renderSimpleCast() {
  renderCastBtn();
  if (appMode !== 'simple') return;
  renderSimpleGate();
}

// ===== Bloqueio do simplificado sem tela conectada =====
// Neste modo a projeção É o telão — não há preview aqui. Sem tela conectada,
// buscar uma música e dar play produz som no celular e mais nada: os controles
// continuavam ali, respondendo a cada toque, sem que nada aparecesse em lugar
// nenhum. A cortina troca esse silêncio por uma resposta: embaça o que está
// atrás, intercepta os toques e deixa na frente só o que resolve o problema —
// o botão de conectar.
//
// **O "Modo avançado" continua acessível**, no cabeçalho. Sem TV o app não
// fica inútil: a projeção passa a ser a preview em tela cheia (ver CLAUDE.md,
// "Sem TV conectada o app continua útil"), e trancar essa saída transformaria
// a falta de telão numa parede. O que se bloqueia é o modo simplificado, não
// o app.
//
// A única parte que muda por contexto é quem responde "há tela?": no app é a
// `Presentation` (a ponte lista as telas de apresentação); no navegador não
// existe Presentation, então vale a janela do Display que o próprio botão
// abre — enquanto ela estiver aberta, há para onde projetar.
let webDisplayWin = null;      // navegador: janela do Display aberta pelo botão
let webDisplayTimer = null;

// (A LIBERAÇÃO DE TESTE — segurar 5 s para destravar sem tela — SAIU na v5.199,
// junto com o bloqueio. Ela era uma porta de desenvolvimento cujo único
// trabalho era derrotar a cortina, e uma porta sem parede não é uma porta: o
// modo já abre usável. Com ela saíram `CAST_HOLD_MS`, `castTestUnlocked`, o
// gesto na cortina e o estado `.testing` do ícone de cast.)

// HÁ ALGUMA TELA RECEBENDO? — e desde a v5.193 a resposta inclui as telas da
// REDE, não só a TV pela `Presentation`.
//
// Ela não decide mais bloqueio nenhum (v5.199): decide QUEM ocupa a célula da
// preview no Modo Fácil — a preview, quando há tela, ou a seção de conexão,
// quando não há — e o estado do ícone de cast. "O telão" deixou de ser sinônimo
// de "uma TV conectada por espelhamento" na v5.187: sem TV, as telas da rede
// SÃO o que a congregação vê, e é por isso que elas contam aqui.
function simpleDisplay() {
  if (!window.__NATIVE__) {
    return webDisplayWin && !webDisplayWin.closed ? { name: 'Display' } : null;
  }
  // O TELÃO NO AR, não a tela listada (shell 59): sem `Presentation` não há
  // para onde projetar, e destravar o Modo Fácil ali dava um ▶ que não produz
  // imagem nem som. A cortina volta, e a folha de conexão diz por quê.
  const tv = telaoNoAr();
  if (tv) return tv;
  const rede = telasDaRede();
  return rede.length ? { name: rede[0].rotulo || 'Tela da rede', rede: true } : null;
}

// As telas da rede que estão de fato RECEBENDO. Uma só fonte para o Modo Fácil
// e para o fechamento da folha — ver `renderSimpleGate`.
function telasDaRede() {
  const e = mirrorEstado || {};
  if (!espelhoLigado() || !Array.isArray(e.telas)) return [];
  // ===== "HÁ TELA" NUNCA FOI "HÁ PROJEÇÃO" — o irmão do `telaoNoAr` (v1.4.19) =====
  //
  // O telão de verdade já tinha esta distinção (o campo `telao`: a tela CONTINUA
  // listada com a `Presentation` no chão, e as três perguntas que dependem de
  // haver projeção leem a janela, não a lista). As telas da rede não tinham
  // equivalente: bastava PAREAR para o `somLocalDeveEstar` calar este aparelho.
  //
  // `pronta` é o `__de` do `display-ready` chegando de volta pelo `POST /r` —
  // isto é, o `/display/` daquela tela subiu e se anunciou. Entre o `POST /par`
  // (que já cria a sessão e o fio SSE) e esse anúncio, a tela não está
  // projetando nada; e sem TV a tela É a projeção, então o celular ficava mudo
  // com ninguém tocando do outro lado — silêncio nos dois lados, que é o
  // desfecho exato que o campo `telao` existe para não ter.
  //
  // `!== false` e não `=== true`: é o idioma deste projeto para "nasce ligado".
  // Um shell que não mande o campo não pode perder a tela por isso.
  return e.telas.filter((t) => t && t.pronta !== false);
}

// O PORTÃO DO MODO FÁCIL: sem tela conectada, a cortina bloqueia e o cartão de
// conexão é a única coisa legível.
//
// **Ele saiu na v5.199 e voltou na v5.203, e a ida e a volta valem escritas**,
// porque a remoção foi um diagnóstico errado e não uma mudança de gosto. O
// operador relatava "o botão de conectar que persiste em existir e bloquear a
// tela do modo simples"; a leitura foi de que o BLOQUEIO incomodava, e a v5.199
// o derrubou inteiro. Não era isso: o que ele via era o botão ANTIGO — o
// `#simpleCastBtn` da v5.192, servido pela base embutida no APK depois de um
// recuo do watchdog que não limpava o cache do WebView (a causa real, corrigida
// na v5.200/v1.91). Ele chegou a dizer, com todas as letras, que "essa parte
// não era o problema".
//
// O argumento que sustenta o bloqueio continua o mesmo, e ficou mais forte com
// o tempo: sem tela a projeção não existe, e desde a v5.189 a preview nem som
// tem — um ▶ aqui não produz absolutamente nada. A saída é o "Modo avançado" do
// cabeçalho, que fica por cima da cortina de propósito: o que se bloqueia é
// este MODO, não o app.
function renderSimpleGate() {
  const temTela = !!simpleDisplay();
  // UMA TELA ENTROU: a escolha de tocar aqui morre com ela. Escrito direto (e
  // não por `setTocarNoCelular`, que re-renderiza) porque estamos DENTRO do
  // render — a chamada de volta seria recursão, e o resto desta função já
  // aplica o estado novo na mesma passada.
  if (temTela && tocarNoCelular) {
    tocarNoCelular = false;
    acertarSaidaDeAudio();
  }
  const semTela = appMode === 'simple' && !temTela && !tocarNoCelular;
  // ===== O BOTÃO DE TOCAR AQUI SE DESENHA DAQUI, e não do `renderCast` =====
  //
  // MEDIDO nas duas pontas. `renderCast` abre com `if (!castConnVisivel())
  // return`, e o botão precisa continuar desenhado exatamente quando aquela
  // guarda fecha: LIGADO, ele desbloqueia o Modo Fácil, o bloco de conexão
  // volta para a folha (fechada) e o botão some — justamente quando ele é a
  // única forma de desfazer o que acabou de fazer. E ele também não era
  // repintado ao TROCAR DE MODO, porque em avançado o `hostCastConn` não chama
  // `renderCast`: o botão sobrevivia visível fora do Modo Fácil.
  //
  // Esta função responde às três coisas de que ele depende — o modo, as telas e
  // a própria escolha —, e é chamada por todas as três.
  renderCastLocal();
  simpleModeEl.classList.toggle('sem-tela', semTela);
  // A CORTINA VOLTOU na v5.203 (ver o comentário do `.simple-veil`): sem tela
  // este modo não projeta nada — nem imagem nem som, desde que a mesa saiu na
  // v5.189 —, e o bloqueio é o que diz isso sem depender de ninguém ler um
  // cartão. O elemento existe só no bundle novo, daí a guarda.
  if (simpleVeilEl) simpleVeilEl.hidden = !semTela;
  // A busca é o que a cortina esconde: deixá-la aberta por trás daria um popup
  // funcionando sobre uma tela bloqueada, e tocar uma música dali não projetaria
  // coisa nenhuma.
  if (semTela) closeHymnSearch();
  hostCastConn(semTela);
  // ALGUMA TELA ENTROU COM A FOLHA ABERTA: ela fecha. Vale para os dois
  // caminhos (TV e navegador) e nos dois modos — quem acabou de conectar
  // terminou o que veio fazer ali. No Modo Fácil o bloco está DENTRO da tela, e
  // o `hostCastConn` acima já o devolveu para a folha.
  //
  // É UMA BORDA, NUNCA UM NÍVEL. Escrita como `if (há tela) fecha`, com uma tela
  // conectada (o estado normal de um culto) a folha era fechada por QUALQUER
  // passagem por aqui — e o próprio `abrirCast` liga a enquete de 2,5 s, que
  // chama esta função: a folha abria e se fechava em milissegundos, isto é, o
  // botão de cast não abria nada. Era também a única porta para trocar de TV,
  // desligar a transmissão ou derrubar uma tela.
  //
  // A memória é re-armada em `abrirCast` (`gateTinhaTela = há tela?`), e é isso
  // que dá o significado certo: enquanto ESTA folha estiver aberta, se uma tela
  // entrar, ela fecha. Sem o re-armar, uma folha aberta muito depois herdaria
  // uma borda de horas atrás.
  const entrou = temTela && !gateTinhaTela;
  gateTinhaTela = temTela;
  if (entrou && !semTela && castPopupEl && castPopupEl.classList.contains('open')) {
    fecharCast();
  }
}

/**
 * O BOTÃO DE TOCAR AQUI SÓ EXISTE ONDE A ESCOLHA AINDA PODE SER FEITA: Modo
 * Fácil, nenhuma tela conectada, e ela ainda não feita.
 *
 * As três metades têm razões diferentes. **No avançado ele não aparece** porque
 * lá o som já sai daqui por derivação — um botão para ligar o que já está
 * ligado. **Com tela conectada**, porque há para onde mandar e é para lá que o
 * som vai. **Já escolhido**, porque isto é caminho só de ida: quem desfaz é
 * fechar o app ou passar pelo modo avançado (ver `setTocarNoCelular`), não um
 * segundo botão.
 *
 * Daí ele não ter estado LIGADO nenhum — nem rótulo que troca, nem cor de
 * escolhido. Um botão que some depois do toque não precisa dizer que foi tocado:
 * a tela desbloqueada e o som saindo já dizem.
 */
function renderCastLocal() {
  if (!castLocalBtnEl) return;
  castLocalBtnEl.hidden = !(appMode === 'simple' && !algumaTelaConectada() && !tocarNoCelular);
}

// O BLOCO DE CONEXÃO TEM DUAS CASAS, e é o MESMO nó — o padrão do `hostPreview`
// (a preview também troca de pai conforme o modo). Duplicar a marcação daria
// duas anatomias para a mesma decisão e elas divergiriam no primeiro ajuste.
//
// `naTela` é a única condição: é exatamente o estado em que o Modo Fácil não
// tem tela para onde projetar, e a conexão ocupa a célula da preview. Fora dele
// o bloco volta para a folha, que é onde ele é aberto de propósito (pelo botão
// de cast da preview, ou pelo cartão deste mesmo modo com uma tela conectada).
function hostCastConn(naTela) {
  if (!castConnEl || !simpleConnEl) return;
  const alvo = naTela ? simpleConnEl : castPopupEl.querySelector('.popup-sheet');
  if (alvo && castConnEl.parentElement !== alvo) alvo.appendChild(castConnEl);
  simpleConnEl.hidden = !naTela;
  if (naTela) {
    // Ele passa a ser conteúdo de tela, não de folha: o estado precisa estar
    // certo sem ninguém ter aberto nada.
    if (castNetBtnEl) castNetBtnEl.hidden = !espelhoDisponivel();
    renderCast();
  }
  acertarEnqueteDaConexao();
}

// A ENQUETE DE 2,5 s TEM UM DONO SÓ, e é a VISIBILIDADE do bloco (v5.199).
//
// Ela nasceu como enquete da FOLHA — `abrirCast` a ligava, `fecharCast` a
// matava —, e a v5.193 deu ao bloco uma segunda casa (a tela do Modo Fácil sem
// telão) sem dar um dono novo à enquete. Ficaram dois acionadores e um só
// interruptor, com as duas metades erradas: `hostCastConn` a acendia e nunca a
// apagava (uma tela entrando devolvia o bloco à folha e deixava a enquete
// batendo na ponte a cada 2,5 s pelo resto da sessão), e `fecharCast` a apagava
// mesmo quando quem a tinha acendido era a TELA — isto é, abrir e fechar a
// folha uma vez cegava o Modo Fácil justamente para o evento que ele espera,
// uma tela da rede entrando.
//
// Perguntar "o bloco está aparecendo?" responde os dois casos de uma vez, e é a
// mesma pergunta que o `renderCast` já faz para decidir se vale desenhar.
function acertarEnqueteDaConexao() {
  const querer = espelhoDisponivel() && castConnVisivel();
  if (querer === !!mirrorTimer) return;
  if (!querer) { clearInterval(mirrorTimer); mirrorTimer = null; return; }
  lerEspelho();
  mirrorTimer = setInterval(lerEspelho, MIRROR_POLL_MS);
}

// ===== A PREVIEW é UM nó só, e ele MUDA DE CASA =====
// No avançado ela mora na faixa do deck; no simplificado, no lugar que era do
// botão de conectar. Move-se o mesmo elemento em vez de existirem duas, pelo
// mesmo padrão do `#selbar` e do `<input type=file>`: duas divergiriam no
// primeiro ajuste, e dois `createStage` decodificariam o MESMO vídeo duas
// vezes num aparelho que já roda dois WebViews.
//
// A troca acontece só na mudança de MODO — não ao conectar/desconectar. Com a
// tela bloqueada a faixa some por CSS (`.simple.sem-tela .simple-stage`), e um
// `display:none` não custa nada; mover o nó a cada conexão, sim (ver abaixo).
// (O seletor citado aqui dizia `.simple.locked` — uma classe que nunca chegou a
// existir nesta folha: quem marca o estado é `.sem-tela`, escrita pelo
// `renderSimpleGate`. Um comentário que aponta para um seletor inexistente é
// pior que nenhum: ele faz o próximo leitor procurar a regra no lugar errado.)
function hostPreview() {
  const alvo = appMode === 'simple' ? simpleStageEl : previewRowEl;
  if (previewEl.parentElement === alvo) {
    pvCastBtnEl.hidden = !(appMode === 'simple' || window.__NATIVE__);
    return;
  }
  // Reparentar um `<video>` NÃO interrompe a reprodução desde que ele volte ao
  // documento no mesmo passo — e `appendChild` de um nó já anexado é remoção e
  // inserção atômicas, então o "removido do documento" nunca chega a valer.
  // Quem manda no botão de cast é o CONTEXTO: no simplificado ele é o sinal de
  // conexão e a porta de saída, então existe sempre; no avançado continua sendo
  // um atalho para um intent do Android, e some no navegador.
  pvCastBtnEl.hidden = !(appMode === 'simple' || window.__NATIVE__);
  alvo.appendChild(previewEl);
  // (Havia aqui a remontagem do player do YouTube: um IFRAME, ao contrário de
  //  um `<video>`, RECARREGA ao mudar de pai, e o player morria junto — então
  //  ele era reconstruído no segundo em que estava. Sem embed sobra só o
  //  `<video>`, que o `appendChild` acima preserva por construção.)
}

// Abre a tela do Display no navegador e acompanha a janela: fechá-la é o
// equivalente a desconectar o telão, e a cortina precisa voltar. `closed` só
// se descobre olhando — não há evento — então o relógio existe apenas
// enquanto a janela existe.
function openWebDisplay() {
  webDisplayWin = window.open('../display/', 'avDisplay');
  renderSimpleCast();
  // No navegador a janela do Display é o "telão", e vale a mesma regra do som
  // deste aparelho (ver `acertarSaidaDeAudio`) — inclusive para desenvolver a
  // base web fora do aparelho, que é justamente o que este caminho serve: abrir
  // a janela cala a preview, fechá-la devolve o som a ela.
  acertarSaidaDeAudio();
  clearInterval(webDisplayTimer);
  if (!webDisplayWin) return;
  webDisplayTimer = setInterval(() => {
    if (webDisplayWin && !webDisplayWin.closed) return;
    clearInterval(webDisplayTimer);
    webDisplayTimer = null;
    webDisplayWin = null;
    renderSimpleCast();
    acertarSaidaDeAudio();
    }, 1000);
}

// A engrenagem do Modo Fácil (v5.250) — o MESMO destino do gearbox do
// avançado, e desde a v5.247 o único caminho para a troca de modo nos dois.
simpleSettingsBtnEl.addEventListener('click', openFadePopup);
// A FOLHA FICA ABERTA E PARADA (v1.4.43), a pedido do operador: *"verifique
// para que a aba de configurações permaneça na tela imóvel ao alternar entre
// fácil e avançado, para não se perder a localização atual na visão do
// usuário"*. Ela fechava — a justificativa era "a escolha já mudou a tela
// inteira atrás do popup", e é justamente esse o problema: quem trocou de modo
// perdia a folha, o lugar dela e o caminho de volta, e reabri-la é achar de
// novo a engrenagem, que no outro modo mora em outro canto. Com o interruptor
// que desliza, o que responde ao toque está DENTRO da folha, à vista.
appModeSegEl.addEventListener('click', (e) => {
  const btn = e.target.closest('.fit-opt');
  if (!btn) return;
  setAppMode(btn.dataset.mode);
});
// O TEMA ALTERNA (v1.4.38): o par escuro/claro virou um tile, e um tile de dois
// estados não escolhe — ele vai para o outro.
temaTileEl.addEventListener('click', () => { setTema(tema === 'claro' ? 'escuro' : 'claro'); });
// SEM FOCO, e o `() =>` é o ponto: registrado por REFERÊNCIA, o ouvinte chama
// `openHymnSearch(evento)` — e um `PointerEvent` é truthy, então a lupa do Modo
// Fácil abria com o teclado por cima da lista. É um BOTÃO, e a regra das duas
// portas (v1.5.0) diz que botão abre sem foco: *"ver o que eu tenho"*. Mesma
// armadilha que a v1.4.31 pagou no `openLyricsPopup`.
simpleSearchBtnEl.addEventListener('click', () => openHymnSearch(false));
// Os controles do simplificado são os do modo completo, acionados por click():
// um botão `disabled` continua sendo um no-op natural, e as bordas ficam num
// lugar só.
simplePlayEl.addEventListener('click', () => playPauseEl.click());
simpleStopEl.addEventListener('click', () => stopEl.click());
simpleMuteEl.addEventListener('click', () => muteToggleEl.click());
// AS PÁGINAS SEGUEM A MESMA REGRA (v1.4.30): elas acionam as âncoras do modo
// completo, e não `stepSlide` direto. Um `.click()` num botão `disabled` é
// no-op natural, e é o que faz o limite (que `applySlideLimits` já calculou uma
// vez) valer aqui sem uma segunda guarda.
simpleSlidePrevEl.addEventListener('click', () => slidePrevBtnEl.click());
simpleSlideNextEl.addEventListener('click', () => slideNextBtnEl.click());
holdRepeat(simpleVolUpEl, () => simpleVolStep(1));
holdRepeat(simpleVolDownEl, () => simpleVolStep(-1));
// (A LIBERAÇÃO DE TESTE — segurar 5 s — SAIU na v5.199. O alvo dela mudou duas
// vezes em cinco versões: o botão grande (até a v5.192), a cortina (v5.193) e
// nada (v5.199), porque o que ela destravava deixou de estar trancado. Ficasse,
// seria um gesto secreto de 5 s cujo efeito é indistinguível do estado normal
// da tela.)
// Fecha o ciclo com o HTML: as classes já vêm do documento (e, no modo
// lembrado, já foram corrigidas no topo do arquivo), aqui o estado do JS
// (segmento do popup, espelho dos controles) nasce igual a elas.
// `appMode`, e NÃO a constante `'simple'` que estava aqui: com o modo lembrado
// essa linha reescrevia o `localStorage` para "simple" em toda abertura, e o
// avançado nunca sobrevivia a fechar o app — o defeito era invisível, porque a
// tela ainda pintava certo até esta linha rodar.
setAppMode(appMode);
// Mesa de som nasce desligada (não é persistida); o segmento precisa nascer
// dizendo isso, senão a primeira abertura de Configurações mostra dois botões
// apagados e nenhuma escolha marcada.

// ===== Botões físicos de volume =====
// No app eles mexem no fader daqui, não na saída do sistema, e a razão é a
// PROJEÇÃO: quem não consome a tecla deixa o Android desenhar o painel de
// volume dele — e com espelhamento ativo esse painel aparece SOBRE o que a
// congregação está vendo. Consumindo, nada disso chega ao telão: o que aparece
// é o fader do celular, por alguns segundos (ver `peekVolume`).
// A Activity intercepta a tecla e chama esta função (ver MainActivity.onKeyDown).
const VOL_KEY_STEP = 0.05;
if (window.__NATIVE__) {
  window.__avVolumeKey = (step) => {
    // Mostra o fader por alguns segundos — inclusive quando o passo vai para o
    // sistema: o fader no máximo/zero é justamente a resposta para "por que o
    // volume do app não muda?".
    peekVolume();
    // Já no limite do fader: devolve a tecla ao sistema (com a UI de volume do
    // Android), senão um aparelho com o volume de mídia baixo ficaria sem como
    // subir enquanto o app estivesse aberto.
    if ((step > 0 && volume >= 1) || (step < 0 && volume <= 0)) {
      AVNative.systemVolume(step);
      return;
    }
    applyVolume(volume + step * VOL_KEY_STEP);
    persistCurrent();
  };
  // Só agora — com o handler de pé — a Activity pode consumir as teclas.
  AVNative.captureVolumeKeys(true);

  // ===== Controles da notificação / tela de bloqueio / botões de mídia =====
  // Tudo cai nos MESMOS botões da tela, via `.click()`: os handlers já tratam
  // todos os casos de borda (texto sem áudio de fundo, YouTube que precisa
  // recarregar, limites da playlist), e um botão `disabled` é um no-op
  // natural. Reimplementar essas decisões aqui — ou pior, em Kotlin — seria
  // criar uma segunda verdade sobre o transporte.
  AVNative.onRemote((action) => {
    switch (action) {
      // 'play'/'pause' vêm de fontes que sabem o que querem (tela de bloqueio,
      // fone); o botão da notificação manda 'playpause', que é alternador.
      //
      // Quando a intenção JÁ é o estado atual, o pedido só pode ter vindo de
      // uma notificação desatualizada — o operador tocou no que a tela dele
      // mostrava. Alternar seria fazer o oposto do pedido (pausar o louvor);
      // ignorar em silêncio foi exatamente o defeito relatado na v1.17. Então
      // não se mexe na mídia e se REPUBLICA a cena, para o botão se corrigir.
      case 'play': if (!playing) playPauseEl.click(); else resyncScene(); break;
      case 'pause': if (playing) playPauseEl.click(); else resyncScene(); break;
      case 'playpause': playPauseEl.click(); break;
      case 'stop': stopEl.click(); break;
      case 'view': viewToggleEl.click(); break;
      // Com letra, versículo ou mensagem em cena, ⏮/⏭ passam ESTROFE — é o que
      // o operador está fazendo naquele momento. Ver `slideMode` em
      // pushNowPlaying, que é o que rotula os botões na notificação.
      case 'prev': (slideTarget() ? slidePrevBtnEl : prevEl).click(); break;
      case 'next': (slideTarget() ? slideNextBtnEl : nextEl).click(); break;
      default: break;
    }
  });
}



plBtnEl.addEventListener('click', openPlPopup);

// Ordem das abas (esquerda→direita) — define a DIREÇÃO do deslize na animação
// de troca de aba (ir pra uma aba à direita desliza a lista entrando pela
// direita, e vice-versa).
//
const prefersReducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
// ===== O DESLIZE LATERAL, o que sobrou do carrossel de abas (v1.5.0) =====
//
// A FAIXA DE ABAS SAIU e levou junto o mecanismo inteiro: o carrossel
// horizontal (`setupTabCarousel`, com o ciclo próprio de `touch*` que três
// tentativas custaram), o fantasma que segurava os nós da tela que saía
// (`makeTabGhost`) e o `switchTab` que os orquestrava. Nada disso tem para onde
// apontar: o Cronograma é a tela única, e a Bíblia virou uma FOLHA — deslizar
// para uma folha não é navegação, é abrir uma janela.
//
// O QUE FICA é o deslize DENTRO da Bíblia (livros → capítulos → leitura), que é
// o único movimento lateral que sobrou no app. Ele nunca precisou do fantasma:
// ali as duas telas são o mesmo host redesenhado, e o que se anima é a ENTRADA
// da nova — a antiga já não existe quando a animação começa.
//
// `dir` = +1 quando a tela nova está à DIREITA (avançar), -1 ao voltar.
const TAB_MOVE_MS = 220;
const TAB_MOVE_EASE = 'cubic-bezier(.2,.7,.3,1)';

function deslizarNaFolha(host, dir) {
  if (!host || prefersReducedMotion || !host.animate) return;
  host.animate(
    [{ transform: 'translateX(' + (dir * 100) + '%)' }, { transform: 'none' }],
    { duration: TAB_MOVE_MS, easing: TAB_MOVE_EASE, fill: 'both' });
}

selCancelEl.addEventListener('click', exitSelection);
selPlaylistEl.addEventListener('click', addSelectedToPlaylist);
selFavEl.addEventListener('click', favoritarSelecionados);
plPackEl.addEventListener('click', guardarPacote);
// A PERGUNTA NASCE NA CAIXA DO BOTÃO (`pedirConfirmacaoNaLinha` olha o pai dele)
// — o mesmo par de "Cancelar/Excluir" das listas, aqui sobre a fila inteira.
plClearEl.addEventListener('click', (e) => {
  e.stopPropagation();
  pedirConfirmacaoNaLinha(plClearEl, {
    ok: 'Limpar',
    dica: 'Esvaziar a fila. O que está no ar segue no ar, e os arquivos só são '
      + 'apagados se não estiverem guardados em mais nenhuma lista.',
    aoConfirmar: limparPlaylist,
  });
});
selDeleteEl.addEventListener('click', deleteSelected);
selRenameEl.addEventListener('click', renameSelected);

// (O `#backBtn` do cabeçalho perdeu o dono na v1.5.0: ele só servia à Bíblia,
//  que virou folha e levou o voltar dela junto. O nó fica no HTML, sempre
//  oculto, porque `renderListTitle` ainda o esconde explicitamente — e é essa
//  linha que impede um bundle futuro de o revelar por acidente.)
if (bibleBackEl) bibleBackEl.addEventListener('click', navigateBack);
if (bibleCloseEl) bibleCloseEl.addEventListener('click', fecharBiblia);

// ===== AS DUAS PORTAS, ligadas (v1.5.0) =====
// O FOCO abre com teclado. `focus` e não `click`: o campo é alcançável também
// por teclado físico e pelo `Tab`, e nos dois a intenção é a mesma.
hymnSearchInputEl.addEventListener('focus', () => {
  if (!hymnSearchPopupEl.classList.contains('open')) openHymnSearch(true);
});
// A SETA abre sem foco; o ✕ (o mesmo botão, outro desenho) fecha.
if (hymnSearchToggleEl) {
  hymnSearchToggleEl.addEventListener('click', () => {
    if (hymnSearchPopupEl.classList.contains('open')) closeHymnSearch();
    else openHymnSearch(false);
  });
}
// A base da janela muda com o teclado e com a rotação. Por EVENTO e não por
// enquete — é a régua de uma caixa que só se mexe quando algo a empurra.
window.addEventListener('resize', medirBarraDaBiblioteca);
window.addEventListener('orientationchange', medirBarraDaBiblioteca);
// NA CARGA, e não só na abertura (v1.5.1): a barra fica à vista com a Biblioteca
// FECHADA, e a caixa de controles reserva a altura dela desde o primeiro quadro.
// Sem esta linha o app abria com a última fileira de botões coberta pela barra
// até alguém abrir a Biblioteca uma vez.
medirBarraDaBiblioteca();
// A SEGUNDA PASSADA é o que pega a barra já assentada (MEDIDO: 28,6px no
// primeiro quadro, 51px depois). Quem arma a animação é a própria medida — ver
// `semAnimarAJanela`, que é o mesmo mecanismo da carga e da remedição.
requestAnimationFrame(medirBarraDaBiblioteca);
// ---- E A CAIXA DE CONTROLES É VIGIADA (v1.5.2) ----
// O lugar da barra é o TOPO dessa caixa, e ela muda de altura por caminhos que
// não passam por aqui: a proporção da preview, o nome da mídia em duas linhas, a
// barra de seleção múltipla, o modo do app. Enumerá-los seria uma lista para
// envelhecer — e o modo de falhar é a barra pousando fora do lugar dela, com uma
// faixa de caixa aparecendo por baixo ou o transporte coberto.
// `ResizeObserver` responde à MUDANÇA, seja qual for a causa. O laço que ele
// poderia criar (a medida muda o `padding-top`, que muda a caixa) é fechado do
// outro lado: `medirBarraDaBiblioteca` só escreve o que mudou.
if (window.ResizeObserver && bottombarEl) {
  new ResizeObserver(medirBarraDaBiblioteca).observe(bottombarEl);
}
sorteioBtnEl.addEventListener('click', abrirSorteio);
hymnSearchInputEl.addEventListener('input', debounce(() => renderSearchResults(hymnSearchInputEl.value), SEARCH_DEBOUNCE_MS));

// Mantém o indicador de Wi-Fi/dados móveis dos cards de coleção atualizado
// em tempo real (o navegador dispara 'change' quando o tipo de conexão muda).
(function () {
  const conn = networkConnection();
  if (conn && conn.addEventListener) conn.addEventListener('change', refreshCollectionsIfVisible);
})();

// Preview: FORA do fullscreen — toque simples coloca a PRÓPRIA preview em tela
// cheia (landscape); pressionar longo (~500 ms) abre as configurações de
// Exibição (fade/fit). A preview em tela cheia é a projeção direta pelo Controle
// (espelha a tela cheia do celular, sem depender do Miracast de app isolado).
//
// DENTRO do fullscreen — uma COLUNA DE ÍCONES na lateral direita (`#pvFsCtl`),
// que o toque acende e 4s sem toque apagam. Ela substituiu um mapa de GESTOS
// INVISÍVEIS (toque por terço, deslizes nos quatro sentidos, arrasto de volume)
// que não tinha como se anunciar: quem não o decorasse não tinha como
// descobri-lo, e um toque no lugar errado fazia outra coisa em cima da
// projeção.
//
// O que a coluna preserva do desenho antigo é a razão dele: sem TV conectada a
// preview em tela cheia É a projeção, e tudo o que se pinta aqui a congregação
// vê. Daí ela ser PASSAGEIRA (só ao toque, some sozinha) e TRANSLÚCIDA.
//
// A trava de paisagem (Screen Orientation API) só é permitida COM o elemento já
// em fullscreen (padrão de player de vídeo); é destravada ao sair.
(function setupPreviewGestures() {
  const isFs = () => document.fullscreenElement === previewEl;

  // ---- controles nos cantos da preview (fora do fullscreen) ----
  // Antes as ações eram gestos invisíveis sobre a preview (toque = tela cheia,
  // toque longo = popup de Exibição) — nada na tela dizia que existiam. Cada
  // uma virou um botão num canto, e por um tempo o toque na preview os
  // MOSTRAVA/ESCONDIA.
  //
  // **Esse toque saiu na v5.67: eles são permanentes.** Esconder era uma
  // resposta ao desenho errado — dois retângulos de vidro empilhados numa
  // coluna, que de fato tampavam a miniatura. Com os ícones sem moldura e nos
  // CANTOS (cast em cima, tela cheia embaixo) não há mais o que atrapalhar, e o
  // que sobrava era um estado escondido: uma preview sem botão nenhum não
  // anuncia que basta tocar nela para trazê-los — é o problema dos gestos
  // invisíveis de volta, com um passo a mais. Errar o alvo por 2px também
  // deixou de custar caro: antes o toque caía no reconhecedor de gestos e
  // sumia com a coluna inteira.
  //
  // São DOIS desde a v5.49 — a engrenagem virou o `#settingsBtn` fixo no topo
  // do mixer.
  document.getElementById('pvFullBtn').addEventListener('click', enterFullscreen);
  // Cast: no avançado só existe com o shell nativo (é um intent do Android) —
  // regra geral do projeto: o web é o padrão, o nativo é a exceção que se
  // declara. No SIMPLIFICADO ele aparece sempre, porque ali é o sinal de
  // conexão da preview e a porta de saída dela (ver renderSimpleCast): no
  // navegador, "desconectar" é fechar a janela do Display.
  // (Havia aqui um ramo para TRANCAR de volta a liberação de teste. Ele saiu na
  // v5.199 com ela.)
  pvCastBtnEl.addEventListener('click', () => abrirCast());

  // O SELO DE CAMADAS. Ele vive na mesma pilha dos outros dois botões da
  // preview, então herda o `pointer-events: auto` da `.pv-fab` — sem isso o
  // toque atravessaria para o reconhecedor de gestos da preview, que dentro da
  // tela cheia é o transporte inteiro.
  if (pvCamadaBtnEl) {
    pvCamadaBtnEl.addEventListener('click', (e) => {
      e.stopPropagation();
      encerrarCamadaDeCima();
    });
  }
  // O DESFAZER DO GIRO (v1.4.43) — mesma faixa, mesmo `stopPropagation`: a
  // preview inteira é o reconhecedor de gestos (dentro da tela cheia ele é o
  // transporte), e um toque que subisse daqui viraria comando de cena.
  if (pvGiroBtnEl) {
    pvGiroBtnEl.addEventListener('click', (e) => {
      e.stopPropagation();
      applyRotate(0);
    });
  }

  async function enterFullscreen() {
    try {
      if (previewEl.requestFullscreen) await previewEl.requestFullscreen();
      else if (previewEl.webkitRequestFullscreen) previewEl.webkitRequestFullscreen();
      try { await (screen.orientation && screen.orientation.lock && screen.orientation.lock('landscape')); } catch (_) {}
    } catch (_) {}
  }
  function exitFullscreen() { try { if (document.exitFullscreen) document.exitFullscreen(); } catch (_) {} }
  document.addEventListener('fullscreenchange', () => {
    // Nada a sincronizar nos botões: dentro da tela cheia quem os esconde é o
    // CSS (nada de UI sobre a projeção), e fora dela eles são permanentes.
    if (!document.fullscreenElement) { try { screen.orientation && screen.orientation.unlock && screen.orientation.unlock(); } catch (_) {} }
  });

  // ---- a coluna de controles (só em fullscreen) ----
  //
  // ELA SÓ VIVE 4 SEGUNDOS POR TOQUE. O relógio é reiniciado por QUALQUER toque
  // na projeção — inclusive num botão dela —, senão a coluna se apagaria no meio
  // de uma sequência de toques (passar três estrofes, subir o volume).
  //
  // E ELA NASCE ACESA (v1.3.10, a pedido do operador: *"quando se chega no
  // preview em tela cheia, eu preciso ver os botões, e depois eles
  // desaparecem"*). Entrar na tela cheia com a coluna apagada devolvia o
  // problema que ela veio resolver: um mapa de gestos invisíveis, agora com um
  // passo a mais — nada na tela dizia que havia o que tocar, e a única
  // descoberta possível era tocar no escuro. Mostrar UMA vez, e sumir, é o que
  // ensina sem cobrar tela: os 4s seguintes já são a projeção limpa.
  const FSCTL_MS = 4000;
  let fsTimer = null;

  function esconderFsCtl() {
    clearTimeout(fsTimer); fsTimer = null;
    if (fsCtlEl) fsCtlEl.classList.remove('visivel');
  }
  function acenderFsCtl() {
    if (!fsCtlEl || !isFs()) return;
    fsCtlEl.classList.add('visivel');
    renderFsCtl();
    clearTimeout(fsTimer);
    fsTimer = setTimeout(esconderFsCtl, FSCTL_MS);
  }

  // O TOQUE É UM INTERRUPTOR (v1.3.10, a segunda metade do mesmo pedido: *"o
  // toque para vê-los deve ser o mesmo toque em qualquer lugar que faz eles
  // desaparecerem quando visíveis"*). Antes ele só ACENDIA, e sumir era coisa
  // do relógio: quem quisesse a tela limpa antes dos 4s não tinha o que tocar,
  // e tocar de novo só reiniciava a contagem — o gesto existia num sentido só.
  //
  // O TOQUE QUE ACENDE CONTINUA NÃO SENDO O QUE ACIONA, e é o que sustenta o
  // interruptor: com a coluna apagada ela é `pointer-events: none`, então o
  // toque atravessa até aqui e só acende. Com ela no ar, um toque NUM BOTÃO
  // chega ao botão — e este `pointerdown`, que borbulha, precisa RENOVAR em vez
  // de apagar, senão comandar a projeção fecharia a coluna a cada comando. Só o
  // toque que cai FORA dela é que a esconde.
  //
  // O vão entre os botões conta como DENTRO (a coluna acesa é `pointer-events:
  // auto` inteira): errar o alvo por 2px renova, como sempre renovou — errar
  // custa um toque, nunca uma ação que não se pediu.
  previewEl.addEventListener('pointerdown', (e) => {
    if (!isFs() || !fsCtlEl) return;
    const naColuna = e.target && e.target.closest && e.target.closest('.pv-fsctl');
    if (!naColuna && fsCtlEl.classList.contains('visivel')) { esconderFsCtl(); return; }
    acenderFsCtl();
  });

  // ===== CADA BOTÃO ACIONA O CONTROLE DE VERDADE (invariante 5) =====
  if (fsCtlEl) {
    document.getElementById('fsExit').addEventListener('click', exitFullscreen);
    document.getElementById('fsView').addEventListener('click', () => {
      viewToggleEl.click(); renderFsCtl();
    });
    document.getElementById('fsPlay').addEventListener('click', () => {
      playPauseEl.click(); renderFsCtl();
    });
    // OS DOIS EIXOS DE GRAÇA: o mesmo `attachTransportStep` da barra de
    // transporte — toque curto passa estrofe, toque longo passa mídia. Escrever
    // aqui um segundo par de botões "estrofe" e "mídia" seria a mesma decisão
    // reimplementada, e ela envelheceria à parte.
    attachTransportStep(document.getElementById('fsPrev'), -1);
    attachTransportStep(document.getElementById('fsNext'), 1);
    // (O par de VOLUME saiu daqui na v1.1.2. Ele é o único controle desta
    // coluna com um alvo melhor FORA da tela: os botões físicos do aparelho,
    // que `captureVolumeKeys` já entrega ao mesmo fader — se acham no escuro,
    // não gastam os 4s de espera da coluna acender, e as duas vagas viraram vão
    // entre os cinco que ficaram.)
  }

  // ENTRAR ACENDE, SAIR APAGA. O apagar não é simetria: reentrar tem de começar
  // do estado limpo, senão a coluna reapareceria com o relógio de outra sessão
  // correndo — e o `acenderFsCtl` de baixo é justamente quem arma o relógio
  // novo. `esconderFsCtl` primeiro, sempre, para o caso de os dois eventos
  // chegarem juntos (sair de uma e entrar em outra tela cheia).
  document.addEventListener('fullscreenchange', () => {
    esconderFsCtl();
    if (isFs()) acenderFsCtl();
  });
})();

// O ESPELHO DOS DOIS BOTÕES DE ESTADO. Ele LÊ os controles de verdade em vez de
// reler o estado por conta própria: `playing` e `view` já têm um dono cada, e
// uma segunda leitura divergiria deles no primeiro caso de borda — que é a
// mesma razão pela qual os botões daqui acionam os de lá.
function renderFsCtl() {
  if (!fsCtlEl) return;
  const play = document.getElementById('fsPlay');
  const vis = document.getElementById('fsView');
  if (play) play.classList.toggle('alternado', playing);
  if (vis) {
    vis.classList.toggle('alternado', view === 'wallpaper');
    vis.title = viewToggleEl.title;
  }
}
// PREENCHIMENTO: o mesmo par de sempre (Ajustar × Preencher — "Esticar" saiu na
// v5.142 porque distorcia a proporção), agora alternado por um tile.
fitTileEl.addEventListener('click', () => { applyFit(mediaFit === 'cover' ? 'contain' : 'cover'); });
// Girar: AVANÇA 90° por toque, dando a volta. Ver `applyRotate`.
if (rotBtnEl) rotBtnEl.addEventListener('click', () => applyRotate(mediaRot + 90));
// Wallpaper: escolher imagem / voltar ao padrão.
wallFileEl.addEventListener('change', async () => {
  const file = (wallFileEl.files || [])[0];
  wallFileEl.value = '';
  if (file) await setWallpaper(file);
});
// O TILE DO WALLPAPER É UM `<label>` sobre o `<input type="file">`, e é a
// ATIVAÇÃO NATIVA dele que abre o seletor do aparelho (invariante 6). Com uma
// imagem própria no ar o toque faz o contrário — volta ao padrão —, e para isso
// a ativação do rótulo precisa ser CANCELADA: sem o `preventDefault()` o
// seletor de arquivos abriria por cima do reset que acabou de acontecer.
wallTileEl.addEventListener('click', (e) => {
  if (!customWallpaper) return;   // padrão: deixa o rótulo abrir o seletor
  e.preventDefault();
  setWallpaper(null);
});
// Estado do telão, no rodapé do popup de Exibição.
//
// O Display NÃO é mais um app que se "abre": é a `Presentation` que o shell
// cria sozinho na TV assim que uma tela de apresentação aparece — e recria
// quando o dongle cai e volta (o WebView recarrega /display/, dispara
// `display-ready` e o Controle reenvia o estado atual). Não há o que lançar,
// então aqui só se informa o que está conectado, ao vivo, pela ponte.
//
// No navegador não existe Presentation: o rodapé volta a ser o atalho para a
// tela do Display, útil para desenvolver a base web fora do app.
// O alvo de espelhamento deste aparelho, guardado como DADO (v5.193). Ele saía
// numa linha do rodapé de Configurações e o Registro a lia do DOM; a linha saiu
// (é assunto da folha de conexão, onde ela continua, no subtítulo do botão de
// espelhar) e o valor passou a morar aqui. Vazio no navegador.
let castAlvo = '';

// "Telão: …" para o Registro. Mesma frase que o rodapé mostrava, montada do
// `lastDisplays` em vez de lida de um `<span>` — ver `cabecalhoDiag`.
function descreverTelao() {
  if (!window.__NATIVE__) return 'navegador (sem Presentation)';
  const tv = lastDisplays[0];
  if (!tv) return 'nenhum conectado';
  // A TELA E O TELÃO SÃO DUAS COISAS, e este é o lugar em que a diferença tem
  // de aparecer: um Registro que diz "conectado" sobre uma TV sem
  // `Presentation` no ar manda investigar o app enquanto o que falhou foi a
  // janela — e é justamente esse o estado de "conectei e não veio nada".
  const est = tv.telao ? '' : ' — SEM TELÃO NO AR (a Presentation não subiu)';
  return 'conectado: ' + (tv.name || 'TV') + ' (' + tv.w + '\u00d7' + tv.h + ')' + est;
}

if (window.__NATIVE__) {
  const renderDisplayStatus = (list) => {
    const tv = (list && list[0]) || null;
    // A TRANSIÇÃO, antes de `lastDisplays` ser sobrescrito. O cabeçalho já diz
    // o estado AGORA; o que faltava era QUANDO mudou — e um dongle que oscila
    // rende uma escada de linhas que É o diagnóstico.
    const antes = lastDisplays[0] || null;
    const nomeDe = (d) => (d.name || 'TV') + (d.w ? ' (' + d.w + '×' + d.h + ')' : '');
    if (!antes && tv) diagC('TV conectada: ' + nomeDe(tv));
    else if (antes && !tv) diagC('TV DESCONECTADA (era ' + (antes.name || 'TV') + ')');
    else if (antes && tv && (antes.id !== tv.id || antes.w !== tv.w || antes.h !== tv.h)) {
      diagC('TV mudou: ' + nomeDe(tv));
    }
    // A PRESENÇA DO TELÃO, não a da tela: é ela que decide se o botão de
    // microfone existe (`haOndeReproduzirMic`), e é ela que precisa disparar o
    // redesenho da aba Ferramentas. Sem isto o botão só apareceria na próxima
    // vez que o operador TROCASSE de aba — isto é, a TV entra no meio do culto e
    // o microfone continua ausente, sem nada na tela explicando.
    //
    // E É O TELÃO, e não `lastDisplays.length`, desde o shell 59: quem capta o
    // microfone é o `/display/` dentro da `Presentation`, então uma tela listada
    // com a janela no chão não é lugar de reproduzir nada.
    const tinhaTela = lastDisplays.length > 0;
    const tinhaTelao = !!telaoNoAr();
    lastDisplays = list || [];
    const temTelao = !!telaoNoAr();
    // A DISTÂNCIA ENTRE A TELA E O TELÃO, na linha do tempo — e ela só é escrita
    // quando é NOTÍCIA. Uma conexão normal já sai na linha "TV conectada" acima;
    // o que aquela linha não sabe dizer é o estado que produz "conectei e não
    // veio nada, nem som": a tela listada com a `Presentation` no chão. As três
    // frases abaixo são as três bordas em que isso acontece.
    if (tv && !temTelao && (!tinhaTela || tinhaTelao)) {
      diagC('TV conectada, mas o TELÃO NÃO SUBIU (o shell vai retentar)');
    } else if (tv && temTelao && tinhaTela && !tinhaTelao) {
      diagC('o telão SUBIU (a TV já estava conectada)');
    }
    // SÓ NA TRANSIÇÃO. `refreshDiversos` esvazia o `libraryEl` e redesenha o
    // painel inteiro: rodá-lo a cada callback (o `onResume` reconfere a lista)
    // derrubaria o que o operador está usando — um campo com foco, uma lista
    // rolada — por um evento que não mudou nada.
    if (tinhaTelao !== temTelao) refreshDiversos();
    // Conectar (ou perder) o telão MUDA O REGIME da preview: com TV a projeção
    // é ela, chega no ato, e a preview volta a andar junto. Ver `cmd`.
    recalcularAtrasoPreview();
    // E MUDA QUEM TOCA O SOM: a TV entrando cala este aparelho, a TV caindo o
    // devolve à caixa de som. Ver `acertarSaidaDeAudio`.
    acertarSaidaDeAudio();
    renderSimpleCast();
    renderCast();          // a folha de conexão é quem mostra isto agora
    applyPreviewAspect(tv);
  };
  AVNative.displays().then(renderDisplayStatus);
  AVNative.onDisplayChange(renderDisplayStatus);
  // E RECONFERE AO VOLTAR PARA A FRENTE (v5.142). O aviso do shell é um evento,
  // e um evento perdido não se recupera sozinho: a tela pode cair (ou voltar)
  // com o app minimizado, e este WebView é estrangulado justamente aí. Uma
  // leitura na retomada — a lista, não um evento — é o piso que fecha esse
  // buraco, e é barata: uma consulta ao DisplayManager quando o operador pega o
  // aparelho de volta.
  reconferirTelas = () => { AVNative.displays().then(renderDisplayStatus); };
  // Para onde o botão de cast da preview abre neste aparelho. Espelhamento de
  // tela não é Google Cast, e o alvo muda por fabricante (Smart View na
  // Samsung, "Wireless display" no AOSP) sem API documentada — então o app
  // mostra o que encontrou em vez de deixar isso invisível.
  AVNative.castTarget().then((label) => {
    // NA FOLHA DE CONEXÃO, que é onde o operador decide, e SÓ ali (v5.193). Os
    // alvos de espelhamento variam por fabricante e não são API documentada:
    // ver ANTES de tocar é a diferença entre "abriu a tela errada" e "eu sabia
    // que ia abrir essa". O Registro continua tendo a linha, agora a partir
    // desta variável — ver `cabecalhoDiag`.
    // SÓ PARA O REGISTRO (v5.194). Ele já foi subtítulo do botão de espelhar
    // ("Abre: Smart View") — mas o operador não escolhe entre dois caminhos
    // pelo NOME do seletor que vai abrir, e quando o botão abre a tela errada a
    // resposta está no Registro, que é o que se copia para diagnosticar.
    castAlvo = label || '';
  });
} else {
  // NO NAVEGADOR ELE FICA, e é AÇÃO, não estado: sem `Presentation` não há quem
  // abra a tela do Display sozinho, e é assim que a base web se desenvolve fora
  // do aparelho. É o único caso em que este botão faz alguma coisa.
  openDisplayBtnEl.hidden = false;
  displayStatusTextEl.textContent = 'Abrir tela do Display';
  // Mesmo caminho do botão do simplificado: uma janela só (nome 'avDisplay') e
  // um só lugar que sabe se ela ainda está aberta.
  openDisplayBtnEl.addEventListener('click', openWebDisplay);
}


// ===== TELÃO POR COMANDOS: o telão nas telas da rede local =====
//
// O celular serve o próprio bundle na rede da igreja e cada navegador roda o
// `/web/display/` de verdade — até três, sem instalar nada neles e sem depender
// de internet. O que atravessa a rede são COMANDOS (os objetos JSON do
// barramento, verbatim, por SSE) e MÍDIA sob demanda (`/m/<token>`, com Range).
// Ver `docs/TELAO-POR-COMANDOS.md`.
//
// O QUE ESTE ARQUIVO FAZ, e só isto: desenha o interruptor, mostra o endereço
// e põe o operador no laço das telas conectadas. Nenhuma decisão de rede ou de
// pareamento mora aqui — o Kotlin devolve DADO (JSON) e a frase é montada deste
// lado, que é a mesma divisão do `otaDiag` e do `ytDiag`.
//
// **A transmissão é AUXILIAR por contrato, e a consequência que governa toda
// esta tela: ela NUNCA se desliga sozinha.** Liga por ação do operador e
// desliga por ação do operador, pelo fechamento do app, ou por uma falha que o
// app nomeia em texto. Uma TV que conecta não a derruba, e ligar com o telão no
// ar não pede confirmação nenhuma (ver `confirmarEspelhoComTv`, abaixo).
// Regra invertida seria pior que regra nenhuma: sem TV, as telas da rede SÃO o
// que a congregação vê, e um desligamento automático apagaria a projeção no
// meio do louvor.

// O piso de shell. Um método novo NÃO chega por OTA: num shell antigo a linha
// simplesmente não é desenhada, e volta sozinha quando o APK novo for
// instalado. É a mesma regra (e o mesmo motivo) do `appendYoutubeSearch`.
// (`MIRROR_POLL_MS` subiu para o topo na v5.195, junto do resto do estado de
// cena — ver o comentário de lá. Ele é lido na CARGA do módulo, e ficar aqui o
// deixava em zona morta temporal no aparelho.)

function espelhoDisponivel() {
  return !!window.__NATIVE__;
}

// (`mirrorEstado`, `mirrorTimer` e `mirrorOcupado` são declarados lá em cima,
// junto do resto do estado de cena — ver o comentário de lá para o porquê.)
// O NOME DA VIA para gente, num lugar só: o Kotlin manda a ENUM
// (`WIFI`/`PONTO_DE_ACESSO`) e quem escreve a frase é o web (invariante 5).
// Duas traduções em dois lugares divergiriam no primeiro ajuste, e a folha e o
// Registro passariam a chamar a mesma rede por nomes diferentes.
function mirrorVia(via) {
  if (via === 'PONTO_DE_ACESSO') return 'pelo ponto de acesso deste celular';
  if (via === 'WIFI') return 'pela Wi-Fi';
  return 'via desconhecida';
}

// O tipo da interface para gente. Mesma razão do `mirrorVia`: a ENUM é do
// Kotlin e a frase é do web.
function mirrorTipoIface(t) {
  if (t === 'PONTO_DE_ACESSO') return 'ponto de acesso';
  if (t === 'CABO') return 'cabo (nao usado)';
  return 'desconhecida (nao usada)';
}

function espelhoLigado() { return !!(mirrorEstado && mirrorEstado.ligado); }

async function lerEspelho() {
  if (!espelhoDisponivel()) return null;
  let e = null;
  try { e = await AVNative.espelhoEstado(); } catch (_) { e = null; }
  mirrorEstado = e || null;
  recalcularAtrasoPreview();
  // UMA TELA DA REDE ENTRANDO TAMBÉM CALA ESTE APARELHO — sem TV são elas a
  // projeção, e cada uma toca o próprio arquivo. Ver `acertarSaidaDeAudio`.
  acertarSaidaDeAudio();
  acertarEnqueteDeFundo();
  // E A FOLHA DE CONECTAR TAMBÉM (v5.184). Ela estava fora daqui desde que
  // nasceu: quem a redesenhava era só o `abrirCast`, então tudo o que ela
  // mostra ao vivo — o endereço que aparece quando o servidor sobe, a lista de
  // quem está vendo, a contagem no subtítulo — congelava no instante da
  // abertura. A enquete de 2,5 s existe justamente para essa folha estar viva
  // enquanto o operador olha para ela, e ela alimentava a outra.
  renderCast();
  // O ÍCONE DE CONECTAR ACOMPANHA — ele é quem diz "há tela recebendo" desde
  // que a notificação do espelho saiu da barra de status (v5.176). Sem esta
  // linha ele só seria repintado quando o TELÃO mudasse, e uma tela da rede
  // entrando não acenderia nada até a próxima troca de aba.
  renderCastBtn();
  // E O BLOQUEIO DO MODO FÁCIL (v5.193): desde que as telas da rede contam como
  // projeção (`simpleDisplay`), uma delas entrando é o que libera os controles
  // — e é aqui, na enquete, que isso se descobre. Sem esta linha o operador
  // ligava a transmissão, via a tela do saguão aparecer na lista e continuava
  // atrás da cortina até trocar de modo.
  renderSimpleGate();
  renderSimpleCast();
  return mirrorEstado;
}

// A ENQUETE DE FUNDO, e ela é de propósito bem mais lenta que a da folha.
//
// A folha enqueta a 2,5 s porque ali o operador está OLHANDO a fila de telas.
// Fora dela havia um consumidor só, e lento: o atraso da preview (ver `cmd`),
// que muda de 100 em 100 ms a cada oito segundos e por isso vivia bem com dez
// segundos de enquete.
//
// Desde a v5.176 há um SEGUNDO consumidor, e ele é um indicador de estado: o
// ícone de conectar, que passou a dizer "há tela recebendo" no lugar do cartão
// na barra de notificações. Aquele cartão se atualizava a cada tela que entrava
// ou saía; um ícone que levasse dez segundos para acender seria uma troca ruim.
// Quatro segundos é a resposta que o operador lê como imediata, e o custo é uma
// chamada de ponte com um JSON pequeno — só enquanto o espelho está no ar.
const MIRROR_FUNDO_MS = 4000;
let mirrorFundoTimer = null;

function acertarEnqueteDeFundo() {
  const precisa = espelhoDisponivel() && espelhoLigado();
  if (precisa && !mirrorFundoTimer) {
    mirrorFundoTimer = setInterval(() => { if (!mirrorTimer) lerEspelho(); }, MIRROR_FUNDO_MS);
  } else if (!precisa && mirrorFundoTimer) {
    clearInterval(mirrorFundoTimer);
    mirrorFundoTimer = null;
    recalcularAtrasoPreview();
  }
}

// (`MIRROR_TEXTO` e `renderEspelho` saíram na v5.196, com a folha de ajustes.
// O parágrafo de ressalvas virou UMA linha na folha de conexão, e o que o
// `renderEspelho` de fato fazia — acertar a enquete de fundo — era uma chamada
// só, que os chamadores passaram a fazer direto.)

// (O CERTIFICADO TLS saiu na v5.196, com a folha de ajustes que era a única
// porta dele — foram ~120 linhas: `CERT_SHELL`, `certDisponivel`,
// `lerCertEspelho`, `renderCertEspelho`, `importarCertEspelho` e
// `removerCertEspelho`. Ele nunca foi um interruptor: exige do operador um
// subdomínio com wildcard por DNS-01, uma entrada estática de DNS no roteador
// da igreja e renovação automática — e sem as três o espelho serve em HTTP
// claro, que é o que ele sempre fez. Os três métodos da ponte
// (`espelhoCertImportar`/`Estado`/`Apagar`) continuam no shell: voltar atrás é
// desenhar uma folha, não publicar uma Release.)

// LIGAR COM A TV NO AR não pede confirmação: a transmissão por comandos custa
// JSON e rajadas de arquivo — não há segunda projeção sendo desenhada e
// codificada no aparelho. A função abaixo fica (UM chamador, `ligarEspelho`)
// como registro da decisão de não perguntar.
async function confirmarEspelhoComTv() {
  return true;
}

// O QUE FAZER quando a recusa é de REDE, e SÓ nesses casos.
//
// O teste é por PALAVRA, nunca por igualdade com um literal: a frase é do
// Kotlin e é ele quem a escolhe, então comparar strings faria o ensino sumir
// no dia em que alguém corrigisse um acento. E ele precisa NÃO casar com a
// recusa de PORTA OCUPADA ("nao foi possivel abrir a porta 8787: …"), que é a
// única deste caminho com conserto diferente — ali a rede está certa e o que
// falta é fechar quem ocupou a porta.
//
// A palavra é larga de propósito ("rede", e não uma frase inteira): errar para
// MAIS custa uma instrução verdadeira num caso que não precisava dela; errar
// para MENOS deixa o operador sem o próximo movimento justamente no caso para
// o qual isto existe. Quem garante que a recusa de porta continua de fora é o
// `tools/recusa-transmissao.test.mjs`, que lê as frases do PRÓPRIO Kotlin.
const CAST_RECUSA_DE_REDE = /wi-?fi|ponto de acesso|rede/i;
const CAST_ENSINO = 'A transmissão não precisa de internet — precisa de uma rede. '
  + 'Ligue o ponto de acesso deste celular e conecte o computador nele, '
  + 'ou entre numa Wi-Fi qualquer (um roteador sem internet serve).';

// Limpa a mensagem da folha E o ensino, sempre juntos: um ensino de pé sob um
// endereço que já está servindo é pior que ensino nenhum.
function limparCastMsg() {
  texto2(castMsgEl, '');
  if (castEnsinoEl) { castEnsinoEl.hidden = true; texto2(castEnsinoEl, ''); }
}

// `ip` VAZIO = "escolha você", que é o caminho de todo aparelho com uma rede
// só. Ele só chega preenchido quando o operador ESCOLHEU entre duas — e a
// escolha só é desenhada quando de fato existem duas (ver `renderCastRedes`).
// Ver `docs/TELAO-POR-COMANDOS.md`.
async function ligarEspelho(ip) {
  if (mirrorOcupado) return false;
  if (!(await confirmarEspelhoComTv())) return false;
  mirrorOcupado = true;
  acertarEnqueteDeFundo();
  // O BOTÃO VIRA O RECADO agora, e não no próximo giro da enquete: é ele quem
  // diz "Ligando…" (ver `renderCast`), e uma resposta que chega até 2,5 s
  // depois do toque não é resposta.
  renderCast();
  let r = null;
  try { r = await AVNative.espelhoLigar(ip || ''); } catch (_) { r = null; }
  mirrorOcupado = false;
  mirrorEstado = r || null;
  acertarEnqueteDeFundo();
  // A falha é NOMEADA, sempre: "sem rede para transmitir — ligue o ponto de
  // acesso deste celular…", "nao foi possivel abrir a porta 8787: …". Um espelho
  // que não liga em silêncio é indistinguível de um botão quebrado.
  // …E ELA MORA NA FOLHA DE CONEXÃO (v5.207), que é de onde o interruptor foi
  // tocado. Antes saía numa faixa flutuante no topo da tela — sobre uma folha
  // que estava aberta bem embaixo dela, com o dedo e o olho no interruptor.
  // `#castMsg` já existia para as frases desta folha; a falha do espelho é uma
  // frase desta folha.
  // SÓ A RECUSA vira linha, e com a frase VERBATIM do shell. Um culto em que a
  // transmissão sobe de primeira não produz linha nenhuma; um em que ela não
  // sobe rende a escada que se lê — e a frase é o veredito de quem decidiu
  // (o Kotlin), não uma segunda opinião do web.
  if (!r) {
    diagC('transmissão: a ponte não respondeu');
    limparCastMsg();
    texto2(castMsgEl, 'A transmissão não respondeu.'); return false;
  }
  if (r.erro) {
    diagC('transmissão RECUSADA: ' + r.erro);
    limparCastMsg();
    // O VEREDITO SAI VERBATIM (é de quem decidiu), e o ensino vem SEPARADO
    // embaixo. Juntá-los faria a frase do Kotlin virar prosa do web, que é
    // exatamente o que a invariante 5 recusa.
    texto2(castMsgEl, r.erro);
    if (castEnsinoEl && CAST_RECUSA_DE_REDE.test(r.erro)) {
      texto2(castEnsinoEl, CAST_ENSINO);
      castEnsinoEl.hidden = false;
    }
    return false;
  }
  // O SUCESSO NÃO PRECISA DE FRASE (a regra da v5.194): o endereço aparecendo
  // logo abaixo, com o rótulo que diz o que fazer com ele, É o "deu certo".
  limparCastMsg();
  return true;
}

async function desligarEspelho() {
  if (mirrorOcupado) return;
  mirrorOcupado = true;
  acertarEnqueteDeFundo();
  renderCast();   // "Desligando…" no próprio botão — ver `ligarEspelho`
  try { AVNative.espelhoDesligar(); } catch (_) { /* ponte */ }
  // `espelhoDesligar` volta na hora (escreve um campo e sai — ver o KDoc da
  // ponte): a demolição acontece logo depois, na main thread do shell. Sem esta
  // folga a releitura pegaria o estado ANTERIOR e a folha diria "ligado" por um
  // ciclo. O relógio da folha aberta corrige de qualquer jeito; isto é para o
  // toque ter resposta imediata.
  await new Promise((r) => setTimeout(r, 300));
  mirrorOcupado = false;
  await lerEspelho();
  // Idem: quem responde é a própria folha. E aqui o sinal já é visível sem
  // frase nenhuma — o endereço e a lista de telas somem —, então ela só limpa
  // o que estivesse escrito.
  limparCastMsg();
}

// ============================================================================
// A FOLHA DE CONECTAR UMA TELA — as duas formas, num lugar só
// ============================================================================
//
// O botão de cast sempre significou "pôr isto noutra tela". Até a v5.156 ele
// abria direto o espelhamento do fabricante, e o espelho na rede — que responde
// exatamente a mesma intenção — vivia numa linha de Configurações que só quem
// já sabia da existência dele iria procurar. São dois caminhos técnicos para
// uma decisão só do operador, e quem escolhe entre eles tem de ser ele.
//
// A folha mostra os dois com a diferença DITA, porque ela é real: o
// espelhamento manda a TELA INTEIRA do celular (e é o caminho da TV da igreja);
// o espelho na rede manda SÓ O TELÃO, para navegadores, sem instalar nada.
//
// E elas têm FORMAS diferentes desde a v5.184, porque são coisas diferentes:
// espelhar é uma AÇÃO que sai do app (abre o seletor do fabricante, e o assunto
// termina ali); transmitir pelo site é um ESTADO que dura o culto inteiro e que
// o operador precisa ver, ligar e desligar. Botão para a primeira, interruptor
// para o segundo.

function abrirCast() {
  if (!castPopupEl) { if (window.__NATIVE__) AVNative.openCast(); else openWebDisplay(); return; }
  // O BLOCO PODE ESTAR NA OUTRA CASA (v5.193): no Modo Fácil sem tela ele vive
  // dentro da própria tela. Abrir a folha sem trazê-lo de volta mostraria um
  // cartão vazio.
  hostCastConn(false);
  castPopupEl.classList.add('open');
  // RE-ARMA A MEMÓRIA DO FECHO AUTOMÁTICO (v5.217): a folha que ACABA de abrir
  // parte do estado de agora, então "uma tela entrou" passa a significar
  // "entrou depois que abri isto". Ver `renderSimpleGate`.
  gateTinhaTela = !!simpleDisplay();
  limparCastMsg();
  // O espelho na rede só existe no app, e só num shell que tenha os métodos.
  // No navegador a folha degrada para uma escolha só, que é a honesta.
  if (castNetBtnEl) castNetBtnEl.hidden = !espelhoDisponivel();
  renderCast();
  if (espelhoDisponivel()) {
    // ABRIR A FOLHA NÃO LIGA MAIS NADA (v5.184), e isto DESFAZ a decisão da
    // v5.171 de propósito, não por esquecimento.
    //
    // Aquela decisão fazia sentido enquanto a rede era um CARTÃO DE ESCOLHA:
    // um cartão não tem como mostrar "ligado", então a folha ligava sozinha
    // para que o endereço estivesse lá. O preço, que não estava dito, é que
    // não havia como abrir esta tela para conferir o endereço, o alvo de
    // espelhamento ou quem está vendo sem SUBIR UM SERVIDOR na rede da igreja
    // — e, com o telão no ar, sem disparar a pergunta do custo dobrado.
    //
    // Com um interruptor o problema desaparece do outro lado: o estado é
    // visível parado, e quem o muda é o operador. Um interruptor que já nasce
    // ligado toda vez que a tela abre não é um interruptor, é um rótulo.
    //
    // (A enquete de 2,5 s deixou de ser ligada aqui na v5.199: quem a decide é
    // a VISIBILIDADE do bloco, que tem duas casas — ver `acertarEnqueteDaConexao`.)
  }
  acertarEnqueteDaConexao();
}

function fecharCast() {
  castPopupEl.classList.remove('open');
  // (Havia aqui um `clearInterval(mirrorTimer)` incondicional. Ele saiu na
  // v5.199: fechar a FOLHA não pode apagar a enquete quando quem a acendeu foi
  // a TELA do Modo Fácil — ver `acertarEnqueteDaConexao`.)
  acertarEnqueteDaConexao();
}

// Um `textContent` que aceita elemento nulo — a folha existe só no bundle novo.
function texto2(el, s) { if (el) el.textContent = s; }

// O bloco de conexão está de fato APARECENDO? Ele tem duas casas (ver
// `hostCastConn`), e a pergunta muda conforme a casa.
//
// **Não dá para perguntar ao layout.** A primeira versão disto usava
// `offsetParent === null`, e ela está errada por uma razão que não se vê lendo:
// `.popup-backdrop` esconde por `opacity: 0` + `pointer-events: none`, NÃO por
// `display: none` — então um popup fechado tem `offsetParent` normal e a guarda
// nunca barrava nada. Perguntar por estado, e não por pixel, é o que funciona
// nos dois casos.
function castConnVisivel() {
  if (!castConnEl) return false;
  return castConnEl.parentElement === simpleConnEl
    ? !simpleConnEl.hidden
    : !!castPopupEl && castPopupEl.classList.contains('open');
}

// A REDE ESCOLHIDA PELO OPERADOR, em IP — e ela é de IDA: morre com a página,
// como o resto do estado desta folha. Guardá-la entre sessões faria o app
// insistir numa rede que só existia no sábado passado, e a recusa que sairia
// disso ("a rede escolhida nao esta mais disponivel") seria sobre uma escolha
// que ninguém lembra de ter feito.
let castRedeEscolhida = '';

// A ESCOLHA DA REDE — desenhada só quando há MAIS DE UMA e a transmissão está
// desligada. Ver o comentário do bloco no HTML.
//
// Ela não decide nada sozinha: `ligarEspelho('')` continua sendo o caminho de
// quem tem uma rede só, e o shell escolhe a primeira (ponto de acesso na
// frente). O que ela faz é dar nome às duas quando as duas existem.
function renderCastRedes(e, ligado) {
  if (!castRedesEl) return;
  const redes = Array.isArray(e.redes) ? e.redes : [];
  const mostrar = !ligado && redes.length > 1;
  castRedesEl.hidden = !mostrar;
  if (!mostrar) { castRedesEl.textContent = ''; return; }
  // A escolha some quando a rede some — senão o toque seguinte pediria um
  // endereço que já não existe e colheria uma recusa que não explica nada.
  if (castRedeEscolhida && !redes.some((r) => r.ip === castRedeEscolhida)) castRedeEscolhida = '';
  const alvo = castRedeEscolhida || redes[0].ip;
  const chave = redes.map((r) => r.ip).join('|') + '#' + alvo;
  // Redesenhar a cada 2,5 s recriaria os botões debaixo do dedo — a mesma
  // lição de `renderCastTelas`. Só se a lista ou a escolha mudarem.
  if (castRedesEl.dataset.chave === chave) return;
  castRedesEl.dataset.chave = chave;
  castRedesEl.textContent = '';
  redes.forEach((r) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'cast-rede' + (r.ip === alvo ? ' active' : '');
    b.setAttribute('aria-pressed', r.ip === alvo ? 'true' : 'false');
    b.textContent = r.via === 'PONTO_DE_ACESSO' ? 'Ponto de acesso' : 'Wi-Fi';
    b.addEventListener('click', () => { castRedeEscolhida = r.ip; renderCast(); });
    castRedesEl.appendChild(b);
  });
}

function renderCast() {
  if (!castConnVisivel()) return;
  const ligado = espelhoLigado();
  const e = mirrorEstado || {};
  const telas = Array.isArray(e.telas) ? e.telas : [];
  // O INTERRUPTOR REFLETE O SHELL, nunca o toque. Ligar é assíncrono, pode
  // pedir confirmação (o custo dobrado com o telão no ar) e pode ser recusado
  // com uma frase — então quem escreve `checked` é sempre a leitura do estado,
  // e o toque só PEDE. Sem isto, uma recusa deixaria a chave na posição de uma
  // coisa que não aconteceu.
  if (castNetBtnEl) {
    // O BOTÃO REFLETE O SHELL, nunca o toque — a mesma regra que valia para o
    // interruptor: ligar é assíncrono, pode pedir confirmação (o custo dobrado
    // com o telão no ar) e pode ser recusado com uma frase. Quem escreve o
    // estado é sempre a leitura, e o toque só PEDE; senão uma recusa deixaria o
    // botão vermelho de uma coisa que não aconteceu.
    castNetBtnEl.classList.toggle('ligado', ligado);
    castNetBtnEl.disabled = mirrorOcupado;
    if (castNetLabelEl) {
      // Ligado, o rótulo nomeia a AÇÃO (é o que o toque faz); desligado, ele
      // nomeia o DESTINO, que é o que ajuda a escolher entre as duas formas de
      // conectar. Ver o comentário do botão no HTML.
      //
      // E ENQUANTO O SHELL RESPONDE ELE É O PRÓPRIO RECADO (v5.227). O "Ligando
      // a transmissão…" saía numa linha de 0,78 rem ABAIXO do botão — o
      // operador acabara de tocar ali, e a resposta aparecia noutro lugar, no
      // menor texto da folha, ao mesmo tempo em que a folha inteira se
      // reorganizava. O botão é onde o olho já está.
      //
      // `mirrorOcupado` com `ligado` FALSO é "ligando" (o servidor ainda não
      // subiu); com `ligado` verdadeiro é "desligando". Os dois saem da mesma
      // leitura de estado que pinta a cor — não há um terceiro lugar guardando
      // "o que eu pedi", que é justamente o que divergiria numa resposta lenta.
      castNetLabelEl.textContent = mirrorOcupado
        ? (ligado ? 'Desligando…' : 'Ligando…')
        : (ligado ? 'Desligar transmissão' : 'Conectar um computador');
    }
  }
  // O BOTÃO DE ESPELHAR DIZ QUAL TV ESTÁ NO AR (v5.196). Ele levava a folha de
  // "Ajustes avançados" a existir com um botão de desligar dentro; agora o
  // estado mora no próprio botão, que é onde a decisão é tomada.
  //
  // O RÓTULO NÃO VIRA "Desconectar", e isso é honestidade, não timidez: o app
  // não tem como derrubar um espelhamento — não existe API pública — e o toque
  // abre o MESMO seletor do Android nos dois estados. É lá que se desconecta.
  // Um botão escrito "Desconectar" que abre uma lista seria uma promessa que a
  // tela seguinte não cumpre.
  //
  // E O VERBO É "CONECTAR", NÃO "ESPELHAR" (v1.0.2). O botão abre o seletor de
  // espelhamento do Android — mas é o telão que vai para a TV, não a tela do
  // celular, e é justamente essa a diferença que o app inteiro existe para
  // fazer. Chamar a ação de "espelhar" anunciava ao operador o oposto do que
  // ele recebe. O que se lê no seletor do fabricante continua sendo o nome
  // dele; aqui se diz o DESFECHO.
  const tv = window.__NATIVE__ ? (lastDisplays[0] || null) : null;
  if (castMirrorLabelEl) {
    // "Conectado" descrevia a TELA e era lido como "o telão está lá". Com a
    // `Presentation` no chão o operador via o rótulo verde sobre uma TV que não
    // mostra nada — e a folha de conexão é exatamente onde ele vai procurar
    // resposta. Ver `telaoNoAr`.
    castMirrorLabelEl.textContent = !tv
      ? 'Conectar uma TV'
      : tv.telao
        ? 'Conectado: ' + (tv.name || 'TV')
        : 'Conectado a ' + (tv.name || 'TV') + ' — o telão não subiu, tentando de novo';
  }
  if (castMirrorBtnEl) castMirrorBtnEl.classList.toggle('connected', !!tv);
  // O AVISO DO SOM (ver o comentário no HTML), e ele SÓ EXISTE COM TV NO AR:
  // sem ela não há para onde vazar, e um aviso permanente sobre uma
  // consequência que ainda não aconteceu é ruído na folha em que se decide
  // conectar. A frase nomeia o que o operador RECONHECE ("vídeo ou áudio de
  // outro app"), não a categoria do Android que a explica — o `USAGE_MEDIA`
  // fica no Registro, que é onde a afirmação precisa ser estrita.
  if (castMirrorNotaEl) {
    castMirrorNotaEl.hidden = !tv;
    castMirrorNotaEl.textContent = tv
      ? 'O som deste celular vai junto: vídeo ou áudio de outro app é ouvido nas caixas.'
      : '';
  }
  // (O subtítulo do interruptor saiu na v5.194: desligado ele descrevia o
  // recurso para quem já decidiu usá-lo, e ligado dizia "N tela(s) recebendo" —
  // que é exatamente o que a LISTA logo abaixo mostra, com nome e tempo de
  // cada uma. Contar o que já está listado é dizer duas vezes.)

  // O ENDEREÇO E QUEM ESTÁ VENDO, nesta mesma folha.
  // A CLASSE, e não `hidden`: é ela que dispara a expansão (ver `#castLive` em
  // controle.css). Ela é escrita SEMPRE — inclusive no `return` de baixo —,
  // senão desligar deixaria o bloco aberto com o endereço de um servidor que já
  // caiu.
  renderCastRedes(e, ligado);
  if (castLiveEl) castLiveEl.classList.toggle('aberto', ligado);
  if (!ligado) return;
  // O RÓTULO NOMEIA A REDE. "Acesse no navegador" está certo e é inútil com o
  // ponto de acesso servindo: o que decide se o endereço responde é o outro
  // aparelho estar CONECTADO ÀQUELA rede, e essa é a instrução que falta.
  if (castRotEl) {
    castRotEl.textContent = e.via === 'PONTO_DE_ACESSO'
      ? 'No computador conectado ao ponto de acesso deste celular, acesse'
      : 'No navegador de um aparelho na mesma Wi-Fi, acesse';
  }
  // UM ENDEREÇO SÓ (v5.185): o IP. O `av.local` saiu com o responder mDNS —
  // ele não resolve no Chrome do Android nem na maioria das Smart TVs, que são
  // exatamente as telas deste recurso.
  texto2(castUrlEl, e.endereco || '');
  // (A FRASE DE INSTRUÇÃO SAIU na v5.194, e com ela o par "primeira tela × mais
  // uma": as duas diziam a mesma coisa com palavras trocadas, e o que elas
  // pediam agora está no rótulo do próprio endereço. O "toque em Ativar esta
  // tela" também saiu daqui — quem precisa dessa instrução é quem está NA
  // OUTRA TELA, e lá ela está escrita no botão, que é onde ela serve.)
  renderCastTelas(telas);
}

// QUEM ESTÁ VENDO, com o botão de derrubar ao lado.
//
// Com a porta aberta, esta lista deixou de ser uma FILA de aprovação e virou o
// controle de verdade: o dano de um curioso na rede não é ele ver o que a
// congregação já vê, é ele ocupar uma das três vagas. Ver e poder derrubar é a
// resposta a isso — e é por isso que a lista subiu para a folha principal.
// A LISTA É UM DIFF, e não um `innerHTML = ''` (v5.226).
//
// Ela era refeita por inteiro a cada leitura do estado — e o estado é lido de
// 2,5 em 2,5 segundos enquanto a folha está aberta. Duas consequências, e a
// segunda é a que este lote existe para corrigir: o botão "Desconectar" era
// recriado debaixo do dedo do operador (perdendo o `disabled` que o toque
// acabara de escrever), e QUALQUER animação de entrada recomeçaria sozinha a
// cada 2,5 s, para sempre.
//
// Com as linhas reaproveitadas por RÓTULO, só o que de fato mudou se mexe: uma
// tela nova entra com a animação, uma que saiu se recolhe antes de ser removida
// do documento, e as demais só têm o texto atualizado no lugar.
const CAST_TELA_SAI_MS = 180;   // igual ao `castTelaSai` do CSS
function renderCastTelas(telas) {
  if (!castTelasEl) return;
  const vazia = !telas.length;
  const chaves = new Set(vazia ? ['__vazia'] : telas.map((t, i) => t.rotulo || ('tela' + i)));
  // O QUE SAIU: recolhe agora e some depois da animação. A marca `saindo` também
  // o tira da conta de reaproveitamento — uma tela que volte a aparecer no
  // meio da saída entra como linha nova, e não herda uma animação de despedida.
  Array.from(castTelasEl.children).forEach((li) => {
    if (chaves.has(li.dataset.chave) && !li.classList.contains('saindo')) return;
    if (li.classList.contains('saindo')) return;
    li.classList.add('saindo');
    li.dataset.chave = '';
    setTimeout(() => li.remove(), CAST_TELA_SAI_MS);
  });
  const achar = (chave) => Array.from(castTelasEl.children)
    .find((li) => li.dataset.chave === chave && !li.classList.contains('saindo'));

  if (vazia) {
    if (achar('__vazia')) return;
    const li = document.createElement('li');
    li.className = 'cast-tela cast-tela--vazia entrando';
    li.dataset.chave = '__vazia';
    li.textContent = 'Nenhuma tela conectada ainda.';
    limparEntrada(li);
    castTelasEl.appendChild(li);
    return;
  }

  telas.forEach((t, i) => {
    const chave = t.rotulo || ('tela' + i);
    // O RÓTULO é o do servidor ("tela B"), e não o User-Agent: numa lista de
    // três, o que o operador precisa é distinguir uma da outra, e um UA de 120
    // caracteres não distingue nada. O detalhe fica no Registro.
    const texto = (t.rotulo || 'tela')
      + (t.conectadaMs ? ' · ' + mirrorDur(t.conectadaMs) : '');
    const existente = achar(chave);
    if (existente) {
      // Só o texto, e só se mudou: reescrever um `textContent` igual a cada
      // 2,5 s não muda um pixel, mas interrompe a seleção de quem estiver
      // copiando o nome.
      const alvo = existente.querySelector('.cast-tela-nome');
      if (alvo && alvo.textContent !== texto) alvo.textContent = texto;
      return;
    }
    const li = document.createElement('li');
    li.className = 'cast-tela entrando';
    li.dataset.chave = chave;
    const nome = document.createElement('span');
    nome.className = 'cast-tela-nome';
    nome.textContent = texto;
    const fora = document.createElement('button');
    fora.type = 'button';
    fora.className = 'cast-tela-fora';
    fora.textContent = 'Desconectar';
    fora.addEventListener('click', async () => {
      fora.disabled = true;
      try { await AVNative.espelhoDerrubar(t.rotulo || ''); } catch (_) { /* ponte */ }
      lerEspelho();
    });
    li.append(nome, fora);
    limparEntrada(li);
    castTelasEl.appendChild(li);
  });
}

// A MARCA DE ENTRADA SAI QUANDO A ANIMAÇÃO ACABA. Ela é `both`, então o estado
// final dela GRUDA — e o estado final inclui um teto de altura (`max-height`)
// que existe só para a animação ter de onde crescer. Deixá-lo ali recortaria a
// linha no dia em que ela precisasse de duas linhas.
function limparEntrada(li) {
  li.addEventListener('animationend', () => li.classList.remove('entrando'), { once: true });
}

// Os ouvintes da seção de conexão. A guarda é o BOTÃO DE ESPELHAR (v5.196):
// era o link "Ajustes avançados", que saiu com a folha dele — e uma guarda que
// aponta para um elemento removido desliga EM SILÊNCIO tudo o que está dentro
// dela, inclusive o interruptor da transmissão.
if (castMirrorBtnEl) {
  // ESPELHAR: abre o seletor do Android, e é ele quem CONECTA E DESCONECTA a
  // TV. O app não tem como derrubar um espelhamento — não existe API pública
  // para isso —, então o botão leva ao mesmo lugar nos dois estados; o que muda
  // é ele DIZER qual TV está no ar (ver `renderCast`), que é a informação que
  // faltava para o toque não ser um pulo no escuro.
  castMirrorBtnEl.addEventListener('click', () => {
    if (window.__NATIVE__) AVNative.openCast();
    else openWebDisplay();
  });
  // ATIVAR (E DESLIGAR) A TRANSMISSÃO PELO SITE: este botão é a única coisa
  // desta folha que sobe ou derruba o servidor.
  //
  // Ele é o IRMÃO do de espelhar desde a v5.224 — era um interruptor —, e a
  // diferença de mecânica é uma só: um `change` de caixa de marcação já vem com
  // a posição nova, e um clique não vem com nada. O que o operador pediu passa
  // a ser DERIVADO do estado atual (`!espelhoLigado()`), que é a mesma fonte que
  // o `renderCast` usa para pintar o botão — então não há duas versões da
  // verdade a divergirem no meio de uma resposta lenta.
  castNetBtnEl.addEventListener('click', async () => {
    if (!espelhoDisponivel()) return;
    const quer = !espelhoLigado();
    // O BOTÃO FECHA ENQUANTO O SHELL RESPONDE. Ligar espera uma confirmação e
    // uma resposta da ponte; um segundo toque nesse intervalo cairia na guarda
    // de `mirrorOcupado` e voltaria `false` — indistinguível, na tela, de uma
    // recusa de verdade ("não deu para ligar") por um toque que o operador deu
    // só porque o primeiro parecia não ter feito nada.
    castNetBtnEl.disabled = true;
    if (quer) {
      // (O "Ligando a transmissão…" saía aqui, no `#castMsg`. Ele virou o
      // RÓTULO do botão na v5.227 — ver `renderCast`. A linha de baixo ficou
      // com o que ela sempre soube dizer melhor: a FALHA, que é uma frase
      // inteira vinda do shell e não caberia num botão.)
      const ok = await ligarEspelho(castRedeEscolhida);
      // A frase da falha já saiu por `texto2(castMsgEl, …)` (ela vem pronta do
      // Kotlin). Aqui fica a saída — e ela aponta para onde o operador pode agir.
      // O SUCESSO NÃO PRECISA DE FRASE (v5.194): o endereço aparecendo logo
      // abaixo, com o rótulo que diz o que fazer com ele, É o "deu certo". A
      // falha continua falando, porque ali não há nada que apareça sozinho.
      // (Até a v5.206 esta linha dizia "veja o aviso acima" e apontava para a
      // faixa flutuante. Com o motivo escrito AQUI pelo `ligarEspelho`, mandar
      // o operador olhar para outro lugar seria mandá-lo olhar para o lugar
      // onde a mensagem deixou de estar — então ela só não sobrescreve.)
      if (ok) limparCastMsg();
    } else {
      await desligarEspelho();
      limparCastMsg();
    }
    renderCast();
  });
  // TOCAR NESTE CELULAR: a terceira porta da folha, e a única que não conecta
  // nada. O que o operador pediu é DERIVADO do estado atual, como no irmão de
  // cima — um clique não vem com a posição nova, e ler `tocarNoCelular` aqui é
  // ler a mesma fonte que `renderCastLocal` acabou de pintar.
  if (castLocalBtnEl) {
    castLocalBtnEl.addEventListener('click', () => setTocarNoCelular(!tocarNoCelular));
  }
  acertarEnqueteDeFundo();
}

// Fechamento dos bottom-sheets: todos se comportam igual — o ✕ fecha e tocar
// no fundo (fora da folha) também. O par de listeners estava copiado seis
// vezes; aqui é uma tabela, e um popup novo entra com uma linha.
// A mesma tabela é a fonte do botão VOLTAR do Android (ver `__avBack`): um
// popup novo entra numa linha e já passa a ser fechável pelos três caminhos
// (✕, toque no fundo, botão do aparelho). Duas listas divergiriam no primeiro
// popup que alguém esquecesse de acrescentar na segunda.
// **Ordenada de BAIXO para CIMA**: o voltar percorre de trás para a frente e
// fecha o primeiro aberto, então o que fica por último é o que está por cima.
// (`collPopup`, as opções da coleção, saiu na v5.72: elas viraram um painel
// DENTRO do card do álbum, e um painel não é uma camada — quem o fecha é o
// mesmo toque na engrenagem que o abriu, ou o toque na barra que fecha o card.)
const POPUPS = [
  // A BIBLIOTECA É A PRIMEIRA LINHA desde a v1.5.6, e a razão é a mesma do
  // `z-index: 190` dela: **ela não é um modal sobre o app, é mobília do app** —
  // a camada existe SEMPRE (a barra vive nela) e fica ABAIXO de toda folha.
  // Como o voltar percorre esta tabela de trás para a frente, estar em primeiro
  // é estar embaixo: com a Biblioteca aberta, abrir a playlist e tocar em voltar
  // fecha a playlist, não a Biblioteca. As duas coisas dizem a mesma ordem, e
  // mudar uma sem a outra é o acaso que já cobriu um popup por inteiro aqui.
  //
  // O BOTÃO DA BIBLIOTECA ENTRA COMO `null`, e isso é o recurso: ele é um
  // ALTERNADOR (seta abre, ✕ fecha) e tem ouvinte próprio. Registrado aqui
  // também, o toque com a janela fechada abriria pelo ouvinte dele e fecharia
  // pelo desta tabela, no mesmo clique — a janela pisca e nada acontece. O que
  // a linha continua entregando é o resto do contrato: o toque no fundo e o
  // degrau do voltar.
  [hymnSearchPopupEl, null, closeHymnSearch],
  [plPopupEl, plPopupCloseEl, closePlPopup],
  [bibleVerPopupEl, bibleVerCloseEl, closeBibleVerPopup],
  [fadePopupEl, fadePopupCloseEl, closeFadePopup],
  // O HISTÓRICO abre DE DENTRO de Configurações (v1.4.31 — era vizinho da
  // playlist, de onde ele abria antes), então vem DEPOIS dela: o voltar
  // percorre esta tabela de trás para a frente, e fechar o histórico tem de
  // devolver o operador à folha de onde ele saiu. O `z-index` de `#histPopup`
  // diz a MESMA ordem, e mudar uma sem a outra é o acaso que já cobriu um
  // popup por inteiro aqui.
  [histPopupEl, histPopupCloseEl, closeHistPopup],
  // A folha de CONECTAR UMA TELA abre da tela principal (o botão de cast), e
  // vem antes das duas que nascem dela — o voltar percorre esta tabela de trás
  // para a frente.
  [castPopupEl, castCloseEl, fecharCast],
  // (A folha de "Ajustes avançados" do espelho e o leitor de QR tinham linha
  // aqui; saíram na v5.196 e na v5.185.)
  [lyricsPopupEl, lyricsPopupCloseEl, closeLyricsPopup],
  // A folha da música abre DE DENTRO do acervo: o voltar percorre esta tabela
  // de trás para a frente, então a ordem aqui é a ordem em que as camadas se
  // empilham. (O `#folderPopup`, o seletor de atalhos, saiu na v5.254.)
  [songMenuPopupEl, songMenuCloseEl, closeSongMenu],
  // A PLAYLIST AUTOMÁTICA abre de dentro da Biblioteca e não abre nada por
  // cima de si — daí ser a ÚLTIMA linha (o voltar percorre de trás para a
  // frente) e ter o degrau mais alto de `z-index` (220, em controle.css). As
  // duas coisas dizem a mesma ordem, e mudar uma sem a outra é o acaso que já
  // cobriu um popup por inteiro aqui.
  [sorteioPopupEl, sorteioCloseEl, fecharSorteio],
];
// A FOLHA DE FERRAMENTAS fica FORA da tabela, e não por esquecimento: ela não é
// um `.popup-backdrop` (não há camada sobre a tela toda, não há fundo escurecido
// e o toque fora dela cai no app, que continua alcançável de propósito). O que
// ela compartilha com a tabela é o ✕ e o degrau do voltar, e os dois estão
// escritos aqui e no `__avBack`.
if (toolsCloseEl) toolsCloseEl.addEventListener('click', fecharFerramentas);

POPUPS.forEach(([backdrop, closeBtn, close]) => {
  if (closeBtn) closeBtn.addEventListener('click', close);
  // Só o próprio backdrop: um clique dentro da folha não fecha.
  backdrop.addEventListener('click', (e) => { if (e.target === backdrop) close(); });
});

// ===== Botão VOLTAR do aparelho (`__avBack`) =====
// Até a v5.32 o voltar só mandava a tarefa para segundo plano — sair por engano
// no meio de um culto derrubaria a projeção, e essa continua sendo a regra no
// fim da fila. O que faltava era a fila: com um popup aberto, uma pasta aberta
// ou a preview em tela cheia, o gesto que TODO usuário de Android conhece para
// "fechar isto" minimizava o app inteiro.
//
// Devolve `true` se consumiu o toque; `false` faz a Activity minimizar (ver
// MainActivity.onBackPressedDispatcher). A ordem é do mais efêmero ao mais
// permanente — é a ordem em que as coisas foram abertas, e portanto a ordem em
// que se espera desfazê-las.
//
// Vive só no app: no navegador não há botão voltar do sistema, e a base precisa
// continuar rodando lá (por isso nada aqui depende de `history`).
window.__avBack = function () {
  // 1. Diálogo modal (confirmar/renomear): cancela, como o botão Cancelar.
  if (appDialogEl.classList.contains('open')) {
    closeAppDialog(appDialogInputEl.hidden ? false : null);
    return true;
  }
  // (O passo 1.5 — a hierarquia DE DENTRO da gaveta de Favoritos — saiu na
  //    v5.294 com a própria gaveta. O passo 5, genérico, continua cuidando da
  //    seleção múltipla feita na lista.)
  // 1.5. A TELA CHEIA DA CIFRA (v1.6.0). Ela é um MODO DA FOLHA: foi aberta
  //    depois dela, e a ordem desta fila é do mais efêmero ao mais permanente —
  //    logo é desfeita antes. Deixá-la para o degrau 3 seria o defeito concreto:
  //    o degrau 2 fecharia a folha com ela AINDA em tela cheia, e tirar `.open`
  //    só muda opacidade e `pointer-events` — o elemento continua na top layer e
  //    a Activity continua deitada. Sair aqui deixa a folha ABERTA, no retrato;
  //    o toque seguinte a fecha.
  if (document.fullscreenElement === lyricsPopupEl) { cifraCheiaSair(); return true; }
  // 2. Bottom-sheets. Fecha o ÚLTIMO da tabela que estiver aberto — normalmente
  //    há um só, mas se houver dois o de cima é o que o operador vê.
  for (let i = POPUPS.length - 1; i >= 0; i--) {
    const [backdrop, , close] = POPUPS[i];
    if (backdrop.classList.contains('open')) { close(); return true; }
  }
  // 2.5. A folha de Ferramentas. Depois dos bottom-sheets porque um deles pode
  //    abrir DE DENTRO dela (a folha da música, pelo sorteio), e antes da tela
  //    cheia porque ela é mais efêmera: é uma camada da lista, não a projeção.
  if (ferramentasAbertas()) { fecharFerramentas(); return true; }
  // 2.6. A folha da BÍBLIA, irmã da de Ferramentas — e com um degrau a mais: ela
  //    tem navegação DENTRO (livros → capítulos → leitura), e o voltar sobe por
  //    ela antes de fechar a folha. É a hierarquia que o `#backBtn` do cabeçalho
  //    carregava enquanto a Bíblia era uma aba; o botão mudou de casa, a regra
  //    não. `navigateBack` continua sendo a dona dela — reimplementá-la aqui
  //    seria uma segunda opinião sobre a mesma subida.
  if (bibliaAberta()) {
    if (bibleBackEl && !bibleBackEl.hidden) navigateBack();
    else fecharBiblia();
    return true;
  }
  // 3. Preview em tela cheia — que, sem telão conectado, É a projeção. Sair
  //    dela é exatamente o que o voltar significa aqui.
  //    E ELA É NOMEADA (v1.6.0): desde que a cifra também pede tela cheia, um
  //    `document.fullscreenElement` cru tem dois donos possíveis, e o terceiro
  //    consumidor herdaria a ambiguidade — aqui o preço de errar é derrubar a
  //    projeção no meio do culto.
  if (document.fullscreenElement === previewEl) {
    try { document.exitFullscreen(); } catch (_) {}
    return true;
  }
  // (O degrau 4 era o fader de volume aberto na coluna do mixer. Ele saiu na
  //  v1.3.8 com o fader; a numeração dos degraus abaixo é a original.)
  // 5. Seleção múltipla: o voltar cancela a seleção, não o app.
  if (selectionMode) { exitSelection(); return true; }
  // (Os degraus 6 e 7 subiram para o 2.6 na v1.5.0. O 6 era o `#backBtn` do
  //  cabeçalho, que só servia à Bíblia e hoje nasce sempre oculto; o 7 era
  //  "fora do Cronograma, volta para ele", e não há mais fora — há uma tela e
  //  duas folhas, e cada folha se fecha no degrau dela.)
  // Nada aberto: a Activity minimiza (a projeção segue viva).
  return false;
};

seekEl.addEventListener('pointerdown', () => { seeking = true; });
seekEl.addEventListener('pointerup', () => { seeking = false; });

// Telão reconectado (`display-ready`): o Display sempre abre no wallpaper e
// espera um comando — quem sabe o que estava em cena é o Controle. Reenvia a
// CENA INTEIRA, não só "mídia tocando": um versículo projetado durante a
// pregação ou uma imagem de aviso estática não têm `playing` e sumiam do telão
// para sempre depois de um blip do dongle, sem nenhum sinal no Controle (que
// seguia mostrando "● No ar").
//
// Ordem importa: a mídia primeiro, o texto depois. No Display um `load` visual
// encerra a Camada de Texto e um `load` de áudio a mantém — mandar o texto por
// último faz as duas combinações caírem no estado certo.
//
// `para` é o ENDEREÇO de quem pediu, e ele existe porque o barramento é um
// broadcast: até a v5.139 esta função era chamada sem destinatário e reenviava
// a cena para TODO MUNDO. Com um telão de verdade no ar, qualquer segunda
// instância de `/display/` que abrisse, recarregasse ou fosse restaurada pelo
// navegador fazia a TV rodar um `load` inteiro — fade de saída, releitura da
// mídia, re-seek, fade de entrada — na frente da congregação, por um evento
// que não tinha nada a ver com ela. Endereçado, o reenvio vai só para quem se
// anunciou. `undefined` (telão antigo, sem `__de`) mantém o broadcast de
// sempre: um bundle velho no telão continua reconectando igual.
function resendSceneToDisplay(para) {
  const enviar = (cmd) => AVDB.sendCommand(para ? Object.assign({ __para: para }, cmd) : cmd);
  // O GIRO VIAJA PRIMEIRO, antes do `load` (v5.142). Ele é preferência de
  // exibição, não conteúdo: o telão o lê do estado no arranque, mas entre o
  // `display-ready` e essa leitura há uma janela — e um telão que reconecta no
  // meio de um vídeo girado não pode mostrá-lo deitado nem por um quadro. Antes
  // do `load` porque `applyMedia` repõe o giro ao revelar a mídia; depois dele
  // seria um giro visível acontecendo na frente da congregação.
  if (mediaRot) enviar({ type: 'rotate', rotate: mediaRot });
  // Reenvia SEMPRE que houver mídia carregada — não só a que está tocando.
  // A condição anterior (`playing || isImage`) deixava de fora justamente o
  // caso mais comum de uma queda de dongle: o louvor de fundo PAUSADO para a
  // oração. Um vídeo pausado mostra o quadro congelado no telão e um áudio
  // pausado mantém a letra sincronizada em cena — nos dois casos há algo
  // projetado, e nos dois casos ele sumia para sempre.
  // `!isCue`: a cena de roteiro em cena é reenviada pelo bloco de TEXTO logo
  // abaixo (é uma sessão, como um versículo escolhido pela aba da Bíblia) — dar
  // `load` no id dela mandaria o telão carregar uma mídia sem bytes e apagaria
  // a projeção justamente na reconexão que este código existe para consertar.
  //
  // `midiaNoAr` (v5.142) É A PERGUNTA CERTA, e `currentId` sozinho era a errada.
  // Ele sobrevive de propósito ao stop e ao fim natural — é o que permite repetir
  // a faixa com o ▶ —, então reenviar por ele fazia o telão ACORDAR TOCANDO algo
  // que o operador tinha parado, ou ressuscitar a música que acabou. Esta função
  // restaura o que ESTAVA no ar; um telão vazio também é um estado, e restaurá-lo
  // é não mandar nada.
  if (midiaNoAr && currentId && !isCue(currentItem)) {
    // E leva a POSIÇÃO. Sem ela o telão recarregava a mídia do ZERO: um hino
    // aos 3:20 recomeçava do início na frente da congregação. Pior, o
    // `display-status` seguinte chegava com `currentTime` 0 e arrastava a
    // preview do Controle de volta junto — o operador perdia até a referência
    // de onde estava.
    // O tempo sai da própria barra de progresso (mesma fonte que
    // `pushNowPlaying` usa): é a única que cobre todos os tipos, inclusive
    // YouTube, onde `preview.getTime()` não sabe de nada.
    const t = !seekEl.disabled ? (parseFloat(seekEl.value) || 0) : 0;
    // A apresentação volta na PÁGINA em que estava, pelo mesmo motivo do
    // tempo: um telão que reconecta no meio da pregação não pode voltar ao
    // primeiro slide na frente de todo mundo.
    enviar({
      type: 'load', mediaId: currentId, view, muted, volume, time: t, playing,
      page: isDeck(currentItem) ? deckPagina : 0,
    });
  }
  // O cronômetro volta pelo DESCRITOR, não por um valor: o telão recalcula o
  // número a partir do mesmo `startAt`, então ele reaparece no segundo certo —
  // não no ponto em que a conexão caiu.
  if (drawProjecting()) {
    // O telão que reconecta no MEIO do rolo entra no mesmo quadro dos demais: o
    // quadro é função de `rollUntil` e do relógio, não de quantos ticks já
    // passaram por ali (ver drawReading).
    enviar({ type: 'text', mode: 'draw', draw: drawDescriptor(), sub: draw.label || '', view });
  } else if (chronoProjecting()) {
    enviar({ type: 'text', mode: 'chrono', chrono: chronoDescriptor(), sub: chrono.label || '', view });
  } else if (bibleSession && bibleSession.projecting) {
    const v = bibleSession.verses[bibleSession.idx];
    if (v) {
      const ref = bibleSession.bookName + ' ' + bibleSession.chapter + ':' + v.n;
      enviar({ type: 'text', mode: 'verse', main: v.text, sub: ref, view });
    }
  } else if (msgProjecting()) {
    const m = messages[msgSession.idx];
    if (m) enviar({ type: 'text', mode: 'message', main: m.text, sub: '', view });
  } else if (lyricProjecting()) {
    enviar({ type: 'text', mode: 'message', main: lyricSession.stanzas[lyricSession.idx], sub: '', view });
  } else if (visualSobreProjetando()) {
    // A IMAGEM SOBRE O ÁUDIO volta como as outras cinco, e precisa: ela é
    // justamente o caso que este reenvio existe para cobrir — um cartão de
    // aviso ESTÁTICO, sem `playing`, que sumia para sempre depois de um blip do
    // dongle enquanto o Controle seguia dizendo "● No ar". Ela vai por
    // `mediaId`, e não pelos bytes: o telão resolve pelo mesmo IndexedDB
    // compartilhado, e a tela da rede pelo `__rec` que o `telaEnriquecer` põe.
    // E A APRESENTAÇÃO VOLTA NA PÁGINA EM QUE ESTAVA, pelo mesmo motivo do
    // tempo da mídia logo acima: um telão que reconecta no meio da pregação não
    // pode voltar ao primeiro slide na frente de todo mundo. Numa imagem o
    // campo é zero e não significa nada.
    enviar({
      type: 'text', mode: 'image', mediaId: visualSession.id, sub: '', view,
      page: deckSobreProjetando() ? deckPagina : 0,
    });
  }
}

// O Display (projeção real) é a FONTE DE SINCRONIZAÇÃO enquanto envia status
// — dirige o play/pause, a barra de progresso, a letra sincronizada e o
// avanço, e re-alinha a preview a ele. Se ele não existir/estiver
// estrangulado ou fechado (nenhum status recente → displayActive() falso), a
// PREVIEW local assume (previewTick). Isso
// cobre os dois casos: Controle em primeiro plano com Display em segundo
// (preview manda) e Controle minimizado com o Display tocando (Display
// manda, e a preview se re-alinha a ele ao voltar). Vale tanto para YouTube
// quanto para mídia comum (áudio/vídeo do stage.js) — dois decodificadores
// independentes (Display e preview) divergem aos poucos sem essa correção
// periódica, e a letra sincronizada acaba trocando de slide em momentos
// diferentes nos dois lados.
AVDB.onCommand((msg) => {
  if (!msg) return;
  // Reenvia SÓ para quem se anunciou (ver `resendSceneToDisplay`). Um telão
  // com bundle antigo não manda `__de`, e aí o reenvio volta a ser broadcast —
  // exatamente o comportamento de antes desta versão.
  if (msg.type === 'display-ready') {
    // Uma TELA DA REDE (`__tela`) não tem o IndexedDB do celular: além da
    // cena, ela precisa receber wallpaper, fundo da letra e preenchimento —
    // o telão de verdade lê tudo isso do IDB sozinho e não entra aqui.
    // ELE É O SINAL DE QUE A PROJEÇÃO RENASCEU: dongle que reconectou, OTA que
    // recarregou a página, renderer que morreu e foi remontado. Num telão
    // estável não sai nenhuma depois da abertura — a presença destas linhas já
    // é o achado.
    diagC('a projeção se reapresentou (' + (msg.__tela ? 'tela da rede' : 'telão') + ')');
    if (msg.__tela) telaReenviarPreferencias(msg.__de);
    resendSceneToDisplay(msg.__de);
    return;
  }
  if (msg.type === 'diag-dump') {
    juntarDiag(Array.isArray(msg.linhas) ? msg.linhas : [], msg.retomada);
    return;
  }
  // Áudio bloqueado no Display (política de autoplay): avisa o OPERADOR —
  // nada é exibido no telão; a recuperação automática roda no Display e o
  // botão de mudo do mixer vira indicador/atalho para liberar.
  if (msg.type === 'display-status' && typeof msg.audioBlocked === 'boolean'
      && msg.audioBlocked !== displayAudioBlocked) {
    displayAudioBlocked = msg.audioBlocked;
    // QUEM AVISA É O BOTÃO DE MUDO, e ele já avisava: `renderControls` o veste
    // com `.blocked` (fundo `--warn-soft`, ícone em `--warn`, pulsando), e o
    // toque nele é o atalho para liberar. A chamada que morava aqui era um
    // `flash()` — no-op desde que o primeiro toast saiu, isto é, uma frase que
    // ninguém via havia versões. O canal certo já estava de pé.
    renderControls();
  }
  // Microfone: camada de áudio independente da mídia — precisa ser tratado
  // ANTES do filtro por `mediaId` abaixo, que descarta tudo que não é sobre o
  // item em exibição.
  if (msg.type === 'mic-status') {
    micOn = !!msg.on;
    // O ERRO DO AO VIVO TAMBÉM ENTRA NO REGISTRO, e a razão é que ele nasce no
    // TELÃO: o `diag('microfone recusado: …')` de lá mora no diário da
    // `Presentation`, que só chega ao Registro se o `diag-ask` conseguir
    // respondê-lo — e um dongle que caiu no meio leva o diário junto. A linha
    // que o operador precisa é a do CELULAR, que sobrevive.
    //
    // Só na TRANSIÇÃO: o telão reemite `mic-status` e repetir a mesma recusa
    // encheria a linha do tempo com o mesmo fato.
    const erroNovo = msg.error || '';
    if (erroNovo && erroNovo !== micError) {
      // OS DEGRAUS VÊM DO TELÃO quando ele os manda. Sem eles o Registro do
      // celular via UMA tentativa e concluía "falhou antes de esgotar a escada"
      // — enquanto o telão tinha rodado a escada inteira. O consumidor não
      // tinha como saber, e um veredito errado é pior que veredito nenhum.
      const dg = Array.isArray(msg.degraus) && msg.degraus.length
        ? msg.degraus
        : [{ qual: 'telão', erro: erroNovo }];
      micRegistrar('ao vivo', dg, null, false);
    }
    micError = erroNovo;
    if (ferramentasAbertas()) renderMicUI();
    return;
  }
  if (!currentItem || msg.mediaId !== currentId) return;
  const isYoutube = currentItem.kind === 'youtube';
  const isTimedLocal = currentItem.kind === 'audio' || currentItem.kind === 'video';
  if (!isYoutube && !isTimedLocal) return; // imagem/etc: sem noção de tempo, nada a sincronizar
  // A ELEIÇÃO DAS TELAS DE COMANDO (telão por comandos, E5). N telas emitem
  // `tela-status` e o handler abaixo supõe UMA fonte por tipo — a mesma
  // alternância de fontes que o dreno do papel espelho existia para impedir.
  // A eleita é a primeira vista; troca quando ela cala por
  // TELA_REF_SILENCIO_MS. O status da eleita entra no ramo do espelho-status
  // (mesma precedência do telão, mesmo realinhamento da preview); as outras
  // telas só existem para a folha e o Registro.
  if (msg.type === 'tela-status') {
    const idTela = String(msg.__tela || '?');
    const agoraTela = Date.now();
    if (!telaRefId || agoraTela - telaRefEm > TELA_REF_SILENCIO_MS) telaRefId = idTela;
    if (idTela !== telaRefId) return;
    telaRefEm = agoraTela;
    msg = Object.assign({}, msg, { type: 'espelho-status' });
  }
  if (msg.type === 'display-status' || msg.type === 'espelho-status') {
    // Player morto/parado (fim natural ou stop manual): ignora qualquer
    // display-status ainda em trânsito reportando o player antigo tocando —
    // senão o ícone voltaria a "pause" e o ▶ (que deve recarregar) quebraria.
    if (isYoutube && ytEnded) return;
    // E A MÍDIA LOCAL TEM A MESMA REGRA (v5.179) — era ela o "o Parar só
    // funciona no SEGUNDO toque".
    //
    // A guarda acima cobria só o YouTube. Um `clear`/`media-clear` de mídia
    // comum ESMAECE antes de sair de cena (`clearFaded`/`fadeOutToBlack`,
    // ~0,6 s), e nesse intervalo o `<video>` do telão CONTINUA tocando: a rampa
    // é de volume, não de pausa. Cada `display-status` do fade chegava aqui com
    // `playing: true` e o tempo antigo e reescrevia, a ~4 Hz, exatamente a UI que
    // `pararMidia` acabara de zerar — a barra voltava ao meio, o seek era
    // reabilitado e o ▶ não aparecia. O segundo toque só "funcionava" porque a
    // essa altura a mídia já saíra e ninguém mais reportava aquele `mediaId`.
    //
    // `midiaNoAr` é a pergunta certa, e já existe desde a v5.142: ele cai no
    // INSTANTE do stop, enquanto `currentId` sobrevive de propósito (é o que
    // permite ao ▶ repetir a faixa) — e é por isso que o filtro por `mediaId`
    // logo acima deixava tudo isto passar. Um status sobre uma mídia que não
    // está mais em cena é passado, e passado não pinta transporte.
    if (!midiaNoAr) return;
    // O TELÃO TEM PRECEDÊNCIA — ver "A REFERÊNCIA". Com os dois no ar, o que a
    // congregação vê é a TV, e o espelho vira ruído a ~4 Hz numa barra que
    // andaria para a frente e para trás.
    const doTelao = msg.type === 'display-status';
    if (!doTelao && telaoAtivo()) return;
    if (doTelao) telaoStatusAt = Date.now();
    refFonte = doTelao ? 'telao' : 'espelho';
    displayStatusAt = Date.now();
    lastDisplayTime = msg.currentTime || 0;
    // AO RETOMAR DO SEGUNDO PLANO o primeiro status vale como reposicionamento
    // exato: ali não há ruído a poupar, há um desvio conhecido e grande.
    // E ele só é CONSUMIDO se houver como agir: com a página escondida o
    // realinhamento não acontece (ver `preverPodeMexer`), e gastar a janela ali
    // deixaria a preview desalinhada justamente na retomada seguinte.
    const tol = (Date.now() < forcarResyncAte && preverPodeMexer()) ? RESYNC_EXATO : undefined;
    if (tol !== undefined) forcarResyncAte = 0;
    setPlaying(!!msg.playing);
    const dur = (typeof msg.duration === 'number' && isFinite(msg.duration)) ? msg.duration : 0;
    seekEl.disabled = !(dur > 0);
    durTimeEl.textContent = fmtTime(dur);
    if (!seeking) {
      seekEl.max = dur > 0 ? dur : 0;
      seekEl.value = msg.currentTime || 0;
      curTimeEl.textContent = fmtTime(msg.currentTime);
    }
    if (isYoutube) {
      renderSimpleTime();   // idem: o ramo do YouTube não chama renderSlideNav
    } else {
      // A LETRA DESENHADA DENTRO DA PREVIEW segue o tempo DA PREVIEW, não o da
      // projeção: com o atraso em jogo (ver `cmd`), alimentá-la com
      // `lastDisplayTime` trocaria a estrofe ~1 s antes da imagem a que ela
      // pertence — dentro do mesmo retângulo. Quem usa o tempo da PROJEÇÃO é a
      // barra e a navegação de estrofe, logo abaixo.
      updatePvLyricSlide(tempoDaPreview());
      renderSlideNav();
      resyncPreviewToDisplay(playing, msg.currentTime, tol);
    }
  } else if (msg.type === 'media-ended') {
    // A GUARDA DE mediaId que o comentário da preview (`onEnded`) sempre
    // prometeu: o Display manda o id do que TERMINOU (stage e YouTube — ver
    // display.js), e um `media-ended` atrasado do item anterior, chegando
    // depois de um load novo, dispararia `autoAdvance` por cima do item que o
    // operador acabou de escolher — pulando uma faixa. Sem id dos dois lados
    // não há o que comparar e vale o comportamento de sempre.
    if (msg.mediaId && currentId && msg.mediaId !== currentId) return;
    displayStatusAt = Date.now();
    if (isYoutube) ytEnded = true;
    setPlaying(false);
    // Mesmo tratamento do onEnded local (o Display pode chegar ao fim primeiro):
    // a letra esmaece e trava, para o slide de capa não piscar no replay.
    pvLyricsEnded = true;
    if (pvLyrics) pvLayerOut(pvLyricsEl);
    autoAdvance();
  }
});

// O service worker SAIU (v5.48). Este bloco registrava `sw.js` e recarregava a
// página quando um SW novo assumisse — mas `sw.js` não existe no bundle desde
// que os andaimes de PWA foram removidos: o `register` devolvia 404 em toda
// abertura no navegador, `swReg` ficava eternamente null e o ramo de "checar
// atualização ao retomar" nunca executava. Era código morto que ainda por cima
// sujava o console justamente no ambiente onde a base é desenvolvida.
// No app nativo ele já era desligado de propósito (os assets vêm do APK e a
// atualização é o OTA do `WebUpdater`), então nada se perde nos dois contextos.

// Um ÚNICO handler ao retomar do 2º plano: atualiza os índices leves das
// coleções (índices dos hinários + catálogo de álbuns — só metadados, sem
// áudio — barato pra rodar a cada retomada, mantém a busca e os cards em
// dia). (A metade que "buscava a versão nova do service worker" saiu junto
// com o SW, v5.48 — ver o bloco acima.)
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState !== 'visible') {
    // App em segundo plano: o botão de falar não está mais sob o dedo, então
    // o microfone não pode continuar aberto. Push-to-talk que sobrevive ao
    // app sair da frente vira um microfone esquecido ligado.
    if (micPressed || micOn) sendMic(false);
    // E O HISTÓRICO PENDENTE VAI AO DISCO (v1.4.31). Sair da frente é o
    // instante em que o processo passa a ser descartável — congelamento,
    // pressão de memória, morte do renderer —, e a gravação coalescida
    // (`HIST_GRAVA_MS`) pode ter até dois segundos de culto na memória.
    // Barato: sem nada agendado, o `if` devolve na primeira linha.
    if (histGravaTimer) histGravar();
    return;
  }
  autoRefreshCollections();
  // O LINK COPIADO ENQUANTO O APP ESTAVA FORA DA FRENTE — que é o caso normal:
  // o operador sai daqui, copia no YouTube e volta. Sem carimbo novo isto não
  // chega a ler nada (ver `conferirLinkCopiado`).
  conferirLinkCopiado();
  // A tela pode ter caído (ou voltado) com o app minimizado — e é exatamente aí
  // que este WebView está estrangulado e pode perder o aviso do shell. Reler a
  // lista ao voltar para a frente é o piso que impede o ícone de cast de ficar
  // aceso sobre uma TV que não está mais lá (v5.142).
  reconferirTelas();
  // A PREVIEW VOLTA DO ESCURO, e ela volta ERRADA — é o defeito que a v5.173
  // existe para fechar. Enquanto o app esteve fora da frente o `<video>` dela
  // foi pausado ou desacelerado pelo Chromium, enquanto a projeção (o telão ou
  // o `/display/` do espelho, que rodam numa `Presentation` e não são
  // estrangulados) seguiu andando. A distância entre os dois é arbitrária e não
  // se corrige sozinha: nada no ciclo normal compara os dois relógios com força
  // suficiente.
  //
  // São dois passos, e nenhum basta sozinho: a fila escoa (os comandos que
  // ficaram presos num timer estrangulado valem AGORA), e o realinhamento
  // acontece contra a última posição conhecida da projeção. Se ela já estiver
  // velha, `forcarResyncAte` faz o próximo status valer como reposicionamento
  // exato — que é o caminho normal numa cena parada, onde o status é o único
  // sinal que ainda chega.
  drenarPreview(true);
  forcarResyncAte = Date.now() + RESYNC_JANELA_MS;
  ressincronizarPreview();
});

(async function init() {
  // A PRIMEIRA LINHA DO ANEL é a abertura, e ela ancora todas as outras: sem
  // ela não há como saber se o que se está lendo é um culto inteiro ou os dois
  // minutos depois de uma remontagem do WebView. As versões vão junto porque a
  // pergunta seguinte a "o que aconteceu?" é sempre "em qual versão?".
  diagC('app aberto · web v' + WEB_VERSION
    + (window.__SHELL_NAME__ ? ' · shell v' + window.__SHELL_NAME__ : ''));
  await loadCollections();
  await desnumerarAlbunsBaixados();
  await preencherAlbunsDosHinos();
  // OS ATALHOS DE PASTA, migrados para os favoritos (v5.254). ANTES do `load()`
  // porque a lista que o operador vê já tem de ser a migrada — e antes do
  // `varrerRestos()` lá embaixo, que é quem apagaria o que ficasse sem dono.
  // Uma vez por aparelho: sem `folders` no banco ela devolve na primeira linha.
  await migrarPastasParaFavoritos();
  // O HISTÓRICO DAS SESSÕES ANTERIORES (v1.4.31). ANTES de qualquer projeção,
  // e por isso antes do `load()`: `historicoRegistrar` faz `unshift` da sessão
  // nova na lista em memória, e uma leitura que chegasse depois a sobrescreveria
  // com o que estava no disco — apagando, em silêncio, o que acabou de tocar.
  await histCarregar();
  // ANTES do load(): é ele que lê `current` e monta a tela a partir dela.
  await clearCurrentSelection();
  await load();
  // A SEGUNDA METADE do modo lembrado. A classe do `<body>` já foi escrita no
  // topo do arquivo (antes do primeiro quadro); falta o que depende do módulo
  // pronto: o segmento das Configurações, os renders do simplificado e — no
  // avançado — o vazado da faixa de abas, que só pode ser POSICIONADO agora,
  // porque medir a faixa antes de `load()` a desenhar daria zero.
  setAppMode(appMode);
  // Wallpaper escolhido pelo operador (a preview espelha o telão).
  await applyPvWallpaper();
  // registra a chegada de compartilhamentos (intent nativo; no navegador é no-op)
  registrarShareNativo();
  // E O LINK QUE JÁ ESTAVA COPIADO. Fire-and-forget, como os três abaixo: a
  // pergunta pode esperar o app terminar de abrir, e segurar a abertura por uma
  // ida à ponte seria pagar por um caso que quase sempre não existe.
  conferirLinkCopiado();
  // A TRANSMISSÃO PODE JÁ ESTAR NO AR — o documento é que é novo.
  //
  // `EspelhoServidor` vive no SHELL: aplicar o OTA (`applyWebUpdate`) ou perder
  // o renderer recarrega esta página com as telas da rede ainda pareadas pelo
  // SSE. `mirrorEstado` nasce `null` e NINGUÉM o relê sozinho: as duas enquetes
  // só ligam quando o estado JÁ é conhecido (`acertarEnqueteDeFundo` exige
  // `espelhoLigado()`; a da folha exige o bloco de conexão à vista), e os demais
  // `lerEspelho()` pendem de um gesto do operador.
  //
  // Com o cache nulo `telaAtiva()` MENTE, e o modo de falhar é mudo: todo `load`
  // sai sem `__rec`, a tela não acha o id no IndexedDB dela e a projeção volta
  // ao wallpaper — o culto inteiro, sem erro em lugar nenhum. Pelo mesmo cache,
  // `somLocalDeveEstar()` desmuta a preview por cima das telas.
  //
  // Fire-and-forget, e ela se sustenta sozinha: `lerEspelho` termina em
  // `acertarEnqueteDeFundo()`, que liga o relógio de 4 s assim que descobre a
  // transmissão. Sem transmissão custa uma chamada de ponte com um JSON pequeno
  // e nada muda — os consumidores já leem `{ligado:false}` e `null` igual.
  lerEspelho();
  // Índices das coleções em segundo plano (fire-and-forget): não atrasa a
  // abertura do app, só deixa a busca/os cards prontos assim que a resposta chegar.
  autoRefreshCollections();
  // A BÍBLIA BASE, garantida sozinha (v5.242) — metadados e, atrás deles, a
  // versão padrão INTEIRA, em segundo plano e resumível. Fire-and-forget pelo
  // mesmo motivo do `autoRefreshCollections` logo acima: não atrasa a abertura
  // do app. Ver `garantirBibliaBase`.
  garantirBibliaBase();
  // A FAXINA DOS RESTOS, por último e sem segurar nada (v5.131). Ver
  // `AVDB.gcOrfaos`: registros que nenhuma lista aponta e que nenhum caminho
  // normal alcançava — o `listSet` os criava a cada troca de playlist. Aqui é
  // o único momento seguro por construção: `load()` já leu tudo o que a tela
  // mostra, e o que a varredura apaga é, por definição, o que ninguém aponta.
  varrerRestos();
  // O DOWNLOAD QUE FICOU SEM DONO, reclamado. Depois do `load()` porque ele
  // acrescenta itens às listas, e antes de qualquer coisa demorada: se o shell
  // ainda tiver o arquivo guardado, o item aparece em segundos.
  resgatarDownloads();
  // A ATUALIZAÇÃO QUE FICOU PELA METADE, retomada — e ela vem ANTES da
  // procura, de propósito: se o operador já disse sim a um lote com APK e a
  // recarga do OTA aconteceu, o que falta é instalar, não perguntar de novo.
  // Ver `retomarAtualizacao`.
  retomarAtualizacao();
  // A PROCURA. A primeira consulta é adiada porque o download do bundle começa
  // junto com a abertura (`checkAsync` no `onCreate`) e leva alguns segundos —
  // perguntar agora seria perguntar antes de haver resposta. Ela é a rede de
  // segurança: o caminho normal é o empurrão do shell (`__avAtualizacao`), que
  // chega no segundo em que a resposta existe.
  setTimeout(ofertarAtualizacao, 6000);
  setInterval(() => { ofertarAtualizacao(); retomarAtualizacao(); }, OTA_POLL_MS);
  // E A RETOMADA DO APP É UM GATILHO deste lado também. O shell já procura ao
  // voltar do segundo plano, mas quem PERGUNTA é esta página — e é exatamente
  // ao retomar que o operador encontra um lote que chegou enquanto este WebView
  // estava estrangulado.
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState !== 'visible') return;
    ofertarAtualizacao();
    retomarAtualizacao();
  });
})();

// ---------------------------------------------------------------------------
// A ATUALIZAÇÃO PERGUNTA, E ELA É UM EVENTO SÓ (shell 43)
//
// 1. UM LOTE, UMA PERGUNTA. O manifesto do canal OTA carrega o bloco `shell` —
//    o `apk.yml` SEGURA o bundle até a Release existir, então base e link do
//    APK chegam juntos. O "Atualizar agora" leva os dois, um depois do outro.
// 2. A PERGUNTA ESPERA SÓ O QUE ACABA: cena projetando e download em curso.
//    O espelho NÃO segura — ele fica ligado o culto inteiro, e incluí-lo
//    tornava a supressão permanente (foi o que fez a v5.151 desistir de
//    perguntar). Instalar o APK, esse sim, espera os três.
// 3. "DEIXAR PARA DEPOIS" vale por esta sessão. Volta a oferecer na abertura
//    seguinte, e o botão do rodapé de Configurações aplica na hora.
// 4. A INTENÇÃO SOBREVIVE À RECARGA. Aplicar o OTA mata este documento e toda
//    variável que soubesse que falta instalar o APK — ela é gravada no `state`
//    do banco ANTES de aplicar (o lugar e o motivo da intenção de download do
//    YouTube) e relida na abertura.
// ---------------------------------------------------------------------------

// A enquete do lado web — a REDE DE SEGURANÇA, não o caminho principal.
//
// Quem põe a pergunta na tela no segundo em que ela existe é o empurrão do
// shell (`window.__avAtualizacao`). Isto aqui cobre o caso em que o empurrão se
// perde: o WebView do Controle é estrangulado em segundo plano, e é justamente
// aí que uma versão nova costuma chegar. Ela não custa rede — lê o disco, e o
// `otaCheck` que dispara respeita o piso do shell.
const OTA_POLL_MS = 10000;

// O que o SHELL recusou aplicar (um bundle sem o index do Controle, por
// exemplo). Sem esta guarda a enquete pediria a aplicação a cada dez segundos,
// para sempre — e o operador veria a pergunta reaparecer sozinha depois de ter
// dito sim.
const otaRecusadas = new Set();
// A LINHA DO TEMPO do que a atualização traz: `[{versao, itens:[…]}]`, mais
// nova primeiro, já filtrada pelo shell para o que este aparelho ainda não tem.
let otaNotas = [];
let otaPerguntando = false;
// (`otaDiagTexto`, `otaPendenteVersao`, `apkNovo` e `apkBaixando` nascem no
// TOPO do arquivo, junto do `WEB_VERSION` — `renderVersionLabel()` os lê na
// carga do módulo, e declará-los aqui seria zona morta temporal. Ver o
// comentário de lá.)

// A chave da INTENÇÃO no banco. Ela existe por um motivo estrutural: aplicar o
// OTA substitui o documento, então nada em memória atravessa esse ponto — e é
// exatamente depois dele que falta a metade nativa do lote.
const OTA_INTENCAO = 'ota-intencao';
// Intenção mais velha que isto é descartada. Um APK de ontem que ninguém
// instalou não é uma tarefa pendente: é lixo, e retomá-lo sozinho na manhã de
// domingo seria abrir o instalador do sistema por cima de quem está montando o
// culto. (Mesmo raciocínio do teto de 6 h da intenção de download.)
const OTA_INTENCAO_MAX_MS = 6 * 60 * 60 * 1000;

// Há algo projetado agora? MESMA leitura de `pushNowPlaying` — se ela mudar de
// ideia sobre o que é "cena", esta pergunta muda junto.
function cenaNoAr() {
  return !!currentId
    || !!(msgSession && msgSession.projecting)
    || !!(bibleSession && bibleSession.projecting)
    || lyricProjecting()
    || chronoProjecting()
    || drawProjecting();
}

// Momento ruim para PERGUNTAR — e ele é diferente do momento ruim para
// INSTALAR, que é o `horaRuimParaAtualizar()` logo abaixo.
//
// Aqui vale o que ACABA sozinho: uma cena sai do ar quando o louvor termina, um
// download termina. O espelho não entra, e essa é a correção do lote: ele fica
// ligado o culto inteiro, então incluí-lo (v5.141 → v5.151) transformava a
// pergunta em algo que nunca aparecia — e foi por isso que a v5.151 desistiu de
// perguntar. O espelho custa uma tela da rede com a página antiga em memória
// até alguém recarregá-la; a cena e o download custam a projeção e o hinário
// pela metade, que é outra ordem de grandeza.
function horaRuimParaPerguntar() {
  return cenaNoAr() || bgWorkPedido();
}

// Momento ruim para INSTALAR O APK: aqui o espelho volta a contar, porque
// instalar derruba o app inteiro — o servidor da rede vai junto, e as telas
// ficam sem nada. É o mesmo peso do `#otaRow` desde a v5.167 (`apkRow` até a
// v5.242), e é o que o
// Registro mostra.
function horaRuimParaAtualizar() {
  return cenaNoAr() || bgWorkPedido() || espelhoLigado();
}

// O que está esperando, numa forma só. `null` quando não há nada.
function loteDaAtualizacao() {
  if (!otaPendenteVersao && !apkNovo) return null;
  return {
    web: otaPendenteVersao || '',
    shell: apkNovo ? apkNovo.versao : '',
    bytes: apkNovo ? (apkNovo.bytes | 0) : 0,
    chave: (otaPendenteVersao || '-') + '|' + (apkNovo ? apkNovo.versao : '-'),
  };
}

// ===== A LEITURA DO ESTADO =====
//
// UMA chamada, e é dela que vem a COERÊNCIA DE INSTANTE: os dois canais (base
// web e APK) chegam na mesma fotografia, e não em três respostas que podem
// discordar entre si. Ela não pode lançar — quem chama é uma enquete que roda
// de dez em dez segundos, e um `throw` a mataria em silêncio.
async function lerAtualizacao() {
  if (!window.__NATIVE__) return;
  let e = null;
  try { e = await AVNative.atualizacaoEstado(); } catch (_) { return; }
  ingerirAtualizacao(e);
}

// ===== A INGESTÃO, NUM PONTO SÓ =====
//
// Os dois caminhos (a enquete e o empurrão) leem a MESMA fotografia, e por três
// versões cada um a desempacotou por conta própria — duas listas de campos, que
// divergem no primeiro esquecimento. E a divergência aqui é MUDA nos dois
// sentidos: um campo lido só na enquete chega dez segundos atrasado; um campo
// lido só no empurrão nunca chega em quem abriu o app com a atualização pronta.
function ingerirAtualizacao(e) {
  if (!e) return false;
  otaPendenteVersao = e.web || '';
  otaDiagTexto = e.diag || '';
  apkNovo = e.shell ? { versao: e.shell, bytes: e.shellBytes | 0 } : null;
  // A LINHA DO TEMPO do que vem (shell 47). Vazia é o normal: bundle anterior a
  // este lote, lote só de APK, ou `notas.json` que o shell não conseguiu ler.
  // Em todos, a pergunta continua a mesma — só não se descreve.
  otaNotas = Array.isArray(e.webNotas) ? e.webNotas : [];
  return true;
}

// ===== O EMPURRÃO DO SHELL =====
//
// Ele é o caminho PRINCIPAL: a pergunta aparece no segundo em que a resposta
// existe, sem esperar enquete nenhuma. O objeto chega pronto, então aqui não há
// ida à ponte — o que importa é que o desenho aconteça no mesmo quadro em que
// o dado chegou.
window.__avAtualizacao = function (e) {
  if (!ingerirAtualizacao(e)) return;
  decidirAtualizacao();
};


// A enquete: relê e decide. Separada do `decidirAtualizacao` porque o empurrão
// já vem com o estado na mão e reler seria uma ida à ponte por nada.
async function ofertarAtualizacao() {
  if (!window.__NATIVE__) return;
  // CUTUCAR O SHELL, e não só perguntar o que ele já tem: sem `forcar`, porque
  // o piso dele é que decide se vale uma requisição — senão uma enquete de dez
  // segundos viraria seis consultas à rede por minuto, para sempre.
  try { AVNative.otaCheck(false); } catch (_) { /* rede/ponte */ }
  await lerAtualizacao();
  decidirAtualizacao();
}

// ===== A DECISÃO =====
function decidirAtualizacao() {
  renderVersionLabel();
  renderOtaRow();
  const lote = loteDaAtualizacao();
  if (!lote) return;
  if (otaPerguntando || apkBaixando) return;
  if (otaAdiadas.has(lote.chave)) return;
  if (lote.web && otaRecusadas.has(lote.web)) return;
  // A pergunta espera o que acaba (ver `horaRuimParaPerguntar`). Ela não se
  // perde: a enquete de dez segundos volta, e o rótulo de versão já está
  // dizendo que há algo esperando.
  if (horaRuimParaPerguntar()) return;
  perguntarAtualizacao(lote);
}

function mb(bytes) {
  return bytes ? Math.round(bytes / 104857.6) / 10 + ' MB' : '';
}

// ===== DUAS FRASES, e a linha do tempo entre elas =====
//
// Eram uma só, com a consequência colada na identidade por duas quebras de
// linha. Com a lista no meio essa junção deixou de servir: um parágrafo sobre
// telas recarregando separaria a versão das mudanças DELA.
//
// `textoDaAtualizacao` responde O QUE É (e é o único que muda de forma com o
// lote); `consequenciaDaAtualizacao` responde O QUE ACONTECE AO TOCAR — que é a
// pergunta que a lista nunca responde, e a razão de este diálogo existir em vez
// de a atualização entrar sozinha.
function textoDaAtualizacao(lote) {
  const tamanho = lote.bytes ? ' (' + mb(lote.bytes) + ')' : '';
  if (lote.web && lote.shell) return 'Base v' + lote.web + ' e app v' + lote.shell + tamanho + '.';
  if (lote.shell) return 'App v' + lote.shell + tamanho + '.';
  return 'Base v' + lote.web + '.';
}

function consequenciaDaAtualizacao(lote, sobram) {
  // O QUE NÃO COUBE VEM PRIMEIRO, e vem aqui porque este bloco não rola: a
  // lista acima pode ter sido cortada pelo teto, e quem a lê precisa saber
  // disso sem depender de rolar até o fim dela.
  const resto = sobram
    ? 'E mais ' + sobram + (sobram === 1 ? ' mudança.' : ' mudanças.') + '\n'
    : '';
  return resto + consequenciaCrua(lote);
}

// TODAS COMEÇAM COM "AO ATUALIZAR", e isto é o recado inteiro deste bloco:
// logo acima está a LISTA de mudanças, e sem o marco de tempo "a projeção pisca
// por um instante" se lia como mais um item dela — uma mudança que a versão nova
// traria. Ela não é: é o que acontece no TOQUE, e nomear o momento é o que
// separa as duas leituras.
function consequenciaCrua(lote) {
  if (lote.web && lote.shell) {
    return 'Ao atualizar, a base entra primeiro e a projeção pisca por um '
      + 'instante. Em seguida o Android vai pedir para confirmar a instalação '
      + 'do app.';
  }
  if (lote.shell) {
    return 'Ao atualizar, o app é baixado e o Android vai pedir para confirmar '
      + 'a instalação — o app fecha durante ela.';
  }
  return 'Ao atualizar, as duas telas recarregam e a projeção pisca por um '
    + 'instante. Uma mídia tocando volta no ponto em que estava.';
}

// ===== A LINHA DO TEMPO, achatada para a lista do diálogo =====
//
// O shell entrega `[{versao, itens}]` porque quem passou três versões sem abrir
// o app tem três blocos a ver; a tela mostra UMA lista. O prefixo de versão só
// aparece quando há mais de um bloco — com um só ele repetiria, em cada linha, o
// número que o texto acima do diálogo acabou de dizer.
//
// TETO DE LINHAS, e ele é a decisão que faz isto continuar sendo uma linha do
// tempo: um diálogo que rola é um texto, e "não se torne um texto" é o pedido.
//
// **O AVISO DO QUE SOBROU NÃO PODE MORAR NA LISTA.** Ele morou, e o desenho o
// desmentiu na primeira medição: a lista tem teto de altura com rolagem (a rede
// para uma fonte de sistema grande, sem a qual os botões saem da tela), e o
// último item é justamente o primeiro a ser cortado — o "e mais 5 mudanças"
// ficava escondido atrás da rolagem, e o que sobrava era uma lista truncada
// afirmando ser tudo. Ele sai daqui e vai para o RODAPÉ, que não rola.
//
// Seis e não oito pela mesma medição: no cartão de 360px cada item ocupa duas
// ou três linhas, e oito deles já batiam no teto de altura num aparelho comum.
// O teto do CSS passa a ser o que ele diz ser — uma rede que quase nunca toca.
const OTA_MAX_LINHAS = 6;
function linhaDoTempoDaAtualizacao() {
  if (!Array.isArray(otaNotas) || !otaNotas.length) return { linhas: [], sobram: 0 };
  const varias = otaNotas.length > 1;
  const linhas = [];
  for (const bloco of otaNotas) {
    const itens = bloco && Array.isArray(bloco.itens) ? bloco.itens : [];
    for (const t of itens) {
      if (!t || !String(t).trim()) continue;
      linhas.push(varias && bloco.versao ? 'v' + bloco.versao + ' · ' + t : String(t));
    }
  }
  const sobram = Math.max(0, linhas.length - OTA_MAX_LINHAS);
  return { linhas: linhas.slice(0, OTA_MAX_LINHAS), sobram };
}

async function perguntarAtualizacao(lote) {
  const tempo = linhaDoTempoDaAtualizacao();
  otaPerguntando = true;
  let sim = false;
  try {
    sim = await openAppDialog({
      title: 'Atualização disponível',
      message: textoDaAtualizacao(lote),
      itens: tempo.linhas,
      rodape: consequenciaDaAtualizacao(lote, tempo.sobram),
      okText: 'Atualizar agora',
      cancelText: 'Deixar para depois',
      input: false,
      // Um toque fora NÃO responde por ele (v5.249, ver `appDialogFixo`): esta
      // pergunta aparece sozinha, e a recusa acidental custava a atualização
      // pelo resto da sessão.
      fixo: true,
    });
  } finally {
    otaPerguntando = false;
  }
  if (!sim) {
    // ADIAR É POR LOTE E POR SESSÃO. Na próxima abertura a pergunta volta, e
    // tocar no rótulo de versão a traz de volta agora — "depois" é o operador
    // escolhendo o momento, não desistindo da atualização.
    otaAdiadas.add(lote.chave);
    // NENHUMA FRASE AQUI (v5.249). Ela existia porque o rótulo de versão só
    // sabia mostrar um ponto, e alguém precisava dizer onde tocar. Agora o
    // botão de Configurações já diz "Atualizar: base v… e app v…" — que é a
    // mesma informação e o próprio alvo. Uma frase por cima dele durante
    // quatro segundos ESCONDERIA a resposta em vez de dá-la.
    renderOtaRow();
    return;
  }
  await aplicarAtualizacao(lote);
}

// ===== A APLICAÇÃO, nesta ordem e por esta razão =====
//
// A base web PRIMEIRO. Ela é rápida (o bundle já está no disco — o que se paga
// é uma recarga) e é a metade que não depende de ninguém confirmar nada. O APK
// exige um diálogo do sistema que o operador pode recusar, adiar ou perder; se
// ele viesse antes, uma recusa ali deixaria o lote inteiro por aplicar.
//
// Entre os dois há uma morte de documento, e é por isso que a intenção é
// GRAVADA antes: o que retoma a segunda metade é a abertura seguinte, lendo o
// banco (ver `retomarAtualizacao`).
async function aplicarAtualizacao(lote) {
  if (lote.shell) {
    try {
      // `updateState` E NÃO `setState`, e a diferença aqui é o recurso inteiro:
      // `setState` resolve na aceitação do REQUEST, com a transação ainda em
      // voo, e a linha seguinte deste caminho é um `otaApply()` que RECARREGA
      // as duas páginas. Conexão derrubada aborta transação em voo — a intenção
      // some, a abertura seguinte não acha nada, e a metade nativa do lote
      // desaparece sem deixar rastro, com tudo PARECENDO ter funcionado (que é
      // o desfecho que o parágrafo acima existe para impedir). `updateState`
      // espera o commit.
      await AVDB.updateState(OTA_INTENCAO, () => ({ shell: lote.shell, em: Date.now() }));
    } catch (_) {
      // Sem intenção gravada, o APK não é retomado depois da recarga — então é
      // melhor não recarregar: instala-se o APK agora e a base web entra na
      // enquete seguinte, que continua funcionando.
      await instalarApk(lote.shell);
      return;
    }
  }
  if (!lote.web) {
    await instalarApk(lote.shell);
    return;
  }
  falarNoOta('Atualizando para a versão ' + lote.web + '…', 0);
  let aplicada = null;
  try {
    // Daqui normalmente não se volta: o documento é substituído pela recarga.
    // Só quando NÃO houver o que aplicar a promise devolve null e a página
    // segue viva — e aí o APK ainda precisa acontecer, senão o operador teria
    // dito sim para nada.
    aplicada = await AVNative.otaApply();
  } catch (_) { /* a recarga levou a página */ }
  if (!aplicada) {
    otaRecusadas.add(lote.web);
    if (lote.shell) await instalarApk(lote.shell);
    else falarNoOta('Não deu para aplicar a versão ' + lote.web, 4000);
  }
}

// ===== O APK: baixar e entregar ao instalador =====
//
// O progresso mora no MESMO diálogo, e não numa faixa nova: são dezenas de MB
// numa rede de igreja, isto é, minutos — e uma tela parada sem número é
// indistinguível de travamento. "Ocultar" fecha a janela e NÃO cancela nada; a
// frase diz isso, porque um botão que parece cancelar e não cancela é pior que
// não ter botão.
async function instalarApk(versao) {
  if (!versao || apkBaixando) return;
  if (!window.__NATIVE__) return;
  apkBaixando = true;
  renderOtaRow();
  openAppDialog({
    title: 'Baixando o app v' + versao,
    message: 'Baixando… 0%\n\nOcultar não cancela o download: o instalador do '
      + 'Android abre sozinho quando ele terminar.',
    okText: 'Ocultar',
    cancelText: null,
    input: false,
  });
  let erro = '';
  try { erro = await AVNative.apkInstalar(); } catch (_) { erro = 'falha ao baixar'; }
  apkBaixando = false;
  // A intenção morreu de qualquer jeito: ou o instalador está na frente do
  // operador (e o que acontece dali em diante é dele), ou falhou e insistir
  // sozinho a cada abertura seria um instalador aparecendo do nada. A procura
  // continua, e a pergunta volta pelo caminho normal.
  // Pelo commit, como a gravação (ver `aplicarAtualizacao`): o diálogo de
  // instalação do Android pode derrubar o app no instante seguinte, e uma
  // limpeza que não commitou deixa a intenção viva — o instalador reabrindo na
  // próxima abertura é o desfecho que estas linhas existem para impedir.
  try { await AVDB.updateState(OTA_INTENCAO, () => null); } catch (_) { /* banco */ }
  if (erro) {
    falarNoOta('Não deu para atualizar: ' + erro, 6000);
    if (appDialogResolve) closeAppDialog(true);
    await appConfirm({
      title: 'A atualização do app falhou',
      message: erro + '\n\nDá para tentar de novo pelo botão de atualização, em Configurações.',
      okText: 'Entendi',
      cancelText: null,
    });
    return;
  }
  if (appDialogResolve) closeAppDialog(true);
  falarNoOta('Confirme a instalação na tela do sistema', 8000);
}

// O PROGRESSO VEM POR EMPURRÃO do shell — o download roda na fila de IO dele e
// daqui não há o que perguntar. Ele pinta os dois lugares que podem estar à
// vista: o diálogo (se não foi ocultado) e a linha de Configurações.
window.__avApk = (pct) => {
  if (!apkBaixando) return;
  const n = pct | 0;
  if (appDialogResolve && appDialogMsgEl && !appDialogMsgEl.hidden) {
    appDialogMsgEl.textContent = 'Baixando… ' + n + '%\n\nOcultar não cancela o '
      + 'download: o instalador do Android abre sozinho quando ele terminar.';
  }
  // Pelo `falarNoOta`, e não escrevendo direto: é ele que segura o render de
  // rotina (a cada dez segundos) para não apagar o progresso no meio.
  falarNoOta('Baixando o app v' + (apkNovo ? apkNovo.versao : '') + '… ' + n + '%', 0);
};

// ===== A INTENÇÃO, relida na abertura =====
//
// É a outra metade do `aplicarAtualizacao`: ela grava, esta lê. Sem ela o
// operador aceitaria um lote com APK, veria a base trocar e o app voltaria sem
// nunca mencionar a segunda metade — o pior desfecho possível, porque tudo
// PARECE ter funcionado.
async function retomarAtualizacao() {
  if (!window.__NATIVE__) return;
  let i = null;
  try { i = await AVDB.getState(OTA_INTENCAO); } catch (_) { return; }
  if (!i || !i.shell) return;
  if (!i.em || Date.now() - i.em > OTA_INTENCAO_MAX_MS) {
    try { await AVDB.updateState(OTA_INTENCAO, () => null); } catch (_) { /* banco */ }
    return;
  }
  // O APK JÁ PODE TER SIDO INSTALADO. `__SHELL_NAME__` é o `versionName` do
  // aparelho: alcançada a versão da intenção, ela cumpriu seu papel e o que
  // sobra é apagá-la. Sem esta comparação, o instalador reabriria a cada
  // abertura oferecendo a versão que já está rodando.
  const atual = String(window.__SHELL_NAME__ || '0');
  if (compararVersoes(atual, String(i.shell)) >= 0) {
    try { await AVDB.updateState(OTA_INTENCAO, () => null); } catch (_) { /* banco */ }
    return;
  }
  // Esperar a hora boa vale aqui também, e mais que na pergunta: instalar
  // derruba o app inteiro. A intenção não se perde — ela vive no banco, e esta
  // função é chamada de novo pela enquete.
  if (horaRuimParaAtualizar()) return;
  // O SHELL PRECISA SABER DE QUE APK SE FALA. A intenção sobrevive ao processo;
  // o achado do `ShellUpdater` é estado de PROCESSO e nasce vazio a cada
  // abertura — numa abertura sem rede o `apkInstalar` responderia "nao ha
  // versao nova para baixar", e o `instalarApk` apagaria a intenção e abriria
  // um modal de falha por uma pergunta que ninguém ainda pôde responder.
  // A pergunta é ESTRUTURAL (`apkNovo`, o mesmo campo `shell` do
  // `atualizacaoEstado`) e não casada por texto de erro: a frase do shell não é
  // contrato. Sem achado, a intenção fica onde está e a enquete volta aqui
  // assim que o manifesto chegar.
  if (!apkNovo) await lerAtualizacao();   // na abertura ninguém leu o estado ainda
  if (!apkNovo) return;
  await instalarApk(String(i.shell));
}

// Comparação NUMÉRICA por componente, a mesma regra do `WebUpdater` do shell:
// "1.9" é MAIOR que "1.76" como texto e MENOR como versão, e é justamente essa
// a faixa em que este app vive.
function compararVersoes(a, b) {
  const pa = String(a).replace(/^v/i, '').split('.');
  const pb = String(b).replace(/^v/i, '').split('.');
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const x = parseInt(pa[i], 10) || 0;
    const y = parseInt(pb[i], 10) || 0;
    if (x !== y) return x > y ? 1 : -1;
  }
  return 0;
}

// Quantos restos a última faxina removeu — o Registro mostra, porque uma
// limpeza silenciosa que apaga mídia é exatamente o tipo de coisa que precisa
// deixar rastro.
let restosVarridos = null;
async function varrerRestos() {
  try {
    const n = await AVDB.gcOrfaos();
    restosVarridos = n;
    if (n) console.info('[limpeza] ' + n + ' registro(s) sem dono removido(s)');
  } catch (e) {
    restosVarridos = null;
    console.warn('[limpeza] falhou:', e);
  }
}


// ===== TELÃO POR COMANDOS (E4/E5 — docs/TELAO-POR-COMANDOS.md) =====
//
// O Controle é o único lado que tem o acervo (OPFS) E a ponte — então é ele
// que: (a) ENRIQUECE todo `load` com o registro saneado (`__rec`) que uma tela
// sem IndexedDB precisa para renderizar; (b) EMPURRA os bytes da mídia ao
// cache do shell pelo canal `__avTelaMidia`, de onde a rota `/m/` serve com
// Range; (c) ELEGE a tela de referência entre N `tela-status` (declarada
// acima, usada no handler de status).
//
// Nada disto roda no navegador (`__NATIVE__`) nem com a transmissão desligada
// — e a detecção do canal é por PRESENÇA (`window.__avTelaMidia`), nunca por
// versão de shell: o objeto só existe onde o Kotlin o instalou, que é a mesma
// pergunta que `__AVBridge` sempre respondeu.

let telaRefId = '';
let telaRefEm = 0;
const TELA_REF_SILENCIO_MS = 5000;

const telaTokens = new Map();      // id do acervo → token de serviço (/m/<t>)
// `telaTokens` FICA: o token tem de ser estável por id — é a URL que as telas já
// usam, e é a regra "mesmo id + mesmo token = mesmo item" do shell. Quem responde
// "já tenho isto?" é o `abrir` do shell, no campo `completo`, e ele sempre
// respondeu: um conjunto local de "já empurrei" seria uma SEGUNDA fonte de
// verdade sobre estado que mora do outro lado da ponte, e o cache do shell é DA
// SESSÃO.
const telaFila = [];               // empurrões esperando (um por vez)
let telaEmpurrando = null;         // o ITEM em curso (carrega o token carimbado)
let telaResposta = null;           // { tipo, resolve } do pedido pendente

function telaCanal() { return (window.__NATIVE__ && window.__avTelaMidia) || null; }
function telaAtiva() { return !!telaCanal() && espelhoLigado(); }

// O token é cunhado AQUI (contexto seguro → randomUUID de verdade) porque o
// `__rec` é montado de forma síncrona na emissão do load — uma ida ao Kotlin
// atrasaria todo load do culto. O shell só valida a forma.
function telaTokenDe(id) {
  let t = telaTokens.get(id);
  if (!t) {
    t = (crypto.randomUUID ? crypto.randomUUID().replace(/-/g, '') : null);
    if (!t) return null; // sem randomUUID não há token forte — sem mídia na rede
    telaTokens.set(id, t);
  }
  return t;
}

// O registro SANEADO: toda referência local vira URL servível; `blob`,
// `opfsPath`, `stream` e `youtubeId` NUNCA atravessam (spec §5.5).
//
// AS IMAGENS DE FUNDO DOS SLIDES VÃO JUNTO desde a v5.188 — cada estrofe com
// `imageOpfsPath` ganha um `imageUrl` `/m/`, e os bytes são enfileirados pelo
// `telaEmpurrarImagensLetra` DEPOIS da mídia principal (o som não espera as
// fotos). O texto deste comentário ainda descrevia a exclusão da v1 ("a letra
// vai SEM as imagens de fundo"), que foi justamente o relato do operador
// naquela versão e foi fechado nela: um registro que descreve a limitação
// depois de ela ter caído manda o próximo leitor procurar o defeito no lugar
// errado — foi o que aconteceu ao auditar a herança de preferências.
function telaSanearRec(it, token) {
  const rec = {
    id: it.id,
    kind: it.kind || '',
    name: it.name || '',
    type: it.type || '',
    url: '/m/' + token,
    seconds: it.seconds || 0,
    height: it.height || 0,
  };
  // A APRESENTAÇÃO É O ÚNICO KIND CUJO CONTEÚDO É UMA LISTA, e por isso o
  // saneamento dela não cabe no `url` acima: cada página é um arquivo próprio,
  // e o que viaja é uma `/m/` POR PÁGINA. O `stage.js` aceita string ou Blob em
  // `pages` — é o mesmo par `rec.url` × `rec.blob` da mídia principal, aplicado
  // à lista. O `url` de cima continua sendo cunhado e NUNCA recebe bytes: o
  // ramo do deck vence antes dele no `stage.js`, e gastar um `if` para não
  // cunhar um token que ninguém busca custaria mais do que paga.
  const pgs = telaDeckUrls(it);
  if (pgs) rec.pages = pgs;
  if (it.hymnName) rec.hymnName = it.hymnName;
  if (it.hymnTrack) rec.hymnTrack = it.hymnTrack;
  if (it.hymnAlbum) rec.hymnAlbum = it.hymnAlbum;
  if (Array.isArray(it.lyrics) && it.lyrics.length) {
    rec.lyrics = it.lyrics.map((sl) => ({
      time: sl.time, text: sl.text, auxText: sl.auxText,
      cover: !!sl.cover, imagePosition: sl.imagePosition,
      // A IMAGEM DE FUNDO da estrofe (v5.188): `imageOpfsPath` continua NUNCA
      // viajando (é caminho de OPFS, que só existe no celular) — o que viaja é
      // uma URL /m/ por imagem DISTINTA, com id estável ('ly:'+caminho): a
      // regra "mesmo id + mesmo token = já tenho" do shell faz o segundo load
      // do mesmo hino custar zero empurrão. Quem enfileira os bytes é o
      // chamador (telaEnriquecer), DEPOIS da mídia principal — o som não pode
      // esperar as fotos.
      imageUrl: sl.imageOpfsPath ? telaImagemLetraUrl(sl.imageOpfsPath) : undefined,
    }));
  }
  return rec;
}

// O MANIFESTO REESCRITO PARA A REDE (v5.189).
//
// As URLs que o shell entrega apontam para `/stream/<token>` no origin do
// WebView (`https://appassets.androidplatform.net/…`), e uma tela da rede não
// tem WebView nenhum no caminho: para ela a mesma faixa é servida pelo
// `EspelhoServidor` em `/s/<token>`, RELATIVA — o host é o próprio celular, de
// onde a página veio. O token é o MESMO dos dois lados (o registro do
// `StreamProxy` é um só), então não há segunda extração nem segundo cache.
//
// Devolve `null` quando não há faixa reescrevível: aí a cena vira o aviso de
// sempre, em vez de uma tela preta com um `<video>` que não busca nada.
function telaManifestoDaRede(man) {
  if (!man) return null;
  const refazer = (faixa) => {
    if (!faixa || !faixa.url) return null;
    const i = String(faixa.url).indexOf('/stream/');
    if (i < 0) return null;
    return Object.assign({}, faixa, { url: '/s/' + String(faixa.url).slice(i + 8) });
  };
  const video = refazer(man.video);
  const audio = refazer(man.audio);
  // O áudio é o que não pode faltar: um manifesto sem ele não toca em lugar
  // nenhum, e a tela sem som é justamente o que a rede existe para evitar.
  if (!audio) return null;
  // ===== A ESCADA TAMBÉM (shell 60), e ELA NÃO PODE PASSAR INTACTA =====
  //
  // `Object.assign` carrega `videos` adiante sem tocar nele, e as URLs de lá
  // apontam para `appassets.androidplatform.net` — um host que o navegador da
  // rede NÃO alcança. A tela mediria a banda, decidiria descer um degrau, e o
  // fetch do init novo falharia quatro vezes até `morrer()`: a transmissão
  // MORRE por causa de uma otimização, e só nas telas.
  //
  // O que não se deixa reescrever SAI da escada — uma escada com um degrau
  // quebrado é pior que escada nenhuma, porque a regra escolheria justamente
  // ele numa rede ruim. Sobrando menos de dois, ela some inteira e a tela volta
  // ao comportamento de antes: uma faixa só, sem medição.
  const escada = Array.isArray(man.videos)
    ? man.videos.map(refazer).filter(Boolean)
    : null;
  return Object.assign({}, man, {
    video: video,
    audio: audio,
    videos: (escada && escada.length > 1) ? escada : undefined,
  });
}

// Token estável por imagem de letra; devolve a URL /m/ dela (ou undefined).
function telaImagemLetraUrl(opfsPath) {
  const token = telaTokenDe('ly:' + opfsPath);
  return token ? '/m/' + token : undefined;
}

// AS URLs DAS PÁGINAS de uma apresentação, ou `null`.
//
// `null` é o veredito de "esta apresentação NÃO vai para a rede", e ele tem
// duas causas: não é um deck, ou o aparelho não tem `crypto.randomUUID` e
// nenhum token forte pôde ser cunhado (`telaTokenDe`). Devolver uma lista com
// buracos seria pior que devolver nada — o `stage.js` acharia `pages` e
// projetaria uma página em branco no lugar do slide.
//
// Id estável por página ('dk:<item>:<i>', irmão do 'ly:<caminho>'): a regra
// "mesmo id + mesmo token = já tenho" do shell faz o segundo `load` da mesma
// apresentação custar ZERO empurrão — que é o caso normal de um sermão, em que
// o operador volta um slide.
function telaDeckUrls(it) {
  if (!it || it.kind !== 'deck' || !Array.isArray(it.pages) || !it.pages.length) return null;
  const urls = [];
  for (let i = 0; i < it.pages.length; i++) {
    const t = telaTokenDe(telaDeckPaginaId(it.id, i));
    if (!t) return null;
    urls.push('/m/' + t);
  }
  return urls;
}
function telaDeckPaginaId(id, i) { return 'dk:' + id + ':' + i; }

// Enfileira o empurrão das páginas de uma apresentação.
//
// EM ORDEM, e a ordem é o recurso: a fila do empurrão é serializada, então a
// página 1 chega primeiro — que é a que a tela vai buscar assim que o `load`
// pousar. As seguintes escoam enquanto o pregador fala em cima da primeira.
function telaEmpurrarPaginasDeck(it) {
  if (!Array.isArray(it.pages)) return;
  for (let i = 0; i < it.pages.length; i++) {
    const b = it.pages[i];
    if (!b) continue;
    telaGarantirEnvio({
      id: telaDeckPaginaId(it.id, i),
      name: (it.name || 'Apresentação') + ' · ' + (i + 1),
      type: b.type || 'image/jpeg',
      blob: b,
    });
  }
}

// Enfileira o empurrão das imagens de fundo de um registro já saneado.
function telaEmpurrarImagensLetra(it) {
  if (!Array.isArray(it.lyrics)) return;
  const vistos = new Set();
  for (const sl of it.lyrics) {
    const p = sl.imageOpfsPath;
    if (!p || vistos.has(p)) continue;
    vistos.add(p);
    telaGarantirEnvio({ id: 'ly:' + p, name: 'letra', type: 'image/jpeg', opfsPath: p });
  }
}

// ---- o canal: pedido/resposta serializado (o empurrão é UM por vez) ----
function telaOuvirCanal(c) {
  if (c.__avOuvindo) return;
  c.__avOuvindo = true;
  c.onmessage = (ev) => {
    let r = null;
    try { r = JSON.parse(String((ev && ev.data) || '')); } catch (_) { return; }
    const p = telaResposta;
    if (!p) return;
    if (!telaRespostaCombina(p.tipo, r)) return;   // é do pedido que venceu
    telaResposta = null;
    p.resolve(r);
  };
}
// A RESPOSTA ATRASADA DE UM PEDIDO VENCIDO NÃO PODE RESOLVER O SEGUINTE. O
// prazo de 15 s solta a promessa, mas não cancela a resposta: ela chega depois,
// encontra o pedido SEGUINTE pendente e o resolve com dados que não são dele —
// o item é abandonado calado. Sem número de série vindo do shell
// (`EspelhoMidiaCanal.responder` não ecoa nada do pedido), o que dá para
// conferir daqui é a FORMA: cada tipo de pedido tem uma resposta reconhecível,
// e uma que não combine com o pendente só pode ser do vencido. Descartá-la
// deixa a verdadeira — que vem logo atrás — resolver o pedido certo.
//
// COBERTURA PARCIAL, e é preciso dizer: dois pedidos do MESMO tipo em sequência
// (um `abrir` vencido seguido de outro `abrir`) têm respostas indistinguíveis.
// Fechar isso é o `seq` do lado Kotlin — ver o achado 9.
function telaRespostaCombina(tipo, r) {
  if (!r || typeof r !== 'object') return false;
  if (typeof r.r === 'number') return tipo === 'bloco';
  if ('recebido' in r || 'completo' in r) return tipo === 'abrir';
  if (r.erro === 'fila cheia') return tipo === 'bloco';
  if (r.erro === 'abrir recusado') return tipo === 'abrir';
  // `{ok:true}` puro (fim/cancelar) e "transmissao desligada" servem a
  // qualquer pedido: não há o que conferir, e recusá-los travaria o empurrão.
  return true;
}
function telaPedir(c, msg, tipo) {
  return new Promise((resolve) => {
    const p = { tipo, resolve };
    telaResposta = p;
    setTimeout(() => {
      if (telaResposta === p) { telaResposta = null; resolve(null); }
    }, 15000);
    try { c.postMessage(msg); } catch (_) {
      if (telaResposta === p) { telaResposta = null; resolve(null); }
    }
  });
}

async function telaEmpurrarAgora(it) {
  const c = telaCanal();
  if (!c) return;
  telaOuvirCanal(c);
  // O TOKEN VEM DO ITEM ENFILEIRADO, nunca relido agora: entre a fila e este
  // ponto o `__wp` pode ter sido recunhado (ver `telaGarantirEnvio`), e reler
  // mandaria os bytes do wallpaper ANTIGO sob o token do NOVO.
  const token = it.token || telaTokenDe(it.id);
  if (!token) return;
  let arquivo = it.blob || null;
  if (!arquivo && it.opfsPath) {
    try { arquivo = await AVDB.opfsGetFile(it.opfsPath); } catch (_) { return; }
  }
  if (!arquivo) return;
  const abriu = await telaPedir(c, JSON.stringify({
    abrir: { token, id: it.id, nome: it.name || '', tipo: arquivo.type || it.type || '', tamanho: arquivo.size },
  }), 'abrir');
  if (!abriu || abriu.ok !== true) return;
  // O SHELL É QUEM SABE: `completo` é a resposta a "já tenho isto?", e ela vale
  // para esta sessão de transmissão — que é o escopo do cache lá.
  if (abriu.completo) return;
  // A RETOMADA vem do outro lado: `recebido` diz de onde continuar — um
  // empurrão interrompido (renderer morto no meio) nunca recomeça do zero.
  let pos = abriu.recebido || 0;
  const PASSO = 512 * 1024;
  while (pos < arquivo.size) {
    if (!telaAtiva()) { await telaPedir(c, JSON.stringify({ cancelar: true }), 'cancelar'); return; }
    const fatia = await arquivo.slice(pos, Math.min(pos + PASSO, arquivo.size)).arrayBuffer();
    const r = await telaPedir(c, fatia, 'bloco');
    if (!r) return;                                   // prazo: o próximo load retoma
    if (r.erro === 'fila cheia') {                    // o disco engasgou: mesmo bloco de novo
      await new Promise((x) => setTimeout(x, 200));
      continue;
    }
    if (typeof r.r !== 'number' || r.r < 0) return;
    pos = r.r;
  }
  await telaPedir(c, JSON.stringify({ fim: true }), 'fim');
}

function telaGarantirEnvio(it) {
  if (!it || !it.id) return;
  // O TOKEN É CARIMBADO AGORA, no item que entra na fila. O `__wp` é o único id
  // MUTÁVEL do acervo — cada troca de wallpaper descarta o token e cunha outro.
  const token = telaTokenDe(it.id);
  const mesmo = (x) => x.id === it.id && x.token === token;
  // A DEDUPLICAÇÃO QUE FICA é só a da fila em curso — dois `load` do mesmo item
  // em sequência não podem virar dois empurrões concorrentes. "Já está no cache
  // do shell" não é pergunta desta função: quem a responde é o `abrir`.
  //
  // POR id + TOKEN, e não só por id: trocar o wallpaper duas vezes seguidas
  // enfileirava um empurrão que a deduplicação por id descartava, e o comando
  // saía anunciando um `/m/<token>` que nunca receberia bytes — o wallpaper
  // sumia da tela e a rota respondia 404, para sempre.
  if ((telaEmpurrando && mesmo(telaEmpurrando)) || telaFila.some(mesmo)) return;
  telaFila.push(Object.assign({}, it, { token }));
  telaEscoar();
}
async function telaEscoar() {
  if (telaEmpurrando) return;
  const it = telaFila.shift();
  if (!it) return;
  telaEmpurrando = it;
  try { await telaEmpurrarAgora(it); } catch (e) { console.warn('[tela] empurrão falhou:', e); }
  telaEmpurrando = null;
  telaEscoar();
}

// ---- o enriquecimento, no funil que vê TODO envio deste documento ----
// O REGISTRO PELAS LISTAS JÁ CARREGADAS, e nunca pelo IDB: o `telaEnriquecer`
// roda DENTRO do caminho síncrono do `cmd()`, e um `await` aqui deixaria o
// comando sair sem `__rec` — a tela receberia um cartão sem imagem e o
// enriquecimento chegaria tarde, para um comando que já partiu.
function await0Rec(id) {
  if (!id) return null;
  if (currentItem && currentItem.id === id) return currentItem;
  // A SESSÃO ANTES DAS LISTAS: a imagem sobreposta quase sempre vem de
  // `libItems`, que a troca de aba zera — e é justamente numa reconexão (a tela
  // que deu F5) que este registro é pedido de novo, horas depois do toque.
  if (visualSession && visualSession.id === id && visualSession.rec) return visualSession.rec;
  return [...plItems, ...libItems, ...favItems].find((m) => m.id === id) || null;
}

function telaEnriquecer(cmd) {
  if (!cmd || !telaAtiva()) return;
  if (cmd.type === 'load') {
    const it = (currentItem && currentItem.id === cmd.mediaId) ? currentItem : null;
    if (!it) return;
    // A TRANSMISSÃO DIRETA VAI PARA A REDE desde a v5.189 (a dívida §7): o
    // shell passou a servir as mesmas faixas em `/s/<token>`, então o que a
    // tela precisa é do manifesto com as URLs REESCRITAS — as originais
    // apontam para `/stream/` no origin do WebView, que não existe lá.
    if (it.stream) {
      const man = telaManifestoDaRede(it.stream);
      if (man) {
        cmd.__rec = Object.assign(telaSanearRec(it, telaTokenDe(it.id) || ''), {
          // Sem `url`: quem toca é o MediaSource, pelo manifesto. Deixar a
          // `/m/<token>` de um item que ninguém empurrou faria a tela buscar
          // um 404 antes de tentar o stream.
          url: '',
          stream: man,
        });
        return;
      }
      // Manifesto sem faixa servível: cai no aviso, como as outras.
    }
    // As cenas que NÃO vão para a rede (spec §5.6): o embed é iframe de
    // terceiro (e a CSP das telas o barra por construção); o deck
    // são Blobs por página (E4.1). O aviso sai LOGO DEPOIS do load — a tela
    // sem __rec limpa a cena sozinha (getMedia nulo → clear).
    // O DECK SAIU DAQUI (a dívida E4.1): as páginas viajam como uma `/m/` cada
    // (ver `telaDeckUrls`). Continua caindo no aviso o deck de que não se
    // consegue cunhar token — e o embed, que é iframe de terceiro e a CSP das
    // telas barra por construção.
    if (it.kind === 'youtube' || (it.kind === 'deck' && !telaDeckUrls(it))) {
      setTimeout(() => {
        try { AVDB.sendCommand({ type: 'tela-aviso', texto: 'Esta cena não aparece nas telas da rede.' }); } catch (_) { /* nada */ }
      }, 0);
      return;
    }
    const token = telaTokenDe(it.id);
    if (!token) return;
    cmd.__rec = telaSanearRec(it, token);
    // A APRESENTAÇÃO não tem arquivo único a empurrar — tem uma lista. O
    // `telaGarantirEnvio(it)` dela sairia sem `blob` nem `opfsPath` e morreria
    // calado dentro do `telaEmpurrarAgora`, gastando um giro da fila.
    if (it.kind === 'deck') telaEmpurrarPaginasDeck(it);
    else telaGarantirEnvio(it);
    telaEmpurrarImagensLetra(it);
  } else if (cmd.type === 'text' && cmd.mode === 'image') {
    // A IMAGEM SOBRE O ÁUDIO (v5.312) precisa do MESMO enriquecimento do
    // `load`, e é o único comando de TEXTO que precisa: os outros quatro modos
    // levam o conteúdo dentro do próprio comando, e este leva um `mediaId` —
    // que na tela da rede não resolve nada (ela não tem o acervo no IndexedDB).
    // Sem isto, o cartão entraria PRETO nas telas, escondendo a cena por baixo
    // sem pôr nada no lugar, e o `display.js` de lá não teria como saber.
    const it = await0Rec(cmd.mediaId);
    if (!it) return;
    const token = telaTokenDe(it.id);
    if (!token) return;
    cmd.__rec = telaSanearRec(it, token);
    // A APRESENTAÇÃO SOBREPOSTA empurra as PÁGINAS, não o item (v1.4.28) — o
    // mesmo par que o ramo do `load` já faz, e pela mesma razão: um deck não
    // tem arquivo único, e o `telaGarantirEnvio` dele sairia sem `blob` nem
    // `opfsPath` e morreria calado dentro do `telaEmpurrarAgora`, gastando um
    // giro da fila. Sem token para todas as páginas o `telaSanearRec` não põe
    // `pages`, e o cartão cai no `url` — que aqui nunca recebe bytes: seria um
    // retângulo PRETO por cima da projeção, que é o desfecho que este ramo
    // inteiro existe para impedir.
    if (isDeck(it)) {
      if (!telaDeckUrls(it)) {
        setTimeout(() => {
          try { AVDB.sendCommand({ type: 'tela-aviso', texto: 'Esta cena não aparece nas telas da rede.' }); } catch (_) { /* nada */ }
        }, 0);
        return;
      }
      telaEmpurrarPaginasDeck(it);
    } else telaGarantirEnvio(it);
  } else if (cmd.type === 'wallpaper') {
    // Um comando que JÁ CHEGA com `__wp` é a segunda etapa (abaixo) ou o
    // reenvio de conexão (`telaReenviarPreferencias`): o token dele já está
    // resolvido e re-cunhar aqui mataria a URL que as telas estão usando.
    if (cmd.__wp) return;
    // O aviso de troca segue na hora para o telão de verdade (que lê o IDB
    // sozinho); a parte das TELAS é resolvida em segundo tempo, porque só o
    // blob diz se a troca foi PARA uma imagem ou PARA o padrão — e anexar
    // `__wp` antes de saber cunhava uma URL sem bytes no caminho do "Padrão"
    // (v5.188). O wallpaper é o id MUTÁVEL: cada troca com imagem cunha token
    // novo (o shell substitui e mata o velho).
    (async () => {
      let blob = null;
      try { blob = await AVDB.getState('wallpaper'); } catch (_) { /* padrão */ }
      if (!blob) { AVDB.sendCommand({ type: 'wallpaper', __wp: 'padrao' }); return; }
      // O ÚNICO id MUTÁVEL do acervo: a mesma chave passa a apontar para outros
      // bytes. Descartar o token força a cunhagem de um novo, e o `abrir` com
      // token novo SUBSTITUI o item no shell (matando a URL antiga, que é o que
      // impede uma tela de continuar buscando o wallpaper que saiu de cena).
      telaTokens.delete('__wp');
      const token = telaTokenDe('__wp');
      if (!token) return;
      telaGarantirEnvio({ id: '__wp', name: 'wallpaper', type: blob.type || 'image/jpeg', blob });
      AVDB.sendCommand({ type: 'wallpaper', __wp: '/m/' + token });
    })();
  }
}

// AS PREFERÊNCIAS DE QUEM ACABOU DE CONECTAR (v5.188). O telão de verdade lê
// wallpaper, fundo da letra e preenchimento do IndexedDB no arranque; uma TELA
// DA REDE não tem esse IDB, e tudo que só viaja "na troca" simplesmente não
// existia para quem entrasse depois — ela ficava no wallpaper padrão, com a
// letra sobre preto e no preenchimento default para sempre. Este é o simétrico
// do `resendSceneToDisplay`: roda no MESMO `display-ready`, e é ENDEREÇADO
// (`__para`) para o telão de verdade e as outras telas nem o verem.
// O token do wallpaper é REUSADO quando já existe (o funil acima não re-cunha
// um comando que chega com `__wp`), então N conexões custam UM empurrão — a
// regra "mesmo id + mesmo token = já tenho" do shell responde as demais.
function telaReenviarPreferencias(para) {
  // A GUARDA NÃO PODE SER `telaAtiva()` (v5.208).
  //
  // `telaAtiva()` pergunta a um CACHE COM ENQUETE (`mirrorEstado`, relido de
  // 2,5 em 2,5 s só quando a folha de conexão está à vista) se a transmissão
  // está ligada. Mas quem chega aqui é um `display-ready` que veio PELO SSE de
  // uma tela da rede: se ele chegou, o servidor está no ar e a tela está
  // conectada — a pergunta já está respondida pelo próprio fato de a mensagem
  // existir. Consultar o cache só pode produzir FALSO NEGATIVO, e o preço dele
  // é a tela ficar para sempre sem wallpaper, sem fundo de letra e sem
  // preenchimento, sem nada que o explique.
  //
  const mandar = (c) => { if (para) c.__para = para; AVDB.sendCommand(c); };
  // ===== DUAS DAS TRÊS PREFERÊNCIAS NÃO DEPENDEM DO CANAL DE MÍDIA =====
  //
  // `lyricsbg` e `fit` são JSON puro: viajam pelo MESMO SSE de todo comando do
  // culto e não movem um byte. Só o WALLPAPER precisa do canal, porque só ele
  // empurra uma imagem. A guarda `if (!telaCanal()) return` estava no TOPO da
  // função e derrubava as três — e o preço é o defeito que este reenvio existe
  // para fechar: a tela não tem o IndexedDB do app para consultar, ao contrário
  // do telão de verdade, então sem o comando ela fica no valor com que NASCEU,
  // para sempre — nada reexamina uma estrofe já renderizada.
  //
  // Calado nos dois sentidos: sem o canal não há erro, não há linha no Registro,
  // e o padrão do `fit` e do wallpaper é aceitável o bastante para ninguém
  // reparar. Só o fundo da letra aparece — e aparece como "o app perdeu a
  // configuração".
  //
  // A guarda desceu para o único bloco que de fato depende dela.
  //
  // E o `lyricsbg` vai SEM CONDIÇÃO. Enquanto o padrão era 'black' um
  // `if (=== 'image')` acertava por coincidência — o caso omitido era igual ao
  // nascimento da tela. Com as imagens como padrão a coincidência se inverte, e
  // a condição passaria a calar justamente o "Remover": a tela com imagens e o
  // telão sem, na mesma cena. Mandar sempre custa um objeto JSON e não depende
  // do valor com que a tela nasce.
  mandar({ type: 'lyricsbg', mode: lyricsBg });
  if (mediaFit !== 'contain') mandar({ type: 'fit', fit: mediaFit });
  if (!telaCanal()) return;
  (async () => {
    let blob = null;
    try { blob = await AVDB.getState('wallpaper'); } catch (_) { /* padrão */ }
    if (!blob) return;                       // sem wallpaper próprio: o padrão da tela já é o certo
    const token = telaTokenDe('__wp');
    if (!token) return;
    telaGarantirEnvio({ id: '__wp', name: 'wallpaper', type: blob.type || 'image/jpeg', blob });
    mandar({ type: 'wallpaper', __wp: '/m/' + token });
  })();
}
(function () {
  if (!window.__NATIVE__) return;
  const enviar0 = AVDB.sendCommand;
  AVDB.sendCommand = function (cmd) {
    try { telaEnriquecer(cmd); } catch (e) { console.warn('[tela] enriquecer falhou:', e); }
    return enviar0(cmd);
  };
})();
